msg() { printf '%s\n' "$*"; }

# Activity indicator for long leaf commands (downloads, image pulls):
# ASCII spinner + label + elapsed seconds on stderr while the command
# runs; the command's exit code is returned unchanged. When stderr is
# not a TTY only a plain label line is printed. Wrap leaf commands only
# (never interactive ones, never functions that rely on die/exit).
abox_run_wait() {
    local _label="$1"; shift
    if [[ ! -t 2 ]]; then
        msg "  [*] ${_label} ..."
        "$@"
        return $?
    fi
    "$@" &
    local _pid=$! _i=0 _t0=$SECONDS _frames='|/-\\'
    while kill -0 "$_pid" 2>/dev/null; do
        printf '\r  [%s] %s ... %ds ' "${_frames:$((_i % 4)):1}" "$_label" "$((SECONDS - _t0))" >&2
        _i=$((_i + 1)); sleep 0.2
    done
    wait "$_pid"; local _rc=$?
    printf '\r\033[K' >&2
    return "$_rc"
}

# Standalone protocols register their share links here at deploy time so
# menu 12 can reproduce them later (combo links are rebuilt from .env,
# but standalone credentials live only inside the core configs).
# File format: line 1 = display title, lines 2+ = share URIs. Display
# cache only: every failure is swallowed, never fails a deployment.
register_standalone_link() {
    local _key="$1" _title="$2"; shift 2
    local _dir="${ABOX_DIR:-/etc/ddr}/standalone-links.d" _tmp
    mkdir -p "$_dir" 2>/dev/null || return 0
    chmod 700 "$_dir" 2>/dev/null || true
    _tmp=$(mktemp "$_dir/.tmp.XXXXXX" 2>/dev/null) || return 0
    { printf '%s\n' "$_title"; printf '%s\n' "$@"; } > "$_tmp" 2>/dev/null         || { rm -f -- "$_tmp"; return 0; }
    chmod 600 "$_tmp" 2>/dev/null || true
    mv -f -- "$_tmp" "$_dir/${_key}.link" 2>/dev/null || rm -f -- "$_tmp"
    return 0
}

# Derive an X25519 public key (base64url) from a raw private key
# (base64url) through an openssl PKCS#8 wrap; prints nothing on failure.
x25519_pub_from_priv() {
    local _priv="$1" _der _raw _pub
    [[ "$_priv" =~ ^[A-Za-z0-9_-]{43}$ ]] || return 1
    _der=$(mktemp /tmp/A-Box-x25519.XXXXXX) || return 1
    _raw=$(printf '%s' "$_priv" | tr '_-' '/+')
    while (( ${#_raw} % 4 )); do _raw+='='; done
    { printf '\x30\x2e\x02\x01\x00\x30\x05\x06\x03\x2b\x65\x6e\x04\x22\x04\x20'
      printf '%s' "$_raw" | base64 -d 2>/dev/null
    } > "$_der" || { rm -f -- "$_der"; return 1; }
    _pub=$(openssl pkey -inform DER -in "$_der" -pubout -outform DER 2>/dev/null | tail -c 32 | base64 | tr '+/' '-_' | tr -d '=\n')
    rm -f -- "$_der"
    [[ "$_pub" =~ ^[A-Za-z0-9_-]{43}$ ]] || return 1
    printf '%s' "$_pub"
}

# Rebuild missing standalone registry entries from the live core configs
# (nodes deployed before the registry existed). Best-effort: a node with
# any missing field is skipped silently. Argo is registry-only - its
# domains live in cloudflared logs, not in the core config.
rebuild_standalone_links() {
    local _dir="${ABOX_DIR:-/etc/ddr}/standalone-links.d" _ip="${F_IP:-}"
    [[ -n "$_ip" && "$_ip" != 'N/A' ]] || return 0
    local _xc='/usr/local/etc/xray/config.json' _sc='/etc/sing-box/config.json'
    local _port='' _pass='' _sni='' _sid='' _pk='' _pub='' _uuid='' _cc='' _inner='' _user=''
    if [[ -f "$_xc" ]]; then
        if [[ ! -f "$_dir/trojan-xray.link" ]]; then
            _port=''; _pass=''; _pk=''; _sni=''; _sid=''
            read -r _port _pass _pk _sni _sid < <(jq -r 'first(.inbounds[]? | select(.protocol=="trojan")) | [(.port|tostring), (.settings.clients[0].password // ""), (.streamSettings.realitySettings.privateKey // ""), (.streamSettings.realitySettings.serverNames[0] // ""), (.streamSettings.realitySettings.shortIds[0] // "")] | @tsv' "$_xc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_pass" && -n "$_pk" ]]; then
                _pub=$(x25519_pub_from_priv "$_pk") && [[ -n "$_pub" ]] && \
                register_standalone_link trojan-xray "Trojan-Reality (Xray) · 端口 ${_port}" "trojan://$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}?security=reality&sni=${_sni}&fp=chrome&pbk=${_pub}&sid=${_sid}&type=tcp#Trojan-Reality"
            fi
        fi
        if [[ ! -f "$_dir/socks5-xray.link" ]]; then
            _port=''; _user=''; _pass=''
            read -r _port _user _pass < <(jq -r 'first(.inbounds[]? | select(.tag=="socks5-landing")) | [(.port|tostring), (.settings.accounts[0].user // ""), (.settings.accounts[0].pass // "")] | @tsv' "$_xc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_user" ]]; then
                register_standalone_link socks5-xray "SOCKS5 (Xray) · 端口 ${_port}" "socks5://$(urlencode "$_user"):$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}"
            fi
        fi
    fi
    if [[ -f "$_sc" ]]; then
        if [[ ! -f "$_dir/trojan-sb.link" ]]; then
            _port=''; _pass=''; _pk=''; _sni=''; _sid=''
            read -r _port _pass _pk _sni _sid < <(jq -r 'first(.inbounds[]? | select(.tag=="trojan-landing")) | [(.listen_port|tostring), (.password // .users[0].password // ""), (.tls.reality.private_key // ""), (.tls.server_name // ""), (.tls.reality.short_id[0] // "")] | @tsv' "$_sc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_pass" && -n "$_pk" ]]; then
                _pub=$(x25519_pub_from_priv "$_pk") && [[ -n "$_pub" ]] && \
                register_standalone_link trojan-sb "Trojan-Reality (sing-box) · 端口 ${_port}" "trojan://$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}?security=reality&sni=${_sni}&fp=chrome&pbk=${_pub}&sid=${_sid}&type=tcp#Trojan-Reality"
            fi
        fi
        if [[ ! -f "$_dir/tuic.link" ]]; then
            _port=''; _uuid=''; _pass=''; _cc=''; _sni=''
            read -r _port _uuid _pass _cc _sni < <(jq -r 'first(.inbounds[]? | select(.tag=="tuic-in")) | [(.listen_port|tostring), (.users[0].uuid // ""), (.users[0].password // ""), (.congestion_control // "bbr"), (.tls.server_name // "")] | @tsv' "$_sc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_uuid" && -n "$_pass" ]]; then
                register_standalone_link tuic "TUIC · 端口 ${_port}" "tuic://${_uuid}:$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}?congestion_control=${_cc}&alpn=h3&sni=${_sni}&allow_insecure=1#TUIC"
            fi
        fi
        if [[ ! -f "$_dir/anytls.link" ]]; then
            _port=''; _pass=''; _pk=''; _sni=''; _sid=''
            read -r _port _pass _pk _sni _sid < <(jq -r 'first(.inbounds[]? | select(.tag=="anytls-in")) | [(.listen_port|tostring), (.users[0].password // .password // ""), (.tls.reality.private_key // ""), (.tls.server_name // ""), (.tls.reality.short_id[0] // "")] | @tsv' "$_sc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_pass" && -n "$_pk" ]]; then
                _pub=$(x25519_pub_from_priv "$_pk") && [[ -n "$_pub" ]] && \
                register_standalone_link anytls "AnyTLS-Reality · 端口 ${_port}" "anytls://$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}?security=reality&sni=${_sni}&fp=chrome&pbk=${_pub}&sid=${_sid}#AnyTLS-Reality"
            fi
        fi
        if [[ ! -f "$_dir/shadowtls.link" ]]; then
            _port=''; _pass=''; _sni=''; _inner=''
            read -r _port _pass _sni _inner < <(jq -r 'first(.inbounds[]? | select(.tag=="shadowtls-in")) | [(.listen_port|tostring), (.users[0].password // ""), (.handshake.server // "")] | @tsv' "$_sc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_pass" ]]; then
                _inner=$(jq -r 'first(.inbounds[]? | select(.tag=="shadowtls-ss")) | .password // ""' "$_sc" 2>/dev/null)
                if [[ -n "$_inner" ]]; then
                    local _ub _pb
                    _ub=$(printf '%s' "2022-blake3-aes-128-gcm:${_inner}@$(uri_host "$_ip"):${_port}" | base64 | tr -d '\n\r')
                    _pb=$(printf '%s' "{\"version\":\"3\",\"host\":\"${_sni}\",\"password\":\"${_pass}\"}" | base64 | tr -d '\n\r')
                    register_standalone_link shadowtls "ShadowTLS · 端口 ${_port}" "ss://${_ub}?shadow-tls=${_pb}#ShadowTLS"
                fi
            fi
        fi
        if [[ ! -f "$_dir/socks5-sb.link" ]]; then
            _port=''; _user=''; _pass=''
            read -r _port _user _pass < <(jq -r 'first(.inbounds[]? | select(.tag=="socks5-landing")) | [(.listen_port|tostring), (.users[0].username // ""), (.users[0].password // "")] | @tsv' "$_sc" 2>/dev/null)
            if [[ "$_port" =~ ^[0-9]+$ && -n "$_user" ]]; then
                register_standalone_link socks5-sb "SOCKS5 (sing-box) · 端口 ${_port}" "socks5://$(urlencode "$_user"):$(urlencode "$_pass")@$(uri_host "$_ip"):${_port}"
            fi
        fi
    fi
    return 0
}
die() {
    printf '%s\n' "${RED}[!] $*${NC}" >&2
    if [[ -n "${ABOX_DIE_HOOK:-}" ]] && declare -F "$ABOX_DIE_HOOK" >/dev/null 2>&1; then
        if ! "$ABOX_DIE_HOOK" "$*"; then
            printf '%s\n' "${RED}[!] WARNING: rollback hook '$ABOX_DIE_HOOK' failed; manual recovery may be required.${NC}" >&2
        fi
    fi
    exit 1
}
now_iso() { date '+%Y-%m-%dT%H:%M:%S%z'; }


abox_dir_has_legacy_fingerprint() {
    local dir="${1:-$ABOX_DIR}" count=0 only='' entry base
    [[ -d "$dir" && ! -L "$dir" ]] || return 1
    if [[ -f "$dir/A-Box.sh" && ! -L "$dir/A-Box.sh" ]] &&
       grep -q '==============================A-Box===============================' "$dir/A-Box.sh" 2>/dev/null &&
       grep -q '^main "\$@"' "$dir/A-Box.sh" 2>/dev/null; then
        return 0
    fi
    if [[ -f "$dir/.env" && ! -L "$dir/.env" ]]; then
        if ( load_abox_env "$dir/.env" >/dev/null 2>&1 && [[ "${CORE:-}" =~ ^(xray|singbox|hysteria)$ ]] ); then
            return 0
        fi
    fi
    while IFS= read -r -d '' entry; do
        base=${entry##*/}
        [[ "$base" == '.' || "$base" == '..' ]] && continue
        count=$((count + 1))
        only="$base"
        (( count <= 1 )) || return 1
    done < <(
        shopt -s nullglob dotglob
        for entry in "$dir"/*; do
            [[ -e "$entry" || -L "$entry" ]] || continue
            printf '%s\0' "$entry"
        done
    )
    if (( count == 0 )); then
        return 0
    fi
    if (( count == 1 )) && [[ "$only" == '.lang' && -f "$dir/.lang" && ! -L "$dir/.lang" ]]; then
        grep -Eq '^(zh|zh-tw|en|ja|ru|fa)[[:space:]]*$' "$dir/.lang"
        return
    fi
    return 1
}

path_owned_by_root() {
    local path="$1" uid gid
    [[ -e "$path" && ! -L "$path" ]] || return 1
    uid=$(stat -c %u "$path" 2>/dev/null) || return 1
    gid=$(stat -c %g "$path" 2>/dev/null) || return 1
    [[ "$uid" == 0 && "$gid" == 0 ]]
}

path_mode_has_no_group_other_write() {
    local path="$1" mode
    mode=$(stat -c %a "$path" 2>/dev/null) || return 1
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#022) == 0 ))
}

path_is_mountpoint() {
    local path="$1" rc
    [[ -e "$path" || -L "$path" ]] || return 1
    if python3 - "$path" <<'PY_EXACT_MOUNT' >/dev/null 2>&1
import os, re, sys

path = os.path.abspath(os.path.normpath(sys.argv[1]))
if os.path.islink(path):
    raise SystemExit(1)
try:
    with open('/proc/self/mountinfo', 'r', encoding='utf-8', errors='strict') as f:
        for line in f:
            fields = line.rstrip('\n').split(' ')
            if len(fields) < 5:
                continue
            raw = fields[4]
            mp = re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), raw)
            mp = os.path.abspath(os.path.normpath(mp))
            if mp == path:
                raise SystemExit(0)
except (OSError, UnicodeError):
    # mountinfo is the authoritative source for Linux mount topology. If it
    # cannot be read, the caller cannot safely prove that the path is not a
    # mountpoint; fail closed rather than falling back to ismount().
    raise SystemExit(0)
raise SystemExit(1)
PY_EXACT_MOUNT
    then
        rc=0
    else
        rc=$?
    fi
    # Only rc=1 is a definitive "not a mountpoint" result. Any other
    # helper failure is treated as a mountpoint so callers fail closed rather
    # than deleting/restoring through an unknown mount boundary.
    case "$rc" in
        0|1) return "$rc" ;;
        *) return 0 ;;
    esac
}

path_tree_has_nested_mountpoint() {
    local path="${1:-}" rc
    [[ -n "$path" && ( -d "$path" || -f "$path" ) && ! -L "$path" ]] || return 1
    command -v python3 >/dev/null 2>&1 || return 0
    python3 - "$path" <<'PY_TREE_NESTED_MOUNT'
import os, re, sys
def decode_mountinfo_path(value):
    return re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), value)
try:
    target=os.path.realpath(sys.argv[1]).rstrip('/') or '/'
    prefix=target + '/'
    with open('/proc/self/mountinfo','r',encoding='utf-8',errors='strict') as f:
        for raw in f:
            parts=raw.split()
            if len(parts) < 5:
                raise RuntimeError('malformed mountinfo')
            mountpoint=decode_mountinfo_path(parts[4])
            mountpoint=os.path.realpath(mountpoint).rstrip('/') or '/'
            if mountpoint.startswith(prefix):
                raise SystemExit(0)
except SystemExit:
    raise
except Exception:
    raise SystemExit(2)
raise SystemExit(1)
PY_TREE_NESTED_MOUNT
    rc=$?
    case "$rc" in
        0) return 0 ;;
        1) return 1 ;;
        *) return 0 ;;
    esac
}

path_tree_has_mountpoint() {
    local path="$1" rc
    [[ -e "$path" || -L "$path" ]] || return 1
    if python3 - "$path" <<'PY_TREE_MOUNT' >/dev/null 2>&1
import os, sys

# Linux os.path.ismount() can miss bind mounts when the mount and parent
# reside on the same device. /proc/self/mountinfo is authoritative for the
# current mount namespace and also catches nested bind mounts.
root = os.path.abspath(os.path.normpath(sys.argv[1]))
if os.path.islink(root):
    raise SystemExit(1)

import re
def decode_mountinfo_path(value):
    # Decode each kernel mountinfo octal escape exactly once. Sequential
    # replacement can turn a literal backslash sequence into a different
    # escape and corrupt a legitimate path.
    return re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), value)

mountpoints = []
try:
    with open('/proc/self/mountinfo', 'r', encoding='utf-8', errors='strict') as f:
        for line in f:
            fields = line.rstrip('\n').split(' ')
            if len(fields) >= 5:
                mp = os.path.abspath(os.path.normpath(decode_mountinfo_path(fields[4])))
                mountpoints.append(mp)
except (OSError, UnicodeError):
    # mountinfo is the authoritative source for Linux mount topology. If it
    # cannot be read, the caller cannot safely prove that the tree is free of
    # mounts; fail closed rather than using weaker ismount()/os.walk() checks.
    raise SystemExit(0)

if root == '/':
    raise SystemExit(0)
for mp in mountpoints:
    if mp == root or mp.startswith(root + os.sep):
        raise SystemExit(0)
raise SystemExit(1)
PY_TREE_MOUNT
    then
        rc=0
    else
        rc=$?
    fi
    # Only rc=1 is a definitive "not a mountpoint" result. Any other
    # helper failure is treated as a mountpoint so destructive/restore paths
    # fail closed instead of crossing an unknown mount boundary.
    case "$rc" in
        0|1) return "$rc" ;;
        *) return 0 ;;
    esac
}

assert_default_abox_parent_chain_trusted() {
    local dir="$1" parent uid gid mode
    [[ "$dir" == '/etc/ddr' ]] || return 0
    for parent in / /etc; do
        [[ -d "$parent" && ! -L "$parent" ]] || die "$(tprintf pc_untrusted "$parent")"
        uid=$(stat -c %u "$parent" 2>/dev/null) || die "$(tprintf pc_owner_read "$parent")"
        gid=$(stat -c %g "$parent" 2>/dev/null) || die "$(tprintf pc_group_read "$parent")"
        mode=$(stat -c %a "$parent" 2>/dev/null) || die "$(tprintf pc_mode_read "$parent")"
        [[ "$uid" == 0 && "$gid" == 0 ]] || die "$(tprintf pc_not_root "$parent")"
        [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#022) == 0 )) || die "$(tprintf pc_writable "$parent")"
    done
}

ensure_abox_dir_owned() {
    local dir="${1:-$ABOX_DIR}" owner tmp uid gid mode
    owner="$dir/.A-Box-owner"
    assert_default_abox_parent_chain_trusted "$dir"
    [[ ! -L "$dir" ]] || die "$(tprintf do_symlink "$dir")"
    if [[ -e "$dir" && ! -d "$dir" ]]; then
        die "$(tprintf do_notdir "$dir")"
    fi
    if [[ -d "$dir" ]]; then
        path_owned_by_root "$dir" || die "$(tprintf do_not_root "$dir")"
        path_mode_has_no_group_other_write "$dir" || die "$(tprintf do_writable "$dir")"
        if [[ -f "$owner" && ! -L "$owner" ]] && grep -Fxq 'A-Box managed directory v1' "$owner" 2>/dev/null; then
            path_owned_by_root "$owner" || die "$(tprintf do_mark_not_root "$owner")"
            mode=$(stat -c %a "$owner" 2>/dev/null) || die "$(tprintf do_mark_mode_read "$owner")"
            [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#077) == 0 )) || die "$(tprintf do_mark_mode_unsafe "$owner")"
            chmod 700 "$dir" || die "$(tprintf do_tighten_dir "$dir")"
            chmod 600 "$owner" || die "$(tprintf do_tighten_mark "$owner")"
            return 0
        fi
        abox_dir_has_legacy_fingerprint "$dir" || die "$(tprintf do_legacy "$dir")"
    else
        mkdir -p "$dir" || die "$(tprintf do_mkdir "$dir")"
    fi
    chown root:root "$dir" || die "$(tprintf do_chown "$dir")"
    chmod 700 "$dir" || die "$(tprintf do_chmod "$dir")"
    tmp=$(umask 077; mktemp "$dir/.A-Box-owner.XXXXXX") || die "$(tr_msg do_mark_tmp)"
    printf '%s\n' 'A-Box managed directory v1' > "$tmp" || { rm -f "$tmp"; die "$(tr_msg do_mark_write)"; }
    chown root:root "$tmp" || { rm -f "$tmp"; die "$(tr_msg do_mark_chown)"; }
    chmod 600 "$tmp" || { rm -f "$tmp"; die "$(tr_msg do_mark_chmod)"; }
    mv -f "$tmp" "$owner" || { rm -f "$tmp"; die "$(tr_msg do_mark_commit)"; }
    path_owned_by_root "$owner" || die "$(tr_msg do_mark_verify)"
}

normalize_lang() {
    case "${1:-}" in
        en|en_US|en-US|english|English) printf 'en' ;;
        ru|ru_RU|ru-RU|russian|Русский) printf 'ru' ;;
        fa|fa_IR|fa-IR|persian|فارسی) printf 'fa' ;;
        ja|ja_JP|ja-JP|japanese|日本語) printf 'ja' ;;
        zh-tw|zh_TW|zh-TW|tw|TW|繁體中文|繁体中文) printf 'zh-tw' ;;
        zh|zh_CN|zh-CN|cn|CN|中文|'') printf 'zh' ;;
        *) printf 'zh' ;;
    esac
}

