        zh:wl_pu_guide_cf_t) echo '── Wallos 使用教程（CF 隧道）──' ;;
        en:wl_pu_guide_cf_t) echo '-- Wallos quick guide (Cloudflare Tunnel) --' ;;
        ru:wl_pu_guide_cf_t) echo '-- Краткое руководство Wallos (туннель Cloudflare) --' ;;
