tprintf() {
    local key="$1" fmt placeholder_count=0 i=0 len next
    shift
    fmt=$(tr_msg "$key")
    # Translation strings are internal, but validate their printf grammar before
    # passing them to printf. Only %s and %% are supported, with %% treated as
    # a literal percent and never counted as a placeholder.
    [[ "$fmt" != *\\* ]] || die "$(tprintf tp_bad_fmt "$key")"
    len=${#fmt}
    while (( i < len )); do
        if [[ "${fmt:i:1}" == '%' ]]; then
            (( i + 1 < len )) || die "$(tprintf tp_bad_fmt "$key")"
            next=${fmt:i+1:1}
            case "$next" in
                '%') i=$((i + 2)) ;;
                s) placeholder_count=$((placeholder_count + 1)); i=$((i + 2)) ;;
                *) die "$(tprintf tp_bad_fmt "$key")" ;;
            esac
        else
            i=$((i + 1))
        fi
    done
    (( placeholder_count == $# )) || die "$(tprintf tp_arg_mismatch "$key" "$placeholder_count" "$#")"
    printf "$fmt" "$@"
}

proto_label() {
    printf '%b[%s]%b' "${BOLD}${CYAN}" "$1" "${NC}"
}

pause_return() {
    # Piped-menu automation: skip pause when stdin is not a TTY (non-interactive).
    [[ ! -t 0 ]] && return 0
    local released=0
    if [[ -t 0 ]]; then
        # Briefly release exclusive flock during idle prompt so cron helpers can run.
        if [[ "${ABOX_RUNTIME_LOCK_MODE:-}" == flock ]] && [[ -e /proc/$$/fd/9 ]]; then
            flock -u 9 2>/dev/null && released=1 || true
        fi
        read -r -p "$(tr_msg press_return)" _ || true
        if (( released == 1 )); then
            flock -w 15 9 || die "$(tr_msg tp_lock)"
        fi
    fi
}

is_yes() { [[ "${1:-}" =~ ^[Yy]$ ]]; }

confirm_yes_no() {
    local prompt="$1" answer
    read -r -p "$prompt" answer
    is_yes "$answer"
}

detect_lang() {
    if [[ -n "${ABOX_LANG_OVERRIDE:-}" ]]; then
        ABOX_LANG=$(normalize_lang "$ABOX_LANG_OVERRIDE")
    elif [[ -n "${ABOX_LANG:-}" && "${ABOX_LANG:-}" != 'zh' ]]; then
        ABOX_LANG=$(normalize_lang "$ABOX_LANG")
    elif [[ -r "$LANG_FILE" ]]; then
        ABOX_LANG=$(normalize_lang "$(tr -d '[:space:]' < "$LANG_FILE" 2>/dev/null)")
    else
        ABOX_LANG='zh'
    fi
}

save_lang() {
    ensure_abox_dir_owned "$ABOX_DIR"
    write_file_atomically_from_stdin "$LANG_FILE" 600 <<< "${ABOX_LANG:-zh}" || die "$(tr_msg tp_lang_write)"
}

initial_language_select() {
    [[ -f "$LANG_FILE" || -n "${ABOX_LANG_OVERRIDE:-}" ]] && return 0
    local c
    echo 'Language / 语言 / 語言 / 言語 / Язык / زبان'
    echo '1. 简体中文'
    echo '2. 繁體中文'
    echo '3. English'
    echo '4. 日本語'
    echo '5. Русский'
    echo '6. فارسی'
    read -r -p 'Select [1-6, default 1]: ' c || true
    case "$c" in
        2) ABOX_LANG='zh-tw' ;;
        3) ABOX_LANG='en' ;;
        4) ABOX_LANG='ja' ;;
        5) ABOX_LANG='ru' ;;
        6) ABOX_LANG='fa' ;;
        *) ABOX_LANG='zh' ;;
    esac
    save_lang
}
language_menu() {
    # Submenu loop: 0/Enter returns to the parent menu.
    while true; do
    clear
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}$(tr_msg lang_title)${NC}"
    msg "${CYAN}======================================================================${NC}"
    msg "${YELLOW}1. 简体中文${NC}"
    msg "${YELLOW}2. 繁體中文${NC}"
    msg "${YELLOW}3. English${NC}"
    msg "${YELLOW}4. 日本語${NC}"
    msg "${YELLOW}5. Русский${NC}"
    msg "${YELLOW}6. فارسی${NC}"
    msg "${CYAN}0. 返回 / Back${NC}"
    local c
    read -r -p 'Select [0-6]: ' c || return 0
    case "$c" in
        1) ABOX_LANG='zh'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        2) ABOX_LANG='zh-tw'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        3) ABOX_LANG='en'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        4) ABOX_LANG='ja'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        5) ABOX_LANG='ru'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        6) ABOX_LANG='fa'; save_lang; msg "${GREEN}$(tr_msg lang_saved)${NC}"; pause_return ;;
        0) return 0 ;;
        *) msg "${RED}$(tr_msg invalid_input): $c${NC}"; sleep 1 ;;
    esac
    done
}
need_interactive_tty() {
    if [[ ! -t 0 ]]; then
        # Version B: piped-menu automation. Honor non-TTY stdin (pipe/file redirect)
        # for scripted menu runs instead of stealing /dev/tty. The main menu
        # already exits cleanly on EOF (read ... || exit 0), and pause_return()
        # skips when stdin is not a TTY.
        # Default: reattach /dev/tty for interactive safety (prevents curl|bash early exit).
        # Automation: set ABOX_PIPED=1 to explicitly enable piped-menu mode.
        [[ "${ABOX_PIPED:-0}" == 1 ]] && return 0
        if [[ -r /dev/tty ]] && ( : < /dev/tty ) 2>/dev/null; then
            exec < /dev/tty || die "$(tr_msg tp_tty_open)"
        else
            die "$(tr_msg tp_tty_menu)"
        fi
    fi
}
valid_decimal_upto() {
    local input="${1:-}" max="${2:-}" normalized
    [[ "$input" =~ ^[0-9]+$ ]] || return 1
    [[ "$max" =~ ^[1-9][0-9]*$ ]] || return 1
    normalized="${input#"${input%%[!0]*}"}"
    [[ -n "$normalized" ]] || normalized='0'
    (( ${#normalized} < ${#max} )) && return 0
    (( ${#normalized} > ${#max} )) && return 1
    (( 10#$normalized <= 10#$max ))
}

valid_port() {
    local input="${1:-}" normalized
    valid_decimal_upto "$input" 65535 || return 1
    normalized="${input#"${input%%[!0]*}"}"
    [[ -n "$normalized" ]] || return 1
    (( 10#$normalized >= 1 ))
}

valid_canonical_port() {
    local input="${1:-}"
    valid_port "$input" || return 1
    [[ "$input" == "$((10#$input))" ]]
}

valid_canonical_port_range() {
    local input="${1:-}" start end
    if [[ "$input" =~ ^([0-9]+):([0-9]+)$ ]]; then
        start="${BASH_REMATCH[1]}"; end="${BASH_REMATCH[2]}"
    elif [[ "$input" =~ ^([0-9]+)-([0-9]+)$ ]]; then
        start="${BASH_REMATCH[1]}"; end="${BASH_REMATCH[2]}"
    else
        return 1
    fi
    valid_canonical_port "$start" && valid_canonical_port "$end" && (( 10#$start <= 10#$end ))
}

valid_port_range() {
    local input="${1:-}" start end
    if [[ "$input" =~ ^([0-9]+):([0-9]+)$ ]]; then
        start="${BASH_REMATCH[1]}"; end="${BASH_REMATCH[2]}"
    elif [[ "$input" =~ ^([0-9]+)-([0-9]+)$ ]]; then
        start="${BASH_REMATCH[1]}"; end="${BASH_REMATCH[2]}"
    else
        return 1
    fi
    valid_port "$start" && valid_port "$end" && (( 10#$start <= 10#$end ))
}

normalize_port_spec() {
    local input="${1:-}" start end
    if valid_port "$input"; then
        printf '%s\n' "$((10#$input))"
        return 0
    fi
    valid_port_range "$input" || return 1
    if [[ "$input" == *:* ]]; then
        start="${input%%:*}"; end="${input##*:}"
    else
        start="${input%%-*}"; end="${input##*-}"
    fi
    printf '%s:%s\n' "$((10#$start))" "$((10#$end))"
}

valid_port_spec() { normalize_port_spec "${1:-}" >/dev/null 2>&1; }

valid_hy2_uri_ports() {
    local input="${1:-}" part
    [[ "$input" =~ ^[0-9]+(-[0-9]+)?(,[0-9]+(-[0-9]+)?)*$ ]] || return 1
    local IFS=,
    local -a _parts=()
    read -r -a _parts <<< "$input"
    ((${#_parts[@]} > 0)) || return 1
    for part in "${_parts[@]}"; do
        if [[ "$part" == *-* ]]; then
            valid_canonical_port_range "$part" || return 1
        else
            valid_canonical_port "$part" || return 1
        fi
    done
}

valid_hy2_clash_ports() {
    local input="${1:-}"
    [[ "$input" =~ ^[0-9]+(-[0-9]+)?$ ]] || return 1
    if [[ "$input" == *-* ]]; then
        valid_canonical_port_range "$input" || return 1
    else
        valid_canonical_port "$input" || return 1
    fi
}

valid_hy2_sb_ports() {
    local input="${1:-}"
    [[ "$input" =~ ^[0-9]+:[0-9]+$ ]] || return 1
    valid_canonical_port_range "$input" || return 1
}

port_spec_for_firewalld() {
    local spec
    spec=$(normalize_port_spec "${1:-}") || return 1
    printf '%s\n' "${spec/:/-}"
}

port_list_for_firewalld() {
    local input="${1:-}" item normalized result=''
    local -a items=()
    [[ -n "$input" ]] || return 1
    local IFS=,
    read -r -a items <<< "$input"
    (("${#items[@]}" > 0)) || return 1
    for item in "${items[@]}"; do
        normalized=$(port_spec_for_firewalld "$item") || return 1
        result+="${result:+,}${normalized}"
    done
    printf '%s\n' "$result"
}

valid_positive_int() {
    # Keep decimal integers within a range safe for Bash arithmetic on
    # standard 64-bit Linux; callers may still impose a tighter domain limit.
    [[ "${1:-}" =~ ^[1-9][0-9]{0,17}$ ]]
}

valid_traffic_limit_gb() {
    local input="${1:-}"
    [[ "$input" =~ ^[1-9][0-9]{0,9}$ ]] || return 1
    (( 10#$input <= 8589934591 ))
}
valid_backup_retention_count() {
    local input="${1:-}"
    [[ "$input" =~ ^[0-9]{1,4}$ ]] || return 1
    (( 10#$input <= 1000 ))
}
valid_hy2_bandwidth_mbps() {
    # Keep the interactive HY2 bandwidth domain identical to the persisted .env validator.
    valid_traffic_limit_gb "${1:-}"
}

valid_domain() {
    local domain="${1:-}"
    [[ ${#domain} -le 253 ]] || return 1
    [[ "$domain" =~ ^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$ ]]
}

valid_sni() { valid_domain "$1"; }

valid_single_line_secret() {
    local value="${1:-}" max_len="${2:-512}"
    [[ -n "$value" && ${#value} -le $max_len ]] || return 1
    [[ "$value" != *[[:cntrl:]]* ]]
}

# ============ Version C: unified validation framework ============
# valid_uuid: standalone UUIDv4 shape check (was inline at config validation).
valid_uuid() {
    local input="${1:-}"
    [[ "$input" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ ]]
}

# valid_path: must start with /, no whitespace/control/quotes/backslash.
valid_path() {
    local input="${1:-}"
    [[ -n "$input" ]] || return 1
    [[ "$input" == /* ]] || return 1
    case "$input" in
        *[[:space:][:cntrl:]]*|*\"*|*\'*|*\\*) return 1 ;;
    esac
    return 0
}

# port_is_free: true when nothing is listening on the TCP port locally.
port_is_free() {
    local port="${1:-}"
    [[ -n "$port" ]] || return 1
    if command -v ss >/dev/null 2>&1; then
        ! ss -tuln 2>/dev/null | awk 'NR>1 {print $5}' | grep -qE ":${port}$"
    elif command -v netstat >/dev/null 2>&1; then
        ! netstat -tuln 2>/dev/null | awk 'NR>2 {print $4}' | grep -qE ":${port}$"
    else
        ! (exec 3<>/dev/tcp/127.0.0.1/"$port") 2>/dev/null
    fi
}

# is_test: single dispatcher for all input validation types (233boy pattern).
#   port   -> 1-65535 and not occupied
#   domain -> valid_domain regex
#   uuid   -> UUIDv4 shape
#   ip     -> plain IPv4 or IPv6 address (no CIDR)
#   path   -> /-prefixed, no whitespace/control chars
#   cidr   -> IPv4 or IPv6 with optional /mask
is_test() {
    local type="${1:-}" value="${2:-}"
    case "$type" in
        port)   valid_port "$value" && port_is_free "$value" ;;
        domain) valid_domain "$value" ;;
        uuid)   valid_uuid "$value" ;;
        ip)     valid_ip_address "$value" ;;
        path)   valid_path "$value" ;;
        cidr)   valid_ipv4_cidr "$value" || valid_ipv6_cidr "$value" ;;
        *)      return 1 ;;
    esac
}

# prompt_validated: read from stdin, apply default on empty, re-prompt until
# is_test passes. Prints the accepted value to stdout.
prompt_validated() {
    local prompt="$1" type="$2" default="${3:-}"
    local val
    while true; do
        if ! read -r -p "$prompt" val; then
            val="$default"
            if is_test "$type" "$val"; then
                printf '%s' "$val"
                return 0
            fi
            msg "${RED}$(tprintf pv_eof "$type")${NC}" >&2
            return 1
        fi
        val="${val:-$default}"
        if is_test "$type" "$val"; then
            printf '%s' "$val"
            return 0
        fi
        if [[ "$type" == 'port' ]] && valid_port "$val"; then
            msg "${RED}$(tprintf pv_port_busy "$val")${NC}" >&2
        else
            msg "${RED}$(tprintf pv_invalid "$type" "$val")${NC}" >&2
        fi
    done
}
# ============ end Version C ============

is_apple_like_sni() {
    local sni="${1,,}"
    [[ "$sni" == 'apple.com' || "$sni" == *.apple.com || "$sni" == 'icloud.com' || "$sni" == *.icloud.com ]]
}

default_sni_for_port() {
    local selected="${ABOX_AUTO_SNI_SELECTED:-}"
    if valid_sni "$selected"; then
        printf '%s\n' "$selected"
    else
        # An unverified fallback is not a default; interactive setup must ask.
        printf '\n'
    fi
}

sni_probe_candidate_tier() {
    local domain="${1:-}" workdir='' raw='' raw_sorted='' verified='' timeout_s=2
    local score actual_domain app ttfb total_time http code ip tls13 alpn san asn country asnmatch samecountry org cdnpenalty tier
    [[ -n "$domain" ]] || { printf 'N\n'; return 0; }
    command -v curl >/dev/null 2>&1 && command -v openssl >/dev/null 2>&1 || { printf 'N\n'; return 0; }
    workdir=$(mktemp -d /tmp/A-Box-sni-custom.XXXXXX) || { printf 'N\n'; return 0; }
    chmod 700 "$workdir" 2>/dev/null || { rm -rf -- "$workdir"; printf 'N\n'; return 0; }
    raw="$workdir/raw.tsv"
    raw_sorted="$workdir/raw.sorted.tsv"
    verified="$workdir/verified.tsv"
    : > "$raw"
    ABOX_CURL_TLS13_SUPPORTED=0
    ABOX_CURL_HTTP2_SUPPORTED=0
    { curl --help all 2>/dev/null || curl --help 2>/dev/null; } | grep -F -- '--tlsv1.3' >/dev/null && ABOX_CURL_TLS13_SUPPORTED=1
    { curl --help all 2>/dev/null || curl --help 2>/dev/null; } | grep -F -- '--http2' >/dev/null && ABOX_CURL_HTTP2_SUPPORTED=1
    sni_probe_domain "$domain" "$raw" "$timeout_s" >&2 || true
    if [[ ! -s "$raw" ]]; then
        rm -rf -- "$workdir"
        printf 'D\n'
        return 0
    fi
    if ! LC_ALL=C sort -t $'\t' -k1,1n -k2,2 "$raw" > "$raw_sorted"; then
        rm -rf -- "$workdir"
        printf 'N\n'
        return 0
    fi
    if ! sni_verify_raw_report "$raw_sorted" "$verified" 1 3 >&2 || [[ ! -s "$verified" ]]; then
        rm -rf -- "$workdir"
        printf 'N\n'
        return 0
    fi
    IFS=$'\t' read -r score actual_domain app ttfb total_time http code ip tls13 alpn san asn country asnmatch samecountry org cdnpenalty < "$verified" || {
        rm -rf -- "$workdir"
        printf 'N\n'
        return 0
    }
    tier=$(sni_report_fit_tier "$tls13" "$alpn" "$san" "$asnmatch" "$samecountry" "$cdnpenalty")
    rm -rf -- "$workdir"
    printf '%s\n' "$tier"
}

sni_verified_amazon_fallback() {
    local fallback='www.amazon.com' tier=''
    tier=$(sni_probe_candidate_tier "$fallback" 2>/dev/null) || tier='N'
    case "$tier" in
        A|B|C)
            printf '[SNI auto] Amazon fallback passed TLS 1.3, h2, and certificate SAN checks.\n' >&2
            printf '%s\n' "$fallback"
            ;;
        R)
            printf '[SNI auto] Amazon fallback passed TLS 1.3, h2, and certificate SAN checks, but its CDN/shared-edge risk is elevated; using it only as a fallback.\n' >&2
            printf '%s\n' "$fallback"
            ;;
        *)
            printf '[SNI auto] Amazon fallback failed or could not complete TLS 1.3/h2/SAN verification; no automatic SNI will be selected.\n' >&2
            return 1
            ;;
    esac
}

prompt_reality_sni() {
    local label="$1" port="$2" default_sni input answer prompt warned custom_tier
    default_sni=$(default_sni_for_port "$port")
    while true; do
        prompt=$(tprintf reality_sni_prompt "$label" "$port" "$default_sni")
        read -r -p "$prompt" input || return 1
        input=${input:-$default_sni}
        if ! valid_sni "$input"; then
            printf '%s\n' "${RED}[!] $(tprintf bad_sni "$input")$NC" >&2
            continue
        fi
        warned=0
        if [[ "$port" != '443' ]]; then
            printf '%s\n' "$YELLOW$(tprintf reality_non443_warn "$port")$NC" >&2
            warned=1
        fi
        if is_apple_like_sni "$input"; then
            printf '%s\n' "$YELLOW$(tprintf apple_sni_warn "$input")$NC" >&2
            warned=1
        fi
        if [[ "$input" != "$default_sni" ]]; then
            custom_tier=$(sni_probe_candidate_tier "$input" 2>/dev/null || printf 'N')
            case "$custom_tier" in
                A|B|C)
                    printf '%s\n' "${GREEN}[SNI custom] $(tprintf sni_ok_tier "$custom_tier")$NC" >&2
                    ;;
                R)
                    printf '%s\n' "${YELLOW}[SNI custom] $(tr_msg sni_risky)$NC" >&2
                    warned=1
                    ;;
                D)
                    printf '%s\n' "${YELLOW}[SNI custom] $(tr_msg sni_fail)$NC" >&2
                    warned=1
                    ;;
                *)
                    printf '%s\n' "${YELLOW}[SNI custom] $(tr_msg sni_untestable)$NC" >&2
                    warned=1
                    ;;
            esac
        fi
        if [[ "$warned" == 1 ]]; then
            prompt=$(tprintf continue_or_reset "$label")
            read -r -p "$prompt" answer || return 1
            is_yes "$answer" && { printf '%s\n' "$input"; return 0; }
            continue
        fi
        printf '%s\n' "$input"
        return 0
    done
}

valid_url_https() {
    local url="${1:-}" rest host port
    [[ "$url" == https://* ]] || return 1
    [[ "$url" =~ [\"\`\$\\] ]] && return 1
    [[ "$url" =~ [[:space:]] ]] && return 1
    rest="${url#https://}"
    host="${rest%%/*}"
    [[ -n "$host" ]] || return 1
    if [[ "$host" == *:* ]]; then
        # This parser intentionally accepts DNS host[:port] only. Reject
        # multiple/empty colons instead of truncating them into a different
        # hostname+port pair (for example example.com:443:444).
        [[ "$host" =~ ^([^:]+):([0-9]+)$ ]] || return 1
        host="${BASH_REMATCH[1]}"
        port="${BASH_REMATCH[2]}"
        valid_port "$port" || return 1
    fi
    valid_domain "$host" || return 1
}

normalize_https_url_input() {
    local input="${1:-}" rest
    input="$(printf '%s' "$input" | tr -d '\r' | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')"
    [[ -n "$input" ]] || return 1
    if [[ "$input" != http://* && "$input" != https://* ]]; then
        input="https://${input}"
    fi
    if [[ "$input" == https://* ]]; then
        rest="${input#https://}"
        [[ "$rest" != */* ]] && input="${input}/"
    fi
    printf '%s\n' "$input"
}

prompt_https_url() {
    local prompt="$1" default_url="$2" input normalized
    while true; do
        read -r -p "$prompt" input || return 1
        input="${input:-$default_url}"
        normalized="$(normalize_https_url_input "$input" 2>/dev/null || true)"
        if [[ -n "$normalized" ]] && valid_url_https "$normalized"; then
            printf '%s\n' "$normalized"
            return 0
        fi
        printf '%s\n' "${RED}[!] $(tprintf hy2_url_bad "$input")${NC}" >&2
        printf '%s\n' "${YELLOW}    $(tr_msg hy2_url_example)${NC}" >&2
    done
}

prompt_port_input() {
    local label="$1" default_port="$2" input prompt
    while true; do
        prompt=$(tprintf port_prompt "$label" "$default_port")
        read -r -p "$prompt" input || return 1
        input="${input:-$default_port}"
        if valid_port "$input"; then
            case "$((10#$input))" in
                22|53|68|123|161|323) printf '%s\n' "${RED}[!] $(tprintf pt_reserved "$((10#$input))")${NC}" >&2; continue ;;
            esac
            printf '%s\n' "$((10#$input))"
            return 0
        fi
        printf '%s\n' "${RED}[!] $(tprintf bad_port "$input")${NC}" >&2
    done
}

prompt_ss_port_input() {
    local label="$1" default_port="$2" input prompt
    while true; do
        prompt=$(tprintf ss_port_prompt "$label" "$default_port")
        read -r -p "$prompt" input || return 1
        input="${input:-$default_port}"
        if valid_port "$input"; then
            case "$((10#$input))" in
                22|53|68|123|161|323) printf '%s\n' "${RED}[!] $(tprintf pt_reserved "$((10#$input))")${NC}" >&2; continue ;;
            esac
            printf '%s\n' "$((10#$input))"
            return 0
        fi
        printf '%s\n' "${RED}[!] $(tprintf bad_port "$input")${NC}" >&2
    done
}

prompt_hy2_bandwidth_mbps_input() {
    local prompt="$1" default_value="$2" input
    while true; do
        read -r -p "$prompt" input || return 1
        input="${input:-$default_value}"
        if valid_hy2_bandwidth_mbps "$input"; then
            printf '%s\n' "$input"
            return 0
        fi
        printf '%s\n' "${RED}[!] $(tprintf hy2_bw_bad "$input")${NC}" >&2
    done
}
valid_ipv4_cidr() {
    local input="${1:-}" addr mask n
    addr="${input%/*}"
    mask=''
    if [[ "$input" == */* ]]; then
        mask="${input#*/}"
        [[ -n "$mask" ]] || return 1
    fi
    if [[ -n "$mask" ]]; then
        valid_decimal_upto "$mask" 32 || return 1
        (( 10#$mask > 0 )) || return 1
    fi
    [[ "$addr" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    local IFS=.
    local -a octets
    read -r -a octets <<< "$addr"
    for n in "${octets[@]}"; do
        valid_decimal_upto "$n" 255 || return 1
        # Keep IPv4 text canonical enough for downstream parsers such as Go's
        # net.ParseIP/net.ParseCIDR, which reject octets with leading zeroes.
        [[ "$n" == "0" || "$n" != 0* ]] || return 1
    done
}

valid_ipv6_cidr() {
    local input="${1:-}" addr mask
    addr="${input%/*}"
    mask=''
    if [[ "$input" == */* ]]; then
        mask="${input#*/}"
        [[ -n "$mask" ]] || return 1
    fi
    if [[ -n "$mask" ]]; then
        valid_decimal_upto "$mask" 128 || return 1
        (( 10#$mask > 0 )) || return 1
    fi
    [[ "$addr" == *:* ]] || return 1
    [[ "$addr" =~ ^[0-9A-Fa-f:.]+$ ]] || return 1
    [[ "$addr" != *':::'* ]] || return 1
    if command -v python3 >/dev/null 2>&1; then
        python3 - "$input" <<'PY' >/dev/null 2>&1
import ipaddress, sys
ipaddress.ip_network(sys.argv[1], strict=False)
PY
        return $?
    fi
    return 1
}

valid_ip_address() {
    local input="${1:-}"
    [[ "$input" != */* && -n "$input" ]] || return 1
    valid_ipv4_cidr "$input" || valid_ipv6_cidr "$input"
}

valid_interface_name() {
    local iface="${1:-}"
    # Linux IFNAMSIZ is 16 bytes including the terminating NUL; the usable
    # interface-name limit is therefore 15 characters.
    [[ "$iface" =~ ^[a-zA-Z0-9_.:-]+$ && ${#iface} -le 15 ]]
}

shell_quote() {
    local v=${1:-} q
    q=${v//\\/\\\\}
    q=${q//\"/\\\"}
    q=${q//$'\n'/\\n}
    q=${q//$'\r'/\\r}
    printf '\"%s\"' "$q"
}
json_escape() { jq -Rn --arg v "${1:-}" '$v'; }

clear_abox_env_vars() {
    unset CORE MODE UUID VLESS_SNI VISION_SNI XHTTP_SNI VLESS_PORT XHTTP_PORT HY2_BASE_PORT HY2_DOMAIN HY2_UP HY2_DOWN HY2_MASQ_URL
    unset SS_PORT SS_WHITELIST_IP PUBLIC_KEY PBK SHORT_ID HY2_PASS HY2_OBFS SS_PASS LINK_IP HY2_CERT_SHA256_FP HY2_CERT_PUBKEY_SHA256_B64
    unset HY2_HOP HY2_HOP_IMPL HY2_MONITOR_PORT HY2_ACME_TYPE HY2_ACME_DNS_PROVIDER HY2_ACME_DNS_CF_API_TOKEN
    unset HY2_URI_PORTS HY2_CLASH_PORTS HY2_SB_PORTS HY2_RANGE_START HY2_RANGE_END INGRESS_IF ENABLE_KEEPALIVE
    unset TRAFFIC_LIMIT_GB TRAFFIC_LIMIT_MODE
    unset SOCKS_PORT SOCKS_USER SOCKS_PASS SOCKS_PROTO
}

validate_abox_env_semantics() {
    local p value
    # Pre-deployment state (e.g. traffic limit set before any protocol is
    # deployed) has neither CORE nor MODE; accept it. A half-present pair
    # (one set, one empty/mismatched) is still rejected as corrupt.
    if [[ -n "${CORE:-}${MODE:-}" ]]; then
        [[ "${CORE:-}" =~ ^(xray|singbox|hysteria)$ ]] || return 1
        [[ "${MODE:-}" =~ ^(VISION|XHTTP|SS|ALL|VLESS_SS|HY2|SOCKS)$ ]] || return 1
        case "${CORE}:${MODE}" in
            xray:VISION|xray:XHTTP|xray:SS|xray:ALL|xray:VLESS_SS|xray:SOCKS|singbox:VISION|singbox:SS|singbox:VLESS_SS|singbox:HY2|singbox:ALL|singbox:SOCKS|hysteria:HY2) ;;
            *) return 1 ;;
        esac
    fi
    for p in VLESS_PORT XHTTP_PORT HY2_BASE_PORT SS_PORT HY2_MONITOR_PORT HY2_RANGE_START HY2_RANGE_END SOCKS_PORT; do
        value=${!p:-}
        [[ -z "$value" ]] || valid_canonical_port "$value" || return 1
    done
    if [[ -n "${HY2_RANGE_START:-}${HY2_RANGE_END:-}" ]]; then
        valid_canonical_port "${HY2_RANGE_START:-}" && valid_canonical_port "${HY2_RANGE_END:-}" || return 1
        (( 10#$HY2_RANGE_START <= 10#$HY2_RANGE_END )) || return 1
    fi
    for p in VLESS_SNI VISION_SNI XHTTP_SNI HY2_DOMAIN; do
        value=${!p:-}
        [[ -z "$value" ]] || valid_domain "$value" || return 1
    done
    for p in HY2_UP HY2_DOWN; do
        value=${!p:-}
        [[ -z "$value" ]] || valid_traffic_limit_gb "$value" || return 1
    done
    [[ -z "${HY2_MASQ_URL:-}" ]] || valid_url_https "$HY2_MASQ_URL" || return 1
    [[ -z "${UUID:-}" || "${UUID:-}" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ ]] || return 1
    [[ -z "${SHORT_ID:-}" || "${SHORT_ID:-}" =~ ^[0-9A-Fa-f]{2,32}$ ]] || return 1
    [[ -z "${SHORT_ID:-}" || $(( ${#SHORT_ID} % 2 )) -eq 0 ]] || return 1
    [[ -z "${HY2_CERT_SHA256_FP:-}" || "${HY2_CERT_SHA256_FP:-}" =~ ^[0-9A-Fa-f]{64}$ ]] || return 1
    [[ -z "${LINK_IP:-}" || "${LINK_IP:-}" == N/A ]] || valid_ip_address "$LINK_IP" || return 1
    [[ -z "${HY2_HOP:-}" || "${HY2_HOP:-}" =~ ^(true|false)$ ]] || return 1
    [[ -z "${HY2_HOP_IMPL:-}" || "${HY2_HOP_IMPL:-}" =~ ^(none|manual|official)$ ]] || return 1
    [[ -z "${HY2_ACME_TYPE:-}" || "${HY2_ACME_TYPE:-}" =~ ^(http|dns)$ ]] || return 1
    [[ -z "${ENABLE_KEEPALIVE:-}" || "${ENABLE_KEEPALIVE:-}" =~ ^(true|false)$ ]] || return 1
    [[ -z "${INGRESS_IF:-}" ]] || valid_interface_name "$INGRESS_IF" || return 1
    if [[ -n "${TRAFFIC_LIMIT_GB:-}" ]]; then
        valid_traffic_limit_gb "$TRAFFIC_LIMIT_GB" || return 1
        [[ "${TRAFFIC_LIMIT_MODE:-total}" =~ ^(total|rx|tx)$ ]] || return 1
    else
        [[ -z "${TRAFFIC_LIMIT_MODE:-}" || "${TRAFFIC_LIMIT_MODE:-}" =~ ^(total|rx|tx)$ ]] || return 1
    fi
    if [[ -n "${HY2_URI_PORTS:-}" ]]; then
        valid_hy2_uri_ports "$HY2_URI_PORTS" || return 1
    fi
    if [[ -n "${HY2_CLASH_PORTS:-}" ]]; then
        valid_hy2_clash_ports "$HY2_CLASH_PORTS" || return 1
    fi
    if [[ -n "${HY2_SB_PORTS:-}" ]]; then
        valid_hy2_sb_ports "$HY2_SB_PORTS" || return 1
    fi
    # F-04: validate persisted fields that were previously unchecked on load.
    if [[ -n "${SS_WHITELIST_IP:-}" ]]; then
        local _wl_ip
        local -a _wl_ips=()
        read -r -a _wl_ips <<< "${SS_WHITELIST_IP:-}"
        for _wl_ip in "${_wl_ips[@]}"; do
            valid_ipv4_cidr "$_wl_ip" || valid_ipv6_cidr "$_wl_ip" || return 1
        done
    fi
    [[ -z "${HY2_ACME_DNS_PROVIDER:-}" || "${HY2_ACME_DNS_PROVIDER:-}" == cloudflare ]] || return 1
    [[ -z "${HY2_ACME_DNS_CF_API_TOKEN:-}" ]] || valid_single_line_secret "$HY2_ACME_DNS_CF_API_TOKEN" 512 || return 1
    # P3-1: PUBLIC_KEY (X25519) accepts 43-char RawURLEncoding (Xray/sing-box native, no padding) or 44-char padded base64.
    [[ -z "${PUBLIC_KEY:-}" || "${PUBLIC_KEY:-}" =~ ^[A-Za-z0-9+/_-]{43}=?$ ]] || return 1
    # P3-3: HY2_CERT_PUBKEY_SHA256_B64 validated here on load, not only at use-site.
    [[ -z "${HY2_CERT_PUBKEY_SHA256_B64:-}" || "${HY2_CERT_PUBKEY_SHA256_B64:-}" =~ ^[A-Za-z0-9+/]{43}=$ ]] || return 1
    # P3-2: passwords must be single-line secrets (prevents JSON injection via .env).
    [[ -z "${HY2_PASS:-}" ]] || valid_single_line_secret "$HY2_PASS" 512 || return 1
    [[ -z "${HY2_OBFS:-}" ]] || valid_single_line_secret "$HY2_OBFS" 512 || return 1
    [[ -z "${SS_PASS:-}" ]] || valid_single_line_secret "$SS_PASS" 512 || return 1
    # SOCKS5: validate port/user/pass/proto when enabled.
    if [[ -n "${SOCKS_PORT:-}" ]]; then
        valid_canonical_port "$SOCKS_PORT" || return 1
        [[ -n "${SOCKS_USER:-}" ]] || return 1
        valid_single_line_secret "$SOCKS_USER" 64 || return 1
        [[ -n "${SOCKS_PASS:-}" ]] || return 1
        valid_single_line_secret "$SOCKS_PASS" 128 || return 1
        [[ "${SOCKS_PROTO:-socks}" =~ ^(socks|mixed)$ ]] || return 1
        [[ "$SOCKS_PORT" != "${VLESS_PORT:-}" && "$SOCKS_PORT" != "${SS_PORT:-}" && "$SOCKS_PORT" != "${HY2_BASE_PORT:-}" && "$SOCKS_PORT" != "10085" ]] || return 1
    fi
    if [[ "${MODE:-}" == "SOCKS" && -z "${SOCKS_PORT:-}" ]]; then
        return 1
    fi
}

load_abox_env() {
    local file="${1:-$ABOX_ENV}" parsed key value uid gid mode i
    local -a staged_keys=() staged_values=()
    clear_abox_env_vars
    [[ -r "$file" && -f "$file" && ! -L "$file" ]] || return 1
    uid=$(stat -c %u "$file" 2>/dev/null) || return 1
    gid=$(stat -c %g "$file" 2>/dev/null) || return 1
    mode=$(stat -c %a "$file" 2>/dev/null) || return 1
    [[ "$uid" == '0' && "$gid" == '0' && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#077) == 0 )) || return 1
    command -v python3 >/dev/null 2>&1 || return 1
    parsed=$(umask 077; mktemp /tmp/A-Box-env.XXXXXX) || return 1
    if ! python3 - "$file" > "$parsed" <<'PY_ABOX_ENV'; then
import os
import shlex
import sys

if os.path.getsize(sys.argv[1]) > 65536:
    raise SystemExit("state file too large")

allowed = {
    "CORE", "MODE", "UUID", "VLESS_SNI", "VISION_SNI", "XHTTP_SNI",
    "VLESS_PORT", "XHTTP_PORT", "HY2_BASE_PORT", "HY2_DOMAIN", "HY2_UP",
    "HY2_DOWN", "HY2_MASQ_URL", "SS_PORT", "PUBLIC_KEY", "SHORT_ID",
    "HY2_PASS", "HY2_OBFS", "SS_PASS", "LINK_IP", "HY2_CERT_SHA256_FP",
    "HY2_CERT_PUBKEY_SHA256_B64", "HY2_HOP", "HY2_HOP_IMPL",
    "HY2_MONITOR_PORT", "HY2_ACME_TYPE", "HY2_ACME_DNS_PROVIDER",
    "HY2_ACME_DNS_CF_API_TOKEN", "HY2_URI_PORTS", "HY2_CLASH_PORTS",
    "HY2_SB_PORTS", "HY2_RANGE_START", "HY2_RANGE_END", "INGRESS_IF",
    "ENABLE_KEEPALIVE", "TRAFFIC_LIMIT_GB", "TRAFFIC_LIMIT_MODE",
    "SS_WHITELIST_IP", "SOCKS_PORT", "SOCKS_USER", "SOCKS_PASS", "SOCKS_PROTO",
}
seen = set()
with open(sys.argv[1], "r", encoding="utf-8", errors="strict") as handle:
    for number, raw_line in enumerate(handle, 1):
        if len(raw_line) > 8192:
            raise SystemExit(f"state line too long at line {number}")
        line = raw_line.rstrip("\n")
        if not line or line.lstrip().startswith("#"):
            continue
        if "=" not in line:
            raise SystemExit(f"invalid state line {number}")
        key, raw_value = line.split("=", 1)
        if key not in allowed or key in seen:
            raise SystemExit(f"invalid or duplicate state key at line {number}")
        if not raw_value.strip():
            value = ""
        else:
            parts = shlex.split(raw_value, posix=True)
            if len(parts) != 1:
                raise SystemExit(f"invalid state value at line {number}")
            value = parts[0]
        if len(value.encode("utf-8")) > 4096:
            raise SystemExit(f"state value too long at line {number}")
        if "\x00" in value or "\n" in value or "\r" in value:
            raise SystemExit(f"invalid control character at line {number}")
        seen.add(key)
        sys.stdout.buffer.write(key.encode("ascii") + b"\0" + value.encode("utf-8") + b"\0")
PY_ABOX_ENV
        rm -f "$parsed"
        clear_abox_env_vars
        return 1
    fi
    while IFS= read -r -d '' key && IFS= read -r -d '' value; do
        staged_keys+=("$key")
        staged_values+=("$value")
    done < "$parsed"
    rm -f "$parsed"
    clear_abox_env_vars
    for ((i=0; i<${#staged_keys[@]}; i++)); do
        printf -v "${staged_keys[i]}" '%s' "${staged_values[i]}"
    done
    if ! validate_abox_env_semantics; then
        clear_abox_env_vars
        return 1
    fi
}


load_optional_abox_env_or_die() {
    # A missing .env is valid during first-time setup. An existing but invalid,
    # unsafe, or unreadable .env must never be treated as an empty installation.
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        load_abox_env "$ABOX_ENV" 2>/dev/null || die "$(tr_msg env_bad)"
    else
        clear_abox_env_vars
    fi
}

rand_alnum() {
    local len="$1" out='' chunk attempt target max_attempts
    valid_positive_int "$len" && (( 10#$len <= 4096 )) || die "$(tr_msg rnd_len)"
    target=$((10#$len))
    # The previous fixed 16 rounds could never produce 4096 alphanumeric chars.
    max_attempts=$(( (target + 255) / 256 + 16 ))
    for ((attempt=0; attempt<max_attempts && ${#out}<target; attempt++)); do
        chunk=$(openssl rand -base64 256 2>/dev/null | tr -dc 'a-zA-Z0-9') || chunk=''
        [[ -n "$chunk" ]] && out+="$chunk"
    done
    (( ${#out} >= target )) || die "$(tr_msg rnd_src)"
    printf '%s\n' "${out:0:target}"
}

generate_robust_uuid() {
    local candidate u variant
    if command -v uuidgen >/dev/null 2>&1; then
        candidate=$(uuidgen 2>/dev/null || true)
        if [[ "$candidate" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-4[0-9A-Fa-f]{3}-[89AaBb][0-9A-Fa-f]{3}-[0-9A-Fa-f]{12}$ ]]; then
            printf '%s\n' "$candidate"
            return 0
        fi
    fi
    if [[ -r /proc/sys/kernel/random/uuid ]]; then
        candidate=$(tr -d '\n\r' < /proc/sys/kernel/random/uuid 2>/dev/null || true)
        if [[ "$candidate" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-4[0-9A-Fa-f]{3}-[89AaBb][0-9A-Fa-f]{3}-[0-9A-Fa-f]{12}$ ]]; then
            printf '%s\n' "$candidate"
            return 0
        fi
    fi
    {
        local u variant
        u=$(openssl rand -hex 16 2>/dev/null) || u=''
        [[ ${#u} -eq 32 ]] || die "$(tr_msg rnd_uuid)"
        case "${u:16:1}" in
            0|1|2|3) variant=8 ;;
            4|5|6|7) variant=9 ;;
            8|9|a|b) variant=a ;;
            *) variant=b ;;
        esac
        printf '%s-%s-4%s-%s%s-%s\n' "${u:0:8}" "${u:8:4}" "${u:13:3}" "$variant" "${u:17:3}" "${u:20:12}"
    }
}

pin_sha256_colon() {
    openssl x509 -noout -fingerprint -sha256 -in "$1" | cut -d= -f2
}

valid_public_ip() {
    local ip="${1:-}"
    valid_ip_address "$ip" || return 1
    python3 - "$ip" <<'PY_PUBLIC_IP'
import ipaddress, sys
try:
    addr = ipaddress.ip_address(sys.argv[1])
except ValueError:
    raise SystemExit(1)
if (addr.is_multicast or addr.is_reserved or addr.is_loopback or
    addr.is_link_local or addr.is_unspecified or addr.is_private):
    raise SystemExit(1)
if addr.version == 6 and addr.ipv4_mapped is not None:
    raise SystemExit(1)
if addr.version == 4:
    blocked = (
        ipaddress.ip_network('0.0.0.0/8'),
        ipaddress.ip_network('192.0.0.0/24'),
        ipaddress.ip_network('192.88.99.0/24'),
        ipaddress.ip_network('198.18.0.0/15'),
        ipaddress.ip_network('198.51.100.0/24'),
        ipaddress.ip_network('203.0.113.0/24'),
        ipaddress.ip_network('240.0.0.0/4'),
    )
else:
    blocked = (
        ipaddress.ip_network('2001:db8::/32'),
        ipaddress.ip_network('2001:2::/48'),
        ipaddress.ip_network('2001:20::/28'),
        ipaddress.ip_network('64:ff9b::/96'),
    )
if any(addr in network for network in blocked):
    raise SystemExit(1)
if not addr.is_global:
    raise SystemExit(1)
raise SystemExit(0)
PY_PUBLIC_IP
}

# BUG-28: hoisted from get_public_ip_fresh().
__abox_try_v4() {
    local api ip
    for api in 'https://api.ipify.org' 'https://ifconfig.me/ip' 'https://icanhazip.com'; do
        ip=$(curl -fsS4 --connect-timeout "$PUBLIC_IP_CONNECT_TIMEOUT" -m "$PUBLIC_IP_MAX_TIME" "$api" 2>/dev/null | tr -d '[:space:]')
        if valid_public_ip "$ip"; then
            printf '%s\n' "$ip"
            return 0
        fi
    done
    return 1
}
# BUG-28: hoisted from get_public_ip_fresh().
__abox_try_v6() {
    local api ip
    for api in 'https://api64.ipify.org' 'https://ifconfig.me/ip' 'https://icanhazip.com'; do
        ip=$(curl -fsS6 --connect-timeout "$PUBLIC_IP_CONNECT_TIMEOUT" -m "$PUBLIC_IP_MAX_TIME" "$api" 2>/dev/null | tr -d '[:space:]')
        if valid_public_ip "$ip"; then
            printf '%s\n' "$ip"
            return 0
        fi
    done
    return 1
}
get_public_ip_fresh() {
    local ip api pref
    pref=$(read_ip_pref 2>/dev/null || printf 'dual')
    case "$pref" in
        ipv4)
            __abox_try_v4 && return 0
            ;;
        ipv6)
            __abox_try_v6 && return 0
            ;;
        *)
            __abox_try_v4 && return 0
            __abox_try_v6 && return 0
            ;;
    esac
    printf 'N/A\n'
    return 1
}

cache_public_ip() {
    local ip="$1"
    [[ -n "$ip" && "$ip" != 'N/A' ]] || return 0
    ensure_abox_dir_owned "$ABOX_DIR"
    write_file_atomically_from_stdin "$PUBLIC_IP_CACHE" 600 <<< "$ip" || return 1
}

read_cached_public_ip() {
    local ip now mtime age
    [[ -r "$PUBLIC_IP_CACHE" && -f "$PUBLIC_IP_CACHE" && ! -L "$PUBLIC_IP_CACHE" ]] || return 1
    [[ "$(stat -c %u:%g "$PUBLIC_IP_CACHE" 2>/dev/null || true)" == 0:0 ]] || return 1
    ip=$(head -n 1 "$PUBLIC_IP_CACHE" 2>/dev/null | tr -d '[:space:]')
    if ! valid_public_ip "$ip"; then
        return 1
    fi
    now=$(date +%s)
    mtime=$(stat -c %Y "$PUBLIC_IP_CACHE" 2>/dev/null || echo 0)
    age=$(( now - mtime ))
    (( age >= 0 && age <= PUBLIC_IP_CACHE_TTL )) || return 1
    printf '%s\n' "$ip"
}

get_public_ip() {
    local ip stale age now mtime
    ip=$(read_cached_public_ip 2>/dev/null || true)
    if [[ -n "$ip" ]]; then
        printf '%s\n' "$ip"
        return 0
    fi
    ip=$(get_public_ip_fresh || true)
    if [[ -n "$ip" && "$ip" != 'N/A' ]]; then
        cache_public_ip "$ip"
        printf '%s\n' "$ip"
        return 0
    fi
    # Never silently use an expired address for generated client links.  A
    # stale address can route users to an unrelated host after VPS renumbering.
    if [[ -r "$PUBLIC_IP_CACHE" && -f "$PUBLIC_IP_CACHE" && ! -L "$PUBLIC_IP_CACHE" ]]; then
        stale=$(head -n 1 "$PUBLIC_IP_CACHE" 2>/dev/null | tr -d '[:space:]')
        if valid_public_ip "$stale"; then
            now=$(date +%s)
            mtime=$(stat -c %Y "$PUBLIC_IP_CACHE" 2>/dev/null || echo 0)
            age=$(( now - mtime ))
            printf '[!] Cached public IP is stale (%ss old); refusing to use it.\n' "$age" >&2
        fi
    fi
    printf 'N/A\n'
    return 1
}

# Background refresh of the public-IP cache (best effort, detached).
refresh_public_ip_bg() {
    ( refresh_public_ip >/dev/null 2>&1 || true ) >/dev/null 2>&1 &
}

# Startup/menu path: stale-while-revalidate. A fresh cache (strict TTL)
# is used as-is; a stale-but-recent (<=24h) cache is served immediately
# and refreshed in the background, so entering the menu never blocks on
# the serial IP-echo endpoints. Only a missing/unusable cache pays the
# synchronous fetch. Link generation keeps the strict code paths.
get_public_ip_swr() {
    local ip=''
    if ip=$(read_cached_public_ip 2>/dev/null) && [[ -n "$ip" ]]; then
        printf '%s\n' "$ip"; return 0
    fi
    if [[ -r "$PUBLIC_IP_CACHE" && -f "$PUBLIC_IP_CACHE" && ! -L "$PUBLIC_IP_CACHE" ]]; then
        local _ip='' _now=0 _mt=0
        _ip=$(head -n 1 "$PUBLIC_IP_CACHE" 2>/dev/null | tr -d '[:space:]')
        if valid_public_ip "$_ip"; then
            _now=$(date +%s); _mt=$(stat -c %Y "$PUBLIC_IP_CACHE" 2>/dev/null || echo 0)
            if (( _now - _mt >= 0 && _now - _mt <= 86400 )); then
                refresh_public_ip_bg
                printf '%s\n' "$_ip"; return 0
            fi
        fi
    fi
    get_public_ip
}

refresh_public_ip() {
    local ip
    ip=$(get_public_ip_fresh || true)
    if [[ -n "$ip" && "$ip" != 'N/A' ]]; then
        cache_public_ip "$ip"
        printf '%s\n' "$ip"
        return 0
    fi
    get_public_ip
}
get_active_interface() {
    local iface
    iface=$(ip route get 8.8.8.8 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [[ -z "$iface" ]] && iface=$(ip -6 route get 2001:4860:4860::8888 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [[ -z "$iface" ]] && iface=$(ip -o route show to default 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [[ -z "$iface" ]] && iface=$(ip -6 -o route show to default 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [[ -z "$iface" ]] && iface=$(ip -o link show up 2>/dev/null | awk -F': ' '$2 !~ /^(lo|vir|wl)/ {sub(/@.*/,"",$2); print $2; exit}')
    printf '%s\n' "$iface"
}

resolve_domain_addresses() {
    local domain="${1:-}" resolved=''
    valid_domain "$domain" || return 1
    # N-05 fix: wrap getent in timeout; a hanging DNS resolver must not
    # block the SNI batch worker forever.
    if command -v getent >/dev/null 2>&1; then
        if command -v timeout >/dev/null 2>&1; then
            resolved=$(timeout 5 getent ahosts "$domain" 2>/dev/null | awk 'NF {print $1}' | sort -u) || resolved=''
            if [[ -z "$resolved" ]]; then
                resolved=$(timeout 5 getent hosts "$domain" 2>/dev/null | awk 'NF {print $1}' | sort -u) || resolved=''
            fi
        else
            resolved=$(getent ahosts "$domain" 2>/dev/null | awk 'NF {print $1}' | sort -u) || resolved=''
            if [[ -z "$resolved" ]]; then
                resolved=$(getent hosts "$domain" 2>/dev/null | awk 'NF {print $1}' | sort -u) || resolved=''
            fi
        fi
    fi
    [[ -n "$resolved" ]] || return 1
    printf '%s\n' "$resolved"
}

verify_domain_points_to_self() {
    local domain="$1" pub_ip="$2" resolved continue_domain
    resolved=$(resolve_domain_addresses "$domain") || die "$(tprintf dom_unresolved "$domain")"
    if [[ "$pub_ip" != 'N/A' ]] && ! grep -Fxq "$pub_ip" <<< "$resolved"; then
        msg "${YELLOW}[!] 域名已解析，但未发现解析到当前公网 IP: $pub_ip${NC}"
        printf '%s\n\n%s\n' "${YELLOW}$(tr_msg dom_resolved_label)${NC}" "$resolved"
        read -r -p "$(tr_msg dom_continue)" continue_domain
        is_yes "$continue_domain" || die "$(tr_msg dom_cancelled)"
    fi
}

openrc_cron_service_name() {
    case "$1" in
        debian|ubuntu) printf '%s\n' cron ;;
        alpine)
            # Prefer an installed alternate cron OpenRC unit. BusyBox ships
            # /etc/init.d/crond by default; apk add cronie/dcron adds a different
            # unit name and must not leave the BusyBox unit as the only target.
            if [[ -x /etc/init.d/cronie ]]; then
                printf '%s\n' cronie
            elif [[ -x /etc/init.d/dcron ]]; then
                printf '%s\n' dcron
            else
                printf '%s\n' crond
            fi
            ;;
        *) printf '%s\n' crond ;;
    esac
}

# BUG-28: hoisted from init_system_environment().
__abox_reconcile_systemd_unit() {
    local unit="$1"
    systemctl list-unit-files --type=service --no-legend "${unit}.service" 2>/dev/null | awk -v wanted="${unit}.service" '$1 == wanted { found=1 } END { exit !found }' || return 0
    systemctl enable --now "$unit" >/dev/null 2>&1 || die "$(tprintf sv_unit_enable "$unit")"
    systemctl is-active --quiet "$unit" || die "$(tprintf sv_unit_inactive "$unit")"
}
# BUG-28: hoisted from init_system_environment().
__abox_reconcile_openrc_service() {
    local unit="$1"
    [[ -x "/etc/init.d/${unit}" ]] || return 0
    rc-update add "$unit" default >/dev/null 2>&1 || die "$(tprintf sv_orc_add "$unit")"
    rc-service "$unit" status >/dev/null 2>&1 || rc-service "$unit" start >/dev/null 2>&1 9>&- 10>&- || die "$(tprintf sv_orc_start "$unit")"
    rc-service "$unit" status >/dev/null 2>&1 || die "$(tprintf sv_orc_notrunning "$unit")"
}
init_system_environment() {
    local _init_soft="${1:-}"
    release=''
    local -a install_cmd=()
    if [[ -f /etc/os-release ]]; then
        . /etc/os-release
        case "${ID:-}" in
            debian) release='debian'; install_cmd=(apt-get -y install) ;;
            ubuntu) release='ubuntu'; install_cmd=(apt-get -y install) ;;
            alpine) release='alpine'; install_cmd=(apk add) ;;
            centos|rhel|rocky|almalinux|fedora|amzn|ol|oracle) release='centos'; install_cmd=(yum -y install) ;;
        esac
        # ID_LIKE fallback for derivatives (e.g. ID=pop ID_LIKE="ubuntu debian").
        if [[ -z "$release" && -n "${ID_LIKE:-}" ]]; then
            case " ${ID_LIKE} " in
                *' debian '*|*' ubuntu '*) release='debian'; install_cmd=(apt-get -y install) ;;
                *' rhel '*|*' fedora '*|*' centos '*) release='centos'; install_cmd=(yum -y install) ;;
            esac
        fi
    fi
    if [[ -z "$release" ]]; then
        if [[ -f /etc/redhat-release ]] || grep -qiE 'centos|red hat|rocky|almalinux|fedora|amazon|oracle' /proc/version 2>/dev/null; then
            release='centos'; install_cmd=(yum -y install)
        elif grep -qi 'Alpine' /etc/issue /proc/version 2>/dev/null; then
            release='alpine'; install_cmd=(apk add)
        elif grep -qi 'debian' /etc/issue /proc/version 2>/dev/null; then
            release='debian'; install_cmd=(apt-get -y install)
        elif grep -qi 'ubuntu' /etc/issue /proc/version 2>/dev/null; then
            release='ubuntu'; install_cmd=(apt-get -y install)
        fi
    fi
    [[ -z "$release" ]] && die "$(tr_msg ie_unsupported)"
    if [[ "$release" == 'centos' ]] && command -v dnf >/dev/null 2>&1; then
        install_cmd=(dnf -y install)
    fi

    if systemd_available; then
        INIT_SYS='systemd'
    elif command -v rc-service >/dev/null 2>&1; then
        INIT_SYS='openrc'
    elif [[ "$_init_soft" == 'soft' ]]; then
        # Menu-open path only: browsing needs no init system. Every
        # deployment entry calls this function without 'soft' and
        # keeps the hard gate below.
        INIT_SYS='unknown'
        msg "${YELLOW}[!] $(tr_msg init_soft_warn)${NC}"
    else
        die "$(tr_msg ie_no_init)"
    fi

    if [[ ! -f "$DEPS_MARKER" ]]; then
        msg "${YELLOW}[*] 正在同步系统依赖环境 (OS: ${release}, Init: ${INIT_SYS})...${NC}"
        case "$release" in
            debian|ubuntu) apt-get update -y -q >/dev/null 2>&1 ;;
            centos) if command -v dnf >/dev/null 2>&1; then dnf makecache -y -q >/dev/null 2>&1 || true; else yum makecache -y -q >/dev/null 2>&1 || true; fi; "${install_cmd[@]}" epel-release >/dev/null 2>&1 || true ;;
            alpine) apk update -q >/dev/null 2>&1 ;;
        esac
        local deps=()
        case "$release" in
            debian|ubuntu)
                deps=(curl jq openssl bc unzip iptables tar psmisc lsof ca-certificates iproute2 coreutils cron logrotate uuid-runtime python3 util-linux diffutils)
                ;;
            centos)
                # Do not force the full 'curl' RPM when curl-minimal already provides
                # /usr/bin/curl (Rocky/Alma/RHEL 8+/9). Forcing curl conflicts with curl-minimal.
                # diffutils provides cmp(1), required by atomic install / OTA / traffic helpers.
                # Fix 2026-10-14: epel-release removed from required deps (EPEL does not exist
                # on Fedora; the opportunistic install above already tries it with || true
                # for RHEL derivatives that need it).
                deps=(jq openssl bc unzip iptables tar psmisc lsof ca-certificates coreutils cronie logrotate util-linux bind-utils iproute python3 diffutils)
                command -v curl >/dev/null 2>&1 || deps+=(curl)
                ;;
            alpine)
                # Use BusyBox crond (OpenRC unit name: crond). Do not apk-add cronie by
                # default: it lives in community and registers unit 'cronie', which used
                # to disagree with openrc_cron_service_name returning 'crond'.
                # Explicit 'tar' pulls GNU tar so backup fixtures and archives support
                # GNU long options where needed.
                deps=(bash curl jq openssl bc unzip iptables tar psmisc lsof ca-certificates iproute2 coreutils logrotate util-linux bind-tools procps iptables-openrc python3 shadow)
                ;;
        esac
        if [[ "$release" == 'centos' ]] && command -v dnf >/dev/null 2>&1; then
            # --allowerasing covers residual curl <-> curl-minimal swaps if curl is needed.
            dnf -y install --allowerasing "${deps[@]}" >/dev/null 2>&1 || die "$(tr_msg ie_deps)"
        else
            "${install_cmd[@]}" "${deps[@]}" >/dev/null 2>&1 || die "$(tr_msg ie_deps)"
        fi
        ensure_abox_dir_owned "$ABOX_DIR"
        install -m 600 /dev/null "$DEPS_MARKER" || die "$(tr_msg ie_deps_marker)"
    fi

    ensure_commands

    if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
        case "$release" in
            debian|ubuntu) __abox_reconcile_systemd_unit cron ;;
            centos) __abox_reconcile_systemd_unit crond ;;
        esac
        if [[ "$release" == 'centos' ]]; then
            if command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
                msg "${YELLOW}[*] firewalld is active; A-Box will add required ports natively and will not disable it.${NC}"
            else
                msg "${YELLOW}[*] firewalld is inactive; A-Box will persist only its own rules through A-Box-firewall.service.${NC}"
            fi
        fi
    elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then
        local cron_unit
        cron_unit=$(openrc_cron_service_name "$release")
        if [[ "$release" == 'alpine' && "$cron_unit" != 'crond' && -x /etc/init.d/crond ]]; then
            # Avoid dual schedulers after apk add cronie/dcron (Alpine wiki guidance).
            rc-service crond stop >/dev/null 2>&1 || true
            if command -v rc-update >/dev/null 2>&1 && rc-update show default 2>/dev/null | grep -Eq '(^|[[:space:]])crond([[:space:]]|$)'; then
                rc-update del crond default >/dev/null 2>&1 || true
            fi
        fi
        __abox_reconcile_openrc_service "$cron_unit"
    fi

    IPT=$(command -v iptables || echo '/sbin/iptables')
    IPT6=$(command -v ip6tables || echo '/sbin/ip6tables')
}

install_optional_package() {
    local pkg="$1"
    [[ -n "$pkg" ]] || return 1
    case "${release:-}" in
        debian|ubuntu) command -v apt-get >/dev/null 2>&1 && apt-get -y install "$pkg" >/dev/null 2>&1 ;;
        centos) if command -v dnf >/dev/null 2>&1; then dnf -y install --allowerasing "$pkg" >/dev/null 2>&1; elif command -v yum >/dev/null 2>&1; then yum -y install "$pkg" >/dev/null 2>&1; else return 1; fi ;;
        alpine) command -v apk >/dev/null 2>&1 && apk add "$pkg" >/dev/null 2>&1 ;;
        *) return 1 ;;
    esac
}

# FINAL-AUDIT: counterpart of install_optional_package, used only by rollback
# to undo a package installation performed by the current transaction.
remove_optional_package() {
    local pkg="$1"
    [[ -n "$pkg" ]] || return 1
    case "${release:-}" in
        debian|ubuntu) command -v apt-get >/dev/null 2>&1 && apt-get -y remove "$pkg" >/dev/null 2>&1 ;;
        centos) if command -v dnf >/dev/null 2>&1; then dnf -y remove "$pkg" >/dev/null 2>&1; elif command -v yum >/dev/null 2>&1; then yum -y remove "$pkg" >/dev/null 2>&1; else return 1; fi ;;
        alpine) command -v apk >/dev/null 2>&1 && apk del "$pkg" >/dev/null 2>&1 ;;
        *) return 1 ;;
    esac
}

# BUG-28: hoisted from ensure_commands(). Redesigned as a query function:
# prints the package name to install when $2 is missing, prints nothing when present.
# $1=release (debian|ubuntu|centos|alpine); unknown release prints nothing (no-op).
__abox_missing_pkg_for() {
    local release="$1" cmd="$2" deb="$3" rpm="$4" apk="$5"
    command -v "$cmd" >/dev/null 2>&1 && return 0
    case "$release" in
        debian|ubuntu) printf '%s\n' "$deb" ;;
        centos) printf '%s\n' "$rpm" ;;
        alpine) printf '%s\n' "$apk" ;;
    esac
}
ensure_commands() {
    local missing_pkgs=()
    local -a _ens_install_cmd=()
    case "${release:-}" in
        debian|ubuntu) _ens_install_cmd=(apt-get -y install) ;;
        alpine) _ens_install_cmd=(apk add) ;;
        centos) if command -v dnf >/dev/null 2>&1; then _ens_install_cmd=(dnf -y install --allowerasing); else _ens_install_cmd=(yum -y install); fi ;;
    esac
    local _pkg
    _pkg=$(__abox_missing_pkg_for "$release" curl curl curl curl)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" jq jq jq jq)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" openssl openssl openssl openssl)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" bc bc bc bc)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" unzip unzip unzip unzip)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" tar tar tar tar)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" iptables iptables iptables iptables)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" ss iproute2 iproute iproute2)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" lsof lsof lsof lsof)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" getent libc-bin glibc-common libc-utils)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" flock util-linux util-linux util-linux)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" cmp diffutils diffutils diffutils)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" crontab cron cronie busybox)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" logrotate logrotate logrotate logrotate)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" python3 python3 python3 python3)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" groupadd passwd shadow-utils shadow)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    _pkg=$(__abox_missing_pkg_for "$release" useradd passwd shadow-utils shadow)
    [[ -n "$_pkg" ]] && missing_pkgs+=("$_pkg")
    if (( ${#missing_pkgs[@]} > 0 )); then
        local -a unique_pkgs=()
        mapfile -t unique_pkgs < <(printf '%s\n' "${missing_pkgs[@]}" | awk 'NF && !seen[$0]++')
        msg "${YELLOW}[*] 检测到缺失依赖包，正在补装...${NC}"
        "${_ens_install_cmd[@]}" "${unique_pkgs[@]}" >/dev/null 2>&1 || die "$(tr_msg ec_reinstall)"
    fi
    local required=(curl jq openssl bc unzip tar iptables ss lsof crontab logrotate python3 flock cmp)
    local c
    for c in "${required[@]}"; do
        command -v "$c" >/dev/null 2>&1 || die "$(tprintf ec_missing "$c")"
    done
    # flock is now guaranteed; upgrade any pre-ensure fallback lock onto LOCK_FILE.
    if [[ "${ABOX_RUNTIME_LOCK_MODE:-}" == fallback ]]; then
        upgrade_runtime_lock_to_flock_if_possible || die "$(tr_msg ec_lock)"
    fi
}

has_ipv6() {
    local _pref
    _pref=$(read_ip_pref 2>/dev/null || printf 'dual')
    [[ "$_pref" == 'ipv4' ]] && return 1
    ip -6 addr show scope global 2>/dev/null | awk '/inet6/ { found=1 } END { exit !found }' && return 0
    ip -6 route show default 2>/dev/null | awk '/^default/ { found=1 } END { exit !found }' && return 0
    return 1
}

wildcard_listen_address() {
    local bindv6only='0' pref
    pref=$(read_ip_pref 2>/dev/null || printf 'dual')
    case "$pref" in
        ipv4)
            printf '0.0.0.0'
            return 0
            ;;
        ipv6)
            has_ipv6 || die "$(tr_msg wl_v6_only)"
            printf '::'
            return 0
            ;;
    esac
    # dual (default): prefer :: when the kernel dual-stacks IPv4-mapped traffic.
    bindv6only=$(cat /proc/sys/net/ipv6/bindv6only 2>/dev/null || printf '0')
    if has_ipv6 && [[ "$bindv6only" == '0' ]]; then
        printf '::'
    else
        # Preserve IPv4 reachability on IPv4-only or v6-only-wildcard hosts.
        printf '0.0.0.0'
    fi
}

_iptables_probe_w() {
    local cmd="$1"
    local cache_var="_IPT_W_${cmd//[^a-zA-Z0-9]/_}"
    if [[ -z "${!cache_var+x}" ]]; then
        if "$cmd" -w --version >/dev/null 2>&1; then
            printf -v "$cache_var" '%s' '-w'
        else
            printf -v "$cache_var" '%s' ''
        fi
    fi
    _IPT_W_CUR="${!cache_var}"
}
_iptables_q() {
    local cmd="$1"; shift
    _iptables_probe_w "$cmd"
    if [[ -n "$_IPT_W_CUR" ]]; then
        "$cmd" "$_IPT_W_CUR" "$@"
    else
        "$cmd" "$@"
    fi
}
_iptables_do() {
    local cmd="$1"; shift
    _iptables_probe_w "$cmd"
    if [[ -n "$_IPT_W_CUR" ]]; then
        "$cmd" "$_IPT_W_CUR" "$@"
    else
        "$cmd" "$@"
    fi
}
ipv6_nat_redirect_usable() {
    command -v ip6tables >/dev/null 2>&1 || return 1
    _iptables_q "$IPT6" -t nat -L PREROUTING >/dev/null 2>&1 || return 1
}

get_architecture() {
    local ARCH
    ARCH=$(uname -m)
    case "$ARCH" in
        x86_64|amd64) XRAY_ARCH='64'; SB_ARCH='amd64'; HY2_ARCH='amd64' ;;
        # armv8l is a 32-bit ARMv8 target, not AArch64; fail closed rather than
        # installing 64-bit arm64/aarch64 binaries into a 32-bit userspace.
        aarch64|arm64) XRAY_ARCH='arm64-v8a'; SB_ARCH='arm64'; HY2_ARCH='arm64' ;;
        *) die "$(tprintf ga_unknown "$ARCH")" ;;
    esac
}

systemd_available() {
    command -v systemctl >/dev/null 2>&1 || return 1
    [[ -r /proc/1/comm ]] || return 1
    [[ "$(cat /proc/1/comm 2>/dev/null || true)" == 'systemd' ]] || return 1
}

# Perf 2026-10-14: batch version to avoid 3x systemctl per menu refresh.
# Usage: service_active_states_batch xray sing-box hysteria
# Output: lines of "srv:1" or "srv:0" or "srv:?" 
service_active_states_batch() {
    local srv state out
    if [[ "${INIT_SYS:-}" == systemd ]] && systemd_available; then
        # Single systemctl call for all services
        out=$(systemctl show -p Id -p ActiveState --value "$@" 2>/dev/null) || return 1
        # Parse: output is pairs of Id, ActiveState lines
        local id=""
        while IFS= read -r line; do
            [[ -z "$line" ]] && continue
            if [[ -z "$id" ]]; then
                id="${line%.service}"
            else
                case "$line" in
                    active) printf '%s:1\n' "$id" ;;
                    inactive|failed|dead|exited) printf '%s:0\n' "$id" ;;
                    *) printf '%s:?\n' "$id" ;;
                esac
                id=""
            fi
        done <<< "$out"
        return 0
    fi
    return 1
}

service_active_state_value() {
    local srv="$1" state rc
    if [[ "${INIT_SYS:-}" == systemd ]] && systemd_available; then
        state=$(systemctl show -p ActiveState --value "$srv" 2>/dev/null) || return 1
        case "$state" in
            active) printf '1\n' ;;
            inactive|failed|dead|exited) printf '0\n' ;;
            *) return 1 ;;
        esac
        return 0
    elif [[ "${INIT_SYS:-}" == openrc ]]; then
        command -v rc-service >/dev/null 2>&1 || return 1
        rc-service "$srv" status >/dev/null 2>&1
        rc=$?
        case "$rc" in
            0) printf '1\n' ;;
            3|16|32) printf '0\n' ;;
            *) return 1 ;;
        esac
        return 0
    fi
    return 1
}

service_manager() {
    local action=$1; shift
    local srv
    for srv in "$@"; do
        if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
            case "$action" in
                stop)
                    systemctl stop "$srv" >/dev/null 2>&1 || true
                    [[ "$(service_active_state_value "$srv" 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
                    systemctl disable "$srv" >/dev/null 2>&1 || return 1
                    [[ "$(service_active_state_value "$srv" 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
                    ;;
                start)
                    systemctl daemon-reload >/dev/null 2>&1 || die 'systemd daemon-reload failed.'
                    systemctl enable "$srv" >/dev/null 2>&1 || die "$(tprintf sv_enable_boot "$srv")"
                    if ! systemctl restart "$srv" >/dev/null 2>&1; then
                        journalctl -u "$srv" --no-pager -n 80 2>/dev/null || true
                        die "$(tprintf sv_restart_fail "$srv")"
                    fi
                    sleep 2
                    if ! systemctl is-active --quiet "$srv"; then
                        journalctl -u "$srv" --no-pager -n 80 2>/dev/null || true
                        case "$srv" in sing-box|hysteria) clean_nat_rules 2>/dev/null || true; save_firewall_rules 2>/dev/null || true ;; esac
                        die "$(tprintf sv_up_fail "$srv")"
                    fi
                    record_core_family_ownership "$srv" || die "$(tprintf sv_ownership "$srv")"
                    ;;
                *) die "$(tprintf sv_unknown_action "$action")" ;;
            esac
        else
            case "$action" in
                stop)
                    rc-service "$srv" stop >/dev/null 2>&1 || true
                    [[ "$(service_active_state_value "$srv" 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
                    # Not being in default runlevel is success; OpenRC returns non-zero then.
                    if rc-update show default 2>/dev/null | grep -Eq "(^|[[:space:]])${srv}([[:space:]]|$)"; then
                        rc-update del "$srv" default >/dev/null 2>&1 || return 1
                    fi
                    [[ "$(service_active_state_value "$srv" 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
                    ;;
                start)
                    rc-update add "$srv" default >/dev/null 2>&1 || die "$(tprintf sv_orc_add2 "$srv")"
                    rc-service "$srv" restart >/dev/null 2>&1 9>&- 10>&- || die "$(tprintf sv_orc_restart "$srv")"
                    sleep 2
                    if ! rc-service "$srv" status >/dev/null 2>&1; then
                        case "$srv" in sing-box|hysteria) clean_nat_rules 2>/dev/null || true; save_firewall_rules 2>/dev/null || true ;; esac
                        die "$(tprintf sv_up_fail "$srv")"
                    fi
                    record_core_family_ownership "$srv" || die "$(tprintf sv_ownership "$srv")"
                    ;;
                *) die "$(tprintf sv_unknown_action "$action")" ;;
            esac
        fi
    done
}

service_unit_path() {
    local srv="$1"
    case "${INIT_SYS:-}" in
        systemd) printf '/etc/systemd/system/%s.service\n' "$srv" ;;
        openrc) printf '/etc/init.d/%s\n' "$srv" ;;
        *)
            if [[ -e "/etc/systemd/system/${srv}.service" || -L "/etc/systemd/system/${srv}.service" ]]; then
                printf '/etc/systemd/system/%s.service\n' "$srv"
            elif [[ -e "/etc/init.d/${srv}" || -L "/etc/init.d/${srv}" ]]; then
                printf '/etc/init.d/%s\n' "$srv"
            else
                return 1
            fi
            ;;
    esac
}


service_file_is_abox_managed() {
    local srv="$1" unit=''
    unit=$(service_unit_path "$srv" 2>/dev/null || true)
    [[ -n "$unit" && -f "$unit" && ! -L "$unit" ]] || return 1
    # Destructive ownership decisions require the exact marker.  Names,
    # standard paths, descriptions, or a stale .env file are not proof.
    grep -Fxq '# Managed by A-Box' "$unit"
}


abox_owns_service() {
    local srv="$1" unit=''
    unit=$(service_unit_path "$srv" 2>/dev/null || true)
    # Destructive ownership decisions require a concrete managed unit.  A
    # stale .env file is state, not proof that standard system paths are ours.
    [[ -n "$unit" && ( -e "$unit" || -L "$unit" ) ]] || return 1
    service_file_is_abox_managed "$srv"
}

effective_init_system() {
    if [[ "${INIT_SYS:-}" == systemd || "${INIT_SYS:-}" == openrc ]]; then
        printf '%s\n' "$INIT_SYS"
    elif systemd_available; then
        printf 'systemd\n'
    elif command -v rc-service >/dev/null 2>&1; then
        printf 'openrc\n'
    else
        printf 'unknown\n'
    fi
}

systemd_same_name_unit_path() {
    local srv="$1" path candidate
    if command -v systemctl >/dev/null 2>&1; then
        path=$(systemctl show -p FragmentPath --value "${srv}.service" 2>/dev/null || true)
        if [[ -n "$path" && ( -e "$path" || -L "$path" ) ]]; then printf '%s\n' "$path"; return 0; fi
    fi
    for candidate in "/etc/systemd/system/${srv}.service" "/run/systemd/system/${srv}.service" "/usr/local/lib/systemd/system/${srv}.service" "/usr/lib/systemd/system/${srv}.service" "/lib/systemd/system/${srv}.service"; do
        if [[ -e "$candidate" || -L "$candidate" ]]; then printf '%s\n' "$candidate"; return 0; fi
    done
    return 1
}

same_name_service_unit_path() {
    local srv="$1" init
    init=$(effective_init_system)
    case "$init" in
        systemd) systemd_same_name_unit_path "$srv" ;;
        openrc) [[ -e "/etc/init.d/${srv}" || -L "/etc/init.d/${srv}" ]] && printf '/etc/init.d/%s\n' "$srv" ;;
        *) return 1 ;;
    esac
}

core_family_paths() {
    local init
    init=$(effective_init_system) || return 1
    case "$init" in
        systemd|openrc) ;;
        *) return 1 ;;
    esac
    case "$1" in
        xray)
            printf '%s\n' /usr/local/bin/xray /usr/local/etc/xray /usr/local/share/xray
            case "$init" in systemd) printf '%s\n' /etc/systemd/system/xray.service ;; openrc) printf '%s\n' /etc/init.d/xray /etc/conf.d/xray ;; esac
            ;;
        sing-box)
            printf '%s\n' /usr/local/bin/sing-box /etc/sing-box
            case "$init" in systemd) printf '%s\n' /etc/systemd/system/sing-box.service ;; openrc) printf '%s\n' /etc/init.d/sing-box /etc/conf.d/sing-box ;; esac
            ;;
        hysteria)
            printf '%s\n' /usr/local/bin/hysteria /etc/hysteria
            case "$init" in systemd) printf '%s\n' /etc/systemd/system/hysteria.service ;; openrc) printf '%s\n' /etc/init.d/hysteria /etc/conf.d/hysteria ;; esac
            ;;
        *) return 1 ;;
    esac
}


record_core_family_ownership() {
    local srv="$1" tmp
    local -a owned_roots=()
    abox_owns_service "$srv" || return 1
    ensure_abox_dir_owned "$ABOX_DIR"
    if [[ -e "$ABOX_CORE_OWNERSHIP" || -L "$ABOX_CORE_OWNERSHIP" ]]; then
        [[ -f "$ABOX_CORE_OWNERSHIP" && ! -L "$ABOX_CORE_OWNERSHIP" ]] || return 1
        [[ "$(stat -c %u:%g "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" == 0:0 ]] || return 1
        [[ "$(stat -c %a "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" =~ ^0?600$ ]] || return 1
        [[ "$(stat -c %s "$ABOX_CORE_OWNERSHIP" 2>/dev/null || echo 99999999)" -le 4194304 ]] || return 1
    fi
    local core_paths=''
    core_paths=$(core_family_paths "$srv") || return 1
    if [[ -n "$core_paths" ]]; then
        mapfile -t owned_roots <<< "$core_paths" || return 1
    fi
    local _root
    for _root in "${owned_roots[@]}"; do
        [[ -e "$_root" || -L "$_root" ]] || continue
        path_tree_has_mountpoint "$_root" && return 1
    done
    tmp=$(umask 077; mktemp "$ABOX_DIR/.managed-core-files.XXXXXX") || return 1
    local runtime_uid runtime_gid _u _g
    IFS=$'\t' read -r _u _g < <(abox_runtime_identity "$srv") || { rm -f -- "$tmp"; return 1; }
    runtime_uid=$(id -u "$_u" 2>/dev/null) || { rm -f -- "$tmp"; return 1; }
    runtime_gid=$(getent group "$_g" 2>/dev/null | awk -F: '{print $3}')
    [[ "$runtime_uid" =~ ^[0-9]+$ && "$runtime_gid" =~ ^[0-9]+$ ]] || { rm -f -- "$tmp"; return 1; }
    python3 - "$srv" "$ABOX_CORE_OWNERSHIP" "$tmp" "$runtime_uid" "$runtime_gid" "${owned_roots[@]}" <<'PY_CORE_RECORD'
import hashlib, os, stat, sys
srv, old_name, out_name, runtime_uid, runtime_gid, *roots = sys.argv[1:]
runtime_uid=int(runtime_uid)
runtime_gid=int(runtime_gid)
old=[]
try:
    st=os.lstat(old_name)
    if not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode) or st.st_uid != 0 or st.st_gid != 0 or st.st_mode & 0o077 or st.st_size > 4*1024*1024:
        raise SystemExit(1)
    with open(old_name, 'r', encoding='utf-8') as f:
        for line in f:
            parts=line.rstrip('\n').split('\t')
            if len(parts)!=4 or parts[0] not in {'F','D'} or not parts[2].startswith('/') or '\x00' in line:
                raise SystemExit(1)
            if parts[1] != srv:
                old.append(parts)
except FileNotFoundError:
    pass
except Exception:
    raise SystemExit(1)
entries=[]

def path_is_mountpoint(path):
    path=os.path.abspath(os.path.normpath(path))
    if os.path.islink(path):
        return False
    try:
        with open('/proc/self/mountinfo','r',encoding='utf-8',errors='strict') as mf:
            for line in mf:
                fields=line.rstrip('\n').split(' ')
                if len(fields) < 5:
                    continue
                mp=__import__('re').sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1),8)), fields[4])
                mp=os.path.abspath(os.path.normpath(mp))
                if mp == path:
                    return True
    except (OSError, UnicodeError):
        raise SystemExit(1)
    return False

def add_path(path):
    try: st=os.lstat(path)
    except FileNotFoundError: return
    if path_is_mountpoint(path):
        raise SystemExit(1)
    acme = srv == 'hysteria' and (path == '/etc/hysteria/acme' or path.startswith('/etc/hysteria/acme/'))
    uid_ok = st.st_uid in ({0, runtime_uid} if acme else {0})
    gid_ok = st.st_gid in ({0, runtime_gid})
    group_write_ok = acme and path == '/etc/hysteria/acme' and st.st_uid == 0 and st.st_gid == runtime_gid and stat.S_ISDIR(st.st_mode)
    if not uid_ok or not gid_ok or stat.S_ISLNK(st.st_mode) or (st.st_mode & 0o002) or ((st.st_mode & 0o020) and not group_write_ok):
        raise SystemExit(1)
    if stat.S_ISREG(st.st_mode):
        if st.st_nlink != 1: raise SystemExit(1)
        h=hashlib.sha256()
        with open(path,'rb') as f:
            for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
        entries.append(['F',srv,path,h.hexdigest()])
    elif stat.S_ISDIR(st.st_mode):
        entries.append(['D',srv,path,'-'])
        try:
            names=sorted(os.listdir(path), key=os.fsencode)
        except OSError:
            raise SystemExit(1)
        for name in names:
            add_path(os.path.join(path,name))
    else:
        raise SystemExit(1)
for root in roots: add_path(root)
all_entries=old+entries
seen=set()
with open(out_name,'w',encoding='utf-8',newline='\n') as f:
    for row in sorted(all_entries,key=lambda r:(r[1],os.fsencode(r[2]))):
        key=(row[0],row[1],row[2])
        if key in seen: raise SystemExit(1)
        seen.add(key)
        f.write('\t'.join(row)+'\n')
    f.flush(); os.fsync(f.fileno())
os.chmod(out_name,0o600)
PY_CORE_RECORD
    local rc=$?
    if (( rc != 0 )); then rm -f -- "$tmp"; return 1; fi
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$ABOX_CORE_OWNERSHIP" || { rm -f -- "$tmp"; return 1; }
}

refresh_dynamic_core_subtree_ownership() {
    local srv="$1" target="$2" tmp
    [[ "$srv" =~ ^(xray|sing-box|hysteria)$ ]] || return 1
    [[ "$target" == /etc/hysteria/acme ]] || return 1
    hysteria_acme_owner_marker_valid "$target/.A-Box-managed" || return 1
    path_tree_has_mountpoint "$target" && return 1
    [[ -f "$ABOX_CORE_OWNERSHIP" && ! -L "$ABOX_CORE_OWNERSHIP" ]] || return 1
    [[ "$(stat -c %u:%g "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" == 0:0 ]] || return 1
    [[ "$(stat -c %a "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" =~ ^0?600$ ]] || return 1
    tmp=$(umask 077; mktemp "$ABOX_DIR/.managed-core-files.dynamic.XXXXXX") || return 1
    python3 - "$srv" "$ABOX_CORE_OWNERSHIP" "$target" "$tmp" <<'PY_DYNAMIC_OWNER'
import hashlib, os, stat, sys
srv, manifest, target, out_name = sys.argv[1:]
try:
    import pwd, grp
    runtime_uid = pwd.getpwnam("abox-hysteria").pw_uid
    runtime_gid = grp.getgrnam("abox-hysteria").gr_gid
except KeyError:
    raise SystemExit(1)

def safe_stat(path):
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return None
    acme = srv == 'hysteria' and (path == target or path.startswith(target + '/'))
    uid_ok = st.st_uid in ({0, runtime_uid} if acme else {0})
    gid_ok = st.st_gid in ({0, runtime_gid})
    legacy_root_dir_ok = acme and path == target and st.st_uid == 0 and st.st_gid == 0 and stat.S_ISDIR(st.st_mode) and (st.st_mode & 0o077) == 0
    group_write_ok = acme and path == target and st.st_uid == 0 and st.st_gid == runtime_gid and stat.S_ISDIR(st.st_mode)
    if not uid_ok or not gid_ok or stat.S_ISLNK(st.st_mode) or (st.st_mode & 0o002) or ((st.st_mode & 0o020) and not group_write_ok) or (acme and path == target and not (group_write_ok or legacy_root_dir_ok)):
        raise SystemExit(1)
    return st

target = target.rstrip('/')
rows=[]
with open(manifest, 'r', encoding='utf-8') as f:
    for line in f:
        p=line.rstrip('\n').split('\t')
        if len(p)!=4 or p[0] not in {'F','D'} or p[1] not in {'xray','sing-box','hysteria'} or not p[2].startswith('/') or '\x00' in line:
            raise SystemExit(1)
        rows.append(p)
if len({(r[0],r[1],r[2]) for r in rows}) != len(rows):
    raise SystemExit(1)
# Only refresh the runtime-owned ACME subtree. Static Hysteria files keep their
# original hashes, so a user edit to config.yaml/certs still fails closed.
rows=[r for r in rows if not (r[1]==srv and (r[2]==target or r[2].startswith(target + '/')))]
entries=[]
mountpoints=set()
try:
    with open('/proc/self/mountinfo','r',encoding='utf-8',errors='strict') as mf:
        for line in mf:
            fields=line.rstrip('\n').split(' ')
            if len(fields) < 5:
                continue
            mp=__import__('re').sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1),8)), fields[4])
            mountpoints.add(os.path.abspath(os.path.normpath(mp)))
except (OSError, UnicodeError):
    raise SystemExit(1)

def is_mountpoint(path):
    return os.path.abspath(os.path.normpath(path)) in mountpoints

try:
    st=safe_stat(target)
except FileNotFoundError:
    st=None
if st is not None:
    if not stat.S_ISDIR(st.st_mode) or is_mountpoint(target):
        raise SystemExit(1)
    def add(path):
        st=safe_stat(path)
        if st is None: raise SystemExit(1)
        if stat.S_ISREG(st.st_mode):
            if st.st_nlink != 1: raise SystemExit(1)
            h=hashlib.sha256()
            with open(path,'rb') as f:
                for chunk in iter(lambda:f.read(1024*1024), b''): h.update(chunk)
            entries.append(['F',srv,path,h.hexdigest()])
        elif stat.S_ISDIR(st.st_mode):
            if is_mountpoint(path): raise SystemExit(1)
            entries.append(['D',srv,path,'-'])
            for name in sorted(os.listdir(path), key=os.fsencode):
                add(os.path.join(path,name))
        else:
            raise SystemExit(1)
    add(target)
rows.extend(entries)
seen=set()
with open(out_name,'w',encoding='utf-8',newline='\n') as f:
    for row in sorted(rows,key=lambda r:(r[1],os.fsencode(r[2]))):
        key=(row[0],row[1],row[2])
        if key in seen: raise SystemExit(1)
        seen.add(key)
        f.write('\t'.join(row)+'\n')
    f.flush(); os.fsync(f.fileno())
os.chmod(out_name,0o600)
PY_DYNAMIC_OWNER
    local rc=$?
    if (( rc != 0 )); then rm -f -- "$tmp"; return 1; fi
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$ABOX_CORE_OWNERSHIP" || { rm -f -- "$tmp"; return 1; }
}

hysteria_acme_owner_marker_valid() {
    local marker="${1:-$HY2_ACME_OWNER_MARKER}"
    [[ -f "$marker" && ! -L "$marker" ]] || return 1
    path_owned_by_root "$marker" || return 1
    path_mode_has_no_group_other_write "$marker" || return 1
    grep -Fxq 'A-Box managed Hysteria ACME directory v1' "$marker" 2>/dev/null
}

mark_hysteria_acme_dir_managed() {
    local dir="${1:-/etc/hysteria/acme}" marker="${2:-$HY2_ACME_OWNER_MARKER}" tmp
    [[ "$dir" == /etc/hysteria/acme ]] || return 1
    [[ "$marker" == "$dir/.A-Box-managed" ]] || return 1
    [[ -d "$dir" && ! -L "$dir" ]] || return 1
    hysteria_acme_dir_runtime_permissions_valid "$dir" || return 1
    if [[ -e "$marker" || -L "$marker" ]]; then
        hysteria_acme_owner_marker_valid "$marker"
        return
    fi
    tmp=$(umask 077; mktemp "$dir/.A-Box-managed.XXXXXX") || return 1
    printf '%s\n' 'A-Box managed Hysteria ACME directory v1' > "$tmp" || { rm -f "$tmp"; return 1; }
    chown root:root "$tmp" || { rm -f "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f "$tmp"; return 1; }
    mv -f "$tmp" "$marker" || { rm -f "$tmp"; return 1; }
    hysteria_acme_owner_marker_valid "$marker"
}

hysteria_acme_current_tree_matches_manifest() {
    local manifest="${1:-$ABOX_CORE_OWNERSHIP}" target="${2:-/etc/hysteria/acme}"
    [[ "$target" == /etc/hysteria/acme ]] || return 1
    path_tree_has_mountpoint "$target" && return 1
    [[ -f "$manifest" && ! -L "$manifest" ]] || return 1
    python3 - "$manifest" "$target" <<'PY_ACME_MATCH'
import hashlib, os, stat, sys
manifest, target = sys.argv[1:]
try:
    import pwd, grp
    runtime_uid = pwd.getpwnam("abox-hysteria").pw_uid
    runtime_gid = grp.getgrnam("abox-hysteria").gr_gid
except KeyError:
    raise SystemExit(1)
rows=[]
with open(manifest,'r',encoding='utf-8') as f:
    for line in f:
        p=line.rstrip('\n').split('\t')
        if len(p)!=4 or p[0] not in {'F','D'} or p[1] != 'hysteria' or not p[2].startswith('/') or '\x00' in line:
            continue
        rows.append(p)
recorded={r[2]:(r[0],r[3]) for r in rows if r[2]==target or r[2].startswith(target+'/')}
if recorded.get(target,('', ''))[0] != 'D':
    raise SystemExit(1)
def check(path):
    try: st=os.lstat(path)
    except FileNotFoundError: raise SystemExit(1)
    acme = path == target or path.startswith(target + '/')
    uid_ok = st.st_uid in ({0, runtime_uid} if acme else {0})
    gid_ok = st.st_gid in ({0, runtime_gid})
    legacy_root_dir_ok = acme and path == target and st.st_uid == 0 and st.st_gid == 0 and stat.S_ISDIR(st.st_mode) and (st.st_mode & 0o077) == 0
    group_write_ok = acme and path == target and st.st_uid == 0 and st.st_gid == runtime_gid and stat.S_ISDIR(st.st_mode)
    if not uid_ok or not gid_ok or stat.S_ISLNK(st.st_mode) or (st.st_mode & 0o002) or ((st.st_mode & 0o020) and not group_write_ok) or (acme and path == target and not (group_write_ok or legacy_root_dir_ok)):
        raise SystemExit(1)
    rec=recorded.get(path)
    if rec is None: raise SystemExit(1)
    typ,_=rec
    if stat.S_ISDIR(st.st_mode):
        if typ!='D': raise SystemExit(1)
        for name in sorted(os.listdir(path), key=os.fsencode):
            check(os.path.join(path,name))
    elif stat.S_ISREG(st.st_mode):
        if typ!='F' or st.st_nlink != 1: raise SystemExit(1)
        h=hashlib.sha256()
        with open(path,'rb') as f:
            for chunk in iter(lambda:f.read(1024*1024), b''): h.update(chunk)
        if h.hexdigest() != rec[1]: raise SystemExit(1)
    else:
        raise SystemExit(1)
check(target)
# No recorded file below the subtree may disappear from the current tree.
for path,(typ,_) in recorded.items():
    if path==target: continue
    if not os.path.lexists(path): raise SystemExit(1)
raise SystemExit(0)
PY_ACME_MATCH
}

hysteria_acme_dir_runtime_permissions_valid() {
    local dir="${1:-/etc/hysteria/acme}" user group uid gid mode nlink
    [[ "$dir" == /etc/hysteria/acme && -d "$dir" && ! -L "$dir" ]] || return 1
    IFS=$'\t' read -r user group < <(abox_runtime_identity hysteria) || return 1
    uid=$(id -u "$user" 2>/dev/null) || return 1
    gid=$(getent group "$group" 2>/dev/null | awk -F: '{print $3}')
    [[ "$uid" =~ ^[0-9]+$ && "$gid" =~ ^[0-9]+$ ]] || return 1
    [[ "$(stat -c %u:%g "$dir" 2>/dev/null || true)" == "0:$gid" ]] || return 1
    mode=$(stat -c %a "$dir" 2>/dev/null) || return 1
    nlink=$(stat -c %h "$dir" 2>/dev/null) || return 1
    # R-01: Accept 1770 (sticky bit) as well as 770.
    [[ "$nlink" =~ ^[1-9][0-9]*$ && "$mode" =~ ^0?1?770$ ]] || return 1
    return 0
}

prepare_hysteria_acme_dir_ownership() {
    local dir=/etc/hysteria/acme marker=$HY2_ACME_OWNER_MARKER user group
    IFS=$'\t' read -r user group < <(abox_runtime_identity hysteria) || return 1
    ensure_abox_runtime_identity hysteria || return 1
    path_parent_chain_safe "$dir/.A-Box-managed" || return 1
    [[ ! -L /etc/hysteria && (! -e /etc/hysteria || -d /etc/hysteria) ]] || return 1
    if [[ -e "$dir" || -L "$dir" ]]; then
        [[ ! -L "$dir" && -d "$dir" ]] || return 1
        if ! hysteria_acme_owner_marker_valid "$marker" && ! hysteria_acme_current_tree_matches_manifest "$ABOX_CORE_OWNERSHIP" "$dir"; then
            return 1
        fi
        chown "root:$group" "$dir" || return 1
        # A-03: Sticky bit (1770) prevents group members from deleting/replacing others' files (TOCTOU).
        chmod 1770 "$dir" || return 1
        hysteria_acme_dir_runtime_permissions_valid "$dir" || return 1
        mark_hysteria_acme_dir_managed "$dir" "$marker" || return 1
        return 0
    fi
    # R-01-FIX: Parent 750, acme dir 1770 (sticky). Fresh-dir was still 770.
    install -d -o root -g "$group" -m 750 /etc/hysteria || return 1
    install -d -o root -g "$group" -m 1770 "$dir" || return 1
    hysteria_acme_dir_runtime_permissions_valid "$dir" || return 1
    mark_hysteria_acme_dir_managed "$dir" "$marker" || return 1
    return 0
}

remove_recorded_core_family() {
    local srv="$1" runtime_uid runtime_gid
    [[ -f "$ABOX_CORE_OWNERSHIP" && ! -L "$ABOX_CORE_OWNERSHIP" ]] || return 2
    [[ "$(stat -c %u:%g "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" == 0:0 ]] || return 1
    [[ "$(stat -c %a "$ABOX_CORE_OWNERSHIP" 2>/dev/null || true)" =~ ^0?600$ ]] || return 1
    [[ "$(stat -c %s "$ABOX_CORE_OWNERSHIP" 2>/dev/null || echo 99999999)" -le 4194304 ]] || return 1
    local _u _g
    IFS=$'\t' read -r _u _g < <(abox_runtime_identity "$srv") || return 1
    runtime_uid=$(id -u "$_u" 2>/dev/null) || return 1
    runtime_gid=$(getent group "$_g" 2>/dev/null | awk -F: '{print $3}')
    [[ "$runtime_uid" =~ ^[0-9]+$ && "$runtime_gid" =~ ^[0-9]+$ ]] || return 1
    python3 - "$srv" "$ABOX_CORE_OWNERSHIP" "$runtime_uid" "$runtime_gid" <<'PY_CORE_REMOVE'
import hashlib, os, re, stat, sys, tempfile
srv, manifest, runtime_uid, runtime_gid=sys.argv[1:]
runtime_uid=int(runtime_uid)
runtime_gid=int(runtime_gid)
rows=[]; keep=[]; all_rows=[]
with open(manifest,'r',encoding='utf-8') as f:
    for line in f:
        p=line.rstrip('\n').split('\t')
        if len(p)!=4 or p[0] not in {'F','D'} or not p[2].startswith('/') or '\x00' in line:
            raise SystemExit(1)
        all_rows.append(p)
        (rows if p[1]==srv else keep).append(p)
if not rows: raise SystemExit(2)
if len({(r[0],r[1],r[2]) for r in all_rows}) != len(all_rows): raise SystemExit(1)
files={r[2]:r[3] for r in rows if r[0]=='F'}
dirs={r[2] for r in rows if r[0]=='D'}
expected=set(files)|dirs
# Complete fail-closed preflight before deleting anything. Every actual entry
# below a recorded directory must itself be recorded, correctly typed, root
# owned, non-link, non-writable by group/other, and (for files) hash-identical.
for path in sorted(expected, key=os.fsencode):
    try: st=os.lstat(path)
    except FileNotFoundError: continue
    def is_mountpoint(path):
        path = os.path.abspath(os.path.normpath(path))
        if os.path.islink(path):
            return False
        try:
            with open('/proc/self/mountinfo', 'r', encoding='utf-8', errors='strict') as mf:
                for line in mf:
                    fields = line.rstrip('\n').split(' ')
                    if len(fields) < 5:
                        continue
                    mp = re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), fields[4])
                    mp = os.path.abspath(os.path.normpath(mp))
                    if mp == path:
                        return True
        except (OSError, UnicodeError):
            # mountinfo is authoritative for this destructive operation.
            # If it cannot be read, the caller cannot prove the path is not
            # mounted; fail closed instead of using the weaker ismount().
            raise SystemExit(4)
        return False
    if is_mountpoint(path):
        raise SystemExit(3)
    acme = srv == 'hysteria' and (path == '/etc/hysteria/acme' or path.startswith('/etc/hysteria/acme/'))
    uid_ok = st.st_uid in ({0} if not acme else {0, runtime_uid})
    gid_ok = st.st_gid in ({0, runtime_gid})
    group_write_ok = acme and path == '/etc/hysteria/acme' and st.st_uid == 0 and st.st_gid == runtime_gid and stat.S_ISDIR(st.st_mode)
    if not uid_ok or not gid_ok or stat.S_ISLNK(st.st_mode) or (st.st_mode & 0o002) or ((st.st_mode & 0o020) and not group_write_ok):
        raise SystemExit(3)
    if path in files:
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1: raise SystemExit(3)
        h=hashlib.sha256()
        try:
            with open(path,'rb') as f:
                for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
        except OSError: raise SystemExit(3)
        if h.hexdigest()!=files[path]: raise SystemExit(3)
    else:
        if not stat.S_ISDIR(st.st_mode): raise SystemExit(3)
        try: names=os.listdir(path)
        except OSError: raise SystemExit(3)
        for name in names:
            child=os.path.join(path,name)
            if child not in expected: raise SystemExit(3)
# Only after the complete tree is proven exact may deletion begin.
for path in sorted(files, key=lambda p:(p.count(os.sep),len(p)), reverse=True):
    try: os.unlink(path)
    except FileNotFoundError: pass
    except OSError: raise SystemExit(1)
for path in sorted(dirs, key=lambda p:(p.count(os.sep),len(p)), reverse=True):
    try: os.rmdir(path)
    except FileNotFoundError: pass
    except OSError: raise SystemExit(1)
dirname=os.path.dirname(manifest)
fd,tmp=tempfile.mkstemp(prefix='.managed-core-files.',dir=dirname,text=True)
try:
    with os.fdopen(fd,'w',encoding='utf-8',newline='\n') as f:
        for row in keep: f.write('\t'.join(row)+'\n')
        f.flush(); os.fsync(f.fileno())
    os.chmod(tmp,0o600); os.chown(tmp,0,0); os.replace(tmp,manifest)
except Exception:
    try: os.unlink(tmp)
    except OSError: pass
    raise
PY_CORE_REMOVE
}

managed_auxiliary_paths() {
    printf '%s\n' \
        /usr/local/bin/sb \
        /etc/logrotate.d/A-Box \
        /etc/fail2ban/filter.d/A-Box.conf \
        /etc/fail2ban/jail.d/A-Box.local \
        /etc/sysctl.d/99-A-Box-tune.conf \
        /etc/security/limits.d/A-Box.conf \
        /etc/modules-load.d/A-Box-bbr.conf \
        /etc/systemd/system/A-Box-firewall.service \
        /etc/init.d/A-Box-firewall
}

auxiliary_content_is_abox_managed() {
    local file="$1" logical_path="$2"
    [[ -f "$file" && ! -L "$file" ]] || return 1
    if [[ "$logical_path" == /usr/local/bin/sb ]]; then
        grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null && return 0
        grep -Fq 'exec bash /etc/ddr/A-Box.sh "$@"' "$file" 2>/dev/null || return 1
        grep -Fq 'exec sudo bash /etc/ddr/A-Box.sh "$@"' "$file" 2>/dev/null || return 1
        return 0
    fi
    grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null && return 0
    # Path-specific legacy fingerprints allow a one-time migration. New files
    # always carry the exact marker above.
    case "$logical_path" in
        /etc/logrotate.d/A-Box)
            grep -Fq '/var/log/A-Box-*.log' "$file" && grep -Fq 'copytruncate' "$file"
            ;;
        /etc/fail2ban/filter.d/A-Box.conf)
            grep -Fq '[Definition]' "$file" && grep -Fq 'message authentication failed' "$file"
            ;;
        /etc/fail2ban/jail.d/A-Box.local)
            grep -Eq '^\[A-Box-(tcp|udp)\]$' "$file" && grep -Fq 'filter = A-Box' "$file"
            ;;
        /etc/sysctl.d/99-A-Box-tune.conf)
            grep -Eq '^fs\.file-max[[:space:]]*=' "$file" && grep -Eq '^net\.ipv4\.tcp_syncookies[[:space:]]*=' "$file"
            ;;
        /etc/security/limits.d/A-Box.conf)
            grep -Fxq '* soft nofile 1048576' "$file" && grep -Fxq 'root hard nofile 1048576' "$file"
            ;;
        /etc/systemd/system/A-Box-firewall.service|/etc/init.d/A-Box-firewall)
            grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null
            ;;
        /etc/ddr/traffic_monitor.sh)
            grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null && grep -Fq 'TRAFFIC_LIMIT_GB' "$file" 2>/dev/null && grep -Fq 'month_bytes()' "$file" 2>/dev/null
            ;;
        /etc/ddr/geo_update.sh)
            grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null && grep -Fq 'Geo' "$file" 2>/dev/null && (grep -Fq 'update_geo_ownership' "$file" 2>/dev/null || grep -Fq 'refresh_dynamic_core_subtree_ownership' "$file" 2>/dev/null)
            ;;
        /etc/ddr/socket_probe.sh)
            grep -Fxq '# Managed by A-Box' "$file" 2>/dev/null && grep -Fq '/run/A-Box-socket-probe.lock' "$file" 2>/dev/null && grep -Fq 'socket_owned_by_pid' "$file" 2>/dev/null
            ;;
        *) return 1 ;;
    esac
}

auxiliary_path_is_abox_managed() {
    auxiliary_content_is_abox_managed "$1" "$1"
}

assert_abox_auxiliary_safe() {
    local path="$1"
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
    auxiliary_path_is_abox_managed "$path" && return 0
    # B2-01: return 1 (not die) so callers with cleanup handlers
    # (e.g. tx_dir removal) actually run; bare callers must add || die.
    return 1
}

remove_owned_auxiliary_path() {
    local path="$1"
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
    auxiliary_path_is_abox_managed "$path" || return 0
    path_tree_has_mountpoint "$path" && return 1
    rm -rf -- "$path" || return 1
    [[ ! -e "$path" && ! -L "$path" ]]
}


prune_owned_core_families_except() {
    local allowed=" $* " srv
    for srv in xray sing-box hysteria; do
        [[ "$allowed" == *" $srv "* ]] && continue
        { abox_owns_service "$srv" || abox_owns_config_only_core_dir "$srv"; } || continue
        stop_abox_service "$srv" || die "$(tprintf pr_stop "$srv")"
        remove_owned_core_family "$srv" || die "$(tprintf pr_remove "$srv")"
    done
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        systemctl daemon-reload >/dev/null 2>&1 || die "$(tr_msg pr_reload)"
    fi
}

abox_owns_config_only_core_dir() {
    local srv="$1" cfg_dir='' bin='' _u='' _g='' _gid=''
    same_name_service_unit_path "$srv" >/dev/null 2>&1 && return 1
    case "$srv" in
        xray) cfg_dir=/usr/local/etc/xray; bin=/usr/local/bin/xray ;;
        sing-box) cfg_dir=/etc/sing-box; bin=/usr/local/bin/sing-box ;;
        hysteria) cfg_dir=/etc/hysteria; bin=/usr/local/bin/hysteria ;;
        *) return 1 ;;
    esac
    [[ ! -e "$bin" && ! -L "$bin" && -d "$cfg_dir" && ! -L "$cfg_dir" ]] || return 1
    IFS=$'\t' read -r _u _g < <(abox_runtime_identity "$srv" 2>/dev/null) || return 1
    _gid=$(getent group "$_g" 2>/dev/null | awk -F: '{print $3}')
    [[ -n "$_gid" && "$(stat -c %u:%g "$cfg_dir" 2>/dev/null || true)" == "0:$_gid" ]]
}

list_foreign_core_conflicts() {
    local srv path unit key core_paths=''
    local -A seen=()
    for srv in "$@"; do
        { abox_owns_service "$srv" || abox_owns_config_only_core_dir "$srv"; } && continue
        unit=$(same_name_service_unit_path "$srv" 2>/dev/null || true)
        if [[ -n "$unit" ]]; then
            key="${srv}|${unit}"
            if [[ -z "${seen[$key]:-}" ]]; then printf '%s|%s\n' "$srv" "$unit"; seen[$key]=1; fi
        fi
        core_paths=$(core_family_paths "$srv") || return 1
        while IFS= read -r path; do
            [[ -e "$path" || -L "$path" ]] || continue
            key="${srv}|${path}"
            [[ -n "${seen[$key]:-}" ]] && continue
            printf '%s|%s\n' "$srv" "$path"
            seen[$key]=1
        done <<< "$core_paths"
    done
}

assert_no_foreign_core_conflicts() {
    local conflicts
    conflicts=$(list_foreign_core_conflicts "$@") || die "$(tr_msg af_enum)"
    [[ -z "$conflicts" ]] && return 0
    msg "${RED}[!] Refusing to overwrite non-A-Box core files/services:${NC}"
    while IFS='|' read -r srv path; do [[ -n "$path" ]] && msg "${RED}    ${srv}: ${path}${NC}"; done <<< "$conflicts"
    die "$(tr_msg af_migrate)"
}

# Legacy residue check: the core's unit file and config dir are
# already gone (an earlier cleanup removed them together with the
# ownership proof) and only the binary remains at the canonical
# path. Such a binary is inert - no working foreign install keeps
# its binary while losing both its unit and its config dir.
core_family_binary_orphaned() {
    local srv="$1" cfg_dir='' bin='' unit=''
    case "$srv" in
        xray) cfg_dir=/usr/local/etc/xray; bin=/usr/local/bin/xray ;;
        sing-box) cfg_dir=/etc/sing-box; bin=/usr/local/bin/sing-box ;;
        hysteria) cfg_dir=/etc/hysteria; bin=/usr/local/bin/hysteria ;;
        *) return 1 ;;
    esac
    [[ -x "$bin" && ! -L "$bin" ]] || return 1
    [[ ! -e "$cfg_dir" && ! -L "$cfg_dir" ]] || return 1
    unit=$(service_unit_path "$srv" 2>/dev/null || true)
    [[ -z "$unit" || ( ! -e "$unit" && ! -L "$unit" ) ]]
}

remove_owned_core_family() {
    # $2 force_heal: only explicit callers (menu 17 / full uninstall) may pass 1.
    # Ambient ABOX_HEAL_MISSING_MANIFEST from the environment is never consulted.
    local srv="$1" force_heal="${2:-0}" path rc core_paths=''
    if ! abox_owns_service "$srv"; then
        if abox_owns_config_only_core_dir "$srv"; then
            remove_core_family_force "$srv" || return 1
            return 0
        fi
        if [[ "$force_heal" == 1 ]] && core_family_binary_orphaned "$srv"; then
            msg "${YELLOW}[!] ${srv} 仅剩无归属记录的二进制残留（旧版本安装、归属凭据已被先前清理删除），按显式清理流程强制移除。${NC}"
            remove_core_family_force "$srv" || return 1
            return 0
        fi
        core_paths=$(core_family_paths "$srv") || return 1
        while IFS= read -r path; do [[ -e "$path" || -L "$path" ]] && msg "${YELLOW}[!] Skip non-A-Box path: ${path}${NC}"; done <<< "$core_paths"
        return 0
    fi
    if [[ "$srv" == hysteria && -d /etc/hysteria/acme && ! -L /etc/hysteria/acme ]]; then
        if hysteria_acme_owner_marker_valid /etc/hysteria/acme/.A-Box-managed || hysteria_acme_current_tree_matches_manifest "$ABOX_CORE_OWNERSHIP" /etc/hysteria/acme; then
            prepare_hysteria_acme_dir_ownership || return 1
            refresh_dynamic_core_subtree_ownership hysteria /etc/hysteria/acme || return 1
        fi
    fi
    remove_recorded_core_family "$srv"; rc=$?
    case "$rc" in
        0) return 0 ;;
        2)
            if [[ "$force_heal" == 1 ]]; then
                msg "${YELLOW}[!] No per-file ownership manifest for ${srv}; performing unit-proven force heal of known core-family paths.${NC}"
                remove_core_family_force "$srv" || return 1
                return 0
            fi
            msg "${YELLOW}[!] No per-file ownership manifest exists for ${srv}; refusing destructive family deletion. Start/restart the managed service once to register exact files.${NC}"
            return 1
            ;;
        3)
            msg "${RED}[!] One or more ${srv} files changed after ownership registration; they were preserved instead of being deleted.${NC}"
            return 1
            ;;
        *) return 1 ;;
    esac
}

remove_all_owned_core_families() {
    # $1 force_heal forwarded to each family (1 = menu 17 / full uninstall only).
    local force_heal="${1:-0}" failed=0
    remove_owned_core_family xray "$force_heal" || failed=1
    remove_owned_core_family sing-box "$force_heal" || failed=1
    remove_owned_core_family hysteria "$force_heal" || failed=1
    (( failed == 0 ))
}


shortcut_is_abox_managed() {
    local path="${1:-/usr/local/bin/sb}"
    auxiliary_content_is_abox_managed "$path" /usr/local/bin/sb
}

assert_abox_shortcut_safe() {
    local path="${1:-/usr/local/bin/sb}"
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
    shortcut_is_abox_managed "$path" && return 0
    die "$(tprintf sc_refuse "$path")"
}

remove_abox_shortcut() {
    local path="${1:-/usr/local/bin/sb}"
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
    if shortcut_is_abox_managed "$path"; then
        path_tree_has_mountpoint "$path" && { msg "${RED}[!] Refusing to remove mounted A-Box shortcut: ${path}${NC}"; return 1; }
        rm -f -- "$path"
    else
        msg "${YELLOW}[!] Skip non-A-Box shortcut: ${path}${NC}"
    fi
}

stop_abox_service() {
    local srv="$1"
    if abox_owns_service "$srv"; then
        service_manager stop "$srv"
    else
        msg "${YELLOW}[!] Skip non-A-Box service: ${srv}${NC}"
        return 0
    fi
}

stop_all_managed_services() {
    local failed=0
    stop_abox_service xray || failed=1
    stop_abox_service sing-box || failed=1
    stop_abox_service hysteria || failed=1
    kill_managed_residual_pids >/dev/null 2>&1 || failed=1
    (( failed == 0 ))
}

managed_service_pid() {
    local srv="$1" pid='' pidfile='' exe='' owner mode nlink
    if [[ "${INIT_SYS:-}" == 'systemd' ]] && systemd_available; then
        pid=$(systemctl show -p MainPID --value "$srv" 2>/dev/null || true)
        [[ "$pid" =~ ^[0-9]+$ && "$pid" -gt 1 ]] && printf '%s\n' "$pid"
    elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then
        case "$srv" in
            xray) pidfile=/run/xray.pid; exe=/usr/local/bin/xray ;;
            sing-box) pidfile=/run/sing-box.pid; exe=/usr/local/bin/sing-box ;;
            hysteria) pidfile=/run/hysteria.pid; exe=/usr/local/bin/hysteria ;;
            *) return 1 ;;
        esac
        [[ -f "$pidfile" && ! -L "$pidfile" ]] || return 1
        [[ "$(stat -c %h "$pidfile" 2>/dev/null)" == 1 ]] || return 1
        owner=$(stat -c %u "$pidfile" 2>/dev/null) || return 1
        [[ "$owner" == 0 ]] || return 1
        mode=$(stat -c %a "$pidfile" 2>/dev/null) || return 1
        [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#022) == 0 )) || return 1
        pid=$(tr -d '[:space:]' < "$pidfile" 2>/dev/null) || return 1
        [[ "$pid" =~ ^[1-9][0-9]*$ && "$pid" -gt 1 ]] || return 1
        pid_exe_matches "$pid" "$exe" || return 1
        printf '%s\n' "$pid"
    fi
}


pid_exe_matches() {
    local pid="$1" expect="$2" exe
    [[ "$pid" =~ ^[0-9]+$ && "$pid" -gt 1 ]] || return 1
    exe=$(readlink -f "/proc/$pid/exe" 2>/dev/null || true)
    [[ "$exe" == "$expect" ]]
}

kill_managed_residual_pids() {
    local srv pid exe failed=0 i
    local -a pids=() exes=()
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        pid=$(managed_service_pid "$srv" 2>/dev/null || true)
        pid=${pid%%$'\n'*}
        [[ "$pid" =~ ^[1-9][0-9]*$ && "$pid" -gt 1 ]] || continue
        case "$srv" in
            xray) exe='/usr/local/bin/xray' ;;
            sing-box) exe='/usr/local/bin/sing-box' ;;
            hysteria) exe='/usr/local/bin/hysteria' ;;
            *) continue ;;
        esac
        pid_exe_matches "$pid" "$exe" || continue
        pids+=("$pid")
        exes+=("$exe")
    done

    (( ${#pids[@]} == 0 )) && return 0

    # Broadcast TERM to the whole managed set before waiting. This avoids the
    # previous serial 1s + optional 1s wait per process.
    for pid in "${pids[@]}"; do
        kill -TERM "$pid" 2>/dev/null || true
    done
    sleep 1

    # Re-check executable identity before escalating. Numeric PID reuse must
    # never turn an A-Box cleanup into a kill of an unrelated process.
    for i in "${!pids[@]}"; do
        pid="${pids[i]}"
        exe="${exes[i]}"
        if kill -0 "$pid" 2>/dev/null && pid_exe_matches "$pid" "$exe"; then
            kill -KILL "$pid" 2>/dev/null || failed=1
        fi
    done

    # Final fail-closed check: only a still-matching managed executable is a
    # cleanup failure. A reused PID belonging to another process is ignored.
    for i in "${!pids[@]}"; do
        pid="${pids[i]}"
        exe="${exes[i]}"
        if kill -0 "$pid" 2>/dev/null && pid_exe_matches "$pid" "$exe"; then
            failed=1
        fi
    done
    return "$failed"
}

is_service_running() {
    local srv=$1 state
    state=$(service_active_state_value "$srv") || return 1
    [[ "$state" == 1 ]]
}

build_status_str() {
    local status_str='' srv state unknown=0 batch_out
    # Perf 2026-10-14: single systemctl call instead of 3x per refresh
    batch_out=$(service_active_states_batch xray sing-box hysteria 2>/dev/null) || batch_out=""
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        # Try batch result first, fall back to single query
        state=$(grep "^${srv}:" <<< "$batch_out" | cut -d: -f2)
        if [[ -z "$state" ]]; then
            if state=$(service_active_state_value "$srv" 2>/dev/null); then
                : # got it
            else
                unknown=1
                continue
            fi
        fi
        case "$state" in
            1)
                case "$srv" in xray) status_str+="${GREEN}Xray${NC} ";; sing-box) status_str+="${CYAN}Sing-Box${NC} ";; hysteria) status_str+="${GREEN}Hy2${NC} ";; esac
                ;;
            0) ;;
            *) unknown=1 ;;
        esac
    done
    # Menu target look (2026-10-19): stack-state words follow UI language.
    local _w_stopped _w_unknown _w_svc_unknown
    case "${ABOX_LANG:-zh}" in
        en)    _w_stopped='Stopped';              _w_unknown='State Unknown';          _w_svc_unknown='Service State Unknown' ;;
        ru)    _w_stopped='Остановлен';            _w_unknown='Состояние неизвестно';   _w_svc_unknown='Состояние служб неизвестно' ;;
        fa)    _w_stopped='متوقف';                 _w_unknown='وضعیت نامشخص';            _w_svc_unknown='وضعیت سرویس نامشخص' ;;
        zh-tw) _w_stopped='已停止';                _w_unknown='狀態未知';                _w_svc_unknown='服務狀態未知' ;;
        ja)    _w_stopped='停止中';                _w_unknown='状態不明';                _w_svc_unknown='サービス状態不明' ;;
        *)     _w_stopped='已停止';                _w_unknown='状态未知';                _w_svc_unknown='服务状态未知' ;;
    esac
    if [[ -n "$status_str" ]]; then
        (( unknown == 1 )) && status_str+="${YELLOW}${_w_unknown}${NC} "
    elif (( unknown == 1 )); then
        status_str="${YELLOW}${_w_svc_unknown}${NC}"
    else
        status_str="${RED}${_w_stopped}${NC}"
    fi
    printf '%s' "$status_str"
}

managed_services_active() {
    local srv state unknown=0
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        if state=$(service_active_state_value "$srv" 2>/dev/null); then
            [[ "$state" == '1' ]] && return 0
        else
            unknown=1
        fi
    done
    (( unknown == 0 )) && return 1
    return 2
}


deployment_evidence_exists() {
    [[ -s /usr/local/etc/xray/config.json ]] && return 0
    [[ -s /etc/sing-box/config.json ]] && return 0
    [[ -s /etc/hysteria/config.yaml ]] && return 0
    local _d="${ABOX_DIR:-/etc/ddr}"
    [[ -d "$_d/standalone-links.d" ]] && [[ -n "$(ls -A "$_d/standalone-links.d" 2>/dev/null)" ]] && return 0
    [[ -d "$_d/users.d" ]] && [[ -n "$(ls -A "$_d/users.d" 2>/dev/null)" ]] && return 0
    return 1
}

confirm_deployment_replacement() {
    local next_core="$1" next_mode="$2" answer current="none" active_rc=1
    [[ -n "${CORE:-}" || -n "${MODE:-}" ]] && current="${CORE:-unknown}-${MODE:-unknown}"
    if [[ "$current" == 'none' ]]; then
        # Do not trust ambient globals alone: reload the recorded
        # deployment from .env before deciding this host is fresh.
        load_abox_env "$ABOX_ENV" >/dev/null 2>&1 || true
        [[ -n "${CORE:-}" || -n "${MODE:-}" ]] && current="${CORE:-unknown}-${MODE:-unknown}"
    fi
    if [[ "$current" == 'none' ]]; then
        managed_services_active
        active_rc=$?
        case $active_rc in
            1)
                # No live services. Silent only when the disk also
                # shows no deployment; existing configs, links or
                # user registries always earn a prompt - a stopped
                # or misprobed stack must never be wiped silently.
                if deployment_evidence_exists; then
                    current="$(tr_msg dp_existing)"
                else
                    if abox_is_fast || [[ "${ABOX_QUICK_DEPLOY:-0}" == '1' ]]; then
                        msg "${YELLOW}$(tr_msg dp_fast_skip)${NC}"
                    fi
                    return 0
                fi
                ;;
            0|2) current="$(tr_msg dp_existing)" ;;
            *) return 1 ;;
        esac
    fi
    msg "${YELLOW}[!] $(tr_msg dp_stop_warn)${NC}"
    msg "$(tprintf dp_current "$current" "${next_core}-${next_mode}")"
    # Critical when replacing existing config/services: never auto-yes in fast mode.
    read -r -p "$(tr_msg dp_continue)" answer
    is_yes "$answer" || die "$(tr_msg dp_cancelled)"
}

service_report_state() {
    local srv="$1" unit state
    if abox_owns_service "$srv"; then
        if state=$(service_active_state_value "$srv" 2>/dev/null); then
            case "$state" in
                1) printf 'active\n' ;;
                0) printf 'inactive\n' ;;
                *) printf 'unknown\n' ;;
            esac
        else
            printf 'unknown\n'
        fi
        return 0
    fi
    unit=$(same_name_service_unit_path "$srv" 2>/dev/null || true)
    if [[ -n "$unit" ]]; then printf 'foreign/unmanaged\n'; else printf 'absent\n'; fi
}

show_status_report() {
    local init='unknown' xray_state sing_state hy2_state shortcut_state='missing' desired='UNINITIALIZED' period='' config_loaded=0
    local _status_lock_held=0
    # Best-effort non-blocking exclusive snapshot lock; proceed unlocked if busy.
    if [[ ${EUID:-0} -eq 0 ]] && command -v flock >/dev/null 2>&1 && [[ -f "$LOCK_FILE" && ! -L "$LOCK_FILE" ]]; then
        exec 8>>"$LOCK_FILE" 2>/dev/null || true
        # Shared advisory snapshot; does not block writers that hold exclusive fd 9.
        if flock -s -n 8 2>/dev/null; then _status_lock_held=1; fi
    fi
    clear_abox_env_vars
    if load_abox_env "$ABOX_ENV" 2>/dev/null; then config_loaded=1; fi
    if systemd_available; then INIT_SYS='systemd'; init='systemd'; elif command -v rc-service >/dev/null 2>&1; then INIT_SYS='openrc'; init='openrc'; fi
    xray_state=$(service_report_state xray)
    sing_state=$(service_report_state sing-box)
    hy2_state=$(service_report_state hysteria)
    if [[ -e /usr/local/bin/sb || -L /usr/local/bin/sb ]]; then
        if shortcut_is_abox_managed /usr/local/bin/sb; then shortcut_state='managed'; else shortcut_state='foreign/unmanaged'; fi
    fi
    if (( config_loaded == 1 )) || [[ -e "$ABOX_DESIRED_STATE" || -L "$ABOX_DESIRED_STATE" ]] || abox_owns_service xray || abox_owns_service sing-box || abox_owns_service hysteria; then
        desired=$(get_desired_state 2>/dev/null || printf 'invalid')
    fi
    period=$(get_traffic_block_period 2>/dev/null || true)
    cat <<EOF_STATUS
A-Box status
Build: ${ABOX_BUILD} (${ABOX_BUILD_EPOCH})
IP preference: $(read_ip_pref 2>/dev/null || echo dual)
Init: ${init}
Config: CORE=${CORE:-} MODE=${MODE:-}
Desired state: ${desired}${period:+ (traffic period ${period})}
Services: xray=${xray_state} sing-box=${sing_state} hysteria=${hy2_state}
Shortcut: /usr/local/bin/sb=${shortcut_state}
Config file: ${ABOX_ENV}
EOF_STATUS
    if (( _status_lock_held == 1 )); then
        flock -u 8 2>/dev/null || true
        eval "exec 8>&-" 2>/dev/null || true
    fi
}

firewall_snapshot_is_abox_managed() {
    local file="${1:-}"
    firewall_state_file_safe "$file" || return 1
    grep -q '^\*' "$file" || return 1
    grep -q '^COMMIT$' "$file" || return 1
    awk '
      /^\*[^ \t\r]+$/ {next}
      /^COMMIT$/ {next}
      /^-A[ \t\r]/ && /--comment[ \t\r]+"?A-Box-/ {next}
      {exit 1}
    ' "$file"
}

remove_abox_firewall_persistence() {
    local fw_file enabled_state rc_update
    # Complete ownership preflight before any destructive service/file operation.
    for fw_file in "$ABOX_DIR/firewall_restore.sh" "$ABOX_DIR/iptables.v4" "$ABOX_DIR/iptables.v6"; do
        [[ -e "$fw_file" || -L "$fw_file" ]] || continue
        case "$fw_file" in
            "$ABOX_DIR/firewall_restore.sh") auxiliary_content_is_abox_managed "$fw_file" /etc/ddr/firewall_restore.sh || return 1 ;;
            *) firewall_snapshot_is_abox_managed "$fw_file" || return 1 ;;
        esac
    done

    if [[ -e /etc/systemd/system/A-Box-firewall.service || -L /etc/systemd/system/A-Box-firewall.service ]]; then
        [[ -f /etc/systemd/system/A-Box-firewall.service && ! -L /etc/systemd/system/A-Box-firewall.service ]] || return 1
        grep -Fxq '# Managed by A-Box' /etc/systemd/system/A-Box-firewall.service 2>/dev/null || return 1
        systemd_available || return 1
        systemctl disable --now A-Box-firewall.service >/dev/null 2>&1 || return 1
        [[ "$(service_active_state_value A-Box-firewall.service 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
        enabled_state=$(systemctl show -p UnitFileState --value A-Box-firewall.service 2>/dev/null) || return 1
        [[ "$enabled_state" == disabled ]] || return 1
        rm -f -- /etc/systemd/system/A-Box-firewall.service || return 1
        [[ ! -e /etc/systemd/system/A-Box-firewall.service && ! -L /etc/systemd/system/A-Box-firewall.service ]] || return 1
        systemctl daemon-reload >/dev/null 2>&1 || return 1
    fi

    if [[ -e /etc/init.d/A-Box-firewall || -L /etc/init.d/A-Box-firewall ]]; then
        [[ -f /etc/init.d/A-Box-firewall && ! -L /etc/init.d/A-Box-firewall ]] || return 1
        grep -Fxq '# Managed by A-Box' /etc/init.d/A-Box-firewall 2>/dev/null || return 1
        command -v rc-service >/dev/null 2>&1 && command -v rc-update >/dev/null 2>&1 || return 1
        rc-service A-Box-firewall stop >/dev/null 2>&1 || return 1
        [[ "$(service_active_state_value A-Box-firewall 2>/dev/null || printf '%s' unknown)" == 0 ]] || return 1
        if rc-update show default 2>/dev/null | grep -Eq '(^|[[:space:]])A-Box-firewall([[:space:]]|$)'; then
            rc-update del A-Box-firewall default >/dev/null 2>&1 || return 1
        fi
        rc_update=$(rc-update show default 2>/dev/null) || return 1
        grep -Eq '(^|[[:space:]])A-Box-firewall([[:space:]]|$)' <<< "$rc_update" && return 1
        rm -f -- /etc/init.d/A-Box-firewall || return 1
        [[ ! -e /etc/init.d/A-Box-firewall && ! -L /etc/init.d/A-Box-firewall ]] || return 1
    fi

    # Recovery script and snapshots remain present until all owning services are
    # confirmed inactive and disabled. A failure above leaves them intact.
    rm -f -- "$ABOX_DIR/firewall_restore.sh" "$ABOX_DIR/iptables.v4" "$ABOX_DIR/iptables.v6" || return 1
    [[ ! -e "$ABOX_DIR/firewall_restore.sh" && ! -e "$ABOX_DIR/iptables.v4" && ! -e "$ABOX_DIR/iptables.v6" ]]
}

write_abox_firewall_restore_script() {
    local tmp target="$ABOX_DIR/firewall_restore.sh" uid gid mode
    install -d -m 700 "$ABOX_DIR" || return 1
    if [[ -e "$target" || -L "$target" ]]; then
        [[ -f "$target" && ! -L "$target" ]] || return 1
        uid=$(stat -c %u "$target" 2>/dev/null) || return 1
        gid=$(stat -c %g "$target" 2>/dev/null) || return 1
        mode=$(stat -c %a "$target" 2>/dev/null) || return 1
        [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
        (( (8#$mode & 8#077) == 0 )) || return 1
        grep -Fxq '# Managed by A-Box' "$target" 2>/dev/null || return 1
    fi
    tmp=$(mktemp "$ABOX_DIR/.firewall_restore.XXXXXX") || return 1
    cat > "$tmp" <<'EOF_ABOX_FW_RESTORE'
#!/usr/bin/env bash
# Managed by A-Box
# A-06: umask 077 ensures lock/temp files are 0600 (not world-readable 0644).
umask 077
set -o pipefail
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin
read_ip_pref() {
    local pref='dual' mode
    local pref_file='/etc/ddr/.ip-pref'
    if [[ -r "$pref_file" && -f "$pref_file" && ! -L "$pref_file" && "$(stat -c %u:%g "$pref_file" 2>/dev/null || true)" == '0:0' ]]; then
        mode=$(stat -c %a "$pref_file" 2>/dev/null) || mode='777'
        if [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#022) == 0 )); then
            pref=$(tr -d '[:space:]' < "$pref_file" 2>/dev/null || true)
        fi
    fi
    [[ "$pref" =~ ^(ipv4|ipv6|dual)$ ]] || pref='dual'
    printf '%s\n' "$pref"
}
has_ipv6() {
    local _pref
    _pref=$(read_ip_pref 2>/dev/null || printf 'dual')
    [[ "$_pref" == 'ipv4' ]] && return 1
    ip -6 addr show scope global 2>/dev/null | awk '/inet6/ { found=1 } END { exit !found }' && return 0
    ip -6 route show default 2>/dev/null | awk '/^default/ { found=1 } END { exit !found }' && return 0
    return 1
}
# Objective IPv6 usability check (not preference-aware).
# Used by clean_chain for N-04 "never silently skip IPv6" intent.
host_has_usable_ipv6() {
    [[ -s /proc/net/if_inet6 ]] && return 0
    local _d6
    _d6=$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null || printf '1')
    [[ "$_d6" != '1' ]] && return 0
    ip -6 addr show scope global 2>/dev/null | grep -q 'inet6 ' && return 0
    ip -6 addr show scope link 2>/dev/null | grep -q 'inet6 ' && return 0
    return 1
}
_iptables_probe_w() {
    local cmd="$1"
    local cache_var="_IPT_W_${cmd//[^a-zA-Z0-9]/_}"
    if [[ -z "${!cache_var+x}" ]]; then
        if "$cmd" -w --version >/dev/null 2>&1; then
            printf -v "$cache_var" '%s' '-w'
        else
            printf -v "$cache_var" '%s' ''
        fi
    fi
    _IPT_W_CUR="${!cache_var}"
}
_iptables_q() {
    local cmd="$1"; shift
    _iptables_probe_w "$cmd"
    if [[ -n "$_IPT_W_CUR" ]]; then
        "$cmd" "$_IPT_W_CUR" "$@"
    else
        "$cmd" "$@"
    fi
}
_iptables_do() {
    local cmd="$1"; shift
    _iptables_probe_w "$cmd"
    if [[ -n "$_IPT_W_CUR" ]]; then
        "$cmd" "$_IPT_W_CUR" "$@"
    else
        "$cmd" "$@"
    fi
}
clean_chain() {
    local cmd="$1" table="$2" chain="$3" output rule
    local owned_re='--comment "?A-Box-(HY2-HOP|[0-9]+(:[0-9]+)?-(tcp|udp)(-(WL6?|DROP6?))?)"?([ \t\r]|$)'
    local -a argv=()
    if ! command -v "$cmd" >/dev/null 2>&1; then
        # N-04: use objective host_has_usable_ipv6 (not preference-aware has_ipv6)
        # to match enforce_ss_whitelist_order's "never silently skip IPv6" intent.
        [[ "${cmd##*/}" == ip6tables ]] && ! host_has_usable_ipv6 && return 0
        return 1
    fi
    while :; do
        if ! output=$(_iptables_q "$cmd" -t "$table" -S "$chain" 2>/dev/null); then
            if [[ "$table" == nat ]]; then
                local _nat_err
                _nat_err=$(_iptables_q "$cmd" -t "$table" -S "$chain" 2>&1 >/dev/null || true)
                if printf '%s\n' "$_nat_err" | grep -qiE "table .* does not exist|table does not exist|table nat is not supported|protocol not supported|can't initialize|cannot initialize"; then
                    return 0
                fi
            fi
            return 1
        fi
        rule=$(awk -v re="$owned_re" '$0 ~ re { sub(/^-A /,"-D "); print; exit }' <<< "$output")
        [[ -n "$rule" ]] || break
        rule=${rule//\"/}
        read -r -a argv <<< "$rule"
        _iptables_do "$cmd" -t "$table" "${argv[@]}" >/dev/null 2>&1 || return 1
    done
}
restore_one() {
    local file="$1" cmd="$2"
    [[ -s "$file" ]] || return 0
    command -v "$cmd" >/dev/null 2>&1 || return 1
    grep -q '^\*' "$file" || return 0
    "$cmd" -w --noflush < "$file" >/dev/null 2>&1 || "$cmd" --noflush < "$file" >/dev/null 2>&1
}
iptables_rule_check() {
    local cmd="$1" rc; shift
    if _iptables_q "$cmd" -C "$@" 2>/dev/null; then
        return 0
    else
        rc=$?
    fi
    case "$rc" in
        1) return 1 ;;
        *) return 2 ;;
    esac
}
# F12: removed zero-call restore_iptables_saved_snapshot (duplicate dead code)
# BUG-28: hoisted from reorder_one()/reorder_ss_whitelist_rules_one().
# $1 = lock fd value. Closes it; caller clears its own lock_fd variable.
__abox_firewall_unlock() {
    local lock_fd="$1"
    # Guard empty lock_fd: `exec >&-` would close stdout.
    if [[ "$lock_fd" =~ ^[0-9]+$ ]]; then
        eval "exec ${lock_fd}>&-" 2>/dev/null || true
    fi
}
__abox_normalize_managed_rule_line() {
    local line="$1"
    line=${line//\"/}
    line=$(printf '%s\n' "$line" | sed -E 's/(^|[[:space:]])(-p[[:space:]]+(tcp|udp))[[:space:]]+-m[[:space:]]+\3([[:space:]]|$)/\1\2\4/')
    printf '%s\n' "$line"
}
reorder_one() {
    local cmd="$1" port="$2" proto="$3" wl_suffix="$4" drop_suffix="$5"
    local wl_comment="A-Box-${port}-${proto}-${wl_suffix}" drop_comment="A-Box-${port}-${proto}-${drop_suffix}"
    local wl_re="--comment[[:space:]]+\"?${wl_comment}\"?([[:space:]]|$)" drop_re="--comment[[:space:]]+\"?${drop_comment}\"?([[:space:]]|$)"
    local save_cmd="${cmd}-save" rules_output='' recovery_snapshot='' lock_file=/run/A-Box-firewall-reorder.lock lock_fd=''
    local original_rules_output='' current_rules_output='' current_line line i j n rule_no target_idx del_idx check_rc=0 mutated=0
    local -a rules=() argv=() current_lines=() delete_lines=() delete_target_indices=() delete_rule_numbers=()
    local -a original_target_lines=() original_target_positions=() expected_target_lines=()
    local -a current_target_lines=() current_foreign_lines=() original_foreign_rules=()

    command -v "$cmd" >/dev/null 2>&1 || return 0
    command -v "$save_cmd" >/dev/null 2>&1 || return 1
    if ! _iptables_q "$cmd" -S INPUT >/dev/null 2>&1; then
        if [[ "${cmd##*/}" == ip6tables ]] && ! host_has_usable_ipv6; then return 0; fi
        return 1
    fi
    if iptables_rule_check "$cmd" INPUT -p "$proto" --dport "$port" -m comment --comment "$drop_comment" -j DROP; then check_rc=0; else check_rc=$?; fi
    case "$check_rc" in 0) ;; 1) return 0 ;; *) return 1 ;; esac

    [[ -d /run && ! -L /run ]] || return 1
    if [[ -e "$lock_file" || -L "$lock_file" ]]; then
        [[ -f "$lock_file" && ! -L "$lock_file" ]] || return 1
        [[ "$(stat -c %u:%g "$lock_file" 2>/dev/null || true)" == 0:0 ]] || return 1
        local lock_mode
        lock_mode=$(stat -c %a "$lock_file" 2>/dev/null) || return 1
        if [[ "$lock_mode" =~ ^[0-7]{3,4}$ ]]; then
            (( (8#$lock_mode & 8#077) == 0 )) || return 1
        else
            return 1
        fi
    else
        (umask 077; set -o noclobber; : > "$lock_file") 2>/dev/null || return 1
    fi
    # Open+flock before chown/chmod so the critical section starts immediately.
    exec {lock_fd}>>"$lock_file" || return 1
    flock -n "$lock_fd" || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; return 1; }
    chown root:root "$lock_file" 2>/dev/null || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; rm -f -- "$lock_file"; return 1; }
    chmod 600 "$lock_file" 2>/dev/null || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; rm -f -- "$lock_file"; return 1; }

    capture_firewall_views() {
        local item normalized
        current_rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || return 1
        current_target_lines=()
        current_foreign_lines=()
        while IFS= read -r item; do
            [[ "$item" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
            if [[ "$item" =~ $wl_re || "$item" =~ $drop_re ]]; then
                normalized=$(__abox_normalize_managed_rule_line "$item") || return 1
                current_target_lines+=("$normalized")
            else
                current_foreign_lines+=("$item")
            fi
        done <<< "$current_rules_output"
    }
    firewall_state_matches_expected() {
        capture_firewall_views || return 1
        [[ "$(printf '%s\n' "${current_target_lines[@]}")" == "$(printf '%s\n' "${expected_target_lines[@]}")" ]] || return 1
        [[ "$(printf '%s\n' "${current_foreign_lines[@]}")" == "$(printf '%s\n' "${original_foreign_rules[@]}")" ]]
    }
    firewall_rollback() {
        local rollback_line
        local -a rollback_lines=() rollback_argv_arr=()
        [[ -n "$recovery_snapshot" && -s "$recovery_snapshot" ]] || return 1
        capture_firewall_views || return 1
        [[ "$(printf '%s\n' "${current_target_lines[@]}")" == "$(printf '%s\n' "${expected_target_lines[@]}")" ]] || {
            printf '%s\n' "A-Box firewall rollback conflict: target rules changed outside this transaction; recovery snapshot preserved at $recovery_snapshot" >&2
            return 2
        }
        [[ "$(printf '%s\n' "${current_foreign_lines[@]}")" == "$(printf '%s\n' "${original_foreign_rules[@]}")" ]] || {
            printf '%s\n' "A-Box firewall rollback conflict: non-A-Box INPUT rules changed outside this transaction; recovery snapshot preserved at $recovery_snapshot" >&2
            return 2
        }
        rollback_lines=("${current_target_lines[@]}")
        for rollback_line in "${rollback_lines[@]}"; do
            rollback_line=${rollback_line//\"/}
            read -r -a rollback_argv_arr <<< "$rollback_line"
            [[ "${rollback_argv_arr[0]:-}" == -A && "${rollback_argv_arr[1]:-}" == INPUT ]] || return 1
            _iptables_do "$cmd" -D INPUT "${rollback_argv_arr[@]:2}" >/dev/null 2>&1 || return 1
        done
        # X-01/X-02: insert in FORWARD order at original 1-based positions.
        # Reverse insertion shifts indices: each -I at an absolute position
        # displaces later rules, so reverse order scrambles the chain.
        for ((i=0; i<${#original_target_lines[@]}; i++)); do
            rollback_line=${original_target_lines[i]//\"/}
            read -r -a rollback_argv_arr <<< "$rollback_line"
            [[ "${rollback_argv_arr[0]:-}" == -A && "${rollback_argv_arr[1]:-}" == INPUT ]] || return 1
            _iptables_do "$cmd" -I INPUT "${original_target_positions[i]}" "${rollback_argv_arr[@]:2}" >/dev/null 2>&1 || return 1
        done
        capture_firewall_views || return 1
        [[ "$current_rules_output" == "$original_rules_output" ]] || return 1
        rm -f -- "$recovery_snapshot" || return 1
        recovery_snapshot=''
        return 0
    }

    recovery_snapshot=$(mktemp /run/A-Box-firewall-recovery.XXXXXX) || { __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    if ! "$save_cmd" -t filter > "$recovery_snapshot" 2>/dev/null; then
        rm -f -- "$recovery_snapshot"
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    original_rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || { rm -f -- "$recovery_snapshot"; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    capture_firewall_views || { rm -f -- "$recovery_snapshot"; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    original_target_lines=("${current_target_lines[@]}")
    original_foreign_rules=("${current_foreign_lines[@]}")
    expected_target_lines=("${original_target_lines[@]}")
    for line in "${original_target_lines[@]}"; do
        if [[ "$line" =~ $wl_re ]]; then rules+=("$line"); fi
    done
    rule_no=0
    while IFS= read -r line; do
        [[ "$line" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
        rule_no=$((rule_no + 1))
        if [[ "$line" =~ $wl_re || "$line" =~ $drop_re ]]; then
            original_target_positions+=("$rule_no")
        fi
    done <<< "$original_rules_output"
    n=${#rules[@]}

    for ((i=n-1; i>=0; i--)); do
        local expected_line="${rules[i]}"
        line=${rules[i]//\"/}
        read -r -a argv <<< "$line"
        [[ "${argv[0]:-}" == -A && "${argv[1]:-}" == INPUT ]] || { firewall_rollback >/dev/null 2>&1 || printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        firewall_state_matches_expected || {
            if (( mutated )); then
                if ! firewall_rollback; then
                    printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2
                fi
            else
                rm -f -- "$recovery_snapshot" || true
            fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        }
        if ! _iptables_do "$cmd" -I INPUT 1 "${argv[@]:2}" >/dev/null 2>&1; then
            if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        fi
        mutated=1
        expected_target_lines=("$expected_line" "${expected_target_lines[@]}")
    done
    local expected_drop_line="-A INPUT -p ${proto} --dport ${port} -m comment --comment ${drop_comment} -j DROP"
    firewall_state_matches_expected || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    if ! _iptables_do "$cmd" -I INPUT "$((n + 1))" -p "$proto" --dport "$port" -m comment --comment "$drop_comment" -j DROP >/dev/null 2>&1; then
        if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    expected_target_lines=("${expected_target_lines[@]:0:n}" "$expected_drop_line" "${expected_target_lines[@]:n}")

    rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    current_lines=(); mapfile -t current_lines <<< "$rules_output"
    delete_lines=(); delete_target_indices=(); target_idx=0; rule_no=0
    for i in "${!current_lines[@]}"; do
        current_line="${current_lines[i]}"
        [[ "$current_line" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
        rule_no=$((rule_no + 1))
        if [[ "$current_line" =~ $wl_re || "$current_line" =~ $drop_re ]]; then
            if (( target_idx > n )); then
                delete_lines+=("$current_line")
                delete_target_indices+=("$target_idx")
                delete_rule_numbers+=("$rule_no")
            fi
            target_idx=$((target_idx + 1))
        fi
    done
    for ((j=${#delete_lines[@]}-1; j>=0; j--)); do
        firewall_state_matches_expected || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        line=${delete_lines[j]//\"/}
        read -r -a argv <<< "$line"
        [[ "${argv[0]:-}" == -A && "${argv[1]:-}" == INPUT ]] || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        if ! _iptables_do "$cmd" -D INPUT "${delete_rule_numbers[j]}" >/dev/null 2>&1; then
            if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        fi
        del_idx="${delete_target_indices[j]}"
        expected_target_lines=("${expected_target_lines[@]:0:del_idx}" "${expected_target_lines[@]:del_idx+1}")
    done
    if ! firewall_state_matches_expected; then
        if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    if ! rm -f -- "$recovery_snapshot"; then
        printf '%s\n' "A-Box firewall change completed, but recovery snapshot cleanup failed; snapshot retained at $recovery_snapshot" >&2
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    recovery_snapshot=''
    __abox_firewall_unlock "$lock_fd"; lock_fd=''
    return 0
}

reorder_policy() {
    local cmd="$1" wl_suffix="$2" drop_suffix="$3" line key port proto rules_output=''
    local -A seen=()
    command -v "$cmd" >/dev/null 2>&1 || return 0
    rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || return 1
    while IFS= read -r line; do
        if [[ "$line" =~ --comment[[:space:]]+"?A-Box-([0-9]{1,5})-(tcp|udp)-${drop_suffix}"?([[:space:]]|$) ]]; then
            port="${BASH_REMATCH[1]}"; proto="${BASH_REMATCH[2]}"; key="${port}|${proto}"
            [[ -n "${seen[$key]:-}" ]] && continue
            seen[$key]=1
            reorder_one "$cmd" "$port" "$proto" "$wl_suffix" "$drop_suffix" || return 1
        fi
    done <<< "$rules_output"
}
clean_chain iptables filter INPUT || exit 1
clean_chain iptables nat PREROUTING || exit 1
restore_one /etc/ddr/iptables.v4 iptables-restore || exit 1
reorder_policy iptables WL DROP || exit 1
if command -v ip6tables >/dev/null 2>&1 && _iptables_q ip6tables -S INPUT >/dev/null 2>&1; then
    clean_chain ip6tables filter INPUT || exit 1
    clean_chain ip6tables nat PREROUTING || exit 1
    restore_one /etc/ddr/iptables.v6 ip6tables-restore || exit 1
    reorder_policy ip6tables WL6 DROP6 || exit 1
fi
EOF_ABOX_FW_RESTORE
    [[ $? -eq 0 ]] || { rm -f "$tmp"; return 1; }
    chmod 700 "$tmp" || { rm -f "$tmp"; return 1; }
    mv -f "$tmp" "$ABOX_DIR/firewall_restore.sh" || { rm -f "$tmp"; return 1; }
}

# BUG-28: hoisted from install_abox_firewall_persistence_service().
# $1=old_restore $2=tx_dir $3=old_unit $4=old_unit_path $5=old_unit_enabled
__abox_firewall_persistence_rollback() {
    local old_restore="$1" tx_dir="$2" old_unit="$3" old_unit_path="$4" old_unit_enabled="$5"
    local fail=0
    if [[ "$old_restore" == 1 ]]; then
        cp -a -- "$tx_dir/firewall_restore.sh" "$ABOX_DIR/firewall_restore.sh" || fail=1
    else
        rm -f -- "$ABOX_DIR/firewall_restore.sh" || fail=1
    fi
    case "${INIT_SYS:-}" in
        systemd)
            if [[ "$old_unit" == 1 ]]; then
                cp -a -- "$tx_dir/A-Box-firewall.service" "$old_unit_path" || fail=1
            else
                systemctl disable A-Box-firewall.service >/dev/null 2>&1 || true
                rm -f -- "$old_unit_path" || fail=1
            fi
            systemctl daemon-reload >/dev/null 2>&1 || fail=1
            if [[ "$old_unit" == 1 ]]; then
                case "$old_unit_enabled" in
                    enabled|enabled-runtime|indirect) systemctl enable A-Box-firewall.service >/dev/null 2>&1 || fail=1 ;;
                    *) systemctl disable A-Box-firewall.service >/dev/null 2>&1 || fail=1 ;;
                esac
            fi
            ;;
        openrc)
            if [[ "$old_unit" == 1 ]]; then
                cp -a -- "$tx_dir/A-Box-firewall" "$old_unit_path" || fail=1
            else
                if command -v rc-update >/dev/null 2>&1 && rc-update show default 2>/dev/null | grep -Eq '(^|[[:space:]])A-Box-firewall([[:space:]]|$)'; then
                    rc-update del A-Box-firewall default >/dev/null 2>&1 || true
                fi
                rm -f -- "$old_unit_path" || fail=1
            fi
            if command -v rc-update >/dev/null 2>&1; then
                if [[ "$old_unit_enabled" == 1 ]]; then
                    rc-update add A-Box-firewall default >/dev/null 2>&1 || true
                elif rc-update show default 2>/dev/null | grep -Eq '(^|[[:space:]])A-Box-firewall([[:space:]]|$)'; then
                    rc-update del A-Box-firewall default >/dev/null 2>&1 || true
                fi
                if [[ "$(service_enabled_state_value A-Box-firewall 2>/dev/null || printf '%s' unknown)" != "$old_unit_enabled" ]]; then
                    fail=1
                fi
            else
                fail=1
            fi
            ;;
    esac
    return "$fail"
}
install_abox_firewall_persistence_service() {
    local tx_dir old_restore=0 old_unit=0 old_unit_path='' old_unit_enabled='' rollback_rc=0
    tx_dir=$(mktemp -d "$ABOX_DIR/.firewall-persist-tx.XXXXXX") || return 1

    if [[ -e "$ABOX_DIR/firewall_restore.sh" || -L "$ABOX_DIR/firewall_restore.sh" ]]; then
        [[ -f "$ABOX_DIR/firewall_restore.sh" && ! -L "$ABOX_DIR/firewall_restore.sh" ]] || { rm -rf -- "$tx_dir"; return 1; }
        path_owned_by_root "$ABOX_DIR/firewall_restore.sh" || { rm -rf -- "$tx_dir"; return 1; }
        path_mode_has_no_group_other_write "$ABOX_DIR/firewall_restore.sh" || { rm -rf -- "$tx_dir"; return 1; }
        grep -Fxq '# Managed by A-Box' "$ABOX_DIR/firewall_restore.sh" 2>/dev/null || { rm -rf -- "$tx_dir"; return 1; }
        cp -a -- "$ABOX_DIR/firewall_restore.sh" "$tx_dir/firewall_restore.sh" || { rm -rf -- "$tx_dir"; return 1; }
        old_restore=1
    fi

    case "${INIT_SYS:-}" in
        systemd)
            old_unit_path=/etc/systemd/system/A-Box-firewall.service
            if [[ -e "$old_unit_path" || -L "$old_unit_path" ]]; then
                assert_abox_auxiliary_safe "$old_unit_path" || { rm -rf -- "$tx_dir"; return 1; }
                cp -a -- "$old_unit_path" "$tx_dir/A-Box-firewall.service" || { rm -rf -- "$tx_dir"; return 1; }
                old_unit=1
                old_unit_enabled=$(service_enabled_state_value A-Box-firewall.service) || { rm -rf -- "$tx_dir"; return 1; }
            fi
            ;;
        openrc)
            old_unit_path=/etc/init.d/A-Box-firewall
            if [[ -e "$old_unit_path" || -L "$old_unit_path" ]]; then
                assert_abox_auxiliary_safe "$old_unit_path" || { rm -rf -- "$tx_dir"; return 1; }
                cp -a -- "$old_unit_path" "$tx_dir/A-Box-firewall" || { rm -rf -- "$tx_dir"; return 1; }
                old_unit=1
                old_unit_enabled=$(service_enabled_state_value A-Box-firewall) || { rm -rf -- "$tx_dir"; return 1; }
            fi
            ;;
        *)
            rm -rf -- "$tx_dir"
            return 1
            ;;
    esac


    if ! write_abox_firewall_restore_script; then
        __abox_firewall_persistence_rollback "$old_restore" "$tx_dir" "$old_unit" "$old_unit_path" "$old_unit_enabled" || rollback_rc=1
        rm -rf -- "$tx_dir"
        (( rollback_rc == 0 )) && return 1
        return 1
    fi
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        if ! write_file_atomically_from_stdin /etc/systemd/system/A-Box-firewall.service 644 <<'EOF_ABOX_FW_UNIT'
# Managed by A-Box
[Unit]
Description=A-Box isolated firewall rule restore
After=network-pre.target iptables.service ip6tables.service nftables.service ufw.service firewalld.service
Before=xray.service sing-box.service hysteria.service

[Service]
Type=oneshot
ExecStart=/etc/ddr/firewall_restore.sh
NoNewPrivileges=true
PrivateTmp=true
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
EOF_ABOX_FW_UNIT
        then
            __abox_firewall_persistence_rollback "$old_restore" "$tx_dir" "$old_unit" "$old_unit_path" "$old_unit_enabled" || rollback_rc=1
            rm -rf -- "$tx_dir"
            return 1
        fi
        if ! systemctl daemon-reload >/dev/null 2>&1 || ! systemctl enable A-Box-firewall.service >/dev/null 2>&1; then
            __abox_firewall_persistence_rollback "$old_restore" "$tx_dir" "$old_unit" "$old_unit_path" "$old_unit_enabled" || rollback_rc=1
            rm -rf -- "$tx_dir"
            return 1
        fi
    else
        if ! write_file_atomically_from_stdin /etc/init.d/A-Box-firewall 755 <<'EOF_ABOX_FW_OPENRC'
#!/sbin/openrc-run
# Managed by A-Box
description="A-Box isolated firewall rule restore"
command="/etc/ddr/firewall_restore.sh"
command_background="no"
depend() { need net; after iptables ip6tables nftables ufw firewalld; before xray sing-box hysteria; }
EOF_ABOX_FW_OPENRC
        then
            __abox_firewall_persistence_rollback "$old_restore" "$tx_dir" "$old_unit" "$old_unit_path" "$old_unit_enabled" || rollback_rc=1
            rm -rf -- "$tx_dir"
            return 1
        fi
        if ! chmod 755 /etc/init.d/A-Box-firewall || ! rc-update add A-Box-firewall default >/dev/null 2>&1; then
            __abox_firewall_persistence_rollback "$old_restore" "$tx_dir" "$old_unit" "$old_unit_path" "$old_unit_enabled" || rollback_rc=1
            rm -rf -- "$tx_dir"
            return 1
        fi
    fi

    rm -rf -- "$tx_dir"
    return 0
}

save_firewall_rules() {
    local tmp4 tmp6 backend target target4="$ABOX_DIR/iptables.v4" target6="$ABOX_DIR/iptables.v6"
    local backup4='' backup6='' restore_failed=0
    backend=$(firewall_backend) || return 1
    case "$backend" in
        nftables-unsupported)
            msg "${RED}Native nftables rules detected; A-Box cannot safely persist or roll them back. No firewall rules were changed.${NC}"
            return 1
            ;;
        ufw|firewalld)
            remove_abox_firewall_persistence || return 1
            return 0
            ;;
    esac
    command -v iptables-save >/dev/null 2>&1 || return 1
    install -d -m 700 "$ABOX_DIR" || return 1

    # Refuse unsafe existing persistence files, then snapshot them before the
    # two-file replacement so a later failure cannot leave a mixed v4/v6 state.
    for target in "$target4" "$target6"; do
        if [[ -L "$target" ]]; then return 1; fi
        if [[ -e "$target" ]]; then
            [[ -f "$target" ]] || return 1
            [[ "$(stat -c %h "$target" 2>/dev/null || echo 0)" == 1 ]] || return 1
        fi
    done
    if [[ -f "$target4" ]]; then
        backup4=$(mktemp "$ABOX_DIR/.iptables.v4.rollback.XXXXXX") || return 1
        rm -f -- "$backup4"
        cp -a -- "$target4" "$backup4" || { rm -f -- "$backup4"; return 1; }
    fi
    if [[ -f "$target6" ]]; then
        backup6=$(mktemp "$ABOX_DIR/.iptables.v6.rollback.XXXXXX") || { rm -f -- "$backup4"; return 1; }
        rm -f -- "$backup6"
        cp -a -- "$target6" "$backup6" || { rm -f -- "$backup4" "$backup6"; return 1; }
    fi

    tmp4=$(mktemp "$ABOX_DIR/.iptables.v4.XXXXXX") || { rm -f -- "$backup4" "$backup6"; return 1; }
    tmp6=$(mktemp "$ABOX_DIR/.iptables.v6.XXXXXX") || { rm -f -- "$tmp4" "$backup4" "$backup6"; return 1; }
    iptables-save > "${tmp4}.all" 2>/dev/null || { rm -f "$tmp4" "$tmp6" "${tmp4}.all" "$backup4" "$backup6"; return 1; }
    extract_abox_iptables_rules "${tmp4}.all" all > "$tmp4" || { rm -f "$tmp4" "$tmp6" "${tmp4}.all" "$backup4" "$backup6"; return 1; }
    rm -f "${tmp4}.all"
    if command -v ip6tables-save >/dev/null 2>&1; then
        if ip6tables-save > "${tmp6}.all" 2>/dev/null; then
            extract_abox_iptables_rules "${tmp6}.all" all > "$tmp6" || { rm -f "$tmp4" "$tmp6" "${tmp6}.all" "$backup4" "$backup6"; return 1; }
            rm -f "${tmp6}.all"
        elif ! has_ipv6; then
            # A present userspace binary does not prove that the kernel IPv6
            # firewall backend is enabled. Ignore only a failed v6 query when
            # no global IPv6 address/default route is available.
            rm -f "${tmp6}.all"
            : > "$tmp6"
        else
            rm -f "$tmp4" "$tmp6" "${tmp6}.all" "$backup4" "$backup6"
            return 1
        fi
    else
        if has_ipv6; then
            rm -f -- "$tmp4" "$tmp6" "$backup4" "$backup6"
            return 1
        fi
        : > "$tmp6"
    fi
    chmod 600 "$tmp4" "$tmp6" || { rm -f "$tmp4" "$tmp6" "$backup4" "$backup6"; return 1; }
    if ! grep -q '^\*' "$tmp4" && ! grep -q '^\*' "$tmp6"; then
        rm -f "$tmp4" "$tmp6" "$backup4" "$backup6"
        remove_abox_firewall_persistence || return 1
        return 0
    fi

    if ! mv -f -- "$tmp4" "$target4"; then
        rm -f -- "$tmp4" "$tmp6" "$backup4" "$backup6"
        return 1
    fi
    if ! mv -f -- "$tmp6" "$target6"; then
        if [[ -n "$backup4" ]]; then cp -a -- "$backup4" "$target4" || restore_failed=1; else rm -f -- "$target4" || restore_failed=1; fi
        rm -f -- "$tmp6" "$backup4" "$backup6"
        (( restore_failed == 0 )) || return 1
        return 1
    fi
    if ! install_abox_firewall_persistence_service; then
        if [[ -n "$backup4" ]]; then cp -a -- "$backup4" "$target4" || restore_failed=1; else rm -f -- "$target4" || restore_failed=1; fi
        if [[ -n "$backup6" ]]; then cp -a -- "$backup6" "$target6" || restore_failed=1; else rm -f -- "$target6" || restore_failed=1; fi
        rm -f -- "$backup4" "$backup6"
        (( restore_failed == 0 )) || return 1
        return 1
    fi
    rm -f -- "$backup4" "$backup6"
    return 0
}

ufw_is_active() {
    command -v ufw >/dev/null 2>&1 || return 1
    LC_ALL=C ufw status 2>/dev/null | awk 'tolower($0) ~ /^status:[ \t\r]*active/ { found=1 } END { exit !found }'
}

nftables_native_rules_present() {
    command -v nft >/dev/null 2>&1 || return 1
    nft -nn list ruleset 2>/dev/null | awk '
        /^[ \t\r]*table[ \t\r]+/ {
            family=$2
            name=$3
            gsub(/[{}]/, "", name)
            if (family == "inet" || family == "bridge" || family == "netdev" || family == "arp")
                native=1
            else if ((family == "ip" || family == "ip6") &&
                     name !~ /^(filter|nat|mangle|raw|security)$/)
                native=1
        }
        # FIX (P3-01 regression revert 2026-10-15): match chain names
        # case-SENSITIVELY (lowercase only). Native nftables convention uses
        # lowercase chain names (input/forward/output). iptables-nft compat
        # tables use UPPERCASE (INPUT/FORWARD/OUTPUT). The case-insensitive
        # match misidentified iptables-nft rulesets as native nftables on
        # Debian/Ubuntu, breaking firewall_backend().
        /^[ \t\r]*chain[ \t\r]+/ {
            cname=$2
            gsub(/\{/, "", cname)
            if (cname == "input" || cname == "forward" || cname == "output")
                native=1
            # G6: custom chain name in a STANDARD table whose declaration
            # continues on the NEXT line with a base-chain header. nftables
            # prints chain declarations as two lines (see src/rule.c
            # chain_print_declaration()). A comment line may sit between.
            # iptables-nft compat chains are UPPERCASE and excluded here.
            pend = ((family == "ip" || family == "ip6") && \
                    (cname != "INPUT" && cname != "FORWARD" && cname != "OUTPUT"))
            next
        }
        # G6 (cont): check the line following a pending custom chain.
        pend && /^[ \t\r]*(comment[ \t"\r]|type[ \t\r])/ {
            if ($0 ~ /type[ \t\r]+filter[ \t\r]+hook[ \t\r]+input/)
                native=1
            next
        }
        { pend = 0 }
        END { exit !native }
    '
}

firewall_backend() {
    if ufw_is_active; then
        printf 'ufw\n'
    elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
        printf 'firewalld\n'
    elif nftables_native_rules_present; then
        printf 'nftables-unsupported\n'
    else
        printf 'iptables\n'
    fi
}

native_firewall_record_valid() {
    local line="$1" backend spec proto scope zone extra normalized
    IFS='|' read -r backend spec proto scope zone extra <<< "$line"
    [[ -z "$extra" ]] || return 1
    normalized=$(normalize_port_spec "$spec") || return 1
    [[ "$normalized" == "$spec" ]] || return 1
    [[ "$proto" == tcp || "$proto" == udp ]] || return 1
    case "$backend:$scope" in
        ufw:rule) [[ -z "$zone" ]] || return 1 ;;
        firewalld:runtime|firewalld:permanent)
            if [[ -n "$zone" ]]; then
                [[ "$zone" =~ ^[A-Za-z0-9_.:@+-]+$ ]] || return 1
            fi
            ;;
        *) return 1 ;;
    esac
    return 0
}

firewall_state_file_safe() {
    local file="${1:-$ABOX_FW_STATE}" uid gid mode
    [[ -f "$file" && ! -L "$file" ]] || return 1
    uid=$(stat -c %u "$file" 2>/dev/null) || return 1
    gid=$(stat -c %g "$file" 2>/dev/null) || return 1
    mode=$(stat -c %a "$file" 2>/dev/null) || return 1
    [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#077) == 0 ))
}

validate_native_firewall_state_file() {
    local file="${1:-$ABOX_FW_STATE}" line
    firewall_state_file_safe "$file" || return 1
    declare -A seen=()
    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ -n "$line" ]] || continue
        native_firewall_record_valid "$line" || return 1
        [[ -z "${seen[$line]:-}" ]] || return 1
        seen[$line]=1
    done < "$file"
}

record_native_firewall_rule() {
    local backend="$1" spec proto="$3" scope="${4:-}" record tmp zone=''
    spec=$(normalize_port_spec "$2") || return 1
    [[ "$proto" == tcp || "$proto" == udp ]] || return 1
    case "$backend:$scope" in
        ufw:rule) ;;
        firewalld:runtime|firewalld:permanent)
            zone=$(firewalld_zone_for_abox) || return 1
            ;;
        *) return 1 ;;
    esac
    if [[ -n "$zone" ]]; then
        record="${backend}|${spec}|${proto}|${scope}|${zone}"
    else
        record="${backend}|${spec}|${proto}|${scope}"
    fi
    native_firewall_record_valid "$record" || return 1
    install -d -o root -g root -m 700 "$ABOX_DIR" || return 1
    if [[ -e "$ABOX_FW_STATE" || -L "$ABOX_FW_STATE" ]]; then
        validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
    fi
    tmp=$(mktemp "$ABOX_DIR/.firewall-native.XXXXXX") || return 1
    if [[ -f "$ABOX_FW_STATE" ]]; then
        cat "$ABOX_FW_STATE" > "$tmp" || { rm -f -- "$tmp"; return 1; }
    fi
    grep -qxF "$record" "$tmp" 2>/dev/null || printf '%s\n' "$record" >> "$tmp" || { rm -f -- "$tmp"; return 1; }
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$ABOX_FW_STATE" || { rm -f -- "$tmp"; return 1; }
}

ufw_global_rule_numbers() {
    local spec proto="$2" owned_only="${3:-0}" target output line number body rest expected_comment
    spec=$(normalize_port_spec "$1") || return 2
    [[ "$proto" == tcp || "$proto" == udp ]] || return 2
    target="${spec}/${proto}"
    expected_comment="# A-Box-${spec}-${proto}"
    command -v ufw >/dev/null 2>&1 || return 2
    output=$(LC_ALL=C ufw status numbered 2>/dev/null) || return 2
    while IFS= read -r line; do
        [[ "$line" =~ ^[[:space:]]*\[[[:space:]]*([0-9]+)\][[:space:]]+(.*)$ ]] || continue
        number="${BASH_REMATCH[1]}"
        body="${BASH_REMATCH[2]}"
        if [[ "$body" == "$target"* ]]; then
            rest="${body#"$target"}"
        else
            continue
        fi
        rest="${rest# (v6)}"
        rest="${rest#"${rest%%[![:space:]]*}"}"
        case "$rest" in
            'ALLOW IN '*) rest="${rest#ALLOW IN }" ;;
            'LIMIT IN '*) rest="${rest#LIMIT IN }" ;;
            *) continue ;;
        esac
        rest="${rest#"${rest%%[![:space:]]*}"}"
        [[ "$rest" =~ ^Anywhere([[:space:]]+\(v6\))?([[:space:]]+#.*)?$ ]] || continue
        if [[ "$owned_only" == 1 ]]; then
            [[ "$rest" == *"$expected_comment" ]] || continue
            [[ "${rest##*# }" == "A-Box-${spec}-${proto}" ]] || continue
        fi
        printf '%s\n' "$number"
    done <<< "$output"
}

ufw_rule_state() {
    local numbers rc
    numbers=$(ufw_global_rule_numbers "$1" "$2" 0); rc=$?
    [[ "$rc" == 0 ]] || return "$rc"
    [[ -n "$numbers" ]]
}

ufw_rule_exists() { ufw_rule_state "$1" "$2"; }

ufw_owned_rule_exists() {
    local numbers rc
    numbers=$(ufw_global_rule_numbers "$1" "$2" 1); rc=$?
    [[ "$rc" == 0 ]] || return "$rc"
    [[ -n "$numbers" ]]
}

ufw_delete_owned_rules() {
    local spec proto="$2" numbers
    spec=$(normalize_port_spec "$1") || return 1
    [[ "$proto" == tcp || "$proto" == udp ]] || return 1
    numbers=$(ufw_global_rule_numbers "$spec" "$proto" 1) || return 1
    [[ -n "$numbers" ]] || return 0
    # Delete by the full rule specification rather than mutable display indices.
    # UFW can match the original comment and removes the generic v4/v6 rule pair
    # as one logical rule; a concurrent insertion cannot redirect deletion to a
    # different numbered rule.
    if ! ufw --force delete allow proto "$proto" from any to any port "$spec" comment "A-Box-${spec}-${proto}" >/dev/null 2>&1 || ufw_owned_rule_exists "$spec" "$proto"; then
        local _num
        while IFS= read -r _num; do
            [[ "$_num" =~ ^[0-9]+$ ]] || continue
            ufw --force delete "$_num" >/dev/null 2>&1 || return 1
        done < <(printf '%s\n' "$numbers" | LC_ALL=C sort -rn)
    fi
    ! ufw_owned_rule_exists "$spec" "$proto"
}

firewalld_zone_for_abox() {
    local zone=''
    if [[ -n "${INGRESS_IF:-}" ]] && command -v firewall-cmd >/dev/null 2>&1; then
        zone=$(firewall-cmd --get-zone-of-interface="$INGRESS_IF" 2>/dev/null || true)
        [[ -n "$zone" && "$zone" != 'no zone' ]] && { printf '%s\n' "$zone"; return 0; }
    fi
    zone=$(firewall-cmd --get-default-zone 2>/dev/null || true)
    [[ -n "$zone" && "$zone" != 'no zone' ]] || return 1
    printf '%s\n' "$zone"
}

firewalld_cmd() {
    local zone=''
    zone=$(firewalld_zone_for_abox 2>/dev/null || true)
    if [[ -n "$zone" ]]; then command firewall-cmd --zone="$zone" "$@"; else command firewall-cmd "$@"; fi
}

firewalld_port_state() {
    local spec proto="$2" scope="${3:-runtime}" zone="${4:-}" fw_spec rc
    spec=$(normalize_port_spec "$1") || return 2
    [[ "$proto" == tcp || "$proto" == udp ]] || return 2
    fw_spec=$(port_spec_for_firewalld "$spec") || return 2
    command -v firewall-cmd >/dev/null 2>&1 || return 2
    firewall-cmd --state >/dev/null 2>&1 || return 2
    if [[ -n "$zone" ]]; then
        if [[ "$scope" == permanent ]]; then
            command firewall-cmd --zone="$zone" --permanent --query-port="${fw_spec}/${proto}" >/dev/null 2>&1
        else
            command firewall-cmd --zone="$zone" --query-port="${fw_spec}/${proto}" >/dev/null 2>&1
        fi
    elif [[ "$scope" == permanent ]]; then
        firewalld_cmd --permanent --query-port="${fw_spec}/${proto}" >/dev/null 2>&1
    else
        firewalld_cmd --query-port="${fw_spec}/${proto}" >/dev/null 2>&1
    fi
    rc=$?
    case "$rc" in 0) return 0 ;; 1) return 1 ;; *) return 2 ;; esac
}

remove_native_firewall_rules() {
    [[ ! -e "$ABOX_FW_STATE" && ! -L "$ABOX_FW_STATE" ]] && return 0
    validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
    local backend spec proto scope zone extra fw_spec any_failed=0 record_failed tmp
    tmp=$(mktemp "$ABOX_DIR/.firewall-native.remaining.XXXXXX") || return 1
    while IFS='|' read -r backend spec proto scope zone extra; do
        [[ -n "$backend" ]] || continue
        record_failed=0
        case "$backend" in
            ufw)
                if ! command -v ufw >/dev/null 2>&1; then
                    record_failed=1
                elif ! ufw_delete_owned_rules "$spec" "$proto"; then
                    record_failed=1
                fi
                ;;
            firewalld)
                fw_spec=$(port_spec_for_firewalld "$spec" 2>/dev/null || true)
                if [[ -z "$fw_spec" ]] || ! command -v firewall-cmd >/dev/null 2>&1 || ! firewall-cmd --state >/dev/null 2>&1; then
                    record_failed=1
                elif [[ "$scope" == runtime ]]; then
                    if [[ -n "$zone" ]]; then command firewall-cmd --zone="$zone" --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true; else firewalld_cmd --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true; fi
                    firewalld_port_state "$spec" "$proto" runtime "$zone"
                    [[ $? == 1 ]] || record_failed=1
                elif [[ "$scope" == permanent ]]; then
                    if [[ -n "$zone" ]]; then command firewall-cmd --zone="$zone" --permanent --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true; else firewalld_cmd --permanent --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true; fi
                    firewalld_port_state "$spec" "$proto" permanent "$zone"
                    [[ $? == 1 ]] || record_failed=1
                else
                    record_failed=1
                fi
                ;;
            *) record_failed=1 ;;
        esac
        if [[ "$record_failed" == 1 ]]; then
            if [[ -n "$zone" ]]; then
                printf '%s|%s|%s|%s|%s\n' "$backend" "$spec" "$proto" "$scope" "$zone" >> "$tmp"
            else
                printf '%s|%s|%s|%s\n' "$backend" "$spec" "$proto" "$scope" >> "$tmp"
            fi
            any_failed=1
        fi
    done < "$ABOX_FW_STATE"
    chown root:root "$tmp" 2>/dev/null || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" 2>/dev/null || { rm -f -- "$tmp"; return 1; }
    if [[ "$any_failed" == 1 ]]; then
        mv -f -- "$tmp" "$ABOX_FW_STATE" || { rm -f -- "$tmp"; return 1; }
        return 1
    fi
    rm -f -- "$tmp" "$ABOX_FW_STATE"
    return 0
}

forget_native_firewall_rule() {
    local raw_spec="$1" proto="$2" target_backend="$3" spec tmp kept=0 rec_backend rec_spec rec_proto rec_scope rec_zone _rec_extra
    spec=$(normalize_port_spec "$raw_spec") || return 1
    [[ "$proto" == tcp || "$proto" == udp ]] || return 1
    [[ "$target_backend" == ufw || "$target_backend" == firewalld || "$target_backend" == iptables ]] || return 1
    [[ ! -e "$ABOX_FW_STATE" && ! -L "$ABOX_FW_STATE" ]] && return 0
    validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
    tmp=$(mktemp "$ABOX_DIR/.firewall-native.forget.XXXXXX") || return 1
    while IFS='|' read -r rec_backend rec_spec rec_proto rec_scope rec_zone _rec_extra; do
        [[ "$rec_backend" == "$target_backend" && "$rec_spec" == "$spec" && "$rec_proto" == "$proto" ]] && continue
        if [[ -n "$rec_zone" ]]; then
            printf '%s|%s|%s|%s|%s\n' "$rec_backend" "$rec_spec" "$rec_proto" "$rec_scope" "$rec_zone" >> "$tmp"
        else
            printf '%s|%s|%s|%s\n' "$rec_backend" "$rec_spec" "$rec_proto" "$rec_scope" >> "$tmp"
        fi
        kept=1
    done < "$ABOX_FW_STATE"
    chown root:root "$tmp" 2>/dev/null || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" 2>/dev/null || { rm -f -- "$tmp"; return 1; }
    if (( kept == 1 )); then
        mv -f -- "$tmp" "$ABOX_FW_STATE" || { rm -f -- "$tmp"; return 1; }
    else
        rm -f -- "$tmp" "$ABOX_FW_STATE" || return 1
    fi
    return 0
}

remove_abox_native_firewall_rule() {
    local raw_spec="$1" proto="$2" spec backend fw_spec failed=0 record _backend _spec _proto _scope _zone _extra
    spec=$(normalize_port_spec "$raw_spec") || return 1
    [[ "$proto" == tcp || "$proto" == udp ]] || return 1
    backend=$(firewall_backend) || return 1
    case "$backend" in
        ufw)
            if [[ -e "$ABOX_FW_STATE" || -L "$ABOX_FW_STATE" ]]; then
                validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
                while IFS='|' read -r _backend _spec _proto _scope _zone _extra; do
                    [[ "$_spec" == "$spec" && "$_proto" == "$proto" && "$_backend" == ufw ]] || continue
                    [[ "$_scope" == rule && -z "$_zone" && -z "$_extra" ]] || return 1
                    ufw_delete_owned_rules "$spec" "$proto" || return 1
                    break
                done < "$ABOX_FW_STATE"
                forget_native_firewall_rule "$spec" "$proto" ufw || return 1
            fi
            return 0
            ;;
        firewalld)
            [[ -e "$ABOX_FW_STATE" || -L "$ABOX_FW_STATE" ]] || return 0
            validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
            fw_spec=$(port_spec_for_firewalld "$spec") || return 1
            while IFS='|' read -r _backend _spec _proto _scope _zone _extra; do
                [[ "$_spec" == "$spec" && "$_proto" == "$proto" && "$_backend" == firewalld ]] || continue
                [[ "$_scope" == runtime || "$_scope" == permanent ]] || return 1
                firewall-cmd --state >/dev/null 2>&1 || return 1
                if [[ "$_scope" == runtime ]]; then
                    if [[ -n "$_zone" ]]; then
                        firewall-cmd --zone="$_zone" --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true
                    else
                        firewalld_cmd --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true
                    fi
                    firewalld_port_state "$spec" "$proto" runtime "$_zone"
                    [[ $? == 1 ]] || failed=1
                else
                    if [[ -n "$_zone" ]]; then
                        firewall-cmd --zone="$_zone" --permanent --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true
                    else
                        firewalld_cmd --permanent --remove-port="${fw_spec}/${proto}" >/dev/null 2>&1 || true
                    fi
                    firewalld_port_state "$spec" "$proto" permanent "$_zone"
                    [[ $? == 1 ]] || failed=1
                fi
            done < "$ABOX_FW_STATE"
            (( failed == 0 )) || return 1
            forget_native_firewall_rule "$spec" "$proto" firewalld || return 1
            ;;
        iptables)
            local comment="A-Box-${spec}-${proto}" cmd check_rc
            for cmd in "$IPT" "$IPT6"; do
                [[ "$cmd" == "$IPT" || -x "$cmd" || -n "$(command -v "$cmd" 2>/dev/null)" ]] || continue
                [[ "$cmd" == "$IPT6" ]] && { command -v ip6tables >/dev/null 2>&1 || continue; _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1 || continue; }
                while :; do
                    if iptables_rule_check "$cmd" INPUT -p "$proto" --dport "$spec" -m comment --comment "$comment" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in
                        0) _iptables_do "$cmd" -D INPUT -p "$proto" --dport "$spec" -m comment --comment "$comment" -j ACCEPT >/dev/null 2>&1 || return 1 ;;
                        1) break ;;
                        *) return 1 ;;
                    esac
                done
                iptables_rule_check "$cmd" INPUT -p "$proto" --dport "$spec" -m comment --comment "$comment" -j ACCEPT
                [[ $? == 1 ]] || return 1
            done
            ;;
        *) return 1 ;;
    esac
    if [[ -e "$ABOX_FW_STATE" || -L "$ABOX_FW_STATE" ]]; then
        validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
    fi
    return 0
}

apply_native_firewall_rules_from_state() {
    [[ ! -e "$ABOX_FW_STATE" && ! -L "$ABOX_FW_STATE" ]] && return 0
    validate_native_firewall_state_file "$ABOX_FW_STATE" || return 1
    [[ "$(firewall_backend 2>/dev/null)" != 'nftables-unsupported' ]] || return 1
    local backend spec proto scope zone extra fw_spec failed=0
    while IFS='|' read -r backend spec proto scope zone extra; do
        [[ -n "$backend" ]] || continue
        case "$backend" in
            ufw)
                if ! command -v ufw >/dev/null 2>&1; then failed=1; continue; fi
                if ufw_owned_rule_exists "$spec" "$proto"; then
                    :
                elif ufw_rule_exists "$spec" "$proto"; then
                    # A foreign equivalent rule must never be adopted as A-Box-owned.
                    failed=1
                    continue
                else
                    ufw allow proto "$proto" from any to any port "$spec" comment "A-Box-${spec}-${proto}" >/dev/null 2>&1 || { failed=1; continue; }
                    ufw_owned_rule_exists "$spec" "$proto" || { failed=1; continue; }
                fi
                ;;
            firewalld)
                fw_spec=$(port_spec_for_firewalld "$spec") || { failed=1; continue; }
                command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1 || { failed=1; continue; }
                if [[ "$scope" == runtime ]]; then
                    firewalld_port_state "$spec" "$proto" runtime "$zone"
                    case $? in
                        0) : ;;
                        1) if [[ -n "$zone" ]]; then command firewall-cmd --zone="$zone" --add-port="${fw_spec}/${proto}" >/dev/null 2>&1; else firewalld_cmd --add-port="${fw_spec}/${proto}" >/dev/null 2>&1; fi || { failed=1; continue; } ;;
                        *) failed=1; continue ;;
                    esac
                    firewalld_port_state "$spec" "$proto" runtime "$zone" || failed=1
                elif [[ "$scope" == permanent ]]; then
                    firewalld_port_state "$spec" "$proto" permanent "$zone"
                    case $? in
                        0) : ;;
                        1) if [[ -n "$zone" ]]; then command firewall-cmd --zone="$zone" --permanent --add-port="${fw_spec}/${proto}" >/dev/null 2>&1; else firewalld_cmd --permanent --add-port="${fw_spec}/${proto}" >/dev/null 2>&1; fi || { failed=1; continue; } ;;
                        *) failed=1; continue ;;
                    esac
                    firewalld_port_state "$spec" "$proto" permanent "$zone" || failed=1
                else
                    failed=1
                fi
                ;;
            *) failed=1 ;;
        esac
    done < "$ABOX_FW_STATE"
    (( failed == 0 ))
}

iptables_rule_check() {
    local cmd="$1" rc; shift
    if _iptables_q "$cmd" -C "$@" 2>/dev/null; then
        return 0
    else
        rc=$?
    fi
    case "$rc" in
        1) return 1 ;;
        *) return 2 ;;
    esac
}
# F12: removed zero-call restore_iptables_saved_snapshot (duplicate dead code)

allowPort() {
    local raw_port="$1" type="${2:-tcp}" backend spec fw_spec runtime=0 permanent=0 added_runtime=0
    spec=$(normalize_port_spec "$raw_port") || die "$(tprintf fw2_bad_port "$raw_port")"
    [[ "$type" == tcp || "$type" == udp ]] || die "$(tprintf fw2_bad_proto "$type")"
    backend=$(firewall_backend)
    case "$backend" in
        iptables|ufw|firewalld) ;;
        *) die "$(tprintf fw2_nft "$backend")" ;;
    esac
    case "$backend" in
        ufw)
            if ufw_owned_rule_exists "$spec" "$type"; then
                record_native_firewall_rule ufw "$spec" "$type" rule || die "$(tr_msg fw2_ufw_record)"
            elif ufw_rule_exists "$spec" "$type"; then
                msg "${YELLOW}[!] ${spec}/${type} 已由非 A-Box UFW 全局规则放行；保留该规则且不声明所有权。${NC}"
            else
                ufw allow proto "$type" from any to any port "$spec" comment "A-Box-${spec}-${type}" >/dev/null 2>&1 || die "$(tprintf fw2_ufw_allow "${spec}/${type}")"
                if ! ufw_owned_rule_exists "$spec" "$type"; then
                    ufw_delete_owned_rules "$spec" "$type" >/dev/null 2>&1 || true
                    die "$(tprintf fw2_ufw_verify "${spec}/${type}")"
                fi
                if ! record_native_firewall_rule ufw "$spec" "$type" rule; then
                    ufw_delete_owned_rules "$spec" "$type" >/dev/null 2>&1 || true
                    die "$(tprintf fw2_ufw_record_rb "${spec}/${type}")"
                fi
            fi
            return 0
            ;;
        firewalld)
            fw_spec=$(port_spec_for_firewalld "$spec") || die "$(tprintf fw2_fwd_convert "$spec")"
            firewalld_port_state "$spec" "$type" runtime
            case $? in 0) runtime=1 ;; 1) runtime=0 ;; *) die "$(tr_msg fw2_fwd_runtime_q)" ;; esac
            firewalld_port_state "$spec" "$type" permanent
            case $? in 0) permanent=1 ;; 1) permanent=0 ;; *) die "$(tr_msg fw2_fwd_perm_q)" ;; esac
            if [[ "$runtime" == 0 ]]; then
                firewalld_cmd --add-port="${fw_spec}/${type}" >/dev/null 2>&1 || die "$(tprintf fw2_fwd_runtime_add "${fw_spec}/${type}")"
                added_runtime=1
                record_native_firewall_rule firewalld "$spec" "$type" runtime || { firewalld_cmd --remove-port="${fw_spec}/${type}" >/dev/null 2>&1 || true; die "$(tr_msg fw2_fwd_runtime_record)"; }
            fi
            if [[ "$permanent" == 0 ]]; then
                if ! firewalld_cmd --permanent --add-port="${fw_spec}/${type}" >/dev/null 2>&1; then
                    [[ "$added_runtime" == 1 ]] && firewalld_cmd --remove-port="${fw_spec}/${type}" >/dev/null 2>&1 || true
                    die "$(tprintf fw2_fwd_perm_add "${fw_spec}/${type}")"
                fi
                if ! record_native_firewall_rule firewalld "$spec" "$type" permanent; then
                    firewalld_cmd --permanent --remove-port="${fw_spec}/${type}" >/dev/null 2>&1 || true
                    [[ "$added_runtime" == 1 ]] && firewalld_cmd --remove-port="${fw_spec}/${type}" >/dev/null 2>&1 || true
                    die "$(tr_msg fw2_fwd_perm_record)"
                fi
            fi
            firewalld_port_state "$spec" "$type" runtime || die "$(tr_msg fw2_fwd_runtime_verify)"
            firewalld_port_state "$spec" "$type" permanent || die "$(tr_msg fw2_fwd_perm_verify)"
            return 0
            ;;
    esac
    local check_rc=0
    if iptables_rule_check "$IPT" INPUT -p "$type" --dport "$spec" -m comment --comment "A-Box-${spec}-${type}" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
    case "$check_rc" in
        0) ;;
        1) _iptables_do "$IPT" -I INPUT -p "$type" --dport "$spec" -m comment --comment "A-Box-${spec}-${type}" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf fw2_v4_allow "${spec}/${type}")" ;;
        *) die "$(tprintf fw2_v4_check "${spec}/${type}")" ;;
    esac
    if has_ipv6 && command -v ip6tables >/dev/null 2>&1 && _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
        if iptables_rule_check "$IPT6" INPUT -p "$type" --dport "$spec" -m comment --comment "A-Box-${spec}-${type}" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
        case "$check_rc" in
            0) ;;
            1) _iptables_do "$IPT6" -I INPUT -p "$type" --dport "$spec" -m comment --comment "A-Box-${spec}-${type}" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf fw2_v6_allow "${spec}/${type}")" ;;
            *) die "$(tprintf fw2_v6_check "${spec}/${type}")" ;;
        esac
    fi
}

remove_ss_open_accept_rules() {
    local proto failed=0 comment check_rc
    [[ -n "${SS_PORT:-}" ]] || return 0
    for proto in tcp udp; do
        comment="A-Box-${SS_PORT}-${proto}"
        while :; do
            if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
            case "$check_rc" in
                0) ;;
                1) break ;;
                *) failed=1; break ;;
            esac
            _iptables_do "$IPT" -D INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT >/dev/null 2>&1 || { failed=1; break; }
        done
        if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
        [[ "$check_rc" == 1 ]] || failed=1
        if command -v ip6tables >/dev/null 2>&1 && _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
            while :; do
                if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                case "$check_rc" in
                    0) ;;
                    1) break ;;
                    *) failed=1; break ;;
                esac
                _iptables_do "$IPT6" -D INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT >/dev/null 2>&1 || { failed=1; break; }
            done
            if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "$comment" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
            [[ "$check_rc" == 1 ]] || failed=1
        fi
    done
    (( failed == 0 ))
}

__abox_normalize_managed_rule_line() {
    local line="$1"
    line=${line//\"/}
    line=$(printf '%s\n' "$line" | sed -E 's/(^|[[:space:]])(-p[[:space:]]+(tcp|udp))[[:space:]]+-m[[:space:]]+\3([[:space:]]|$)/\1\2\4/')
    printf '%s\n' "$line"
}

# D-01: main-script copy of __abox_firewall_unlock (heredoc copy at L3032 is
# written to firewall_restore.sh and never executed by the main shell).
# $1 = lock fd value. Closes it; caller clears its own lock_fd variable.
__abox_firewall_unlock() {
    local lock_fd="$1"
    # Guard empty lock_fd: `exec >&-` would close stdout.
    if [[ "$lock_fd" =~ ^[0-9]+$ ]]; then
        eval "exec ${lock_fd}>&-" 2>/dev/null || true
    fi
}

reorder_ss_whitelist_rules_one() {
    local cmd="$1" port="$2" proto="$3" wl_suffix="$4" drop_suffix="$5"
    local wl_comment="A-Box-${port}-${proto}-${wl_suffix}" drop_comment="A-Box-${port}-${proto}-${drop_suffix}"
    local wl_re="--comment[[:space:]]+\"?${wl_comment}\"?([[:space:]]|$)" drop_re="--comment[[:space:]]+\"?${drop_comment}\"?([[:space:]]|$)"
    local save_cmd="${cmd}-save" rules_output='' recovery_snapshot='' lock_file=/run/A-Box-firewall-reorder.lock lock_fd=''
    local original_rules_output='' current_rules_output='' current_line line i j n rule_no target_idx del_idx check_rc=0 mutated=0
    local -a rules=() argv=() current_lines=() delete_lines=() delete_target_indices=() delete_rule_numbers=()
    local -a original_target_lines=() original_target_positions=() expected_target_lines=()
    local -a current_target_lines=() current_foreign_lines=() original_foreign_rules=()

    command -v "$cmd" >/dev/null 2>&1 || return 0
    command -v "$save_cmd" >/dev/null 2>&1 || return 1
    if ! _iptables_q "$cmd" -S INPUT >/dev/null 2>&1; then
        if [[ "${cmd##*/}" == ip6tables ]] && ! host_has_usable_ipv6; then return 0; fi
        return 1
    fi
    if iptables_rule_check "$cmd" INPUT -p "$proto" --dport "$port" -m comment --comment "$drop_comment" -j DROP; then check_rc=0; else check_rc=$?; fi
    case "$check_rc" in 0) ;; 1) return 0 ;; *) return 1 ;; esac

    [[ -d /run && ! -L /run ]] || return 1
    if [[ -e "$lock_file" || -L "$lock_file" ]]; then
        [[ -f "$lock_file" && ! -L "$lock_file" ]] || return 1
        [[ "$(stat -c %u:%g "$lock_file" 2>/dev/null || true)" == 0:0 ]] || return 1
        local lock_mode
        lock_mode=$(stat -c %a "$lock_file" 2>/dev/null) || return 1
        if [[ "$lock_mode" =~ ^[0-7]{3,4}$ ]]; then
            (( (8#$lock_mode & 8#077) == 0 )) || return 1
        else
            return 1
        fi
    else
        (umask 077; set -o noclobber; : > "$lock_file") 2>/dev/null || return 1
    fi
    # Open+flock before chown/chmod so the critical section starts immediately.
    exec {lock_fd}>>"$lock_file" || return 1
    flock -n "$lock_fd" || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; return 1; }
    chown root:root "$lock_file" 2>/dev/null || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; rm -f -- "$lock_file"; return 1; }
    chmod 600 "$lock_file" 2>/dev/null || { [[ "$lock_fd" =~ ^[0-9]+$ ]] && eval "exec ${lock_fd}>&-"; rm -f -- "$lock_file"; return 1; }

    capture_firewall_views() {
        local item normalized
        current_rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || return 1
        current_target_lines=()
        current_foreign_lines=()
        while IFS= read -r item; do
            [[ "$item" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
            if [[ "$item" =~ $wl_re || "$item" =~ $drop_re ]]; then
                normalized=$(__abox_normalize_managed_rule_line "$item") || return 1
                current_target_lines+=("$normalized")
            else
                current_foreign_lines+=("$item")
            fi
        done <<< "$current_rules_output"
    }
    firewall_state_matches_expected() {
        capture_firewall_views || return 1
        [[ "$(printf '%s\n' "${current_target_lines[@]}")" == "$(printf '%s\n' "${expected_target_lines[@]}")" ]] || return 1
        [[ "$(printf '%s\n' "${current_foreign_lines[@]}")" == "$(printf '%s\n' "${original_foreign_rules[@]}")" ]]
    }
    firewall_rollback() {
        local rollback_line
        local -a rollback_lines=() rollback_argv_arr=()
        [[ -n "$recovery_snapshot" && -s "$recovery_snapshot" ]] || return 1
        capture_firewall_views || return 1
        [[ "$(printf '%s\n' "${current_target_lines[@]}")" == "$(printf '%s\n' "${expected_target_lines[@]}")" ]] || {
            printf '%s\n' "A-Box firewall rollback conflict: target rules changed outside this transaction; recovery snapshot preserved at $recovery_snapshot" >&2
            return 2
        }
        [[ "$(printf '%s\n' "${current_foreign_lines[@]}")" == "$(printf '%s\n' "${original_foreign_rules[@]}")" ]] || {
            printf '%s\n' "A-Box firewall rollback conflict: non-A-Box INPUT rules changed outside this transaction; recovery snapshot preserved at $recovery_snapshot" >&2
            return 2
        }
        rollback_lines=("${current_target_lines[@]}")
        for rollback_line in "${rollback_lines[@]}"; do
            rollback_line=${rollback_line//\"/}
            read -r -a rollback_argv_arr <<< "$rollback_line"
            [[ "${rollback_argv_arr[0]:-}" == -A && "${rollback_argv_arr[1]:-}" == INPUT ]] || return 1
            _iptables_do "$cmd" -D INPUT "${rollback_argv_arr[@]:2}" >/dev/null 2>&1 || return 1
        done
        # X-01/X-02: insert in FORWARD order at original 1-based positions.
        # Reverse insertion shifts indices: each -I at an absolute position
        # displaces later rules, so reverse order scrambles the chain.
        for ((i=0; i<${#original_target_lines[@]}; i++)); do
            rollback_line=${original_target_lines[i]//\"/}
            read -r -a rollback_argv_arr <<< "$rollback_line"
            [[ "${rollback_argv_arr[0]:-}" == -A && "${rollback_argv_arr[1]:-}" == INPUT ]] || return 1
            _iptables_do "$cmd" -I INPUT "${original_target_positions[i]}" "${rollback_argv_arr[@]:2}" >/dev/null 2>&1 || return 1
        done
        capture_firewall_views || return 1
        [[ "$current_rules_output" == "$original_rules_output" ]] || return 1
        rm -f -- "$recovery_snapshot" || return 1
        recovery_snapshot=''
        return 0
    }

    recovery_snapshot=$(mktemp /run/A-Box-firewall-recovery.XXXXXX) || { __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    if ! "$save_cmd" -t filter > "$recovery_snapshot" 2>/dev/null; then
        rm -f -- "$recovery_snapshot"
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    original_rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || { rm -f -- "$recovery_snapshot"; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    capture_firewall_views || { rm -f -- "$recovery_snapshot"; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    original_target_lines=("${current_target_lines[@]}")
    original_foreign_rules=("${current_foreign_lines[@]}")
    expected_target_lines=("${original_target_lines[@]}")
    for line in "${original_target_lines[@]}"; do
        if [[ "$line" =~ $wl_re ]]; then rules+=("$line"); fi
    done
    rule_no=0
    while IFS= read -r line; do
        [[ "$line" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
        rule_no=$((rule_no + 1))
        if [[ "$line" =~ $wl_re || "$line" =~ $drop_re ]]; then
            original_target_positions+=("$rule_no")
        fi
    done <<< "$original_rules_output"
    n=${#rules[@]}

    for ((i=n-1; i>=0; i--)); do
        local expected_line="${rules[i]}"
        line=${rules[i]//\"/}
        read -r -a argv <<< "$line"
        [[ "${argv[0]:-}" == -A && "${argv[1]:-}" == INPUT ]] || { firewall_rollback >/dev/null 2>&1 || printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        firewall_state_matches_expected || {
            if (( mutated )); then
                if ! firewall_rollback; then
                    printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2
                fi
            else
                rm -f -- "$recovery_snapshot" || true
            fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        }
        if ! _iptables_do "$cmd" -I INPUT 1 "${argv[@]:2}" >/dev/null 2>&1; then
            if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        fi
        mutated=1
        expected_target_lines=("$expected_line" "${expected_target_lines[@]}")
    done
    local expected_drop_line="-A INPUT -p ${proto} --dport ${port} -m comment --comment ${drop_comment} -j DROP"
    firewall_state_matches_expected || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    if ! _iptables_do "$cmd" -I INPUT "$((n + 1))" -p "$proto" --dport "$port" -m comment --comment "$drop_comment" -j DROP >/dev/null 2>&1; then
        if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    expected_target_lines=("${expected_target_lines[@]:0:n}" "$expected_drop_line" "${expected_target_lines[@]:n}")

    rules_output=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
    current_lines=(); mapfile -t current_lines <<< "$rules_output"
    delete_lines=(); delete_target_indices=(); target_idx=0; rule_no=0
    for i in "${!current_lines[@]}"; do
        current_line="${current_lines[i]}"
        [[ "$current_line" =~ ^-A[[:space:]]+INPUT[[:space:]] ]] || continue
        rule_no=$((rule_no + 1))
        if [[ "$current_line" =~ $wl_re || "$current_line" =~ $drop_re ]]; then
            if (( target_idx > n )); then
                delete_lines+=("$current_line")
                delete_target_indices+=("$target_idx")
                delete_rule_numbers+=("$rule_no")
            fi
            target_idx=$((target_idx + 1))
        fi
    done
    for ((j=${#delete_lines[@]}-1; j>=0; j--)); do
        firewall_state_matches_expected || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        line=${delete_lines[j]//\"/}
        read -r -a argv <<< "$line"
        [[ "${argv[0]:-}" == -A && "${argv[1]:-}" == INPUT ]] || { if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi; __abox_firewall_unlock "$lock_fd"; lock_fd=''; return 1; }
        if ! _iptables_do "$cmd" -D INPUT "${delete_rule_numbers[j]}" >/dev/null 2>&1; then
            if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
            __abox_firewall_unlock "$lock_fd"; lock_fd=''
            return 1
        fi
        del_idx="${delete_target_indices[j]}"
        expected_target_lines=("${expected_target_lines[@]:0:del_idx}" "${expected_target_lines[@]:del_idx+1}")
    done
    if ! firewall_state_matches_expected; then
        if ! firewall_rollback >/dev/null 2>&1; then printf '%s\n' "A-Box firewall rollback incomplete; recovery snapshot: $recovery_snapshot" >&2; fi
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    if ! rm -f -- "$recovery_snapshot"; then
        printf '%s\n' "A-Box firewall change completed, but recovery snapshot cleanup failed; snapshot retained at $recovery_snapshot" >&2
        __abox_firewall_unlock "$lock_fd"; lock_fd=''
        return 1
    fi
    recovery_snapshot=''
    __abox_firewall_unlock "$lock_fd"; lock_fd=''
    return 0
}

# FINAL-AUDIT fix: fail-closed IPv6 firewall pre-check for SS whitelist mode.
# If the host has IPv6 but ip6tables is missing or unusable, the IPv6 DROP
# rules would be silently skipped while IPv4 gets WL ACCEPT + DROP, leaving
# SS reachable from any IPv6 address under a default-ACCEPT INPUT policy.
# Refuse BEFORE any rule is touched. Returns 1 (callers die/return).
# Objective IPv6 availability check: ignores the user's IP-preference
# setting (read_ip_pref). has_ipv6() returns false in IPv4-preferred mode
# even when the host actually has working IPv6, which would let an
# IPv6-reachable service slip through a whitelist that only filtered IPv4.
# A host with IPv6 enabled in the kernel can be reached via link-local
# (fe80::/10) even with no global address, so we check broadly. Returns 0
# if IPv6 traffic can plausibly reach the host.
host_has_usable_ipv6() {
    # (1) Kernel has IPv6 addresses (any scope, incl. link-local).
    [[ -s /proc/net/if_inet6 ]] && return 0
    # (2) IPv6 not disabled at the kernel level.
    local _d6
    _d6=$(sysctl -n net.ipv6.conf.all.disable_ipv6 2>/dev/null || printf '1')
    [[ "$_d6" != '1' ]] && return 0
    # (3) Global or link-local address visible via iproute2.
    ip -6 addr show scope global 2>/dev/null | grep -q 'inet6 ' && return 0
    ip -6 addr show scope link 2>/dev/null | grep -q 'inet6 ' && return 0
    return 1
}

# Actual ip6tables functionality probe (not just binary presence): the
# binary may exist without the kernel modules loaded.
ip6tables_usable() {
    command -v ip6tables >/dev/null 2>&1 || return 1
    _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1
}

# Snapshot all A-Box SS rules for $SS_PORT before whitelist modification,
# enabling exact restoration if a later step fails mid-setup.
# Must be called before remove_ss_open_accept_rules in each whitelist flow.
# Stores newline-separated rule specs (without the leading "-A INPUT").
_ss_wl_snapshot_rules() {
    local port="${1:-${SS_PORT:-}}"
    [[ -n "$port" ]] || return 1
    _SS_WL_SNAP_PORT="$port"
    # P2-01: distinguish "no rules" from "read failed". A failed iptables
    # query must abort the snapshot instead of being mistaken for empty.
    local out rc
    out="$(_iptables_q "$IPT" -S INPUT 2>/dev/null)"; rc=$?
    (( rc == 0 )) || return 1
    _SS_WL_SNAP_V4="$(printf '%s\n' "$out" | grep -F "A-Box-${port}-" | sed 's/^-A INPUT //')"
    _SS_WL_SNAP_V6=""
    _SS_WL_SNAP_V6_TAKEN=0
    if host_has_usable_ipv6 && ip6tables_usable; then
        out="$(_iptables_q "$IPT6" -S INPUT 2>/dev/null)"; rc=$?
        (( rc == 0 )) || return 1
        _SS_WL_SNAP_V6="$(printf '%s\n' "$out" | grep -F "A-Box-${port}-" | sed 's/^-A INPUT //')"
        _SS_WL_SNAP_V6_TAKEN=1
    fi
    _SS_WL_SNAP_TAKEN=1
    return 0
}

# Rollback SS whitelist firewall rules to snapshot state.
# Uses a single iptables-restore transaction per address family.
# Policy: A-Box rules are placed at chain head in snapshot order
# ("unified top" strategy). This is NOT exact restoration of original
# absolute positions - non-A-Box rules that were before A-Box rules
# will shift down. This is an explicit priority policy choice.
# CRITICAL: Never add :CHAIN declarations to the restore input.
# Even with --noflush, iptables-restore will flush any user-defined
# chain explicitly declared in the input stream.
_ss_wl_rollback_to_snapshot() {
    local ipt snap failed=0 restore_bin v6_ok=0 v6_needed=0
    [[ "${_SS_WL_SNAP_TAKEN:-0}" == 1 ]] || return 1
    [[ -n "${_SS_WL_SNAP_PORT:-}" ]] || return 1
    # Check if IPv6 was snapshotted and needs recovery
    [[ "${_SS_WL_SNAP_V6_TAKEN:-0}" == 1 ]] && v6_needed=1
    for ipt in "$IPT" "$IPT6"; do
        if [[ "$ipt" == "$IPT" ]]; then
            snap="$_SS_WL_SNAP_V4"
            # Match restore binary to actual backend (nft vs legacy).
            # update-alternatives may point iptables/iptables-restore to different
            # backends; detect via --version output.
            local ipt_ver restore_ver
            ipt_ver="$("$ipt" --version 2>/dev/null || echo "")"
            # Default to iptables-restore; refine if version strings indicate mismatch
            restore_bin="iptables-restore"
            if command -v "$restore_bin" >/dev/null 2>&1; then
                restore_ver="$("$restore_bin" --version 2>/dev/null || echo "")"
                # If $IPT reports nf_tables but restore does not (or vice versa),
                # try the alternative binary name
                if [[ "$ipt_ver" == *"nf_tables"* && "$restore_ver" != *"nf_tables"* ]]; then
                    command -v iptables-nft-restore >/dev/null 2>&1 && restore_bin="iptables-nft-restore"
                elif [[ "$ipt_ver" != *"nf_tables"* && "$restore_ver" == *"nf_tables"* ]]; then
                    command -v iptables-legacy-restore >/dev/null 2>&1 && restore_bin="iptables-legacy-restore"
                fi
            fi
        else
            # Skip IPv6 if it was not snapshotted (unusable at snapshot time).
            [[ "$v6_needed" == 1 ]] || continue
            snap="$_SS_WL_SNAP_V6"
            # If IPv6 was snapshotted but now unusable, mark as failed
            # (don't silently skip)
            if ! ip6tables_usable; then failed=1; continue; fi
            # G7: match IPv6 restore binary to actual backend (nft vs legacy)
            local ipt6_ver restore6_ver
            ipt6_ver="$("$ipt" --version 2>/dev/null || echo "")"
            restore_bin="ip6tables-restore"
            if command -v "$restore_bin" >/dev/null 2>&1; then
                restore6_ver="$("$restore_bin" --version 2>/dev/null || echo "")"
                if [[ "$ipt6_ver" == *"nf_tables"* && "$restore6_ver" != *"nf_tables"* ]]; then
                    command -v ip6tables-nft-restore >/dev/null 2>&1 && restore_bin="ip6tables-nft-restore"
                elif [[ "$ipt6_ver" != *"nf_tables"* && "$restore6_ver" == *"nf_tables"* ]]; then
                    command -v ip6tables-legacy-restore >/dev/null 2>&1 && restore_bin="ip6tables-legacy-restore"
                fi
            fi
        fi
        command -v "$restore_bin" >/dev/null 2>&1 || { failed=1; continue; }
        local cur_out cur_rc
        cur_out="$(_iptables_q "$ipt" -S INPUT 2>/dev/null)"; cur_rc=$?
        if (( cur_rc != 0 )); then failed=1; continue; fi
        local cur
        cur="$(printf '%s\n' "$cur_out" | grep -F "A-Box-${_SS_WL_SNAP_PORT}-" | sed 's/^-A INPUT //')"
        local restore_input="*filter"
        local line pos
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            restore_input+=$'\n-D INPUT '"$line"
        done <<< "$cur"
        pos=1
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            restore_input+=$'\n-I INPUT '"$pos"' '"$line"
            (( pos++ ))
        done <<< "$snap"
        restore_input+=$'\nCOMMIT'
        # G5: strict payload guard
        if ! awk '
            NR == 1 { if ($0 != "*filter") exit 1; next }
            { lines[NR] = $0 }
            END {
                if (NR < 2 || lines[NR] != "COMMIT") exit 1
                for (i = 2; i < NR; i++) {
                    if (lines[i] !~ /^-(D|I) INPUT /) exit 1
                }
            }
        ' <<< "$restore_input" || [[ "${restore_input//$'\n'/}" == *[[:cntrl:]]* ]]; then
            printf '%s\n' 'ERROR: internal error: restore payload failed strict line guard' >&2
            failed=1
            continue
        fi
        if "$restore_bin" --help 2>&1 | grep -q -- "--test"; then
            if ! printf '%s\n' "$restore_input" | "$restore_bin" --noflush -w 5 --test >/dev/null 2>&1 &&
               ! printf '%s\n' "$restore_input" | "$restore_bin" --noflush --test >/dev/null 2>&1; then
                printf '%s\n' 'ERROR: restore payload failed --test pre-check' >&2
                failed=1
                continue
            fi
        fi
        local restore_rc=0 w_probe_err=''
        # F10: distinguish option syntax error from lock contention timeout
        w_probe_err="$(printf '*filter\nCOMMIT\n' | "$restore_bin" --noflush -w 0 --test 2>&1 >/dev/null || true)"
        if ! grep -qiE 'unrecognized option|unknown option|invalid option|bad argument' <<< "$w_probe_err"; then
            # Modern: use built-in wait
            printf '%s\n' "$restore_input" | "$restore_bin" --noflush -w 5 >/dev/null 2>&1
            restore_rc=$?
        elif command -v flock >/dev/null 2>&1 && [[ -e /run/xtables.lock || -e /var/run/xtables.lock ]]; then
            # Legacy: wrap with flock (do not combine with -w to avoid self-deadlock)
            local lock_file="/run/xtables.lock"
            [[ -e "$lock_file" ]] || lock_file="/var/run/xtables.lock"
            printf '%s\n' "$restore_input" | flock -w 5 "$lock_file" "$restore_bin" --noflush >/dev/null 2>&1
            restore_rc=$?
        else
            # Pre-1.6.2 (e.g. 1.4.x): no -w support and no file lock.
            # 1.4.x restore never locked natively, so run unlocked best-effort.
            printf '%s\n' 'WARNING: pre-1.6.2 iptables has no file lock; running unlocked rollback (best effort).' >&2
            printf '%s\n' "$restore_input" | "$restore_bin" --noflush >/dev/null 2>&1
            restore_rc=$?
        fi
        if (( restore_rc != 0 )); then
            failed=1
            continue
        fi
        # Verify: check that first N rules of INPUT match snapshot in order
        # (N = number of snapshot rules), proving they are at chain head.
        # Use normalized comparison to handle -m tcp / quote variations.
        local final_out final_rc
        final_out="$(_iptables_q "$ipt" -S INPUT 2>/dev/null)"; final_rc=$?
        if (( final_rc != 0 )); then failed=1; continue; fi
        local snap_count
        snap_count="$(printf '%s\n' "$snap" | grep -c -v '^$' || true)"
        local head_rules normalized_head normalized_expected
        head_rules="$(printf '%s\n' "$final_out" | grep "^-A INPUT " | head -n "$snap_count" | sed 's/^-A INPUT //')"
        # Normalize both sides for comparison
        normalized_head=""
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            line="$(__abox_normalize_managed_rule_line "$line" 2>/dev/null || printf '%s' "$line")"
            normalized_head+="$line"$'\n'
        done <<< "$head_rules"
        normalized_expected=""
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            line="$(__abox_normalize_managed_rule_line "$line" 2>/dev/null || printf '%s' "$line")"
            normalized_expected+="$line"$'\n'
        done <<< "$snap"
        if [[ "$normalized_head" != "$normalized_expected" ]]; then
            failed=1
            continue
        fi
        # Also verify full A-Box rule set matches (no extras/missing)
        # Compare normalized full sets (order-independent for this check,
        # as head-order was already verified above)
        local final normalized_final
        final="$(printf '%s\n' "$final_out" | grep -F "A-Box-${_SS_WL_SNAP_PORT}-" | sed 's/^-A INPUT //')"
        normalized_final=""
        while IFS= read -r line; do
            [[ -n "$line" ]] || continue
            line="$(__abox_normalize_managed_rule_line "$line" 2>/dev/null || printf '%s' "$line")"
            normalized_final+="$line"$'\n'
        done <<< "$final"
        # Sort both for order-independent comparison
        if [[ "$(printf '%s' "$normalized_final" | sort)" != "$(printf '%s' "$normalized_expected" | sort)" ]]; then
            failed=1
            continue
        fi
        # Mark IPv6 as successfully recovered (IPv4 success is tracked via failed==0)
        if [[ "$ipt" != "$IPT" ]]; then v6_ok=1; fi
    done
    # Cross-family check: if IPv6 was needed but not recovered, fail overall
    if (( v6_needed == 1 && v6_ok == 0 )); then
        failed=1
    fi
    if (( failed != 0 )); then
        local fail_fams=""
        # v4 failed if overall failed and v6 either not needed or succeeded
        # (v6 failure is tracked separately via v6_ok)
        if (( v6_needed == 0 || v6_ok == 1 )); then
            fail_fams="IPv4"
        fi
        (( v6_needed == 1 && v6_ok == 0 )) && fail_fams="${fail_fams:+$fail_fams,}IPv6"
        printf '%s\n' "ERROR: firewall rollback incomplete (${fail_fams:-unknown}); manual recovery required." >&2
        printf '%s\n' "Check: iptables -S INPUT / ip6tables -S INPUT against snapshot." >&2
        return 1
    fi
    _SS_WL_SNAP_TAKEN=0
    _SS_WL_SNAP_PORT=""
    return 0
}

ss_whitelist_ipv6_precheck() {
    # Use the objective check, not has_ipv6(): a host in IPv4-preferred mode
    # may still be reachable over IPv6, and the whitelist must cover it.
    # The ip6tables_usable() probe is a real functionality test, not just
    # a binary-presence check.
    if host_has_usable_ipv6; then
        ip6tables_usable || return 1
    fi
    return 0
}

enforce_ss_whitelist_order() {
    local port="${1:-${SS_PORT:-}}" failed=0 proto
    if (( $# == 0 )) && [[ -z "${SS_PORT:-}" ]]; then
        return 0
    fi
    # G8: invalid port must fail, not silently succeed.
    valid_port "$port" || return 1
    # FINAL-AUDIT: fail closed here too (defense in depth for restore paths).
    ss_whitelist_ipv6_precheck || return 1
    for proto in tcp udp; do
        reorder_ss_whitelist_rules_one "$IPT" "$port" "$proto" WL DROP || failed=1
        # Objective check (not has_ipv6()): never silently skip the IPv6 path
        # when the host is actually IPv6-reachable. The precheck above already
        # guaranteed ip6tables works in that case, so a failure here is real.
        if host_has_usable_ipv6; then
            reorder_ss_whitelist_rules_one "$IPT6" "$port" "$proto" WL6 DROP6 || failed=1
        fi
    done
    (( failed == 0 ))
}

clean_nat_rules() {
    [[ "$(firewall_backend 2>/dev/null)" != 'nftables-unsupported' ]] || {
        msg "${RED}Native nftables rules detected; refusing to mutate a parallel iptables ruleset.${NC}"
        return 1
    }
    local output rule failed=0 owned_re ipv6_nat_error
    local -a argv=()
    owned_re='--comment "?A-Box-HY2-HOP"?([ \t\r]|$)'
    while :; do
        output=$(_iptables_q "$IPT" -t nat -S PREROUTING 2>/dev/null) || { failed=1; break; }
        rule=$(awk -v re="$owned_re" '$0 ~ re { sub(/^-A /,"-D "); print; exit }' <<< "$output")
        [[ -n "$rule" ]] || break
        rule=${rule//\"/}
        read -r -a argv <<< "$rule"
        _iptables_do "$IPT" -t nat "${argv[@]}" >/dev/null 2>&1 || { failed=1; break; }
    done
    if command -v ip6tables >/dev/null 2>&1; then
        if _iptables_q "$IPT6" -t nat -S PREROUTING >/dev/null 2>&1; then
            while :; do
                output=$(_iptables_q "$IPT6" -t nat -S PREROUTING 2>/dev/null) || { failed=1; break; }
                rule=$(awk -v re="$owned_re" '$0 ~ re { sub(/^-A /,"-D "); print; exit }' <<< "$output")
                [[ -n "$rule" ]] || break
                rule=${rule//\"/}
                read -r -a argv <<< "$rule"
                _iptables_do "$IPT6" -t nat "${argv[@]}" >/dev/null 2>&1 || { failed=1; break; }
            done
        else
            ipv6_nat_error=$(_iptables_q "$IPT6" -t nat -S PREROUTING 2>&1 >/dev/null || true)
            if ! grep -Eiq "table ['\"]?nat['\"]? does not exist|table does not exist|table nat is not supported|protocol not supported|can't initialize ip6tables table ['\"]nat['\"]|cannot initialize ip6tables table ['\"]nat['\"]|table ['\"]nat['\"] is incompatible, use ['\"]nft['\"] tool" <<< "$ipv6_nat_error"; then
                failed=1
            fi
        fi
    elif has_ipv6; then
        # Without the binary, previously managed IPv6 rules cannot be inspected.
        failed=1
    fi
    (( failed == 0 ))
}

clean_input_rules() {
    [[ "$(firewall_backend 2>/dev/null)" != 'nftables-unsupported' ]] || {
        msg "${RED}Native nftables rules detected; refusing to mutate a parallel iptables ruleset.${NC}"
        return 1
    }
    local output rule failed=0 owned_re
    local -a argv=()
    owned_re='--comment "?A-Box-[0-9]+(:[0-9]+)?-(tcp|udp)(-(WL6?|DROP6?))?"?([ \t\r]|$)'
    remove_native_firewall_rules 2>/dev/null || failed=1
    while :; do
        output=$(_iptables_q "$IPT" -S INPUT 2>/dev/null) || { failed=1; break; }
        rule=$(awk -v re="$owned_re" '$0 ~ re { sub(/^-A /,"-D "); print; exit }' <<< "$output")
        [[ -n "$rule" ]] || break
        rule=${rule//\"/}
        read -r -a argv <<< "$rule"
        _iptables_do "$IPT" "${argv[@]}" >/dev/null 2>&1 || { failed=1; break; }
    done
    if command -v ip6tables >/dev/null 2>&1; then
        if _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
            while :; do
                output=$(_iptables_q "$IPT6" -S INPUT 2>/dev/null) || { failed=1; break; }
                rule=$(awk -v re="$owned_re" '$0 ~ re { sub(/^-A /,"-D "); print; exit }' <<< "$output")
                [[ -n "$rule" ]] || break
                rule=${rule//\"/}
                read -r -a argv <<< "$rule"
                _iptables_do "$IPT6" "${argv[@]}" >/dev/null 2>&1 || { failed=1; break; }
            done
        elif has_ipv6; then
            failed=1
        fi
    elif has_ipv6; then
        failed=1
    fi
    (( failed == 0 ))
}

add_port_pair() {
    local arr_name="$1" proto="$2" port="$3"
    [[ -n "$port" && "$port" =~ ^[0-9]+$ ]] || return 0
    printf -v "$arr_name" '%s%s/%s\n' "${!arr_name}" "$proto" "$port"
}

hy2_http01_enabled() {
    local core="${1:-${CORE_IN:-${CORE:-}}}" mode="${2:-${MODE_IN:-${MODE:-}}}"
    [[ -n "${HY2_DOMAIN:-}" && "${HY2_ACME_TYPE:-http}" == http &&
       ( "$core" == 'hysteria' || ( "$core" == 'xray' && "$mode" == *'ALL'* ) ) ]]
}

selected_port_pairs() {
    local pairs=''
    add_port_pair pairs tcp "${VLESS_PORT:-}"
    add_port_pair pairs tcp "${XHTTP_PORT:-}"
    add_port_pair pairs tcp "${SS_PORT:-}"
    add_port_pair pairs udp "${SS_PORT:-}"
    if hy2_http01_enabled; then
        add_port_pair pairs tcp 80
    fi
    # Native Hysteria official range mode listens on the first range port; the
    # separate base port is only real for non-hopping/manual redirect modes.
    if [[ "${HY2_HOP:-}" != true || "${HY2_HOP_IMPL:-none}" != official ]]; then
        add_port_pair pairs udp "${HY2_BASE_PORT:-}"
    fi
    printf '%s' "$pairs"
}

check_selected_ports_free() {
    msg "${YELLOW}[*] 正在检查新选择端口是否仍被任何进程占用...${NC}"
    local pairs pair proto p holder dup line
    pairs=$(selected_port_pairs | awk 'NF')
    dup=$(printf '%s\n' "$pairs" | awk 'NF { seen[$0]++ } END { for (k in seen) if (seen[k] > 1) { print k; break } }')
    [[ -n "$dup" ]] && die "$(tprintf pt_dup "$dup")"

    if [[ "${HY2_HOP:-}" == 'true' && -n "${HY2_RANGE_START:-}" && -n "${HY2_RANGE_END:-}" ]]; then
        for pair in $pairs; do
            proto=${pair%/*}; p=${pair#*/}
            if [[ "$proto" == 'udp' ]] && (( 10#$p >= 10#$HY2_RANGE_START && 10#$p <= 10#$HY2_RANGE_END )); then
                die "$(tprintf pt_hy2_range "$p" "$HY2_RANGE_START" "$HY2_RANGE_END")"
            fi
        done
    fi

    command -v ss >/dev/null 2>&1 || die "$(tr_msg pt_no_ss)"
    for pair in $pairs; do
        proto=${pair%/*}; p=${pair#*/}
        if ! holder=$(ss -H -n -l -p -A "$proto" 2>/dev/null); then
            die "$(tprintf pt_ss_fail "${p}/${proto}")"
        fi
        holder=$(awk -v p="$p" '$4 ~ ("[:.]" p "$") || $5 ~ ("[:.]" p "$") { print }' <<< "$holder" || true)
        [[ -z "$holder" ]] && continue
        msg "${RED}[!] 新选择端口 ${p}/${proto} 仍被进程占用：${NC}"
        printf '%s\n' "$holder"
        die "$(tprintf pt_release_manual "${p}/${proto}")"
    done

    if [[ "${HY2_HOP:-}" == 'true' && -n "${HY2_RANGE_START:-}" && -n "${HY2_RANGE_END:-}" ]]; then
        local ss_udp_output
        if ! ss_udp_output=$(ss -H -n -l -p -A udp 2>/dev/null); then
            die "$(tr_msg pt_hy2_ss_fail)"
        fi
        holder=''
        if [[ -n "$ss_udp_output" ]]; then
            while IFS= read -r line; do
                # FIX: ss UDP columns are Netid/State/Recv-Q/Send-Q/Local/Peer/Process,
                # so $5 is the Local address and $4 is Send-Q (a bare number like "0").
                # Using $4 always yields empty p (dead check). Use $5, falling back
                # to $4 for ss variants with different column layouts.
                p=$(awk '{print $5}' <<< "$line" | sed -nE 's/.*[:.]([0-9]+)$/\1/p')
                if [[ -z "$p" ]]; then
                    p=$(awk '{print $4}' <<< "$line" | sed -nE 's/.*[:.]([0-9]+)$/\1/p')
                fi
                [[ "$p" =~ ^[0-9]+$ ]] || continue
                if (( 10#$p >= 10#$HY2_RANGE_START && 10#$p <= 10#$HY2_RANGE_END )); then
                    holder+="$line"$'\n'
                fi
            done <<< "$ss_udp_output"
        fi
        if [[ -n "$holder" ]]; then
            msg "${RED}[!] HY2 UDP 跳跃区间 ${HY2_RANGE_START}-${HY2_RANGE_END} 仍被进程占用：${NC}"
            printf '%s' "$holder"
            die "$(tr_msg pt_hy2_release)"
        fi
    fi
}

release_ports() {
    msg "${YELLOW}[*] 正在停止 A-Box 托管服务...${NC}"
    stop_all_managed_services || die "$(tr_msg pt_stop_all)"
    sleep 1
    local pairs pair proto p holder
    pairs=$(selected_port_pairs | awk 'NF' | sort -u)
    if [[ -z "$pairs" ]]; then
        # Fresh install / empty .env: ports are chosen in the wizard after this
        # step. Occupancy for the newly selected ports is enforced by
        # check_selected_ports_free at the end of pre_install_setup.
        msg "${YELLOW}[*] 当前尚未选定监听端口；端口占用检查将在参数向导完成后执行。${NC}"
        return 0
    fi
    msg "${YELLOW}[*] 正在检查已配置端口占用...${NC}"
    command -v ss >/dev/null 2>&1 || die "$(tr_msg pt_no_ss)"
    for pair in $pairs; do
        proto=${pair%/*}; p=${pair#*/}
        if ! holder=$(ss -H -n -l -p -A "$proto" 2>/dev/null); then
            die "$(tprintf pt_ss_fail "${p}/${proto}")"
        fi
        holder=$(awk -v p="$p" '$4 ~ ("[:.]" p "$") || $5 ~ ("[:.]" p "$") { print }' <<< "$holder" || true)
        [[ -z "$holder" ]] && continue
        msg "${YELLOW}[!] 旧配置端口 ${p}/${proto} 当前被非 A-Box 进程占用；若向导中继续选择该端口需先手动释放，改选其它新端口则不受影响。${NC}"
    done
}


write_if_changed() {
    local target="$1" tmp="$2" mode="${3:-700}"
    if [[ -f "$target" && ! -L "$target" ]] && cmp -s "$tmp" "$target"; then
        rm -f "$tmp"
    else
        install_file_atomically "$tmp" "$target" "$mode" || { rm -f "$tmp"; return 1; }
        rm -f "$tmp"
    fi
}

validate_abox_script_file() {
    local f="$1" context="${2:-script}"
    [[ -s "$f" ]] || { printf '%s\n' "$(tprintf vs_empty "$context")" >&2; return 1; }
    bash -n "$f" >/dev/null 2>&1 || { printf '%s\n' "$(tprintf vs_syntax "$context")" >&2; return 1; }
    grep -q '==============================A-Box===============================' "$f" || { printf '%s\n' "$(tprintf vs_fingerprint "$context")" >&2; return 1; }
    grep -q '^main "\$@"' "$f" || { printf '%s\n' "$(tprintf vs_entry "$context")" >&2; return 1; }
}


resolve_abox_main_commit_url() {
    local api='https://api.github.com/repos/alariclin/A-Box/commits/main' json sha
    json=$(github_api_get "$api") || return 1
    sha=$(jq -r '.sha // empty' <<< "$json" 2>/dev/null)
    [[ "$sha" =~ ^[0-9a-f]{40}$ ]] || return 1
    printf 'https://raw.githubusercontent.com/alariclin/A-Box/%s/install.sh\n' "$sha"
}

install_remote_abox_script_guarded() {
    local url="$1" dest="$2" tmp sha resolved_url
    if [[ "$url" == 'https://raw.githubusercontent.com/alariclin/A-Box/main/install.sh' ]]; then
        resolved_url=$(resolve_abox_main_commit_url) || die "$(tr_msg ir_resolve)"
        url="$resolved_url"
    fi
    tmp=$(umask 077; mktemp /tmp/A-Box-script.XXXXXX.sh) || die "$(tr_msg ir_tmp)"
    abox_run_wait "$(tr_msg ir_dl_label)" curl -fLs --connect-timeout 10 -m 60 "$url" -o "$tmp" || { rm -f -- "$tmp"; die "$(tr_msg ir_download)"; }
    if ! ( validate_abox_script_file "$tmp" '远端 A-Box 脚本' && validate_ota_version_direction "$tmp" ); then
        rm -f -- "$tmp"
        die "$(tr_msg ir_verify)"
    fi
    sha=$(sha256sum "$tmp" | awk '{print $1}')
    msg "${YELLOW}[*] Remote script SHA256: ${sha}${NC}"
    confirm_ota_script_hash "$sha" "$url" || { rm -f -- "$tmp"; die "$(tr_msg ir_cancelled)"; }
    write_if_changed "$dest" "$tmp" 700 || { rm -f -- "$tmp"; die "$(tr_msg ir_persist)"; }
    rm -f -- "$tmp"
}

setup_shortcut() {
    ensure_abox_dir_owned "$ABOX_DIR" || return 1
    if [[ -f "$0" && -r "$0" && "$0" != 'bash' && "$0" != '-bash' ]]; then
        validate_abox_script_file "$0" "$(tr_msg ss2_ctx_current)" || die "$(tr_msg ss2_self_verify)"
        if [[ -f "$ABOX_DIR/A-Box.sh" ]]; then
            local current_build_epoch remote_build_epoch
            current_build_epoch=$(awk -F= '/^ABOX_BUILD_EPOCH=/{gsub(/[^0-9]/,"",$2); print $2; exit}' "$ABOX_DIR/A-Box.sh" 2>/dev/null || true)
            remote_build_epoch=$(awk -F= '/^ABOX_BUILD_EPOCH=/{gsub(/[^0-9]/,"",$2); print $2; exit}' "$0" 2>/dev/null || true)
            if [[ "$current_build_epoch" =~ ^[0-9]+$ && "$remote_build_epoch" =~ ^[0-9]+$ ]] && (( 10#$remote_build_epoch < 10#$current_build_epoch )); then
                confirm_yes_no "$(tr_msg ss2_downgrade_prompt)" || die "$(tr_msg ss2_refuse_downgrade)"
            fi
        fi
        if [[ ! -f "$ABOX_DIR/A-Box.sh" ]] || ! cmp -s "$0" "$ABOX_DIR/A-Box.sh"; then
            install_binary_atomically "$0" "$ABOX_DIR/A-Box.sh" || die "$(tr_msg ss2_persist)"
        fi
    else
        # A piped invocation has no readable $0 file to persist.
        if [[ -f "$ABOX_DIR/A-Box.sh" && ! -L "$ABOX_DIR/A-Box.sh" ]]; then
            local installed_epoch=''
            installed_epoch=$(awk -F= '/^ABOX_BUILD_EPOCH=/{gsub(/[^0-9]/,"",$2); print $2; exit}' "$ABOX_DIR/A-Box.sh" 2>/dev/null || true)
            if [[ "$installed_epoch" =~ ^[0-9]+$ ]] && (( 10#$installed_epoch > 10#$ABOX_BUILD_EPOCH )); then
                msg "${YELLOW}[!] 保留磁盘中较新的 A-Box 脚本版本 (${installed_epoch})；拒绝从管道运行的旧版本覆盖。${NC}"
            else
                install_remote_abox_script_guarded "$SCRIPT_URL" "$ABOX_DIR/A-Box.sh"
            fi
        else
            install_remote_abox_script_guarded "$SCRIPT_URL" "$ABOX_DIR/A-Box.sh"
        fi
    fi
    [[ -f "$ABOX_DIR/A-Box.sh" ]] || die "$(tr_msg ss2_persist_missing)"
    validate_abox_script_file "$ABOX_DIR/A-Box.sh" "$(tr_msg ss2_ctx_persisted)" || die "$(tr_msg ss2_persist_verify)"
    chmod +x "$ABOX_DIR/A-Box.sh" || die "$(tr_msg ss2_chmod)"

    local shortcut_tmp
    shortcut_tmp=$(umask 077; mktemp /tmp/A-Box-sb.XXXXXX) || die "$(tr_msg ss2_tmp)"
    cat > "$shortcut_tmp" <<'EOS' || { rm -f -- "$shortcut_tmp"; die '快捷入口临时文件写入失败。'; }
#!/usr/bin/env bash
# Managed by A-Box
if [[ $EUID -eq 0 ]]; then
    exec bash /etc/ddr/A-Box.sh "$@"
elif command -v sudo >/dev/null 2>&1; then
    exec sudo bash /etc/ddr/A-Box.sh "$@"
else
    echo 'Root privileges required. Please run: su -'
    exit 1
fi
EOS
    chmod 755 "$shortcut_tmp" || { rm -f -- "$shortcut_tmp"; die "$(tr_msg ss2_tmp_chmod)"; }
    if ! assert_abox_shortcut_safe /usr/local/bin/sb; then
        rm -f -- "$shortcut_tmp"
        die "$(tr_msg ss2_sb_unsafe)"
    fi
    if [[ ! -f /usr/local/bin/sb ]] || ! cmp -s "$shortcut_tmp" /usr/local/bin/sb; then
        install_binary_atomically "$shortcut_tmp" /usr/local/bin/sb || { rm -f -- "$shortcut_tmp"; die "$(tr_msg ss2_write)"; }
    fi
    rm -f -- "$shortcut_tmp"
}
validate_downloaded_asset() {
    local asset_name="$1" f="${2:-/tmp/$1}" magic=''
    [[ -s "$f" ]] || { printf '%s\n' "$(tprintf va_empty "$asset_name")" >&2; return 1; }
    case "$asset_name" in
        xray_core.zip)
            unzip -tqq "$f" >/dev/null 2>&1 || { printf '%s\n' "$(tr_msg va_xray_zip)" >&2; return 1; }
            ;;
        singbox_core.tar.gz)
            tar -tzf "$f" >/dev/null 2>&1 || { printf '%s\n' "$(tr_msg va_sb_tar)" >&2; return 1; }
            ;;
        hysteria_core)
            magic=$(head -c 4 "$f" | od -An -tx1 | tr -d ' \n' || true)
            [[ "$magic" == '7f454c46' ]] || { printf '%s\n' "$(tr_msg va_hy2_elf)" >&2; return 1; }
            ;;
        *)
            printf '%s\n' "$(tprintf va_undefined "$asset_name")" >&2
            return 1
            ;;
    esac
}


validate_core_asset_binary_version() {
    local asset_name="${1:-}" f="${2:-}" expected_ref="${3:-}" workdir='' binary='' output=''
    [[ -s "$f" && -n "$expected_ref" ]] || return 1
    workdir=$(mktemp -d /tmp/A-Box-core-version.XXXXXX) || return 1
    case "$asset_name" in
        xray_core.zip)
            binary="$workdir/xray"
            if ! extract_zip_member_safely "$f" xray "$binary"; then rm -rf -- "$workdir"; return 1; fi
            chmod 700 "$binary" || { rm -rf -- "$workdir"; return 1; }
            output=$("$binary" version 2>&1) || { rm -rf -- "$workdir"; return 1; }
            ;;
        singbox_core.tar.gz)
            binary="$workdir/sing-box"
            if ! extract_tar_regular_basename_safely "$f" sing-box "$binary"; then rm -rf -- "$workdir"; return 1; fi
            chmod 700 "$binary" || { rm -rf -- "$workdir"; return 1; }
            output=$("$binary" version 2>&1) || { rm -rf -- "$workdir"; return 1; }
            ;;
        hysteria_core)
            chmod 700 "$f" 2>/dev/null || { rm -rf -- "$workdir"; return 1; }
            output=$("$f" version 2>&1) || { rm -rf -- "$workdir"; return 1; }
            ;;
        *) rm -rf -- "$workdir"; return 1 ;;
    esac
    if ! core_binary_matches_release_ref "$expected_ref" "$output"; then
        printf 'Core binary version does not match selected Release tag %s: %s\n' "$expected_ref" "$output" >&2
        rm -rf -- "$workdir"
        return 1
    fi
    rm -rf -- "$workdir"
    return 0
}

extract_zip_member_safely() {
    local archive="$1" member="$2" dest="$3"
    [[ -s "$archive" && -n "$member" && -n "$dest" ]] || return 1
    python3 - "$archive" "$member" "$dest" <<'PY_ZIP_EXTRACT'
import os, shutil, stat, sys, zipfile
archive, member, dest = sys.argv[1:]
MAX_FILE = 512 * 1024 * 1024
created = False
try:
    if os.path.lexists(dest): raise ValueError('destination exists')
    with zipfile.ZipFile(archive) as zf:
        matches = [x for x in zf.infolist() if x.filename == member]
        if len(matches) != 1: raise ValueError('member count')
        info = matches[0]
        mode = (info.external_attr >> 16) & 0o170000
        if info.is_dir() or mode == stat.S_IFLNK: raise ValueError('not regular')
        if info.file_size <= 0 or info.file_size > MAX_FILE: raise ValueError('size')
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, 'O_NOFOLLOW'): flags |= os.O_NOFOLLOW
        fd = os.open(dest, flags, 0o600)
        created = True
        try:
            with zf.open(info, 'r') as src, os.fdopen(fd, 'wb', closefd=False) as out:
                remaining = MAX_FILE + 1
                while True:
                    chunk = src.read(min(1024 * 1024, remaining))
                    if not chunk: break
                    out.write(chunk); remaining -= len(chunk)
                    if remaining <= 0: raise ValueError('expanded size')
                out.flush(); os.fsync(out.fileno())
        finally:
            os.close(fd)
except Exception:
    if created:
        try: os.unlink(dest)
        except OSError: pass
    raise SystemExit(1)
PY_ZIP_EXTRACT
}

extract_tar_regular_basename_safely() {
    local archive="$1" basename="$2" dest="$3"
    [[ -s "$archive" && "$basename" =~ ^[A-Za-z0-9._-]+$ && -n "$dest" ]] || return 1
    python3 - "$archive" "$basename" "$dest" <<'PY_TAR_EXTRACT'
import os, posixpath, sys, tarfile
archive, wanted, dest = sys.argv[1:]
MAX_MEMBERS = 10000
MAX_FILE = 512 * 1024 * 1024
created = False
try:
    if os.path.lexists(dest): raise ValueError('destination exists')
    with tarfile.open(archive, 'r:gz') as tf:
        members = tf.getmembers()
        if len(members) > MAX_MEMBERS: raise ValueError('member count')
        matches = []
        for m in members:
            raw = m.name
            if '\x00' in raw or raw.startswith('/'): raise ValueError('path')
            while raw.startswith('./'): raw = raw[2:]
            norm = posixpath.normpath(raw)
            if norm in ('', '.'):
                continue
            if norm == '..' or norm.startswith('../'): raise ValueError('path')
            if m.issym() or m.islnk() or m.ischr() or m.isblk() or m.isfifo() or m.isdev():
                raise ValueError('special member')
            if not (m.isfile() or m.isdir()): raise ValueError('unknown member')
            if m.isfile() and posixpath.basename(norm) == wanted:
                matches.append(m)
        if len(matches) != 1: raise ValueError('binary member count')
        target = matches[0]
        if target.size <= 0 or target.size > MAX_FILE: raise ValueError('size')
        src = tf.extractfile(target)
        if src is None: raise ValueError('extract')
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, 'O_NOFOLLOW'): flags |= os.O_NOFOLLOW
        fd = os.open(dest, flags, 0o600)
        created = True
        try:
            with src, os.fdopen(fd, 'wb', closefd=False) as out:
                remaining = MAX_FILE + 1
                while True:
                    chunk = src.read(min(1024 * 1024, remaining))
                    if not chunk: break
                    out.write(chunk); remaining -= len(chunk)
                    if remaining <= 0: raise ValueError('expanded size')
                out.flush(); os.fsync(out.fileno())
        finally:
            os.close(fd)
except Exception:
    if created:
        try: os.unlink(dest)
        except OSError: pass
    raise SystemExit(1)
PY_TAR_EXTRACT
}

github_api_get() {
    local url="$1" attempt=1 max_attempts=3 delay=1 rc http_code tmp headers retry_after remaining reset_epoch now
    local -a args=()
    [[ -n "$url" ]] || return 1
    if [[ "${GITHUB_API_RETRY_DELAY:-1}" =~ ^[0-9]+$ ]]; then
        delay="${GITHUB_API_RETRY_DELAY:-1}"
    elif [[ -n "${GITHUB_API_RETRY_DELAY:-}" ]]; then
        return 1
    fi
    tmp=$(umask 077; mktemp /tmp/A-Box-github-api.XXXXXX) || return 1
    headers=$(umask 077; mktemp /tmp/A-Box-github-api-headers.XXXXXX) || { rm -f -- "$tmp"; return 1; }
    args=(-sS -L --connect-timeout 10 -m 60 -D "$headers"
        -H 'Accept: application/vnd.github+json'
        -H 'X-GitHub-Api-Version: 2026-03-10' -o "$tmp")
    while (( attempt <= max_attempts )); do
        : > "$headers" || { rm -f -- "$tmp" "$headers"; return 1; }
        if [[ -n "${GITHUB_TOKEN:-}" ]]; then
            [[ "${GITHUB_TOKEN}" != *[$'\r\n"\\']* ]] || { rm -f -- "$tmp" "$headers"; return 1; }
            http_code=$(printf 'header = "Authorization: Bearer %s"\n' "$GITHUB_TOKEN" | curl "${args[@]}" -w '%{http_code}' --config - "$url" 2>/dev/null)
            rc=$?
        else
            http_code=$(curl "${args[@]}" -w '%{http_code}' "$url" 2>/dev/null)
            rc=$?
        fi
        if (( rc == 0 )) && [[ "$http_code" =~ ^2[0-9][0-9]$ ]]; then
            cat -- "$tmp"
            rc=$?
            rm -f -- "$tmp" "$headers"
            return "$rc"
        fi
        retry_after=$(awk 'tolower($1)=="retry-after:" {gsub("\r","",$2); value=$2} END {print value}' "$headers" 2>/dev/null)
        remaining=$(awk 'tolower($1)=="x-ratelimit-remaining:" {gsub("\r","",$2); value=$2} END {print value}' "$headers" 2>/dev/null)
        reset_epoch=$(awk 'tolower($1)=="x-ratelimit-reset:" {gsub("\r","",$2); value=$2} END {print value}' "$headers" 2>/dev/null)
        if (( rc == 0 )) && [[ "$http_code" =~ ^5[0-9][0-9]$ ]]; then
            :
        elif (( rc == 0 )) && { [[ "$http_code" == 429 ]] || { [[ "$http_code" == 403 ]] && { [[ "$remaining" == 0 ]] || [[ -n "$retry_after" ]]; }; }; }; then
            if [[ "$retry_after" =~ ^[0-9]+$ ]]; then
                delay=$retry_after
            elif [[ "$reset_epoch" =~ ^[0-9]+$ ]]; then
                now=$(date +%s 2>/dev/null || printf '0')
                if [[ "$now" =~ ^[0-9]+$ ]] && (( reset_epoch > now )); then
                    delay=$((reset_epoch - now))
                fi
            fi
            [[ -n "${GITHUB_TOKEN:-}" ]] || printf '%s\n' 'GitHub API rate limit detected; set GITHUB_TOKEN for a higher authenticated limit.' >&2
        elif (( rc == 5 || rc == 6 || rc == 7 || rc == 18 || rc == 28 || rc == 35 || rc == 52 || rc == 56 )); then
            :
        else
            if [[ "$http_code" == 403 && -z "${GITHUB_TOKEN:-}" ]]; then
                printf '%s\n' 'GitHub API returned 403; shared anonymous API rate limits may be exhausted.' >&2
            fi
            rm -f -- "$tmp" "$headers"
            return 1
        fi
        if (( attempt == max_attempts )); then break; fi
        if (( delay > 30 )); then delay=30; fi
        if (( delay > 0 )); then sleep "$delay"; fi
        if (( delay < 30 )); then delay=$((delay * 2)); fi
        attempt=$((attempt + 1))
    done
    rm -f -- "$tmp" "$headers"
    return 1
}

verify_github_asset_digest() {
    local file="$1" digest="${2:-}" expected actual
    if [[ -z "$digest" || "$digest" == 'null' ]]; then
        printf '%s\n' "$(tr_msg vg_missing)" >&2
        return 1
    fi
    [[ "$digest" == sha256:* ]] || { printf '%s\n' "$(tr_msg vg_not_sha)" >&2; return 1; }
    expected="${digest#sha256:}"
    [[ "$expected" =~ ^[A-Fa-f0-9]{64}$ ]] || { printf '%s\n' "$(tr_msg vg_bad_format)" >&2; return 1; }
    actual=$(sha256sum "$file" 2>/dev/null | awk '{print $1}') || actual=''
    [[ "${actual,,}" == "${expected,,}" ]] || { printf '%s\n' "$(tr_msg vg_mismatch)" >&2; return 1; }
}

# ============ F-05: Ed25519 detached signature verification ============
# Uses ONLY openssl + python3 (both guaranteed by ensure_commands).
# .sig files are base64 text of the raw 64-byte Ed25519 signature.
# F8: probe OpenSSL Ed25519/rawin capability. Ed25519 needs OpenSSL 1.1.1+;
# -rawin for pkeyutl needs 1.1.1+. Cache the result.
_openssl_has_ed25519() {
    if [[ -n "${_OPENSSL_ED25519_OK:-}" ]]; then
        return "$_OPENSSL_ED25519_OK"
    fi
    # PROBE-ERROR must not be cached: only a DEFINITIVE "algorithm unsupported"
    # is a platform capability answer. Infrastructure failures (mktemp, ENOSPC)
    # are transient and must force fail-closed, not fail-open.
    local _t _err
    _t=$(mktemp -d 2>/dev/null) || return 1
    printf 'test' > "$_t/in.bin" 2>/dev/null || { rm -rf -- "$_t"; return 1; }
    _err="$_t/err"
    if ! openssl genpkey -algorithm ed25519 -out "$_t/priv.pem" 2>"$_err"; then
        # Only cache when the error definitively indicates unsupported algorithm.
        if grep -qiE 'unknown[ _]algorithm|not found|unsupported|no such' "$_err" 2>/dev/null; then
            _OPENSSL_ED25519_OK=1
        fi
        rm -rf -- "$_t"
        return 1
    fi
    # Probe: pkeyutl -rawin support. Note: -rawin requires file input,
    # not stdin pipe (oneshot operation needs file size).
    if ! openssl pkeyutl -sign -inkey "$_t/priv.pem" -rawin -in "$_t/in.bin" -out "$_t/sig.bin" 2>/dev/null; then
        # -rawin missing is a definitive capability gap; cache it.
        _OPENSSL_ED25519_OK=1
        rm -rf -- "$_t"
        return 1
    fi
    rm -rf -- "$_t"
    _OPENSSL_ED25519_OK=0
    return 0
}
# Returns 0 iff ANY non-revoked pubkey in ABOX_SIGNING_PUBKEYS verifies.
verify_ed25519_detached() {
    local file="$1" sigfile="$2"
    local entry label pubkey_b64 fp keydir keypem sigbin r revoked
    [[ -f "$file" && -f "$sigfile" ]] || return 1
    command -v openssl >/dev/null 2>&1 || return 1
    command -v python3 >/dev/null 2>&1 || return 1
    command -v base64 >/dev/null 2>&1 || return 1
    keydir=$(umask 077; mktemp -d /tmp/A-Box-ed25519.XXXXXX 2>/dev/null) || return 1
    keypem="$keydir/pub.pem"
    sigbin="$keydir/sig.bin"
    # Signature must decode to exactly 64 raw bytes (Ed25519).
    if ! base64 -d "$sigfile" > "$sigbin" 2>/dev/null || [[ $(wc -c < "$sigbin") -ne 64 ]]; then
        rm -rf -- "$keydir"
        return 1
    fi
    for entry in "${ABOX_SIGNING_PUBKEYS[@]}"; do
        label="${entry%%:*}"
        pubkey_b64="${entry#*:}"
        # Malformed entry (no colon) or empty key: skip.
        [[ -n "$label" && -n "$pubkey_b64" && "$pubkey_b64" != "$entry" ]] || continue
        # Skip revoked keys: fingerprint = sha256 hex of raw pubkey bytes.
        fp=$(printf '%s' "$pubkey_b64" | base64 -d 2>/dev/null | sha256sum 2>/dev/null | awk '{print $1}')
        revoked=0
        if [[ -n "$fp" ]]; then
            for r in "${ABOX_REVOKED_PUBKEY_FPS[@]}"; do
                if [[ "${r,,}" == "${fp,,}" ]]; then revoked=1; break; fi
            done
        fi
        (( revoked == 0 )) || continue
        # Convert base64 raw 32-byte pubkey -> PEM (SubjectPublicKeyInfo).
        # Uses python3 -c (not heredoc) to avoid multi-level escaping fragility.
        if ! python3 -c "
import base64, sys
try:
    raw = base64.b64decode(sys.argv[1], validate=True)
except Exception:
    sys.exit(1)
if len(raw) != 32:
    sys.exit(1)
der = bytes.fromhex('302a300506032b6570032100') + raw
pem = '-----BEGIN PUBLIC KEY-----' + chr(10) + base64.encodebytes(der).decode().strip() + chr(10) + '-----END PUBLIC KEY-----' + chr(10)
open(sys.argv[2], 'w').write(pem)
" "$pubkey_b64" "$keypem" 2>/dev/null; then
            continue
        fi
        if openssl pkeyutl -verify -pubin -inkey "$keypem" -rawin -in "$file" -sigfile "$sigbin" >/dev/null 2>&1; then
            rm -rf -- "$keydir"
            return 0
        fi
    done
    rm -rf -- "$keydir"
    return 1
}

# F-05 anti-replay: metadata timestamp (ISO UTC, e.g. 2026-10-15T02:30:00Z
# or already-compact YYYYMMDDHHMMSS) must not be older than
# ABOX_SIGNING_MIN_TIMESTAMP_UTC. Returns 0 iff acceptable.
abox_signing_timestamp_ok() {
    local ts compact min_ts
    ts="${1:-}"
    # Normalize: strip everything except digits.
    compact=$(printf '%s' "$ts" | tr -cd '0-9')
    [[ "$compact" =~ ^[0-9]{14}$ ]] || return 1
    min_ts="${ABOX_SIGNING_MIN_TIMESTAMP_UTC:-0}"
    [[ "$compact" > "$min_ts" || "$compact" == "$min_ts" ]] || return 1
    return 0
}

# F-05 enforcement gate for a downloaded metadata file + its .sig.
#   $1 = metadata file path, $2 = .sig file path, $3 = description
# Returns 0 if signature verifies, or if enforcement is off (warns).
# Returns 1 (fail-closed) iff ABOX_SIGNING_ENFORCE=1 and sig missing/invalid.
abox_verify_sig_gate() {
    local file="$1" sigfile="$2" desc="${3:-metadata}"
    # F8: if OpenSSL lacks Ed25519/rawin, we cannot verify.
    # DS-Q4: CentOS 7 (OpenSSL 1.0.2) has no Ed25519. Fail-closed here would break
    # the documented CentOS 7 support. Downgrade to LOUD warning instead of FATAL
    # on platforms that fundamentally cannot verify (vs. missing .sig file).
    if ! _openssl_has_ed25519; then
        printf '[A-Box][F-05] WARNING: OpenSSL lacks Ed25519/rawin support (e.g. CentOS 7); cannot verify %s. Integrity is TLS-only on this platform.\n' "$desc" >&2
        return 0
    fi
    if [[ -f "$sigfile" ]]; then
        if verify_ed25519_detached "$file" "$sigfile"; then
            return 0
        fi
        printf '[A-Box][F-05] WARNING: invalid Ed25519 signature for %s\n' "$desc" >&2
    else
        printf '[A-Box][F-05] WARNING: missing signature for %s (%s not found)\n' "$desc" "$sigfile" >&2
    fi
    if [[ "${ABOX_SIGNING_ENFORCE:-1}" == '1' ]]; then
        printf '[A-Box][F-05] FATAL: signature enforcement is ON; rejecting %s\n' "$desc" >&2
        return 1
    fi
    return 0
}
# ========== end F-05 verification ==========

valid_github_download_url() {
    local repo="$1" url="$2" expected_ref="${3:-}" expected_asset="${4:-}"
    local repo_lower="${repo,,}" url_lower="${url,,}"
    [[ "$repo_lower" =~ ^[a-z0-9_.-]+/[a-z0-9_.-]+$ ]] || return 1
    [[ "$url" != *$'\r'* && "$url" != *$'\n'* && "$url" != *$'\t'* ]] || return 1
    if [[ -n "$expected_ref" ]]; then
        [[ "$expected_ref" =~ ^[A-Za-z0-9._/-]+$ ]] || return 1
        if [[ -n "$expected_asset" ]]; then
            python3 - "$url" "$repo" "$expected_ref" "$expected_asset" <<'PY_GITHUB_URL'
from urllib.parse import urlsplit
import sys
url, repo, ref, asset = sys.argv[1:]
try:
    u = urlsplit(url)
except ValueError:
    raise SystemExit(1)
if u.scheme != 'https' or u.hostname != 'github.com' or u.username or u.password or u.query or u.fragment:
    raise SystemExit(1)
if u.path != f'/{repo}/releases/download/{ref}/{asset}':
    raise SystemExit(1)
raise SystemExit(0)
PY_GITHUB_URL
            return $?
        fi
        [[ "$url" == "https://github.com/${repo}/releases/download/${expected_ref}/"* ]] || return 1
        local tail="${url#https://github.com/${repo}/releases/download/${expected_ref}/}"
        [[ -n "$tail" && "$tail" != */* && "$tail" != *'?'* && "$tail" != *'#'* && "$tail" != *'..'* && "$tail" != *'\\'* ]] || return 1
    else
        [[ "$url_lower" == "https://github.com/${repo_lower}/releases/download/"* ]] || return 1
        local tail="${url#https://github.com/${repo_lower}/releases/download/}"
        [[ -n "$tail" && "$tail" != *'?'* && "$tail" != *'#'* && "$tail" != *'..'* && "$tail" != *'\\'* ]] || return 1
    fi
}

singbox_asset_regex() {
    if [[ "${release:-}" == 'alpine' ]]; then
        printf '%s\n' "^sing-box-.*-linux-${SB_ARCH}-musl\.tar\.gz$"
    else
        printf '%s\n' "^sing-box-.*-linux-${SB_ARCH}-glibc\.tar\.gz$"
    fi
}

decimal_component_compare() {
    local a="${1:-}" b="${2:-}" LC_ALL=C
    [[ "$a" =~ ^[0-9]+$ && "$b" =~ ^[0-9]+$ ]] || return 2
    a="${a#"${a%%[!0]*}"}"; b="${b#"${b%%[!0]*}"}"
    [[ -n "$a" ]] || a='0'
    [[ -n "$b" ]] || b='0'
    if (( ${#a} < ${#b} )); then printf '%s\n' -1; return 0; fi
    if (( ${#a} > ${#b} )); then printf '%s\n' 1; return 0; fi
    if [[ "$a" == "$b" ]]; then printf '%s\n' 0; elif (( 10#$a < 10#$b )); then printf '%s\n' -1; else printf '%s\n' 1; fi
}

xray_version_at_least() {
    local version="${1:-}" min_major="${2:-0}" min_minor="${3:-0}" min_patch="${4:-0}" major minor patch cmp
    version="${version#v}"
    [[ "$version" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || return 2
    major="${BASH_REMATCH[1]}"; minor="${BASH_REMATCH[2]}"; patch="${BASH_REMATCH[3]}"
    cmp=$(decimal_component_compare "$major" "$min_major") || return 2
    (( cmp > 0 )) && return 0; (( cmp < 0 )) && return 1
    cmp=$(decimal_component_compare "$minor" "$min_minor") || return 2
    (( cmp > 0 )) && return 0; (( cmp < 0 )) && return 1
    cmp=$(decimal_component_compare "$patch" "$min_patch") || return 2
    (( cmp >= 0 ))
}

xray_version_compare() {
    local a="${1:-}" b="${2:-}" am aj ap bm bj bp cmp
    a="${a#v}"; b="${b#v}"
    [[ "$a" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || return 2
    am="${BASH_REMATCH[1]}"; aj="${BASH_REMATCH[2]}"; ap="${BASH_REMATCH[3]}"
    [[ "$b" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || return 2
    bm="${BASH_REMATCH[1]}"; bj="${BASH_REMATCH[2]}"; bp="${BASH_REMATCH[3]}"
    cmp=$(decimal_component_compare "$am" "$bm") || return 2; (( cmp != 0 )) && { printf '%s\n' "$cmp"; return 0; }
    cmp=$(decimal_component_compare "$aj" "$bj") || return 2; (( cmp != 0 )) && { printf '%s\n' "$cmp"; return 0; }
    decimal_component_compare "$ap" "$bp"
}

# Extract a semantic version from the first-line output of a core binary.
core_version_from_output() {
    local output="${1:-}"
    if [[ "$output" =~ (^|[^[:alnum:]])(v?[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?) ]]; then
        printf '%s\n' "${BASH_REMATCH[2]}"
    else
        return 1
    fi
}

# Compare SemVer tags, including prerelease tags and release refs such as app/v2.13.0.
# Prints -1/0/1 for target ordering and 2 on malformed input.
core_version_compare() {
    local a="${1:-}" b="${2:-}" a_pre='' b_pre='' cmp i id_a id_b norm_a norm_b
    local LC_ALL=C
    local -a a_ids=() b_ids=()
    a="${a##*/}"; b="${b##*/}"; a="${a#v}"; b="${b#v}"
    [[ "$a" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)(-([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$ ]] || return 2
    local am="${BASH_REMATCH[1]}" aj="${BASH_REMATCH[2]}" ap="${BASH_REMATCH[3]}"
    a_pre="${BASH_REMATCH[5]:-}"
    [[ "$b" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)(-([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$ ]] || return 2
    local bm="${BASH_REMATCH[1]}" bj="${BASH_REMATCH[2]}" bp="${BASH_REMATCH[3]}"
    b_pre="${BASH_REMATCH[5]:-}"
    cmp=$(xray_version_compare "$am.$aj.$ap" "$bm.$bj.$bp") || return 2
    if (( cmp != 0 )); then printf '%s\n' "$cmp"; return 0; fi
    if [[ -z "$a_pre" && -n "$b_pre" ]]; then printf '%s\n' 1; return 0; fi
    if [[ -n "$a_pre" && -z "$b_pre" ]]; then printf '%s\n' -1; return 0; fi
    if [[ -z "$a_pre" && -z "$b_pre" ]]; then printf '%s\n' 0; return 0; fi
    IFS='.' read -r -a a_ids <<< "$a_pre"
    IFS='.' read -r -a b_ids <<< "$b_pre"
    for ((i=0; i<${#a_ids[@]} && i<${#b_ids[@]}; i++)); do
        id_a="${a_ids[i]}"; id_b="${b_ids[i]}"
        [[ "$id_a" == "$id_b" ]] && continue
        if [[ "$id_a" =~ ^[0-9]+$ && "$id_b" =~ ^[0-9]+$ ]]; then
            norm_a="$id_a"; norm_b="$id_b"
            while [[ "${#norm_a}" -gt 1 && "$norm_a" == 0* ]]; do norm_a="${norm_a#0}"; done
            while [[ "${#norm_b}" -gt 1 && "$norm_b" == 0* ]]; do norm_b="${norm_b#0}"; done
            if (( ${#norm_a} < ${#norm_b} )); then cmp=-1
            elif (( ${#norm_a} > ${#norm_b} )); then cmp=1
            elif [[ "$norm_a" < "$norm_b" ]]; then cmp=-1
            else cmp=1
            fi
        elif [[ "$id_a" =~ ^[0-9]+$ ]]; then
            cmp=-1
        elif [[ "$id_b" =~ ^[0-9]+$ ]]; then
            cmp=1
        elif [[ "$id_a" < "$id_b" ]]; then
            cmp=-1
        else
            cmp=1
        fi
        printf '%s\n' "$cmp"
        return 0
    done
    if (( ${#a_ids[@]} < ${#b_ids[@]} )); then printf '%s\n' -1
    elif (( ${#a_ids[@]} > ${#b_ids[@]} )); then printf '%s\n' 1
    else printf '%s\n' 0
    fi
}

# Return codes: 0=proceed, 1=explicit downgrade needs opt-in, 2=invalid versions,
# 3=installed version is newer than the default pin (safe no-op), 4=already pinned.
core_binary_matches_release_ref() {
    local expected_ref="${1:-}" output="${2:-}" expected actual cmp
    [[ -n "$expected_ref" && -n "$output" ]] || return 1
    expected="${expected_ref##*/}"
    expected="${expected#v}"
    actual=$(core_version_from_output "$output" 2>/dev/null) || return 1
    actual="${actual#v}"
    cmp=$(core_version_compare "$actual" "$expected" 2>/dev/null) || return 1
    [[ "$cmp" == '0' ]]
}

core_version_upgrade_decision() {
    local current="${1:-}" target="${2:-}" explicit="${3:-0}" allow="${4:-0}" cmp
    [[ "$explicit" == 0 || "$explicit" == 1 ]] || return 2
    [[ "$allow" == 0 || "$allow" == 1 ]] || return 2
    cmp=$(core_version_compare "$current" "$target") || return 2
    [[ "$allow" == 1 ]] && return 0
    if (( cmp > 0 )); then
        [[ "$explicit" == 1 ]] && return 1
        return 3
    fi
    if (( cmp == 0 )) && [[ "$explicit" == 0 ]]; then return 4; fi
    return 0
}

core_version_downgrade_allowed() {
    core_version_upgrade_decision "${1:-}" "${2:-}" 1 "${3:-0}"
}

# A present binary whose version command failed is not safe to replace silently:
# it may be a newer/custom build that the version guard cannot order.
core_version_probe_safe() {
    local binary_path="${1:-}" output="${2:-}" allow="${3:-0}"
    [[ "$allow" == 0 || "$allow" == 1 ]] || return 2
    if [[ -e "$binary_path" || -L "$binary_path" ]]; then
        [[ -n "$output" || "$allow" == 1 ]]
    else
        return 0
    fi
}

core_release_ref_valid() {
    local repo="${1:-}" ref="${2:-}"
    case "$repo" in
        XTLS/Xray-core|SagerNet/sing-box) [[ "$ref" =~ ^v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$ ]] ;;
        HyNetworks/hysteria) [[ "$ref" =~ ^app/v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$ ]] ;;
        *) return 1 ;;
    esac
}

core_latest_stable_tag_from_json() {
    local repo="${1:-}" release_json="${2:-}" pattern tag
    case "$repo" in
        XTLS/Xray-core|SagerNet/sing-box) pattern='^v[0-9]+\.[0-9]+\.[0-9]+$' ;;
        HyNetworks/hysteria) pattern='^app/v[0-9]+\.[0-9]+\.[0-9]+$' ;;
        *) return 1 ;;
    esac
    [[ -n "$release_json" ]] || return 1
    # GitHub's release feed is ordered by publication time, not semantic version.
    # Sort the validated stable tags numerically so a late-published older release
    # cannot shadow a newer version. Prereleases and drafts are filtered above.
    tag=$(jq -er --arg pattern "$pattern" '
        if type != "array" then empty
        else
          [ .[]?
            | select(.draft == false and .prerelease == false)
            | select(((.tag_name // "") | type) == "string")
            | select((.tag_name // "") | test($pattern))
          ]
          | sort_by(
              .tag_name
              | capture("^(?:app/)?v(?<major>[0-9]+)\\.(?<minor>[0-9]+)\\.(?<patch>[0-9]+)$")
              | [(.major | tonumber), (.minor | tonumber), (.patch | tonumber)]
            )
          | last
          | .tag_name // empty
        end
    ' <<< "$release_json" 2>/dev/null) || return 1
    core_release_ref_valid "$repo" "$tag" || return 1
    printf '%s\n' "$tag"
}

core_latest_stable_release_ref() {
    local repo="${1:-}" json
    case "$repo" in
        XTLS/Xray-core|SagerNet/sing-box|HyNetworks/hysteria) ;;
        *) return 1 ;;
    esac
    json=$(github_api_get "https://api.github.com/repos/$repo/releases?per_page=100") || return 1
    core_latest_stable_tag_from_json "$repo" "$json"
}

core_release_mirror_version() {
    case "${1:-}" in
        XTLS/Xray-core) printf '%s\n' "$ABOX_XRAY_MIRROR_VERSION" ;;
        SagerNet/sing-box) printf '%s\n' "$ABOX_SINGBOX_MIRROR_VERSION" ;;
        HyNetworks/hysteria) printf '%s\n' "$ABOX_HYSTERIA_MIRROR_VERSION" ;;
        *) return 1 ;;
    esac
}

core_latest_mirror_tag_from_text() {
    local repo="${1:-}" versions="${2:-}" key ref
    case "$repo" in XTLS/Xray-core) key='Xray' ;; SagerNet/sing-box) key='sing-box' ;; HyNetworks/hysteria) key='Hysteria' ;; *) return 1 ;; esac
    [[ -n "$versions" ]] || return 1
    ref=$(awk -F= -v key="$key" '$1 == key {sub(/^[^=]*=/, ""); print; found=1; exit} END {if (!found) exit 1}' <<< "$versions") || return 1
    core_release_ref_valid "$repo" "$ref" || return 1
    [[ "$ref" != *-* ]] || return 1
    printf '%s\n' "$ref"
}

core_latest_mirror_release_ref() {
    local repo="${1:-}" base='' workdir='' expected='' actual='' versions='' _f05_ts=''
    case "$repo" in XTLS/Xray-core|SagerNet/sing-box|HyNetworks/hysteria) ;; *) return 1 ;; esac
    base="${ABOX_CORE_MIRROR_BASE:-$ABOX_CORE_MIRROR_BASE_DEFAULT}"
    [[ -n "$base" ]] || return 1
    case "$base" in
        https://*) ;;
        *) msg "${RED}[!] ABOX_CORE_MIRROR_BASE must use https://; refusing plaintext mirror (integrity bypass).${NC}" >&2; return 1 ;;
    esac
    workdir=$(mktemp -d /tmp/A-Box-core-mirror-meta.XXXXXX) || return 1
    if ! curl -fLsS --connect-timeout 5 -m 15 "${base%/}/CORE-VERSIONS" -o "$workdir/CORE-VERSIONS" || ! curl -fLsS --connect-timeout 5 -m 15 "${base%/}/SHA256SUMS" -o "$workdir/SHA256SUMS"; then
        rm -rf -- "$workdir"; return 1
    fi
    # F-05: fetch detached signatures (best-effort); gate enforces when on.
    curl -fLsS --connect-timeout 5 -m 15 "${base%/}/CORE-VERSIONS.sig" -o "$workdir/CORE-VERSIONS.sig" 2>/dev/null || true
    curl -fLsS --connect-timeout 5 -m 15 "${base%/}/SHA256SUMS.sig" -o "$workdir/SHA256SUMS.sig" 2>/dev/null || true
    if ! abox_verify_sig_gate "$workdir/CORE-VERSIONS" "$workdir/CORE-VERSIONS.sig" "core mirror CORE-VERSIONS"; then
        rm -rf -- "$workdir"; return 1
    fi
    if ! abox_verify_sig_gate "$workdir/SHA256SUMS" "$workdir/SHA256SUMS.sig" "core mirror SHA256SUMS"; then
        rm -rf -- "$workdir"; return 1
    fi
    # F-05 anti-replay: CORE-VERSIONS timestamp must not predate trust floor.
    _f05_ts=$(awk -F= '$1=="updated_at_utc" {print $2; exit}' "$workdir/CORE-VERSIONS" 2>/dev/null || true)
    if [[ -n "$_f05_ts" ]] && ! abox_signing_timestamp_ok "$_f05_ts"; then
        if [[ "${ABOX_SIGNING_ENFORCE:-1}" == '1' ]]; then
            printf '[A-Box][F-05] FATAL: CORE-VERSIONS timestamp %s is older than trust floor %s\n' "$_f05_ts" "$ABOX_SIGNING_MIN_TIMESTAMP_UTC" >&2
            rm -rf -- "$workdir"; return 1
        fi
        printf '[A-Box][F-05] WARNING: CORE-VERSIONS timestamp %s is older than trust floor %s (enforcement off)\n' "$_f05_ts" "$ABOX_SIGNING_MIN_TIMESTAMP_UTC" >&2
    fi
    expected=$(awk '$2 == "CORE-VERSIONS" {print $1; exit}' "$workdir/SHA256SUMS")
    actual=$(sha256sum "$workdir/CORE-VERSIONS" 2>/dev/null | awk '{print $1}') || actual=''
    if [[ ! "$expected" =~ ^[A-Fa-f0-9]{64}$ || "${actual,,}" != "${expected,,}" ]]; then rm -rf -- "$workdir"; return 1; fi
    versions=$(cat "$workdir/CORE-VERSIONS") || { rm -rf -- "$workdir"; return 1; }
    rm -rf -- "$workdir"
    core_latest_mirror_tag_from_text "$repo" "$versions"
}

core_mirror_asset_leaf() {
    local repo="${1:-}" output_file="${2:-}" version="${3:-}" prefer_versioned="${4:-0}" pin='' sb_ver='' hysteria_leaf=''
    pin=$(core_release_mirror_version "$repo") || return 1
    core_release_ref_valid "$repo" "$version" || return 1
    case "$repo:$output_file" in
        XTLS/Xray-core:xray_core.zip)
            if [[ "$version" == "$pin" && "$prefer_versioned" != '1' ]]; then
                printf 'Xray-linux-%s.zip\n' "$XRAY_ARCH"
            else
                printf 'Xray-%s-linux-%s.zip\n' "$version" "$XRAY_ARCH"
            fi
            ;;
        SagerNet/sing-box:singbox_core.tar.gz)
            sb_ver="${version#v}"
            if [[ "${release:-}" == 'alpine' ]]; then
                printf 'sing-box-%s-linux-%s-musl.tar.gz\n' "$sb_ver" "$SB_ARCH"
            else
                printf 'sing-box-%s-linux-%s-glibc.tar.gz\n' "$sb_ver" "$SB_ARCH"
            fi
            ;;
        HyNetworks/hysteria:hysteria_core)
            if [[ "$version" == "$pin" && "$prefer_versioned" != '1' ]]; then
                printf 'hysteria-linux-%s\n' "$HY2_ARCH"
            else
                hysteria_leaf=$(tr '/' '-' <<< "$version" | tr -d '\n')
                printf 'hysteria-%s-linux-%s\n' "$hysteria_leaf" "$HY2_ARCH"
            fi
            ;;
        *) return 1 ;;
    esac
}

core_resolved_version() {
    case "${1:-}" in
        XTLS/Xray-core) printf '%s\n' "${ABOX_RESOLVED_XRAY_VERSION:-}" ;;
        SagerNet/sing-box) printf '%s\n' "${ABOX_RESOLVED_SINGBOX_VERSION:-}" ;;
        HyNetworks/hysteria) printf '%s\n' "${ABOX_RESOLVED_HYSTERIA_VERSION:-}" ;;
        *) return 1 ;;
    esac
}

core_resolved_source() {
    case "${1:-}" in
        XTLS/Xray-core) printf '%s\n' "${ABOX_RESOLVED_XRAY_SOURCE:-}" ;;
        SagerNet/sing-box) printf '%s\n' "${ABOX_RESOLVED_SINGBOX_SOURCE:-}" ;;
        HyNetworks/hysteria) printf '%s\n' "${ABOX_RESOLVED_HYSTERIA_SOURCE:-}" ;;
        *) return 1 ;;
    esac
}

core_set_resolved_target() {
    local repo="${1:-}" ref="${2:-}" source="${3:-}"
    core_release_ref_valid "$repo" "$ref" || return 1
    case "$source" in upstream|mirror|mirror-latest|mirror-exact|explicit|pinned) ;; *) return 1 ;; esac
    case "$repo" in
        XTLS/Xray-core) ABOX_RESOLVED_XRAY_VERSION="$ref"; ABOX_RESOLVED_XRAY_SOURCE="$source" ;;
        SagerNet/sing-box) ABOX_RESOLVED_SINGBOX_VERSION="$ref"; ABOX_RESOLVED_SINGBOX_SOURCE="$source" ;;
        HyNetworks/hysteria) ABOX_RESOLVED_HYSTERIA_VERSION="$ref"; ABOX_RESOLVED_HYSTERIA_SOURCE="$source" ;;
        *) return 1 ;;
    esac
}

clear_core_release_resolution() {
    case "${1:-}" in
        XTLS/Xray-core) ABOX_RESOLVED_XRAY_VERSION=''; ABOX_RESOLVED_XRAY_SOURCE='' ;;
        SagerNet/sing-box) ABOX_RESOLVED_SINGBOX_VERSION=''; ABOX_RESOLVED_SINGBOX_SOURCE='' ;;
        HyNetworks/hysteria) ABOX_RESOLVED_HYSTERIA_VERSION=''; ABOX_RESOLVED_HYSTERIA_SOURCE='' ;;
        *) return 1 ;;
    esac
}

core_update_policy() {
    # Returns the update policy for a core repo: 'pinned' or 'auto-stable'.
    # Xray defaults to pinned (ML-KEM compat risk); sing-box/Hysteria default
    # to auto-stable. Explicit ABOX_*_VERSION overrides always win.
    case "${1:-}" in
        XTLS/Xray-core) printf '%s\n' "${ABOX_XRAY_UPDATE_POLICY:-pinned}" ;;
        SagerNet/sing-box) printf '%s\n' "${ABOX_SINGBOX_UPDATE_POLICY:-auto-stable}" ;;
        HyNetworks/hysteria) printf '%s\n' "${ABOX_HYSTERIA_UPDATE_POLICY:-auto-stable}" ;;
        *) return 1 ;;
    esac
}

core_stable_release_age_days() {
    # Prints the age in whole days of a stable release tag, or fails when the
    # published date cannot be determined. Used to enforce the cooldown before
    # an auto-stable policy accepts a newly published release.
    local repo="${1:-}" tag="${2:-}" json published now_ts pub_ts
    case "$repo" in XTLS/Xray-core|SagerNet/sing-box|HyNetworks/hysteria) ;; *) return 1 ;; esac
    [[ -n "$tag" ]] || return 1
    json=$(github_api_get "https://api.github.com/repos/$repo/releases?per_page=100") || return 1
    published=$(jq -er --arg tag "$tag" '
        [ .[]? | select(.draft == false and .prerelease == false and .tag_name == $tag)
        | .published_at ] | first // empty
    ' <<< "$json") || return 1
    [[ -n "$published" ]] || return 1
    now_ts=$(date +%s) || return 1
    pub_ts=$(date -d "$published" +%s 2>/dev/null || python3 - "$published" <<'PY_ISO_TS' 2>/dev/null
import datetime, sys
s = sys.argv[1].strip()
if s.endswith('Z'):
    s = s[:-1] + '+00:00'
dt = datetime.datetime.fromisoformat(s)
if dt.tzinfo is None:
    dt = dt.replace(tzinfo=datetime.timezone.utc)
print(int(dt.timestamp()))
PY_ISO_TS
    ) || return 1
    [[ "$pub_ts" -le "$now_ts" ]] || return 1
    printf '%s\n' $(( (now_ts - pub_ts) / 86400 ))
}

resolve_core_release_target() {
    local repo="${1:-}" override='' latest='' latest_age='' target='' source='' resolved='' resolved_source='' default_ref=''
    case "$repo" in
        XTLS/Xray-core) override="${ABOX_XRAY_VERSION:-}"; default_ref="$ABOX_XRAY_DEFAULT_VERSION" ;;
        SagerNet/sing-box) override="${ABOX_SINGBOX_VERSION:-}"; default_ref="$ABOX_SINGBOX_DEFAULT_VERSION" ;;
        HyNetworks/hysteria) override="${ABOX_HYSTERIA_APP_VERSION:-}"; default_ref="$ABOX_HYSTERIA_DEFAULT_VERSION" ;;
        *) return 1 ;;
    esac
    if [[ -n "$override" ]]; then
        core_release_ref_valid "$repo" "$override" || { msg "${RED}[!] $(tprintf rc_bad_override "$repo" "$override")${NC}" >&2; return 1; }
        target="$override"; source='explicit'
    else
        resolved=$(core_resolved_version "$repo" 2>/dev/null || true)
        resolved_source=$(core_resolved_source "$repo" 2>/dev/null || true)
        if core_release_ref_valid "$repo" "$resolved" && [[ "$resolved_source" == 'upstream' || "$resolved_source" == 'mirror' || "$resolved_source" == 'mirror-latest' || "$resolved_source" == 'mirror-exact' || "$resolved_source" == 'pinned' ]]; then
            target="$resolved"; source="$resolved_source"
        elif [[ "${ABOX_TRY_LATEST_CORE_STABLE:-0}" == '1' ]] || [[ "$(core_update_policy "$repo" 2>/dev/null || true)" == 'auto-stable' ]]; then
            latest=$(core_latest_stable_release_ref "$repo" 2>/dev/null || true)
            if core_release_ref_valid "$repo" "$latest" && [[ "$latest" != *-* ]]; then
                # Cooldown: a stable release must be published for at least
                # ABOX_STABLE_COOLDOWN_DAYS before auto-stable accepts it.
                # Cooling is necessary, not sufficient. When the age cannot be
                # determined, refuse to auto-adopt and fall back to the pin.
                # Explicit ABOX_TRY_LATEST_CORE_STABLE=1 (DANGER menu) bypasses
                # the cooldown: the operator asked for latest, knowing the risk.
                if [[ "${ABOX_TRY_LATEST_CORE_STABLE:-0}" == '1' ]]; then
                    msg "${YELLOW}[!] ABOX_TRY_LATEST_CORE_STABLE=1: cooldown bypassed by explicit operator request; $latest will be tried.${NC}" >&2
                    target="$latest"; source='upstream'
                else
                    latest_age=$(core_stable_release_age_days "$repo" "$latest" 2>/dev/null || true)
                    # Validate cooldown is numeric to avoid set -u crash on bad input
                    local cooldown_days="${ABOX_STABLE_COOLDOWN_DAYS:-7}"
                    # N-14 fix: 0 would silently disable the cooldown (latest_age >= 0
                    # is always true). Require >= 1; invalid values fall back to 7.
                    if [[ "$cooldown_days" =~ ^[0-9]{1,4}$ ]] && (( 10#$cooldown_days >= 1 && 10#$cooldown_days <= 3650 )); then
                        :
                    else
                        [[ "$cooldown_days" == "0" ]] && msg "${YELLOW}[!] ABOX_STABLE_COOLDOWN_DAYS=0 is not allowed (would disable cooldown); using 7.${NC}" >&2
                        cooldown_days=7
                    fi
                    if [[ "$latest_age" =~ ^[0-9]+$ ]] && (( latest_age >= cooldown_days )); then
                        target="$latest"; source='upstream'
                    else
                        msg "${YELLOW}[!] $repo latest stable $latest is still in cooldown (${latest_age:-unknown} days < ${cooldown_days}); keeping pin $default_ref.${NC}" >&2
                        target="$default_ref"; source='pinned'
                    fi
                fi
            else
                # Upstream API unavailable: try mirror-latest.
                # DANGER mode (ABOX_TRY_LATEST_CORE_STABLE=1) bypasses cooldown,
                # matching the upstream-success path. Otherwise enforce cooldown;
                # CORE-VERSIONS has no published_at, so we attempt a targeted API
                # query for this specific tag's date. If age cannot be determined,
                # fall back to pin (fail-closed per version policy).
                latest=$(core_latest_mirror_release_ref "$repo" 2>/dev/null || true)
                if core_release_ref_valid "$repo" "$latest" && [[ "$latest" != *-* ]]; then
                    # BUG-04 fix (Option A): API already unavailable (we are in mirror branch).
                    # Calling core_stable_release_age_days would fail again (it needs API).
                    # Skip cooldown, trust mirror version with format validation.
                    # Mirror is maintained by weekly workflow that enforces cooldown at build time.
                    if [[ "$latest" =~ ^(app/)?v?[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z._-]+)?$ ]]; then
                        target="$latest"; source='mirror-latest'; msg "${YELLOW}[!] 上游稳定版 API 不可用；直接信任镜像版本 ${target}（跳过实时冷却期查询，镜像构建时已执行冷却校验）。${NC}" >&2
                    else
                        target=$(core_release_mirror_version "$repo") || return 1; source='mirror'; msg "${YELLOW}[!] 镜像版本格式非法，回退到固定兼容版本 ${target}。${NC}" >&2
                    fi
                else target=$(core_release_mirror_version "$repo") || return 1; source='mirror'; msg "${YELLOW}[!] 上游与最新镜像元数据均不可用；本次尝试固定 A-Box 兼容性容灾版本 ${target}。${NC}" >&2; fi
            fi
        else core_release_ref_valid "$repo" "$default_ref" || return 1; target="$default_ref"; source='pinned'
        fi
    fi
    core_set_resolved_target "$repo" "$target" "$source"
}


effective_xray_version() {
    # Explicit operator override (ABOX_XRAY_VERSION) always wins first;
    # otherwise prefer the actual installed binary version over intent-based values.
    # ABOX_XRAY_VERSION_PROBE_SKIP=1 disables the binary probe (self-test).
    local actual
    if [[ -n "${ABOX_XRAY_VERSION:-}" ]]; then
        printf '%s\n' "$ABOX_XRAY_VERSION"
        return 0
    fi
    if [[ "${ABOX_XRAY_VERSION_PROBE_SKIP:-0}" != '1' && -x /usr/local/bin/xray ]]; then
        actual=$(/usr/local/bin/xray version 2>/dev/null | head -n 1 || true)
        actual=$(core_version_from_output "$actual" 2>/dev/null || true)
        if [[ -n "$actual" ]]; then
            # Normalize to v-prefixed tag for downstream comparisons.
            [[ "$actual" == v* ]] || actual="v$actual"
            printf '%s\n' "$actual"
            return 0
        fi
    fi
    if [[ -n "${ABOX_RESOLVED_XRAY_VERSION:-}" ]]; then
        printf '%s\n' "$ABOX_RESOLVED_XRAY_VERSION"
    else
        printf '%s\n' "$ABOX_XRAY_DEFAULT_VERSION"
    fi
}

xray_reality_requires_mlkem() {
    local threshold="${ABOX_XRAY_REALITY_MLKEM_MIN_VERSION#v}" min_major min_minor min_patch
    IFS=. read -r min_major min_minor min_patch <<< "$threshold"
    [[ "$min_major" =~ ^[0-9]+$ && "$min_minor" =~ ^[0-9]+$ && "$min_patch" =~ ^[0-9]+$ ]] || return 2
    xray_version_at_least "$(effective_xray_version)" "$min_major" "$min_minor" "$min_patch"
}

clash_reality_mlkem_enabled() {
    [[ "${CORE:-}" == 'xray' ]] || return 1
    xray_reality_requires_mlkem
}

singbox_asset_json_from_release() {
    local release_json="${1:-}" preferred asset_json
    preferred="$(singbox_asset_regex)"
    # Fail closed on libc selection. A generic linux-ARCH asset is not accepted
    # because it can silently select the wrong libc family and fail after install.
    asset_json=$(jq -c --arg re "$preferred" 'first(.assets[]? | select(.name | test($re)) | {name:.name,url:.browser_download_url,digest:(.digest // "")}) // empty' <<< "$release_json")
    [[ -n "$asset_json" && "$asset_json" != 'null' ]] || return 1
    printf '%s\n' "$asset_json"
}

core_fetch_upstream_release_asset() {
    local repo="${1:-}" output_file="${2:-}" dest_file="${3:-}" release_ref="${4:-}" asset_re="${5:-}" source="${6:-upstream}"
    local api_url release_json asset_array count asset_json asset_name download_url digest mirror tmp_file require_stable=1
    api_url="https://api.github.com/repos/${repo}/releases/tags/${release_ref//\//%2F}"
    release_json=$(github_api_get "$api_url" 2>/dev/null) || { msg "${YELLOW}[!] 上游 Release API 不可用: ${repo}:${release_ref}${NC}" >&2; return 1; }
    [[ "$source" == 'explicit' || "$source" == 'pinned' ]] && require_stable=0
    if ! jq -e --arg tag "$release_ref" --argjson stable "$require_stable" '
        type == "object" and .tag_name == $tag and .draft == false
        and (if $stable == 1 then .prerelease == false else true end)
    ' <<< "$release_json" >/dev/null 2>&1; then
        msg "${YELLOW}[!] 上游 Release 元数据与目标版本/稳定性不一致: ${repo}:${release_ref}${NC}" >&2; return 1
    fi
    if [[ "$repo:$output_file" == 'SagerNet/sing-box:singbox_core.tar.gz' ]]; then asset_re="$(singbox_asset_regex)"; fi
    asset_array=$(jq -c --arg re "$asset_re" '[.assets[]? | select(((.name // "") | type) == "string") | select((.name // "") | test($re)) | {name:.name,url:(.browser_download_url // ""),digest:(.digest // "")}]' <<< "$release_json" 2>/dev/null) || return 1
    count=$(jq -r 'length' <<< "$asset_array" 2>/dev/null) || return 1
    [[ "$count" == '1' ]] || { msg "${YELLOW}[!] 目标架构资产匹配数不是 1（匹配 ${count:-0} 个）: ${repo}:${release_ref}${NC}" >&2; return 1; }
    asset_json=$(jq -c '.[0]' <<< "$asset_array") || return 1
    asset_name=$(jq -r '.name // ""' <<< "$asset_json"); download_url=$(jq -r '.url // ""' <<< "$asset_json"); digest=$(jq -r '.digest // ""' <<< "$asset_json")
    [[ -n "$asset_name" ]] || return 1
    valid_github_download_url "$repo" "$download_url" "$release_ref" "$asset_name" || { msg "${YELLOW}[!] 下载 URL 与官方仓库/tag/资产不匹配，拒绝该候选。${NC}" >&2; return 1; }
    [[ "$digest" == sha256:* && "${digest#sha256:}" =~ ^[A-Fa-f0-9]{64}$ ]] || { msg "${YELLOW}[!] 官方 Release 缺少有效 SHA-256 digest。${NC}" >&2; return 1; }
    for mirror in '' 'https://ghp.ci/' 'https://mirror.ghproxy.com/'; do
        tmp_file=$(mktemp "${dest_file}.download.XXXXXX") || return 1
        if abox_run_wait "下载 ${asset_name}" curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 10 -m 180 "${mirror}${download_url}" -o "$tmp_file"; then
            if ! validate_downloaded_asset "$output_file" "$tmp_file"; then rm -f -- "$tmp_file"; msg "${YELLOW}[!] 下载归档格式校验失败，继续下一个通道。${NC}" >&2; continue; fi
            if ! verify_github_asset_digest "$tmp_file" "$digest"; then rm -f -- "$tmp_file"; msg "${YELLOW}[!] 资产 SHA-256 不匹配，继续下一个通道。${NC}" >&2; continue; fi
            if ! validate_core_asset_binary_version "$output_file" "$tmp_file" "$release_ref"; then rm -f -- "$tmp_file"; msg "${YELLOW}[!] 二进制版本与上游 tag 不一致，拒绝该候选。${NC}" >&2; continue; fi
            mv -f -- "$tmp_file" "$dest_file" || { rm -f -- "$tmp_file"; return 1; }
            ABOX_LAST_CORE_RELEASE_REF="$release_ref"; ABOX_LAST_CORE_SOURCE="$source"
            core_set_resolved_target "$repo" "$release_ref" "$source" || return 1
            msg "${GREEN}   上游候选通过归档、SHA-256 与二进制版本校验：${repo}:${release_ref}${NC}"
            return 0
        fi
        rm -f -- "$tmp_file"
    done
    msg "${YELLOW}[!] 上游资产全部下载/验证通道失败。${NC}" >&2
    return 1
}

fetch_github_release() {
    local repo="${1:-}" output_file="${2:-}" dest_file="${3:-}" asset_re='' target_ref='' target_source='' mirror_ref=''
    case "$repo:$output_file" in XTLS/Xray-core:xray_core.zip) asset_re="^Xray-linux-${XRAY_ARCH}[.]zip$" ;; SagerNet/sing-box:singbox_core.tar.gz) asset_re="$(singbox_asset_regex)" ;; HyNetworks/hysteria:hysteria_core) asset_re="^hysteria-linux-${HY2_ARCH}$" ;; *) die "$(tprintf fg_no_rule "$repo" "$output_file")" ;; esac
    resolve_core_release_target "$repo" || die "$(tprintf fg_resolve "$repo")"
    target_ref=$(core_resolved_version "$repo") || die "$(tprintf fg_read_ver "$repo")"
    target_source=$(core_resolved_source "$repo") || die "$(tprintf fg_read_src "$repo")"
    core_release_ref_valid "$repo" "$target_ref" || die "$(tprintf fg_bad_ref "$repo" "$target_ref")"
    [[ -n "$dest_file" ]] || { local tmp_dir; tmp_dir=$(mktemp -d /tmp/A-Box-asset.XXXXXX) || die "$(tr_msg fg_tmpdir)"; dest_file="$tmp_dir/$output_file"; }
    mkdir -p "$(dirname "$dest_file")" || die "$(tr_msg fg_outdir)"
    if [[ "$repo:$output_file" == 'XTLS/Xray-core:xray_core.zip' ]]; then
        if ABOX_XRAY_VERSION="$target_ref" xray_reality_requires_mlkem; then msg "${YELLOW}[!] $(tprintf fg_mlkem "$target_ref")${NC}"; else local mlkem_rc=$?; (( mlkem_rc == 1 )) || die "$(tr_msg fg_unparsable)"; fi
    fi
    msg "${YELLOW} -> 核心候选 [${repo}:${target_ref}，source=${target_source}]... ${NC}"
    probe_core_sources_banner

    if [[ "$target_source" == 'mirror-exact' ]]; then
        if fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 1; then return 0; fi
        mirror_ref=$(core_release_mirror_version "$repo") || die "$(tprintf fg_no_pin "$repo")"
        if [[ "$target_ref" == "$mirror_ref" ]] && fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 0; then return 0; fi
        die "$(tprintf fg_exact_unavail "$target_ref")"
    fi

    if [[ "$target_source" == 'upstream' || "$target_source" == 'explicit' || "$target_source" == 'pinned' ]]; then
        if core_fetch_upstream_release_asset "$repo" "$output_file" "$dest_file" "$target_ref" "$asset_re" "$target_source"; then return 0; fi
        # F-02 fix: for auto-stable (source=upstream), try the exact-tag versioned
        # mirror before falling back to the fixed compat pin. This honors the
        # documented "same version mirror first" policy.
        if [[ "$target_source" == 'upstream' ]]; then
            if fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 1; then
                core_set_resolved_target "$repo" "$target_ref" mirror-exact || die "$(tr_msg fg_record_exact)"
                ABOX_LAST_CORE_RELEASE_REF="$target_ref"; ABOX_LAST_CORE_SOURCE='mirror-exact'
                msg "${GREEN}   上游失败，从同标签版本化镜像恢复 ${target_ref}；未替换版本号。${NC}"
                return 0
            fi
            msg "${YELLOW}[!] 同标签版本化镜像也不可用，继续尝试固定兼容版本。${NC}" >&2
        fi
        if [[ "$target_source" == 'explicit' ]]; then
            if fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 1; then
                core_set_resolved_target "$repo" "$target_ref" mirror-exact || die "$(tr_msg fg_record_exact)"
                ABOX_LAST_CORE_RELEASE_REF="$target_ref"; ABOX_LAST_CORE_SOURCE='mirror-exact'
                msg "${GREEN}   显式版本从同标签容灾资产恢复；未替换版本号。${NC}"
                return 0
            fi
            mirror_ref=$(core_release_mirror_version "$repo") || die "$(tprintf fg_no_pin "$repo")"
            if [[ "$target_ref" == "$mirror_ref" ]] && fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 0; then
                core_set_resolved_target "$repo" "$target_ref" mirror-exact || die "$(tr_msg fg_record_exact)"
                ABOX_LAST_CORE_RELEASE_REF="$target_ref"; ABOX_LAST_CORE_SOURCE='mirror-exact'
                msg "${GREEN}   显式版本从同标签固定容灾资产恢复；未替换版本号。${NC}"
                return 0
            fi
            die "$(tprintf fg_explicit_unavail "$target_ref")"
        fi
    fi

    if [[ "$target_source" == 'mirror-latest' || ( "$target_source" == 'upstream' && "${ABOX_TRY_LATEST_CORE_STABLE:-0}" == '1' ) ]]; then
        if fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$target_ref" 1; then
            core_set_resolved_target "$repo" "$target_ref" mirror-latest || die "$(tr_msg fg_record_latest)"
            ABOX_LAST_CORE_RELEASE_REF="$target_ref"; ABOX_LAST_CORE_SOURCE='mirror-latest'
            msg "${GREEN}   最新稳定镜像候选通过 SHA-256 与实际二进制版本校验：${target_ref}${NC}"
            return 0
        fi
        msg "${YELLOW}[!] 与目标版本一致的最新稳定镜像资产不可用；继续尝试固定兼容性容灾版本。${NC}" >&2
    fi

    mirror_ref=$(core_release_mirror_version "$repo") || die "$(tprintf fg_no_pin "$repo")"
    msg "${YELLOW}[!] 使用固定 A-Box 兼容性容灾版本 ${mirror_ref}，独立于失败的目标 ${target_ref}。${NC}" >&2
    if fetch_abox_mirror_asset "$repo" "$output_file" "$dest_file" "$mirror_ref"; then
        core_set_resolved_target "$repo" "$mirror_ref" mirror || die "$(tr_msg fg_record_pin)"
        ABOX_LAST_CORE_RELEASE_REF="$mirror_ref"; ABOX_LAST_CORE_SOURCE='mirror'
        msg "${GREEN}   固定容灾候选通过 SHA-256 与实际二进制版本校验：${mirror_ref}${NC}"
        return 0
    fi
    die "$(tr_msg fg_none_valid)"
}

fetch_geo_data() {
    local file_name official_url out tmp_out size repo asset release_json asset_json asset_name download_url digest release_ref out_created=0
    file_name="${1:-}"
    official_url="${2:-}"
    out="${3:-}"
    [[ -n "$file_name" && -n "$official_url" ]] || die "$(tr_msg gd_params)"
    [[ "$file_name" =~ ^[A-Za-z0-9._-]+$ ]] || die "$(tprintf gd_bad_name "$file_name")"
    if [[ -z "$out" ]]; then
        out="$(umask 077; mktemp "/tmp/${file_name}.XXXXXX")" || die "$(tr_msg gd_out_tmp)"
        out_created=1
        rm -f -- "$out" || die "$(tr_msg gd_out_init)"
    fi
    [[ ! -L "$out" && ! -d "$out" ]] || die "$(tprintf gd_out_notfile "$out")"
    mkdir -p "$(dirname "$out")" || die "$(tr_msg gd_out_dir)"
    tmp_out=$(umask 077; mktemp "${out}.download.XXXXXX") || { (( out_created == 1 )) && rm -f -- "$out"; die "$(tr_msg gd_tmp)"; }

    if [[ "$official_url" =~ ^https://github.com/([^/]+/[^/]+)/releases/latest/download/([^/?#]+)$ ]]; then
        repo="${BASH_REMATCH[1]}"
        asset="${BASH_REMATCH[2]}"
        release_json=$(github_api_get "https://api.github.com/repos/${repo}/releases/latest" 2>/dev/null) || release_json=''
        [[ -n "$release_json" ]] || { rm -f -- "$tmp_out"; die "$(tprintf gd_api "$repo")"; }
        asset_json=$(jq -c --arg name "$asset" 'first(.assets[]? | select(.name == $name) | {name:.name,url:.browser_download_url,digest:(.digest // "")}) // empty' <<< "$release_json")
        [[ -n "$asset_json" && "$asset_json" != 'null' ]] || { rm -f -- "$tmp_out"; die "$(tprintf gd_asset_missing "$asset")"; }
        asset_name=$(jq -r '.name // ""' <<< "$asset_json")
        release_ref=$(jq -r '.tag_name // ""' <<< "$release_json")
        download_url=$(jq -r '.url' <<< "$asset_json")
        digest=$(jq -r '.digest // ""' <<< "$asset_json")
        [[ -n "$asset_name" && -n "$release_ref" ]] || { rm -f -- "$tmp_out"; die 'Geo Release metadata missing asset name or tag.'; }
        valid_github_download_url "$repo" "$download_url" "$release_ref" "$asset_name" || { rm -f -- "$tmp_out"; die "$(tr_msg gd_url_mismatch)"; }
        abox_run_wait "$(tprintf gd_dl_label "$file_name")" curl -fLs --connect-timeout 10 -m 90 "$download_url" -o "$tmp_out" || { rm -f -- "$tmp_out"; die "$(tprintf gd_download "$file_name")"; }
        if ! verify_github_asset_digest "$tmp_out" "$digest"; then
            rm -f -- "$tmp_out"; (( out_created == 1 )) && rm -f -- "$out"
            die "$(tprintf gd_digest "$file_name")"
        fi
    else
        rm -f -- "$tmp_out"
        die "$(tprintf gd_no_digest "$file_name")"
    fi

    size=$(wc -c < "$tmp_out" 2>/dev/null | tr -d ' ')
    [[ -n "$size" && "$size" -gt 500000 ]] || { rm -f -- "$tmp_out"; (( out_created == 1 )) && rm -f -- "$out"; die "$(tprintf gd_size "$file_name")"; }
    if head -c 256 "$tmp_out" 2>/dev/null | grep -Eiq '<(html|!doctype)'; then
        rm -f -- "$tmp_out"; (( out_created == 1 )) && rm -f -- "$out"
        die "$(tprintf gd_html "$file_name")"
    fi
    mv -f -- "$tmp_out" "$out" || { rm -f -- "$tmp_out"; (( out_created == 1 )) && rm -f -- "$out"; die "$(tprintf gd_commit "$file_name")"; }
}

desired_state_valid() { [[ "${1:-}" =~ ^(RUNNING|TRAFFIC_BLOCKED|MANUAL_STOPPED|MAINTENANCE)$ ]]; }
traffic_period_valid() { [[ "${1:-}" =~ ^[0-9]{4}-(0[1-9]|1[0-2])$ ]]; }

# Authoritative traffic state is PAIR ("DESIRED|PERIOD"; PERIOD empty => no block).
# Legacy .desired_state / .traffic-block-state are derived ONLY after pair publish
# succeeds, for older helper readers that have not yet migrated.
read_traffic_pair_fields() {
    local line desired period uid gid mode
    [[ -r "$ABOX_TRAFFIC_PAIR_STATE" && -f "$ABOX_TRAFFIC_PAIR_STATE" && ! -L "$ABOX_TRAFFIC_PAIR_STATE" ]] || return 1
    uid=$(stat -c %u "$ABOX_TRAFFIC_PAIR_STATE" 2>/dev/null) || return 1
    gid=$(stat -c %g "$ABOX_TRAFFIC_PAIR_STATE" 2>/dev/null) || return 1
    mode=$(stat -c %a "$ABOX_TRAFFIC_PAIR_STATE" 2>/dev/null) || return 1
    [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#077) == 0 )) || return 1
    IFS= read -r line < "$ABOX_TRAFFIC_PAIR_STATE" || return 1
    [[ "$line" == *'|'* ]] || return 1
    desired=${line%%|*}
    period=${line#*|}
    desired_state_valid "$desired" || return 1
    if [[ -n "$period" ]]; then
        traffic_period_valid "$period" || return 1
    fi
    printf '%s\n%s\n' "$desired" "$period"
}

# BUG-28: hoisted from commit_traffic_pair_state().
# Restores traffic state files from backups. Args are triplets:
# $1/$2/$3=pair_existed/pair_backup/pair_target, $4/$5/$6=desired_*, $7/$8/$9=block_*.
__abox_traffic_state_rollback() {
    local pair_existed="$1" pair_backup="$2" pair_target="$3"
    local desired_existed="$4" desired_backup="$5" desired_target="$6"
    local block_existed="$7" block_backup="$8" block_target="$9"
    local restore_failed=0
    if (( pair_existed == 1 )); then
        cp -p -- "$pair_backup" "$pair_target" 2>/dev/null || restore_failed=1
    else
        rm -f -- "$pair_target" 2>/dev/null || restore_failed=1
    fi
    if (( desired_existed == 1 )); then
        cp -p -- "$desired_backup" "$desired_target" 2>/dev/null || restore_failed=1
    else
        rm -f -- "$desired_target" 2>/dev/null || restore_failed=1
    fi
    if (( block_existed == 1 )); then
        cp -p -- "$block_backup" "$block_target" 2>/dev/null || restore_failed=1
    else
        rm -f -- "$block_target" 2>/dev/null || restore_failed=1
    fi
    rm -f -- "$pair_backup" "$desired_backup" "$block_backup"
    return "$restore_failed"
}
commit_traffic_pair_state() {
    local desired="$1" period="${2:-}"
    local pair_backup="" desired_backup="" block_backup=""
    local pair_existed=0 desired_existed=0 block_existed=0
    local restore_failed=0
    desired_state_valid "$desired" || return 1
    if [[ -n "$period" ]]; then
        traffic_period_valid "$period" || return 1
    fi
    ensure_abox_dir_owned "$ABOX_DIR" >/dev/null 2>&1 || return 1
    # Snapshot all three files for full transactional rollback.
    if [[ -f "$ABOX_TRAFFIC_PAIR_STATE" ]]; then
        pair_existed=1; pair_backup=$(mktemp) || return 1
        cp -p -- "$ABOX_TRAFFIC_PAIR_STATE" "$pair_backup" || { rm -f -- "$pair_backup"; return 1; }
    fi
    if [[ -f "$ABOX_DESIRED_STATE" ]]; then
        desired_existed=1; desired_backup=$(mktemp) || { rm -f -- "$pair_backup"; return 1; }
        cp -p -- "$ABOX_DESIRED_STATE" "$desired_backup" || { rm -f -- "$pair_backup" "$desired_backup"; return 1; }
    fi
    if [[ -f "$ABOX_TRAFFIC_BLOCK_STATE" ]]; then
        block_existed=1; block_backup=$(mktemp) || { rm -f -- "$pair_backup" "$desired_backup"; return 1; }
        cp -p -- "$ABOX_TRAFFIC_BLOCK_STATE" "$block_backup" || { rm -f -- "$pair_backup" "$desired_backup" "$block_backup"; return 1; }
    fi
    # Rollback helper: restore all three files to snapshot state. Reports failure.
    # 1) Atomic pair publish (sole authority for modern readers).
    write_file_atomically_from_stdin "$ABOX_TRAFFIC_PAIR_STATE" 600 <<< "${desired}|${period}" || { __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE"; return 1; }
    # 2) Derive legacy files only after pair is durable.
    if ! write_file_atomically_from_stdin "$ABOX_DESIRED_STATE" 600 <<< "$desired"; then
        __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE" || msg "${RED}[!] Traffic state rollback incomplete; manual check required.${NC}" >&2
        return 1
    fi
    if [[ -n "$period" ]]; then
        if ! write_file_atomically_from_stdin "$ABOX_TRAFFIC_BLOCK_STATE" 600 <<< "$period"; then
            __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE" || msg "${RED}[!] Traffic state rollback incomplete; manual check required.${NC}" >&2
            return 1
        fi
    else
        if [[ -e "$ABOX_TRAFFIC_BLOCK_STATE" || -L "$ABOX_TRAFFIC_BLOCK_STATE" ]]; then
            path_tree_has_mountpoint "$ABOX_TRAFFIC_BLOCK_STATE" && { __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE" >/dev/null 2>&1; return 1; }
            rm -f -- "$ABOX_TRAFFIC_BLOCK_STATE" || { __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE" >/dev/null 2>&1; return 1; }
            [[ ! -e "$ABOX_TRAFFIC_BLOCK_STATE" && ! -L "$ABOX_TRAFFIC_BLOCK_STATE" ]] || { __abox_traffic_state_rollback "$pair_existed" "$pair_backup" "$ABOX_TRAFFIC_PAIR_STATE" "$desired_existed" "$desired_backup" "$ABOX_DESIRED_STATE" "$block_existed" "$block_backup" "$ABOX_TRAFFIC_BLOCK_STATE" >/dev/null 2>&1; return 1; }
        fi
    fi
    rm -f -- "$pair_backup" "$desired_backup" "$block_backup"
}

get_desired_state() {
    local state='RUNNING' uid gid mode pair desired period
    if pair=$(read_traffic_pair_fields); then
        IFS= read -r desired <<< "$pair"
        printf '%s\n' "$desired"
        return 0
    fi
    if [[ -e "$ABOX_DESIRED_STATE" || -L "$ABOX_DESIRED_STATE" ]]; then
        [[ -r "$ABOX_DESIRED_STATE" && -f "$ABOX_DESIRED_STATE" && ! -L "$ABOX_DESIRED_STATE" ]] || return 1
        uid=$(stat -c %u "$ABOX_DESIRED_STATE" 2>/dev/null) || return 1
        gid=$(stat -c %g "$ABOX_DESIRED_STATE" 2>/dev/null) || return 1
        mode=$(stat -c %a "$ABOX_DESIRED_STATE" 2>/dev/null) || return 1
        [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
        (( (8#$mode & 8#077) == 0 )) || return 1
        IFS= read -r state < "$ABOX_DESIRED_STATE" || return 1
        desired_state_valid "$state" || return 1
    fi
    printf '%s\n' "$state"
}

# FINAL-AUDIT fix: distinguish "pair file does not exist" (safe to create
# with defaults) from "pair file exists but is unreadable/corrupt" (must
# refuse to overwrite, or a quota block could be silently cleared / a
# MANUAL_STOPPED state silently flipped by committing defaults).
traffic_pair_file_exists() {
    [[ -e "$ABOX_TRAFFIC_PAIR_STATE" || -L "$ABOX_TRAFFIC_PAIR_STATE" ]]
}

set_desired_state() {
    local state="$1" period=''
    desired_state_valid "$state" || return 1
    if traffic_pair_file_exists && ! read_traffic_pair_fields >/dev/null 2>&1; then
        msg "${RED}[!] Traffic pair state exists but is unreadable or corrupt; refusing to overwrite. Manual repair required.${NC}" >&2
        return 1
    fi
    period=$(get_traffic_block_period 2>/dev/null || true)
    commit_traffic_pair_state "$state" "$period"
}

get_traffic_block_period() {
    local period uid gid mode pair desired
    if pair=$(read_traffic_pair_fields); then
        desired=${pair%%$'\n'*}
        # FIX: When the period is empty, command substitution strips the
        # trailing newline, so pair="RUNNING" with no newline at all. The
        # naive ${pair#*$'\n'} then returns "RUNNING" unchanged (no match),
        # which passes -n and later fails commit validation. Detect the
        # missing newline explicitly and treat the period as empty.
        if [[ "$pair" == *$'\n'* ]]; then
            period=${pair#*$'\n'}
        else
            period=""
        fi
        [[ -n "$period" ]] || return 1
        printf '%s\n' "$period"
        return 0
    fi
    [[ -r "$ABOX_TRAFFIC_BLOCK_STATE" && -f "$ABOX_TRAFFIC_BLOCK_STATE" && ! -L "$ABOX_TRAFFIC_BLOCK_STATE" ]] || return 1
    uid=$(stat -c %u "$ABOX_TRAFFIC_BLOCK_STATE" 2>/dev/null) || return 1
    gid=$(stat -c %g "$ABOX_TRAFFIC_BLOCK_STATE" 2>/dev/null) || return 1
    mode=$(stat -c %a "$ABOX_TRAFFIC_BLOCK_STATE" 2>/dev/null) || return 1
    [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#077) == 0 )) || return 1
    IFS= read -r period < "$ABOX_TRAFFIC_BLOCK_STATE" || return 1
    traffic_period_valid "$period" || return 1
    printf '%s\n' "$period"
}

set_traffic_block_period() {
    local period="$1" state
    traffic_period_valid "$period" || return 1
    if traffic_pair_file_exists && ! read_traffic_pair_fields >/dev/null 2>&1; then
        msg "${RED}[!] Traffic pair state exists but is unreadable or corrupt; refusing to overwrite. Manual repair required.${NC}" >&2
        return 1
    fi
    state=$(get_desired_state) || return 1
    commit_traffic_pair_state "$state" "$period"
}

clear_traffic_block_period() {
    local state pair_fields
    # B-03 fix: if the block file is absent AND the pair state exists but is
    # unreadable/corrupt, that is an error, not "nothing to clean".
    # If neither file ever existed (fresh box / never configured), there is
    # genuinely nothing to clean.
    if [[ ! -e "$ABOX_TRAFFIC_BLOCK_STATE" && ! -L "$ABOX_TRAFFIC_BLOCK_STATE" ]]; then
        if [[ ! -e "$ABOX_TRAFFIC_PAIR_STATE" && ! -L "$ABOX_TRAFFIC_PAIR_STATE" ]]; then
            return 0
        fi
        if ! pair_fields=$(read_traffic_pair_fields 2>/dev/null); then
            msg "${RED}[!] Traffic pair state is unreadable or corrupt; refusing to treat as clean.${NC}" >&2
            return 1
        fi
        [[ -z "$(sed -n '2p' <<< "$pair_fields")" ]] && return 0
    fi
    state=$(get_desired_state) || return 1
    commit_traffic_pair_state "$state" ""
}

validate_abox_env_file_for_write() {
    [[ -f "$ABOX_ENV" && ! -L "$ABOX_ENV" ]] || return 1
    path_owned_by_root "$ABOX_ENV" || return 1
    path_mode_has_no_group_other_write "$ABOX_ENV" || return 1
    load_abox_env "$ABOX_ENV" >/dev/null 2>&1 || return 1
}

remove_abox_env_file() {
    [[ ! -e "$ABOX_ENV" && ! -L "$ABOX_ENV" ]] && return 0
    validate_abox_env_file_for_write || return 1
    path_tree_has_mountpoint "$ABOX_ENV" && return 1
    rm -f -- "$ABOX_ENV" || return 1
    [[ ! -e "$ABOX_ENV" && ! -L "$ABOX_ENV" ]]
}

remove_owned_runtime_helper() {
    local path="$1"
    [[ ! -e "$path" && ! -L "$path" ]] && return 0
    auxiliary_content_is_abox_managed "$path" "$path" || return 1
    path_tree_has_mountpoint "$path" && return 1
    rm -f -- "$path" || return 1
    [[ ! -e "$path" && ! -L "$path" ]]
}

update_traffic_state_atomically() {
    local limit="${1:-}" mode="${2:-}" tmp
    # Fresh boxes may have no .env yet (no deployment); create it securely
    # so a traffic limit can be set standalone.
    if [[ ! -e "$ABOX_ENV" && ! -L "$ABOX_ENV" ]]; then
        ensure_abox_dir_owned "$ABOX_DIR" >/dev/null 2>&1 || return 1
        install -m 600 /dev/null "$ABOX_ENV" || return 1
        if [[ $EUID -eq 0 ]]; then chown root:root "$ABOX_ENV" || { rm -f -- "$ABOX_ENV"; return 1; }; fi
    fi
    validate_abox_env_file_for_write || return 1
    ensure_abox_dir_owned "$ABOX_DIR" >/dev/null 2>&1 || return 1
    tmp=$(mktemp "$ABOX_DIR/.env.A-Box-update.XXXXXX") || return 1
    awk '!/^TRAFFIC_LIMIT_GB=/ && !/^TRAFFIC_LIMIT_MODE=/' "$ABOX_ENV" > "$tmp" || { rm -f "$tmp"; return 1; }
    if [[ -n "$limit" ]]; then
        valid_traffic_limit_gb "$limit" || { rm -f "$tmp"; return 1; }
        [[ "$mode" =~ ^(total|rx|tx)$ ]] || { rm -f "$tmp"; return 1; }
        printf 'TRAFFIC_LIMIT_GB=%q\nTRAFFIC_LIMIT_MODE=%q\n' "$limit" "$mode" >> "$tmp" || { rm -f "$tmp"; return 1; }
    fi
    chmod 600 "$tmp" || { rm -f "$tmp"; return 1; }
    if [[ $EUID -eq 0 ]]; then chown root:root "$tmp" || { rm -f "$tmp"; return 1; }; fi
    sync -f "$tmp" 2>/dev/null || true
    mv -f "$tmp" "$ABOX_ENV" || { rm -f "$tmp"; return 1; }
}

reset_protocol_vars() {
    unset UUID VLESS_SNI VISION_SNI XHTTP_SNI VLESS_PORT XHTTP_PORT HY2_BASE_PORT HY2_DOMAIN HY2_UP HY2_DOWN HY2_MASQ_URL
    unset SS_PORT SS_WHITELIST_IP PUBLIC_KEY PBK SHORT_ID HY2_PASS HY2_OBFS SS_PASS
    unset HY2_CERT_SHA256_FP HY2_CERT_PUBKEY_SHA256_B64 HY2_HOP HY2_HOP_IMPL HY2_MONITOR_PORT
    unset HY2_ACME_TYPE HY2_ACME_DNS_PROVIDER HY2_ACME_DNS_CF_API_TOKEN
    unset HY2_URI_PORTS HY2_CLASH_PORTS HY2_SB_PORTS HY2_RANGE_START HY2_RANGE_END ENABLE_KEEPALIVE
    unset SOCKS_PORT SOCKS_USER SOCKS_PASS SOCKS_PROTO
}

path_parent_chain_safe() {
    local target="$1" current
    [[ "$target" == /* ]] || return 1
    current=$(dirname -- "$target")
    while :; do
        [[ "$current" == '/' ]] && return 0
        [[ ! -L "$current" ]] || return 1
        if [[ -e "$current" && ! -d "$current" ]]; then
            return 1
        fi
        current=$(dirname -- "$current")
    done
}

write_file_atomically_from_stdin() {
    local dest="$1" mode="${2:-600}" dir tmp
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    [[ ! -e "$dest" && ! -L "$dest" || -f "$dest" ]] || return 1
    [[ ! -L "$dest" && ! -d "$dest" ]] || return 1
    path_parent_chain_safe "$dest" || return 1
    if [[ -e "$dest" || -L "$dest" ]] && path_is_mountpoint "$dest"; then
        return 1
    fi
    dir=$(dirname "$dest")
    if [[ -L "$dir" || ( -e "$dir" && ! -d "$dir" ) ]]; then
        return 1
    fi
    [[ -d "$dir" ]] || mkdir -p "$dir" || return 1
    tmp=$(mktemp "${dest}.A-Box-new.XXXXXX") || return 1
    cat > "$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod "$mode" "$tmp" || { rm -f -- "$tmp"; return 1; }
    if [[ $EUID -eq 0 ]]; then chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }; fi
    sync -f "$tmp" 2>/dev/null || true
    mv -f -- "$tmp" "$dest" || { rm -f -- "$tmp"; return 1; }
    sync -f "$dir" 2>/dev/null || true
}

write_env() {
    local env_core="${1:-${CORE:-}}" env_mode="${2:-${MODE:-}}" old_traffic_limit_gb='' old_traffic_limit_mode='' tmp
    [[ -n "$env_core" && -n "$env_mode" ]] || die "$(tr_msg we_missing)"
    [[ ! -L "$ABOX_DIR" ]] || die "$(tr_msg we_dir_symlink)"
    if [[ -e "$ABOX_ENV" ]]; then
        [[ -f "$ABOX_ENV" && ! -L "$ABOX_ENV" ]] || die "$(tr_msg we_file_unsafe)"
        path_owned_by_root "$ABOX_ENV" || die "$(tr_msg we_file_owner)"
        path_mode_has_no_group_other_write "$ABOX_ENV" || die "$(tr_msg we_file_mode)"
    fi
    if [[ -f "$ABOX_ENV" && ! -L "$ABOX_ENV" ]]; then
        old_traffic_limit_gb=$(grep '^TRAFFIC_LIMIT_GB=' "$ABOX_ENV" | tail -n 1 | cut -d= -f2- | tr -d '"')
        old_traffic_limit_mode=$(grep '^TRAFFIC_LIMIT_MODE=' "$ABOX_ENV" | tail -n 1 | cut -d= -f2- | tr -d '"')
        if [[ -z "$old_traffic_limit_gb" ]] || ! valid_traffic_limit_gb "$old_traffic_limit_gb" || [[ "$old_traffic_limit_mode" != total && "$old_traffic_limit_mode" != rx && "$old_traffic_limit_mode" != tx ]]; then
            old_traffic_limit_gb=''
            old_traffic_limit_mode=''
        fi
    fi
    umask 077
    install -d -m 700 "$ABOX_DIR" || die "$(tr_msg we_dir_create)"
    tmp=$(mktemp "$ABOX_DIR/.env.A-Box-new.XXXXXX") || die "$(tr_msg we_tmp)"
    {
        printf 'CORE=%s\n' "$(shell_quote "$env_core")"
        printf 'MODE=%s\n' "$(shell_quote "$env_mode")"
        printf 'UUID=%s\n' "$(shell_quote "${UUID:-}")"
        printf 'VLESS_SNI=%s\n' "$(shell_quote "${VLESS_SNI:-}")"
        printf 'VISION_SNI=%s\n' "$(shell_quote "${VISION_SNI:-}")"
        printf 'XHTTP_SNI=%s\n' "$(shell_quote "${XHTTP_SNI:-}")"
        printf 'VLESS_PORT=%s\n' "$(shell_quote "${VLESS_PORT:-}")"
        printf 'XHTTP_PORT=%s\n' "$(shell_quote "${XHTTP_PORT:-}")"
        printf 'HY2_BASE_PORT=%s\n' "$(shell_quote "${HY2_BASE_PORT:-}")"
        printf 'HY2_DOMAIN=%s\n' "$(shell_quote "${HY2_DOMAIN:-}")"
        printf 'HY2_UP=%s\n' "$(shell_quote "${HY2_UP:-}")"
        printf 'HY2_DOWN=%s\n' "$(shell_quote "${HY2_DOWN:-}")"
        printf 'HY2_MASQ_URL=%s\n' "$(shell_quote "${HY2_MASQ_URL:-}")"
        printf 'SS_PORT=%s\n' "$(shell_quote "${SS_PORT:-}")"
        printf 'SS_WHITELIST_IP=%s\n' "$(shell_quote "${SS_WHITELIST_IP:-}")"
        printf 'SOCKS_PORT=%s\n' "$(shell_quote "${SOCKS_PORT:-}")"
        printf 'SOCKS_USER=%s\n' "$(shell_quote "${SOCKS_USER:-}")"
        printf 'SOCKS_PASS=%s\n' "$(shell_quote "${SOCKS_PASS:-}")"
        printf 'SOCKS_PROTO=%s\n' "$(shell_quote "${SOCKS_PROTO:-}")"
        printf 'PUBLIC_KEY=%s\n' "$(shell_quote "${PUBLIC_KEY:-${PBK:-}}")"
        printf 'SHORT_ID=%s\n' "$(shell_quote "${SHORT_ID:-}")"
        printf 'HY2_PASS=%s\n' "$(shell_quote "${HY2_PASS:-}")"
        printf 'HY2_OBFS=%s\n' "$(shell_quote "${HY2_OBFS:-}")"
        printf 'SS_PASS=%s\n' "$(shell_quote "${SS_PASS:-}")"
        printf 'LINK_IP=%s\n' "$(shell_quote "${LINK_IP:-${GLOBAL_PUBLIC_IP:-}}")"
        printf 'HY2_CERT_SHA256_FP=%s\n' "$(shell_quote "${HY2_CERT_SHA256_FP:-}")"
        printf 'HY2_CERT_PUBKEY_SHA256_B64=%s\n' "$(shell_quote "${HY2_CERT_PUBKEY_SHA256_B64:-}")"
        printf 'HY2_HOP=%s\n' "$(shell_quote "${HY2_HOP:-}")"
        printf 'HY2_HOP_IMPL=%s\n' "$(shell_quote "${HY2_HOP_IMPL:-none}")"
        printf 'HY2_MONITOR_PORT=%s\n' "$(shell_quote "${HY2_MONITOR_PORT:-}")"
        printf 'HY2_ACME_TYPE=%s\n' "$(shell_quote "${HY2_ACME_TYPE:-http}")"
        printf 'HY2_ACME_DNS_PROVIDER=%s\n' "$(shell_quote "${HY2_ACME_DNS_PROVIDER:-}")"
        printf 'HY2_ACME_DNS_CF_API_TOKEN=%s\n' "$(shell_quote "${HY2_ACME_DNS_CF_API_TOKEN:-}")"
        printf 'HY2_URI_PORTS=%s\n' "$(shell_quote "${HY2_URI_PORTS:-}")"
        printf 'HY2_CLASH_PORTS=%s\n' "$(shell_quote "${HY2_CLASH_PORTS:-}")"
        printf 'HY2_SB_PORTS=%s\n' "$(shell_quote "${HY2_SB_PORTS:-}")"
        printf 'HY2_RANGE_START=%s\n' "$(shell_quote "${HY2_RANGE_START:-}")"
        printf 'HY2_RANGE_END=%s\n' "$(shell_quote "${HY2_RANGE_END:-}")"
        printf 'INGRESS_IF=%s\n' "$(shell_quote "${INGRESS_IF:-}")"
        printf 'ENABLE_KEEPALIVE=%s\n' "$(shell_quote "${ENABLE_KEEPALIVE:-}")"
        [[ -n "$old_traffic_limit_gb" ]] && printf 'TRAFFIC_LIMIT_GB=%s\n' "$(shell_quote "$old_traffic_limit_gb")"
        [[ -n "$old_traffic_limit_mode" ]] && printf 'TRAFFIC_LIMIT_MODE=%s\n' "$(shell_quote "$old_traffic_limit_mode")"
        :
    } > "$tmp" || { rm -f -- "$tmp"; die "$(tr_msg we_write)"; }
    chmod 600 "$tmp" || { rm -f -- "$tmp"; die "$(tr_msg we_chmod)"; }
    mv -f -- "$tmp" "$ABOX_ENV" || { rm -f -- "$tmp"; die "$(tr_msg we_commit)"; }
}

validate_fail2ban_config_or_die() {
    command -v fail2ban-client >/dev/null 2>&1 || return 0
    local out sample
    if fail2ban-client -h 2>&1 | grep -E -- '(^|[[:space:]])-t([,[:space:]]|$)|--test' >/dev/null; then
        if ! out=$(fail2ban-client -t 2>&1); then
            msg "${YELLOW}[!] Fail2Ban 全局配置校验失败；可能由系统其它 jail 引起，A-Box 不会因此覆盖或删除其它 jail。${NC}"
            printf '%s\n' "$out" >&2
        fi
    else
        if ! out=$(fail2ban-client -d 2>&1); then
            msg "${YELLOW}[!] Fail2Ban 全局配置 dump 失败；可能由系统其它 jail 引起。${NC}"
            printf '%s\n' "$out" >&2
        fi
    fi
    if command -v fail2ban-regex >/dev/null 2>&1 && [[ -r /etc/fail2ban/filter.d/A-Box.conf ]]; then
        sample=$(umask 077; mktemp /tmp/A-Box-f2b-sample.XXXXXX) || die 'Fail2Ban sample creation failed.'
        cat > "$sample" <<'EOF_F2B_SAMPLE' || { rm -f -- "$sample"; die 'Fail2Ban sample write failed.'; }
2026-07-25T10:00:00Z process connection from 203.0.113.7:54321: message authentication failed
2026-07-25T10:00:01Z authentication failed from [2001:db8::7]:443
2026-07-25T10:00:02Z proxy/vless/inbound: invalid request from 198.51.100.9:44321 > proxy/vless/encoding
2026-07-25T10:00:03Z client=198.51.100.8 rejected
2026-07-25T10:00:04Z health check succeeded without authentication failure
EOF_F2B_SAMPLE
        out=$(fail2ban-regex "$sample" /etc/fail2ban/filter.d/A-Box.conf 2>&1) || { rm -f "$sample"; printf '%s\n' "$out" >&2; die "$(tr_msg fb_regex_fail)"; }
        rm -f "$sample"
        local summary matched_count missed_count
        summary=$(grep -E '^[[:space:]]*Lines: [0-9]+ lines?, [0-9]+ ignored, [0-9]+ matched, [0-9]+ missed' <<< "$out" | tail -n 1)
        matched_count=$(sed -nE 's/^[[:space:]]*Lines: [0-9]+ lines?, [0-9]+ ignored, ([0-9]+) matched, [0-9]+ missed.*/\1/p' <<< "$summary")
        missed_count=$(sed -nE 's/^[[:space:]]*Lines: [0-9]+ lines?, [0-9]+ ignored, [0-9]+ matched, ([0-9]+) missed.*/\1/p' <<< "$summary")
        [[ "$matched_count" =~ ^[0-9]+$ && "$missed_count" =~ ^[0-9]+$ ]] && (( matched_count >= 1 && missed_count >= 1 )) || { printf '%s\n' "$out" >&2; die 'Fail2Ban must match a representative failure log and leave a benign log unmatched.'; }
    fi
}

abox_log_files() {
    printf '%s\n' /var/log/A-Box-xray-access.log /var/log/A-Box-xray-error.log /var/log/A-Box-singbox.log /var/log/A-Box-hysteria.log /var/log/A-Box-traffic.log
}

abox_runtime_identity() {
    local family="$1"
    case "$family" in
        xray) printf '%s\t%s\n' "$ABOX_RUNTIME_XRAY_USER" "$ABOX_RUNTIME_XRAY_GROUP" ;;
        sing-box|singbox) printf '%s\t%s\n' "$ABOX_RUNTIME_SINGBOX_USER" "$ABOX_RUNTIME_SINGBOX_GROUP" ;;
        hysteria) printf '%s\t%s\n' "$ABOX_RUNTIME_HYSTERIA_USER" "$ABOX_RUNTIME_HYSTERIA_GROUP" ;;
        *) return 1 ;;
    esac
}

ensure_abox_runtime_identity() {
    local family="$1" user group uid gid shell
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || return 1
    getent group "$group" >/dev/null 2>&1 || {
        if command -v groupadd >/dev/null 2>&1; then
            groupadd --system "$group" >/dev/null 2>&1 || getent group "$group" >/dev/null 2>&1 || return 1
        elif [[ "${release:-}" == 'alpine' ]] && command -v addgroup >/dev/null 2>&1; then
            addgroup -S "$group" >/dev/null 2>&1 || getent group "$group" >/dev/null 2>&1 || return 1
        elif command -v addgroup >/dev/null 2>&1; then
            addgroup --system "$group" >/dev/null 2>&1 || getent group "$group" >/dev/null 2>&1 || return 1
        else
            return 1
        fi
    }
    if ! getent passwd "$user" >/dev/null 2>&1; then
        if command -v useradd >/dev/null 2>&1; then
            useradd --system --no-create-home --home-dir /nonexistent --shell /usr/sbin/nologin --gid "$group" "$user" >/dev/null 2>&1 || return 1
        elif [[ "${release:-}" == 'alpine' ]] && command -v adduser >/dev/null 2>&1; then
            adduser -S -D -H -s /sbin/nologin -G "$group" "$user" >/dev/null 2>&1 || return 1
        elif command -v adduser >/dev/null 2>&1; then
            adduser --system --no-create-home --home /nonexistent --shell /sbin/nologin --ingroup "$group" "$user" >/dev/null 2>&1 || return 1
        else
            return 1
        fi
    fi
    uid=$(id -u "$user" 2>/dev/null) || return 1
    gid=$(id -g "$user" 2>/dev/null) || return 1
    [[ "$uid" =~ ^[0-9]+$ && "$gid" =~ ^[0-9]+$ ]] || return 1
    (( uid != 0 && gid != 0 )) || return 1
    shell=$(getent passwd "$user" | awk -F: '{print $7}')
    [[ "$shell" == '/usr/sbin/nologin' || "$shell" == '/sbin/nologin' || "$shell" == '/bin/false' ]] || return 1
}

prepare_abox_runtime_config_dir() {
    local family="$1" dir="$2" user group gid mode nlink
    case "$family:$dir" in
        sing-box:/etc/sing-box|hysteria:/etc/hysteria|xray:/usr/local/etc/xray) ;;
        *) return 1 ;;
    esac
    ensure_abox_runtime_identity "$family" || return 1
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || return 1
    path_parent_chain_safe "$dir/.A-Box-config" || return 1
    [[ ! -L "$dir" && (! -e "$dir" || -d "$dir") ]] || return 1
    install -d -o root -g "$group" -m 750 -- "$dir" || return 1
    gid=$(getent group "$group" 2>/dev/null | awk -F: '{print $3}')
    [[ "$gid" =~ ^[1-9][0-9]*$ ]] || return 1
    [[ "$(stat -c %u:%g "$dir" 2>/dev/null || true)" == "0:$gid" ]] || return 1
    mode=$(stat -c %a "$dir" 2>/dev/null) || return 1
    nlink=$(stat -c %h "$dir" 2>/dev/null) || return 1
    [[ "$nlink" =~ ^[1-9][0-9]*$ && "$mode" =~ ^0?750$ ]] || return 1
}

prepare_abox_runtime_read_file() {
    local path="$1" family="$2" user group
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || return 1
    [[ -f "$path" && ! -L "$path" ]] || return 1
    path_parent_chain_safe "$path" || return 1
    [[ "$(stat -c %u:%g "$path" 2>/dev/null || true)" == 0:* ]] || return 1
    [[ "$(stat -c %h "$path" 2>/dev/null || true)" == 1 ]] || return 1
    chown "root:$group" "$path" || return 1
    chmod 640 "$path" || return 1
}

prepare_abox_runtime_write_file() {
    local path="$1" family="$2" user group
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || return 1
    path_parent_chain_safe "$path" || return 1
    if [[ ! -e "$path" && ! -L "$path" ]]; then
        install -o root -g "$group" -m 660 /dev/null "$path" || return 1
        return 0
    fi
    [[ -f "$path" && ! -L "$path" ]] || return 1
    [[ "$(stat -c %u:%g "$path" 2>/dev/null || true)" == 0:* ]] || return 1
    [[ "$(stat -c %h "$path" 2>/dev/null || true)" == 1 ]] || return 1
    chown "root:$group" "$path" || return 1
    chmod 660 "$path" || return 1
}

prepare_abox_runtime_permissions() {
    local family="$1"
    ensure_abox_runtime_identity "$family" || return 1
    case "$family" in
        xray)
            prepare_abox_runtime_config_dir xray /usr/local/etc/xray || return 1
            prepare_abox_runtime_read_file /usr/local/etc/xray/config.json xray || return 1
            prepare_abox_runtime_write_file /var/log/A-Box-xray-access.log xray || return 1
            prepare_abox_runtime_write_file /var/log/A-Box-xray-error.log xray || return 1
            ;;
        sing-box)
            prepare_abox_runtime_config_dir sing-box /etc/sing-box || return 1
            prepare_abox_runtime_read_file /etc/sing-box/config.json sing-box || return 1
            [[ ! -e /etc/sing-box/hy2.crt ]] || prepare_abox_runtime_read_file /etc/sing-box/hy2.crt sing-box || return 1
            [[ ! -e /etc/sing-box/hy2.key ]] || prepare_abox_runtime_read_file /etc/sing-box/hy2.key sing-box || return 1
            [[ ! -e /etc/sing-box/tuic.crt ]] || prepare_abox_runtime_read_file /etc/sing-box/tuic.crt sing-box || return 1
            [[ ! -e /etc/sing-box/tuic.key ]] || prepare_abox_runtime_read_file /etc/sing-box/tuic.key sing-box || return 1
            prepare_abox_runtime_write_file /var/log/A-Box-singbox.log sing-box || return 1
            ;;
        hysteria)
            prepare_abox_runtime_config_dir hysteria /etc/hysteria || return 1
            [[ ! -e /etc/hysteria/acme ]] || prepare_hysteria_acme_dir_ownership || return 1
            prepare_abox_runtime_read_file /etc/hysteria/config.yaml hysteria || return 1
            [[ ! -e /etc/hysteria/server.crt ]] || prepare_abox_runtime_read_file /etc/hysteria/server.crt hysteria || return 1
            [[ ! -e /etc/hysteria/server.key ]] || prepare_abox_runtime_read_file /etc/hysteria/server.key hysteria || return 1
            prepare_abox_runtime_write_file /var/log/A-Box-hysteria.log hysteria || return 1
            ;;
        *) return 1 ;;
    esac
}

assert_abox_log_file_safe() {
    local path="$1" uid gid mode nlink _group _gid _svc_uid
    [[ "$path" == /var/log/A-Box-*.log ]] || return 1
    [[ -d /var/log && ! -L /var/log ]] || return 1
    path_parent_chain_safe "$path" || return 1
    if [[ ! -e "$path" && ! -L "$path" ]]; then return 0; fi
    [[ -f "$path" && ! -L "$path" ]] || return 1
    uid=$(stat -c %u "$path" 2>/dev/null) || return 1
    gid=$(stat -c %g "$path" 2>/dev/null) || return 1
    mode=$(stat -c %a "$path" 2>/dev/null) || return 1
    nlink=$(stat -c %h "$path" 2>/dev/null) || return 1
    [[ "$nlink" == 1 ]] || return 1
    if [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^0?600$ ]]; then return 0; fi
    local _family _user
    for _family in xray sing-box hysteria; do
        IFS=$'\t' read -r _user _group < <(abox_runtime_identity "$_family") || continue
        [[ -n "${_group:-}" ]] || continue
        _gid=$(getent group "$_group" 2>/dev/null | awk -F: '{print $3}')
        _svc_uid=$(id -u "$_user" 2>/dev/null || true)
        if [[ -n "$_gid" && "$gid" == "$_gid" ]] && [[ "$uid" == 0 || ( -n "$_svc_uid" && "$uid" == "$_svc_uid" ) ]] && [[ "$mode" =~ ^0?6[046]0$ ]]; then
            return 0
        fi
    done
    return 1
}

ensure_abox_log_file() {
    local path="$1" family='' user group
    assert_abox_log_file_safe "$path" || die "$(tprintf lg_refuse "$path")"
    [[ -e "$path" ]] && return 0
    case "$path" in
        /var/log/A-Box-xray-*.log) family=xray ;;
        /var/log/A-Box-singbox.log) family=sing-box ;;
        /var/log/A-Box-hysteria.log) family=hysteria ;;
        /var/log/A-Box-traffic.log) install -o root -g root -m 600 /dev/null "$path" || die "$(tprintf lg_create "$path")"; return 0 ;;
        *) return 1 ;;
    esac
    ensure_abox_runtime_identity "$family" || die "$(tprintf lg_user "$family")"
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || die "$(tprintf lg_user_parse "$family")"
    install -o root -g "$group" -m 660 /dev/null "$path" || die "$(tprintf lg_create "$path")"
}

remove_abox_log_files() {
    local path
    while IFS= read -r path; do
        [[ -n "$path" ]] || continue
        [[ -e "$path" || -L "$path" ]] || continue
        assert_abox_log_file_safe "$path" || return 1
        path_tree_has_mountpoint "$path" && return 1
        rm -f -- "$path" || return 1
        [[ ! -e "$path" && ! -L "$path" ]] || return 1
    done < <(abox_log_files)
}

ensure_fail2ban() {
    command -v fail2ban-client >/dev/null 2>&1 && return 0
    msg "${YELLOW}[*] 未检测到 Fail2Ban, 正在自动安装 (主动防御需要)...${NC}"
    if command -v apt-get >/dev/null 2>&1; then
        apt-get update -y -q >/dev/null 2>&1 || true
        apt-get -y install fail2ban >/dev/null 2>&1 || true
    elif command -v dnf >/dev/null 2>&1; then
        dnf -y install fail2ban >/dev/null 2>&1 || true
    elif command -v yum >/dev/null 2>&1; then
        yum -y install fail2ban >/dev/null 2>&1 || true
    elif command -v apk >/dev/null 2>&1; then
        apk add --no-cache fail2ban >/dev/null 2>&1 || true
    fi
    if ! command -v fail2ban-client >/dev/null 2>&1; then
        msg "${RED}[!] Fail2Ban 自动安装失败, 主动防御 (日志封禁) 本次不生效; 节点本身不受影响。${NC}"
        return 1
    fi
    if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
        systemctl enable fail2ban >/dev/null 2>&1 || true
        systemctl start fail2ban >/dev/null 2>&1 || true
    elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then
        rc-update add fail2ban default >/dev/null 2>&1 || true
        rc-service fail2ban start >/dev/null 2>&1 9>&- 10>&- || true
    fi
    return 0
}

setup_active_defense() {
    local log_file
    msg "${YELLOW}[*] 正在挂载私有日志与 Fail2Ban 主动防御矩阵...${NC}"
    while IFS= read -r log_file; do
        [[ -n "$log_file" ]] || continue
        ensure_abox_log_file "$log_file"
    done < <(abox_log_files)
    assert_abox_auxiliary_safe /etc/logrotate.d/A-Box || die "$(tprintf ax_refuse "/etc/logrotate.d/A-Box")"
    write_file_atomically_from_stdin /etc/logrotate.d/A-Box 644 <<'EOF_LOGROTATE' || die 'logrotate 配置原子写入失败。'
# Managed by A-Box
/var/log/A-Box-*.log {
    su root root
    daily
    rotate 2
    size 50M
    missingok
    notifempty
    copytruncate
    compress
    # No "create …": copytruncate keeps the existing inode/ownership so
    # abox-xray / abox-singbox / abox-hysteria (mode 0660 root:group) can keep writing.
}
EOF_LOGROTATE
    ensure_fail2ban || true
    if command -v fail2ban-client >/dev/null 2>&1; then
        local tcp_ports='' udp_ports='' jail_tmp='' f2b_action='' f2b_backend='' f2b_tcp_action='' f2b_udp_action='' sb_harv='' xr_harv='' f2b_inc='' f2b_ver=''
        path_parent_chain_safe /etc/fail2ban/filter.d/A-Box.conf || die "$(tr_msg ad_filter_chain)"
        path_parent_chain_safe /etc/fail2ban/jail.d/A-Box.local || die "$(tr_msg ad_jail_chain)"
        mkdir -p /etc/fail2ban/filter.d /etc/fail2ban/jail.d || die "$(tr_msg ad_dirs)"
        assert_abox_auxiliary_safe /etc/fail2ban/filter.d/A-Box.conf || die "$(tprintf ax_refuse "/etc/fail2ban/filter.d/A-Box.conf")"
        assert_abox_auxiliary_safe /etc/fail2ban/jail.d/A-Box.local || die "$(tprintf ax_refuse "/etc/fail2ban/jail.d/A-Box.local")"
        jail_tmp=$(mktemp /etc/fail2ban/jail.d/.A-Box.local.A-Box-new.XXXXXX) || die "$(tr_msg ad_jail_tmp)"
        write_file_atomically_from_stdin /etc/fail2ban/filter.d/A-Box.conf 644 <<'EOF_F2B_FILTER' || { rm -f -- "$jail_tmp"; die 'Fail2Ban filter 原子写入失败。'; }
# Managed by A-Box
[Definition]
failregex = ^.*(?:authentication failed|message authentication failed).*?(?:from|client[=:])\s*\[?<HOST>\]?(?::[0-9]+)?(?:\s|:|$).*$
            ^.*(?:from|client[=:])\s*\[?<HOST>\]?(?::[0-9]+)?(?:\s|:).*?(?:authentication failed|message authentication failed).*$
            ^.*invalid request from[[:space:]]+\[?<HOST>\]?(?::[0-9]+)?(?:[[:space:]]|>|:|$).*$
ignoreregex =
EOF_F2B_FILTER
        [[ -n "${VLESS_PORT:-}" ]] && tcp_ports+="${VLESS_PORT},"
        [[ -n "${XHTTP_PORT:-}" ]] && tcp_ports+="${XHTTP_PORT},"
        [[ -n "${SS_PORT:-}" ]] && { tcp_ports+="${SS_PORT},"; udp_ports+="${SS_PORT},"; }
        [[ -n "${SOCKS_PORT:-}" ]] && { tcp_ports+="${SOCKS_PORT},"; udp_ports+="${SOCKS_PORT},"; }
        if [[ "${HY2_HOP:-}" == true && -n "${HY2_RANGE_START:-}" && -n "${HY2_RANGE_END:-}" ]]; then
            # P2-2: manual hop REDIRECTs to HY2_BASE_PORT in PREROUTING, so Fail2Ban
            # must monitor HY2_BASE_PORT in INPUT chain, not just the hop range.
            [[ "${HY2_HOP_IMPL:-}" == manual && -n "${HY2_BASE_PORT:-}" ]] && udp_ports+="${HY2_BASE_PORT},"
            udp_ports+="${HY2_RANGE_START}:${HY2_RANGE_END},"
        elif [[ -n "${HY2_BASE_PORT:-}" ]]; then
            udp_ports+="${HY2_BASE_PORT},"
        fi
        # Harvest public ports from the live core configs so standalone
        # protocols (TUIC/AnyTLS/ShadowTLS/Trojan/SOCKS landings) are covered
        # by the jails too. Loopback inbounds (Argo WS, detour targets) are
        # excluded: they have no public attack surface.
        if command -v jq >/dev/null 2>&1 && [[ -r /etc/sing-box/config.json ]]; then
            sb_harv=$(jq -r '.inbounds[]? | select(.listen_port != null) | select(.listen != "127.0.0.1" and .listen != "::1") | (if .type == "tuic" or .type == "hysteria2" then "udp/\(.listen_port)" elif .type == "shadowsocks" or .type == "socks" or .type == "mixed" then "tcp/\(.listen_port),udp/\(.listen_port)" else "tcp/\(.listen_port)" end)' /etc/sing-box/config.json 2>/dev/null | paste -sd, -)
            if [[ -n "$sb_harv" ]]; then
                tcp_ports+=",$(printf '%s' "$sb_harv" | tr ',' '\n' | awk -F/ '$1=="tcp" {print $2}' | paste -sd, -)"
                udp_ports+=",$(printf '%s' "$sb_harv" | tr ',' '\n' | awk -F/ '$1=="udp" {print $2}' | paste -sd, -)"
            fi
        fi
        if command -v jq >/dev/null 2>&1 && [[ -r /usr/local/etc/xray/config.json ]]; then
            xr_harv=$(jq -r '.inbounds[]? | select(.port != null and .tag != "api") | select(.listen == null or (.listen != "127.0.0.1" and .listen != "::1")) | (if .protocol == "shadowsocks" or .protocol == "socks" then "tcp/\(.port),udp/\(.port)" else "tcp/\(.port)" end)' /usr/local/etc/xray/config.json 2>/dev/null | paste -sd, -)
            if [[ -n "$xr_harv" ]]; then
                tcp_ports+=",$(printf '%s' "$xr_harv" | tr ',' '\n' | awk -F/ '$1=="tcp" {print $2}' | paste -sd, -)"
                udp_ports+=",$(printf '%s' "$xr_harv" | tr ',' '\n' | awk -F/ '$1=="udp" {print $2}' | paste -sd, -)"
            fi
        fi
        tcp_ports=$(printf '%s' "$tcp_ports" | tr ',' '\n' | awk 'NF && !seen[$0]++' | paste -sd, -)
        udp_ports=$(printf '%s' "$udp_ports" | tr ',' '\n' | awk 'NF && !seen[$0]++' | paste -sd, -)
        # Repeat offenders: exponential bantime growth (fail2ban >= 0.11 only;
        # older parsers reject the keys, so gate on the client version).
        f2b_ver=$(fail2ban-client --version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+' | head -1)
        if [[ -n "$f2b_ver" ]] && awk -v v="$f2b_ver" 'BEGIN { split(v, a, "."); exit !(a[1] > 0 || (a[1] == 0 && a[2] >= 11)) }'; then
            f2b_inc='bantime.increment = true
bantime.factor = 2
bantime.maxtime = 86400'
        fi
        tcp_ports="${tcp_ports%,}"; udp_ports="${udp_ports%,}"
        if [[ -n "$tcp_ports" || -n "$udp_ports" ]]; then
            f2b_backend=$(firewall_backend) || { rm -f -- "$jail_tmp"; die "$(tr_msg ad_backend_unknown)"; }
            case "$f2b_backend" in
                firewalld)
                    # firewallcmd-multiport invokes iptables -m multiport --dports (requires colon port ranges).
                    f2b_action='firewallcmd-multiport'
                    ;;
                ufw) f2b_action='ufw' ;;
                iptables) f2b_action='iptables-multiport' ;;
                *) rm -f -- "$jail_tmp"; die "$(tprintf ad_backend_unsupported "$f2b_backend")" ;;
            esac
            [[ -r "/etc/fail2ban/action.d/${f2b_action}.conf" ]] || {
                rm -f -- "$jail_tmp"
                die "$(tprintf ad_action_missing "$f2b_action")"
            }
            if [[ "$f2b_action" == 'ufw' ]]; then
                # Stock Fail2Ban UFW action blocks the offending source host-wide;
                # do not attach misleading port/protocol arguments to it.
                f2b_tcp_action='ufw[name=A-Box-tcp]'
                f2b_udp_action='ufw[name=A-Box-udp]'
            else
                f2b_tcp_action="${f2b_action}[name=A-Box-tcp, port=\"${tcp_ports}\", protocol=tcp]"
                f2b_udp_action="${f2b_action}[name=A-Box-udp, port=\"${udp_ports}\", protocol=udp]"
            fi
        fi
        printf '%s\n' '# Managed by A-Box' > "$jail_tmp" || { rm -f -- "$jail_tmp"; die 'Fail2Ban jail file initialization failed.'; }
        if [[ -n "$tcp_ports" ]]; then cat >> "$jail_tmp" <<EOF_F2B_TCP
[A-Box-tcp]
enabled = true
ignoreip = 127.0.0.1/8 ::1
port = ${tcp_ports}
filter = A-Box
logpath = /var/log/A-Box-xray-error.log
          /var/log/A-Box-singbox.log
          /var/log/A-Box-hysteria.log
maxretry = 8
findtime = 120
bantime = 3600
${f2b_inc}
action = ${f2b_tcp_action}

EOF_F2B_TCP
        fi
        if [[ -n "$udp_ports" ]]; then cat >> "$jail_tmp" <<EOF_F2B_UDP
[A-Box-udp]
enabled = true
ignoreip = 127.0.0.1/8 ::1
port = ${udp_ports}
filter = A-Box
logpath = /var/log/A-Box-singbox.log
          /var/log/A-Box-hysteria.log
maxretry = 8
findtime = 120
bantime = 3600
${f2b_inc}
action = ${f2b_udp_action}
EOF_F2B_UDP
        fi
        if [[ -n "$tcp_ports" || -n "$udp_ports" ]]; then
            chmod 644 "$jail_tmp" || { rm -f -- "$jail_tmp"; die "$(tr_msg ad_jail_chmod)"; }
            mv -f -- "$jail_tmp" /etc/fail2ban/jail.d/A-Box.local || { rm -f -- "$jail_tmp"; die "$(tr_msg ad_jail_commit)"; }
            validate_fail2ban_config_or_die
            if [[ "${INIT_SYS:-}" == systemd ]]; then
                systemctl restart fail2ban >/dev/null 2>&1 || msg "${YELLOW}[!] Fail2Ban 重启失败；不影响 A-Box 核心服务提交。${NC}"
            else
                rc-service fail2ban restart >/dev/null 2>&1 9>&- 10>&- || msg "${YELLOW}[!] Fail2Ban 重启失败；不影响 A-Box 核心服务提交。${NC}"
            fi
        else
            rm -f -- "$jail_tmp"
            remove_owned_auxiliary_path /etc/fail2ban/jail.d/A-Box.local || die "$(tr_msg ad_jail_remove)"
        fi
    fi
}


hysteria_official_hop_firewall_ok() {
    local start="${1:-${HY2_RANGE_START:-}}" end="${2:-${HY2_RANGE_END:-}}" first="${3:-${HY2_MONITOR_PORT:-${HY2_RANGE_START:-}}}"
    local first_other=''
    [[ "$start" =~ ^[0-9]+$ && "$end" =~ ^[0-9]+$ && "$first" =~ ^[0-9]+$ ]] || return 1
    (( 10#$start <= 10#$end && 10#$first <= 10#$end )) || return 1
    first_other=$((10#$start + 1))
    if command -v iptables >/dev/null 2>&1; then
        if _iptables_q iptables -t nat -S PREROUTING 2>/dev/null | grep -Eq -- "-p udp[[:space:]].*--dport (${start}:${end}|${first_other}:${end}) .*REDIRECT --to-ports ${first}([[:space:]]|$)"; then
            if has_ipv6; then
                command -v ip6tables >/dev/null 2>&1 && _iptables_q ip6tables -t nat -S PREROUTING 2>/dev/null | grep -Eq -- "-p udp[[:space:]].*--dport (${start}:${end}|${first_other}:${end}) .*REDIRECT --to-ports ${first}([[:space:]]|$)" || return 1
            fi
            return 0
        fi
    fi
    if command -v nft >/dev/null 2>&1; then
        nft list ruleset 2>/dev/null | grep -Eq -- "udp dport (${start}-${end}|${first_other}-${end}).*redirect to :${first}([[:space:]]|$)" && return 0
    fi
    return 1
}


setup_health_monitor() {
    msg "${YELLOW}[*] 正在注入带锁、连续失败阈值与退避的 L4 健康探针...${NC}"
    install -d -m 700 "$ABOX_DIR" || die "$(tr_msg hm_dir)"
    write_file_atomically_from_stdin "$ABOX_DIR/socket_probe.sh" 700 <<'EOF_PROBE' || die '健康探针原子写入失败。'
#!/usr/bin/env bash
# Managed by A-Box
# A-06: umask 077 ensures lock/temp files are 0600 (not world-readable 0644).
umask 077
set -o pipefail
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin
ENV=/etc/ddr/.env
read_ip_pref() {
    local pref='dual' mode
    local pref_file='/etc/ddr/.ip-pref'
    if [[ -r "$pref_file" && -f "$pref_file" && ! -L "$pref_file" && "$(stat -c %u:%g "$pref_file" 2>/dev/null || true)" == '0:0' ]]; then
        mode=$(stat -c %a "$pref_file" 2>/dev/null) || mode='777'
        if [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#022) == 0 )); then
            pref=$(tr -d '[:space:]' < "$pref_file" 2>/dev/null || true)
        fi
    fi
    [[ "$pref" =~ ^(ipv4|ipv6|dual)$ ]] || pref='dual'
    printf '%s\n' "$pref"
}
LOCK=/run/A-Box-socket-probe.lock
STATE=/run/A-Box-socket-probe.fail
DESIRED=/etc/ddr/.desired_state
PAIR_STATE=/etc/ddr/.traffic-pair-state
INIT_SYS_EXPECTED='unknown'
exec 9>>"$LOCK" || exit 0
flock -n 9 || exit 0
RUNTIME_LOCK=/run/A-Box.lock
acquire_abox_runtime_guard() {
    local FALLBACK_DIR=/run/A-Box.lock.d fb_pid fb_start fb_actual mode
    [[ -d /run && ! -L /run ]] || exit 0
    # If a live fallback lock is held by another A-Box process, yield. Helpers
    # must not treat an idle LOCK_FILE flock as free while main owns fallback.
    if [[ -d "$FALLBACK_DIR" && ! -L "$FALLBACK_DIR" && -r "$FALLBACK_DIR/pid" && -r "$FALLBACK_DIR/starttime" ]]; then
