    for_expected_services stop_owned || { traffic_error 'traffic limit reached but at least one owned service could not be stopped'; exit 1; }
elif [[ "$desired" == TRAFFIC_BLOCKED ]]; then
    # Same-period blocks remain fail-closed even if vnStat later reports a lower value.
    for_expected_services stop_owned || { traffic_error 'traffic-blocked state could not be fully enforced'; exit 1; }
fi
EOF_TRAFFIC
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        sed -i "s|^INIT_SYS_EXPECTED=.*|INIT_SYS_EXPECTED='systemd'|" "$ABOX_DIR/traffic_monitor.sh" || { msg "${RED}[!] 流量监控脚本运行环境标记写入失败。${NC}" >&2; return 1; }
    else
        sed -i "s|^INIT_SYS_EXPECTED=.*|INIT_SYS_EXPECTED='openrc'|" "$ABOX_DIR/traffic_monitor.sh" || { msg "${RED}[!] 流量监控脚本运行环境标记写入失败。${NC}" >&2; return 1; }
    fi
    grep -Fxq "INIT_SYS_EXPECTED='${INIT_SYS}'" "$ABOX_DIR/traffic_monitor.sh" || { msg "${RED}[!] 流量监控脚本运行环境标记后置校验失败。${NC}" >&2; return 1; }
    chmod 700 "$ABOX_DIR/traffic_monitor.sh" || { msg "${RED}[!] 流量监控脚本权限设置失败。${NC}" >&2; return 1; }
    [[ -z "${ABOX_TRAFFIC_TX_DIR:-}" ]] || capture_traffic_quota_expected_state "$ABOX_TRAFFIC_TX_DIR" || { msg "${RED}[!] 流量限制监控脚本事务快照失败。${NC}" >&2; return 1; }
    ( ABOX_DIE_HOOK=''; install_abox_cron_block TRAFFIC '* * * * * /bin/bash /etc/ddr/traffic_monitor.sh >/dev/null 2>&1' ) || { msg "${RED}[!] 流量限制 cron 写入失败。${NC}" >&2; return 1; }
    [[ -z "${ABOX_TRAFFIC_TX_DIR:-}" ]] || capture_traffic_quota_expected_state "$ABOX_TRAFFIC_TX_DIR" || { msg "${RED}[!] 流量限制 cron 事务快照失败。${NC}" >&2; return 1; }
}

disable_traffic_monitor() {
    remove_abox_cron_block TRAFFIC || return 1
    remove_owned_runtime_helper "$ABOX_DIR/traffic_monitor.sh" || return 1
    clear_traffic_block_period || return 1
}

traffic_snapshot_file_hash() {
    local file="$1"
    [[ -f "$file" && ! -L "$file" ]] || return 1
    sha256sum "$file" 2>/dev/null | awk '{print $1}'
}

capture_traffic_env_state_file() {
    local source_file="$1" out="$2"
    # Symlink: reject (security, unchanged).
    [[ ! -L "$source_file" ]] || return 1
    # Missing env file: fresh system where no core was installed yet; treat as
    # "no traffic limit configured" instead of a fatal error.
    if [[ ! -f "$source_file" ]]; then
        : > "$out" || return 1
        return 0
    fi
    awk '/^TRAFFIC_LIMIT_(GB|MODE)=/{print}' "$source_file" | LC_ALL=C sort > "$out"
}

capture_traffic_optional_state() {
    local source_file="$1" out="$2" hash
    [[ "$out" == /* || "$out" == */* ]] || return 1
    if [[ -e "$source_file" || -L "$source_file" ]]; then
        [[ -f "$source_file" && ! -L "$source_file" ]] || return 1
        hash=$(traffic_snapshot_file_hash "$source_file") || return 1
        printf 'present|%s\n' "$hash" > "$out"
    else
        printf '%s\n' 'absent' > "$out"
    fi
}

traffic_optional_state_matches_expected() {
    local source_file="$1" expected_file="$2" expected='' actual=''
    [[ -f "$expected_file" && ! -L "$expected_file" ]] || return 1
    IFS= read -r expected < "$expected_file" || return 1
    if [[ "$expected" == absent ]]; then
        [[ ! -e "$source_file" && ! -L "$source_file" ]]
        return $?
    fi
    [[ "$expected" == present\|* ]] || return 1
    [[ -f "$source_file" && ! -L "$source_file" ]] || return 2
    actual=$(traffic_snapshot_file_hash "$source_file" 2>/dev/null || true)
    [[ "$actual" == "${expected#present|}" ]]
}

capture_vnstat_runtime_state() {
    local name='' active enabled
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        if systemctl list-unit-files vnstat.service >/dev/null 2>&1; then
            name=vnstat
        elif systemctl list-unit-files vnstatd.service >/dev/null 2>&1; then
            name=vnstatd
        else
            printf '%s\n' 'absent'
            return 0
        fi
        systemctl is-active --quiet "$name" && active=1 || active=0
        systemctl is-enabled --quiet "$name" && enabled=1 || enabled=0
        printf 'systemd|%s|%s|%s\n' "$name" "$active" "$enabled"
    elif [[ "${INIT_SYS:-}" == openrc ]] && command -v rc-service >/dev/null 2>&1; then
        [[ -x /etc/init.d/vnstatd ]] || { printf '%s\n' 'absent'; return 0; }
        rc-service vnstatd status >/dev/null 2>&1 && active=1 || active=0
        rc-update show default 2>/dev/null | grep -Eq '(^|[[:space:]])vnstatd([[:space:]]|$)' && enabled=1 || enabled=0
        printf 'openrc|vnstatd|%s|%s\n' "$active" "$enabled"
    else
        return 1
    fi
}

# FINAL-AUDIT fix: the old hard requirement that the CURRENT state be 1|1
# caused false rollback failures (e.g. pre-state 0|1 restored correctly, but
# the gate demanded 1|1). Conflict detection (current vs recorded post-state)
# is done by the caller in preflight; this function only restores the given
# pre-state.
restore_vnstat_runtime_state() {
    local state="$1" kind name active enabled
    IFS='|' read -r kind name active enabled <<< "$state"
    case "$kind" in
        absent) return 0 ;;
        systemd)
            if [[ "$enabled" == 1 ]]; then systemctl enable "$name" >/dev/null 2>&1 || return 1; else systemctl disable "$name" >/dev/null 2>&1 || return 1; fi
            if [[ "$active" == 1 ]]; then systemctl start "$name" >/dev/null 2>&1 || systemctl restart "$name" >/dev/null 2>&1 || return 1; else systemctl stop "$name" >/dev/null 2>&1 || return 1; fi
            ;;
        openrc)
            if [[ "$enabled" == 1 ]]; then rc-update add "$name" default >/dev/null 2>&1 || return 1; elif rc-update show default 2>/dev/null | grep -Eq "(^|[[:space:]])${name}([[:space:]]|$)"; then rc-update del "$name" default >/dev/null 2>&1 || return 1; fi
            if [[ "$active" == 1 ]]; then rc-service "$name" start >/dev/null 2>&1 9>&- 10>&- || rc-service "$name" restart >/dev/null 2>&1 9>&- 10>&- || return 1; else rc-service "$name" stop >/dev/null 2>&1 || return 1; fi
            ;;
        *) return 1 ;;
    esac
    return 0
}

# FINAL-AUDIT fix: undo a vnstat installation performed by the current
# transaction. Stops and disables the service; removes the package ONLY if
# the transaction installed it (pre.vnstat.binary == 0). Never removes a
# package that pre-existed, as other tools may depend on it.
rollback_newly_installed_vnstat() {
    local tx_dir="$1" svc_name=""
    if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
        if systemctl list-unit-files vnstat.service >/dev/null 2>&1; then svc_name=vnstat
        elif systemctl list-unit-files vnstatd.service >/dev/null 2>&1; then svc_name=vnstatd
        fi
        [[ -n "$svc_name" ]] || return 0
        systemctl stop "$svc_name" >/dev/null 2>&1 || true
        systemctl disable "$svc_name" >/dev/null 2>&1 || true
    elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then
        [[ -x /etc/init.d/vnstatd ]] || return 0
        rc-service vnstatd stop >/dev/null 2>&1 || true
        rc-update del vnstatd default >/dev/null 2>&1 || true
    else
        return 0
    fi
    # Only uninstall the package if this transaction installed it.
    local pre_binary=1
    [[ -f "$tx_dir/pre.vnstat.binary" ]] && IFS= read -r pre_binary < "$tx_dir/pre.vnstat.binary" 2>/dev/null || pre_binary=1
    if [[ "$pre_binary" == 0 ]]; then
        remove_optional_package vnstat 2>/dev/null || true
    fi
    return 0
}

traffic_restore_cron_block() {
    local pre_file="$1" expected_block="$2" current tmp stripped rc=0
    current=$(umask 077; mktemp /tmp/A-Box-traffic-cron-current.XXXXXX) || return 1
    tmp=$(umask 077; mktemp /tmp/A-Box-traffic-cron-restore.XXXXXX) || { rm -f -- "$current"; return 1; }
    if ! read_crontab_to_file "$current"; then rm -f -- "$current" "$tmp"; return 1; fi
    stripped=$(umask 077; mktemp /tmp/A-Box-traffic-cron-stripped.XXXXXX) || { rm -f -- "$current" "$tmp"; return 1; }
    if ! strip_abox_cron_blocks_from_file "$current" "$stripped" TRAFFIC; then rm -f -- "$current" "$tmp" "$stripped"; return 1; fi
    local current_block
    current_block=$(awk 'BEGIN{p=0} $0=="# A-Box TRAFFIC BEGIN"{p=1} p{print} $0=="# A-Box TRAFFIC END"{exit}' "$current")
    if [[ -n "$expected_block" ]]; then
        [[ "$current_block" == "$expected_block" ]] || { rm -f -- "$current" "$tmp" "$stripped"; return 2; }
    else
        [[ -z "$current_block" ]] || { rm -f -- "$current" "$tmp" "$stripped"; return 2; }
    fi
    cat "$stripped" > "$tmp" || { rm -f -- "$current" "$tmp" "$stripped"; return 1; }
    if [[ -s "$pre_file" ]]; then cat "$pre_file" >> "$tmp" || { rm -f -- "$current" "$tmp" "$stripped"; return 1; }; fi
    if commit_crontab_if_unchanged "$current" "$tmp"; then
        rc=0
    else
        rc=$?
    fi
    rm -f -- "$current" "$tmp" "$stripped"
    return "$rc"
}

capture_traffic_quota_expected_state() {
    local tx_dir="$1" current monitor_hash
    [[ -d "$tx_dir" && ! -L "$tx_dir" ]] || return 1
    capture_traffic_env_state_file "$ABOX_ENV" "$tx_dir/post-traffic.env" || return 1
    capture_traffic_optional_state "$ABOX_DESIRED_STATE" "$tx_dir/post.desired" || return 1
    capture_traffic_optional_state "$ABOX_TRAFFIC_BLOCK_STATE" "$tx_dir/post.block" || return 1
    # C-06: Capture pair-state so rollback can detect external changes.
    capture_traffic_optional_state "$ABOX_TRAFFIC_PAIR_STATE" "$tx_dir/post.pair" || return 1
    current=$(umask 077; mktemp /tmp/A-Box-traffic-postcron.XXXXXX) || return 1
    read_crontab_to_file "$current" || { rm -f -- "$current"; return 1; }
    awk 'BEGIN{p=0} $0=="# A-Box TRAFFIC BEGIN"{p=1} p{print} $0=="# A-Box TRAFFIC END"{exit}' "$current" > "$tx_dir/post.cron.traffic" || { rm -f -- "$current"; return 1; }
    rm -f -- "$current"
    if [[ -e "$ABOX_DIR/traffic_monitor.sh" || -L "$ABOX_DIR/traffic_monitor.sh" ]]; then
        [[ -f "$ABOX_DIR/traffic_monitor.sh" && ! -L "$ABOX_DIR/traffic_monitor.sh" ]] || return 1
        auxiliary_content_is_abox_managed "$ABOX_DIR/traffic_monitor.sh" /etc/ddr/traffic_monitor.sh || return 1
        monitor_hash=$(traffic_snapshot_file_hash "$ABOX_DIR/traffic_monitor.sh") || return 1
        printf '%s\n' "$monitor_hash" > "$tx_dir/post.monitor.hash" || return 1
    else
        printf '%s\n' none > "$tx_dir/post.monitor.hash"
    fi
    if ! capture_vnstat_runtime_state > "$tx_dir/post.vnstat"; then
        return 1
    fi
}

traffic_quota_transaction_rollback() {
    local tx_dir="$1" rc=0 current_monitor='' expected_monitor='' pre_monitor=0 current_block='' expected_block='' cron_rc=0 vnstat_state='' expected_vnstat='' current_state current_traffic_env current_vnstat
    [[ -d "$tx_dir" && ! -L "$tx_dir" ]] || return 2

    # Establish every expected post-state before changing anything. This prevents
    # rollback from overwriting state changed by another actor after provisioning.
    if [[ -f "$tx_dir/post-traffic.env" ]]; then
        current_traffic_env=$(umask 077; mktemp /tmp/A-Box-traffic-current-env.XXXXXX) || return 2
        if ! capture_traffic_env_state_file "$ABOX_ENV" "$current_traffic_env" || ! cmp -s "$current_traffic_env" "$tx_dir/post-traffic.env"; then
            rm -f -- "$current_traffic_env"
            printf '%s\n' "A-Box traffic rollback conflict: traffic quota environment changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        fi
        rm -f -- "$current_traffic_env"
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected quota environment; recovery state preserved at $tx_dir" >&2
        return 2
    fi
    if [[ -f "$tx_dir/post.desired" ]]; then
        traffic_optional_state_matches_expected "$ABOX_DESIRED_STATE" "$tx_dir/post.desired" || {
            printf '%s\n' "A-Box traffic rollback conflict: desired state changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        }
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected desired state; recovery state preserved at $tx_dir" >&2
        return 2
    fi
    if [[ -f "$tx_dir/post.block" ]]; then
        traffic_optional_state_matches_expected "$ABOX_TRAFFIC_BLOCK_STATE" "$tx_dir/post.block" || {
            printf '%s\n' "A-Box traffic rollback conflict: traffic block state changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        }
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected block state; recovery state preserved at $tx_dir" >&2
        return 2
    fi
    if [[ -f "$tx_dir/post.pair" ]]; then
        traffic_optional_state_matches_expected "$ABOX_TRAFFIC_PAIR_STATE" "$tx_dir/post.pair" || {
            printf '%s\n' "A-Box traffic rollback conflict: traffic pair state changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        }
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected pair state; recovery state preserved at $tx_dir" >&2
        return 2
    fi

    if [[ -f "$tx_dir/post.cron.traffic" ]]; then
        expected_block=$(cat "$tx_dir/post.cron.traffic") || return 2
        current=$(umask 077; mktemp /tmp/A-Box-traffic-current-cron.XXXXXX) || return 2
        if ! read_crontab_to_file "$current"; then rm -f -- "$current"; return 2; fi
        current_block=$(awk 'BEGIN{p=0} $0=="# A-Box TRAFFIC BEGIN"{p=1} p{print} $0=="# A-Box TRAFFIC END"{exit}' "$current")
        rm -f -- "$current"
        [[ "$current_block" == "$expected_block" ]] || {
            printf '%s\n' "A-Box traffic rollback conflict: crontab TRAFFIC block changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        }
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected TRAFFIC cron state; recovery state preserved at $tx_dir" >&2
        return 2
    fi

    if [[ -s "$tx_dir/post.monitor.hash" ]]; then
        IFS= read -r expected_monitor < "$tx_dir/post.monitor.hash" || return 2
        if [[ "$expected_monitor" == none ]]; then
            [[ ! -e "$ABOX_DIR/traffic_monitor.sh" && ! -L "$ABOX_DIR/traffic_monitor.sh" ]] || {
                printf '%s\n' "A-Box traffic rollback conflict: traffic_monitor.sh was created externally; recovery state preserved at $tx_dir" >&2
                return 2
            }
        else
            current_monitor=$(traffic_snapshot_file_hash "$ABOX_DIR/traffic_monitor.sh" 2>/dev/null || true)
            [[ "$current_monitor" == "$expected_monitor" ]] || {
                printf '%s\n' "A-Box traffic rollback conflict: traffic_monitor.sh changed externally; recovery state preserved at $tx_dir" >&2
                return 2
            }
        fi
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected monitor state; recovery state preserved at $tx_dir" >&2
        return 2
    fi

    if [[ -s "$tx_dir/post.vnstat" ]]; then
        IFS= read -r current_vnstat < <(capture_vnstat_runtime_state) || {
            printf '%s\n' "A-Box traffic rollback could not read current vnStat state; recovery state preserved at $tx_dir" >&2
            return 2
        }
        IFS= read -r expected_vnstat < "$tx_dir/post.vnstat" || return 2
        [[ "$current_vnstat" == "$expected_vnstat" ]] || {
            printf '%s\n' "A-Box traffic rollback conflict: vnStat state changed externally; recovery state preserved at $tx_dir" >&2
            return 2
        }
    else
        printf '%s\n' "A-Box traffic rollback could not establish the expected vnStat state; recovery state preserved at $tx_dir" >&2
        return 2
    fi

    # Restore only A-Box-owned traffic state after the complete conflict preflight.
    if [[ -f "$tx_dir/pre-traffic.env" ]]; then
        local envtmp
        envtmp=$(mktemp "$ABOX_DIR/.env.A-Box-traffic-rollback.XXXXXX") || rc=1
        if (( rc == 0 )); then
            # .env may not exist on fresh boxes; treat as empty in that case.
            if [[ -f "$ABOX_ENV" && ! -L "$ABOX_ENV" ]]; then
                awk '!/^TRAFFIC_LIMIT_(GB|MODE)=/' "$ABOX_ENV" > "$envtmp" || rc=1
            else
                : > "$envtmp" || rc=1
            fi
            cat "$tx_dir/pre-traffic.env" >> "$envtmp" || rc=1
            chmod 600 "$envtmp" || rc=1
            (( rc == 0 )) && mv -f -- "$envtmp" "$ABOX_ENV" || rm -f -- "$envtmp"
        fi
    fi
    # C-06: write_private_line undefined in main script (only in generated traffic_monitor.sh).
    if [[ -s "$tx_dir/pre.desired" ]]; then IFS= read -r current_state < "$tx_dir/pre.desired" && printf '%s\n' "$current_state" | write_file_atomically_from_stdin "$ABOX_DESIRED_STATE" 600 || rc=1; else rm -f -- "$ABOX_DESIRED_STATE" 2>/dev/null || true; fi
    if [[ -s "$tx_dir/pre.block" ]]; then IFS= read -r current_state < "$tx_dir/pre.block" && printf '%s\n' "$current_state" | write_file_atomically_from_stdin "$ABOX_TRAFFIC_BLOCK_STATE" 600 || rc=1; else rm -f -- "$ABOX_TRAFFIC_BLOCK_STATE" 2>/dev/null || true; fi
    # C-06: Restore authoritative pair-state atomically (was cp -a: non-atomic, symlink-unsafe).
    if [[ -s "$tx_dir/pre.pair" ]]; then IFS= read -r current_state < "$tx_dir/pre.pair" && printf '%s\n' "$current_state" | write_file_atomically_from_stdin "$ABOX_TRAFFIC_PAIR_STATE" 600 || rc=1; else rm -f -- "$ABOX_TRAFFIC_PAIR_STATE" 2>/dev/null || true; fi

    if [[ -f "$tx_dir/pre.cron.traffic" ]]; then
        if traffic_restore_cron_block "$tx_dir/pre.cron.traffic" "$expected_block"; then :; else cron_rc=$?; rc=1; fi
        if (( cron_rc == 2 )); then printf '%s\n' "A-Box traffic rollback conflict: crontab TRAFFIC block changed externally; recovery state preserved at $tx_dir" >&2; fi
    fi

    if [[ -s "$tx_dir/pre.monitor.meta" ]]; then
        IFS='|' read -r pre_monitor _ < "$tx_dir/pre.monitor.meta" || rc=1
        if (( pre_monitor == 1 )); then
            cp -a -- "$tx_dir/traffic_monitor.pre" "$ABOX_DIR/traffic_monitor.sh" || rc=1
        else
            remove_owned_runtime_helper "$ABOX_DIR/traffic_monitor.sh" || rc=1
        fi
    else
        rc=1
    fi

    if [[ -s "$tx_dir/pre.vnstat" ]]; then
        IFS= read -r vnstat_state < "$tx_dir/pre.vnstat" || rc=1
        if [[ -n "$vnstat_state" && "$vnstat_state" != absent ]]; then
            restore_vnstat_runtime_state "$vnstat_state" || { printf '%s\n' "A-Box traffic rollback incomplete: vnStat state restore failed; recovery state preserved at $tx_dir" >&2; rc=1; }
        elif [[ "$vnstat_state" == absent ]]; then
            # FINAL-AUDIT: pre-state was absent. If the transaction installed
            # vnstat (post.vnstat shows it present), undo the installation:
            # stop/disable the service, and uninstall the package only if
            # this transaction installed it (pre.vnstat.binary == 0).
            local _post_vnstat=""
            [[ -s "$tx_dir/post.vnstat" ]] && IFS= read -r _post_vnstat < "$tx_dir/post.vnstat" 2>/dev/null || true
            if [[ -n "$_post_vnstat" && "$_post_vnstat" != absent ]]; then
                rollback_newly_installed_vnstat "$tx_dir" || { printf '%s\n' "A-Box traffic rollback incomplete: newly-installed vnStat cleanup failed; recovery state preserved at $tx_dir" >&2; rc=1; }
            fi
        fi
    else
        rc=1
    fi
    return "$rc"
}

prepare_traffic_quota_transaction() {
    local tx_dir="$1" traffic_env_tmp current
    mkdir -p "$tx_dir" || return 1
    chmod 700 "$tx_dir" || return 1
    traffic_env_tmp="$tx_dir/pre-traffic.env"
    grep -E '^TRAFFIC_LIMIT_(GB|MODE)=' "$ABOX_ENV" > "$traffic_env_tmp" 2>/dev/null || :
    [[ -f "$ABOX_DESIRED_STATE" ]] && { cp -a -- "$ABOX_DESIRED_STATE" "$tx_dir/pre.desired" || return 1; } || :
    [[ -f "$ABOX_TRAFFIC_BLOCK_STATE" ]] && { cp -a -- "$ABOX_TRAFFIC_BLOCK_STATE" "$tx_dir/pre.block" || return 1; } || :
    # C-06: Backup authoritative pair-state (was missing). Reject symlinks.
    if [[ -e "$ABOX_TRAFFIC_PAIR_STATE" || -L "$ABOX_TRAFFIC_PAIR_STATE" ]]; then
        [[ -f "$ABOX_TRAFFIC_PAIR_STATE" && ! -L "$ABOX_TRAFFIC_PAIR_STATE" ]] || return 1
        cp -a -- "$ABOX_TRAFFIC_PAIR_STATE" "$tx_dir/pre.pair" || return 1
    fi
    current=$(umask 077; mktemp /tmp/A-Box-traffic-precron.XXXXXX) || return 1
    read_crontab_to_file "$current" || { rm -f -- "$current"; return 1; }
    awk 'BEGIN{p=0} $0=="# A-Box TRAFFIC BEGIN"{p=1} p{print} $0=="# A-Box TRAFFIC END"{exit}' "$current" > "$tx_dir/pre.cron.traffic" || { rm -f -- "$current"; return 1; }
    rm -f -- "$current"
    if [[ -e "$ABOX_DIR/traffic_monitor.sh" || -L "$ABOX_DIR/traffic_monitor.sh" ]]; then
        [[ -f "$ABOX_DIR/traffic_monitor.sh" && ! -L "$ABOX_DIR/traffic_monitor.sh" ]] || return 1
        auxiliary_content_is_abox_managed "$ABOX_DIR/traffic_monitor.sh" /etc/ddr/traffic_monitor.sh || return 1
        printf '1|%s\n' "$(traffic_snapshot_file_hash "$ABOX_DIR/traffic_monitor.sh")" > "$tx_dir/pre.monitor.meta" || return 1
        cp -a -- "$ABOX_DIR/traffic_monitor.sh" "$tx_dir/traffic_monitor.pre" || return 1
    else
        printf '%s\n' '0|none' > "$tx_dir/pre.monitor.meta"
    fi
    capture_vnstat_runtime_state > "$tx_dir/pre.vnstat" || return 1
    # FINAL-AUDIT: record whether the vnstat binary/package pre-existed, so
    # rollback only uninstalls it if THIS transaction installed it.
    if command -v vnstat >/dev/null 2>&1; then
        printf '1\n' > "$tx_dir/pre.vnstat.binary" || return 1
    else
        printf '0\n' > "$tx_dir/pre.vnstat.binary" || return 1
    fi
}

finalize_traffic_quota_transaction() {
    local tx_dir="$1"
    capture_traffic_quota_expected_state "$tx_dir"
}


start_services_for_traffic_unblock() {
    local pre_state="$1" changed_pre="$2" changed_expected="$3"
    local services srv before after active enabled op_rc final_state
    services=$(expected_managed_services) || return 1
    while IFS= read -r srv; do
        [[ -n "$srv" ]] || continue
        abox_owns_service "$srv" || return 1
        before=$(managed_service_state_value "$srv" 2>/dev/null) || return 1
        [[ "$before" == "$srv|1|1" ]] && continue
        IFS='|' read -r _ active enabled <<< "$before"
        append_managed_service_state_entry "$pre_state" "$changed_pre" "$srv" || return 1
        if [[ "$active" == 1 ]]; then
            if enable_abox_service_soft "$srv"; then op_rc=0; else op_rc=$?; fi
        else
            if start_abox_service_soft "$srv"; then op_rc=0; else op_rc=$?; fi
        fi
        after=$(managed_service_state_value "$srv" 2>/dev/null || true)
        if [[ -n "$after" ]]; then
            printf '%s\n' "$after" >> "$changed_expected" || return 1
        else
            # Keep the expected post-state explicit; rollback will refuse to
            # mutate if the actual state cannot later be proven to match it.
            printf '%s\n' "$srv|1|1" >> "$changed_expected" || return 1
        fi
        (( op_rc == 0 )) || return 1
        [[ "$after" == "$srv|1|1" ]] || return 1
    done <<< "$services"
    while IFS= read -r srv; do
        [[ -n "$srv" ]] || continue
        final_state=$(managed_service_state_value "$srv" 2>/dev/null) || return 1
        [[ "$final_state" == "$srv|1|1" ]] || return 1
    done <<< "$services"
}

# Traffic transaction failure: run the rollback hook (fail-closed), clean up the
# die hook so a stale hook cannot fire later, show the error, and return to the
# traffic menu instead of exiting the script. Must be followed by `continue`
# (we are inside the menu's while loop).
_traffic_txn_fail() {
    local _rb_fn="$1" _oldhook_vn="$2" _reason="$3" _old=''
    if declare -F "$_rb_fn" >/dev/null 2>&1; then
        "$_rb_fn" "$_reason" || msg "${RED}[!] WARNING: rollback failed; manual recovery may be required.${NC}"
    fi
    unset ABOX_DIE_HOOK
    _old="${!_oldhook_vn:-}"
    if [[ -n "$_old" ]]; then ABOX_DIE_HOOK="$_old"; fi
    ABOX_TRAFFIC_TX_DIR=''
    msg "${RED}[!] $_reason${NC}"
    pause_return
}


traffic_management_menu() {
    # Submenu loop: sub-functions return here; 0/Enter goes back to the parent menu.
    while true; do
    clear
    local INTERFACE limit_gb mode_choice previous_state
    load_optional_abox_env_or_die
    INTERFACE="${INGRESS_IF:-$(get_active_interface)}"
    # Traffic dashboard (2026-10-19, per traffic-table.png): progress bar +
    # clean monthly table instead of raw vnStat ASCII boxes.
    local _tjson='' _tlimit="${TRAFFIC_LIMIT_GB:-}"
    if command -v vnstat >/dev/null 2>&1; then
        _tjson=$(vnstat -i "$INTERFACE" --json m 2>/dev/null) || _tjson=''
    fi
    if [[ -n "$_tjson" ]]; then
        python3 - "$_tjson" "$INTERFACE" "$_tlimit" <<'PY_TRAFFIC_DASH' 2>/dev/null || \
            msg "${YELLOW}[!] 流量数据解析失败。${NC}"
import json, sys, unicodedata

def dw(s):
    return sum(2 if unicodedata.east_asian_width(c) in ("W", "F") else 1 for c in s)

def pad(s, w, right=False):
    p = " " * max(0, w - dw(s))
    return (p + s) if right else (s + p)

def center(s, w=80):
    return " " * max(0, (w - dw(s)) // 2) + s

YELLOW = "\033[0;33m"; CYAN = "\033[0;36m"; GREEN = "\033[0;32m"
RED = "\033[0;31m"; GRAY = "\033[0;37m"; BLUE = "\033[0;34m"
BOLD = "\033[1m"; NC = "\033[0m"
BAR = "─" * 80
GIB = 1073741824

raw, iface, limit_s = sys.argv[1], sys.argv[2], sys.argv[3]
try:
    limit_gb = float(limit_s)
except (ValueError, TypeError):
    limit_gb = 0.0

def fmt_gb(n):
    return f"{n / GIB:,.1f} GB"

def progress_bar(pct, width=60):
    pct = max(0.0, min(pct, 1.0))
    filled = int(width * pct)
    label = f"{pct * 100:.1f}%"
    ls = (width - len(label)) // 2
    parts = []
    for i in range(width):
        if ls <= i < ls + len(label):
            parts.append(f"{BOLD}{label[i - ls]}{NC}")
        elif i < filled:
            parts.append(f"{YELLOW}\u2588{NC}")
        else:
            parts.append(f"{GRAY}\u2591{NC}")
    return "".join(parts)

try:
    data = json.loads(raw)
except Exception:
    sys.exit(1)
months = ((data.get("interfaces") or [{}])[0].get("traffic") or {}).get("month") or []
months = sorted(months,
                key=lambda m: (m.get("date", {}).get("year", 0),
                               m.get("date", {}).get("month", 0)),
                reverse=True)

out = []
out.append(f"{BLUE}{BAR}{NC}")
out.append(f"{YELLOW}{center('每月流量管控 / Monthly Traffic')}{NC}")
out.append(f"{BLUE}{BAR}{NC}")
if months:
    cur = months[0]
    rx = int(cur.get("rx", 0)); tx = int(cur.get("tx", 0)); total = rx + tx
    d = cur.get("date", {})
    ym = f"{d.get('year', '--')}-{int(d.get('month', 0)):02d}" if d.get("year") else "本月"
    out.append(f"本月已用 ({iface} \u00b7 {ym}):")
    if limit_gb > 0:
        cap = limit_gb * GIB
        out.append(progress_bar(total / cap))
        rem = cap - total
        rem_s = f"{GREEN}剩余 {fmt_gb(rem)}{NC}" if rem >= 0 else f"{RED}超出 {fmt_gb(-rem)}{NC}"
        out.append(f"{YELLOW}已用 {fmt_gb(total)}{NC} / 上限 {limit_gb:,.0f} GB / {rem_s}")
    else:
        out.append(f"{YELLOW}已用 {fmt_gb(total)}{NC} / 上限 未设定")
    out.append(f"{BLUE}{BAR}{NC}")
    out.append(f"{CYAN}{center('历史月度统计')}{NC}")
    out.append(f"{YELLOW}{pad('月份', 10)}{pad('总流量', 15, True)}"
               f"{pad('下行 RX', 15, True)}{pad('上行 TX', 15, True)}  状态{NC}")
    out.append(f"{GRAY}{'─' * 66}{NC}")
    for i, m in enumerate(months):
        dd = m.get("date", {})
        yymm = f"{dd.get('year', '--')}-{int(dd.get('month', 0)):02d}"
        r = int(m.get("rx", 0)); t = int(m.get("tx", 0)); tot = r + t
        if i == 0:
            st = f"{YELLOW}进行中{NC}"
        elif limit_gb > 0 and tot > limit_gb * GIB:
            st = f"{RED}超限{NC}"
        else:
            st = f"{GREEN}正常{NC}"
        out.append(f"{pad(yymm, 10)}{pad(fmt_gb(tot), 15, True)}"
                   f"{pad(fmt_gb(r), 15, True)}{pad(fmt_gb(t), 15, True)}  {st}")
else:
    out.append(f"{YELLOW}暂无本月统计数据，vnStat 正在收集中。{NC}")
sys.stdout.write("\n".join(out) + "\n")
PY_TRAFFIC_DASH
    else
        msg "${YELLOW}[!] vnStat 未安装或暂无数据；设定上限时会按需安装。${NC}"
    fi
    msg "${CYAN}────────────────────────────────────────────────────────────────────────────────${NC}"
    msg "${CYAN}1.${NC}  设定/修改每月流量上限"
    msg "${CYAN}2.${NC}  解除流量限制"
    msg "${CYAN}0.${NC}  返回主菜单"
    read -r -p "$(tr_msg tf_pick)" tr_choice || return 0
    case "$tr_choice" in
        1)
            read -r -p "$(tr_msg tf_limit_prompt)" limit_gb
            valid_traffic_limit_gb "$limit_gb" || { msg "${RED}[!] 流量上限必须是 1-8589934591 GB 的整数。${NC}"; pause_return; return; }
            read -r -p "$(tr_msg tf_mode_prompt)" mode_choice
            mode_choice=${mode_choice:-total}
            [[ "$mode_choice" =~ ^(total|rx|tx)$ ]] || { msg "${RED}[!] 计量模式无效。${NC}"; pause_return; return; }
            local traffic_tx_dir="" old_die_hook="" traffic_previous_state='' traffic_service_pre='' traffic_service_changed_pre='' traffic_service_changed_expected='' traffic_op_rc=0 traffic_target_state=''
            traffic_previous_state=$(get_desired_state) || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_read_state)"; continue; }
            traffic_tx_dir=$(mktemp -d /run/A-Box-traffic-tx.XXXXXX) || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_tx_dir)"; continue; }
            chmod 700 "$traffic_tx_dir" || { rm -rf -- "$traffic_tx_dir"; _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_tx_dir_mode)"; continue; }
            prepare_traffic_quota_transaction "$traffic_tx_dir" || { rm -rf -- "$traffic_tx_dir"; _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_tx_presave)"; continue; }
            if [[ "$traffic_previous_state" == TRAFFIC_BLOCKED ]]; then
                traffic_service_pre="$traffic_tx_dir/pre-services.state"
                traffic_service_changed_pre="$traffic_tx_dir/changed-services-pre.state"
                traffic_service_changed_expected="$traffic_tx_dir/changed-services-expected.state"
                capture_managed_service_state "$traffic_service_pre" || { rm -rf -- "$traffic_tx_dir"; _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_unblock_presave)"; continue; }
                : > "$traffic_service_changed_pre"; : > "$traffic_service_changed_expected"
            fi
            if [[ ${ABOX_DIE_HOOK+x} ]]; then old_die_hook="$ABOX_DIE_HOOK"; fi
            ABOX_TRAFFIC_TX_DIR="$traffic_tx_dir"
            ABOX_DIE_HOOK=traffic_quota_menu_die_rollback
            traffic_quota_menu_die_rollback() {
                local rollback_rc=0 reason="${1:-traffic quota change failed}"
                if [[ -n "$traffic_service_changed_pre" && -s "$traffic_service_changed_pre" ]]; then
                    if [[ -s "$traffic_service_changed_expected" ]]; then
                        restore_managed_service_state "$traffic_service_changed_pre" "$traffic_service_changed_expected" || rollback_rc=1
                    else
                        rollback_rc=1
                    fi
                fi
                traffic_quota_transaction_rollback "$traffic_tx_dir" || rollback_rc=1
                if (( rollback_rc != 0 )); then
                    printf '%s\n' "A-Box traffic quota rollback incomplete/conflicted; recovery state preserved at $traffic_tx_dir" >&2
                else
                    rm -rf -- "$traffic_tx_dir" || rollback_rc=1
                fi
                if (( rollback_rc != 0 )); then
                    printf '%s\n' "A-Box traffic quota/service rollback incomplete; inspect recovery state at $traffic_tx_dir" >&2
                fi
                if [[ -n "$old_die_hook" && "$old_die_hook" != traffic_quota_menu_die_rollback ]] && declare -F "$old_die_hook" >/dev/null 2>&1; then
                    "$old_die_hook" "$reason" || true
                fi
                return "$rollback_rc"
            }
            if ! setup_traffic_monitor; then
                _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_monitor_init)"; continue
            fi
            if update_traffic_state_atomically "$limit_gb" "$mode_choice"; then traffic_op_rc=0; else traffic_op_rc=$?; fi
            capture_traffic_quota_expected_state "$traffic_tx_dir" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_verify_after_update)"; continue; }
            (( traffic_op_rc == 0 )) || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_commit)"; continue; }
            if clear_traffic_block_period; then traffic_op_rc=0; else traffic_op_rc=$?; fi
            capture_traffic_quota_expected_state "$traffic_tx_dir" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_verify_after_purge)"; continue; }
            (( traffic_op_rc == 0 )) || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_purge_old)"; continue; }
            case "$traffic_previous_state" in
                TRAFFIC_BLOCKED)
                    start_services_for_traffic_unblock "$traffic_service_pre" "$traffic_service_changed_pre" "$traffic_service_changed_expected" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_services_restore)"; continue; }
                    traffic_target_state=RUNNING
                    ;;
                RUNNING|MANUAL_STOPPED|MAINTENANCE)
                    traffic_target_state="$traffic_previous_state"
                    ;;
                *) _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tprintf tf_unknown_state "$traffic_previous_state")"; continue ;;
            esac
            if set_desired_state "$traffic_target_state"; then traffic_op_rc=0; else traffic_op_rc=$?; fi
            capture_traffic_quota_expected_state "$traffic_tx_dir" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_verify_after_desired)"; continue; }
            (( traffic_op_rc == 0 )) || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_desired_write)"; continue; }
            finalize_traffic_quota_transaction "$traffic_tx_dir" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_finalize)"; continue; }
            unset ABOX_DIE_HOOK
            if [[ -n "$old_die_hook" ]]; then ABOX_DIE_HOOK="$old_die_hook"; fi
            ABOX_TRAFFIC_TX_DIR=''
            rm -rf -- "$traffic_tx_dir" || { _traffic_txn_fail traffic_quota_menu_die_rollback old_die_hook "$(tr_msg tf_tx_cleanup)"; continue; }
            msg "${GREEN}流量限制已设定为 ${limit_gb} GB，模式 ${mode_choice}。${NC}"
            pause_return
            ;;
        2)
            previous_state=$(get_desired_state) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_read_state_unblock)"; continue; }
            local unblock_tx_dir='' unblock_old_die_hook='' unblock_state_pre='' unblock_changed_pre='' unblock_changed_expected='' unblock_op_rc=0 target_state=''
            unblock_tx_dir=$(mktemp -d /run/A-Box-traffic-unblock.XXXXXX) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_tx_dir)"; continue; }
            chmod 700 "$unblock_tx_dir" || { rm -rf -- "$unblock_tx_dir"; _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_tx_mode)"; continue; }
            prepare_traffic_quota_transaction "$unblock_tx_dir" || { rm -rf -- "$unblock_tx_dir"; _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_presave)"; continue; }
            unblock_state_pre="$unblock_tx_dir/pre-services.state"
            unblock_changed_pre="$unblock_tx_dir/changed-services-pre.state"
            unblock_changed_expected="$unblock_tx_dir/changed-services-expected.state"
            capture_managed_service_state "$unblock_state_pre" || { rm -rf -- "$unblock_tx_dir"; _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_svc_presave)"; continue; }
            : > "$unblock_changed_pre"; : > "$unblock_changed_expected"
            if [[ ${ABOX_DIE_HOOK+x} ]]; then unblock_old_die_hook="$ABOX_DIE_HOOK"; fi
            ABOX_TRAFFIC_TX_DIR="$unblock_tx_dir"
            ABOX_DIE_HOOK=traffic_unblock_menu_die_rollback
            traffic_unblock_menu_die_rollback() {
                local rollback_rc=0 reason="${1:-traffic unblock failed}"
                if [[ -s "$unblock_changed_pre" ]]; then
                    if [[ -s "$unblock_changed_expected" ]]; then
                        restore_managed_service_state "$unblock_changed_pre" "$unblock_changed_expected" || rollback_rc=1
                    else
                        rollback_rc=1
                    fi
                fi
                traffic_quota_transaction_rollback "$unblock_tx_dir" || rollback_rc=1
                if (( rollback_rc == 0 )); then
                    rm -rf -- "$unblock_tx_dir" || rollback_rc=1
                fi
                if (( rollback_rc != 0 )); then
                    printf '%s\n' "A-Box traffic-unblock rollback incomplete; recovery state preserved at $unblock_tx_dir" >&2
                fi
                if [[ -n "$unblock_old_die_hook" && "$unblock_old_die_hook" != traffic_unblock_menu_die_rollback ]] && declare -F "$unblock_old_die_hook" >/dev/null 2>&1; then
                    "$unblock_old_die_hook" "$reason" || true
                fi
                return "$rollback_rc"
            }

            if update_traffic_state_atomically '' ''; then unblock_op_rc=0; else unblock_op_rc=$?; fi
            capture_traffic_quota_expected_state "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_verify_new)"; continue; }
            (( unblock_op_rc == 0 )) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_commit)"; continue; }
            if remove_abox_cron_block TRAFFIC; then unblock_op_rc=0; else unblock_op_rc=$?; fi
            capture_traffic_quota_expected_state "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_verify_cron)"; continue; }
            (( unblock_op_rc == 0 )) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_rm_cron)"; continue; }
            if remove_owned_runtime_helper "$ABOX_DIR/traffic_monitor.sh"; then unblock_op_rc=0; else unblock_op_rc=$?; fi
            capture_traffic_quota_expected_state "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_verify_script)"; continue; }
            (( unblock_op_rc == 0 )) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_rm_script)"; continue; }
            if clear_traffic_block_period; then unblock_op_rc=0; else unblock_op_rc=$?; fi
            capture_traffic_quota_expected_state "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_verify_purge)"; continue; }
            (( unblock_op_rc == 0 )) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_purge)"; continue; }
            load_abox_env "$ABOX_ENV" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_reload)"; continue; }
            case "$previous_state" in
                TRAFFIC_BLOCKED)
                    start_services_for_traffic_unblock "$unblock_state_pre" "$unblock_changed_pre" "$unblock_changed_expected" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_services)"; continue; }
                    target_state=RUNNING
                    ;;
                RUNNING|MANUAL_STOPPED|MAINTENANCE)
                    target_state="$previous_state"
                    ;;
                *) _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tprintf tf_unknown_state_unblock "$previous_state")"; continue ;;
            esac
            if set_desired_state "$target_state"; then unblock_op_rc=0; else unblock_op_rc=$?; fi
            capture_traffic_quota_expected_state "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_verify_desired)"; continue; }
            (( unblock_op_rc == 0 )) || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_desired_write)"; continue; }
            finalize_traffic_quota_transaction "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_finalize)"; continue; }
            unset ABOX_DIE_HOOK
            if [[ -n "$unblock_old_die_hook" ]]; then ABOX_DIE_HOOK="$unblock_old_die_hook"; fi
            ABOX_TRAFFIC_TX_DIR=''
            rm -rf -- "$unblock_tx_dir" || { _traffic_txn_fail traffic_unblock_menu_die_rollback unblock_old_die_hook "$(tr_msg tf_unblock_cleanup)"; continue; }
            msg "${GREEN}流量限制已解除。${NC}"
            pause_return
            ;;
        0) return 0 ;;
        *) msg "${RED}$(tr_msg invalid_input): $tr_choice${NC}"; sleep 1 ;;
    esac
    done
}

remove_ss_source_whitelist_rules() {
    local failed=0 cmd proto line rule ipt_out
    local -a argv=()
    [[ -n "${SS_PORT:-}" ]] || return 0
    for cmd in "$IPT" "$IPT6"; do
        command -v "$cmd" >/dev/null 2>&1 || continue
        _iptables_q "$cmd" -S INPUT >/dev/null 2>&1 || continue
        for proto in tcp udp; do
            while :; do
                ipt_out=$(_iptables_q "$cmd" -S INPUT 2>/dev/null) || { failed=1; break; }
                line=$(awk -v p="$proto" -v port="$SS_PORT" '$0 ~ "^-A INPUT " && $0 ~ ("-p " p) && $0 ~ ("--dport " port) && $0 ~ ("--comment \"?A-Box-" port "-" p "-WL6?\"?($|[ \t\r])") {print; exit}' <<< "$ipt_out") || { failed=1; break; }
                [[ -n "$line" ]] || break
                line=${line//\"/}
                rule="${line#-A INPUT }"
                read -r -a argv <<< "$rule"
                _iptables_do "$cmd" -D INPUT "${argv[@]}" >/dev/null 2>&1 || { failed=1; break; }
            done
        done
    done
    (( failed == 0 ))
}

# B-12: Rebuild SS_WHITELIST_IP from live iptables rules and persist to .env,
# so menu edits (add/remove) don't leave .env stale for redeploy wizards.
sync_ss_whitelist_ip_to_env() {
    local ips='' v6ips='' ipt_output ip6_output
    [[ -n "${SS_PORT:-}" ]] || return 1
    if ! ipt_output=$(_iptables_q "$IPT" -S INPUT 2>&1); then
        printf '[A-Box] WARNING: iptables query failed, not syncing whitelist to .env: %s\n' "$ipt_output" >&2
        return 1
    fi
    ips=$(awk -v port="$SS_PORT" '
        $0 ~ ("--comment \"?A-Box-" port "-(tcp|udp)-WL\"?([ \t\r]|$)") && $0 ~ /-j ACCEPT([ \t\r]|$)/ {
            for (i = 1; i < NF; i++) {
                if ($i == "-s") { sub(/\/32$/, "", $(i+1)); print $(i+1) }
            }
        }
    ' <<< "$ipt_output" | LC_ALL=C sort -u | tr '\n' ' ')
    if host_has_usable_ipv6 && ip6tables_usable; then
        if ! ip6_output=$(_iptables_q "$IPT6" -S INPUT 2>&1); then
            printf '[A-Box] WARNING: ip6tables query failed, not syncing whitelist to .env: %s\n' "$ip6_output" >&2
            return 1
        fi
        v6ips=$(awk -v port="$SS_PORT" '
            $0 ~ ("--comment \"?A-Box-" port "-(tcp|udp)-WL6\"?([ \t\r]|$)") && $0 ~ /-j ACCEPT([ \t\r]|$)/ {
                for (i = 1; i < NF; i++) {
                    if ($i == "-s") { sub(/\/128$/, "", $(i+1)); print $(i+1) }
                }
            }
        ' <<< "$ip6_output" | LC_ALL=C sort -u | tr '\n' ' ')
        ips+="$v6ips"
    fi
    SS_WHITELIST_IP=$(printf '%s' "$ips" | tr -s ' ' | sed 's/^ *//;s/ *$//')
    write_env || return 1
}
manage_ss_whitelist() {
    local check_rc=0
    clear
    local _wl_backend
    _wl_backend=$(firewall_backend)
    [[ "$_wl_backend" == 'iptables' ]] || {
        msg "${RED}[!] SS-2022 源地址白名单仅支持原生 iptables/ip6tables 后端；当前是 ${_wl_backend}。为避免 UFW/firewalld 与 A-Box 双重持久化或规则顺序错误，拒绝修改。${NC}"
        pause_return
        return 1
    }
    load_optional_abox_env_or_die
    [[ -z "${SS_PORT:-}" && -z "${SOCKS_PORT:-}" ]] && { msg "${RED}[!] 未检测到已部署的 SS-2022 或 SOCKS5 服务端口。${NC}"; pause_return; return; }
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}SS-2022 白名单 IP 管理 / SS-2022 Whitelist Manager${NC}"
    msg "${CYAN}======================================================================${NC}"
    msg "${YELLOW}当前 SS-2022 监听端口: $SS_PORT/TCP+UDP${NC}"
    msg "IPv4 白名单:"
    $IPT -nL INPUT --line-numbers 2>/dev/null | grep -E "(tcp|udp) dpt:$SS_PORT" | grep 'ACCEPT' | awk '{print $5}' | grep -v '0.0.0.0/0' | sort -u || true
    if command -v ip6tables >/dev/null 2>&1 && $IPT6 -nL INPUT >/dev/null 2>&1; then
        msg "IPv6 白名单:"
        $IPT6 -nL INPUT --line-numbers 2>/dev/null | grep -E "(tcp|udp) dpt:$SS_PORT" | grep 'ACCEPT' | awk '{print $5}' | grep -v '::/0' | sort -u || true
    fi
    msg "${BLUE}--------------------------------------------------------------------------------${NC}"
    msg "${YELLOW}1. 新增白名单 IP/CIDR (TCP+UDP)${NC}"
    msg "${YELLOW}2. 移除白名单 IP/CIDR (TCP+UDP)${NC}"
    msg "${YELLOW}3. 开启白名单模式 (TCP+UDP DROP)${NC}"
    msg "${YELLOW}4. 切换为全网开放 (移除 DROP 并放行 TCP+UDP)${NC}"
    msg "${CYAN}0. 返回主菜单${NC}"
    read -r -p "$(tr_msg wl_pick_prompt)" wl_choice
    local add_ip del_ip rule found proto
    case "$wl_choice" in
        1)
            read -r -p "$(tr_msg wl_add_prompt)" add_ip
            [[ -z "$add_ip" ]] && return
            if [[ "$add_ip" == *:* ]]; then
                valid_ipv6_cidr "$add_ip" || { msg "${RED}[!] IPv6 白名单地址非法: $add_ip${NC}"; pause_return; return; }
                # N-04: objective check (not preference-aware has_ipv6), consistent
                # with option 2/3 and pre_install_setup.
                host_has_usable_ipv6 && command -v ip6tables >/dev/null 2>&1 && _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1 || die "$(tr_msg mw_no_v6fw)"
                for proto in tcp udp; do
                    # F-06: check existence first (idempotent) — do not insert duplicates.
                    if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -s "$add_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL6" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in
                        0) ;;
                        1) _iptables_do "$IPT6" -I INPUT 1 -p "$proto" --dport "$SS_PORT" -s "$add_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL6" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf pi_ss_wl6_fail "$add_ip/$proto")" ;;
                        *) die "$(tr_msg pi_ss_fw_check)" ;;
                    esac
                done
            else
                valid_ipv4_cidr "$add_ip" || { msg "${RED}[!] IPv4 白名单地址非法: $add_ip${NC}"; pause_return; return; }
                for proto in tcp udp; do
                    # F-06: check existence first (idempotent) — do not insert duplicates.
                    if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -s "$add_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in
                        0) ;;
                        1) _iptables_do "$IPT" -I INPUT 1 -p "$proto" --dport "$SS_PORT" -s "$add_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf pi_ss_wl4_fail "$add_ip/$proto")" ;;
                        *) die "$(tr_msg pi_ss_fw_check)" ;;
                    esac
                done
            fi
            save_firewall_rules || die "$(tr_msg pi_fw_persist_fail)"
            sync_ss_whitelist_ip_to_env || die "$(tr_msg mw_env_sync)"
            msg "${GREEN}已添加白名单: $add_ip (TCP+UDP)${NC}"
            pause_return
            ;;
        2)
            read -r -p "$(tr_msg wl_del_prompt)" del_ip
            [[ -z "$del_ip" ]] && return
            found=0
            if [[ "$del_ip" == *:* ]]; then
                valid_ipv6_cidr "$del_ip" || { msg "${RED}[!] IPv6 白名单地址非法: $del_ip${NC}"; pause_return; return; }
                if ! host_has_usable_ipv6 || ! command -v ip6tables >/dev/null 2>&1 || ! _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
                    msg "${YELLOW}[!] 当前系统没有可用的 IPv6 防火墙，无法移除 IPv6 白名单；IPv4 规则未受影响。${NC}"
                    pause_return
                    return
                fi
                for proto in tcp udp; do
                    while :; do
                        if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -s "$del_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL6" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                        case "$check_rc" in
                            0) ;;
                            1) break ;;
                            *) die "$(tprintf mw_wl6_check "$del_ip/$proto")" ;;
                        esac
                        _iptables_do "$IPT6" -D INPUT -p "$proto" --dport "$SS_PORT" -s "$del_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL6" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf mw_wl6_del "$del_ip/$proto")"
                        found=1
                    done
                done
            else
                valid_ipv4_cidr "$del_ip" || { msg "${RED}[!] IPv4 白名单地址非法: $del_ip${NC}"; pause_return; return; }
                for proto in tcp udp; do
                    while :; do
                        if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -s "$del_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL" -j ACCEPT; then check_rc=0; else check_rc=$?; fi
                        case "$check_rc" in
                            0) ;;
                            1) break ;;
                            *) die "$(tprintf mw_wl4_check "$del_ip/$proto")" ;;
                        esac
                        _iptables_do "$IPT" -D INPUT -p "$proto" --dport "$SS_PORT" -s "$del_ip" -m comment --comment "A-Box-${SS_PORT}-${proto}-WL" -j ACCEPT >/dev/null 2>&1 || die "$(tprintf mw_wl4_del "$del_ip/$proto")"
                        found=1
                    done
                done
            fi
            save_firewall_rules || die "$(tr_msg pi_fw_persist_fail)"
            sync_ss_whitelist_ip_to_env || die "$(tr_msg mw_env_sync)"
            [[ "$found" == 1 ]] && msg "${GREEN}已移除白名单: $del_ip${NC}" || msg "${YELLOW}未找到该白名单规则。${NC}"
            pause_return
            ;;
        3)
            ss_whitelist_ipv6_precheck || die "$(tr_msg pi_ss_v6_fw)"
            _ss_wl_snapshot_rules || die "$(tr_msg pi_ss_snapshot)"
            remove_ss_open_accept_rules || { _ss_wl_rollback_to_snapshot; die "$(tr_msg pi_ss_old_accept)"; }
            for proto in tcp udp; do
                if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP" -j DROP; then check_rc=0; else check_rc=$?; fi
                case "$check_rc" in
                    0) ;;
                    1) _iptables_do "$IPT" -I INPUT 1 -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP" -j DROP >/dev/null 2>&1 || { _ss_wl_rollback_to_snapshot; die "$(tprintf pi_ss_drop4_fail "$proto")"; } ;;
                    *) { _ss_wl_rollback_to_snapshot; die "$(tr_msg pi_ss_fw_check)"; } ;;
                esac
                if host_has_usable_ipv6 && command -v ip6tables >/dev/null 2>&1 && _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
                    if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP6" -j DROP; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in
                        0) ;;
                        1) _iptables_do "$IPT6" -I INPUT 1 -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP6" -j DROP >/dev/null 2>&1 || { if _ss_wl_rollback_to_snapshot; then die "$(tprintf pi_ss_drop6_fail_rb "$proto")"; else die "$(tprintf pi_ss_drop6_fail_norb "$proto")"; fi; } ;;
                        *) { _ss_wl_rollback_to_snapshot; die "$(tr_msg pi_ss_fw_check)"; } ;;
                    esac
                fi
            done
            enforce_ss_whitelist_order "$SS_PORT" || { _ss_wl_rollback_to_snapshot; die "$(tr_msg pi_ss_order)"; }
            save_firewall_rules || { if _ss_wl_rollback_to_snapshot; then die "$(tr_msg pi_fw_persist_rb)"; else die "$(tr_msg pi_fw_persist_norb)"; fi; }
            msg "${GREEN}已开启白名单保护模式 (TCP+UDP)。${NC}"
            pause_return
            ;;
        4)
            _ss_wl_snapshot_rules || die "$(tr_msg pi_ss_snapshot)"
            # Use DIE_HOOK so that allowPort's internal die() calls trigger rollback
            # (allowPort calls die directly, outer || cannot catch it)
            local _old_die_hook="${ABOX_DIE_HOOK:-}"
            ABOX_DIE_HOOK=_ss_wl_rollback_to_snapshot
            remove_ss_source_whitelist_rules || { ABOX_DIE_HOOK="$_old_die_hook"; if _ss_wl_rollback_to_snapshot; then die "$(tr_msg mw_old_rb)"; else die "$(tr_msg mw_old_norb)"; fi; }
            for proto in tcp udp; do
                while :; do
                    if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP" -j DROP; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in
                        0) ;;
                        1) break ;;
                        *) die "$(tprintf mw_drop4_check "$proto")" ;;
                    esac
                    _iptables_do "$IPT" -D INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP" -j DROP >/dev/null 2>&1 || die "$(tprintf mw_drop4_del "$proto")"
                done
                if iptables_rule_check "$IPT" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP" -j DROP; then check_rc=0; else check_rc=$?; fi
                case "$check_rc" in 1) ;; 0) die "$(tprintf mw_drop4_still "$proto")" ;; *) die "$(tprintf mw_drop4_verify "$proto")" ;; esac
                if command -v ip6tables >/dev/null 2>&1 && _iptables_q "$IPT6" -S INPUT >/dev/null 2>&1; then
                    while :; do
                        if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP6" -j DROP; then check_rc=0; else check_rc=$?; fi
                        case "$check_rc" in
                            0) ;;
                            1) break ;;
                            *) die "$(tprintf mw_drop6_check "$proto")" ;;
                        esac
                        _iptables_do "$IPT6" -D INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP6" -j DROP >/dev/null 2>&1 || die "$(tprintf mw_drop6_del "$proto")"
                    done
                    if iptables_rule_check "$IPT6" INPUT -p "$proto" --dport "$SS_PORT" -m comment --comment "A-Box-${SS_PORT}-${proto}-DROP6" -j DROP; then check_rc=0; else check_rc=$?; fi
                    case "$check_rc" in 1) ;; 0) die "$(tprintf mw_drop6_still "$proto")" ;; *) die "$(tprintf mw_drop6_verify "$proto")" ;; esac
                fi
                allowPort "$SS_PORT" "$proto"
            done
            save_firewall_rules || die "$(tr_msg pi_fw_persist_fail)"
            sync_ss_whitelist_ip_to_env || die "$(tr_msg mw_env_sync)"
            ABOX_DIE_HOOK="$_old_die_hook"
            msg "${GREEN}已切换为全网开放模式 (TCP+UDP)。${NC}"
            pause_return
            ;;
        *) return 0 ;;
    esac
}

do_cleanup() {
    clear; msg "${RED}$(tr_msg cu_running)${NC}"
    init_system_environment
    local uninstall_tx_dir='' uninstall_tx_key='' uninstall_tx_value=''
    if [[ "${1:-}" == full ]]; then
        uninstall_tx_dir=$(mktemp -d /run/A-Box-uninstall-tx.XXXXXX) || die "$(tr_msg cu_tx_dir)"
        chmod 700 "$uninstall_tx_dir" || { rm -rf -- "$uninstall_tx_dir"; die "$(tr_msg cu_tx_perm)"; }
        ABOX_DEPLOY_TX_BACKUP_DIR="$uninstall_tx_dir"
        ABOX_DEPLOY_TX_EPHEMERAL_DIR="$uninstall_tx_dir"
        ABOX_DIE_HOOK='cleanup_ephemeral_deployment_transaction_dir'
    fi
    begin_deployment_transaction 'full A-Box cleanup' xray sing-box hysteria
    if [[ -n "$uninstall_tx_dir" ]]; then
        ensure_backup_auth_key || die "$(tr_msg cu_tx_key_new)"
        IFS= read -r uninstall_tx_value < "$ABOX_BACKUP_KEY" || die "$(tr_msg cu_tx_key_read)"
        uninstall_tx_key="$uninstall_tx_dir/recovery.key"
        write_private_sidecar "$uninstall_tx_key" "$uninstall_tx_value" || die "$(tr_msg cu_tx_key_save)"
        ABOX_DEPLOY_TX_KEY_FILE="$uninstall_tx_key"
    fi
    stop_all_managed_services || die "$(tr_msg cu_stop)"
    clean_nat_rules || die "$(tr_msg cl_nat)"
    clean_input_rules || die "$(tr_msg cl_input)"
    save_firewall_rules || die "$(tr_msg pi_fw_persist_fail)"
    kill_managed_residual_pids || die "$(tr_msg cu_residual)"
    remove_all_owned_core_families 1 || die "$(tr_msg cl_cores_clean)"
    if [[ -d "$ABOX_DIR/tune-backup" ]]; then
        restore_vps_tune 1 >/dev/null 2>&1 || die "$(tr_msg cu_tune)"
    else
        remove_owned_auxiliary_path /etc/sysctl.d/99-A-Box-tune.conf || die "$(tr_msg cu_sysctl)"
        remove_owned_auxiliary_path /etc/security/limits.d/A-Box.conf || die "$(tr_msg cu_limits)"
    fi
    remove_all_abox_cron_blocks || die "$(tr_msg cl_cron)"
    remove_owned_auxiliary_path /etc/fail2ban/jail.d/A-Box.local || die "$(tr_msg cl_f2b_jail)"
    remove_owned_auxiliary_path /etc/fail2ban/filter.d/A-Box.conf || die "$(tr_msg cl_f2b_filter)"
    remove_owned_auxiliary_path /etc/logrotate.d/A-Box || die "$(tr_msg cl_logrotate)"
    remove_abox_log_files || die "$(tr_msg cl_log_files)"
    # Argo units/binary, WARP/Argo/traffic state and the Wallos fail2ban
    # pair are outside the managed-path lists; remove them best-effort.
    argo_remove_unit argo || true
    argo_remove_unit argo-vmess || true
    argo_remove_unit argo-vless || true
    rm -f /usr/local/bin/cloudflared "$ROUTING_STATE_FILE" "$ARGO_STATE_FILE" /etc/ddr/.argo-token /etc/ddr/.extra-uuids /etc/ddr/.traffic-pair-state /etc/ddr/.desired_state /etc/ddr/.traffic-block-state 2>/dev/null || true; rm -rf -- /etc/ddr/standalone-links.d 2>/dev/null || true
    for _wf in /etc/fail2ban/filter.d/A-Box-wallos.conf /etc/fail2ban/jail.d/A-Box-wallos.local; do
        if [[ -f "$_wf" ]] && grep -q 'A-Box-wallos' "$_wf" 2>/dev/null; then rm -f "$_wf" || true; fi
    done
    wallos_https_teardown >/dev/null 2>&1 || true
    wallos_cftunnel_teardown >/dev/null 2>&1 || true
    wallos_stack_teardown
    users_registries_wipe || msg "${YELLOW}[!] $(tprintf cu_users_note '/etc/ddr/users.d')${NC}"
    abox_zram_teardown
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        if systemctl list-unit-files fail2ban.service >/dev/null 2>&1 && systemctl cat fail2ban.service >/dev/null 2>&1; then
            systemctl try-restart fail2ban >/dev/null 2>&1 || msg "${YELLOW}[!] $(tr_msg cl_f2b_restart_clean)${NC}"
        fi
        systemctl daemon-reload >/dev/null 2>&1 || die "$(tr_msg cl_reload_clean)"
    elif [[ "${INIT_SYS:-}" == openrc ]] && [[ -x /etc/init.d/fail2ban ]]; then
        { rc-service fail2ban status >/dev/null 2>&1 && rc-service fail2ban restart >/dev/null 2>&1 9>&- 10>&-; } || msg "${YELLOW}[!] $(tr_msg cl_f2b_restart_clean)${NC}"
    fi
    if [[ "${1:-}" == full ]]; then
        remove_abox_shortcut /usr/local/bin/sb || die "$(tr_msg cu_shortcut)"
        # Do not destroy ABOX_DIR until managed Swap has been removed successfully.
        # The ownership marker is required for a safe retry when /etc/fstab or swapoff fails.
        if ! remove_abox_swap; then
            msg "${YELLOW}[!] $(tprintf cu_swap_note "$ABOX_DIR")${NC}"
            die "$(tr_msg cu_swap_die)"
        fi
        wallos_stack_teardown purge-data
        path_tree_has_mountpoint "$ABOX_DIR" && die "$(tr_msg cu_mount)"
        # Keep the deployment transaction active until the final data-directory
        # deletion has been confirmed. If rm/race/permission errors occur, the
        # transaction hook must still be able to restore the pre-uninstall backup.
        rm -rf -- "$ABOX_DIR" || die "$(tr_msg cu_datadir)"
        [[ ! -e "$ABOX_DIR" && ! -L "$ABOX_DIR" ]] || die "$(tr_msg cu_datadir_left)"
        commit_deployment_transaction
        msg "${GREEN}$(tr_msg cu_full_done)${NC}"
        exit 0
    fi
    remove_abox_env_file || die "$(tr_msg cl_env_clean)"
    for runtime_file in "$ABOX_DIR/traffic_monitor.sh" "$ABOX_DIR/geo_update.sh" "$ABOX_DIR/socket_probe.sh"; do
        remove_owned_runtime_helper "$runtime_file" || die "$(tprintf cl_runtime_clean "$runtime_file")"
    done
    remove_sni_candidate_cache || die "$(tr_msg cl_sni_clean)"
    if [[ -f "$DEPS_MARKER" && ! -L "$DEPS_MARKER" ]]; then rm -f -- "$DEPS_MARKER" || die "$(tr_msg cl_deps_clean)"; fi
    setup_shortcut
    commit_deployment_transaction
    remove_abox_swap || msg "${YELLOW}[!] $(tr_msg cl_swap_keep)${NC}"
    msg "${GREEN}$(tr_msg cu_proxy_done)${NC}"
    pause_return
}

preflight_reset_ownership() {
    [[ -n "${ABOX_DIR:-}" ]] || return 1
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        validate_abox_env_file_for_write || return 1
    fi
    local runtime_file srv core_paths path sni_cache="$ABOX_DIR/A-Box-sni-candidates.txt"
    if [[ -e "$sni_cache" || -L "$sni_cache" ]]; then
        [[ -f "$sni_cache" && ! -L "$sni_cache" ]] || return 1
        path_owned_by_root "$sni_cache" || return 1
        path_mode_has_no_group_other_write "$sni_cache" || return 1
        path_tree_has_mountpoint "$sni_cache" && return 1
    fi
    for runtime_file in "$ABOX_DIR/traffic_monitor.sh" "$ABOX_DIR/geo_update.sh" "$ABOX_DIR/socket_probe.sh"; do
        [[ ! -e "$runtime_file" && ! -L "$runtime_file" ]] && continue
        auxiliary_content_is_abox_managed "$runtime_file" "$runtime_file" || return 1
        path_tree_has_mountpoint "$runtime_file" && return 1
    done
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        core_paths=$(core_family_paths "$srv") || return 1
        while IFS= read -r path; do
            [[ -e "$path" || -L "$path" ]] || continue
            path_tree_has_mountpoint "$path" && return 1
        done <<< "$core_paths"
    done
    return 0
}


# ================= Protocol removal (menu 16) =================
# Inbounds are enumerated from the live core configs (ground truth), and
# removed per-tag with the same discipline as deployments: the new config
# must pass the core's own check before it is installed atomically, and a
# failed restart restores the snapshot.
protocol_label() { # $1 = config tag, $2 = protocol/type (fallback display)
    local tag="${1:-}" proto="${2:-}"
    case "$tag" in
        latest-vision) printf '%s' 'VLESS-Vision-Reality (Latest Xray)' ;;
        latest-xhttp) printf '%s' 'VLESS-XHTTP-Reality (Latest Xray)' ;;
        latest-ss) printf '%s' 'SS-2022 (Latest Xray)' ;;
        vmess-ws-in) printf '%s' 'VMess-WS (Argo)' ;;
        vless-ws-in) printf '%s' 'VLESS-WS (Argo)' ;;
        *vision*) printf '%s' 'VLESS-Vision-Reality' ;;
        *xhttp*) printf '%s' 'VLESS-XHTTP-Reality' ;;
        *shadowtls*) printf '%s' 'ShadowTLS' ;;
        *trojan*) printf '%s' 'Trojan-Reality' ;;
        *tuic*) printf '%s' 'TUIC' ;;
        *anytls*) printf '%s' 'AnyTLS' ;;
        *socks*|*mixed*) printf '%s' 'SOCKS5/Mixed' ;;
        *hysteria*|*hy2*) printf '%s' 'Hysteria 2' ;;
        *ss*) printf '%s' 'Shadowsocks-2022' ;;
        *) printf '%s' "${proto:-$tag}" ;;
    esac
}

# One line per deployed inbound: core<TAB>tag<TAB>protocol<TAB>port
# (the internal "api" inbound is infrastructure, never listed).
protocol_inventory() {
    local cfg=''
    cfg="$XRAY_SLOT_CFG"
    if [[ -f "$cfg" && ! -L "$cfg" ]]; then
        jq -r '.inbounds[]? | select(.tag != null and .tag != "" and .tag != "api") | "xray\t\(.tag)\t\(.protocol // "")\t\(.port // "")"' "$cfg" 2>/dev/null || true
    fi
    cfg='/etc/sing-box/config.json'
    if [[ -f "$cfg" && ! -L "$cfg" ]]; then
        jq -r '.inbounds[]? | select(.tag != null and .tag != "" and .tag != "api") | "sing-box\t\(.tag)\t\(.type // "")\t\(.listen_port // "")"' "$cfg" 2>/dev/null || true
    fi
    if [[ -n "$(_xl_state_get mode)" && -f "$XRAY_LATEST_CFG" && ! -L "$XRAY_LATEST_CFG" ]]; then
        jq -r '.inbounds[]? | select(.tag != null and .tag != "" and .tag != "api") | "xray-latest\t\(.tag)\t\(.protocol // "")\t\(.port // "")"' "$XRAY_LATEST_CFG" 2>/dev/null || true
    fi
    if [[ -f /etc/hysteria/config.yaml && ! -L /etc/hysteria/config.yaml ]]; then
        printf 'hy2\thy2-official\thysteria2\t%s\n' "$(xl_hy2_port)"
    fi
    return 0
}

_protocol_cfg_of() { # $1 = core -> cfg|bin|svc
    case "$1" in
        xray) printf '%s|%s|%s' "$XRAY_SLOT_CFG" '/usr/local/bin/xray' 'xray' ;;
        sing-box) printf '%s|%s|%s' '/etc/sing-box/config.json' '/usr/local/bin/sing-box' 'sing-box' ;;
        xray-latest) printf '%s|%s|%s' "$XRAY_LATEST_CFG" "$XRAY_LATEST_BIN" 'xray-latest' ;;
        *) return 1 ;;
    esac
}

# _remove_inbounds_from_config CORE TAG...   |   CORE --all
_remove_inbounds_from_config() {
    local core="$1"; shift
    local info='' cfg='' bin='' svc='' bak='' tmp_cfg='' tags_json='' filter=''
    info=$(_protocol_cfg_of "$core") || return 1
    IFS='|' read -r cfg bin svc <<< "$info"
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    if [[ "${1:-}" == '--all' ]]; then
        # Clear-all keeps the internal "api" inbound (traffic-stats
        # infrastructure, not a node protocol) and drops everything else.
        filter='.inbounds |= map(select(.tag == "api"))'
        tags_json='[]'
    else
        (( $# >= 1 )) || return 1
        tags_json=$(printf '%s\n' "$@" | jq -R . | jq -s .) || return 1
        filter='.inbounds |= map(select(.tag as $t | ($tags | index($t)) == null))'
    fi
    bak=$(mktemp /tmp/A-Box-rm-bak.XXXXXX) || return 1
    cp -f -- "$cfg" "$bak" || { rm -f "$bak"; return 1; }
    tmp_cfg=$(mktemp /tmp/A-Box-rm-cfg.XXXXXX) || { rm -f "$bak"; return 1; }
    mv "$tmp_cfg" "$tmp_cfg.json" || { rm -f "$tmp_cfg" "$bak"; return 1; }
    tmp_cfg="$tmp_cfg.json"
    if ! jq --argjson tags "$tags_json" "$filter" "$cfg" > "$tmp_cfg" 2>/dev/null; then
        rm -f "$tmp_cfg" "$bak"; return 1
    fi
    if [[ "$core" == 'sing-box' ]]; then
        "$bin" check -c "$tmp_cfg" >/dev/null 2>&1 || { rm -f "$tmp_cfg" "$bak"; return 1; }
    else
        XRAY_LOCATION_ASSET=/usr/local/share/xray "$bin" run -test -config "$tmp_cfg" >/dev/null 2>&1 || { rm -f "$tmp_cfg" "$bak"; return 1; }
    fi
    install_file_atomically "$tmp_cfg" "$cfg" 600 || { rm -f "$tmp_cfg" "$bak"; return 1; }
    rm -f "$tmp_cfg"
    case "$core" in
        xray) prepare_abox_runtime_permissions xray 2>/dev/null || true ;;
        sing-box) prepare_abox_runtime_read_file "$cfg" sing-box 2>/dev/null || true ;;
        xray-latest) prepare_abox_runtime_read_file "$cfg" xray 2>/dev/null || true ;;
    esac
    if ! restart_service_soft "$svc"; then
        install_file_atomically "$bak" "$cfg" 600 2>/dev/null || cp -f -- "$bak" "$cfg"
        restart_service_soft "$svc" >/dev/null 2>&1 || true
        rm -f "$bak"; return 1
    fi
    rm -f "$bak"; return 0
}

# Side effects after inbounds were removed from CORE: Argo tunnel units for
# ws inbounds, and the standalone link registrations of the removed tags.
# Remove one node's multi-user registry (single-delete path).
users_registry_remove() { # $1 = core, $2 = tag
    local _f="${ABOX_USERS_DIR:-/etc/ddr/users.d}/$1__$2.json"
    [[ -f "$_f" && ! -L "$_f" ]] && rm -f -- "$_f"
    return 0
}

# Remove every multi-user registry (clear-all / virgin reset):
# once the inbounds are gone the registries are orphans and the
# panel would keep listing ghost users from them.
users_registries_wipe() {
    local _dir="${ABOX_USERS_DIR:-/etc/ddr/users.d}" _f=''
    [[ -d "$_dir" ]] || return 0
    for _f in "$_dir"/*.json; do
        [[ -f "$_f" && ! -L "$_f" ]] || continue
        rm -f -- "$_f" || return 1
    done
    return 0
}

_protocol_removed_side_effects() { # $1 = core, rest = removed tags
    local core="$1"; shift
    local tag='' cfg=''
    for tag in "$@"; do
        case "$tag" in
            vmess-ws-in) argo_remove_unit argo-vmess || true ;;
            vless-ws-in) argo_remove_unit argo-vless || true ;;
            *trojan*) rm -f -- /etc/ddr/standalone-links.d/trojan-xray.link /etc/ddr/standalone-links.d/trojan-sb.link 2>/dev/null || true ;;
            *tuic*) rm -f -- /etc/ddr/standalone-links.d/tuic.link 2>/dev/null || true ;;
            *anytls*) rm -f -- /etc/ddr/standalone-links.d/anytls.link 2>/dev/null || true ;;
            *shadowtls*) rm -f -- /etc/ddr/standalone-links.d/shadowtls.link 2>/dev/null || true ;;
            *socks*|*mixed*) rm -f -- /etc/ddr/standalone-links.d/socks5-sb.link /etc/ddr/standalone-links.d/socks5-xray.link 2>/dev/null || true ;;
        esac
        rm -f -- "/etc/ddr/standalone-links.d/${tag}.link" 2>/dev/null || true
        users_registry_remove "$core" "$tag"
    done
    # The shared Argo link registration goes only when no ws inbound remains.
    if [[ "$core" == 'sing-box' ]]; then
        cfg='/etc/sing-box/config.json'
        if [[ -f "$cfg" ]] && ! jq -e '.inbounds[]? | select(.tag == "vmess-ws-in" or .tag == "vless-ws-in")' "$cfg" >/dev/null 2>&1; then
            rm -f -- /etc/ddr/standalone-links.d/argo.link 2>/dev/null || true
            argo_remove_unit argo || true
        fi
    fi
    return 0
}

_remove_hy2_official() {
    stop_abox_service_soft hysteria >/dev/null 2>&1 || {
        if [[ "${INIT_SYS:-}" == 'systemd' ]]; then systemctl stop hysteria >/dev/null 2>&1 || true
        elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then rc-service hysteria stop >/dev/null 2>&1 || true; fi
    }
    if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
        systemctl disable hysteria >/dev/null 2>&1 || true
        rm -f -- /etc/systemd/system/hysteria.service
        systemctl daemon-reload >/dev/null 2>&1 || true
    elif [[ "${INIT_SYS:-}" == 'openrc' ]]; then
        rc-update del hysteria default >/dev/null 2>&1 || true
        rm -f -- /etc/init.d/hysteria /etc/conf.d/hysteria
    fi
    rm -rf -- /etc/hysteria
    rm -f -- /etc/ddr/standalone-links.d/hy2.link /etc/ddr/standalone-links.d/hysteria.link 2>/dev/null || true
    users_registry_remove hy2 hy2
    return 0
}

remove_single_protocol_menu() {
    local -a rows=() tags=()
    local row='' core='' tag='' proto='' port='' label='' idx=0 choice='' answer='' info='' cfg='' deps='' d=''
    mapfile -t rows < <(protocol_inventory)
    if (( ${#rows[@]} == 0 )); then
        msg "${YELLOW}$(tr_msg cl_none)${NC}"
        return 0
    fi
    msg "${BOLD}${GREEN}$(tr_msg cl_m_single)${NC}"
    for row in "${rows[@]}"; do
        idx=$((idx + 1))
        IFS=$'\t' read -r core tag proto port <<< "$row"
        label=$(protocol_label "$tag" "$proto")
        local _idxf=''; printf -v _idxf '%2d' "$idx"
        msg "${YELLOW}${_idxf}.  ${label} · ${core} · :${port:-—}${NC}"
    done
    read -r -p "$(tr_msg cl_select)" choice || return 0
    if [[ ! "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#rows[@]} )); then
        msg "${RED}$(tr_msg xl_invalid)${NC}"
        return 0
    fi
    row="${rows[$((choice - 1))]}"
    IFS=$'\t' read -r core tag proto port <<< "$row"
    label=$(protocol_label "$tag" "$proto")
    tags=("$tag")
    if [[ "$core" != 'hy2' ]]; then
        info=$(_protocol_cfg_of "$core")
        IFS='|' read -r cfg _ _ <<< "$info"
        deps=$(jq -r --arg t "$tag" '.inbounds[]? | select(.detour == $t) | .tag' "$cfg" 2>/dev/null || true)
        if [[ -n "$deps" ]]; then
            while IFS= read -r d; do [[ -n "$d" ]] && tags+=("$d"); done <<< "$deps"
            msg "${YELLOW}$(tr_msg cl_dep_warn): ${deps//$'\n'/, }${NC}"
        fi
    fi
    read -r -p "$(tr_msg cl_confirm_one) ${label} [Y/N]: " answer || return 0
    is_yes "$answer" || { msg "${GREEN}$(tr_msg xl_remove_cancelled)${NC}"; return 0; }
    if [[ "$core" == 'hy2' ]]; then
        _remove_hy2_official
    else
        if ! _remove_inbounds_from_config "$core" "${tags[@]}"; then
            msg "${RED}$(tr_msg cl_fail)${NC}"
            return 1
        fi
        _protocol_removed_side_effects "$core" "${tags[@]}"
    fi
    ( setup_active_defense ) >/dev/null 2>&1 || true
    msg "${GREEN}$(tr_msg cl_done): ${label}${NC}"
    return 0
}

clear_all_protocols() {
    local answer='' core='' info='' cfg=''
    local -a all_tags=()
    read -r -p "$(tr_msg cl_confirm_all) [Y/N]: " answer || return 0
    is_yes "$answer" || { msg "${GREEN}$(tr_msg xl_remove_cancelled)${NC}"; return 0; }
    for core in xray sing-box xray-latest; do
        [[ "$core" == 'xray-latest' && -z "$(_xl_state_get mode)" ]] && continue
        info=$(_protocol_cfg_of "$core") || continue
        IFS='|' read -r cfg _ _ <<< "$info"
        [[ -f "$cfg" && ! -L "$cfg" ]] || continue
        mapfile -t all_tags < <(jq -r '.inbounds[]? | .tag // empty' "$cfg" 2>/dev/null)
        if ! _remove_inbounds_from_config "$core" --all; then
            msg "${YELLOW}[!] ${core}: $(tr_msg cl_fail)${NC}"
            continue
        fi
        (( ${#all_tags[@]} )) && _protocol_removed_side_effects "$core" "${all_tags[@]}"
    done
    argo_remove_unit argo || true
    if [[ -f /etc/hysteria/config.yaml ]]; then _remove_hy2_official; fi
    users_registries_wipe || msg "${YELLOW}[!] $(tprintf cu_users_note '/etc/ddr/users.d')${NC}"
    rm -f -- /etc/ddr/standalone-links.d/*.link 2>/dev/null || true
    ( setup_active_defense ) >/dev/null 2>&1 || true
    msg "${GREEN}$(tr_msg cl_all_done)${NC}"
    return 0
}

cleanup_protocols_menu() {
    local c=''
    while true; do
        clear
        msg "${CYAN}======================================================================${NC}"
        msg "${BOLD}${GREEN}$(tr_msg cl_title)${NC}"
        msg "${CYAN}======================================================================${NC}"
        msg "${YELLOW}1.  $(tr_msg cl_m_single)${NC}"
        msg "${YELLOW}2.  $(tr_msg cl_m_all)${NC}"
        msg "${YELLOW}3.  $(tr_msg cl_m_reset)${NC}"
        msg "${YELLOW}0.  $(tr_msg xl_back_main)${NC}"
        read -r -p "$(tr_msg cl_select)" c || return 0
        case "$c" in
            1) remove_single_protocol_menu; pause_return ;;
            2) clear_all_protocols; pause_return ;;
            3) check_virgin_state ;;
            0) return 0 ;;
            *) msg "${RED}$(tr_msg xl_invalid)${NC}" ;;
        esac
    done
}

check_virgin_state() {
    if [[ -t 1 ]]; then
        command clear || true
    fi
    init_system_environment || die "$(tr_msg vg_init_fail)"
    msg "${YELLOW}$(tr_msg vg_title)${NC}"
    local confirm_virgin=""
    if [[ -t 0 ]]; then
        read -r -p "$(tr_msg vg_confirm)" confirm_virgin || confirm_virgin='N'
    else
        confirm_virgin="${ABOX_YES:-N}"
    fi
    [[ -n "$confirm_virgin" ]] || confirm_virgin='N'
    is_yes "$confirm_virgin" || { msg "${GREEN}$(tr_msg vg_cancelled)${NC}"; pause_return; return 0; }
    : "${ABOX_DIR:?ABOX_DIR 未定义}"
    begin_deployment_transaction 'environment reset' xray sing-box hysteria || die "$(tr_msg vg_tx_fail)"
    preflight_reset_ownership || die "$(tr_msg vg_preflight_fail)"
    stop_all_managed_services || die "$(tr_msg vg_stop)"
    clean_nat_rules || die "$(tr_msg cl_nat)"
    clean_input_rules || die "$(tr_msg cl_input)"
    save_firewall_rules || die "$(tr_msg pi_fw_persist_fail)"
    remove_all_abox_cron_blocks || die "$(tr_msg cl_cron)"
    # Menu 17 deep self-heal: pass force_heal=1 explicitly (never via environment).
    remove_all_owned_core_families 1 || die "$(tr_msg cl_cores_reset)"
    remove_abox_env_file || die "$(tr_msg cl_env_reset)"
    for runtime_file in "$ABOX_DIR/traffic_monitor.sh" "$ABOX_DIR/geo_update.sh" "$ABOX_DIR/socket_probe.sh"; do
        remove_owned_runtime_helper "$runtime_file" || die "$(tprintf cl_runtime_reset "$runtime_file")"
    done
    remove_sni_candidate_cache || die "$(tr_msg cl_sni_reset)"
    if [[ -f "$DEPS_MARKER" && ! -L "$DEPS_MARKER" ]]; then rm -f -- "$DEPS_MARKER" || die "$(tr_msg cl_deps_reset)"; fi
    remove_owned_auxiliary_path /etc/fail2ban/jail.d/A-Box.local || die "$(tr_msg cl_f2b_jail)"
    remove_owned_auxiliary_path /etc/fail2ban/filter.d/A-Box.conf || die "$(tr_msg cl_f2b_filter)"
    remove_owned_auxiliary_path /etc/logrotate.d/A-Box || die "$(tr_msg cl_logrotate)"
    remove_abox_log_files || die "$(tr_msg cl_log_files)"
    # Argo units/binary, WARP/Argo/traffic state and the Wallos fail2ban
    # pair are outside the managed-path lists; remove them best-effort.
    argo_remove_unit argo || true
    argo_remove_unit argo-vmess || true
    argo_remove_unit argo-vless || true
    rm -f /usr/local/bin/cloudflared "$ROUTING_STATE_FILE" "$ARGO_STATE_FILE" /etc/ddr/.argo-token /etc/ddr/.extra-uuids /etc/ddr/.traffic-pair-state /etc/ddr/.desired_state /etc/ddr/.traffic-block-state 2>/dev/null || true; rm -rf -- /etc/ddr/standalone-links.d 2>/dev/null || true
    users_registries_wipe || true
    abox_zram_teardown
    for _wf in /etc/fail2ban/filter.d/A-Box-wallos.conf /etc/fail2ban/jail.d/A-Box-wallos.local; do
        if [[ -f "$_wf" ]] && grep -q 'A-Box-wallos' "$_wf" 2>/dev/null; then rm -f "$_wf" || true; fi
    done
    wallos_https_teardown >/dev/null 2>&1 || true
    wallos_cftunnel_teardown >/dev/null 2>&1 || true
    wallos_stack_teardown
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        if systemctl list-unit-files fail2ban.service >/dev/null 2>&1 && systemctl cat fail2ban.service >/dev/null 2>&1; then
            systemctl try-restart fail2ban >/dev/null 2>&1 || msg "${YELLOW}[!] $(tr_msg cl_f2b_restart_reset)${NC}"
        fi
        systemctl daemon-reload >/dev/null 2>&1 || die "$(tr_msg cl_reload_reset)"
    elif [[ "${INIT_SYS:-}" == openrc ]] && [[ -x /etc/init.d/fail2ban ]]; then
        { rc-service fail2ban status >/dev/null 2>&1 && rc-service fail2ban restart >/dev/null 2>&1 9>&- 10>&-; } || msg "${YELLOW}[!] $(tr_msg cl_f2b_restart_reset)${NC}"
    fi
    commit_deployment_transaction
    remove_abox_swap || msg "${YELLOW}[!] $(tr_msg cl_swap_keep)${NC}"
    msg "${GREEN}$(tr_msg vg_done)${NC}"
    pause_return
}

restore_vps_tune() {
    local quiet="${1:-0}" dir="$ABOX_DIR/tune-backup" line key value path failed=0
    local bbr_module_file='/etc/modules-load.d/A-Box-bbr.conf'
    [[ -d "$dir" ]] || { [[ "$quiet" == 1 ]] || msg "${YELLOW}[!] 没有可恢复的 A-Box 调优快照。${NC}"; return 1; }
    path_tree_has_mountpoint "$dir" && { [[ "$quiet" == 1 ]] || msg "${RED}[!] 调优快照目录或其子树存在挂载点，拒绝恢复后删除。${NC}"; return 1; }
    path_parent_chain_safe /etc/sysctl.d/99-A-Box-tune.conf || return 1
    path_parent_chain_safe /etc/security/limits.d/A-Box.conf || return 1
    path_parent_chain_safe "$bbr_module_file" || return 1
    [[ ! -L /etc/sysctl.d && (! -e /etc/sysctl.d || -d /etc/sysctl.d) ]] || return 1
    [[ ! -L /etc/security/limits.d && (! -e /etc/security/limits.d || -d /etc/security/limits.d) ]] || return 1
    [[ ! -L /etc/modules-load.d && (! -e /etc/modules-load.d || -d /etc/modules-load.d) ]] || return 1
    for path in /etc/sysctl.d/99-A-Box-tune.conf /etc/security/limits.d/A-Box.conf "$bbr_module_file"; do
        [[ ! -e "$path" && ! -L "$path" ]] || auxiliary_path_is_abox_managed "$path" || return 1
    done
    if [[ -f "$dir/sysctl.original" ]]; then
        while IFS='=' read -r key value; do [[ -n "$key" ]] || continue; sysctl -w "$key=$value" >/dev/null 2>&1 || failed=1; done < "$dir/sysctl.original"
    fi
    if [[ -f "$dir/sysctl.conf" ]]; then install -d -m 755 /etc/sysctl.d || failed=1; cp -a "$dir/sysctl.conf" /etc/sysctl.d/99-A-Box-tune.conf || failed=1; else rm -f /etc/sysctl.d/99-A-Box-tune.conf || failed=1; fi
    if [[ -f "$dir/limits.conf" ]]; then install -d -m 755 /etc/security/limits.d || failed=1; cp -a "$dir/limits.conf" /etc/security/limits.d/A-Box.conf || failed=1; else rm -f /etc/security/limits.d/A-Box.conf || failed=1; fi
    if [[ -f "$dir/bbr-modules.conf" ]]; then
        install -d -m 755 /etc/modules-load.d || failed=1
        cp -a "$dir/bbr-modules.conf" "$bbr_module_file" || failed=1
    else
        rm -f -- "$bbr_module_file" || failed=1
    fi
    sysctl --system >/dev/null 2>&1 || failed=1
    (( failed == 0 )) || return 1
    path_tree_has_mountpoint "$dir" && return 1
    rm -rf -- "$dir" || return 1
    [[ "$quiet" == 1 ]] || msg "${GREEN}A-Box VPS 调优已恢复。${NC}"
}

# Desired sysctl tune set, one "key value" per line. BBR/FQ keys are included
# only when the running kernel actually offers BBR.
_tune_desired_sysctl() {
    local available
    printf '%s\n' \
        'fs.file-max 1048576' \
        'fs.inotify.max_user_instances 8192' \
        'net.ipv4.tcp_syncookies 1' \
        'net.ipv4.tcp_fin_timeout 30' \
        'net.ipv4.tcp_max_syn_backlog 8192' \
        'net.ipv4.tcp_fastopen 3' \
        'net.ipv4.tcp_mtu_probing 1' \
        'net.ipv4.tcp_notsent_lowat 16384' \
        'net.core.netdev_max_backlog 250000' \
        'net.core.somaxconn 32768'
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)
    if grep -qw bbr <<< "$available"; then
        printf '%s\n' 'net.core.default_qdisc fq' 'net.ipv4.tcp_congestion_control bbr'
    fi
}

# Prints one line per tune item that is missing or drifted from the desired
# state (sysctl live values, limits file, BBR persistence). Empty output means
# the VPS is fully tuned.
_tune_missing_items() {
    local key want got missing_list='' available
    while read -r key want; do
        [[ -n "$key" ]] || continue
        sysctl -n "$key" >/dev/null 2>&1 || continue
        got=$(sysctl -n "$key" 2>/dev/null)
        [[ "$got" == "$want" ]] || missing_list+="${key}（当前 ${got:-<空>}，期望 $want）"$'\n'
    done < <(_tune_desired_sysctl)
    if ! grep -q '^# Managed by A-Box' /etc/security/limits.d/A-Box.conf 2>/dev/null \
        || ! grep -q '^\* soft nofile 1048576' /etc/security/limits.d/A-Box.conf 2>/dev/null; then
        missing_list+='limits 配置（nofile 上限 1048576）'$'\n'
    fi
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)
    if grep -qw bbr <<< "$available" && modprobe tcp_bbr >/dev/null 2>&1; then
        grep -qx 'tcp_bbr' /etc/modules-load.d/A-Box-bbr.conf 2>/dev/null \
            || missing_list+='BBR 模块开机自动加载配置'$'\n'
    fi
    printf '%s' "$missing_list"
}

# BUG-28: hoisted from apply_vps_tune(). $3 = destination file.
__abox_add_sysctl() {
    sysctl -n "$1" >/dev/null 2>&1 && printf '%s = %s\n' "$1" "$2" >> "$3"
}
apply_vps_tune() {
    local dir="$ABOX_DIR/tune-backup" tmp key value available bbr_loaded=0
    local bbr_module_file='/etc/modules-load.d/A-Box-bbr.conf'
    local missing snapshot_exists=0 snapshot_tmp
    assert_abox_auxiliary_safe /etc/security/limits.d/A-Box.conf || die "$(tprintf ax_refuse "/etc/security/limits.d/A-Box.conf")"
    assert_abox_auxiliary_safe /etc/sysctl.d/99-A-Box-tune.conf || die "$(tprintf ax_refuse "/etc/sysctl.d/99-A-Box-tune.conf")"
    assert_abox_auxiliary_safe "$bbr_module_file" || die "$(tprintf ax_refuse "$bbr_module_file")"
    # Snapshot state validation stays strict: a half-written snapshot is unsafe.
    if [[ -f "$dir/.captured" ]]; then
        snapshot_exists=1
    elif [[ -e "$dir" || -L "$dir" ]]; then
        [[ -d "$dir" && ! -L "$dir" ]] || die "$(tr_msg tn_backup_unsafe)"
        [[ -z "$(find "$dir" -mindepth 1 -maxdepth 1 -print -quit 2>/dev/null)" ]] || { msg "${RED}[!] 检测到未完成的调优快照；请先检查并恢复/清理该快照。${NC}"; return 1; }
    fi
    # Idempotent re-run: inspect live state first, never error out on re-apply.
    missing=$(_tune_missing_items)
    if [[ -z "$missing" ]]; then
        msg "${GREEN}VPS 调优已全部应用，无需重复操作。${NC}"
        return 0
    fi
    msg "${YELLOW}检测到未应用的调优项：${NC}"
    msg "$missing"
    if (( snapshot_exists == 1 )); then
        msg "${YELLOW}[!] 保留已有调优快照（恢复时仍回到最初状态），仅补齐缺失项。${NC}"
    else
        snapshot_tmp=$(mktemp -d "$ABOX_DIR/.tune-backup-new.XXXXXX") || die "$(tr_msg tn_backup_tmp)"
        if [[ -f /etc/sysctl.d/99-A-Box-tune.conf ]] && ! cp -a /etc/sysctl.d/99-A-Box-tune.conf "$snapshot_tmp/sysctl.conf"; then
            rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_sysctl_backup)"
        fi
        if [[ -f /etc/security/limits.d/A-Box.conf ]] && ! cp -a /etc/security/limits.d/A-Box.conf "$snapshot_tmp/limits.conf"; then
            rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_limits_backup)"
        fi
        if [[ -f "$bbr_module_file" ]] && ! cp -a "$bbr_module_file" "$snapshot_tmp/bbr-modules.conf"; then
            rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_bbr_backup)"
        fi
        : > "$snapshot_tmp/sysctl.original" || { rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_snapshot_create)"; }
        for key in fs.file-max fs.inotify.max_user_instances net.ipv4.tcp_syncookies net.ipv4.tcp_fin_timeout net.ipv4.tcp_keepalive_time net.ipv4.tcp_max_syn_backlog net.ipv4.tcp_max_tw_buckets net.ipv4.tcp_fastopen net.ipv4.tcp_mtu_probing net.ipv4.tcp_notsent_lowat net.core.netdev_max_backlog net.core.somaxconn net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem net.ipv4.tcp_slow_start_after_idle net.ipv4.ip_local_port_range net.core.default_qdisc net.ipv4.tcp_congestion_control; do
            value=$(sysctl -n "$key" 2>/dev/null) || continue
            printf '%s=%s\n' "$key" "$value" >> "$snapshot_tmp/sysctl.original" || { rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_snapshot_write)"; }
        done
        touch "$snapshot_tmp/.captured" || { rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_snapshot_mark)"; }
        if [[ -d "$dir" ]]; then
            rmdir -- "$dir" || { rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_replace_dir)"; }
        fi
        mv -f -- "$snapshot_tmp" "$dir" || { rm -rf -- "$snapshot_tmp"; die "$(tr_msg tn_commit)"; }
    fi
    write_file_atomically_from_stdin /etc/security/limits.d/A-Box.conf 644 <<'EOF_LIMITS' || { restore_vps_tune 1 || true; die 'limits 配置原子写入失败，已恢复原状态。'; }
# Managed by A-Box
* soft nofile 1048576
* hard nofile 1048576
root soft nofile 1048576
root hard nofile 1048576
EOF_LIMITS
    tmp=$(umask 077; mktemp /tmp/A-Box-sysctl.XXXXXX) || { restore_vps_tune 1 || true; die "$(tr_msg tn_tmp)"; }
    printf '%s\n' '# Managed by A-Box' > "$tmp" || { rm -f "$tmp"; restore_vps_tune 1 || true; die "$(tr_msg tn_tmp_init)"; }
    __abox_add_sysctl fs.file-max 1048576 "$tmp"
    __abox_add_sysctl fs.inotify.max_user_instances 8192 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_syncookies 1 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_fin_timeout 30 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_max_syn_backlog 8192 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_fastopen 3 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_mtu_probing 1 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_notsent_lowat 16384 "$tmp"
    __abox_add_sysctl net.core.netdev_max_backlog 250000 "$tmp"
    __abox_add_sysctl net.core.somaxconn 32768 "$tmp"
    __abox_add_sysctl net.core.rmem_max 16777216 "$tmp"
    __abox_add_sysctl net.core.wmem_max 16777216 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_rmem '4096 87380 16777216' "$tmp"
    __abox_add_sysctl net.ipv4.tcp_wmem '4096 65536 16777216' "$tmp"
    __abox_add_sysctl net.ipv4.tcp_keepalive_time 600 "$tmp"
    __abox_add_sysctl net.ipv4.tcp_slow_start_after_idle 0 "$tmp"
    __abox_add_sysctl net.ipv4.ip_local_port_range '10240 65535' "$tmp"
    if modprobe tcp_bbr >/dev/null 2>&1; then bbr_loaded=1; fi
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || true)
    if grep -qw bbr <<< "$available"; then
        __abox_add_sysctl net.core.default_qdisc fq "$tmp"
        __abox_add_sysctl net.ipv4.tcp_congestion_control bbr "$tmp"
        if (( bbr_loaded == 1 )); then
            path_parent_chain_safe "$bbr_module_file" || { rm -f -- "$tmp"; restore_vps_tune 1 || true; die "$(tr_msg tn_bbr_chain)"; }
            [[ ! -L /etc/modules-load.d && (! -e /etc/modules-load.d || -d /etc/modules-load.d) ]] || { rm -f -- "$tmp"; restore_vps_tune 1 || true; die "$(tr_msg tn_moddir_unsafe)"; }
            install -d -m 755 /etc/modules-load.d || { rm -f -- "$tmp"; restore_vps_tune 1 || true; die "$(tr_msg tn_moddir_create)"; }
            write_file_atomically_from_stdin "$bbr_module_file" 644 <<'EOF_BBR' || { rm -f -- "$tmp"; restore_vps_tune 1 || true; die 'BBR 内核模块持久加载配置写入失败。'; }
# Managed by A-Box
tcp_bbr
EOF_BBR
        fi
    else
        msg "${YELLOW}[!] 当前内核未提供 BBR，跳过 BBR/FQ 设置。${NC}"
    fi
    install_file_atomically "$tmp" /etc/sysctl.d/99-A-Box-tune.conf 600 || { rm -f "$tmp"; restore_vps_tune 1 || true; die "$(tr_msg tn_atomic_write)"; }
    rm -f "$tmp"
    if ! sysctl -p /etc/sysctl.d/99-A-Box-tune.conf >/dev/null 2>&1; then restore_vps_tune 1; die "$(tr_msg tn_apply)"; fi
    missing=$(_tune_missing_items)
    if [[ -z "$missing" ]]; then
        msg "${GREEN}缺失项已补齐，系统调优已全部应用；未强制启用 IP forwarding，也未修改核心 JSON 配置。${NC}"
    else
        msg "${YELLOW}[!] 以下调优项仍未生效（可能为内核限制）：${NC}"
        msg "$missing"
    fi
}



# Operations helpers
abox_is_fast() {
    [[ "${ABOX_FAST:-}" =~ ^(1|true|yes|YES|True)$ ]] && return 0
    [[ -r "$FAST_MODE_FILE" && -f "$FAST_MODE_FILE" && ! -L "$FAST_MODE_FILE" ]] || return 1
    [[ "$(tr -d '[:space:]' < "$FAST_MODE_FILE" 2>/dev/null || true)" == '1' ]]
}

read_fast_mode_label() {
    # Menu target look (2026-10-19): mode word follows UI language (display only).
    local _m=strict
    abox_is_fast && _m=fast
    case "${ABOX_LANG:-zh}" in
        en)    printf '%s\n' "$_m" ;;
        ru)    [[ "$_m" == fast ]] && printf 'быстрый\n' || printf 'строгий\n' ;;
        fa)    [[ "$_m" == fast ]] && printf 'سریع\n' || printf 'سخت‌گیرانه\n' ;;
        zh-tw) [[ "$_m" == fast ]] && printf '快速\n' || printf '嚴格\n' ;;
        ja)    [[ "$_m" == fast ]] && printf '高速\n' || printf '厳格\n' ;;
        *)     [[ "$_m" == fast ]] && printf '快速\n' || printf '严格\n' ;;
    esac
}

save_fast_mode() {
    local v="${1:-0}"
    [[ "$v" =~ ^(0|1)$ ]] || die "$(tr_msg fm_bad)"
    ensure_abox_dir_owned "$ABOX_DIR" || die "$(tr_msg state_dir_prep)"
    write_file_atomically_from_stdin "$FAST_MODE_FILE" 600 <<< "$v" || die "$(tr_msg fm_write)"
}

abox_prefer_mirror() {
    # Compatibility shim; official stable releases always have priority.
    return 1
}

save_mirror_prefer() {
    msg "${YELLOW}核心下载顺序固定为：上游正式稳定版 → 固定 A-Box 容灾版本。${NC}"
    return 1
}


confirm_soft() {
    # Non-critical confirm: auto-yes in fast mode. Never use for uninstall/digest/destructive wipe.
    local prompt="$1" answer
    if abox_is_fast; then
        msg "${YELLOW}[fast] ${prompt} → Y${NC}"
        return 0
    fi
    read -r -p "$prompt" answer || return 1
    is_yes "$answer"
}

show_core_pin_docs() {
    clear
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}核心版本选择与容灾说明 / Core release policy${NC}"
    msg "${CYAN}======================================================================${NC}"
    # F-10 fix: do not imply routine upgrades always use compat pins.
    # Xray defaults to pinned; sing-box/Hysteria default to auto-stable.
    msg "Update policy per core: Xray ${YELLOW}pinned${NC} (${ABOX_XRAY_DEFAULT_VERSION}); sing-box ${YELLOW}auto-stable${NC} (compat pin ${ABOX_SINGBOX_DEFAULT_VERSION}); Hysteria ${YELLOW}auto-stable${NC} (compat pin ${ABOX_HYSTERIA_DEFAULT_VERSION})."
    msg "Auto-stable follows the latest official stable tag after a ${YELLOW}${ABOX_STABLE_COOLDOWN_DAYS:-7}-day${NC} cooling period (draft/prerelease excluded); config, client compatibility, and post-upgrade health gates still apply."
    msg "Fixed compatibility recovery assets remain in Release: ${YELLOW}${ABOX_CORE_MIRROR_RELEASE}${NC}. Latest-stable attempts try an exact-tag versioned mirror first, then these fixed pins."
    msg "CORE-VERSIONS is accepted only when its digest matches SHA256SUMS; older versioned mirror assets are retained for rollback."
    msg "Explicit version overrides: ABOX_XRAY_VERSION / ABOX_SINGBOX_VERSION / ABOX_HYSTERIA_APP_VERSION; failed explicit pins do not silently switch versions."
    msg "Every candidate must pass tag/URL, SHA-256, archive structure and actual binary-version checks."
    msg "Mode: ${YELLOW}$(read_fast_mode_label)${NC} (ABOX_FAST=1 or ${FAST_MODE_FILE})"
    pause_return
}

probe_core_sources_banner() {
    local pref='compatibility-pin-first' api_code mirror_code base
    [[ "${ABOX_TRY_LATEST_CORE_STABLE:-0}" == '1' ]] && pref='latest-official-stable-first'
    base="${ABOX_CORE_MIRROR_BASE:-$ABOX_CORE_MIRROR_BASE_DEFAULT}"
    api_code=$(curl -sS -o /dev/null -w '%{http_code}' --connect-timeout 3 --max-time 5 'https://api.github.com/repos/XTLS/Xray-core/releases?per_page=100' 2>/dev/null || printf '000')
    mirror_code=$(curl -sSL -o /dev/null -w '%{http_code}' --connect-timeout 3 --max-time 5 "${base%/}/SHA256SUMS" 2>/dev/null || printf '000')
    case "$api_code" in 200) api_code='available (HTTP 200)' ;; *) api_code="unavailable (HTTP ${api_code:-000})" ;; esac
    case "$mirror_code" in 200) mirror_code='available (HTTP 200)' ;; *) mirror_code="unavailable (HTTP ${mirror_code:-000})" ;; esac
    msg "${CYAN}[download sources] order=${pref} → fixed recovery mirror; release API: ${api_code}; recovery SHA256SUMS: ${mirror_code}; custom base=${ABOX_CORE_MIRROR_BASE:-<unset>}${NC}"
}

# Pinned-utility mirror fetch (cloudflared / wgcf). The caller's in-script
# SHA-256 pin remains the verification anchor for BOTH sources: mirror bytes
# are used only when they match the pin exactly, so this adds an
# availability fallback without any new trust assumption.
fetch_util_mirror_asset() {
    local leaf="${1:-}" dest="${2:-}" base="${ABOX_CORE_MIRROR_BASE:-$ABOX_CORE_MIRROR_BASE_DEFAULT}"
    [[ -n "$leaf" && -n "$dest" && -n "$base" ]] || return 1
    case "$base" in https://*) ;; *) return 1 ;; esac
    msg "${YELLOW} -> A-Box recovery mirror: ${base%/}/${leaf}${NC}"
    curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 10 -m 180 "${base%/}/${leaf}" -o "$dest" 2>/dev/null
}

fetch_abox_mirror_asset() {
    local repo="${1:-}" output_file="${2:-}" dest_file="${3:-}" requested_version="${4:-}" prefer_versioned="${5:-0}"
    local mirror_base mirror_url mirror_sum expect_sum got_sum asset_leaf tmp_file
    mirror_base="${ABOX_CORE_MIRROR_BASE:-$ABOX_CORE_MIRROR_BASE_DEFAULT}"
    [[ -n "$mirror_base" ]] || return 1
    # Integrity depends on TLS: a plaintext HTTP mirror lets a network attacker
    # serve a backdoored binary with a matching forged SHA256SUMS. Refuse.
    case "$mirror_base" in
        https://*) ;;
        *) msg "${RED}[!] ABOX_CORE_MIRROR_BASE must use https://; refusing plaintext mirror (integrity bypass).${NC}" >&2; return 1 ;;
    esac
    if [[ -z "$requested_version" ]]; then requested_version=$(core_release_mirror_version "$repo") || return 1; fi
    core_release_ref_valid "$repo" "$requested_version" || return 1
    asset_leaf=$(core_mirror_asset_leaf "$repo" "$output_file" "$requested_version" "$prefer_versioned") || return 1
    mirror_url="${mirror_base%/}/${asset_leaf}"; mirror_sum="${mirror_base%/}/SHA256SUMS"
    msg "${YELLOW} -> A-Box recovery mirror: ${mirror_url} [${requested_version}]${NC}"
    tmp_file=$(mktemp "${dest_file}.download.XXXXXX") || return 1
    # F-02 fix: if fixed-name asset 404s, fall back to versioned filename.
    if ! curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 10 -m 180 "$mirror_url" -o "$tmp_file"; then
        rm -f -- "$tmp_file"
        if [[ "$prefer_versioned" != '1' ]]; then
            local versioned_leaf
            versioned_leaf=$(core_mirror_asset_leaf "$repo" "$output_file" "$requested_version" 1) || return 1
            if [[ "$versioned_leaf" != "$asset_leaf" ]]; then
                msg "${YELLOW} -> Fixed-name asset not found, trying versioned: ${versioned_leaf}${NC}" >&2
                asset_leaf="$versioned_leaf"
                mirror_url="${mirror_base%/}/${asset_leaf}"
                tmp_file=$(mktemp "${dest_file}.download.XXXXXX") || return 1
                if ! curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 10 -m 180 "$mirror_url" -o "$tmp_file"; then rm -f -- "$tmp_file"; return 1; fi
            else
                return 1
            fi
        else
            return 1
        fi
    fi
    if ! validate_downloaded_asset "$output_file" "$tmp_file"; then rm -f -- "$tmp_file"; return 1; fi
    # N-16 fix: use fixed-string matching, not regex. The old $2~(f"$") treated
    # dots in filenames as regex wildcards.
    # DS-High-02: verify SHA256SUMS signature before trusting it (F-05 trust root).
    local sum_file sum_sig
    sum_file=$(mktemp) || { rm -f -- "$tmp_file"; return 1; }
    sum_sig="${sum_file}.sig"
    if ! curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 8 -m 30 "$mirror_sum" -o "$sum_file" 2>/dev/null; then
        rm -f -- "$tmp_file" "$sum_file"; return 1
    fi
    curl -fLsS --retry 2 --retry-delay 2 --connect-timeout 8 -m 30 "${mirror_sum}.sig" -o "$sum_sig" 2>/dev/null || true
    # DS-High-02: abox_verify_sig_gate 本身就是 (c) 语义 (默认 fail-closed,
    # ABOX_SIGNING_ENFORCE=0 为显式逃生门)。无需新造变量。
    if ! abox_verify_sig_gate "$sum_file" "$sum_sig" "recovery mirror SHA256SUMS"; then
        rm -f -- "$tmp_file" "$sum_file" "$sum_sig"; return 1
    fi
    expect_sum=$(awk -v f="$asset_leaf" '$2==f || $2==("./" f) || (n=length(f), substr($2, length($2)-n+1)==f && (length($2)==n || substr($2, length($2)-n, 1)=="/")) {print $1; exit}' "$sum_file")
    rm -f -- "$sum_file" "$sum_sig"
    got_sum=$(sha256sum "$tmp_file" 2>/dev/null | awk '{print $1}') || got_sum=''
    if [[ -z "$expect_sum" || ! "$expect_sum" =~ ^[A-Fa-f0-9]{64}$ || "${got_sum,,}" != "${expect_sum,,}" ]]; then msg "${YELLOW}[!] recovery mirror SHA-256 mismatch or missing SHA256SUMS${NC}" >&2; rm -f -- "$tmp_file"; return 1; fi
    if ! validate_core_asset_binary_version "$output_file" "$tmp_file" "$requested_version"; then msg "${YELLOW}[!] recovery binary version does not match requested version ${requested_version}${NC}" >&2; rm -f -- "$tmp_file"; return 1; fi
    mv -f -- "$tmp_file" "$dest_file" || { rm -f -- "$tmp_file"; return 1; }
    msg "${GREEN}   recovery SHA-256 and actual binary version verified: ${requested_version}${NC}"
    return 0
}
one_click_reality_deploy() {
    local choice answer prompt
    clear
    msg "${CYAN}======================================================================${NC}"
    case "${ABOX_LANG:-zh}" in
        en)
            msg "${RED}${BOLD}One-click Vision REALITY${NC}"
            msg "Defaults: port 443, SNI auto-selected from this VPS; www.amazon.com is used only after TLS 1.3/h2/SAN verification. If no target verifies, one-click setup stops. KeepAlive off."
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='Deploy one-click Vision REALITY now? [Y/N]: ' ;;
        ru)
            msg "${RED}${BOLD}Vision REALITY в один клик${NC}"
            msg "По умолчанию SNI выбирается по тестам этого VPS; www.amazon.com используется только после проверки TLS 1.3/h2/SAN. Если цель не подтверждена, установка в один клик остановится. KeepAlive выключен."
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='Запустить установку Vision REALITY в один клик? [Y/N]: ' ;;
        fa)
            msg "${RED}${BOLD}نصب یک‌کلیکی Vision REALITY${NC}"
            msg "پیش‌فرض SNI بر اساس آزمون‌های همین VPS انتخاب می‌شود؛ www.amazon.com فقط پس از بررسی TLS 1.3/h2/SAN استفاده می‌شود. اگر هیچ مقصدی تأیید نشود، نصب یک‌کلیکی متوقف می‌شود. KeepAlive خاموش است."
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='نصب یک‌کلیکی Vision REALITY آغاز شود؟ [Y/N]: ' ;;
        ja)
            msg "${RED}${BOLD}ワンクリック Vision REALITY${NC}"
            msg "デフォルト: port 443。SNI はこの VPS の TLS/ASN/地域に関する実測結果に基づいて自動選択されます。www.amazon.com は TLS 1.3/h2/証明書 SAN の検証に成功した場合のみフォールバック先として使用されます。検証可能な接続先がない場合、ワンクリックインストールは停止します。KeepAlive は無効です。"
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='今すぐ Vision REALITY をワンクリックでデプロイしますか？[Y/N]: ' ;;
        zh-tw)
            msg "${RED}${BOLD}一鍵 Vision REALITY${NC}"
            msg "預設 SNI 根據當前 VPS 的 TLS/ASN/地區實測自動選擇；僅在 www.amazon.com 透過 TLS 1.3/h2/證書 SAN 驗證後才用作回退。無可驗證目標時一鍵安裝會停止。KeepAlive 關閉。"
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='現在開始一鍵部署 Vision REALITY？[Y/N]: ' ;;
        *)
            msg "${RED}${BOLD}一键 Vision REALITY${NC}"
            msg "默认 SNI 根据当前 VPS 的 TLS/ASN/地区实测自动选择；仅在 www.amazon.com 通过 TLS 1.3/h2/证书 SAN 验证后才用作回退。无可验证目标时一键安装会停止。KeepAlive 关闭。"
            msg "${YELLOW}1. Xray Vision REALITY${NC}"
            msg "${YELLOW}2. sing-box Vision REALITY${NC}"
            prompt='现在开始一键部署 Vision REALITY？[Y/N]: ' ;;
    esac
    msg "${CYAN}0. Cancel / 返回${NC}"
    read -r -p 'Select [0-2]: ' choice || return 0
    case "$choice" in 1|2) ;; *) return 0 ;; esac
    load_abox_env "$ABOX_ENV" >/dev/null 2>&1 || true
    if deployment_evidence_exists || [[ -n "${CORE:-}" || -n "${MODE:-}" ]]; then
        local _oc_cur="${CORE:-?}-${MODE:-?}"
        [[ -n "${CORE:-}" || -n "${MODE:-}" ]] || _oc_cur="$(tr_msg dp_existing)"
        msg "${RED}[!] $(tprintf oc_replace_warn "$_oc_cur")${NC}"
    fi
    if ! confirm_soft "$prompt"; then
        case "${ABOX_LANG:-zh}" in
            en) msg "${YELLOW}Cancelled.${NC}" ;;
            ru) msg "${YELLOW}Отменено.${NC}" ;;
            fa) msg "${YELLOW}لغو شد.${NC}" ;;
            zh-tw) msg "${YELLOW}已取消。${NC}" ;;
            ja)
                msg "${YELLOW}キャンセルしました。${NC}" ;;
            *) msg "${YELLOW}已取消。${NC}" ;;
        esac
        pause_return; return 0
    fi
    export ABOX_QUICK_DEPLOY=1
    case "$choice" in 1) deploy_xray VISION ;; 2) deploy_singbox VISION ;; esac
    unset ABOX_QUICK_DEPLOY
}
ux_mode_menu() {
    # Submenu loop: sub-functions return here; 0/Enter goes back to the parent menu.
    while true; do
    clear
    local c
    case "${ABOX_LANG:-zh}" in
        en)
            msg "${BOLD}${GREEN}Runtime mode and core version policy${NC}"
            msg "Current mode: ${YELLOW}$(read_fast_mode_label)${NC} | Core order: official stable → fixed recovery mirror"
            msg "${YELLOW}1. Strict mode${NC}"
            msg "${YELLOW}2. Fast mode (non-critical confirmations only)${NC}"
            msg "${YELLOW}3. Show stable version policy and recovery pins${NC}"
            msg "${CYAN}0. Back${NC}" ;;
        ru)
            msg "${BOLD}${GREEN}Режим работы и политика версий ядер${NC}"
            msg "Режим: ${YELLOW}$(read_fast_mode_label)${NC} | Источник: стабильная upstream-версия → резервная копия"
            msg "${YELLOW}1. Строгий режим${NC}"
            msg "${YELLOW}2. Быстрый режим${NC}"
            msg "${YELLOW}3. Политика стабильных версий и резервные pins${NC}"
            msg "${CYAN}0. Назад${NC}" ;;
        fa)
            msg "${BOLD}${GREEN}حالت اجرا و سیاست نسخه هسته‌ها${NC}"
            msg "حالت: ${YELLOW}$(read_fast_mode_label)${NC} | منبع: نسخه پایدار upstream سپس نسخه بازیابی"
            msg "${YELLOW}1. حالت سخت‌گیرانه${NC}"
            msg "${YELLOW}2. حالت سریع${NC}"
            msg "${YELLOW}3. سیاست نسخه پایدار و نسخه‌های بازیابی${NC}"
            msg "${CYAN}0. بازگشت${NC}" ;;
        zh-tw)
            msg "${BOLD}${GREEN}執行模式與核心版本策略${NC}"
            msg "當前模式: ${YELLOW}$(read_fast_mode_label)${NC} | 核心來源：上游正式穩定版 → 固定容災映象"
            msg "${YELLOW}1. 嚴格模式${NC}"
            msg "${YELLOW}2. 快速模式（只跳過非關鍵確認）${NC}"
            msg "${YELLOW}3. 檢視正式穩定版策略與固定容災版本${NC}"
            msg "${CYAN}0. 返回${NC}" ;;
        ja)
            msg "${BOLD}${GREEN}実行モードとコアバージョンのポリシー${NC}"
            msg "現在のモード: ${YELLOW}$(read_fast_mode_label)${NC} | コアの取得順序: 公式の安定版 → 固定リカバリミラー"
            msg "${YELLOW}1. 厳格モード${NC}"
            msg "${YELLOW}2. 高速モード（重要でない確認のみをスキップ）${NC}"
            msg "${YELLOW}3. 公式安定版のポリシーと固定リカバリバージョンを表示${NC}"
            msg "${CYAN}0. 戻る${NC}" ;;
        *)
            msg "${BOLD}${GREEN}运行模式与核心版本策略${NC}"
            msg "当前模式: ${YELLOW}$(read_fast_mode_label)${NC} | 核心来源：上游正式稳定版 → 固定容灾镜像"
            msg "${YELLOW}1. 严格模式${NC}"
            msg "${YELLOW}2. 快速模式（只跳过非关键确认）${NC}"
            msg "${YELLOW}3. 查看正式稳定版策略与固定容灾版本${NC}"
            msg "${CYAN}0. 返回${NC}" ;;
    esac
    read -r -p 'Select [0-3]: ' c || return 0
    case "$c" in
        1) save_fast_mode 0; pause_return ;;
        2) save_fast_mode 1; pause_return ;;
        3) show_core_pin_docs ;;
        0) return 0 ;;
        *) msg "${RED}$(tr_msg invalid_input): $c${NC}"; sleep 1 ;;
    esac
    done
}
list_extra_uuids() {
    # FINAL-AUDIT fix: only a TRULY ABSENT file is an empty list. A file that
    # exists but is a symlink, unreadable, or not a regular file is a hard
    # failure; otherwise callers silently overwrite it and revoke all stored
    # extra UUIDs.
    if [[ ! -e "$EXTRA_UUID_FILE" && ! -L "$EXTRA_UUID_FILE" ]]; then
        return 0
    fi
    [[ -r "$EXTRA_UUID_FILE" && -f "$EXTRA_UUID_FILE" && ! -L "$EXTRA_UUID_FILE" ]] || return 1
    # Validate UUID shape without interval-regex operators such as {8}. Older
    # mawk versions shipped by supported legacy distributions do not implement
    # interval expressions, which would otherwise silently hide every UUID.
    awk -v primary="${UUID:-}" '
        {
            if (split($0, part, "-") != 5) next
            if (length(part[1]) != 8 || length(part[2]) != 4 || length(part[3]) != 4 || length(part[4]) != 4 || length(part[5]) != 12) next
            if ($0 !~ /^[0-9A-Fa-f-]+$/) next
            if (tolower($0) != tolower(primary) && !seen[tolower($0)]++) print $0
        }
    ' "$EXTRA_UUID_FILE" 2>/dev/null || true
}

# Write the full UUID list (primary UUID first, then extras) to $1.
# Returns 1 if the extra-UUID list is unreadable/untrusted. Callers MUST
# abort on failure; never treat a failed read as an empty list.
# (TRAP-7: do NOT use `done < <(list_extra_uuids)` -- process substitution
# swallows the exit status. Use this helper with an explicit status check.)
write_full_uuid_list_to_file() {
    local out="$1"
    # TRAP-7(c): declare first, assign separately -- `local x=$(cmd)` masks
    # the exit code (local always returns 0).
    local _rc
    {
        printf '%s\n' "${UUID:-}"
        list_extra_uuids
    } > "$out"
    _rc=$?
    return "$_rc"
}

sync_uuids_into_xray_config() {
    local cfg='/usr/local/etc/xray/config.json' tmp primary extras_json
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    primary="${UUID:-}"
    [[ -n "$primary" ]] || return 1
    # FINAL-AUDIT: PIPESTATUS[0] catches a list_extra_uuids failure that the
    # pipeline would otherwise mask (jq's exit code wins). Never sync a
    # config built from an untrusted/empty UUID list.
    local _uuid_list_rc=0
    extras_json=$(list_extra_uuids | jq -R . | jq -s -c 'map(select(length>0))')
    _uuid_list_rc=${PIPESTATUS[0]:-0}
    if (( _uuid_list_rc != 0 )); then
        msg "${RED}Extra UUID list is unreadable or untrusted; refusing to sync Xray config.${NC}" >&2
        return 1
    fi
    [[ -n "$extras_json" ]] || extras_json='[]'
    tmp=$(mktemp /tmp/A-Box-uuid.XXXXXX) || return 1
    if ! jq --arg p "$primary" --argjson extras "$extras_json" '
        .inbounds |= map(
          if .protocol=="vless" then
            (.settings.clients[0].flow // "") as $flow |
            (.tag // "vless") as $itag |
            .settings.clients = (
              [({id:$p, email:($itag + "/main")} + (if $flow != "" then {flow:$flow} else {} end))]
              + ($extras | map({id:., email:($itag + "/x-" + .[0:8])} + (if $flow != "" then {flow:$flow} else {} end)))
            )
          else . end
        )
      ' "$cfg" > "$tmp"; then
        rm -f "$tmp"; return 1
    fi
    jq empty "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 1; }
    if [[ -x /usr/local/bin/xray ]]; then
        XRAY_LOCATION_ASSET=/usr/local/share/xray /usr/local/bin/xray run -test -config "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 1; }
    fi
    install_file_atomically "$tmp" "$cfg" 600 || { rm -f "$tmp"; return 1; }
    # C-02: Restore abox-xray read permission (install_file_atomically creates root:root 600).
    prepare_abox_runtime_permissions xray || { rm -f "$tmp"; return 1; }
    rm -f "$tmp"
    return 0
}

export_lightweight_subscription() {
    local CALLER=${1:-manual} F_IP VISION_SNI_E XHTTP_SNI_E PUBLIC_KEY_E SHORT_ID_E uri_file b64_file clash_file u url client_uuid proxy_name
    ensure_abox_dir_owned "$ABOX_DIR" || die 'subscribe dir prepare failed'
    mkdir -p "$SUBSCRIBE_DIR" || die 'subscribe dir create failed'
    # A-05c-FIX: Directory chmod failure is fatal (was || true, fail-open).
    chmod 700 "$SUBSCRIBE_DIR" || return 1
    [[ -f "$ABOX_ENV" ]] || { msg "${RED}No deployment env.${NC}"; pause_return; return 1; }
    load_abox_env "$ABOX_ENV" || die 'env invalid'
    F_IP="${LINK_IP:-}"
    [[ "$F_IP" =~ : ]] && F_IP="[$F_IP]"
    VISION_SNI=${VISION_SNI:-${VLESS_SNI:-}}
    XHTTP_SNI=${XHTTP_SNI:-${VLESS_SNI:-}}
    VISION_SNI_E=$(urlencode "${VISION_SNI:-}")
    XHTTP_SNI_E=$(urlencode "${XHTTP_SNI:-}")
    PUBLIC_KEY_E=$(urlencode "${PUBLIC_KEY:-}")
    SHORT_ID_E=$(urlencode "${SHORT_ID:-}")
    uri_file="$SUBSCRIBE_DIR/uri-list.txt"
    b64_file="$SUBSCRIBE_DIR/subscription.base64"
    # A-05c-FIX: Build URI content in temp file (umask 077), then atomic install 600.
    # Previously: ": > uri_file" created 0644 under umask 022, then chmod 600 (window).
    local uri_tmp
    uri_tmp=$(umask 077; mktemp "$SUBSCRIBE_DIR/.uri-list.XXXXXX") || return 1
    # TRAP-7: capture UUID list to temp file with explicit status check.
    # Process substitution would swallow a list_extra_uuids failure.
    local _uuid_list_tmp
    _uuid_list_tmp=$(umask 077; mktemp /tmp/A-Box-uuid-list.XXXXXX) || { rm -f -- "$uri_tmp"; return 1; }
    if ! write_full_uuid_list_to_file "$_uuid_list_tmp"; then
        rm -f -- "$uri_tmp" "$_uuid_list_tmp"
        msg "${RED}UUID list unreadable or untrusted; refusing to generate incomplete subscription.${NC}" >&2
        return 1
    fi
    if [[ "$MODE" == *'VISION'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
        while IFS= read -r client_uuid; do
            [[ -n "$client_uuid" ]] || continue
            if [[ "$client_uuid" == "${UUID:-}" ]]; then proxy_name='Vision'; else proxy_name="Vision-${client_uuid:0:8}"; fi
            url="vless://$client_uuid@$F_IP:$VLESS_PORT?encryption=none&flow=xtls-rprx-vision&security=reality&sni=$VISION_SNI_E&fp=chrome&pbk=$PUBLIC_KEY_E&sid=$SHORT_ID_E&type=tcp#$proxy_name"
            printf '%s\n' "$url" >> "$uri_tmp" || { rm -f -- "$uri_tmp" "$_uuid_list_tmp"; return 1; }
        done < "$_uuid_list_tmp"
    fi
    if [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]]; then
        while IFS= read -r client_uuid; do
            [[ -n "$client_uuid" ]] || continue
            if [[ "$client_uuid" == "${UUID:-}" ]]; then proxy_name='XHTTP'; else proxy_name="XHTTP-${client_uuid:0:8}"; fi
            url="vless://$client_uuid@$F_IP:$XHTTP_PORT?encryption=none&security=reality&sni=$XHTTP_SNI_E&fp=chrome&pbk=$PUBLIC_KEY_E&sid=$SHORT_ID_E&type=xhttp&host=$XHTTP_SNI_E&path=%2Fxhttp&mode=stream-one#$proxy_name"
            printf '%s\n' "$url" >> "$uri_tmp" || { rm -f -- "$uri_tmp" "$_uuid_list_tmp"; return 1; }
        done < "$_uuid_list_tmp"
    fi
    rm -f -- "$_uuid_list_tmp"
    # FIX: If neither VISION nor XHTTP branch ran (e.g. HY2-only or SS-only
    # deployment), no URIs were written. Do NOT install an empty subscription
    # file and claim success — report clearly instead.
    if [[ ! -s "$uri_tmp" ]]; then
        rm -f -- "$uri_tmp"
        msg "${YELLOW}[!] No subscription URIs generated: current MODE ($MODE) has no VLESS/VISION/XHTTP inbound. Subscription files were not written.${NC}" >&2
        return 1
    fi
    # A-05c-FIX: Atomic install of URI list (600). Temp file cleaned up.
    install_file_atomically "$uri_tmp" "$uri_file" 600 || { rm -f -- "$uri_tmp"; return 1; }
    rm -f -- "$uri_tmp"
    if command -v base64 >/dev/null 2>&1; then
        # A-05c-FIX: Pipe base64 through atomic writer (600). Previously: redirect
        # created 0644, then chmod 600 with || true (fail-open, window).
        ( base64 -w0 < "$uri_file" 2>/dev/null || base64 < "$uri_file" | tr -d '\n' ) \
            | write_file_atomically_from_stdin "$b64_file" 600 || return 1
    fi
    clash_file=$(write_clash_yaml 2>/dev/null || true)
    msg "${GREEN}URI list: ${uri_file}${NC}"
    [[ -f "$b64_file" ]] && msg "${GREEN}Base64 subscription: ${b64_file}${NC}"
    [[ -n "${clash_file:-}" ]] && msg "${GREEN}Clash YAML: ${clash_file}${NC}"
    if [[ "$CALLER" != 'quiet' ]]; then
        msg "${YELLOW}Host these files via HTTPS for remote import; this is not a full panel.${NC}"
        pause_return
    fi
}

# ================= Multi-user manager (fix47) =================
# Per-inbound user registries live in /etc/ddr/users.d/<core>__<tag>.json
# (600). The registry is the source of truth for who may connect;
# users_sync rewrites the core config's user list from it inside the
# usual transaction (validate -> atomic install -> restart -> rollback).
# Xray-family users carry email "<tag>/<name>", which is what the
# StatsService counters and `xray api rmu` key on.
USERS_DIR='/etc/ddr/users.d'

users_reg_file() { printf '%s/%s__%s.json' "${ABOX_USERS_DIR:-$USERS_DIR}" "$1" "$2"; }
# Rename the historical default label 'abox' to 'main' so every
# node's default user reads the same. SOCKS-type registries are
# excluded: there the name IS the login username (a credential).
users_normalize_default_name() {
    local core="$1" tag="$2" reg='' proto='' new=''
    reg=$(users_reg_file "$core" "$tag")
    [[ -f "$reg" && ! -L "$reg" ]] || return 0
    proto=$(jq -r '.protocol // ""' "$reg" 2>/dev/null) || return 0
    case "$proto" in *socks*|mixed) return 0 ;; esac
    jq -e '([.users[].name] | (index("abox") != null) and (index("main") == null))' "$reg" >/dev/null 2>&1 || return 0
    new=$(jq -c --arg tag "$tag" '.users |= map(if .name == "abox" then .name = "main" | (if .email == ($tag + "/abox") then .email = ($tag + "/main") else . end) else . end)' "$reg" 2>/dev/null) || return 0
    [[ -n "$new" ]] || return 0
    users_reg_write "$core" "$tag" "$new" >/dev/null 2>&1 || return 0
    users_sync "$core" "$tag" >/dev/null 2>&1 || true
}
# Startup sweep: normalize every registry's default label without
# waiting for the toolbox or the guard tick to visit it.
users_normalize_all_default_names() {
    local _dir="${ABOX_USERS_DIR:-${USERS_DIR:-/etc/ddr/users.d}}" _f='' _c='' _t=''
    [[ -d "$_dir" ]] || return 0
    for _f in "$_dir"/*.json; do
        [[ -f "$_f" && ! -L "$_f" ]] || continue
        _c=$(jq -r '.core // ""' "$_f" 2>/dev/null) || continue
        _t=$(jq -r '.tag // ""' "$_f" 2>/dev/null) || continue
        [[ -n "$_c" && -n "$_t" ]] && users_normalize_default_name "$_c" "$_t"
    done
    return 0
}



users_cfg_of() {
    case "$1" in
        xray) printf '%s' "${XRAY_SLOT_CFG:-/usr/local/etc/xray/config.json}" ;;
        xray-latest)
            if [[ "$(_xl_state_get mode 2>/dev/null)" == 'takeover' ]]; then
                printf '%s' "${XRAY_SLOT_CFG:-/usr/local/etc/xray/config.json}"
            else
                printf '%s' "${XRAY_LATEST_CFG:-/etc/ddr/xray-latest/config.json}"
            fi ;;
        sing-box) printf '%s' '/etc/sing-box/config.json' ;;
        hy2) printf '%s' '/etc/hysteria/config.yaml' ;;
        *) return 1 ;;
    esac
}

users_svc_of() {
    case "$1" in
        xray) printf '%s' 'xray' ;;
        xray-latest) if [[ "$(_xl_state_get mode 2>/dev/null)" == 'coexist' ]]; then printf '%s' 'xray-latest'; else printf '%s' 'xray'; fi ;;
        sing-box) printf '%s' 'sing-box' ;;
        hy2) printf '%s' 'hysteria' ;;
        *) return 1 ;;
    esac
}

users_bin_of() {
    case "$1" in
        xray) printf '%s' "${XRAY_SLOT_BIN:-/usr/local/bin/xray}" ;;
        xray-latest)
            if [[ "$(_xl_state_get mode 2>/dev/null)" == 'takeover' ]]; then
                printf '%s' "${XRAY_SLOT_BIN:-/usr/local/bin/xray}"
            else
                printf '%s' "${XRAY_LATEST_BIN:-/usr/local/bin/xray-latest}"
            fi ;;
        sing-box) printf '%s' '/usr/local/bin/sing-box' ;;
        hy2) printf '%s' '/usr/local/bin/hysteria' ;;
        *) return 1 ;;
    esac
}

users_api_port_of() {
    case "$1" in
        xray) printf '%s' '10085' ;;
        xray-latest)
            if [[ "$(_xl_state_get mode 2>/dev/null)" == 'takeover' ]]; then printf '%s' '10085'; else printf '%s' '10086'; fi ;;
        *) printf '%s' '10085' ;;
    esac
}

users_valid_name() { [[ "$1" =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]{0,23}$ ]]; }

# Atomic registry write: $1=core $2=tag $3=json-content
users_reg_write() { users_reg_write_path "$(users_reg_file "$1" "$2")" "$3"; }

# Atomic registry write to an explicit path: $1=path $2=json-content
users_reg_write_path() {
    local dest="$1" content="$2" dir='' tmp=''
    dir=$(dirname -- "$dest") || return 1
    install -d -m 700 "$dir" 2>/dev/null || return 1
    tmp=$(mktemp "$dir/.reg.XXXXXX") || return 1
    printf '%s\n' "$content" > "$tmp" || { rm -f "$tmp"; return 1; }
    jq empty "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f "$tmp"; return 1; }
    mv -f -- "$tmp" "$dest" || { rm -f "$tmp"; return 1; }
    return 0
}

# Validate + install a prepared config file with the core's own checker,
# restart its service, roll back on any failure.
# $1=core $2=cfg-path $3=new-file $4=backup-file
users_commit_cfg() {
    local core="$1" cfg="$2" newf="$3" bak="$4" bin='' svc=''
    bin=$(users_bin_of "$core") || return 1
    svc=$(users_svc_of "$core") || return 1
    case "$core" in
        xray|xray-latest)
            [[ -x "$bin" ]] || return 1
            XRAY_LOCATION_ASSET=/usr/local/share/xray "$bin" run -test -config "$newf" >/dev/null 2>&1 || return 1 ;;
        sing-box)
            [[ -x "$bin" ]] || return 1
            "$bin" check -c "$newf" >/dev/null 2>&1 || return 1 ;;
        hy2) : ;; # no offline checker; service restart is the validation
    esac
    install_file_atomically "$newf" "$cfg" 600 || return 1
    case "$core" in
        xray) prepare_abox_runtime_permissions xray >/dev/null 2>&1 || true ;;
        xray-latest) prepare_abox_runtime_read_file "$cfg" xray >/dev/null 2>&1 || true ;;
        sing-box) prepare_abox_runtime_permissions sing-box >/dev/null 2>&1 || true ;;
    esac
    if ! restart_service_soft "$svc"; then
        if [[ -n "$bak" && -f "$bak" ]]; then
            install_file_atomically "$bak" "$cfg" 600 >/dev/null 2>&1 || cp -f -- "$bak" "$cfg"
            case "$core" in
                xray) prepare_abox_runtime_permissions xray >/dev/null 2>&1 || true ;;
                xray-latest) prepare_abox_runtime_read_file "$cfg" xray >/dev/null 2>&1 || true ;;
                sing-box) prepare_abox_runtime_permissions sing-box >/dev/null 2>&1 || true ;;
            esac
            restart_service_soft "$svc" >/dev/null 2>&1 || true
        fi
        return 1
    fi
    return 0
}

# Tag retrofit for combo inbounds built before fix47 (they had no tags,
# which kept them invisible to per-tag management). Assigns tags by
# protocol/network shape only when the tag is still free.
users_xray_ensure_tags() {
    local cfg="$1" bak='' tmp=''
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    jq -e '[.inbounds[]? | select(.tag == null or .tag == "")] | length > 0' "$cfg" >/dev/null 2>&1 || return 0
    bak=$(mktemp /tmp/A-Box-utag-bak.XXXXXX) || return 1
    cp -f -- "$cfg" "$bak" || { rm -f "$bak"; return 1; }
    tmp=$(mktemp /tmp/A-Box-utag.XXXXXX) || { rm -f "$bak"; return 1; }
    mv -- "$tmp" "$tmp.json" || { rm -f "$tmp" "$bak"; return 1; }; tmp="$tmp.json"
    if ! jq '
        ([.inbounds[]?.tag | select(. != null and . != "")]) as $used
        | .inbounds |= map(
            if (.tag != null and .tag != "") then .
            elif .protocol == "vless" and ((.streamSettings.network // "tcp") == "xhttp") and ("xhttp" | IN($used[]) | not) then .tag = "xhttp"
            elif .protocol == "vless" and ("vision" | IN($used[]) | not) then .tag = "vision"
            elif .protocol == "shadowsocks" and ("ss" | IN($used[]) | not) then .tag = "ss"
            else . end)
    ' "$cfg" > "$tmp"; then rm -f "$tmp" "$bak"; return 1; fi
    if users_commit_cfg xray "$cfg" "$tmp" "$bak"; then rm -f "$tmp" "$bak"; return 0; fi
    rm -f "$tmp" "$bak"; return 1
}

users_sb_ensure_tags() {
    local cfg="$1" bak='' tmp=''
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    jq -e '[.inbounds[]? | select(.tag == null or .tag == "")] | length > 0' "$cfg" >/dev/null 2>&1 || return 0
    bak=$(mktemp /tmp/A-Box-utag-bak.XXXXXX) || return 1
    cp -f -- "$cfg" "$bak" || { rm -f "$bak"; return 1; }
    tmp=$(mktemp /tmp/A-Box-utag.XXXXXX) || { rm -f "$bak"; return 1; }
    mv -- "$tmp" "$tmp.json" || { rm -f "$tmp" "$bak"; return 1; }; tmp="$tmp.json"
    if ! jq '
        ([.inbounds[]?.tag | select(. != null and . != "")]) as $used
        | .inbounds |= map(
            if (.tag != null and .tag != "") then .
            elif .type == "vless" and ("vision" | IN($used[]) | not) then .tag = "vision"
            elif .type == "hysteria2" and ("hy2" | IN($used[]) | not) then .tag = "hy2"
            elif .type == "shadowsocks" and ("ss" | IN($used[]) | not) then .tag = "ss"
            else . end)
    ' "$cfg" > "$tmp"; then rm -f "$tmp" "$bak"; return 1; fi
    if users_commit_cfg sing-box "$cfg" "$tmp" "$bak"; then rm -f "$tmp" "$bak"; return 0; fi
    rm -f "$tmp" "$bak"; return 1
}

# ---- adoption: build a registry from the live config ----
# Shared jq: turn a raw [{name,secret,...}] list into registry users,
# sanitising/deduping names and stamping defaults.
USERS_JQ_DEDUPE='
def cleanname: (tostring | gsub("[^a-zA-Z0-9_-]"; "_") | .[0:24] | if . == "" then "main" end);
def dedupe: reduce .[] as $u ({seen:{}, out:[]};
    if .seen[$u.name] then .out += [$u + {name: ("u" + ((.out | length) + 1 | tostring))}] | .seen += {(("u" + ((.out | length) | tostring))): 1}
    else .seen += {($u.name): 1} | .out += [$u] end) | .out;
def mkusers($tag): map({
    name: ((.name // "main") | cleanname),
    secret: (.secret // ""),
    uuid: (.uuid // ""),
    flow: (.flow // ""),
    email: (if $tag != "" then ($tag + "/" + ((.name // "main") | cleanname)) else "" end),
    created: "",
    expire_at: 0, quota_gb: 0, window: "",
    disabled: false, blocked: "",
    period: "", used_up: 0, used_down: 0, last_up: 0, last_down: 0
}) | dedupe | map(.email = (if $tag != "" then ($tag + "/" + .name) else "" end))'

users_adopt() {
    local core="$1" tag="$2" outfile="${3:-}" cfg='' proto='' users='[]' ssecret='' raw=''
    cfg=$(users_cfg_of "$core") || return 1
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    case "$core" in
        xray|xray-latest)
            proto=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .protocol // ""' "$cfg" 2>/dev/null | head -1)
            [[ -n "$proto" ]] || return 1
            raw=$(jq -c --arg t "$tag" '
                .inbounds[]? | select(.tag == $t) | .settings as $st
                | if .protocol == "vless" then [$st.clients[]? | {name: (if .email then (.email | split("/") | .[1] // "main") else "main" end), secret: .id, flow: (.flow // "")}]
                  elif .protocol == "trojan" then [$st.clients[]? | {name: (if .email then (.email | split("/") | .[1] // "main") else "main" end), secret: .password}]
                  elif .protocol == "shadowsocks" then
                      (if (($st.clients // null) | type) == "array"
                       then [$st.clients[] | {name: (if .email then (.email | split("/") | .[1] // "main") else "main" end), secret: .password}]
                       else [{name: "main", secret: ($st.password // "")}] end)
                  elif .protocol == "socks" then [$st.accounts[]? | {name: (.user // "main"), secret: (.pass // "")}]
                  else [] end' "$cfg" 2>/dev/null) || return 1
            if [[ "$proto" == 'shadowsocks' ]]; then
                # clients-form SS keeps the server key separately.
                if jq -e --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.settings.clients // null | type) == "array"' "$cfg" >/dev/null 2>&1; then
                    ssecret=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .settings.password // ""' "$cfg" 2>/dev/null | head -1)
                fi
            fi
            ;;
        sing-box)
            proto=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .type // ""' "$cfg" 2>/dev/null | head -1)
            [[ -n "$proto" ]] || return 1
            raw=$(jq -c --arg t "$tag" '
                .inbounds[]? | select(.tag == $t)
                | if .type == "vless" or .type == "vmess" then [.users[]? | {name: (.name // "main"), secret: (.uuid // .password // ""), flow: (.flow // "")}]
                  elif .type == "tuic" then [.users[]? | {name: (.name // "main"), secret: (.password // ""), uuid: (.uuid // "")}]
                  elif .type == "shadowsocks" then
                      (if ((.users // null) | type) == "array" and ((.users // []) | length) > 0
                       then [.users[] | {name: (.name // "main"), secret: (.password // "")}]
                       else [{name: "main", secret: (.password // "")}] end)
                  elif .type == "mixed" or .type == "socks" then [.users[]? | {name: (.username // "main"), secret: (.password // "")}]
                  else [.users[]? | {name: (.name // "main"), secret: (.password // "")}] end' "$cfg" 2>/dev/null) || return 1
            if [[ "$proto" == 'shadowsocks' ]] && jq -e --arg t "$tag" '.inbounds[]? | select(.tag == $t) | ((.users // []) | length) > 0' "$cfg" >/dev/null 2>&1; then
                ssecret=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .password // ""' "$cfg" 2>/dev/null | head -1)
            fi
            ;;
        hy2)
            proto='hysteria2'
            raw=$(users_hy2_read_users "$cfg") || return 1
            ;;
        *) return 1 ;;
    esac
    [[ -n "$raw" ]] || raw='[]'
    users=$(printf '%s' "$raw" | jq -c --arg tag "$tag" "$USERS_JQ_DEDUPE; mkusers(\$tag)") || return 1
    local now=''
    now=$(date -u '+%Y-%m-%dT%H:%M:%SZ' 2>/dev/null || echo '')
    users=$(printf '%s' "$users" | jq -c --arg now "$now" 'map(.created = (if .created == "" then $now else .created end))') || return 1
    local reg=''
    reg=$(jq -cn --arg core "$core" --arg tag "$tag" --arg proto "$proto" --arg ss "$ssecret" --argjson users "$users" \
        '{core: $core, tag: $tag, protocol: $proto, server_secret: $ss, users: $users}') || return 1
    if [[ -n "$outfile" ]]; then users_reg_write_path "$outfile" "$reg"; else users_reg_write "$core" "$tag" "$reg"; fi
}

# Read the official Hy2 auth block into a raw users list [{name,secret}].
users_hy2_read_users() {
    local cfg="$1" block='' type='' pw='' out='[]'
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 1
    block=$(awk '/^auth:/{f=1} f && /^[^[:space:]#]/{if ($0 !~ /^auth:/) exit} f{print}' "$cfg" 2>/dev/null) || return 1
    [[ -n "$block" ]] || return 1
    type=$(printf '%s\n' "$block" | sed -n 's/^[[:space:]]*type:[[:space:]]*//p' | head -1 | tr -d '"'"'"' \r')
    if [[ "$type" == 'userpass' ]]; then
        out=$(printf '%s\n' "$block" | awk '
            /^  userpass:/{u=1; next}
            u && /^    [^[:space:]]/{line=$0; sub(/^    /, "", line);
                i=index(line, ": "); name=substr(line, 1, i-1); val=substr(line, i+2);
                printf "%s\t%s\n", name, val}
            u && /^  [^[:space:]]/{exit}')
        local list='[]' n='' v=''
        while IFS=$'\t' read -r n v; do
            [[ -n "$n" ]] || continue
            # Values are written as JSON strings; decode escapes properly.
            if [[ "$v" == '"'* ]]; then v=$(printf '%s' "$v" | jq -r . 2>/dev/null || printf '%s' "$v"); fi
            list=$(printf '%s' "$list" | jq -c --arg n "$n" --arg v "$v" '. + [{name: $n, secret: $v}]') || return 1
        done <<< "$out"
        printf '%s' "$list"
        return 0
    fi
    pw=$(printf '%s\n' "$block" | sed -n 's/^[[:space:]]*password:[[:space:]]*//p' | head -1)
    [[ -n "$pw" ]] || return 1
    # The writer json-escapes the value; decode it as a JSON string when quoted.
    if [[ "$pw" == '"'* ]]; then pw=$(printf '%s' "$pw" | jq -r . 2>/dev/null || printf '%s' "$pw"); fi
    jq -cn --arg v "$pw" '[{name: "main", secret: $v}]'
}

# Ensure a registry exists for (core, tag): adopt from the live config
# when missing, then merge in any config credentials the registry does
# not know yet (out-of-band changes) as auto-named users.
users_reg_ensure() {
    local core="$1" tag="$2" reg=''
    reg=$(users_reg_file "$core" "$tag")
    if [[ ! -f "$reg" ]]; then
        users_adopt "$core" "$tag" || return 1
        users_normalize_default_name "$core" "$tag"
        return 0
    fi
    jq -e '.users | type == "array"' "$reg" >/dev/null 2>&1 || return 1
    local scratch='' merged=''
    scratch=$(mktemp /tmp/A-Box-ureg.XXXXXX) || return 0
    if users_adopt "$core" "$tag" "$scratch" >/dev/null 2>&1 && jq -e '.users' "$scratch" >/dev/null 2>&1; then
        merged=$(jq -c --slurpfile s "$scratch" '
            . as $r | ($s[0].users // []) as $fresh
            | .users = (.users + [$fresh[] | select(.secret as $sec | [$r.users[].secret] | index($sec) | not)])
            | .server_secret = (if (.server_secret // "") == "" then ($s[0].server_secret // "") else .server_secret end)
        ' "$reg" 2>/dev/null) && [[ -n "$merged" ]] && users_reg_write "$core" "$tag" "$merged" || true
    fi
    rm -f -- "$scratch"
    users_normalize_default_name "$core" "$tag"
    return 0
}

# ---- sync: rewrite the core config's user list from the registry ----
users_sync() {
    local core="$1" tag="$2" cfg='' reg='' bak='' tmp='' enabled='' proto='' ssecret=''
    cfg=$(users_cfg_of "$core") || return 1
    reg=$(users_reg_file "$core" "$tag")
    [[ -f "$cfg" && ! -L "$cfg" && -f "$reg" ]] || return 1
    proto=$(jq -r '.protocol // ""' "$reg" 2>/dev/null) || return 1
    [[ -n "$proto" ]] || return 1
    ssecret=$(jq -r '.server_secret // ""' "$reg" 2>/dev/null)
    enabled=$(jq -c '[.users[] | select(.disabled != true and ((.blocked // "") == ""))]' "$reg" 2>/dev/null) || return 1
    bak=$(mktemp /tmp/A-Box-usync-bak.XXXXXX) || return 1
    cp -f -- "$cfg" "$bak" || { rm -f "$bak"; return 1; }
    tmp=$(mktemp /tmp/A-Box-usync.XXXXXX) || { rm -f "$bak"; return 1; }
    mv -- "$tmp" "$tmp.json" || { rm -f "$tmp" "$bak"; return 1; }; tmp="$tmp.json"
    # SS multi-user promotion: with no stored server_secret and >1
    # enabled users, the CURRENT password becomes the server key and
    # each user's secret becomes their uPSK (their link changes; the
    # menu warns about this when the second user is added).
    local eff_ss="$ssecret" promote=0 encount=0
    encount=$(printf '%s' "$enabled" | jq 'length' 2>/dev/null || echo 0)
    if [[ "$proto" == 'shadowsocks' && -z "$eff_ss" ]] && (( encount > 1 )); then
        case "$core" in
            xray|xray-latest) eff_ss=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .settings.password // ""' "$cfg" 2>/dev/null | head -1) ;;
            sing-box) eff_ss=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .password // ""' "$cfg" 2>/dev/null | head -1) ;;
            hy2) : ;;
        esac
        [[ -n "$eff_ss" ]] && promote=1
    fi
    case "$core" in
        xray|xray-latest)
            xray_ensure_stats "$cfg" "$(users_api_port_of "$core")" >/dev/null 2>&1 || true
            local flow=''
            flow=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.settings.clients[0].flow // "")' "$cfg" 2>/dev/null | head -1)
            if ! jq --arg t "$tag" --arg proto "$proto" --argjson users "$enabled" --arg flow "$flow" --arg ss "$eff_ss" '
                .inbounds |= map(if .tag == $t then
                    (if $proto == "vless" then
                        .settings.clients = [$users[] | {id: .secret, email: .email} + (if $flow != "" then {flow: $flow} else {} end)]
                     elif $proto == "trojan" then
                        .settings.clients = [$users[] | {password: .secret, email: .email}]
                     elif $proto == "shadowsocks" then
                        (if $ss != "" then
                            .settings.password = $ss
                            | .settings.clients = [$users[] | {password: .secret, email: .email}]
                         elif ($users | length) == 1 then
                            .settings.password = $users[0].secret | .settings |= del(.clients)
                         else
                            .settings.password = "AAAAAAAAAAAAAAAAAAAAAA" | .settings |= del(.clients) end)
                     elif $proto == "socks" then
                        .settings.accounts = [$users[] | {user: .name, pass: .secret}]
                     else . end)
                else . end)
            ' "$cfg" > "$tmp" 2>/dev/null; then
                rm -f "$tmp" "$bak"; return 1
            fi
            ;;
        sing-box)
            if ! jq --arg t "$tag" --arg proto "$proto" --argjson users "$enabled" --arg ss "$eff_ss" '
                .inbounds |= map(if .tag == $t then
                    (if $proto == "vless" or $proto == "vmess" then
                        .users = [$users[] | {name: .name, uuid: .secret} + (if (.flow // "") != "" then {flow: .flow} else {} end)]
                     elif $proto == "tuic" then
                        .users = [$users[] | {name: .name, uuid: .uuid, password: .secret}]
                     elif $proto == "shadowsocks" then
                        (if $ss != "" then
                            .password = $ss | .users = [$users[] | {name: .name, password: .secret}]
                         elif ($users | length) == 1 then
                            .password = $users[0].secret | del(.users)
                         else
                            .password = "AAAAAAAAAAAAAAAAAAAAAA" | del(.users) end)
                     elif $proto == "mixed" or $proto == "socks" then
                        .users = [$users[] | {username: .name, password: .secret}]
                     else
                        .users = [$users[] | {name: .name, password: .secret}] end)
                else . end)
            ' "$cfg" > "$tmp" 2>/dev/null; then
                rm -f "$tmp" "$bak"; return 1
            fi
            ;;
        hy2)
            users_hy2_write_users "$cfg" "$enabled" "$tmp" || { rm -f "$tmp" "$bak"; return 1; }
            ;;
        *) rm -f "$tmp" "$bak"; return 1 ;;
    esac
    if users_commit_cfg "$core" "$cfg" "$tmp" "$bak"; then
        rm -f "$tmp" "$bak"
        if (( promote == 1 )); then
            local regj=''
            regj=$(jq -c --arg ss "$eff_ss" '.server_secret = $ss' "$reg" 2>/dev/null) && users_reg_write "$core" "$tag" "$regj" || true
        fi
        return 0
    fi
    rm -f "$tmp" "$bak"; return 1
}

# Write a new hysteria config with the auth block replaced by $enabled
# users (JSON array). One user -> password auth; more -> userpass.
users_hy2_write_users() {
    local cfg="$1" users_json="$2" out="$3" auth_block='' count=0
    count=$(printf '%s' "$users_json" | jq 'length' 2>/dev/null || echo 0)
    if (( count == 1 )); then
        local sec=''
        sec=$(printf '%s' "$users_json" | jq -r '.[0].secret' 2>/dev/null)
        auth_block=$(printf 'auth:\n  type: password\n  password: %s' "$(json_escape "$sec")")
    elif (( count == 0 )); then
        auth_block=$(printf 'auth:\n  type: password\n  password: %s' "$(json_escape "$(openssl rand -hex 16 2>/dev/null || echo disabled)")")
    else
        local lines=''
        lines=$(printf '%s' "$users_json" | jq -r '.[] | "    " + .name + ": " + (.secret | @json)' 2>/dev/null) || return 1
        auth_block=$(printf 'auth:\n  type: userpass\n  userpass:\n%s' "$lines")
    fi
    awk -v block="$auth_block" '
        /^auth:/ { print block; skip = 1; next }
        skip && /^[^[:space:]#]/ { skip = 0 }
        skip && /^  / { next }
        skip && /^$/ { next }
        { print }
    ' "$cfg" > "$out" || return 1
    grep -q '^auth:' "$out" || return 1
    return 0
}

# ---- per-user links ----
users_link_stem() {
    local core="$1" tag="$2"
    case "$core:$tag" in
        xray:trojan-landing) printf '%s' 'trojan-xray' ;;
        sing-box:trojan-landing) printf '%s' 'trojan-sb' ;;
        xray:socks5-landing) printf '%s' 'socks5-xray' ;;
        sing-box:socks5-landing) printf '%s' 'socks5-sb' ;;
        sing-box:tuic-in) printf '%s' 'tuic' ;;
        sing-box:anytls-in) printf '%s' 'anytls' ;;
        sing-box:shadowtls-in) printf '%s' 'shadowtls' ;;
        sing-box:mixed-in|sing-box:socks-in) printf '%s' 'socks5-sb' ;;
        hy2:*) printf '%s' 'hy2' ;;
        *) printf '%s' "$tag" ;;
    esac
}

users_registered_link() {
    local stem='' f=''
    stem=$(users_link_stem "$1" "$2") || return 1
    f="${ABOX_DIR:-/etc/ddr}/standalone-links.d/${stem}.link"
    [[ -f "$f" && ! -L "$f" ]] || return 1
    sed -n '2p' "$f" | tr -d '\r'
}

users_b64url_dec() { printf '%s' "$1" | tr '_-' '/+' | awk '{l=length($0); if (l%4==2) print $0"=="; else if (l%4==3) print $0"="; else print $0}' | base64 -d 2>/dev/null; }
users_b64url_enc() { base64 -w0 2>/dev/null | tr '+/' '-_' | tr -d '='; }

# Build the connection link for one registry user.
# $1=core $2=tag $3=name -> prints link on stdout
users_link() {
    local core="$1" tag="$2" name="$3" reg='' user='' main='' proto='' ssecret=''
    reg=$(users_reg_file "$core" "$tag")
    [[ -f "$reg" ]] || return 1
    user=$(jq -c --arg n "$name" '.users[] | select(.name == $n)' "$reg" 2>/dev/null) || return 1
    [[ -n "$user" && "$user" != 'null' ]] || return 1
    main=$(jq -c '.users[] | select(.name == "main")' "$reg" 2>/dev/null)
    proto=$(jq -r '.protocol // ""' "$reg" 2>/dev/null)
    ssecret=$(jq -r '.server_secret // ""' "$reg" 2>/dev/null)
    local secret='' use_uuid=''
    secret=$(printf '%s' "$user" | jq -r '.secret // ""')
    use_uuid=$(printf '%s' "$user" | jq -r '.uuid // ""')
    [[ -n "$secret" ]] || return 1
    # Combo inbounds (either core) build from .env + live config values.
    if [[ "$tag" == 'vision' || "$tag" == 'xhttp' || "$tag" == 'ss' || "$tag" == 'hy2' ]] && [[ "$core" == 'xray' || "$core" == 'sing-box' ]]; then
        users_link_combo "$core" "$tag" "$name" "$secret" "$ssecret" "$proto"
        return $?
    fi
    local link='' msecret=''
    link=$(users_registered_link "$core" "$tag") || return 1
    [[ -n "$link" ]] || return 1
    msecret=$(printf '%s' "$main" | jq -r '.secret // ""')
    local frag="#${tag}-${name}"
    if [[ "$link" == ss://* ]]; then
        # userinfo is base64(method:credential)
        local rest="${link#ss://}" userinfo='' hostpart='' plain='' method='' eff=''
        userinfo="${rest%%@*}"; hostpart="${rest#*@}"
        hostpart="${hostpart%%#*}"
        plain=$(users_b64url_dec "$userinfo") || return 1
        method="${plain%%:*}"
        if [[ -n "$ssecret" ]]; then eff="${ssecret}:${secret}"; else eff="$secret"; fi
        printf 'ss://%s@%s%s' "$(printf '%s' "${method}:${eff}" | users_b64url_enc)" "$hostpart" "$frag"
        return 0
    fi
    # Generic userinfo substitution: scheme://userinfo@rest
    local scheme='' rest2='' userinfo2='' hostpart2=''
    scheme="${link%%://*}"; rest2="${link#*://}"
    userinfo2="${rest2%%@*}"; hostpart2="${rest2#*@}"
    hostpart2="${hostpart2%%#*}"
    local newinfo=''
    if [[ "$proto" == 'tuic' ]]; then
        local muuid=''
        muuid=$(printf '%s' "$main" | jq -r '.uuid // ""')
        if [[ "$userinfo2" == "$(urlencode "$muuid"):$(urlencode "$msecret")" || "$userinfo2" == "${muuid}:${msecret}" ]]; then
            newinfo="$(urlencode "$use_uuid"):$(urlencode "$secret")"
        else
            return 1
        fi
    elif [[ "$core" == 'hy2' ]]; then
        if [[ "$name" == 'main' ]]; then
            newinfo="$(urlencode "$secret")"
        else
            newinfo="$(urlencode "$name"):$(urlencode "$secret")"
        fi
    else
        if [[ "$userinfo2" == "$(urlencode "$msecret")" || "$userinfo2" == "$msecret" ]]; then
            newinfo="$(urlencode "$secret")"
        else
            return 1
        fi
    fi
    printf '%s://%s@%s%s' "$scheme" "$newinfo" "$hostpart2" "$frag"
    return 0
}

# Combo link builder (vision / xhttp / ss / sing-box hy2) from .env for
# shared REALITY parameters plus the live config for ports and method.
users_link_combo() {
    local core="$1" tag="$2" name="$3" secret="$4" ssecret="$5" proto="$6"
    [[ -f "${ABOX_ENV:-/etc/ddr/.env}" ]] && load_abox_env "$ABOX_ENV" 2>/dev/null || true
    local ip='' cfg='' port=''
    ip="${LINK_IP:-}"
    [[ -n "$ip" ]] || ip=$(read_cached_public_ip 2>/dev/null || true)
    [[ -n "$ip" ]] || ip=$(get_public_ip 2>/dev/null || true)
    [[ -n "$ip" ]] || ip='<server-ip>'
    cfg=$(users_cfg_of "$core") || return 1
    local pbk="${PUBLIC_KEY:-}" sid="${SHORT_ID:-}"
    case "$tag" in
        vision)
            port=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.port // .listen_port // "")' "$cfg" 2>/dev/null | head -1)
            local sni="${VISION_SNI:-${VLESS_SNI:-}}"
            printf 'vless://%s@%s:%s?encryption=none&flow=xtls-rprx-vision&security=reality&sni=%s&fp=chrome&pbk=%s&sid=%s&type=tcp#%s-%s' \
                "$(urlencode "$secret")" "$(uri_host "$ip")" "${port:-${VLESS_PORT:-443}}" "$sni" "$pbk" "$sid" "$tag" "$name" ;;
        xhttp)
            port=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.port // .listen_port // "")' "$cfg" 2>/dev/null | head -1)
            local sni="${XHTTP_SNI:-${VLESS_SNI:-}}"
            printf 'vless://%s@%s:%s?encryption=none&security=reality&sni=%s&fp=chrome&pbk=%s&sid=%s&type=xhttp&host=%s&path=%%2Fxhttp&mode=auto#%s-%s' \
                "$(urlencode "$secret")" "$(uri_host "$ip")" "${port:-${XHTTP_PORT:-8443}}" "$sni" "$pbk" "$sid" "$sni" "$tag" "$name" ;;
        ss)
            port=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.port // .listen_port // "")' "$cfg" 2>/dev/null | head -1)
            local eff=''
            if [[ -n "$ssecret" ]]; then eff="${ssecret}:${secret}"; else eff="$secret"; fi
            printf 'ss://%s@%s:%s#%s-%s' \
                "$(printf '%s' "2022-blake3-aes-128-gcm:${eff}" | users_b64url_enc)" "$(uri_host "$ip")" "${port:-${SS_PORT:-2053}}" "$tag" "$name" ;;
        hy2)
            port=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | (.listen_port // "")' "$cfg" 2>/dev/null | head -1)
            local obfs='' sni=''
            obfs=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .obfs.password // ""' "$cfg" 2>/dev/null | head -1)
            sni=$(jq -r --arg t "$tag" '.inbounds[]? | select(.tag == $t) | .tls.server_name // ""' "$cfg" 2>/dev/null | head -1)
            printf 'hysteria2://%s@%s:%s?insecure=1&sni=%s&obfs=salamander&obfs-password=%s#%s-%s' \
                "$(urlencode "$secret")" "$(uri_host "$ip")" "${port:-443}" "$sni" "$(urlencode "$obfs")" "$tag" "$name" ;;
        *) return 1 ;;
    esac
    return 0
}

# Export every enabled user's link (all registries) in the subscription
# file formats the legacy exporter produced.
users_export_all() {
    local dir='' out='' count=0 reg='' core='' tag=''
    dir="${SUBSCRIBE_DIR:-/etc/ddr/subscribe}"
    mkdir -p "$dir" 2>/dev/null || return 1
    chmod 700 "$dir" 2>/dev/null || true
    local tmp=''
    tmp=$(umask 077; mktemp "$dir/.uri-list.XXXXXX") || return 1
    for reg in "${ABOX_USERS_DIR:-$USERS_DIR}"/*.json; do
        [[ -f "$reg" ]] || continue
        core=$(jq -r '.core // ""' "$reg" 2>/dev/null); tag=$(jq -r '.tag // ""' "$reg" 2>/dev/null)
        [[ -n "$core" && -n "$tag" ]] || continue
        local uname='' link=''
        while IFS= read -r uname; do
            [[ -n "$uname" ]] || continue
            link=$(users_link "$core" "$tag" "$uname" 2>/dev/null || true)
            [[ -n "$link" ]] || continue
            printf '%s\n' "$link" >> "$tmp" && count=$((count + 1))
        done < <(jq -r '.users[] | select(.disabled != true and ((.blocked // "") == "")) | .name' "$reg" 2>/dev/null)
    done
    if (( count == 0 )); then rm -f -- "$tmp"; return 1; fi
    install_file_atomically "$tmp" "$dir/uri-list.txt" 600 || { rm -f -- "$tmp"; return 1; }
    rm -f -- "$tmp"
    if command -v base64 >/dev/null 2>&1; then
        ( base64 -w0 < "$dir/uri-list.txt" 2>/dev/null || base64 < "$dir/uri-list.txt" | tr -d '\n' ) \
            | write_file_atomically_from_stdin "$dir/subscription.base64" 600 || true
    fi
    printf '%s' "$count"
    return 0
}

# ---- menu ----
users_fmt_bytes() {
    local b="${1:-0}"
    [[ "$b" =~ ^[0-9]+$ ]] || b=0
    if (( b == 0 )); then printf '-'; return 0; fi
    awk -v b="$b" 'BEGIN { if (b < 1073741824) printf "%.1fM", b/1048576; else { v = sprintf("%.2f", b/1073741824); sub(/\.?0+$/, "", v); printf "%sG", v } }' 2>/dev/null || {
        # awk unavailable: pure-bash mirror of the same M/G format.
        if (( b < 1073741824 )); then
            local _m10=$(( (b * 10 + 524288) / 1048576 ))
            printf '%d.%dM' $(( _m10 / 10 )) $(( _m10 % 10 ))
        else
            local _g100=$(( (b * 100 + 5368709) / 1073741824 )) _frac
            _frac=$(( _g100 % 100 ))
            if (( _frac == 0 )); then printf '%dG' $(( _g100 / 100 ));
            elif (( _frac % 10 == 0 )); then printf '%d.%dG' $(( _g100 / 100 )) $(( _frac / 10 ));
            else printf '%d.%02dG' $(( _g100 / 100 )) "$_frac"; fi
        fi
    }
}
# Display width of a string: wide (CJK/fullwidth) codepoints count 2.
_str_dwidth() {
    local s="${1:-}" w=0 i=0 c='' cp=0
    for (( i=0; i<${#s}; i++ )); do
        c="${s:i:1}"
        cp=$(printf '%d' "'$c" 2>/dev/null || echo 0)
        if (( cp >= 4352 )); then w=$((w + 2)); else w=$((w + 1)); fi
    done
    printf '%d' "$w"
}


# Write a mutated registry and sync it; roll the registry back when the
# sync fails. $1=core $2=tag $3=new-json $4=old-json
users_apply_reg() {
    users_reg_write "$1" "$2" "$3" || return 1
    if ! users_sync "$1" "$2"; then
        users_reg_write "$1" "$2" "$4" >/dev/null 2>&1 || true
        return 1
    fi
    return 0
}

users_pick_user() {
    # $1=reg-file $2=prompt -> echoes the chosen name
    local reg="$1" names='' sel=''
    names=$(jq -r '.users[].name' "$reg" 2>/dev/null) || return 1
    [[ -n "$names" ]] || return 1
    local i=0 n=''
    while IFS= read -r n; do i=$((i + 1)); printf '%3d. %s\n' "$i" "$n" >&2; done <<< "$names"
    read -r -p "$2" sel || return 1
    [[ "$sel" =~ ^[0-9]+$ ]] || return 1
    printf '%s\n' "$names" | sed -n "${sel}p"
}

users_inbound_menu() {
    local core="$1" tag="$2" proto="$3" port="$4" reg=''
    reg=$(users_reg_file "$core" "$tag")
    users_reg_ensure "$core" "$tag" || { msg "${RED}$(tr_msg mu_reg_bad)${NC}"; pause_return; return 1; }
    while true; do
        clear
        msg "${BOLD}${GREEN}$(protocol_label "$core" "$tag" "$proto" 2>/dev/null || printf '%s' "$tag") · ${core} · :${port}${NC}"
        if [[ "$core" == 'sing-box' ]]; then
            msg "${YELLOW}$(tr_msg mu_note_sb)${NC}"
        fi
        msg "--------------------------------------------------------------------------------"
        local line='' name='' dis='' blk='' qu='' exp='' win='' used=''
        local idx=0
        while IFS= read -r line; do
            idx=$((idx + 1))
            name=$(printf '%s' "$line" | jq -r '.name')
            dis=$(printf '%s' "$line" | jq -r '.disabled')
            blk=$(printf '%s' "$line" | jq -r '.blocked // ""')
            qu=$(printf '%s' "$line" | jq -r '.quota_gb // 0')
            exp=$(printf '%s' "$line" | jq -r '.expire_at // 0')
            win=$(printf '%s' "$line" | jq -r '.window // ""')
            local st="$(tr_msg mu_st_ok)"
            [[ "$dis" == 'true' ]] && st="$(tr_msg mu_st_disabled)"
            [[ -n "$blk" ]] && st="$(tr_msg mu_st_blocked)($blk)"
            local expd="$(tr_msg mu_exp_forever)"
            if [[ "$exp" =~ ^[0-9]+$ ]] && (( exp > 0 )); then expd=$(date -d "@$exp" '+%Y-%m-%d' 2>/dev/null || printf '%s' "$exp"); fi
            local usd='-'
            if [[ "$core" == xray* ]]; then
                local uu='' ud=''
                uu=$(printf '%s' "$line" | jq -r '.used_up // 0'); ud=$(printf '%s' "$line" | jq -r '.used_down // 0')
                usd="$(users_fmt_bytes $((uu + ud)))"
                [[ "$qu" != '0' ]] && usd="${usd}/${qu}G"
            fi
            printf '%3d. %-18s %-12s %s:%-14s %s:%-12s %s:%s\n' "$idx" "$name" "$st" "$(tr_msg mu_col_usage)" "$usd" "$(tr_msg mu_col_expiry)" "$expd" "$(tr_msg mu_col_window)" "${win:-$(tr_msg mu_allday)}"
        done < <(jq -c '.users[]' "$reg" 2>/dev/null)
        msg "--------------------------------------------------------------------------------"
        local -a _oacts=("" "$(tr_msg mu_a1)" "$(tr_msg mu_a2)" "$(tr_msg mu_a3)" "$(tr_msg mu_a4)" "$(tr_msg mu_a5)" "$(tr_msg mu_a6)" "$(tr_msg mu_a7)" "$(tr_msg mu_a8)" "$(tr_msg mu_a9)")
        local _or=0 _oleft='' _opad=''
        for _or in 1 2 3 4 5; do
            _oleft="${_or}. ${_oacts[$_or]}"
            printf -v _opad '%*s' $(( 36 - $(_str_dwidth "$_oleft") )) ''
            (( ${#_opad} < 2 )) && _opad='  '
            if (( _or == 5 )); then
                msg "${YELLOW}${_oleft}${_opad}0. $(tr_msg mu_back_word)${NC}"
            else
                msg "${YELLOW}${_oleft}${_opad}$((_or + 5)). ${_oacts[$((_or + 5))]}${NC}"
            fi
        done
        local c=''
        read -r -p "$(tr_msg select_prompt) [0-9]: " c || return 0
        local old='' new='' nm='' now=''
        old=$(cat "$reg" 2>/dev/null) || return 1
        now=$(date +%s)
        case "$c" in
            1)
                read -r -p "$(tr_msg mu_name_prompt)" nm || continue
                users_valid_name "$nm" || { msg "${RED}$(tr_msg mu_name_bad)${NC}"; pause_return; continue; }
                jq -e --arg n "$nm" '.users[] | select(.name == $n)' "$reg" >/dev/null 2>&1 && { msg "${RED}$(tr_msg mu_name_dup)${NC}"; pause_return; continue; }
                local secret='' nuuid='' flow='' email=''
                flow=$(jq -r '.users[] | select(.name == "main") | .flow // ""' "$reg" 2>/dev/null | head -1)
                case "$proto" in
                    vless|vmess) secret=$(generate_robust_uuid) || continue ;;
                    tuic) nuuid=$(generate_robust_uuid) || continue; secret=$(rand_alnum 16) || continue ;;
                    shadowsocks) secret=$(openssl rand -base64 16 2>/dev/null | tr -d '\n\r'); [[ -n "$secret" ]] || continue ;;
                    *) secret=$(rand_alnum 16) || continue ;;
                esac
                [[ "$core" == xray* ]] && email="${tag}/${nm}"
                local created=''
                created=$(date -u '+%Y-%m-%dT%H:%M:%SZ')
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" --arg s "$secret" --arg u "$nuuid" --arg f "$flow" --arg e "$email" --arg now "$created" '
                    .users += [{name: $n, secret: $s, uuid: $u, flow: $f, email: $e, created: $now,
                                expire_at: 0, quota_gb: 0, window: "", disabled: false, blocked: "",
                                period: "", used_up: 0, used_down: 0, last_up: 0, last_down: 0}]') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then
                    msg "${GREEN}$(tr_msg mu_added): ${nm}${NC}"
                    if [[ "$proto" == 'shadowsocks' ]] && (( $(printf '%s' "$new" | jq '.users | length') == 2 )) && [[ -z "$(printf '%s' "$old" | jq -r '.server_secret // ""')" ]]; then
                        msg "${YELLOW}$(tr_msg mu_ss_warn)${NC}"
                    fi
                    local lk=''
                    lk=$(users_link "$core" "$tag" "$nm" 2>/dev/null || true)
                    [[ -n "$lk" ]] && { msg "$lk"; generate_qr "$lk"; }
                else
                    msg "${RED}$(tr_msg mu_add_fail)${NC}"
                fi
                pause_return ;;
            2)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick_del)") || { pause_return; continue; }
                [[ -n "$nm" && "$nm" != 'main' ]] || { msg "${RED}$(tr_msg mu_main_keep)${NC}"; pause_return; continue; }
                is_yes "$(printf '%s %s ? [Y/N]: ' "$(tr_msg mu_del_confirm)" "$nm")" || { msg "$(tr_msg mu_cancelled)"; pause_return; continue; }
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" '.users |= map(select(.name != $n))') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_deleted): ${nm}${NC}"; else msg "${RED}$(tr_msg mu_del_fail)${NC}"; fi
                pause_return ;;
            3)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                local gb=''
                read -r -p "$(tr_msg mu_gb_prompt)" gb || continue
                [[ "$gb" =~ ^[0-9]+$ ]] || { msg "${RED}$(tr_msg mu_int_err)${NC}"; pause_return; continue; }
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" --argjson g "$gb" '
                    .users |= map(if .name == $n then .quota_gb = $g | (if .blocked == "quota" and $g == 0 then .blocked = "" else . end) else . end)') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_quota_set): ${nm} = ${gb} GB${NC}"; else msg "${RED}$(tr_msg mu_set_fail)${NC}"; fi
                pause_return ;;
            4)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                local days=''
                read -r -p "$(tr_msg mu_days_prompt)" days || continue
                [[ "$days" =~ ^[0-9]+$ ]] || { msg "${RED}$(tr_msg mu_int_err)${NC}"; pause_return; continue; }
                local expat=0
                (( days > 0 )) && expat=$((now + days * 86400))
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" --argjson e "$expat" '
                    .users |= map(if .name == $n then .expire_at = $e | (if .blocked == "expired" and $e > 0 then .blocked = "" else . end) else . end)') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_expiry_set): ${nm}${NC}"; else msg "${RED}$(tr_msg mu_set_fail)${NC}"; fi
                pause_return ;;
            5)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                local w=''
                read -r -p "$(tr_msg mu_win_prompt)" w || continue
                if [[ -n "$w" && ! "$w" =~ ^([01][0-9]|2[0-3]):[0-5][0-9]-([01][0-9]|2[0-3]):[0-5][0-9]$ ]]; then
                    msg "${RED}$(tr_msg mu_win_bad)${NC}"; pause_return; continue
                fi
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" --arg w "$w" '
                    .users |= map(if .name == $n then .window = $w | (if .blocked == "window" then .blocked = "" else . end) else . end)') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_win_set): ${nm}${NC}"; else msg "${RED}$(tr_msg mu_set_fail)${NC}"; fi
                pause_return ;;
            6)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                local per=''
                per=$(date '+%Y-%m')
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" --arg p "$per" '
                    .users |= map(if .name == $n then .used_up = 0 | .used_down = 0 | .period = $p | (if .blocked == "quota" then .blocked = "" else . end) else . end)') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_reset_done): ${nm}${NC}"; else msg "${RED}$(tr_msg mu_reset_fail)${NC}"; fi
                pause_return ;;
            7)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                local lk=''
                lk=$(users_link "$core" "$tag" "$nm" 2>/dev/null || true)
                if [[ -n "$lk" ]]; then msg "$lk"; generate_qr "$lk"; else msg "${RED}$(tr_msg mu_nolink)${NC}"; fi
                pause_return ;;
            8)
                nm=$(users_pick_user "$reg" "$(tr_msg mu_pick)") || { pause_return; continue; }
                new=$(printf '%s' "$old" | jq -c --arg n "$nm" '
                    .users |= map(if .name == $n then .disabled = (.disabled != true) | (if .disabled == false then .blocked = "" else . end) else . end)') || continue
                if users_apply_reg "$core" "$tag" "$new" "$old"; then msg "${GREEN}$(tr_msg mu_toggled): ${nm}${NC}"; else msg "${RED}$(tr_msg mu_op_fail)${NC}"; fi
                pause_return ;;
            9)
                is_yes "$(tr_msg mu_reimport_confirm) [Y/N]: " || { msg "$(tr_msg mu_cancelled)"; pause_return; continue; }
                if users_adopt "$core" "$tag" && users_sync "$core" "$tag"; then msg "${GREEN}$(tr_msg mu_reimported)${NC}"; else msg "${RED}$(tr_msg mu_import_fail)${NC}"; fi
                pause_return ;;
            0) return 0 ;;
            *) msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1 ;;
        esac
    done
}

multi_user_menu() {
    # Bring pre-fix47 combo inbounds into per-tag management (idempotent,
    # no-op when everything is already tagged).
    local slot_cfg="${XRAY_SLOT_CFG:-/usr/local/etc/xray/config.json}"
    [[ -f "$slot_cfg" && ! -L "$slot_cfg" ]] && users_xray_ensure_tags "$slot_cfg" >/dev/null 2>&1 || true
    [[ -f /etc/sing-box/config.json && ! -L /etc/sing-box/config.json ]] && users_sb_ensure_tags /etc/sing-box/config.json >/dev/null 2>&1 || true
    setup_user_guard >/dev/null 2>&1 || true
    while true; do
        clear
        msg "${CYAN}======================================================================${NC}"
        msg "${BOLD}${GREEN}$(tr_msg mu_title)${NC}"
        msg "${CYAN}======================================================================${NC}"
        local rows='' i=0 core='' tag='' proto='' port=''
        rows=$(protocol_inventory 2>/dev/null || true)
        local -a cores=() tags=() protos=() ports=()
        while IFS=$'\t' read -r core tag proto port; do
            [[ -n "$core" && -n "$tag" ]] || continue
            [[ "$proto" == 'shadowtls' ]] && continue
            users_reg_ensure "$core" "$tag" >/dev/null 2>&1 || continue
            local cnt=0
            cnt=$(jq '.users | length' "$(users_reg_file "$core" "$tag")" 2>/dev/null || echo 0)
            i=$((i + 1))
            cores+=("$core"); tags+=("$tag"); protos+=("$proto"); ports+=("$port")
            printf '%3d. %-46s %-11s :%-6s %s %s\n' "$i" "$(protocol_label "$core" "$tag" "$proto" 2>/dev/null || printf '%s' "$tag")" "$core" "$port" "$(tr_msg mu_users_word)" "$cnt"
        done <<< "$rows"
        if (( i == 0 )); then msg "${YELLOW}$(tr_msg mu_none)${NC}"; fi
        msg "${YELLOW}  E. $(tr_msg mu_export)${NC}"
        msg "${CYAN}  0. $(tr_msg mu_back_word)${NC}"
        local c=''
        read -r -p "$(tr_msg select_prompt) [0-${i}/E]: " c || return 0
        case "$c" in
            0) return 0 ;;
            E|e)
                local n=''
                n=$(users_export_all 2>/dev/null || true)
                if [[ -n "$n" ]]; then msg "${GREEN}$(tr_msg mu_exported): ${n} (uri-list.txt / subscription.base64)${NC}"; else msg "${RED}$(tr_msg mu_export_fail)${NC}"; fi
                pause_return ;;
            ''|*[!0-9]*) msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1 ;;
            *)
                if (( c >= 1 && c <= i )); then
                    users_inbound_menu "${cores[$((c - 1))]}" "${tags[$((c - 1))]}" "${protos[$((c - 1))]}" "${ports[$((c - 1))]}"
                else
                    msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1
                fi ;;
        esac
    done
}

# ================= User guard (fix47 stage 3) =================
# Enforcement engine for per-user quota / expiry / time-window rules.
# A cron tick every 5 minutes runs a stamped copy of this script with
# --user-guard-tick: it folds Xray StatsService counters into the
# registries, re-evaluates each user's blocked state, and applies
# transitions. Xray blocks go through the hot path (config edit + API
# rmu, no restart); unblocks and sing-box/Hy2 changes use users_sync.

setup_user_guard() {
    local runner="${ABOX_DIR:-/etc/ddr}/user-guard-runner.sh"
    [[ -f "$0" && ! -L "$0" ]] || return 1
    install -d -m 700 "$(dirname -- "$runner")" 2>/dev/null || return 1
    local sha_new='' sha_old=''
    sha_new=$(sha256sum -- "$0" 2>/dev/null | awk '{print $1}')
    sha_old=$(sha256sum -- "$runner" 2>/dev/null | awk '{print $1}')
    if [[ -z "$sha_new" || "$sha_new" != "$sha_old" ]]; then
        local tmp=''
        tmp=$(mktemp "$(dirname -- "$runner")/.guard-runner.XXXXXX") || return 1
        cp -f -- "$0" "$tmp" || { rm -f -- "$tmp"; return 1; }
        chmod 700 "$tmp" || { rm -f -- "$tmp"; return 1; }
        mv -f -- "$tmp" "$runner" || { rm -f -- "$tmp"; return 1; }
    fi
    ( ABOX_DIE_HOOK=''; install_abox_cron_block USERGUARD "*/5 * * * * /bin/bash $runner --user-guard-tick >/dev/null 2>&1" ) || return 1
    return 0
}

# Query one Xray-family API for per-user counters.
# $1=binary $2=port -> JSON map: email -> {up, down}; rc 1 when down.
users_stats_snapshot() {
    local bin="$1" port="$2" out=''
    [[ -x "$bin" ]] || return 1
    out=$("$bin" api statsquery --server "127.0.0.1:$port" -pattern 'user>>>' 2>/dev/null) || return 1
    [[ -n "$out" ]] || return 1
    printf '%s' "$out" | jq -c '
        [(.stat[]? | (.name | split(">>>")) as $p | select($p[0] == "user") | {e: $p[1], d: $p[3], v: (.value // 0)})]
        | group_by(.e)
        | map({(.[0].e): {up: ([.[] | select(.d == "uplink") | .v] | add // 0),
                          down: ([.[] | select(.d == "downlink") | .v] | add // 0)}})
        | add // {}' 2>/dev/null || return 1
}

# Hot-remove one user from a RUNNING Xray-family core: first drop the
# client from the on-disk config (so a restart cannot resurrect it),
# then rmu it from the live process. No restart. rc 1 -> caller falls
# back to a full users_sync.
users_hot_remove() {
    local core="$1" tag="$2" email="$3" cfg='' bin='' reg='' proto='' tmp=''
    [[ -n "$email" ]] || return 1
    cfg=$(users_cfg_of "$core") || return 1
    bin=$(users_bin_of "$core") || return 1
    reg=$(users_reg_file "$core" "$tag")
    proto=$(jq -r '.protocol // ""' "$reg" 2>/dev/null) || return 1
    [[ -f "$cfg" && ! -L "$cfg" && -x "$bin" ]] || return 1
    tmp=$(mktemp /tmp/A-Box-uhot.XXXXXX) || return 1
    mv -- "$tmp" "$tmp.json" || { rm -f -- "$tmp"; return 1; }; tmp="$tmp.json"
    local ok=0
    case "$proto" in
        vless|trojan)
            jq --arg t "$tag" --arg e "$email" '
                .inbounds |= map(if .tag == $t then .settings.clients |= map(select(.email != $e)) else . end)
            ' "$cfg" > "$tmp" 2>/dev/null && ok=1 ;;
        shadowsocks)
            jq --arg t "$tag" --arg e "$email" '
                .inbounds |= map(if .tag == $t then
                    (if ((.settings.clients // null) | type) == "array"
                     then .settings.clients |= map(select(.email != $e))
                     else .settings.password = "AAAAAAAAAAAAAAAAAAAAAA" end)
                else . end)
            ' "$cfg" > "$tmp" 2>/dev/null && ok=1 ;;
        *) : ;;
    esac
    (( ok == 1 )) || { rm -f -- "$tmp"; return 1; }
    jq empty "$tmp" >/dev/null 2>&1 || { rm -f -- "$tmp"; return 1; }
    install_file_atomically "$tmp" "$cfg" 600 || { rm -f -- "$tmp"; return 1; }
    rm -f -- "$tmp"
    case "$core" in
        xray) prepare_abox_runtime_permissions xray >/dev/null 2>&1 || true ;;
        xray-latest) prepare_abox_runtime_read_file "$cfg" xray >/dev/null 2>&1 || true ;;
    esac
    "$bin" api rmu --server "127.0.0.1:$(users_api_port_of "$core")" -tag "$tag" "$email" >/dev/null 2>&1 || return 1
    return 0
}

# Evaluate one registry: fold counters in, recompute blocked states,
# write back, and apply transitions. All inputs are parameters so the
# policy core is directly testable.
# $1=reg $2=core $3=tag $4=now-epoch $5=period(YYYY-MM) $6=hh:mm $7=stats-json $8=have-stats(0/1)
users_guard_eval() {
    local reg="$1" core="$2" tag="$3" now_s="$4" period="$5" hhmm="$6" stats="$7" have="$8"
    local old_json='' updated=''
    old_json=$(jq -c . "$reg" 2>/dev/null) || return 0
    [[ -n "$old_json" ]] || return 0
    updated=$(jq -c --arg per "$period" --argjson now "$now_s" --arg hhmm "$hhmm" --argjson stats "${stats:-{\}}" --argjson have "$have" '
        def inwindow($w; $t):
            if $w == "" then true
            else ($w | split("-")) as $r
                 | (if $r[0] <= $r[1] then ($t >= $r[0] and $t < $r[1]) else ($t >= $r[0] or $t < $r[1]) end)
            end;
        .users |= map(
            (if $have == 1 and (.email // "") != "" and ($stats[.email] != null) then
                (if .period != $per then
                    .used_up = 0 | .used_down = 0 | .period = $per
                    | .last_up = $stats[.email].up | .last_down = $stats[.email].down
                 else
                    .used_up += (if $stats[.email].up >= (.last_up // 0) then $stats[.email].up - (.last_up // 0) else $stats[.email].up end)
                    | .used_down += (if $stats[.email].down >= (.last_down // 0) then $stats[.email].down - (.last_down // 0) else $stats[.email].down end)
                    | .last_up = $stats[.email].up | .last_down = $stats[.email].down
                 end)
             elif .period != $per then
                .used_up = 0 | .used_down = 0 | .period = $per
             else . end)
            | (if .disabled == true then .
               else
                 .blocked = (
                    if (.expire_at // 0) > 0 and $now >= .expire_at then "expired"
                    elif $have == 1 and (.quota_gb // 0) > 0 and ((.used_up + .used_down) >= (.quota_gb * 1073741824)) then "quota"
                    elif (inwindow(.window // ""; $hhmm) | not) then "window"
                    else "" end)
               end)
        )' "$reg" 2>/dev/null) || return 0
    [[ -n "$updated" && "$updated" != "$old_json" ]] || return 0
    # Transitions, by name (emails only exist on the Xray family).
    local new_blocked='' unblocked=''
    new_blocked=$(jq -rn --argjson old "$old_json" --argjson new "$updated" '
        [$new.users[] | select((.blocked // "") != "" and .disabled != true) | .name
         | select(. as $n | [$old.users[] | select(.name == $n) | (.blocked // "")] | .[0] == "")] | .[]' 2>/dev/null || true)
    unblocked=$(jq -cn --argjson old "$old_json" --argjson new "$updated" '
        [$old.users[] | select((.blocked // "") != "" and .disabled != true) | .name
         | select(. as $n | [$new.users[] | select(.name == $n) | (.blocked // "")] | .[0] == "")] | length' 2>/dev/null || echo 0)
    users_reg_write "$core" "$tag" "$updated" || return 0
    local need_sync=0
    if [[ "$core" == 'sing-box' || "$core" == 'hy2' ]]; then
        [[ -n "$new_blocked" || "$unblocked" != '0' ]] && need_sync=1
    else
        # Xray family: hot-remove each newly blocked user; sync only
        # when a hot removal fails or someone was unblocked.
        if [[ -n "$new_blocked" ]]; then
            local nm='' em=''
            while IFS= read -r nm; do
                [[ -n "$nm" ]] || continue
                em=$(jq -r --arg n "$nm" '.users[] | select(.name == $n) | .email // ""' "$reg" 2>/dev/null)
                users_hot_remove "$core" "$tag" "$em" || need_sync=1
            done <<< "$new_blocked"
        fi
        [[ "$unblocked" != '0' ]] && need_sync=1
    fi
    (( need_sync == 1 )) && { users_sync "$core" "$tag" >/dev/null 2>&1 || true; }
    return 0
}


# ---- change one deployed node's SNI (credentials untouched) ----
# Probe one inbound: echoes kind|current|key_path|crt_path|cfg_path.
_nsni_probe() {
    local core="$1" tag="$2" cfg='' j=''
    case "$core" in
        xray) cfg="${XRAY_SLOT_CFG:-/usr/local/etc/xray/config.json}" ;;
        xray-latest) cfg='/etc/ddr/xray-latest/config.json' ;;
        sing-box) cfg='/etc/sing-box/config.json' ;;
        *) return 0 ;;
    esac
    [[ -f "$cfg" && ! -L "$cfg" ]] || return 0
    if [[ "$core" == 'sing-box' ]]; then
        j=$(jq -r --arg t "$tag" '
            .inbounds[]? | select(.tag == $t) |
            if (.tls.reality.handshake.server // "") != "" then "reality-sb|" + .tls.reality.handshake.server + "||"
            elif .type == "tuic" then "tuic|" + (.tls.server_name // "") + "|" + (.tls.key_path // "") + "|" + (.tls.certificate_path // "")
            elif .type == "shadowtls" then "shadowtls|" + (.handshake.server // "") + "||"
            else "" end' "$cfg" 2>/dev/null)
    else
        j=$(jq -r --arg t "$tag" '
            .inbounds[]? | select(.tag == $t) |
            if (.streamSettings.realitySettings.serverNames[0] // "") != "" then "reality-xray|" + .streamSettings.realitySettings.serverNames[0] + "||"
            else "" end' "$cfg" 2>/dev/null)
    fi
    [[ -n "$j" ]] && printf '%s|%s' "$j" "$cfg"
    return 0
}

# Apply a new SNI: validated config edit, TUIC cert re-issue, restart,
# standalone-link and .env follow-through. Prints the updated link.
_nsni_apply() {
    local core="$1" tag="$2" kind="$3" cfg="$4" old="$5" new="$6" key="${7:-}" crt="${8:-}"
    local bak='' tmp='' bin='' filter=''
    bak=$(mktemp /tmp/A-Box-nsni-bak.XXXXXX) || return 1
    cp -a "$cfg" "$bak" || { rm -f "$bak"; return 1; }
    tmp=$(mktemp /tmp/A-Box-nsni.XXXXXX) || { rm -f "$bak"; return 1; }
    mv "$tmp" "$tmp.json"; tmp="$tmp.json"
    case "$kind" in
        reality-xray) filter='.inbounds |= map(if .tag == $t then (.streamSettings.realitySettings |= (.serverNames = [$s] | .target = (if .target then ($s + (.target | if contains(":") then sub("^[^:]*"; "") else "" end)) else .target end) | .dest = (if .dest then ($s + (.dest | if contains(":") then sub("^[^:]*"; "") else "" end)) else .dest end))) else . end)' ;;
        reality-sb) filter='.inbounds |= map(if .tag == $t then (.tls.reality.handshake.server = $s | if .tls.server_name then .tls.server_name = $s else . end) else . end)' ;;
        tuic) filter='.inbounds |= map(if .tag == $t then .tls.server_name = $s else . end)' ;;
        shadowtls) filter='.inbounds |= map(if .tag == $t then .handshake.server = $s else . end)' ;;
        *) rm -f "$tmp" "$bak"; return 1 ;;
    esac
    if ! jq --arg t "$tag" --arg s "$new" "$filter" "$cfg" > "$tmp" 2>/dev/null; then rm -f "$tmp" "$bak"; return 1; fi
    case "$core" in
        xray) bin='/usr/local/bin/xray'; if [[ -x "$bin" ]]; then "$bin" run -test -config "$tmp" >/dev/null 2>&1 || { rm -f "$tmp" "$bak"; return 1; }; fi ;;
        xray-latest) bin=$(users_bin_of xray-latest 2>/dev/null || echo /usr/local/bin/xray-latest); if [[ -x "$bin" ]]; then "$bin" run -test -config "$tmp" >/dev/null 2>&1 || { rm -f "$tmp" "$bak"; return 1; }; fi ;;
        sing-box) bin="${SB_PATH:-/usr/local/bin/sing-box}"; if [[ -x "$bin" ]]; then "$bin" check -c "$tmp" >/dev/null 2>&1 || { rm -f "$tmp" "$bak"; return 1; }; fi ;;
    esac
    cat "$tmp" > "$cfg" || { cp -a "$bak" "$cfg" 2>/dev/null; rm -f "$tmp" "$bak"; return 1; }
    rm -f "$tmp"
    if [[ "$kind" == 'tuic' && -n "$key" && -n "$crt" ]]; then
        if ! generate_self_signed_cert_atomically "$key" "$crt" "$new" >/dev/null 2>&1; then
            cp -a "$bak" "$cfg" 2>/dev/null; rm -f "$bak"; return 1
        fi
    fi
    rm -f "$bak"
    if is_service_running "$core" 2>/dev/null; then
        if is_systemd; then systemctl restart "$core" >/dev/null 2>&1 || true; else rc-service "$core" restart >/dev/null 2>&1 || true; fi
    fi
    local _ldir="${ABOX_DIR:-/etc/ddr}/standalone-links.d" _lf='' _shown=''
    local -a _cands=("${tag}.link")
    case "$tag" in
        *trojan*) if [[ "$core" == 'sing-box' ]]; then _cands+=('trojan-sb.link'); else _cands+=('trojan-xray.link'); fi ;;
        *tuic*) _cands+=('tuic.link') ;;
        *anytls*) _cands+=('anytls.link') ;;
        *shadowtls*) _cands+=('shadowtls.link') ;;
    esac
    for _lf in "${_cands[@]}"; do
        [[ -f "$_ldir/$_lf" && ! -L "$_ldir/$_lf" ]] || continue
        if grep -q 'sni=' "$_ldir/$_lf" 2>/dev/null; then
            sed -i "s|\([?&]sni=\)[^&#]*|\1${new}|g" "$_ldir/$_lf" 2>/dev/null || true
            _shown=$(cat "$_ldir/$_lf" 2>/dev/null)
        fi
    done
    local _envf="${ABOX_ENV:-/etc/ddr/.env}" _var=''
    if [[ -f "$_envf" && ! -L "$_envf" ]]; then
        while IFS= read -r _var; do
            sed -i "s|^${_var}=${old}\$|${_var}=${new}|" "$_envf" 2>/dev/null || true
        done < <(grep -oE '^[A-Z0-9_]*SNI[A-Z0-9_]*' "$_envf" 2>/dev/null | sort -u)
    fi
    [[ -n "$_shown" ]] && printf '%s' "$_shown"
    return 0
}

node_sni_menu() {
    while true; do
        clear
        msg "${CYAN}======================================================================${NC}"
        msg "${BOLD}${GREEN}$(tr_msg tb_nsni)${NC}"
        msg "${CYAN}======================================================================${NC}"
        local rows='' i=0 core='' tag='' proto='' port='' probe='' kind='' cur='' key='' crt='' cfg=''
        rows=$(protocol_inventory 2>/dev/null || true)
        local -a _cs=() _ts=() _ks=() _os=() _cfgs=()
        while IFS=$'\t' read -r core tag proto port; do
            [[ -n "$core" && -n "$tag" ]] || continue
            case "$proto" in socks|mixed|shadowsocks|hysteria2) continue ;; esac
            case "$tag" in *-ws-in) continue ;; esac
            probe=$(_nsni_probe "$core" "$tag")
            [[ -n "$probe" ]] || continue
            IFS='|' read -r kind cur key crt cfg <<< "$probe"
            [[ -n "$cur" ]] || continue
            i=$((i + 1))
            _cs+=("$core"); _ts+=("$tag"); _ks+=("$kind"); _os+=("$cur"); _cfgs+=("$cfg")
            printf '%3d. %-40s %-11s :%-6s %s: %s\n' "$i" "$(protocol_label "$core" "$tag" "$proto" 2>/dev/null || printf '%s' "$tag")" "$core" "$port" "$(tr_msg nsni_cur)" "$cur"
        done <<< "$rows"
        if (( i == 0 )); then msg "${YELLOW}$(tr_msg nsni_none)${NC}"; fi
        msg "${CYAN}  0. $(tr_msg mu_back_word)${NC}"
        local c=''
        read -r -p "$(tr_msg select_prompt) [0-${i}]: " c || return 0
        case "$c" in
            0|'') return 0 ;;
            *[!0-9]*) msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1 ;;
            *)
                if (( c >= 1 && c <= i )); then
                    local _ix=$((c - 1)) _probe2='' _k2='' _c2='' _new='' _shown=''
                    _probe2=$(_nsni_probe "${_cs[$_ix]}" "${_ts[$_ix]}")
                    IFS='|' read -r _ _ _k2 _c2 _ <<< "$_probe2"
                    printf '%s: %s\n' "$(tr_msg nsni_cur)" "${_os[$_ix]}"
                    read -r -p "$(tr_msg nsni_prompt)" _new || continue
                    _new=$(printf '%s' "$_new" | tr -d '[:space:]')
                    [[ -n "$_new" ]] || continue
                    if ! valid_sni "$_new"; then msg "${RED}$(tr_msg nsni_invalid)${NC}"; pause_return; continue; fi
                    if _shown=$(_nsni_apply "${_cs[$_ix]}" "${_ts[$_ix]}" "${_ks[$_ix]}" "${_cfgs[$_ix]}" "${_os[$_ix]}" "$_new" "$_k2" "$_c2"); then
                        msg "${GREEN}$(tr_msg nsni_done)${NC}"
                        [[ -n "$_shown" ]] && msg "${LBLW}${_shown}${NC}"
                        msg "${YELLOW}$(tr_msg nsni_warn)${NC}"
                    else
                        msg "${RED}$(tr_msg nsni_fail)${NC}"
                    fi
                    pause_return
                else
                    msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1
                fi ;;
        esac
    done
}

user_guard_tick() {
    exec 9>>/run/A-Box-user-guard.lock 2>/dev/null || return 0
    flock -n 9 || return 0
    local now_s='' period='' hhmm=''
    now_s=$(date +%s); period=$(date '+%Y-%m'); hhmm=$(date '+%H:%M')
    local core='' tag='' proto='' port=''
    while IFS=$'\t' read -r core tag proto port; do
        [[ -n "$core" && -n "$tag" && "$proto" != 'shadowtls' ]] || continue
        users_reg_ensure "$core" "$tag" >/dev/null 2>&1 || true
    done < <(protocol_inventory 2>/dev/null || true)
    local stats_xray='' have_xray=0 stats_latest='' have_latest=0
    if is_service_running xray 2>/dev/null; then
        stats_xray=$(users_stats_snapshot /usr/local/bin/xray 10085) && have_xray=1
    fi
    if [[ -n "$(_xl_state_get mode 2>/dev/null)" ]]; then
        local lbin='' lport=''
        lbin=$(users_bin_of xray-latest 2>/dev/null || true)
        lport=$(users_api_port_of xray-latest 2>/dev/null || echo 10086)
        if [[ -n "$lbin" ]] && is_service_running "$(users_svc_of xray-latest 2>/dev/null || echo xray-latest)" 2>/dev/null; then
            stats_latest=$(users_stats_snapshot "$lbin" "$lport") && have_latest=1
        fi
    fi
    local reg='' rcore='' rtag='' stats='' have=0
    for reg in "${ABOX_USERS_DIR:-$USERS_DIR}"/*.json; do
        [[ -f "$reg" ]] || continue
        rcore=$(jq -r '.core // ""' "$reg" 2>/dev/null); rtag=$(jq -r '.tag // ""' "$reg" 2>/dev/null)
        [[ -n "$rcore" && -n "$rtag" ]] || continue
        case "$rcore" in
            xray) stats="$stats_xray"; have=$have_xray ;;
            xray-latest) stats="$stats_latest"; have=$have_latest ;;
            *) stats=''; have=0 ;;
        esac
        users_guard_eval "$reg" "$rcore" "$rtag" "$now_s" "$period" "$hhmm" "$stats" "$have"
    done
    return 0
}


try_latest_cores_danger() {
    local answer targets=() t latest
    clear
    msg "${RED}${BOLD}DANGER: 尝试上游最新正式稳定版 / Try latest upstream stable release${NC}"
    msg "$(tprintf tl_body "${ABOX_XRAY_DEFAULT_VERSION}" "${ABOX_SINGBOX_DEFAULT_VERSION}" "${ABOX_HYSTERIA_DEFAULT_VERSION}")"
    msg "$(tr_msg tl_risk)"
    read -r -p "$(tr_msg tl_type_yes)" answer
    [[ "$answer" == 'YES' ]] || { msg "${YELLOW}$(tr_msg tl_cancelled)${NC}"; pause_return; return 0; }
    init_system_environment
    load_optional_abox_env_or_die
    if abox_owns_service xray && [[ -x /usr/local/bin/xray ]]; then targets+=(xray); fi
    if abox_owns_service sing-box && [[ -x /usr/local/bin/sing-box ]]; then targets+=(singbox); fi
    if abox_owns_service hysteria && [[ -x /usr/local/bin/hysteria ]]; then targets+=(hysteria); fi
    (( ${#targets[@]} > 0 )) || { msg "${YELLOW}$(tr_msg tl_no_owned)${NC}"; pause_return; return 0; }
    # Each core gets an independent transaction in a subshell.
    local failed_cores=()
    for t in "${targets[@]}"; do
        msg "${CYAN}$(tprintf tl_trying "$t")${NC}"
        if ( begin_core_upgrade_transaction "$t"
             case "$t" in
                 xray)
                     latest=$(core_latest_stable_release_ref XTLS/Xray-core 2>/dev/null || core_release_mirror_version XTLS/Xray-core) || die "$(tr_msg tl_cand_xray)"
                     msg "${YELLOW}$(tprintf tl_try_xray "$latest")${NC}"
                     ABOX_TRY_LATEST_CORE_STABLE=1 upgrade_xray_core_only ;;
                 singbox)
                     latest=$(core_latest_stable_release_ref SagerNet/sing-box 2>/dev/null || core_release_mirror_version SagerNet/sing-box) || die "$(tr_msg tl_cand_sb)"
                     msg "${YELLOW}$(tprintf tl_try_sb "$latest")${NC}"
                     ABOX_TRY_LATEST_CORE_STABLE=1 upgrade_singbox_core_only ;;
                 hysteria)
                     latest=$(core_latest_stable_release_ref HyNetworks/hysteria 2>/dev/null || core_release_mirror_version HyNetworks/hysteria) || die "$(tr_msg tl_cand_hy)"
                     msg "${YELLOW}$(tprintf tl_try_hy "$latest")${NC}"
                     ABOX_TRY_LATEST_CORE_STABLE=1 upgrade_hysteria_core_only ;;
             esac
             commit_core_upgrade_transaction ); then
            msg "${GREEN}$(tprintf tl_done_one "$t")${NC}"
        else
            msg "${YELLOW}$(tprintf tl_failed_one "$t")${NC}"
            failed_cores+=("$t")
        fi
    done
    if (( ${#failed_cores[@]} > 0 )); then
        msg "${YELLOW}$(tprintf tl_finished_fail "${failed_cores[*]}")${NC}"
    else
        msg "${GREEN}$(tr_msg tl_finished_ok)${NC}"
    fi
    pause_return
}


valid_ip_pref() {
    [[ "${1:-}" =~ ^(ipv4|ipv6|dual)$ ]]
}

read_ip_pref() {
    local v='dual'
    if [[ -r "$IP_PREF_FILE" && -f "$IP_PREF_FILE" && ! -L "$IP_PREF_FILE" ]]; then
        [[ "$(stat -c %u:%g "$IP_PREF_FILE" 2>/dev/null || true)" == '0:0' ]] || { printf 'dual\n'; return 0; }
        local _m; _m=$(stat -c %a "$IP_PREF_FILE" 2>/dev/null || echo 777)
        [[ "$_m" =~ ^[0-7]{3,4}$ ]] && (( (8#$_m & 8#022) == 0 )) || { printf 'dual\n'; return 0; }
        v=$(tr -d '[:space:]' < "$IP_PREF_FILE" 2>/dev/null || true)
    fi
    valid_ip_pref "$v" || v='dual'
    printf '%s\n' "$v"
}

save_ip_pref() {
    local v="${1:-}"
    valid_ip_pref "$v" || die "$(tr_msg ip_pref_bad)"
    ensure_abox_dir_owned "$ABOX_DIR" || die "$(tr_msg state_dir_prep)"
    write_file_atomically_from_stdin "$IP_PREF_FILE" 600 <<< "$v" || die "$(tr_msg ip_pref_write)"
}

ip_preference_menu() {
    # Submenu loop: 0/Enter returns to the parent menu.
    while true; do
    clear
    local cur c title ipv4 ipv6 dual back
    cur=$(read_ip_pref)
    case "${ABOX_LANG:-zh}" in
        en) title='IP protocol preference'; ipv4='IPv4 only (0.0.0.0 listener; prefer IPv4 share links)'; ipv6='IPv6 only (:: listener; requires working global IPv6)'; dual='Dual stack (prefer IPv6 when available, otherwise IPv4)'; back='Back' ;;
        ru) title='Предпочтение IP-протокола'; ipv4='Только IPv4 (слушатель 0.0.0.0)'; ipv6='Только IPv6 (требуется глобальный IPv6)'; dual='Два стека (IPv6 при доступности, иначе IPv4)'; back='Назад' ;;
        fa) title='ترجیح پروتکل IP'; ipv4='فقط IPv4 (نشانی شنونده 0.0.0.0)'; ipv6='فقط IPv6 (نیازمند IPv6 عمومی فعال)'; dual='دوپشته (در صورت دسترسی IPv6، وگرنه IPv4)'; back='بازگشت' ;;
        zh-tw) title='IP 協議偏好'; ipv4='僅 IPv4（監聽 0.0.0.0，分享連結優先 IPv4）'; ipv6='僅 IPv6（需要可用的全域性 IPv6）'; dual='雙棧（優先可用 IPv6，否則 IPv4）'; back='返回' ;;
        ja)
            title='IP プロトコルの設定'; ipv4='IPv4 のみ（0.0.0.0 でリッスンし、共有リンクでは IPv4 を優先）'; ipv6='IPv6 のみ（利用可能なグローバル IPv6 が必要）'; dual='デュアルスタック（IPv6 が利用可能な場合は優先し、それ以外は IPv4）'; back='戻る' ;;
        *) title='IP 协议偏好'; ipv4='仅 IPv4（监听 0.0.0.0，分享链接优先 IPv4）'; ipv6='仅 IPv6（需要可用的全局 IPv6）'; dual='双栈（优先可用 IPv6，否则 IPv4）'; back='返回' ;;
    esac
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}$title${NC}"
    msg "Current: ${YELLOW}$cur${NC}"
    msg "${YELLOW}1. $ipv4${NC}"
    msg "${YELLOW}2. $ipv6${NC}"
    msg "${YELLOW}3. $dual${NC}"
    msg "${CYAN}0. $back${NC}"
    read -r -p 'Select [0-3]: ' c || return 0
    case "$c" in
        1) save_ip_pref ipv4 ;;
        2)
            if ! has_ipv6; then
                case "${ABOX_LANG:-zh}" in
                    en) msg "${RED}No usable global IPv6 was detected; IPv6-only mode was not saved.${NC}" ;;
                    ru) msg "${RED}Рабочий глобальный IPv6 не обнаружен; режим IPv6-only не сохранён.${NC}" ;;
                    fa) msg "${RED}IPv6 عمومی قابل استفاده یافت نشد؛ حالت فقط IPv6 ذخیره نشد.${NC}" ;;
                    zh-tw) msg "${RED}系統當前無可用全域性 IPv6，未儲存僅 IPv6 模式。${NC}" ;;
                    ja)
                        msg "${RED}利用可能なグローバル IPv6 が検出されなかったため、IPv6 のみのモードは保存されませんでした。${NC}" ;;
                    *) msg "${RED}系统当前无可用全局 IPv6，未保存仅 IPv6 模式。${NC}" ;;
                esac
                pause_return; return 1
            fi
            save_ip_pref ipv6 ;;
        3) save_ip_pref dual ;;
        0) return 0 ;;
        *) msg "${RED}$(tr_msg invalid_input): $c${NC}"; sleep 1; continue ;;
    esac
    case "${ABOX_LANG:-zh}" in
        en) msg "${GREEN}Saved: $(read_ip_pref). New listener preference applies to future deployments; running nodes require redeployment or an applicable restart.${NC}" ;;
        ru) msg "${GREEN}Сохранено: $(read_ip_pref). Настройка слушателя применяется к новым узлам; существующие узлы нужно переустановить или перезапустить.${NC}" ;;
        fa) msg "${GREEN}ذخیره شد: $(read_ip_pref). این تنظیم برای استقرارهای بعدی اعمال می‌شود؛ نودهای فعال به استقرار مجدد یا راه‌اندازی مجدد نیاز دارند.${NC}" ;;
        zh-tw) msg "${GREEN}已儲存：$(read_ip_pref)。新監聽偏好對後續部署生效；已執行節點需重新部署或適當重啟。${NC}" ;;
        ja)
            msg "${GREEN}保存しました: $(read_ip_pref)。新しいリスナー設定は今後のデプロイに適用されます。稼働中のノードには再デプロイまたは適切な再起動が必要です。${NC}" ;;
        *) msg "${GREEN}已保存：$(read_ip_pref)。新监听偏好对后续部署生效；已运行节点需重新部署或适当重启。${NC}" ;;
    esac
    pause_return
    done
}
