swapfile_active_state() {
    # Return 0=active, 1=definitely inactive, 2=query failure.
    # A query failure must never be interpreted as inactivity before a
    # destructive swapfile operation.
    local output='' line
    # N-08: use swapon when available (util-linux syntax); fall back to
    # /proc/swaps when swapon is missing (BusyBox swapon lacks --show).
    if command -v swapon >/dev/null 2>&1; then
        if ! output=$(swapon --show=NAME --noheadings 2>/dev/null); then
            return 2
        fi
    elif [[ -r /proc/swaps ]]; then
        output=$(awk 'NR>1 {print $1}' /proc/swaps 2>/dev/null || true)
    else
        return 2
    fi
    while IFS= read -r line; do
        [[ "$line" == '/swapfile' ]] && return 0
    done <<< "$output"
    return 1
}

rollback_new_swap_activation_only() {
    # Used only before /etc/fstab has been modified. Never edits /etc/fstab.
    # This makes early setup failures independent of the generic rollback path,
    # which may remove A-Box swap entries from fstab.
    swapfile_active_state
    case $? in
        0) swapoff /swapfile >/dev/null 2>&1 || return 1 ;;
        1) ;;
        *) return 1 ;;
    esac
    if [[ -e /swapfile || -L /swapfile ]]; then
        rm -f -- /swapfile || return 1
    fi
    [[ ! -e /swapfile && ! -L /swapfile ]]
}

rollback_abox_new_swap() {
    local fstab_backup="${1:-}" rollback_tmp=''
    if [[ -n "$fstab_backup" && -f "$fstab_backup" && ! -L "$fstab_backup" ]]; then
        if ! cp -a "$fstab_backup" /etc/fstab; then
            msg "${RED}[!] Swap 回滚无法恢复 /etc/fstab；保留现状以避免制造更严重的不一致。${NC}" >&2
            return 1
        fi
    else
        rollback_tmp=$(mktemp /etc/.fstab.A-Box-swap-rollback.XXXXXX) || return 1
        if ! awk '
          $0 == "# A-Box swap BEGIN" {
            if (skip) { print "A-Box swap: nested BEGIN" > "/dev/stderr"; exit 2 }
            skip=1; begin_seen=1; next
          }
          $0 == "# A-Box swap END" {
            if (!skip) { print "A-Box swap: END without BEGIN" > "/dev/stderr"; exit 2 }
            skip=0; end_seen=1; next
          }
          skip {next}
          {print}
          END {
            if (skip || (begin_seen && !end_seen) || (!begin_seen && end_seen)) {
              print "A-Box swap: unbalanced BEGIN/END markers; refusing to rewrite /etc/fstab" > "/dev/stderr"
              exit 2
            }
          }
        ' /etc/fstab > "$rollback_tmp"; then
            rm -f "$rollback_tmp"
            return 1
        fi
        chmod --reference=/etc/fstab "$rollback_tmp" 2>/dev/null || chmod 644 "$rollback_tmp"
        chown --reference=/etc/fstab "$rollback_tmp" 2>/dev/null || true
        mv -f "$rollback_tmp" /etc/fstab || { rm -f "$rollback_tmp"; return 1; }
    fi
    swapfile_active_state
    case $? in
        0) swapoff /swapfile >/dev/null 2>&1 || return 1 ;;
        1) ;;
        *) return 1 ;;
    esac
    rm -f /swapfile "$ABOX_DIR/.swapfile.managed"
    [[ ! -e /swapfile && ! -e "$ABOX_DIR/.swapfile.managed" ]]
}

fstab_path_is_safe() {
    [[ -f /etc/fstab && ! -L /etc/fstab ]] || return 1
    path_owned_by_root /etc/fstab || return 1
    path_mode_has_no_group_other_write /etc/fstab || return 1
}

setup_swap_2g() {
    local fstab_tmp='' fstab_backup='' free_kib=0 created_by_abox=0
    clear
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}Swap 虚拟内存一键划拨 / Allocate 2G Swap${NC}"
    msg "${CYAN}======================================================================${NC}"
    fstab_path_is_safe || die '/etc/fstab 必须是 root 所有且不可被组/其他用户写入的普通文件，拒绝继续写入。'
    [[ ! -L /swapfile ]] || die '拒绝使用符号链接 /swapfile。'
    if [[ -e /swapfile && ! -f /swapfile ]]; then die '/swapfile 已存在但不是普通文件。'; fi
    if [[ -f /swapfile ]]; then
        [[ "$(stat -c %u:%g /swapfile 2>/dev/null || echo -1:-1)" == 0:0 ]] || die '/swapfile 不是 root:root 所有。'
        [[ "$(stat -c %a /swapfile 2>/dev/null || echo 999)" =~ ^0?600$ ]] || die '/swapfile 已存在但权限不是 0600；A-Box 不会修改非托管 Swap 文件，请先手动收紧权限。'
        msg "${YELLOW}$(tr_msg swap_exists)${NC}"
    else
        free_kib=$(df -Pk / | awk 'NR==2{print $4}')
        [[ "$free_kib" =~ ^[0-9]+$ && "$free_kib" -ge 2300000 ]] || die "根文件系统剩余空间不足 2G Swap 安全创建阈值。当前=${free_kib:-unknown}KiB。"
        if ! fallocate -l 2G /swapfile 2>/dev/null; then
            rm -f /swapfile
            dd if=/dev/zero of=/swapfile bs=1M count=2048 status=progress || { rm -f /swapfile; die 'Swap 文件创建失败。'; }
        fi
        created_by_abox=1
        chmod 600 /swapfile || { rm -f /swapfile; die 'Swap 文件权限设置失败。'; }
        chown root:root /swapfile || { rm -f /swapfile; die 'Swap 文件属主设置失败。'; }
        mkswap /swapfile >/dev/null || { rm -f /swapfile; die 'mkswap 失败。'; }
    fi
    swapfile_active_state
    case $? in
        0) ;;
        1) swapon /swapfile || { (( created_by_abox == 1 )) && rm -f -- /swapfile; die 'swapon 失败；不会写入 /etc/fstab。'; } ;;
        *) die '无法可靠判断 /swapfile 当前是否已激活；拒绝执行破坏性 Swap 操作。' ;;
    esac
    if (( created_by_abox == 1 )); then
        if ! fstab_backup=$(mktemp /etc/.fstab.A-Box-setup-backup.XXXXXX); then
            if ! rollback_new_swap_activation_only; then
                die '/etc/fstab 备份创建失败且新建 Swap 无法安全关闭；已保留 /swapfile，未修改 /etc/fstab，请立即检查并手动处理。'
            fi
            die '/etc/fstab 备份创建失败；已回滚新建 Swap，且未修改 /etc/fstab。'
        fi
        if ! cp -a /etc/fstab "$fstab_backup"; then
            rm -f -- "$fstab_backup" || true
            if ! rollback_new_swap_activation_only; then
                die '无法创建可靠的 /etc/fstab 备份且新建 Swap 无法安全关闭；已保留 /swapfile，未修改 /etc/fstab。'
            fi
            die '/etc/fstab 备份失败；已回滚新建 Swap，且未修改 /etc/fstab。'
        fi
        if ! grep -qE '^/swapfile[[:space:]]+none[[:space:]]+swap[[:space:]]+sw[[:space:]]+0[[:space:]]+0([[:space:]]|$)' /etc/fstab 2>/dev/null; then
            if ! fstab_tmp=$(mktemp /etc/.fstab.A-Box.XXXXXX); then
                if ! rollback_abox_new_swap "$fstab_backup"; then
                    msg "${RED}[!] Swap 回滚未完成；保留 fstab 备份：${fstab_backup}${NC}" >&2
                    die '/etc/fstab 临时文件创建失败且 Swap 无法安全回滚；已保留恢复材料。'
                fi
                rm -f "$fstab_backup" || true
                die '/etc/fstab 临时文件创建失败；已回滚新建 Swap。'
            fi
            if ! cat /etc/fstab > "$fstab_tmp" || ! printf '%s\n' '# A-Box swap BEGIN' '/swapfile none swap sw 0 0' '# A-Box swap END' >> "$fstab_tmp"; then
                rm -f "$fstab_tmp"
                if ! rollback_abox_new_swap "$fstab_backup"; then
                    msg "${RED}[!] Swap 回滚未完成；保留 fstab 备份：${fstab_backup}${NC}" >&2
                    die '/etc/fstab 写入失败且 Swap 无法安全回滚；已保留恢复材料。'
                fi
                rm -f "$fstab_backup" || true
                die '/etc/fstab 写入失败；已回滚新建 Swap。'
            fi
            chmod --reference=/etc/fstab "$fstab_tmp" 2>/dev/null || chmod 644 "$fstab_tmp"
            chown --reference=/etc/fstab "$fstab_tmp" 2>/dev/null || true
            if ! mv -f "$fstab_tmp" /etc/fstab; then
                rm -f "$fstab_tmp"
                if ! rollback_abox_new_swap "$fstab_backup"; then
                    msg "${RED}[!] Swap 回滚未完成；保留 fstab 备份：${fstab_backup}${NC}" >&2
                    die '/etc/fstab 原子提交失败且 Swap 无法安全回滚；已保留恢复材料。'
                fi
                rm -f "$fstab_backup" || true
                die '/etc/fstab 原子提交失败；已回滚新建 Swap。'
            fi
        fi
        if ! write_file_atomically_from_stdin "$ABOX_DIR/.swapfile.managed" 600 <<'EOF_SWAP_MARK'
A-Box managed swap v1
EOF_SWAP_MARK
        then
            if ! rollback_abox_new_swap "$fstab_backup"; then
                msg "${RED}[!] Swap ownership marker 写入失败，自动回滚未完成；保留 fstab 备份：${fstab_backup}${NC}" >&2
                die 'Swap 归属标记写入失败且自动回滚不完整；已保留恢复材料，请立即检查 /etc/fstab 与 /swapfile。'
            fi
            rm -f "$fstab_backup" || true
            die 'Swap 归属标记写入失败；已完整回滚 A-Box 新建 Swap。'
        fi
        rm -f "$fstab_backup" || die 'Swap 临时备份清理失败；Swap 已部署但安全备份残留，请检查 /etc/.fstab.A-Box-setup-backup.*。'
    elif ! grep -qE '^/swapfile[[:space:]]+none[[:space:]]+swap[[:space:]]+sw[[:space:]]+0[[:space:]]+0([[:space:]]|$)' /etc/fstab 2>/dev/null; then
        msg "${YELLOW}[!] 已存在的 /swapfile 非 A-Box 创建文件；已启用但不修改 /etc/fstab，也不会声明所有权。${NC}"
    fi
    swapon --show || true
    msg "${GREEN}$(tr_msg swap_done)${NC}"
    pause_return
}

# --- zram compressed swap -------------------------------------------
# Helper: /usr/local/sbin/abox-zram (start|stop|status); its config
# /etc/ddr/zram.conf pins SIZE_MB/ALGO so a boot-time start reproduces
# exactly what setup created. zram runs at swap priority 100, above
# the disk swapfile, so the kernel prefers it automatically.
abox_zram_write_helper() {
    write_file_atomically_from_stdin /usr/local/sbin/abox-zram 755 <<'EOF_ZRAM_HELPER'
#!/bin/bash
# A-Box zram swap helper: start|stop|status
set -u
CONF=/etc/ddr/zram.conf
SIZE_MB=512
ALGO=zstd
if [[ -f "$CONF" ]]; then . "$CONF"; fi
zram_active_devs() {
    swapon --show=NAME --noheadings 2>/dev/null | grep -E '^/dev/zram[0-9]+$' || true
}
case "${1:-}" in
    start)
        [[ -z "$(zram_active_devs)" ]] || exit 0
        modprobe zram 2>/dev/null || true
        [[ -e /sys/class/zram-control ]] || exit 1
        dev=''
        if command -v zramctl >/dev/null 2>&1; then
            dev=$(zramctl --find --size "${SIZE_MB}M" --algorithm "$ALGO" 2>/dev/null) || dev=''
        fi
        if [[ -z "$dev" ]]; then
            id=$(cat /sys/class/zram-control/hot_add 2>/dev/null) || exit 1
            [[ "$id" =~ ^[0-9]+$ ]] || exit 1
            dev="/dev/zram${id}"
            echo "$ALGO" > "/sys/block/zram${id}/comp_algorithm" 2>/dev/null || true
            echo "${SIZE_MB}M" > "/sys/block/zram${id}/disksize" || exit 1
        fi
        mkswap "$dev" >/dev/null 2>&1 || exit 1
        swapon -p 100 "$dev" || exit 1
        ;;
    stop)
        for d in $(zram_active_devs); do swapoff "$d" 2>/dev/null || exit 1; done
        if command -v zramctl >/dev/null 2>&1; then
            for b in /sys/block/zram[0-9]*; do
                [[ -e "$b" ]] || continue
                zramctl --reset "/dev/${b##*/}" >/dev/null 2>&1 || true
            done
        fi
        ;;
    status)
        zram_active_devs
        ;;
    *) echo "usage: abox-zram start|stop|status" >&2; exit 2 ;;
esac
EOF_ZRAM_HELPER
}
# Stop the zram swap and remove its persistence (unit/init script,
# helper, config). Best-effort; used by the toolbox remover, the
# virgin reset and the full uninstaller.
abox_zram_teardown() {
    if [[ -x /usr/local/sbin/abox-zram ]]; then /usr/local/sbin/abox-zram stop >/dev/null 2>&1 || true; fi
    local _init=''
    _init=$(effective_init_system)
    if [[ "$_init" == 'systemd' ]]; then
        systemctl disable abox-zram.service >/dev/null 2>&1 || true
        rm -f /etc/systemd/system/abox-zram.service 2>/dev/null || true
        systemctl daemon-reload >/dev/null 2>&1 || true
    elif [[ "$_init" == 'openrc' ]]; then
        rc-update del abox-zram default >/dev/null 2>&1 || true
        rm -f /etc/init.d/abox-zram 2>/dev/null || true
    fi
    rm -f /usr/local/sbin/abox-zram /etc/ddr/zram.conf 2>/dev/null || true
    return 0
}


setup_zram_swap() {
    clear
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}zram 压缩交换 / zram Compressed Swap${NC}"
    msg "${CYAN}======================================================================${NC}"
    if swapon --show=NAME --noheadings 2>/dev/null | grep -qE '^/dev/zram[0-9]+$'; then
        msg "${YELLOW}zram 交换已在运行：${NC}"
        swapon --show || true
        pause_return
        return 0
    fi
    modprobe zram 2>/dev/null || true
    if [[ ! -e /sys/class/zram-control ]]; then
        msg "${RED}当前内核没有 zram 支持（模块不可用）。请改用本菜单第 2 项的磁盘 Swap 文件。${NC}"
        pause_return
        return 0
    fi
    local algo='' supported='' cand=''
    if [[ -r /sys/block/zram0/comp_algorithm ]]; then
        supported=$(tr -d '[]' < /sys/block/zram0/comp_algorithm)
        for cand in zstd lz4 lzo-rle lzo; do
            if [[ " $supported " == *" $cand "* ]]; then algo="$cand"; break; fi
        done
    fi
    [[ -n "$algo" ]] || algo='lz4'
    local mem_kb=0 size_mb=512
    mem_kb=$(awk '/^MemTotal:/{print $2}' /proc/meminfo 2>/dev/null || echo 0)
    [[ "$mem_kb" =~ ^[0-9]+$ ]] || mem_kb=0
    size_mb=$(( mem_kb / 1024 / 2 ))
    (( size_mb < 256 )) && size_mb=256
    (( size_mb > 2048 )) && size_mb=2048
    if ! write_file_atomically_from_stdin /etc/ddr/zram.conf 600 <<EOF_ZRAM_CONF
SIZE_MB=${size_mb}
ALGO=${algo}
EOF_ZRAM_CONF
    then
        msg "${RED}zram 配置写入失败。${NC}"
        pause_return
        return 0
    fi
    if ! abox_zram_write_helper; then
        rm -f /etc/ddr/zram.conf
        msg "${RED}zram 辅助脚本写入失败。${NC}"
        pause_return
        return 0
    fi
    if ! /usr/local/sbin/abox-zram start; then
        rm -f /usr/local/sbin/abox-zram /etc/ddr/zram.conf
        msg "${RED}zram 启用失败（设备创建/格式化/挂载任一环节未通过），已清理。请改用磁盘 Swap 文件。${NC}"
        pause_return
        return 0
    fi
    local init=''
    init=$(effective_init_system)
    case "$init" in
        systemd)
            write_file_atomically_from_stdin /etc/systemd/system/abox-zram.service 644 <<'EOF_ZRAM_UNIT' || true
[Unit]
Description=A-Box zram compressed swap
After=local-fs.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/sbin/abox-zram start
ExecStop=/usr/local/sbin/abox-zram stop

[Install]
WantedBy=multi-user.target
EOF_ZRAM_UNIT
            systemctl daemon-reload >/dev/null 2>&1 || true
            systemctl enable abox-zram.service >/dev/null 2>&1 || msg "${YELLOW}[!] zram 已启用，但开机自启设置未成功（systemctl enable 失败），重启后需手动重新启用。${NC}"
            ;;
        openrc)
            write_file_atomically_from_stdin /etc/init.d/abox-zram 755 <<'EOF_ZRAM_RC' || true
#!/sbin/openrc-run
description="A-Box zram compressed swap"
depend() {
    need localmount
    before swap
}
start() {
    ebegin "Starting A-Box zram swap"
    /usr/local/sbin/abox-zram start
    eend $?
}
stop() {
    ebegin "Stopping A-Box zram swap"
    /usr/local/sbin/abox-zram stop
    eend $?
}
EOF_ZRAM_RC
            rc-update add abox-zram default >/dev/null 2>&1 || msg "${YELLOW}[!] zram 已启用，但开机自启设置未成功（rc-update 失败），重启后需手动重新启用。${NC}"
            ;;
        *)
            msg "${YELLOW}[!] 无法识别 init 系统：zram 本次已启用，但未设置开机自启。${NC}"
            ;;
    esac
    msg "${GREEN}zram 已启用：大小 ${size_mb}M · 算法 ${algo} · 优先级 100（高于磁盘 Swap，内核优先使用）${NC}"
    swapon --show || true
    pause_return
}

remove_zram_swap() {
    abox_zram_teardown
    msg "${GREEN}zram 已移除（A-Box 创建的配置与自启已清理）。${NC}"
    swapon --show || true
    pause_return
}

swap_status_show() {
    msg "${BOLD}${GREEN}当前交换状态 / Swap Status${NC}"
    swapon --show || true
    if command -v zramctl >/dev/null 2>&1; then zramctl || true; fi
    free -m | grep -iE '^(Mem|Swap|内存|交换)' || free -m || true
    pause_return
}

swap_menu() {
    local choice=''
    while true; do
        clear
        msg "${CYAN}======================================================================${NC}"
        msg "${BOLD}${GREEN}交换内存管理 / Swap Manager${NC}"
        msg "${CYAN}======================================================================${NC}"
        msg "${YELLOW} 1.  zram 压缩交换（推荐：内存内压缩，不占磁盘）${NC}"
        msg "${YELLOW} 2.  磁盘 Swap 文件 2G（传统方式）${NC}"
        msg "${YELLOW} 3.  查看当前交换状态${NC}"
        msg "${YELLOW} 4.  移除 zram（仅 A-Box 创建的）${NC}"
        msg "${YELLOW} 5.  移除磁盘 Swap 文件（仅 A-Box 创建的）${NC}"
        msg "${CYAN} 0.  返回${NC}"
        read -r -p "请选择 [0-5]：" choice || return 0
        case "$choice" in
            1) setup_zram_swap ;;
            2) setup_swap_2g ;;
            3) swap_status_show ;;
            4) remove_zram_swap ;;
            5)
                if [[ -f /etc/ddr/.swapfile.managed ]]; then
                    remove_abox_swap && msg "${GREEN}磁盘 Swap 文件已移除。${NC}" || msg "${RED}移除失败，请检查 /swapfile 与 /etc/fstab。${NC}"
                else
                    msg "${YELLOW}没有 A-Box 创建的磁盘 Swap 文件。${NC}"
                fi
                pause_return
                ;;
            0) return 0 ;;
            *) msg "${RED}$(tr_msg invalid_input)${NC}"; sleep 1 ;;
        esac
    done
}


# BUG-28: hoisted from remove_abox_swap(). $1 = fstab backup path.
__abox_restore_fstab_from_swap_backup() {
    local backup="$1"
    if cp -a "$backup" /etc/fstab; then
        return 0
    fi
    msg "${RED}[!] Swap 清理失败且 /etc/fstab 自动恢复也失败；保留恢复备份：${backup}${NC}" >&2
    return 1
}
remove_abox_swap() {
    [[ -f "$ABOX_DIR/.swapfile.managed" && ! -L "$ABOX_DIR/.swapfile.managed" ]] || return 0
    grep -Fxq 'A-Box managed swap v1' "$ABOX_DIR/.swapfile.managed" 2>/dev/null || return 1
    fstab_path_is_safe || return 1
    local tmp backup swap_active=0 swap_state=1
    if [[ -f /swapfile && ! -L /swapfile ]]; then
        swapfile_active_state
        swap_state=$?
        case "$swap_state" in
            0) swap_active=1 ;;
            1) ;;
            *) return 1 ;;
        esac
    fi
    tmp=$(mktemp /etc/.fstab.A-Box-remove.XXXXXX) || return 1
    backup=$(mktemp /etc/.fstab.A-Box-backup.XXXXXX) || { rm -f "$tmp"; return 1; }
    cp -a /etc/fstab "$backup" || { rm -f "$tmp" "$backup"; return 1; }
    awk '
      $0 == "# A-Box swap BEGIN" {
        if (skip) { print "A-Box swap: nested BEGIN" > "/dev/stderr"; exit 2 }
        skip=1; begin_seen=1; next
      }
      $0 == "# A-Box swap END" {
        if (!skip) { print "A-Box swap: END without BEGIN" > "/dev/stderr"; exit 2 }
        skip=0; end_seen=1; next
      }
      skip {next}
      {print}
      END {
        if (skip || (begin_seen && !end_seen) || (!begin_seen && end_seen)) {
          print "A-Box swap: unbalanced BEGIN/END markers; refusing to rewrite /etc/fstab" > "/dev/stderr"
          exit 2
        }
      }
    ' /etc/fstab > "$tmp" || { rm -f "$tmp" "$backup"; return 1; }
    chmod --reference=/etc/fstab "$tmp" 2>/dev/null || chmod 644 "$tmp"
    chown --reference=/etc/fstab "$tmp" 2>/dev/null || true
    mv -f "$tmp" /etc/fstab || { rm -f "$tmp" "$backup"; return 1; }


    if (( swap_active == 1 )); then
        if ! swapoff /swapfile; then
            __abox_restore_fstab_from_swap_backup "$backup" || return 1
            rm -f "$backup" || true
            return 1
        fi
    fi
    if [[ -f /swapfile && ! -L /swapfile ]]; then
        if ! rm -f /swapfile; then
            __abox_restore_fstab_from_swap_backup "$backup" || return 1
            msg "${YELLOW}[!] /swapfile 删除失败；已恢复 /etc/fstab，保留现有 Swap 文件与所有权标记。${NC}" >&2
            rm -f "$backup" || true
            return 1
        fi
    fi
    if ! rm -f "$ABOX_DIR/.swapfile.managed"; then
        __abox_restore_fstab_from_swap_backup "$backup" || return 1
        msg "${YELLOW}[!] Swap 所有权标记删除失败；已恢复 /etc/fstab，保留恢复状态。${NC}" >&2
        rm -f "$backup" || true
        return 1
    fi
    rm -f "$backup" || return 1
}

redact_secrets_stream() {
    if command -v python3 >/dev/null 2>&1; then
        python3 - 3<&0 <<'PY_REDACT'
import json
import os
import re
import sys

text = os.fdopen(3, "r", encoding="utf-8", errors="replace").read()
secret = re.compile(
    r"(?:^|[_-])(uuid|private.?key|public.?key|short.?ids?|fingerprint|password|passwd|token|secret|api.?key|authorization|cookie|ss_pass|hy2_pass|hy2_obfs)(?:$|[_-])",
    re.I,
)
link = re.compile(r"(?i)\b(?:vless|hysteria2|hy2|ss)://\S+")
inline_authorization = re.compile(
    r"(?i)(\b(?:authorization|proxy-authorization)\s*[:=]\s*)(?:Bearer\s+\S+|Basic\s+\S+|\S+)"
)
inline_cookie = re.compile(r"(?i)(\b(?:cookie|set-cookie)\s*[:=]\s*)[^\r\n]+")
inline_secret_assignment = re.compile(
    r"(?i)([\"']?\b(?:uuid|private.?key|public.?key|short.?ids?|fingerprint|password|passwd|token|secret|api.?key|ss_pass|hy2_pass|hy2_obfs)\b[\"']?\s*[:=]\s*)([\"']?)[^,;\s}\"']+\2"
)


def redact_text(value):
    value = link.sub("***CLIENT_LINK_REDACTED***", value)
    value = inline_authorization.sub(r"\1***REDACTED***", value)
    value = inline_cookie.sub(r"\1***REDACTED***", value)
    value = inline_secret_assignment.sub(r'\1"***REDACTED***"', value)
    return value


# A-05b-FIX: UUID regex for "id" key check (Xray clients[].id holds UUIDs).
uuid_val = re.compile(r"^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$")


def walk(value):
    if isinstance(value, dict):
        return {
            key: ("***REDACTED***" if (secret.search(str(key)) or (str(key).lower() == "id" and isinstance(item, str) and uuid_val.match(item))) else walk(item))
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [walk(item) for item in value]
    if isinstance(value, str):
        return redact_text(value)
    return value


try:
    parsed = json.loads(text)
except Exception:
    text = re.sub(
        r"(?im)^(UUID|PUBLIC_KEY|SHORT_ID|HY2_CERT_SHA256_FP|HY2_CERT_PUBKEY_SHA256_B64|SS_PASS|HY2_PASS|HY2_OBFS|HY2_ACME_DNS_CF_API_TOKEN)=.*$",
        r"\1=***REDACTED***",
        text,
    )
    text = re.sub(
        r"(?i)(\b(?:authorization|proxy-authorization)\s*:\s*)(?:bearer\s+[^\s,;}]+|basic\s+[^\s,;}]+|[^\s,;}]+)",
        r'\1***REDACTED***',
        text,
    )
    text = re.sub(
        r"(?i)(\b(?:cookie|set-cookie)\s*:\s*)[^\r\n]+",
        r'\1***REDACTED***',
        text,
    )
    text = re.sub(
        r"(?i)([\"']?(?:uuid|private.?key|public.?key|short.?ids?|fingerprint|password|passwd|token|secret|api.?key|authorization|cookie)[\"']?\s*[:=]\s*)([\"']?)[^,}\s\"']+\2",
        r'\1"***REDACTED***"',
        text,
    )
    sys.stdout.write(link.sub("***CLIENT_LINK_REDACTED***", text))
else:
    json.dump(walk(parsed), sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write("\n")
PY_REDACT
    else
        sed -E \
            -e 's/(UUID|SS_PASS|HY2_PASS|HY2_OBFS|HY2_ACME_DNS_CF_API_TOKEN|PUBLIC_KEY|SHORT_ID)=.*/\1=***REDACTED***/Ig' \
            -e 's/((Authorization|Proxy-Authorization)[[:space:]]*:[[:space:]]*)(Bearer|Basic)[[:space:]]+[^,;[:space:]}"]+/\1\3 ***REDACTED***/Ig' \
            -e 's/((Authorization|Proxy-Authorization)[[:space:]]*:[[:space:]]*)[^,;[:space:]}"]+/\1***REDACTED***/Ig' \
            -e 's/((Cookie|Set-Cookie)[[:space:]]*:[[:space:]]*)[^,}[:cntrl:]"]+/\1***REDACTED***/Ig' \
            -e 's/^([[:space:]]*(Authorization|Proxy-Authorization)[[:space:]]*:[[:space:]]*).*/\1***REDACTED***/Ig' \
            -e 's/^([[:space:]]*(Cookie|Set-Cookie)[[:space:]]*:[[:space:]]*).*/\1***REDACTED***/Ig' \
            -e 's/([" ]?(UUID|SS_PASS|HY2_PASS|HY2_OBFS|PRIVATE_KEY|PUBLIC_KEY|SHORT_ID|HY2_CERT_SHA256_FP|HY2_CERT_PUBKEY_SHA256_B64|privateKey|private_key|publicKey|shortId|fingerprint|password|passwd|token|secret|api[_-]?key|authorization|cookie)[" ]?[[:space:]]*[:=][[:space:]]*[" ]?)[^,}[:space:]["]+/\1***REDACTED***/Ig' \
            -e 's/(vless|hysteria2|hy2|ss):\/\/[^[:space:]]+/***CLIENT_LINK_REDACTED***/Ig'
    fi
}

write_redacted_file() {
    local src="$1" dst="$2"
    [[ -r "$src" ]] || return 0
    mkdir -p "$(dirname "$dst")" || return 1
    redact_secrets_stream < "$src" > "$dst" 2>/dev/null || { rm -f -- "$dst"; return 1; }
    [[ -s "$dst" ]] || { rm -f -- "$dst"; return 1; }
}

validate_abox_cron_file() {
    local file="$1"
    [[ -f "$file" && ! -L "$file" ]] || return 1
    python3 - "$file" <<'PY_ABOX_CRON'
import sys
from pathlib import Path
lines=Path(sys.argv[1]).read_text(encoding='utf-8',errors='strict').splitlines()
# A-06-FIX: Accept BOTH formats (writes only produce new format).
# Old format must still validate for backward compat (existing hosts + v3 backups).
allowed={
 'PROBE':{
  '* * * * * /bin/bash /etc/ddr/socket_probe.sh >/dev/null 2>&1',
  '* * * * * /usr/bin/flock -n /run/A-Box-probe-cron.lock /bin/bash /etc/ddr/socket_probe.sh >/dev/null 2>&1',
 },
 'GEO':{
  '0 3 * * 1 /bin/bash /etc/ddr/geo_update.sh >/dev/null 2>&1',
  '0 3 * * 1 /usr/bin/flock -n /run/A-Box-geo-cron.lock /bin/bash /etc/ddr/geo_update.sh >/dev/null 2>&1',
 },
 'TRAFFIC':{
  '* * * * * /bin/bash /etc/ddr/traffic_monitor.sh >/dev/null 2>&1',
 },
}
i=0; seen=set()
while i < len(lines):
    if not lines[i]: i+=1; continue
    if not (lines[i].startswith('# A-Box ') and lines[i].endswith(' BEGIN')): raise SystemExit(1)
    name=lines[i][8:-6]
    if name not in allowed or name in seen or i+2 >= len(lines): raise SystemExit(1)
    if lines[i+1] not in allowed[name] or lines[i+2] != f'# A-Box {name} END': raise SystemExit(1)
    seen.add(name); i+=3
PY_ABOX_CRON
}

collect_abox_cron() {
    local all err extracted
    all=$(umask 077; mktemp /tmp/A-Box-cron-all.XXXXXX) || return 1
    err=$(umask 077; mktemp /tmp/A-Box-cron-err.XXXXXX) || { rm -f "$all"; return 1; }
    extracted=$(umask 077; mktemp /tmp/A-Box-cron-extract.XXXXXX) || { rm -f "$all" "$err"; return 1; }
    if LC_ALL=C crontab -l > "$all" 2> "$err"; then :
    elif grep -Eqi 'no crontab|no crontab for' "$err"; then : > "$all"
    else rm -f "$all" "$err" "$extracted"; return 1
    fi
    awk '
      /^# A-Box (PROBE|GEO|TRAFFIC) BEGIN$/ {inblock=1}
      inblock {print}
      /^# A-Box (PROBE|GEO|TRAFFIC) END$/ {inblock=0}
      END {if (inblock) exit 1}
    ' "$all" > "$extracted" || { rm -f "$all" "$err" "$extracted"; return 1; }
    validate_abox_cron_file "$extracted" || { rm -f "$all" "$err" "$extracted"; return 1; }
    local cat_rc=0
    cat "$extracted" || cat_rc=$?
    rm -f "$all" "$err" "$extracted"
    return "$cat_rc"
}

read_crontab_to_file() {
    local out="$1" err
    [[ -n "$out" ]] || return 1
    err=$(umask 077; mktemp /tmp/A-Box-crontab-error.XXXXXX) || return 1
    if LC_ALL=C crontab -l > "$out" 2> "$err"; then
        rm -f -- "$err"
        return 0
    elif grep -Eqi 'no crontab|no crontab for' "$err"; then
        : > "$out"
        rm -f -- "$err"
        return 0
    fi
    rm -f -- "$err"
    return 1
}

strip_abox_cron_blocks_from_file() {
    local input="$1" output="$2" name="${3:-}"
    [[ -f "$input" && ! -L "$input" && -n "$output" ]] || return 1
    awk -v wanted="$name" '
      BEGIN { skip=0; seen_wanted=0 }
      {
        if (wanted != "" && $0 == "# A-Box " wanted " BEGIN") { skip=1; seen_wanted=seen_wanted+1; next }
        if (wanted != "" && $0 == "# A-Box " wanted " END") { if (!skip) exit 1; skip=0; next }
        if (wanted == "" && $0 ~ /^# A-Box (PROBE|GEO|TRAFFIC) BEGIN$/) { skip=1; next }
        if (wanted == "" && $0 ~ /^# A-Box (PROBE|GEO|TRAFFIC) END$/) { if (!skip) exit 1; skip=0; next }
        if (skip) next
        print
      }
      END { if (skip) exit 1; if (wanted != "" && seen_wanted > 1) exit 1 }
    ' "$input" > "$output" || return 1
}

commit_crontab_if_unchanged() {
    local snapshot="$1" candidate="$2" live rc=0
    [[ -f "$snapshot" && ! -L "$snapshot" && -f "$candidate" && ! -L "$candidate" ]] || return 1
    live=$(mktemp) || return 1
    if ! read_crontab_to_file "$live"; then rm -f -- "$live"; return 1; fi
    if ! cmp -s -- "$snapshot" "$live"; then
        rm -f -- "$live"
        printf '%s\n' 'A-Box cron update aborted: crontab changed concurrently; no overwrite was attempted.' >&2
        return 2
    fi
    rm -f -- "$live"
    crontab "$candidate" >/dev/null 2>&1 || rc=1
    return "$rc"
}

install_abox_cron_block() {
    local name="$1" line="$2" current tmp
    [[ -n "$name" && -n "$line" ]] || return 1
    current=$(mktemp) || die 'crontab 当前内容临时文件创建失败。'
    tmp=$(mktemp) || { rm -f -- "$current"; die 'crontab 临时文件创建失败。'; }
    if ! read_crontab_to_file "$current"; then
        rm -f -- "$current" "$tmp"
        die '无法读取现有 crontab；为避免覆盖用户任务，已中止。'
    fi
    if ! strip_abox_cron_blocks_from_file "$current" "$tmp" "$name"; then
        rm -f -- "$current" "$tmp"
        die "现有 crontab 中的 A-Box ${name} 区块格式异常；为避免破坏计划任务，已中止。"
    fi
    {
        printf '%s\n' "# A-Box ${name} BEGIN"
        printf '%s\n' "$line"
        printf '%s\n' "# A-Box ${name} END"
    } >> "$tmp" || { rm -f -- "$current" "$tmp"; die 'crontab 临时内容写入失败。'; }
    local commit_rc=0
    commit_crontab_if_unchanged "$current" "$tmp" || commit_rc=$?
    if (( commit_rc != 0 )); then
        rm -f -- "$current" "$tmp"
        if (( commit_rc == 2 )); then die 'crontab 在提交前发生并发修改；已中止以保护外部任务。'; fi
        die 'crontab 写入失败；原有 crontab 未被覆盖。'
    fi
    rm -f -- "$current" "$tmp"
}

remove_abox_cron_block() {
    local name="$1" current tmp rc=0
    [[ -n "$name" ]] || return 1
    current=$(mktemp) || die 'crontab 当前内容临时文件创建失败。'
    tmp=$(mktemp) || { rm -f -- "$current"; die 'crontab 临时文件创建失败。'; }
    if ! read_crontab_to_file "$current"; then
        rm -f -- "$current" "$tmp"
        return 1
    fi
    if ! strip_abox_cron_blocks_from_file "$current" "$tmp" "$name"; then
        rm -f -- "$current" "$tmp"
        return 1
    fi
    commit_crontab_if_unchanged "$current" "$tmp" || rc=$?
    rm -f -- "$current" "$tmp"
    return "$rc"
}

remove_all_abox_cron_blocks() {
    local current tmp rc=0
    current=$(mktemp) || die 'crontab 当前内容临时文件创建失败。'
    tmp=$(mktemp) || { rm -f -- "$current"; die 'crontab 临时文件创建失败。'; }
    if ! read_crontab_to_file "$current"; then
        rm -f -- "$current" "$tmp"
        return 1
    fi
    if ! strip_abox_cron_blocks_from_file "$current" "$tmp"; then
        rm -f -- "$current" "$tmp"
        return 1
    fi
    commit_crontab_if_unchanged "$current" "$tmp" || rc=$?
    rm -f -- "$current" "$tmp"
    return "$rc"
}

service_enabled_state_value() {
    local srv="$1" state output rc
    if [[ "${INIT_SYS:-}" == systemd ]] && systemd_available; then
        output=$(systemctl show -p UnitFileState --value "$srv" 2>/dev/null) || return 1
        state="$output"
        case "$state" in
            enabled|enabled-runtime|indirect|disabled) printf '%s\n' "$state" ;;
            *) return 1 ;;
        esac
        return 0
    elif [[ "${INIT_SYS:-}" == openrc ]]; then
        command -v rc-update >/dev/null 2>&1 || return 1
        output=$(rc-update show default 2>/dev/null) || return 1
        if grep -Eq "(^|[[:space:]])${srv//[^a-zA-Z0-9_.@+-]/}([[:space:]]|$)" <<< "$output"; then
            printf '1\n'
        else
            printf '0\n'
        fi
        return 0
    fi
    return 1
}

managed_service_state_value() {
    local srv="$1" active=0 enabled_state enabled=0 output active_state rc
    if [[ "${INIT_SYS:-}" == systemd ]] && systemd_available; then
        output=$(systemctl show -p ActiveState --value "$srv" 2>/dev/null) || return 1
        active_state="$output"
        case "$active_state" in
            active) active=1 ;;
            inactive|failed|dead|exited) active=0 ;;
            *) return 1 ;;
        esac
        enabled_state=$(service_enabled_state_value "$srv") || return 1
        case "$enabled_state" in
            enabled|enabled-runtime|indirect) enabled=1 ;;
            disabled) enabled=0 ;;
            *) return 1 ;;
        esac
    elif [[ "${INIT_SYS:-}" == openrc ]] && command -v rc-service >/dev/null 2>&1; then
        rc-service "$srv" status >/dev/null 2>&1
        rc=$?
        case "$rc" in
            0) active=1 ;;
            3|16|32) active=0 ;;
            *) return 1 ;;
        esac
        enabled_state=$(service_enabled_state_value "$srv") || return 1
        case "$enabled_state" in
            1) enabled=1 ;;
            0) enabled=0 ;;
            *) return 1 ;;
        esac
    else
        return 1
    fi
    printf '%s|%s|%s\n' "$srv" "$active" "$enabled"
}

capture_managed_service_state() {
    local out="$1" srv
    : > "$out" || return 1
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        managed_service_state_value "$srv" >> "$out" || return 1
    done
}


append_managed_service_state_entry() {
    local source="$1" dest="$2" srv="$3" line
    [[ -r "$source" && -f "$source" && ! -L "$source" ]] || return 1
    line=$(awk -F'|' -v target="$srv" '$1 == target {print; found=1; exit} END {if (!found) exit 1}' "$source") || return 1
    printf '%s\n' "$line" >> "$dest"
}

_apply_managed_service_state_file() {
    local state_file="${1:-}" expected_file="${2:-}" line srv active enabled extra seen_srvs="|"
    [[ -r "$state_file" && -f "$state_file" && ! -L "$state_file" ]] || return 1
    [[ "$(stat -c %u:%g "$state_file" 2>/dev/null || true)" == 0:0 ]] || return 1
    local mode
    mode=$(stat -c %a "$state_file" 2>/dev/null) || return 1
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#077) == 0 )) || return 1
    if [[ -n "$expected_file" ]]; then
        validate_services_state_file "$expected_file" || return 1
        [[ "$(stat -c %u:%g "$expected_file" 2>/dev/null || true)" == 0:0 ]] || return 1
        mode=$(stat -c %a "$expected_file" 2>/dev/null) || return 1
        [[ "$mode" =~ ^[0-7]{3,4}$ ]] && (( (8#$mode & 8#077) == 0 )) || return 1
        [[ "$(awk -F'|' '{print $1}' "$state_file" | sort)" == "$(awk -F'|' '{print $1}' "$expected_file" | sort)" ]] || return 1
    fi

    # Preflight the complete expected post-state before changing any service.
    # A mismatch means another actor changed shared service state; never overwrite
    # that state with an A-Box rollback snapshot.
    if [[ -n "$expected_file" ]]; then
        while IFS= read -r line || [[ -n "$line" ]]; do
            [[ -z "$line" ]] && continue
            IFS='|' read -r srv _ _ extra <<< "$line"
            [[ -z "${extra:-}" ]] || return 1
            local expected_line current_state
            expected_line="$line"
            current_state=$(managed_service_state_value "$srv") || return 2
            [[ "$current_state" == "$expected_line" ]] || return 2
        done < "$expected_file"
    fi

    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ -z "$line" ]] && continue
        IFS='|' read -r srv active enabled extra <<< "$line"
        [[ -z "${extra:-}" ]] || return 1
        case "$srv" in
            xray|sing-box|hysteria) ;;
            *) return 1 ;;
        esac
        [[ "$active" =~ ^[01]$ && "$enabled" =~ ^[01]$ ]] || return 1
        case "$seen_srvs" in *"|$srv|"*) return 1 ;; esac
        seen_srvs+="$srv|"
        abox_owns_service "$srv" || return 1

        if [[ -n "$expected_file" ]]; then
            local expected_state_before
            expected_state_before=$(awk -F'|' -v target="$srv" '$1 == target {print; found=1; exit} END {if (!found) exit 1}' "$expected_file") || return 2
            local current_state_before
            current_state_before=$(managed_service_state_value "$srv") || return 2
            [[ "$current_state_before" == "$expected_state_before" ]] || return 2
        fi

        local restored_state restored_srv restored_active restored_enabled restored_extra
        if [[ "${INIT_SYS:-}" == systemd ]]; then
            systemctl daemon-reload >/dev/null 2>&1 || return 1
            if [[ "$enabled" == 1 ]]; then
                systemctl enable "$srv" >/dev/null 2>&1 || return 1
            else
                systemctl disable "$srv" >/dev/null 2>&1 || return 1
            fi
            if [[ "$active" == 1 ]]; then
                systemctl start "$srv" >/dev/null 2>&1 || systemctl restart "$srv" >/dev/null 2>&1 || return 1
            else
                systemctl stop "$srv" >/dev/null 2>&1 || return 1
            fi
        elif [[ "${INIT_SYS:-}" == openrc ]]; then
            if [[ "$enabled" == 1 ]]; then
                rc-update add "$srv" default >/dev/null 2>&1 || return 1
            else
                if rc-update show default 2>/dev/null | grep -Eq "(^|[[:space:]])${srv}([[:space:]]|$)"; then
                    rc-update del "$srv" default >/dev/null 2>&1 || return 1
                fi
            fi
            if [[ "$active" == 1 ]]; then
                rc-service "$srv" start >/dev/null 2>&1 || rc-service "$srv" restart >/dev/null 2>&1 9>&- 10>&- || return 1
            else
                rc-service "$srv" stop >/dev/null 2>&1 || return 1
            fi
        else
            return 1
        fi
        restored_state=$(managed_service_state_value "$srv") || return 1
        IFS='|' read -r restored_srv restored_active restored_enabled restored_extra <<< "$restored_state"
        [[ -z "${restored_extra:-}" && "$restored_srv" == "$srv" && "$restored_active" == "$active" && "$restored_enabled" == "$enabled" ]] || return 1
    done < "$state_file"
}

restore_managed_service_state() {
    local state_file="${1:-}" expected_file="${2:-}" tx_dir before_file post_file line srv before after rc=0
    [[ -r "$state_file" && -f "$state_file" && ! -L "$state_file" ]] || return 1
    validate_services_state_file "$state_file" || return 1
    tx_dir=$(mktemp -d /run/A-Box-service-restore.XXXXXX) || return 1
    chmod 700 "$tx_dir" || { rm -rf -- "$tx_dir"; return 1; }
    before_file="$tx_dir/before.state"; post_file="$tx_dir/post.state"
    : > "$before_file" || { rm -rf -- "$tx_dir"; return 1; }
    while IFS='|' read -r srv _active _enabled extra; do
        [[ -n "$srv" ]] || continue
        [[ -z "${extra:-}" ]] || { rm -rf -- "$tx_dir"; return 1; }
        before=$(managed_service_state_value "$srv" 2>/dev/null) || { rm -rf -- "$tx_dir"; return 1; }
        printf '%s\n' "$before" >> "$before_file" || { rm -rf -- "$tx_dir"; return 1; }
    done < "$state_file"
    chmod 600 "$before_file" || { rm -rf -- "$tx_dir"; return 1; }

    if _apply_managed_service_state_file "$state_file" "$expected_file"; then
        rm -rf -- "$tx_dir" || return 1
        return 0
    else
        rc=$?
    fi

    # The low-level applier may have changed a prefix of services before a later
    # command failed. Capture the exact observable intermediate state; if any
    # query fails, preserve the recovery snapshot instead of guessing.
    : > "$post_file" || { printf '%s\n' "A-Box service restore failed; recovery state preserved at $tx_dir" >&2; return 1; }
    while IFS='|' read -r srv _active _enabled extra; do
        [[ -n "$srv" ]] || continue
        after=$(managed_service_state_value "$srv" 2>/dev/null) || { printf '%s\n' "A-Box service restore failed; state query unavailable, recovery state preserved at $tx_dir" >&2; return 1; }
        printf '%s\n' "$after" >> "$post_file" || { printf '%s\n' "A-Box service restore failed; recovery state preserved at $tx_dir" >&2; return 1; }
    done < "$state_file"
    chmod 600 "$post_file" || { printf '%s\n' "A-Box service restore failed; recovery state preserved at $tx_dir" >&2; return 1; }
    if cmp -s -- "$before_file" "$post_file"; then
        # No service state changed; avoid needlessly restarting/stopping a stack
        # when the original operation failed before its first effective mutation.
        rm -rf -- "$tx_dir" || return 1
        return "$rc"
    fi

    # Roll back only if the live state still equals the captured intermediate state.
    # _apply_managed_service_state_file performs this precondition check before mutation.
    if ! _apply_managed_service_state_file "$before_file" "$post_file"; then
        printf '%s\n' "A-Box service restore rollback incomplete or conflicted; recovery state preserved at $tx_dir" >&2
        return 1
    fi
    rm -rf -- "$tx_dir" || return 1
    return "$rc"
}

extract_abox_iptables_rules() {
    local snapshot="$1" mode="${2:-all}"
    awk -v mode="$mode" '''
      /^\*/ {table=$0; next} /^COMMIT$/ {next}
      /^-A / {
        base=($0 ~ /--comment "?A-Box-[0-9]+(:[0-9]+)?-(tcp|udp)"?([ \t\r]|$)/)
        wl=($0 ~ /--comment "?A-Box-[0-9]+-(tcp|udp)-WL6?"?([ \t\r]|$)/)
        drop=($0 ~ /--comment "?A-Box-[0-9]+-(tcp|udp)-DROP6?"?([ \t\r]|$)/)
        hop=($0 ~ /--comment "?A-Box-HY2-HOP"?([ \t\r]|$)/)
        owned=(base || wl || drop || hop)
        special=(wl || drop || hop)
        if ((mode=="all" && owned) || special) {
          if (table!=emitted) {if (emitted!="") print "COMMIT"; print table; emitted=table}
          print
        }
      }
      END {if (emitted!="") print "COMMIT"}
    ''' "$snapshot"
}

capture_abox_iptables_snapshot() {
    local out="$1" family="${2:-4}" cmd all
    [[ "$family" == 6 ]] && cmd=ip6tables-save || cmd=iptables-save
    if ! command -v "$cmd" >/dev/null 2>&1; then
        [[ "$family" == 6 ]] && ! host_has_usable_ipv6 || return 1
        : > "$out"
        return 0
    fi
    all=$(mktemp) || return 1
    if ! "$cmd" > "$all" 2>/dev/null; then
        rm -f "$all"
        if [[ "$family" == 6 ]] && ! host_has_usable_ipv6; then
            : > "$out"
            return 0
        fi
        return 1
    fi
    extract_abox_iptables_rules "$all" all > "$out" || { rm -f "$all"; return 1; }
    rm -f "$all"
}

restore_abox_iptables_snapshot() {
    local snapshot="$1" family="${2:-4}" mode="${3:-all}" cmd tmp
    [[ "$family" == 6 ]] && ! host_has_usable_ipv6 && return 0
    [[ -s "$snapshot" ]] || return 0
    [[ "$family" == 6 ]] && cmd=ip6tables-restore || cmd=iptables-restore
    tmp=$(mktemp) || return 1
    extract_abox_iptables_rules "$snapshot" "$mode" > "$tmp" || { rm -f "$tmp"; return 1; }
    if grep -q '^\*' "$tmp"; then
        command -v "$cmd" >/dev/null 2>&1 || { rm -f "$tmp"; return 1; }
        "$cmd" -w --noflush < "$tmp" >/dev/null 2>&1 || "$cmd" --noflush < "$tmp" >/dev/null 2>&1 || { rm -f "$tmp"; return 1; }
    fi
    rm -f "$tmp"
}

backup_sidecar_safe() {
    local file="$1" uid gid mode
    [[ -f "$file" && ! -L "$file" ]] || return 1
    uid=$(stat -c %u "$file" 2>/dev/null) || return 1
    gid=$(stat -c %g "$file" 2>/dev/null) || return 1
    mode=$(stat -c %a "$file" 2>/dev/null) || return 1
    [[ "$uid" == 0 && "$gid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    (( (8#$mode & 8#077) == 0 ))
}

write_private_sidecar() {
    local dest="$1" value="$2" dir tmp
    [[ "$dest" == /* ]] || return 1
    path_parent_chain_safe "$dest" || return 1
    dir=$(dirname "$dest")
    [[ -d "$dir" && ! -L "$dir" ]] || return 1
    [[ "$(stat -c %u:%g "$dir" 2>/dev/null || true)" == 0:0 ]] || return 1
    path_mode_has_no_group_other_write "$dir" || return 1
    [[ ! -L "$dest" ]] || return 1
    if [[ -e "$dest" ]] && path_is_mountpoint "$dest"; then return 1; fi
    tmp=$(umask 077; mktemp "$dir/.A-Box-sidecar.XXXXXX") || return 1
    printf '%s\n' "$value" > "$tmp" || { rm -f -- "$tmp"; return 1; }
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$dest" || { rm -f -- "$tmp"; return 1; }
}

ensure_backup_auth_key() {
    local key tmp
    if [[ -e "$ABOX_BACKUP_KEY" || -L "$ABOX_BACKUP_KEY" ]]; then
        backup_sidecar_safe "$ABOX_BACKUP_KEY" || return 1
        IFS= read -r key < "$ABOX_BACKUP_KEY" || return 1
        [[ "$key" =~ ^[A-Fa-f0-9]{64}$ ]]
        return
    fi
    ensure_abox_dir_owned "$ABOX_DIR"
    tmp=$(umask 077; mktemp "$ABOX_DIR/.backup-hmac-key.XXXXXX") || return 1
    key=$(openssl rand -hex 32 2>/dev/null) || { rm -f -- "$tmp"; return 1; }
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ ]] || { rm -f -- "$tmp"; return 1; }
    printf '%s\n' "$key" > "$tmp" || { rm -f -- "$tmp"; return 1; }
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$ABOX_BACKUP_KEY" || { rm -f -- "$tmp"; return 1; }
}

backup_checksum_write() {
    local archive="$1" hash
    [[ -f "$archive" && ! -L "$archive" ]] || return 1
    hash=$(sha256sum "$archive" 2>/dev/null | awk '{print $1}')
    [[ "$hash" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    write_private_sidecar "${archive}.sha256" "$hash  $(basename "$archive")"
}

backup_checksum_verify() {
    local archive="$1" sidecar="${2:-${1}.sha256}" expected actual extra
    [[ -f "$archive" && ! -L "$archive" ]] || return 1
    backup_sidecar_safe "$sidecar" || return 2
    read -r expected extra < "$sidecar" || return 1
    [[ "$expected" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    actual=$(sha256sum "$archive" 2>/dev/null | awk '{print $1}')
    [[ "${actual,,}" == "${expected,,}" ]]
}

backup_auth_write() {
    local archive="$1" key mac
    ensure_backup_auth_key || return 1
    IFS= read -r key < "$ABOX_BACKUP_KEY" || return 1
    mac=$(openssl dgst -sha256 -mac HMAC -macopt "hexkey:${key}" "$archive" 2>/dev/null | awk '{print $NF}')
    [[ "$mac" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    write_private_sidecar "${archive}.hmac" "$mac  $(basename "$archive")"
}

backup_auth_verify() {
    local archive="$1" sidecar="${2:-${1}.hmac}" key expected actual extra
    [[ -f "$archive" && ! -L "$archive" ]] || return 1
    backup_sidecar_safe "$ABOX_BACKUP_KEY" || return 2
    backup_sidecar_safe "$sidecar" || return 2
    IFS= read -r key < "$ABOX_BACKUP_KEY" || return 1
    read -r expected extra < "$sidecar" || return 1
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ && "$expected" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    actual=$(openssl dgst -sha256 -mac HMAC -macopt "hexkey:${key}" "$archive" 2>/dev/null | awk '{print $NF}')
    [[ "${actual,,}" == "${expected,,}" ]]
}

backup_auth_verify_with_key_file() {
    local archive="$1" sidecar="$2" key_file="$3" key expected actual extra
    [[ -f "$archive" && ! -L "$archive" ]] || return 1
    backup_sidecar_safe "$sidecar" || return 1
    backup_sidecar_safe "$key_file" || return 1
    IFS= read -r key < "$key_file" || return 1
    read -r expected extra < "$sidecar" || return 1
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ && "$expected" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    actual=$(openssl dgst -sha256 -mac HMAC -macopt "hexkey:${key}" "$archive" 2>/dev/null | awk '{print $NF}')
    [[ "${actual,,}" == "${expected,,}" ]]
}

backup_key_fingerprint() {
    local key_file="$1" key
    backup_sidecar_safe "$key_file" || return 1
    IFS= read -r key < "$key_file" || return 1
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    printf '%s' "${key,,}" | sha256sum | awk '{print $1}'
}

install_recovery_backup_key() {
    local key_file="$1" tmp key
    [[ ! -e "$ABOX_BACKUP_KEY" && ! -L "$ABOX_BACKUP_KEY" ]] || return 1
    backup_sidecar_safe "$key_file" || return 1
    IFS= read -r key < "$key_file" || return 1
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ ]] || return 1
    ensure_abox_dir_owned "$ABOX_DIR"
    tmp=$(umask 077; mktemp "$ABOX_DIR/.backup-hmac-import.XXXXXX") || return 1
    printf '%s\n' "$key" > "$tmp" || { rm -f -- "$tmp"; return 1; }
    chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    chmod 600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    mv -f -- "$tmp" "$ABOX_BACKUP_KEY" || { rm -f -- "$tmp"; return 1; }
}

prepare_backup_auth_for_manual_restore() {
    local archive="$1" rc fingerprint answer
    # A-05a: Prefer the separated key in /root/A-Box-backup-keys/; fall back to
    # the archive-adjacent sidecar only if the separated key is absent.
    # (Sidecar-first defeated the separation trust model.)
    local hmac="${archive}.hmac" recovery="/root/A-Box-backup-keys/$(basename "$archive").key"
    # A-05a: Only fall back to sidecar if separated key is entirely absent
    # (not merely unreadable). A present-but-broken separated key must fail closed.
    if [[ ! -e "$recovery" && ! -L "$recovery" ]]; then
        recovery="${archive}.key"
    fi
    if backup_auth_verify "$archive" "$hmac"; then return 0; else rc=$?; fi
    # Never replace an existing trust key automatically. A mismatch may mean
    # the user selected a foreign or malicious backup.
    if [[ -e "$ABOX_BACKUP_KEY" || -L "$ABOX_BACKUP_KEY" ]]; then
        return "$rc"
    fi
    backup_auth_verify_with_key_file "$archive" "$hmac" "$recovery" || return 1
    fingerprint=$(backup_key_fingerprint "$recovery") || return 1
    if [[ -n "${ABOX_BACKUP_KEY_SHA256_ALLOWLIST:-}" ]]; then
        sha256_in_allowlist "$fingerprint" "$ABOX_BACKUP_KEY_SHA256_ALLOWLIST" || return 1
    else
        [[ -t 0 ]] || return 1
        msg "${YELLOW}[!] 此备份需要导入独立保存的恢复密钥。密钥指纹: ${fingerprint}${NC}"
        msg "${YELLOW}[!] 持有归档、HMAC 与恢复密钥的人可以构造受该密钥认证的 root 恢复内容；只应导入你自己保管的密钥。${NC}"
        read -r -p '输入 IMPORT-RECOVERY-KEY 以导入并继续: ' answer
        [[ "$answer" == 'IMPORT-RECOVERY-KEY' ]] || return 130
    fi
    install_recovery_backup_key "$recovery" || return 1
    backup_auth_verify "$archive" "$hmac"
}


export_backup_recovery_key() {
    local dest="${1:-}" key fingerprint
    [[ $EUID -eq 0 ]] || die '导出备份恢复密钥需要 root。'
    [[ -n "$dest" ]] || die '用法: --export-backup-key /path/on/separate-medium/A-Box-recovery.key'
    [[ "$dest" == /* ]] || die '恢复密钥导出路径必须是绝对路径。'
    [[ ! -e "$dest" && ! -L "$dest" ]] || die "拒绝覆盖现有恢复密钥文件: $dest"
    ensure_backup_auth_key || die '无法创建或读取备份认证密钥。'
    IFS= read -r key < "$ABOX_BACKUP_KEY" || die '恢复密钥读取失败。'
    [[ "$key" =~ ^[A-Fa-f0-9]{64}$ ]] || die '恢复密钥格式非法。'
    write_private_sidecar "$dest" "$key" || die '恢复密钥导出失败；目标目录必须为 root 所有且不可被组/其他用户写入。'
    fingerprint=$(backup_key_fingerprint "$dest") || die '恢复密钥指纹计算失败。'
    msg "${GREEN}[*] Recovery key exported:${NC} $dest"
    msg "${GREEN}[*] Key fingerprint (SHA256):${NC} $fingerprint"
    msg "${YELLOW}[!] Store this key separately from backup archives. Anyone holding both can authenticate modified archives.${NC}"
}

validate_legacy_backup_archive() {
    local archive="$1"
    [[ -s "$archive" ]] || return 1
    python3 - "$archive" <<'PY_LEGACY_VALIDATE'
import posixpath, stat, sys, tarfile
fn=sys.argv[1]; max_members=10000; max_file=512*1024*1024; max_total=1024*1024*1024
allowed_prefixes=(
 'root/etc/ddr','root/usr/local/bin/sb','root/usr/local/bin/xray','root/usr/local/bin/sing-box','root/usr/local/bin/hysteria',
 'root/usr/local/etc/xray','root/usr/local/share/xray','root/etc/sing-box','root/etc/hysteria','root/etc/logrotate.d/A-Box',
 'root/etc/fail2ban/filter.d/A-Box.conf','root/etc/fail2ban/jail.d/A-Box.local','root/etc/systemd/system/xray.service',
 'root/etc/systemd/system/sing-box.service','root/etc/systemd/system/hysteria.service','root/etc/init.d/xray','root/etc/init.d/sing-box',
 'root/etc/init.d/hysteria','meta/metadata.txt','meta/cron.abox.txt','meta/iptables.snapshot','meta/ip6tables.snapshot')
def allowed(n):
 if n in {'root','root/etc','root/usr','root/usr/local','root/usr/local/bin','root/usr/local/etc','root/usr/local/share','root/etc/logrotate.d','root/etc/fail2ban','root/etc/fail2ban/filter.d','root/etc/fail2ban/jail.d','root/etc/systemd','root/etc/systemd/system','root/etc/init.d','root/etc/ddr','meta'}: return True
 prefix='root/etc/ddr/'
 if n.startswith(prefix):
  rel=n[len(prefix):]
  if '/' in rel or not rel: return False
  exact={'.env','.firewall-native.rules','.lang','.desired_state','.traffic-block-state','.A-Box-owner','.public_ip.cache','.backup-hmac.key','.runtime.lock','.managed-core-files.tsv','.ip-pref','.dns-state','.timezone-state','.fast-mode','.mirror-prefer','.extra-uuids','A-Box.sh','socket_probe.sh','geo_update.sh','traffic_monitor.sh','firewall_restore.sh','iptables.v4','iptables.v6','A-Box-sni-full.tsv','A-Box-sni-mini.tsv'}
  return rel in exact or rel.startswith('.deps.v')
 return any(n==x or n.startswith(x+'/') for x in allowed_prefixes if x!='root/etc/ddr')
try: tf=tarfile.open(fn,'r:gz')
except Exception: raise SystemExit(1)
members=tf.getmembers(); seen=set(); total=0
if len(members)>max_members: raise SystemExit(1)
for m in members:
 raw=m.name
 while raw.startswith('./'): raw=raw[2:]
 n=posixpath.normpath(raw)
 if n in ('','.'): continue
 if raw.startswith('/') or n=='..' or n.startswith('../') or not allowed(n): raise SystemExit(1)
 if n in seen and not m.isdir(): raise SystemExit(1)
 seen.add(n)
 if m.issym() or m.islnk() or m.ischr() or m.isblk() or m.isfifo() or m.isdev(): raise SystemExit(1)
 if not (m.isfile() or m.isdir()) or m.uid!=0 or m.gid!=0: raise SystemExit(1)
 mode=m.mode & 0o7777
 # R-01: Allow sticky (0o1000) for acme dir 1770; reject only setuid/setgid (0o6000).
 if mode & 0o6000 or mode & 0o022: raise SystemExit(1)
 if m.isfile():
  if m.size<0 or m.size>max_file: raise SystemExit(1)
  total+=m.size
  if total>max_total: raise SystemExit(1)
if 'root/etc/ddr' not in seen or 'meta/metadata.txt' not in seen: raise SystemExit(1)
if 'meta/manifest.version' in seen: raise SystemExit(1)
PY_LEGACY_VALIDATE
}

convert_legacy_backup_archive() {
    local selected="$1" out_dir="${2:-$(dirname "$1")}" work root out answer unit srv path
    [[ -f "$selected" && ! -L "$selected" ]] || die 'Legacy backup path is invalid.'
    if [[ -f "${selected}.sha256" && ! -L "${selected}.sha256" ]]; then
        backup_checksum_verify "$selected" "${selected}.sha256" || die 'Legacy backup SHA256 verification failed.'
    else
        [[ -t 0 ]] || die 'Legacy backup has no checksum and conversion is non-interactive.'
        confirm_yes_no 'Legacy backup has no trusted checksum. Import anyway? [Y/N]: ' || return 130
    fi
    validate_legacy_backup_archive "$selected" || die 'Legacy backup archive safety validation failed.'
    work=$(mktemp -d /tmp/A-Box-legacy-import.XXXXXX) || die 'Legacy conversion temp directory failed.'
    chmod 700 "$work"
    python3 - "$selected" "$work" <<'PY_LEGACY_EXTRACT'
import os, pathlib, tarfile, sys
src,dst=sys.argv[1:]; base=pathlib.Path(dst).resolve()
with tarfile.open(src,'r:gz') as tf:
 for m in tf.getmembers():
  name=m.name
  while name.startswith('./'): name=name[2:]
  if not name or name=='.': continue
  target=(base/name).resolve()
  if base not in target.parents and target!=base: raise SystemExit(1)
  if m.isdir(): target.mkdir(parents=True,exist_ok=True); os.chmod(target,m.mode & 0o777)
  elif m.isfile():
   target.parent.mkdir(parents=True,exist_ok=True)
   f=tf.extractfile(m)
   if f is None: raise SystemExit(1)
   with open(target,'wb') as out:
    while True:
     chunk=f.read(1024*1024)
     if not chunk: break
     out.write(chunk)
   os.chmod(target,m.mode & 0o777)
  else: raise SystemExit(1)
PY_LEGACY_EXTRACT
    root="$work/root"
    rm -rf -- "$root$ABOX_DIR/backups" "$root$ABOX_DIR/diagnostics" "$root$ABOX_DIR/preflight"
    rm -f -- "$root$ABOX_DIR/A-Box.sh" "$root$ABOX_DIR/.backup-hmac.key" "$root$ABOX_DIR/.runtime.lock" \
        "$root$ABOX_DIR/socket_probe.sh" "$root$ABOX_DIR/geo_update.sh" "$root$ABOX_DIR/traffic_monitor.sh" "$root$ABOX_DIR/firewall_restore.sh" \
        "$root$ABOX_DIR/iptables.v4" "$root$ABOX_DIR/iptables.v6" "$root$ABOX_DIR/.managed-core-files.tsv" "$root$ABOX_DIR/.public_ip.cache"
    find "$root$ABOX_DIR" -maxdepth 1 -type f -name '.deps.v*' -delete 2>/dev/null || true
    install -d -m 700 "$root$ABOX_DIR" "$work/meta" || { rm -rf "$work"; die 'Legacy conversion directory normalization failed.'; }
    printf '%s\n' 'A-Box managed directory v1' > "$root$ABOX_DIR/.A-Box-owner"
    chmod 600 "$root$ABOX_DIR/.A-Box-owner"
    # A-04 fix: Never trust executable binaries, OpenRC scripts, or arbitrary systemd directives
    # inside an unauthenticated legacy archive. Strip all binaries/units/auxiliary executables;
    # only import validated state/config/certs, and require binaries/units to be re-deployed cleanly.
    rm -rf -- "$root/usr/local/bin" "$root/etc/systemd" "$root/etc/init.d" "$root/etc/conf.d" \
        "$root/etc/fail2ban" "$root/etc/logrotate.d" "$root/etc/sysctl.d" \
        "$root/etc/security" "$root/etc/modules-load.d"
    if [[ -f "$root$ABOX_DIR/.env" ]]; then
        chown root:root "$root$ABOX_DIR/.env" && chmod 600 "$root$ABOX_DIR/.env"
        load_abox_env "$root$ABOX_DIR/.env" || { rm -rf "$work"; die 'Legacy .env failed strict semantic validation.'; }
    else
        rm -rf "$work"; die 'Legacy backup is missing /etc/ddr/.env.'
    fi
    local _legacy_cfg_dir
    for _legacy_cfg_dir in "$root/usr/local/etc/xray" "$root/etc/sing-box" "$root/etc/hysteria"; do
        if [[ -d "$_legacy_cfg_dir" && ! -L "$_legacy_cfg_dir" ]]; then
            find "$_legacy_cfg_dir" -type d -exec chmod 700 {} + 2>/dev/null || true
            find "$_legacy_cfg_dir" -type f -exec chmod 600 {} + 2>/dev/null || true
        fi
    done
    printf 'iptables\n' > "$work/meta/firewall.backend"
    : > "$work/meta/services.state"
    : > "$work/meta/managed-paths.txt"
    [[ -f "$work/meta/cron.abox.txt" ]] || : > "$work/meta/cron.abox.txt"
    validate_abox_cron_file "$work/meta/cron.abox.txt" || { rm -rf "$work"; die 'Legacy cron block is not compatible with the strict importer.'; }
    [[ -f "$work/meta/iptables.snapshot" ]] || : > "$work/meta/iptables.snapshot"
    [[ -f "$work/meta/ip6tables.snapshot" ]] || : > "$work/meta/ip6tables.snapshot"
    printf 'iptables\n' > "$work/meta/firewall.backend"
    { managed_auxiliary_paths; printf '%s\n' \
        /usr/local/bin/xray /usr/local/etc/xray /usr/local/share/xray /etc/systemd/system/xray.service /etc/init.d/xray /etc/conf.d/xray \
        /usr/local/bin/sing-box /etc/sing-box /etc/systemd/system/sing-box.service /etc/init.d/sing-box /etc/conf.d/sing-box \
        /usr/local/bin/hysteria /etc/hysteria /etc/systemd/system/hysteria.service /etc/init.d/hysteria /etc/conf.d/hysteria; } | \
        while IFS= read -r path; do [[ -e "$root$path" ]] && printf '%s\n' "$path"; done | awk 'NF && !seen[$0]++' > "$work/meta/managed-paths.txt"
    local legacy_aux_paths=''
    legacy_aux_paths=$(managed_auxiliary_paths) || { rm -rf "$work"; die 'Legacy auxiliary path enumeration failed.'; }
    while IFS= read -r path; do
        [[ -e "$root$path" ]] || continue
        auxiliary_content_is_abox_managed "$root$path" "$path" || { rm -rf "$work"; die "Legacy auxiliary path fingerprint rejected: $path"; }
        if ! grep -Fxq '# Managed by A-Box' "$root$path" 2>/dev/null; then
            if head -n 1 "$root$path" | grep -q '^#!'; then sed -i '1a# Managed by A-Box' "$root$path"; else sed -i '1i# Managed by A-Box' "$root$path"; fi
        fi
    done <<< "$legacy_aux_paths"
    printf '%s\n' 'A-Box backup manifest v3' > "$work/meta/manifest.version"
    printf '\nConverted by %s from legacy archive: %s\n' "$ABOX_BUILD" "$(basename "$selected")" >> "$work/meta/metadata.txt"
    create_backup_manifest "$work" "$work/meta/manifest.sha256" || { rm -rf "$work"; die 'Converted manifest creation failed.'; }
    install -d -m 700 "$out_dir" || { rm -rf "$work"; die 'Legacy conversion output directory failed.'; }
    out="$out_dir/$(basename "${selected%.tar.gz}")-v3-imported.tar.gz"
    [[ ! -e "$out" && ! -L "$out" ]] || { rm -rf "$work"; die "Converted backup already exists: $out"; }
    tar -C "$work" -czf "$out" root meta || { rm -rf "$work"; rm -f "$out"; die 'Converted backup archive creation failed.'; }
    chmod 600 "$out"
    validate_backup_archive "$out" || { rm -rf "$work"; rm -f "$out"; die 'Converted backup failed v3 structure validation.'; }
    backup_checksum_write "$out" && backup_auth_write "$out" || { rm -rf "$work"; rm -f "$out" "${out}.sha256" "${out}.hmac"; die 'Converted backup authentication failed.'; }
    rm -rf "$work"
    msg "${GREEN}[*] Legacy backup converted safely:${NC} $out"
    msg "${YELLOW}[*] Services are imported as stopped; review configuration before starting them.${NC}"
}


validate_backup_archive() {
    local archive="$1"
    [[ -s "$archive" ]] || return 1
    command -v python3 >/dev/null 2>&1 || return 1
    # UID/GID numbers stored in a backup are source-host metadata. The archive
    # is authenticated separately; restore-time ownership is normalized to the
    # target host's dedicated runtime accounts before any service starts.
    python3 - "$archive" <<'PY_VALIDATE'
import posixpath,stat,sys,tarfile
fn=sys.argv[1]
MAX_MEMBERS=10000
MAX_FILE=512*1024*1024
MAX_TOTAL=1024*1024*1024
SB_DIR='root/etc/sing-box'
HY_DIR='root/etc/hysteria'
HY_ACME=HY_DIR + '/acme'
XRAY_DIR='root/usr/local/etc/xray'
XRAY_CFG='root/usr/local/etc/xray/config.json'
sb_gid=None
hy_uid=None
hy_gid=None
xray_gid=None
try: tf=tarfile.open(fn,'r:gz')
except Exception: raise SystemExit(1)
seen=set(); total=0
members=tf.getmembers()
if len(members)>MAX_MEMBERS: raise SystemExit(1)
for m in members:
    raw=m.name
    if '\x00' in raw or raw.startswith('/'): raise SystemExit(1)
    while raw.startswith('./'): raw=raw[2:]
    n=posixpath.normpath(raw)
    if n in ('','.'): continue
    if n=='..' or n.startswith('../') or n.split('/',1)[0] not in ('root','meta'): raise SystemExit(1)
    if n in seen and not m.isdir(): raise SystemExit(1)
    seen.add(n)
    # Backup contents are copied regular files/directories only.  Reject all
    # links and special members to avoid re-rooting and extraction ambiguity.
    if m.issym() or m.islnk() or m.ischr() or m.isblk() or m.isfifo() or m.isdev(): raise SystemExit(1)
    if not (m.isfile() or m.isdir()): raise SystemExit(1)
    mode=m.mode & 0o7777
    # R-01: Allow sticky (0o1000) for acme dir 1770; reject only setuid/setgid (0o6000).
    # The sticky bit is validated per-branch (ACME dir allows 0o770/0o1770).
    if mode & 0o6000 or mode & 0o002: raise SystemExit(1)
    in_sb = n == SB_DIR or n.startswith(SB_DIR + '/')
    in_hy = n == HY_DIR or n.startswith(HY_DIR + '/')
    in_hy_acme = n == HY_ACME or n.startswith(HY_ACME + '/')
    in_xray = n == XRAY_DIR or n.startswith(XRAY_DIR + '/')
    in_xray_cfg = (n == XRAY_CFG)
    if in_xray_cfg:
        # Boundary 1: Xray config.json is root:abox-xray 0640 (gid != 0).
        # Allow non-root group with consistent gid, mode must not be group/other-writable.
        if m.uid != 0 or not m.isfile(): raise SystemExit(1)
        if m.gid == 0:
            if mode & 0o077: raise SystemExit(1)
        else:
            if mode & 0o027: raise SystemExit(1)
            if xray_gid is None: xray_gid=m.gid
            elif m.gid != xray_gid: raise SystemExit(1)
    elif in_xray:
        # Xray config dir is root:abox-xray 0750 (gid != 0) or legacy root:root (no group/other write).
        if m.uid != 0: raise SystemExit(1)
        if m.gid == 0:
            if n == XRAY_DIR:
                if mode & 0o022: raise SystemExit(1)
            else:
                if mode & 0o077: raise SystemExit(1)
        else:
            if mode & 0o027: raise SystemExit(1)
            if xray_gid is None: xray_gid=m.gid
            elif m.gid != xray_gid: raise SystemExit(1)
        if n == XRAY_DIR and not ((m.gid != 0 and mode == 0o750) or (m.gid == 0 and (mode & 0o022) == 0)): raise SystemExit(1)
    elif in_sb:
        # Sing-box config data may be group-readable by its dedicated runtime
        # service account. Preserve root:root compatibility, but when a non-root
        # group is present it must be internally consistent within this archive.
        if m.uid != 0: raise SystemExit(1)
        if m.gid == 0:
            if mode & 0o077: raise SystemExit(1)
        else:
            if mode & 0o020: raise SystemExit(1)
            if sb_gid is None: sb_gid=m.gid
            elif m.gid != sb_gid: raise SystemExit(1)
        if n == SB_DIR and not ((m.gid != 0 and mode == 0o750) or (m.gid == 0 and (mode & 0o077) == 0)): raise SystemExit(1)
    elif in_hy_acme:
        # Hysteria ACME state is runtime-owned to allow non-root renewal. The
        # source UID/GID are portable metadata, but must remain internally
        # consistent so a modified member cannot introduce an unrelated identity.
        if n == HY_ACME:
            if m.uid != 0 or not m.isdir(): raise SystemExit(1)
            if m.gid != 0:
                if hy_gid is None: hy_gid=m.gid
                elif m.gid != hy_gid: raise SystemExit(1)
                if hy_uid is None: hy_uid=0
            # R-01: Allow 1770 (sticky) for acme dir as well as 770.
            if not ((m.gid != 0 and mode in (0o770, 0o1770)) or
                    (m.gid == 0 and (mode & 0o077) == 0)): raise SystemExit(1)
        else:
            if m.gid != 0:
                if hy_gid is None: hy_gid=m.gid
                elif m.gid != hy_gid: raise SystemExit(1)
            if m.uid != 0:
                if hy_uid in (None,0): hy_uid=m.uid
                elif m.uid != hy_uid: raise SystemExit(1)
                if hy_gid in (None,0): hy_gid=m.gid
                elif m.gid != hy_gid: raise SystemExit(1)
            elif m.gid != 0 and hy_uid is None:
                hy_uid=0
            if mode & 0o020: raise SystemExit(1)
    elif in_hy:
        # Hysteria's top-level config tree is group-readable by its dedicated
        # runtime account; source group numbers are portable but must be consistent.
        if m.uid != 0: raise SystemExit(1)
        if m.gid == 0:
            if mode & 0o077: raise SystemExit(1)
        else:
            if mode & 0o020: raise SystemExit(1)
            if hy_gid is None: hy_gid=m.gid
            elif m.gid != hy_gid: raise SystemExit(1)
        if n == HY_DIR and not ((m.gid != 0 and mode == 0o750) or (m.gid == 0 and (mode & 0o077) == 0)): raise SystemExit(1)
    else:
        if m.uid != 0 or m.gid != 0: raise SystemExit(1)
        if mode & 0o020: raise SystemExit(1)
    if m.isfile():
        if m.size < 0 or m.size > MAX_FILE: raise SystemExit(1)
        total += m.size
        if total > MAX_TOTAL: raise SystemExit(1)
required_names={'root/etc/ddr','meta/manifest.version','meta/manifest.sha256','meta/managed-paths.txt','meta/services.state','meta/firewall.backend','meta/iptables.snapshot','meta/ip6tables.snapshot','meta/cron.abox.txt'}
if not required_names.issubset(seen): raise SystemExit(1)
required_root='root/etc/ddr'
if required_root not in seen: raise SystemExit(1)
root_member=next((m for m in members if posixpath.normpath(m.name.lstrip('./'))==required_root),None)
if root_member is None or not root_member.isdir(): raise SystemExit(1)
raise SystemExit(0)
PY_VALIDATE
}

backup_root_contains_service() {
    local root="$1" srv="$2" path
    local -a paths=()
    case "$srv" in
        xray) paths=(
            /usr/local/bin/xray /usr/local/etc/xray /usr/local/share/xray
            /etc/systemd/system/xray.service /etc/init.d/xray /etc/conf.d/xray
        ) ;;
        sing-box) paths=(
            /usr/local/bin/sing-box /etc/sing-box
            /etc/systemd/system/sing-box.service /etc/init.d/sing-box /etc/conf.d/sing-box
        ) ;;
        hysteria) paths=(
            /usr/local/bin/hysteria /etc/hysteria
            /etc/systemd/system/hysteria.service /etc/init.d/hysteria /etc/conf.d/hysteria
        ) ;;
        *) return 2 ;;
    esac
    for path in "${paths[@]}"; do
        [[ -e "$root$path" || -L "$root$path" ]] && return 0
    done
    return 1
}

backup_root_service_init() {
    local root="$1" srv="$2" unit found=''
    for unit in "$root/etc/systemd/system/${srv}.service" "$root/etc/init.d/${srv}"; do
        [[ -e "$unit" || -L "$unit" ]] || continue
        if [[ -n "$found" ]]; then
            return 2
        fi
        case "$unit" in
            "$root/etc/systemd/system/${srv}.service") found=systemd ;;
            "$root/etc/init.d/${srv}") found=openrc ;;
        esac
    done
    [[ -n "$found" ]] || return 1
    printf '%s\n' "$found"
}

validate_backup_core_init_compatibility() {
    local root="$1" srv backup_init current_init contains_rc
    current_init=$(effective_init_system) || return 1
    [[ "$current_init" == systemd || "$current_init" == openrc ]] || return 1
    for srv in xray sing-box hysteria; do
        backup_root_contains_service "$root" "$srv"
        contains_rc=$?
        case "$contains_rc" in
            0) ;;
            1) continue ;;
            *) return 1 ;;
        esac
        # A-04: Config-only backups have no unit; skip init compatibility check.
        backup_root_service_is_config_only "$root" "$srv" && continue
        backup_root_service_is_managed "$root" "$srv" || return 1
        backup_init=$(backup_root_service_init "$root" "$srv") || return 1
        [[ "$backup_init" == "$current_init" ]] || {
            msg "${RED}[!] Backup for ${srv} uses ${backup_init}, but this VPS uses ${current_init}; refusing restore before any destructive change.${NC}"
            return 1
        }
    done
    return 0
}

backup_root_service_is_managed() {
    local root="$1" srv="$2" unit found=0
    for unit in "$root/etc/systemd/system/${srv}.service" "$root/etc/init.d/${srv}"; do
        [[ -e "$unit" || -L "$unit" ]] || continue
        [[ -f "$unit" && ! -L "$unit" ]] || return 1
        grep -Fxq '# Managed by A-Box' "$unit" 2>/dev/null || return 1
        found=$((found + 1))
    done
    (( found == 1 ))
}

# A-04: A backup is "config-only" if it has NO unit file AND NO binary for the
# service (A-04 converter strips both). Config-only backups import config files
# only; they must NOT pass the managed-unit check (no unit to check) and must
# NOT declare the service as running in services.state.
backup_root_service_is_config_only() {
    local root="$1" srv="$2" bin
    case "$srv" in
        xray) bin="$root/usr/local/bin/xray" ;;
        sing-box) bin="$root/usr/local/bin/sing-box" ;;
        hysteria) bin="$root/usr/local/bin/hysteria" ;;
        *) return 1 ;;
    esac
    [[ ! -e "$root/etc/systemd/system/${srv}.service" && ! -L "$root/etc/systemd/system/${srv}.service" ]] || return 1
    [[ ! -e "$root/etc/init.d/${srv}" && ! -L "$root/etc/init.d/${srv}" ]] || return 1
    [[ ! -e "$bin" && ! -L "$bin" ]]
}

validate_backup_manifest_tree() {
    local work="$1"
    python3 - "$work" <<'PY_BACKUP_MANIFEST'
import hashlib
import os
import re
import sys
from pathlib import Path, PurePosixPath
root=Path(sys.argv[1]).resolve()
manifest=root/'meta'/'manifest.sha256'
if not manifest.is_file() or manifest.is_symlink(): raise SystemExit(1)
entries={}
for raw in manifest.read_text(encoding='utf-8',errors='strict').splitlines():
    m=re.fullmatch(r'([0-9A-Fa-f]{64})  (.+)',raw)
    if not m: raise SystemExit(1)
    digest,name=m.groups()
    pp=PurePosixPath(name)
    if pp.is_absolute() or '..' in pp.parts or not pp.parts or pp.parts[0] not in {'root','meta'}: raise SystemExit(1)
    if name=='meta/manifest.sha256' or name in entries: raise SystemExit(1)
    entries[name]=digest.lower()
actual={}
for base in (root/'root',root/'meta'):
    for path in base.rglob('*'):
        if path.is_symlink(): raise SystemExit(1)
        if path.is_file():
            rel=path.relative_to(root).as_posix()
            if rel=='meta/manifest.sha256': continue
            actual[rel]=path
if set(entries)!=set(actual): raise SystemExit(1)
for name,path in actual.items():
    h=hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda:f.read(1024*1024),b''): h.update(chunk)
    if h.hexdigest()!=entries[name]: raise SystemExit(1)
PY_BACKUP_MANIFEST
}

validate_managed_paths_file() {
    local file="$1" allowed_paths='' srv core_paths
    [[ -f "$file" && ! -L "$file" ]] || return 1
    allowed_paths=$(managed_auxiliary_paths) || return 1
    for srv in xray sing-box hysteria; do
        core_paths=$(core_family_paths "$srv") || return 1
        allowed_paths+=$'\n'"$core_paths"
    done
    python3 - "$file" "$allowed_paths" <<'PY_MANAGED_PATHS'
import sys
from pathlib import Path
allowed={x for x in sys.argv[2].splitlines() if x}
lines=[x for x in Path(sys.argv[1]).read_text(encoding='utf-8',errors='strict').splitlines() if x]
if len(lines)!=len(set(lines)) or any(x not in allowed for x in lines): raise SystemExit(1)
PY_MANAGED_PATHS
}

validate_services_state_file() {
    local file="$1"
    [[ -f "$file" && ! -L "$file" ]] || return 1
    awk -F'|' '
      NF==0 {next}
      NF!=3 || $1 !~ /^(xray|sing-box|hysteria)$/ || $2 !~ /^[01]$/ || $3 !~ /^[01]$/ {bad=1; exit}
      seen[$1]++ {bad=1; exit}
      END {exit bad}
    ' "$file"
}

validate_extracted_backup_content() {
    local root="$1" srv path src work
    work=$(dirname "$root")
    [[ -f "$work/meta/manifest.version" && -f "$work/meta/manifest.sha256" ]] || return 1
    grep -Fxq 'A-Box backup manifest v3' "$work/meta/manifest.version" || return 1
    validate_backup_manifest_tree "$work" || return 1
    validate_managed_paths_file "$work/meta/managed-paths.txt" || return 1
    validate_abox_cron_file "$work/meta/cron.abox.txt" || return 1
    grep -Eq '^(iptables|ufw|firewalld)$' "$work/meta/firewall.backend" || return 1
    validate_services_state_file "$work/meta/services.state" || return 1
    [[ -f "$root$ABOX_DIR/.A-Box-owner" && ! -L "$root$ABOX_DIR/.A-Box-owner" ]] || return 1
    grep -Fxq 'A-Box managed directory v1' "$root$ABOX_DIR/.A-Box-owner" 2>/dev/null || return 1
    for srv in xray sing-box hysteria; do
        backup_root_contains_service "$root" "$srv" || continue
        if backup_root_service_is_config_only "$root" "$srv"; then
            # A-04: Config-only backup must NOT declare service as running,
            # and must contain the config file.
            ! grep -Eq "^${srv}\|" "$work/meta/services.state" 2>/dev/null || return 1
            case "$srv" in
                xray) [[ -f "$root/usr/local/etc/xray/config.json" ]] || return 1 ;;
                sing-box) [[ -f "$root/etc/sing-box/config.json" ]] || return 1 ;;
                hysteria) [[ -f "$root/etc/hysteria/config.yaml" ]] || return 1 ;;
            esac
        else
            backup_root_service_is_managed "$root" "$srv" || return 1
            case "$srv" in
                xray) [[ -f "$root/usr/local/bin/xray" && -f "$root/usr/local/etc/xray/config.json" ]] || return 1 ;;
                sing-box) [[ -f "$root/usr/local/bin/sing-box" && -f "$root/etc/sing-box/config.json" ]] || return 1 ;;
                hysteria) [[ -f "$root/usr/local/bin/hysteria" && -f "$root/etc/hysteria/config.yaml" ]] || return 1 ;;
            esac
        fi
    done
    local aux_paths=''
    aux_paths=$(managed_auxiliary_paths) || return 1
    while IFS= read -r path; do
        src="$root$path"
        [[ -e "$src" || -L "$src" ]] || continue
        auxiliary_content_is_abox_managed "$src" "$path" || return 1
    done <<< "$aux_paths"
}

assert_restore_target_safe() {
    local root="$1" srv path c=''
    validate_extracted_backup_content "$root" || { msg "${RED}[!] Backup content ownership markers are invalid.${NC}"; return 1; }
    local conflicts=''
    for srv in xray sing-box hysteria; do
        backup_root_contains_service "$root" "$srv" || continue
        conflicts=$(list_foreign_core_conflicts "$srv") || return 1
        c+="$conflicts"$'\n'
    done
    local aux_paths=''
    aux_paths=$(managed_auxiliary_paths) || return 1
    while IFS= read -r path; do
        [[ "$path" == /usr/local/bin/sb ]] && continue
        [[ -e "$root$path" || -L "$root$path" ]] || continue
        [[ ! -e "$path" && ! -L "$path" ]] || auxiliary_path_is_abox_managed "$path" || c+="aux|${path}"$'\n'
    done <<< "$aux_paths"
    [[ -z "${c//$'\n'/}" ]] || { msg "${RED}[!] Restore would overwrite non-A-Box paths:${NC}"; printf '%s' "$c" >&2; return 1; }
}

assert_restore_shortcut_safe() {
    local root="$1"
    [[ -e "$root/usr/local/bin/sb" || -L "$root/usr/local/bin/sb" ]] || return 0
    assert_abox_shortcut_safe /usr/local/bin/sb
}

abox_restore_preserved_name() {
    case "$1" in
        backups|diagnostics|preflight|.tz-rollback|.dns-backup|A-Box.sh|.backup-hmac.key|.runtime.lock|.runtime.lock.d|socket_probe.sh|geo_update.sh|traffic_monitor.sh|firewall_restore.sh|iptables.v4|iptables.v6) return 0 ;;
        *) return 1 ;;
    esac
}

clear_abox_runtime_for_restore() {
    local child base failed=0
    [[ -d "$ABOX_DIR" && ! -L "$ABOX_DIR" ]] || return 0
    for child in "$ABOX_DIR"/* "$ABOX_DIR"/.[!.]* "$ABOX_DIR"/..?*; do
        [[ -e "$child" || -L "$child" ]] || continue
        base=${child##*/}
        abox_restore_preserved_name "$base" && continue
        path_tree_has_mountpoint "$child" && { msg "${RED}[!] Restore cleanup encountered a mountpoint; aborting before deletion: ${child}${NC}"; return 1; }
    done
    for child in "$ABOX_DIR"/* "$ABOX_DIR"/.[!.]* "$ABOX_DIR"/..?*; do
        [[ -e "$child" || -L "$child" ]] || continue
        base=${child##*/}
        abox_restore_preserved_name "$base" && continue
        rm -rf -- "$child" || failed=1
    done
    (( failed == 0 ))
}

restore_abox_directory() {
    local root="$1" src child base
    src="$root$ABOX_DIR"
    [[ -d "$src" && ! -L "$src" ]] || return 1
    path_parent_chain_safe "$ABOX_DIR" || return 1
    if [[ -e "$ABOX_DIR" || -L "$ABOX_DIR" ]]; then
        [[ -d "$ABOX_DIR" && ! -L "$ABOX_DIR" ]] || return 1
    else
        install -d -m 700 "$ABOX_DIR" || return 1
    fi
    path_tree_has_mountpoint "$ABOX_DIR" && return 1
    ensure_abox_dir_owned "$ABOX_DIR" || return 1
    for child in "$src"/* "$src"/.[!.]* "$src"/..?*; do
        [[ -e "$child" || -L "$child" ]] || continue
        base=${child##*/}
        abox_restore_preserved_name "$base" && continue
        [[ ! -L "$child" ]] || return 1
        cp -a -- "$child" "$ABOX_DIR/" || return 1
    done
    ensure_abox_dir_owned "$ABOX_DIR" || return 1
}

normalize_restored_runtime_ownership() {
    local family="$1" user group
    IFS=$'\t' read -r user group < <(abox_runtime_identity "$family") || return 1
    ensure_abox_runtime_identity "$family" || return 1
    case "$family" in
        sing-box)
            [[ -d /etc/sing-box && ! -L /etc/sing-box ]] || return 1
            chown -R "root:$group" /etc/sing-box || return 1
            ;;
        hysteria)
            [[ -d /etc/hysteria && ! -L /etc/hysteria ]] || return 1
            chown -R "root:$group" /etc/hysteria || return 1
            if [[ -d /etc/hysteria/acme ]]; then
                [[ ! -L /etc/hysteria/acme ]] || return 1
                chown -R "$user:$group" /etc/hysteria/acme || return 1
                if [[ -f /etc/hysteria/acme/.A-Box-managed ]]; then
                    chown root:root /etc/hysteria/acme/.A-Box-managed || return 1
                    chmod 600 /etc/hysteria/acme/.A-Box-managed || return 1
                fi
                chown "root:$group" /etc/hysteria/acme || return 1
            fi
            ;;
        xray)
            [[ -d /usr/local/etc/xray && ! -L /usr/local/etc/xray ]] || return 1
            chown -R "root:$group" /usr/local/etc/xray || return 1
            chmod 750 /usr/local/etc/xray || return 1
            ;;
        *) return 1 ;;
    esac
}

regenerate_runtime_assets_after_restore() {
    clear_abox_env_vars
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        load_abox_env "$ABOX_ENV" || return 1
    fi
    for srv in xray sing-box hysteria; do
        abox_owns_service "$srv" || continue
        prepare_abox_runtime_permissions "$srv" || return 1
    done
    setup_shortcut || return 1
    setup_health_monitor || return 1
    setup_geo_cron || return 1
    if valid_traffic_limit_gb "${TRAFFIC_LIMIT_GB:-}"; then
        setup_traffic_monitor || return 1
    else
        disable_traffic_monitor || return 1
    fi
}


restore_tree_path() {
    local root="$1" path="$2" src parent current
    src="$root$path"
    [[ "$path" == /* && "$path" != / ]] || return 1
    parent=$(dirname "$path")
    # Refuse to traverse a symlinked live parent directory.
    current='/'
    IFS='/' read -r -a _parts <<< "${parent#/}"
    for _part in "${_parts[@]}"; do
        [[ -n "$_part" ]] || continue
        current="${current%/}/$_part"
        [[ -L "$current" ]] && return 1
    done
    if [[ "$parent" != "/" ]] && path_is_mountpoint "$parent"; then
        return 1
    fi
    if [[ ! -e "$src" && ! -L "$src" ]]; then
        # Even when the backup has no matching target, the live target may
        # contain nested mounts. Treat the whole target tree as protected so
        # cleanup cannot recurse into an unrelated mounted filesystem.
        path_tree_has_mountpoint "$path" && return 1
        rm -rf -- "$path"
        return 0
    fi
    [[ ! -L "$src" ]] || return 1
    path_tree_has_mountpoint "$path" && return 1
    mkdir -p "$parent" || return 1
    rm -rf -- "$path" || return 1
    cp -a -- "$src" "$parent/" || return 1
    [[ ! -L "$path" ]]
}

restore_shortcut_from_backup() {
    local root="$1" src
    src="$root/usr/local/bin/sb"
    if [[ -e "$src" || -L "$src" ]]; then
        auxiliary_content_is_abox_managed "$src" /usr/local/bin/sb || return 1
        assert_abox_shortcut_safe /usr/local/bin/sb
        restore_tree_path "$root" /usr/local/bin/sb
    else
        remove_abox_shortcut /usr/local/bin/sb
    fi
}

restore_auxiliary_path_from_backup() {
    local root="$1" path="$2" src
    src="$root$path"
    [[ "$path" != /usr/local/bin/sb ]] || { restore_shortcut_from_backup "$root"; return; }
    if [[ -e "$src" || -L "$src" ]]; then
        auxiliary_content_is_abox_managed "$src" "$path" || return 1
        [[ ! -e "$path" && ! -L "$path" ]] || auxiliary_path_is_abox_managed "$path" || return 1
        restore_tree_path "$root" "$path"
    else
        remove_owned_auxiliary_path "$path"
    fi
}

restore_core_family_from_backup() {
    local root="$1" srv="$2" path core_paths='' contains_rc=0 backup_init current_init
    backup_root_contains_service "$root" "$srv"
    contains_rc=$?
    case "$contains_rc" in
        0) ;;
        1) return 0 ;;
        *) return 1 ;;
    esac
    # A-04: Config-only backups have no unit; skip init checks.
    if ! backup_root_service_is_config_only "$root" "$srv"; then
        backup_root_service_is_managed "$root" "$srv" || return 1
        backup_init=$(backup_root_service_init "$root" "$srv") || return 1
        current_init=$(effective_init_system) || return 1
        [[ "$backup_init" == "$current_init" ]] || {
            msg "${RED}[!] Backup for ${srv} uses ${backup_init}, but this VPS uses ${current_init}; refusing cross-init restore.${NC}"
            return 1
        }
    fi
    core_paths=$(core_family_paths "$srv") || return 1
    [[ -n "$core_paths" ]] || return 1
    while IFS= read -r path; do
        [[ -n "$path" ]] || continue
        restore_tree_path "$root" "$path" || return 1
    done <<< "$core_paths"
    normalize_restored_runtime_ownership "$srv" || return 1
}



# BUG-28: hoisted from backup_current_config(). $1=src $2=root (staging dir).
# Returns 0 on success/skip, 1 on failure (caller sets backup_failed=1).
__abox_backup_copy_path() {
    local src="$1" root="$2" dst links
    [[ -e "$src" ]] || return 0
    [[ ! -L "$src" ]] || return 1
    # A managed path may acquire a nested mount after ownership was recorded.
    # Never let cp -a traverse into an external filesystem/bind mount during backup.
    path_tree_has_mountpoint "$src" && return 1
    if [[ -d "$src" ]]; then
        links=$(find "$src" -type l -print 2>/dev/null) || return 1
        [[ -z "$links" ]] || return 1
    fi
    dst="$root$src"
    mkdir -p "$(dirname "$dst")" || return 1
    cp -a -- "$src" "$dst"
}
backup_current_config() {
    local ts unique backup_dir work root tarball backup_failed=0 backend srv path _abox_links _old_backups
    valid_backup_retention_count "$BACKUP_RETENTION_COUNT" || die 'BACKUP_RETENTION_COUNT 无效；必须是 0-1000 的整数。'
    ts=$(date +%Y%m%d-%H%M%S); unique=$(openssl rand -hex 3 2>/dev/null || printf '%s' "$$")
    backup_dir="${1:-$ABOX_DIR/backups}"
    [[ "$backup_dir" == /* ]] || die 'Backup directory must be an absolute path.'
    path_parent_chain_safe "$backup_dir/.A-Box-backup-destination" || die 'Backup directory parent chain is unsafe.'
    if [[ -e "$backup_dir" || -L "$backup_dir" ]]; then
        [[ -d "$backup_dir" && ! -L "$backup_dir" ]] || die 'Backup directory is not a safe regular directory.'
        path_owned_by_root "$backup_dir" || die 'Backup directory is not root-owned.'
        path_mode_has_no_group_other_write "$backup_dir" || die 'Backup directory permissions are unsafe.'
    fi
    work=$(mktemp -d /tmp/A-Box-backup.XXXXXX) || die 'Backup temp directory creation failed.'
    root="$work/root"; install -d -m 700 "$backup_dir" "$root" "$work/meta" || { rm -rf "$work"; die 'Backup directory creation failed.'; }
    path_owned_by_root "$backup_dir" || { rm -rf "$work"; die 'Backup directory ownership verification failed.'; }
    path_mode_has_no_group_other_write "$backup_dir" || { rm -rf "$work"; die 'Backup directory permissions verification failed.'; }
    local managed_paths='' core_paths=''
    managed_paths=$(managed_auxiliary_paths) || { rm -rf "$work"; die 'Managed path list creation failed.'; }
    for srv in xray sing-box hysteria; do
        core_paths=$(core_family_paths "$srv") || { rm -rf "$work"; die "Core path enumeration failed: $srv"; }
        managed_paths+=$'\n'"$core_paths"
    done
    printf '%s\n' "$managed_paths" | awk 'NF && !seen[$0]++' > "$work/meta/managed-paths.txt" || { rm -rf "$work"; die 'Managed path list write failed.'; }
    msg "${YELLOW}[*] $(tr_msg bk_creating)${NC}"
    if [[ -d "$ABOX_DIR" ]]; then
        # The A-Box data directory itself can live on a separate filesystem, but
        # a nested mount must never be traversed by tar during backup. This also
        # catches same-device bind mounts that --one-file-system cannot detect.
        path_tree_has_nested_mountpoint "$ABOX_DIR" && backup_failed=1
        # C-04: Exclude .tz-rollback/.dns-backup (contain symlinks from cp -a of /etc/localtime, /etc/resolv.conf).
        _abox_links=$(find "$ABOX_DIR" -path "$ABOX_DIR/backups" -prune -o -path "$ABOX_DIR/diagnostics" -prune -o -path "$ABOX_DIR/preflight" -prune -o -path "$ABOX_DIR/.tz-rollback" -prune -o -path "$ABOX_DIR/.dns-backup" -prune -o -type l -print 2>/dev/null) || backup_failed=1
        if [[ -n "${_abox_links:-}" ]]; then
            backup_failed=1
        else
            mkdir -p "$root$ABOX_DIR" || backup_failed=1
            [[ "$backup_failed" == 0 ]] && (cd "$ABOX_DIR" && tar \
                --exclude='./backups' --exclude='./diagnostics' --exclude='./preflight' \
                --exclude='./.tz-rollback' --exclude='./.dns-backup' \
                --exclude='./A-Box.sh' --exclude='./.backup-hmac.key' --exclude='./.runtime.lock' --exclude='./.runtime.lock.d' \
                --exclude='./socket_probe.sh' --exclude='./geo_update.sh' --exclude='./traffic_monitor.sh' \
                --exclude='./firewall_restore.sh' --exclude='./iptables.v4' --exclude='./iptables.v6' \
                -cpf - . | tar -C "$root$ABOX_DIR" -xpf -) || backup_failed=1
        fi
    fi
    shortcut_is_abox_managed /usr/local/bin/sb && { __abox_backup_copy_path /usr/local/bin/sb "$root" || backup_failed=1; }
    for srv in xray sing-box hysteria; do
        if abox_owns_service "$srv"; then
            core_paths=$(core_family_paths "$srv") || { rm -rf "$work"; die "Core path enumeration failed during backup: $srv"; }
            while IFS= read -r path; do
                [[ -n "$path" ]] || continue
                __abox_backup_copy_path "$path" "$root" || backup_failed=1
            done <<< "$core_paths"
        fi
    done
    local aux_paths=''
    aux_paths=$(managed_auxiliary_paths) || { rm -rf "$work"; die 'Managed auxiliary path enumeration failed during backup.'; }
    while IFS= read -r path; do
        [[ "$path" == /usr/local/bin/sb ]] && continue
        auxiliary_path_is_abox_managed "$path" && { __abox_backup_copy_path "$path" "$root" || backup_failed=1; }
    done <<< "$aux_paths"
    { echo 'A-Box backup'; echo "Created: $(now_iso)"; echo "Host: $(hostname 2>/dev/null || true)"; echo "Kernel: $(uname -a 2>/dev/null || true)"; echo "Init: ${INIT_SYS:-unknown}"; echo "Script SHA256: $(sha256sum "$0" 2>/dev/null | awk '{print $1}')"; } > "$work/meta/metadata.txt"
    collect_abox_cron > "$work/meta/cron.abox.txt" 2>/dev/null || backup_failed=1
    capture_managed_service_state "$work/meta/services.state" || backup_failed=1
    backend=$(firewall_backend); printf '%s\n' "$backend" > "$work/meta/firewall.backend"
    [[ "$backend" != 'nftables-unsupported' ]] || backup_failed=1
    capture_abox_iptables_snapshot "$work/meta/iptables.snapshot" 4 || backup_failed=1
    capture_abox_iptables_snapshot "$work/meta/ip6tables.snapshot" 6 || backup_failed=1
    (( backup_failed == 0 )) || { rm -rf "$work"; die 'Backup aborted because an existing A-Box path could not be copied.'; }
    printf '%s\n' 'A-Box backup manifest v3' > "$work/meta/manifest.version"
    create_backup_manifest "$work" "$work/meta/manifest.sha256" || { rm -rf "$work"; die 'Backup manifest creation failed.'; }
    tarball="$backup_dir/A-Box-backup-${ts}-${unique}.tar.gz"
    tar -C "$work" -czf "$tarball" root meta || { rm -rf "$work"; rm -f "$tarball"; die 'Backup tarball creation failed.'; }
    chmod 600 "$tarball"; validate_backup_archive "$tarball" || { rm -rf "$work"; rm -f "$tarball"; die 'Backup archive validation failed.'; }
    backup_checksum_write "$tarball" || { rm -rf "$work"; rm -f "$tarball" "${tarball}.sha256"; die 'Backup SHA256 creation failed.'; }
    backup_auth_write "$tarball" || { rm -rf "$work"; rm -f "$tarball" "${tarball}.sha256" "${tarball}.hmac"; die 'Backup HMAC authentication creation failed.'; }
    local backup_dir_real abox_dir_real
    backup_dir_real=$(canonical_path "$backup_dir") || { rm -rf "$work"; die 'Backup directory canonicalization failed.'; }
    abox_dir_real=$(canonical_path "$ABOX_DIR") || { rm -rf "$work"; die 'A-Box directory canonicalization failed.'; }
    if [[ "$backup_dir_real" != "$abox_dir_real" && "$backup_dir_real" != "$abox_dir_real/"* ]]; then
        # External destinations leave ABOX_DIR (and .backup-hmac.key) behind.
        # Write the recovery key ONLY under /root/A-Box-backup-keys/ (mode 700).
        # A-05a: Do NOT place ${tarball}.key next to archive (co-location defeats HMAC trust model).
        local key_value keys_dir='/root/A-Box-backup-keys' separated_key
        separated_key="$keys_dir/$(basename "$tarball").key"
        IFS= read -r key_value < "$ABOX_BACKUP_KEY" || { rm -rf "$work"; rm -f "$tarball" "${tarball}.sha256" "${tarball}.hmac"; die 'External backup recovery key read failed.'; }
        install -d -m 700 -o root -g root -- "$keys_dir" || { rm -rf "$work"; rm -f "$tarball" "${tarball}.sha256" "${tarball}.hmac"; die 'Backup keys directory creation failed.'; }
        if [[ ! -e "$separated_key" && ! -L "$separated_key" ]]; then
            write_private_sidecar "$separated_key" "$key_value" || { rm -rf "$work"; rm -f "$tarball" "${tarball}.sha256" "${tarball}.hmac" "$separated_key"; die 'Separated recovery key write failed.'; }
        fi
        # A-05a: Do NOT write ${tarball}.key next to archive (co-location defeats HMAC trust model).
        # Key lives ONLY in /root/A-Box-backup-keys/ (mode 700, root-only).
        msg "${GREEN}[*] $(tr_msg bk_recovery_key)${NC} $separated_key"
        msg "${YELLOW}[!] $(tr_msg bk_keep_key)${NC}"
    fi
    rm -rf "$work"
    ABOX_LAST_BACKUP="$tarball"
    _old_backups=()
    local _old_backups_output=''
    if _old_backups_output=$(python3 - "$backup_dir" "$BACKUP_RETENTION_COUNT" <<'PY_BACKUP_RETENTION'
from pathlib import Path
import sys
root=Path(sys.argv[1]); keep=int(sys.argv[2])
items=[]
for p in root.glob('A-Box-backup-*.tar.gz'):
    try:
        if p.is_file() and not p.is_symlink(): items.append((p.stat().st_mtime_ns, str(p)))
    except OSError: pass
for _, name in sorted(items, reverse=True)[keep:]: print(name)
PY_BACKUP_RETENTION
); then
        [[ -z "$_old_backups_output" ]] || mapfile -t _old_backups <<< "$_old_backups_output"
        for _old in "${_old_backups[@]}"; do [[ "$_old" == "$ABOX_LAST_BACKUP" ]] || rm -f -- "$_old" "${_old}.sha256" "${_old}.hmac" "${_old}.key"; done
    else
        msg "${YELLOW}[!] $(tr_msg bk_retention_fail)${NC}"
    fi
    msg "${GREEN}[*] $(tr_msg bk_created)${NC} $tarball"
}

auto_backup_prompt() {
    local reason="${1:-operation}" dest="${2:-$ABOX_DIR/backups}" answer
    local _lbl=''
    _lbl=$(tr_msg "$reason")
    [[ -n "$_lbl" ]] || _lbl="$reason"
    msg "${YELLOW}[!] $(tprintf bk_recommend "$_lbl")${NC}"
    read -r -p "$(tr_msg bk_create_prompt)" answer
    if is_yes "$answer"; then
        backup_current_config "$dest"
    else
        msg "${YELLOW}[*] $(tr_msg bk_skipped)${NC}"
    fi
}

auto_backup_silent() {
    local reason="${1:-operation}" dest="${2:-$ABOX_DIR/backups}"
    msg "${YELLOW}[*] Auto backup before: ${reason}${NC}"
    backup_current_config "$dest"
}

restore_latest_backup_silent() {
    local backup_dir="${1:-$ABOX_DIR/backups}" selected="${2:-}" key_file="${3:-}" work root backend mode=all srv
    [[ -d "$backup_dir" ]] || return 1
    if [[ -n "$selected" ]]; then
        [[ -f "$selected" && "$(dirname "$selected")" == "$backup_dir" ]] || return 1
    else
        selected=$(find "$backup_dir" -maxdepth 1 -type f -name 'A-Box-backup-*.tar.gz' -print | sort -r | sed -n '1p')
    fi
    [[ -n "$selected" ]] || return 1
    backup_checksum_verify "$selected" "${selected}.sha256" || return 1
    if [[ -n "$key_file" ]]; then
        backup_auth_verify_with_key_file "$selected" "${selected}.hmac" "$key_file" || return 1
    else
        backup_auth_verify "$selected" "${selected}.hmac" || return 1
    fi
    validate_backup_archive "$selected" || return 1
    work=$(mktemp -d /tmp/A-Box-rollback.XXXXXX) || return 1; chmod 700 "$work"
    tar -xzf "$selected" -C "$work" || { rm -rf "$work"; return 1; }
    root="$work/root"; assert_restore_target_safe "$root" || { rm -rf "$work"; return 1; }; assert_restore_shortcut_safe "$root" || { rm -rf "$work"; return 1; }; validate_backup_core_init_compatibility "$root" || { rm -rf "$work"; return 1; }
    stop_all_managed_services >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    clean_nat_rules >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    clean_input_rules >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    remove_all_owned_core_families || { rm -rf "$work"; return 1; }
    clear_abox_runtime_for_restore || { rm -rf "$work"; return 1; }
    restore_abox_directory "$root" || { rm -rf "$work"; return 1; }
    for srv in xray sing-box hysteria; do restore_core_family_from_backup "$root" "$srv" || { rm -rf "$work"; return 1; }; done
    local aux_paths=''
    aux_paths=$(managed_auxiliary_paths) || { rm -rf "$work"; return 1; }
    while IFS= read -r path; do
        [[ "$path" == /usr/local/bin/sb ]] && continue
        restore_auxiliary_path_from_backup "$root" "$path" || { rm -rf "$work"; return 1; }
    done <<< "$aux_paths"
    regenerate_runtime_assets_after_restore >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    apply_native_firewall_rules_from_state >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    backend=$(cat "$work/meta/firewall.backend" 2>/dev/null || echo iptables); [[ "$backend" == iptables ]] || mode=special
    restore_abox_iptables_snapshot "$work/meta/iptables.snapshot" 4 "$mode" || { rm -rf "$work"; return 1; }
    restore_abox_iptables_snapshot "$work/meta/ip6tables.snapshot" 6 "$mode" || { rm -rf "$work"; return 1; }
    # X-08: a pre-deployment backup on a fresh host legitimately has no .env;
    # guard like regenerate_runtime_assets_after_restore does (L13851).
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        load_abox_env "$ABOX_ENV" >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
        if [[ -n "${SS_PORT:-}" ]]; then enforce_ss_whitelist_order "$SS_PORT" || { rm -rf "$work"; return 1; }; fi
    else
        clear_abox_env_vars
    fi
    save_firewall_rules >/dev/null 2>&1 || { rm -rf "$work"; return 1; }
    if [[ "${INIT_SYS:-}" == systemd ]]; then systemctl daemon-reload >/dev/null 2>&1 || { rm -rf "$work"; return 1; }; fi
    restore_managed_service_state "$work/meta/services.state" || { rm -rf "$work"; return 1; }
    rm -rf "$work"; msg "${GREEN}[*] Rollback restored backup:${NC} $selected"
}

restore_from_backup() {
    local backup_dir="$ABOX_DIR/backups" backups i choice selected work root answer backend mode=all srv path targets='' backups_output=''
    if ! backups_output=$(
        for _dir in "$ABOX_DIR/backups" /root/A-Box-backups; do
            [[ -d "$_dir" && ! -L "$_dir" ]] || continue
            find "$_dir" -maxdepth 1 -type f -name 'A-Box-backup-*.tar.gz' -print
        done | sort -ru
    ); then
        msg "${RED}[!] $(tr_msg rb_enum_fail)${NC}"
        pause_return
        return
    fi
    backups=()
    [[ -z "$backups_output" ]] || mapfile -t backups <<< "$backups_output"
    (( ${#backups[@]} )) || { msg "${RED}[!] $(tprintf rb_none_found "$ABOX_DIR")${NC}"; pause_return; return; }
    clear
    for i in "${!backups[@]}"; do printf '%2d. %s\n' "$((i+1))" "${backups[$i]}"; done
    read -r -p "$(tr_msg rb_select)" choice
    [[ "$choice" == 0 ]] && return
    if ! [[ "$choice" =~ ^[1-9][0-9]*$ ]] || ! valid_decimal_upto "$choice" "${#backups[@]}"; then
        msg "${RED}[!] $(tr_msg rb_invalid)${NC}"
        pause_return
        return
    fi
    selected="${backups[$((10#$choice-1))]}"
    backup_checksum_verify "$selected" "${selected}.sha256" || die "$(tr_msg rb_sha_bad)"
    prepare_backup_auth_for_manual_restore "$selected" || die "$(tr_msg rb_auth_fail)"
    validate_backup_archive "$selected" || die "$(tr_msg rb_structure_fail)"
    work=$(mktemp -d /tmp/A-Box-restore.XXXXXX) || die "$(tr_msg rb_tmp_fail)"
    chmod 700 "$work"
    tar -xzf "$selected" -C "$work" || { rm -rf "$work"; die "$(tr_msg rb_extract_fail)"; }
    root="$work/root"
    assert_restore_target_safe "$root" || { rm -rf "$work"; die "$(tr_msg rb_target_fail)"; }
    assert_restore_shortcut_safe "$root" || { rm -rf "$work"; die "$(tr_msg rb_shortcut_fail)"; }
    validate_backup_core_init_compatibility "$root" || { rm -rf "$work"; die "$(tr_msg rb_init_incompat)"; }
    msg "${YELLOW}[!] $(tr_msg rb_replace_note)${NC}"
    read -r -p "$(tr_msg rb_continue)" answer
    is_yes "$answer" || { rm -rf "$work"; return; }

    ABOX_LAST_BACKUP=''
    backup_current_config "$backup_dir"
    [[ -n "$ABOX_LAST_BACKUP" && -f "$ABOX_LAST_BACKUP" ]] || { rm -rf "$work"; die "$(tr_msg rb_snapshot_fail)"; }
    for srv in xray sing-box hysteria; do
        if abox_owns_service "$srv" || backup_root_contains_service "$root" "$srv"; then
            targets+=" ${srv}"
        fi
    done
    ABOX_DEPLOY_TX_ACTIVE=1
    ABOX_DEPLOY_TX_REASON='manual backup restore'
    ABOX_DEPLOY_TX_TARGETS="${targets# }"
    ABOX_DEPLOY_TX_BACKUP="$ABOX_LAST_BACKUP"
    ABOX_DEPLOY_TX_TMP="$work"
    ABOX_DIE_HOOK=deployment_transaction_rollback
    install_deployment_transaction_traps

    stop_all_managed_services || die '恢复前无法停止全部 A-Box 托管服务。'
    clean_nat_rules || die '恢复前无法完整删除 A-Box HY2 NAT 规则。'
    clean_input_rules || die '恢复前无法完整删除 A-Box INPUT/原生防火墙规则。'
    remove_all_owned_core_families || die '恢复前删除当前 A-Box 核心文件失败。'
    clear_abox_runtime_for_restore || die '恢复前清理 A-Box 运行目录失败。'
    restore_abox_directory "$root" || die 'Restore A-Box directory failed.'
    for srv in xray sing-box hysteria; do
        restore_core_family_from_backup "$root" "$srv" || die "Restore failed for core family: $srv"
    done
    local aux_paths=''
    aux_paths=$(managed_auxiliary_paths) || die '无法枚举 A-Box 辅助文件，恢复已中止。'
    while IFS= read -r path; do
        [[ "$path" == /usr/local/bin/sb ]] && continue
        restore_auxiliary_path_from_backup "$root" "$path" || die "Restore failed: $path"
    done <<< "$aux_paths"
    chmod 700 "$ABOX_DIR" 2>/dev/null || die '恢复后的 A-Box 目录权限加固失败。'
    # X-08: restoring an initial backup (no .env) must not die here.
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        chmod 600 "$ABOX_ENV" 2>/dev/null || die '恢复后的 .env 权限加固失败。'
    fi
    regenerate_runtime_assets_after_restore || die 'Regenerate trusted A-Box runtime helpers and cron blocks failed.'
    apply_native_firewall_rules_from_state || die 'Restore native firewall rules failed.'
    backend=$(cat "$work/meta/firewall.backend" 2>/dev/null || echo iptables)
    [[ "$backend" == iptables ]] || mode=special
    restore_abox_iptables_snapshot "$work/meta/iptables.snapshot" 4 "$mode" || die 'IPv4 A-Box firewall restore failed.'
    restore_abox_iptables_snapshot "$work/meta/ip6tables.snapshot" 6 "$mode" || die 'IPv6 A-Box firewall restore failed.'
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        load_abox_env "$ABOX_ENV" >/dev/null 2>&1 || die '恢复后的 A-Box 环境文件校验失败。'
        if [[ -n "${SS_PORT:-}" ]]; then enforce_ss_whitelist_order "$SS_PORT" || die 'Restored SS whitelist order validation failed.'; fi
    else
        clear_abox_env_vars
    fi
    save_firewall_rules || die 'Restored A-Box firewall persistence failed.'
    if [[ "${INIT_SYS:-}" == systemd ]]; then systemctl daemon-reload >/dev/null 2>&1 || die 'systemd daemon-reload after restore failed.'; fi
    restore_managed_service_state "$work/meta/services.state" || die 'Restored service state failed validation/startup.'
    for srv in xray sing-box hysteria; do
        if abox_owns_service "$srv"; then
            record_core_family_ownership "$srv" || die "Restored ${srv} ownership manifest update failed; restore was not committed."
        fi
    done
    commit_deployment_transaction
    rm -rf "$work"
    msg "${GREEN}[*] $(tr_msg rb_done)${NC}"
    pause_return
}

backup_restore_menu() {
    # Submenu loop: sub-functions return here; 0/Enter goes back to the parent menu.
    while true; do
    clear
    msg "${CYAN}======================================================================${NC}"
    msg "${BOLD}${GREEN}Backup / Restore / 配置备份与恢复${NC}"
    msg "${CYAN}======================================================================${NC}"
    case "${ABOX_LANG:-zh}" in
        en)
        msg "${YELLOW}1. Backup current A-Box configuration${NC}"
        msg "${YELLOW}2. Restore from backup${NC}"
        msg "${YELLOW}3. Export recovery key to a separate medium${NC}"
        msg "${YELLOW}4. Convert a legacy backup to manifest v3${NC}"
        msg "${CYAN}0. Back${NC}"
            ;;
        ru)
        msg "${YELLOW}1. Резервное копирование текущей конфигурации A-Box${NC}"
        msg "${YELLOW}2. Восстановление из резервной копии${NC}"
        msg "${YELLOW}3. Экспорт ключа восстановления на отдельный носитель${NC}"
        msg "${YELLOW}4. Конвертация старой резервной копии в manifest v3${NC}"
        msg "${CYAN}0. Назад${NC}"
            ;;
        fa)
        msg "${YELLOW}1. پشتیبان‌گیری از پیکربندی فعلی A-Box${NC}"
        msg "${YELLOW}2. بازیابی از پشتیبان${NC}"
        msg "${YELLOW}3. صدور کلید بازیابی به رسانه جداگانه${NC}"
        msg "${YELLOW}4. تبدیل پشتیبان قدیمی به manifest v3${NC}"
        msg "${CYAN}0. بازگشت${NC}"
            ;;
        ja)
            msg "${YELLOW}1. 現在の A-Box 設定をバックアップ${NC}"
            msg "${YELLOW}2. バックアップから復元${NC}"
            msg "${YELLOW}3. 復旧キーを別の媒体にエクスポート${NC}"
            msg "${YELLOW}4. 旧バージョンのバックアップを manifest v3 に安全に変換${NC}"
            msg "${CYAN}0. 戻る${NC}"
            ;;
        zh-tw)
        msg "${YELLOW}1. 備份當前 A-Box 配置${NC}"
        msg "${YELLOW}2. 從備份恢復${NC}"
        msg "${YELLOW}3. 將恢復金鑰匯出到獨立介質${NC}"
        msg "${YELLOW}4. 將舊版備份安全轉換為 manifest v3${NC}"
        msg "${CYAN}0. 返回${NC}"
            ;;
        *)
        msg "${YELLOW}1. 备份当前 A-Box 配置${NC}"
        msg "${YELLOW}2. 从备份恢复${NC}"
        msg "${YELLOW}3. 将恢复密钥导出到独立介质${NC}"
        msg "${YELLOW}4. 将旧版备份安全转换为 manifest v3${NC}"
        msg "${CYAN}0. 返回${NC}"
            ;;
    esac
    local c
    read -r -p 'Select [0-4]: ' c || return 0
    case "$c" in
        1) backup_current_config; pause_return ;;
        2) restore_from_backup ;;
        3)
            local key_dest
            read -r -p 'Absolute path on a separate trusted medium: ' key_dest
            export_backup_recovery_key "$key_dest"; pause_return
            ;;
        4)
            local legacy_path legacy_out
            read -r -p 'Legacy .tar.gz path: ' legacy_path
            read -r -p 'Output directory (default: same directory): ' legacy_out
            convert_legacy_backup_archive "$legacy_path" "${legacy_out:-$(dirname "$legacy_path")}"; pause_return
            ;;
        0) return 0 ;;
        *) msg "${RED}$(tr_msg invalid_input): $c${NC}"; sleep 1 ;;
    esac
    done
}

write_diagnostic_checksum() {
    local bundle="$1" checksum="$2" tmp dir
    [[ -f "$bundle" && ! -L "$bundle" ]] || return 1
    [[ ! -L "$checksum" && (! -e "$checksum" || -f "$checksum") ]] || return 1
    path_parent_chain_safe "$checksum" || return 1
    dir=$(dirname "$checksum")
    [[ -d "$dir" && ! -L "$dir" ]] || return 1
    tmp=$(mktemp "${checksum}.A-Box-new.XXXXXX") || return 1
    if ! sha256sum "$bundle" > "$tmp" 2>/dev/null; then
        rm -f -- "$tmp"
        return 1
    fi
    chmod 600 "$tmp" || { rm -f -- "$tmp"; return 1; }
    if [[ $EUID -eq 0 ]]; then
        chown root:root "$tmp" || { rm -f -- "$tmp"; return 1; }
    fi
    mv -f -- "$tmp" "$checksum" || { rm -f -- "$tmp"; return 1; }
    [[ -s "$checksum" && ! -L "$checksum" ]] || return 1
    return 0
}

export_diagnostic_bundle() {
    local ts diag_dir work bundle checksum
    ts=$(date +%Y%m%d-%H%M%S)
    diag_dir="$ABOX_DIR/diagnostics"
    work=$(mktemp -d /tmp/A-Box-diagnostic.XXXXXX) || die 'Diagnostic temp directory creation failed.'
    mkdir -p "$diag_dir" "$work/logs" || { rm -rf -- "$work"; die '诊断目录创建失败。'; }
    chmod 700 "$diag_dir" 2>/dev/null || { rm -rf -- "$work"; die '诊断目录权限设置失败。'; }

    msg "${YELLOW}[*] Collecting diagnostic information with secret redaction...${NC}"
    {
        echo "A-Box diagnostic bundle"
        echo "Created: $(now_iso)"
        echo "Host: $(hostname 2>/dev/null || true)"
        echo "Script: $0"
        echo "Script SHA256: $(sha256sum "$0" 2>/dev/null | awk '{print $1}')"
    } > "$work/summary.txt"

    { uname -a 2>/dev/null; echo; cat /etc/os-release 2>/dev/null || true; echo; command -v systemctl >/dev/null 2>&1 && systemctl --version 2>/dev/null | head -n 3 || true; } > "$work/system.txt"
    { ip addr 2>/dev/null || true; echo; ip route 2>/dev/null || true; echo; ip -6 route 2>/dev/null || true; echo; ss -lntup 2>/dev/null || true; } > "$work/network.txt"
    { show_status_report 2>/dev/null || true; echo; for c in xray sing-box hysteria; do command -v "$c" >/dev/null 2>&1 && "$c" version 2>/dev/null | head -n 5; done; } > "$work/status.txt"
    { iptables -S 2>/dev/null | grep 'A-Box' || true; echo; iptables -t nat -S 2>/dev/null | grep 'A-Box' || true; echo; ip6tables -S 2>/dev/null | grep 'A-Box' || true; echo; ip6tables -t nat -S 2>/dev/null | grep 'A-Box' || true; } > "$work/firewall.txt"
    collect_abox_cron > "$work/cron.txt" 2>/dev/null || true
    if [[ -e "$ABOX_ENV" || -L "$ABOX_ENV" ]]; then
        write_redacted_file "$ABOX_ENV" "$work/env.redacted" || { rm -rf "$work"; die 'Diagnostic secret redaction failed; refusing to create a misleading bundle.'; }
    else
        printf '%s\n' 'A-Box environment file is not present.' > "$work/env.redacted" || { rm -rf "$work"; die 'Diagnostic environment placeholder creation failed.'; }
    fi

    if command -v journalctl >/dev/null 2>&1; then
        journalctl -u xray --no-pager -n 120 2>/dev/null | redact_secrets_stream > "$work/logs/xray.journal.txt" || true
        journalctl -u sing-box --no-pager -n 120 2>/dev/null | redact_secrets_stream > "$work/logs/sing-box.journal.txt" || true
        journalctl -u hysteria --no-pager -n 120 2>/dev/null | redact_secrets_stream > "$work/logs/hysteria.journal.txt" || true
    fi
    for f in /var/log/A-Box-xray-error.log /var/log/A-Box-xray-access.log /var/log/A-Box-singbox.log /var/log/A-Box-hysteria.log; do
        [[ -r "$f" ]] && tail -n 200 "$f" 2>/dev/null | redact_secrets_stream > "$work/logs/$(basename "$f").tail.txt" || true
    done

    bundle="$diag_dir/A-Box-diagnostic-${ts}.tar.gz"
    tar -C "$work" -czf "$bundle" . || { rm -rf "$work"; die 'Diagnostic bundle creation failed.'; }
    chmod 600 "$bundle" 2>/dev/null || { rm -rf "$work"; rm -f "$bundle"; die 'Diagnostic bundle permission hardening failed.'; }
    checksum="${bundle}.sha256"
    write_diagnostic_checksum "$bundle" "$checksum" || { rm -rf "$work"; rm -f "$bundle"; die 'Diagnostic bundle checksum generation failed.'; }
    rm -rf "$work"
    msg "${GREEN}[*] Diagnostic bundle:${NC}" $bundle
    msg "${GREEN}[*] SHA256:${NC}" $checksum
    pause_return
}


default_route_uses_warp() {
    local dev=''
    dev=$(ip -o route get 8.8.8.8 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}' || true)
    [[ "$dev" =~ ^(wg|warp|tun|CloudflareWARP)[0-9A-Za-z_.-]*$ ]]
}


light_preflight_check() {
    local fail=0 warn=0 c
    msg "${YELLOW}[*] $(tr_msg pf_running)${NC}"
    [[ $EUID -eq 0 ]] || { msg "${RED}[FAIL] $(tr_msg pf_root)${NC}"; fail=$((fail+1)); }
    [[ -t 0 ]] || { msg "${YELLOW}[WARN] $(tr_msg pf_notty)${NC}"; warn=$((warn+1)); }
    if [[ -r /etc/os-release ]]; then
        . /etc/os-release
        case "${ID:-}" in debian|ubuntu|centos|rhel|rocky|almalinux|alpine|fedora|amzn|ol|oracle) msg "${GREEN}[PASS] OS: ${ID:-unknown}${NC}" ;; *) msg "${YELLOW}[WARN] $(tprintf pf_os_maybe "${ID:-unknown}")${NC}"; warn=$((warn+1)) ;; esac
    else
        msg "${YELLOW}[WARN] $(tr_msg pf_os_unreadable)${NC}"; warn=$((warn+1))
    fi
    local route_dev warp_confirm=''
    route_dev=$(ip -o route get 8.8.8.8 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}' || true)
    if default_route_uses_warp; then
        msg "${YELLOW}[WARN] $(tprintf pf_warp_route "$route_dev")${NC}"
        if [[ -t 0 ]]; then
            read -r -p "$(tr_msg pf_warp_confirm)" warp_confirm || warp_confirm='N'
            is_yes "$warp_confirm" || { msg "${RED}[FAIL] $(tr_msg pf_warp_unconfirmed)${NC}"; fail=$((fail+1)); }
        else
            msg "${RED}[FAIL] $(tr_msg pf_warp_noninteractive)${NC}"
            fail=$((fail+1))
        fi
    fi
    if systemd_available; then
        msg "${GREEN}[PASS] init: systemd${NC}"
    elif command -v rc-service >/dev/null 2>&1; then
        msg "${GREEN}[PASS] init: OpenRC${NC}"
    else
        msg "${RED}[FAIL] $(tr_msg pf_no_init)${NC}"; fail=$((fail+1))
    fi
    case "$(uname -m)" in x86_64|amd64|aarch64|arm64) msg "${GREEN}[PASS] arch: $(uname -m)${NC}" ;; *) msg "${RED}[FAIL] $(tprintf pf_bad_arch "$(uname -m)")${NC}"; fail=$((fail+1)) ;; esac
    for c in bash curl jq openssl unzip tar iptables ss lsof python3 getent flock qrencode fail2ban-client; do
        command -v "$c" >/dev/null 2>&1 || { msg "${YELLOW}[WARN] $(tprintf pf_cmd_missing "$c")${NC}"; warn=$((warn+1)); }
    done
    if curl -fsS --connect-timeout 3 -m 6 https://api.github.com >/dev/null 2>&1; then
        msg "${GREEN}[PASS] $(tr_msg pf_gh_ok)${NC}"
    else
        msg "${YELLOW}[WARN] $(tr_msg pf_gh_bad)${NC}"; warn=$((warn+1))
    fi
    if (( fail > 0 )); then
        die "$(tr_msg pf_blocked)"
    fi
    msg "${GREEN}[*] $(tprintf pf_done "$warn")${NC}"
}



validate_test_script() {
    local file="$1" size first
    [[ -f "$file" && ! -L "$file" ]] || return 1
    size=$(wc -c < "$file" 2>/dev/null | tr -d ' ') || return 1
    [[ "$size" =~ ^[0-9]+$ ]] && # D-3: Align with update-mirrors.yml (2MB max).
    (( size >= 1000 && size <= 2000000 )) || return 1
    IFS= read -r first < "$file" || return 1
    [[ "$first" =~ ^#!.*(bash|env[[:space:]]+bash)([[:space:]]|$) ]] || return 1
    if head -n 25 "$file" | grep -Eiq '<!doctype[[:space:]]+html|<html'; then return 1; fi
    bash -n "$file" >/dev/null 2>&1 || return 1
}

run_mirrored_test_script() {
    local label="$1" upstream_url="$2" asset="$3" selected='' source='' expected='' sha='' answer work run_prompt
    shift 3
    work=$(umask 077; mktemp -d /tmp/A-Box-test-tool.XXXXXX) || return 1
    chmod 700 "$work" || { rm -rf -- "$work"; return 1; }
    local upstream="$work/upstream.sh" mirror="$work/mirror.sh" sums="$work/SHA256SUMS" manifest="$work/manifest.txt"
    # P2: Mirror-first (SHA-256 verified). Upstream has NO SHA pin — a
    # syntactically-valid malicious script passes validate_test_script.
    # Mirror is updated weekly; at most 1-week staleness for diagnostics.
    local sums_dl_ok=0 sig_dl_ok=0
    if curl -fLsS --connect-timeout 10 --max-time 45 \
        "https://github.com/alariclin/A-Box/releases/download/$ABOX_TEST_MIRROR_RELEASE/SHA256SUMS" -o "$sums"; then
        sums_dl_ok=1
    fi
    if curl -fLsS --connect-timeout 10 --max-time 45 \
        "https://github.com/alariclin/A-Box/releases/download/$ABOX_TEST_MIRROR_RELEASE/SHA256SUMS.sig" -o "$sums.sig" 2>/dev/null; then
        sig_dl_ok=1
    fi
    # P3-02: fail-closed - use verify_ed25519_detached directly (not the
    # degradable gate). Missing .sig or failed verification blocks execution.
    if (( sums_dl_ok == 1 )); then
        if (( sig_dl_ok == 0 )) || ! verify_ed25519_detached "$sums" "$sums.sig" >/dev/null 2>&1; then
            rm -f -- "$sums" "$sums.sig"
            sums_dl_ok=0
        fi
    fi
    if (( sums_dl_ok == 1 )) && curl -fLsS --connect-timeout 10 --max-time 45 \
        "https://github.com/alariclin/A-Box/releases/download/$ABOX_TEST_MIRROR_RELEASE/test-tools-manifest.txt" -o "$manifest" &&
       curl -fLsS --connect-timeout 10 --max-time 180 \
        "https://github.com/alariclin/A-Box/releases/download/$ABOX_TEST_MIRROR_RELEASE/$asset" -o "$mirror"; then
        # Verify manifest digest (manifest is covered by SHA256SUMS signature)
        local manifest_expected manifest_sha
        manifest_expected=$(awk -v f="test-tools-manifest.txt" '$2==f || $2==("*" f) {print $1; exit}' "$sums")
        manifest_sha=$(sha256sum "$manifest" 2>/dev/null | awk '{print $1}')
        if [[ ! "$manifest_expected" =~ ^[A-Fa-f0-9]{64}$ || "${manifest_sha,,}" != "${manifest_expected,,}" ]]; then
            # Manifest digest mismatch - do not trust manifest content
            rm -f -- "$manifest"
        fi
        expected=$(awk -v f="$asset" '$2==f || $2==("*" f) {print $1; exit}' "$sums")
        sha=$(sha256sum "$mirror" | awk '{print $1}')
        if [[ "$expected" =~ ^[A-Fa-f0-9]{64}$ && "${sha,,}" == "${expected,,}" ]] && validate_test_script "$mirror"; then
            selected="$mirror"
            source="A-Box Release $ABOX_TEST_MIRROR_RELEASE"
        fi
    fi
    if [[ -z "$selected" ]]; then
        rm -f -- "$mirror" "$sums" "$manifest"
        # P2-03: upstream fallback has no pre-pinned SHA; default-deny unless
        # the operator explicitly opts in via ABOX_ALLOW_UNVERIFIED_UPSTREAM=1.
        if [[ "${ABOX_ALLOW_UNVERIFIED_UPSTREAM:-0}" != '1' ]]; then
            case "${ABOX_LANG:-zh}" in
                en) msg "${RED}[-] A-Box verified mirror unavailable and unverified upstream fallback is disabled (set ABOX_ALLOW_UNVERIFIED_UPSTREAM=1 to allow).${NC}" ;;
                ru) msg "${RED}[-] Проверенное зеркало A-Box недоступно, а непроверенный upstream запрещён.${NC}" ;;
                fa) msg "${RED}[-] آینه تأییدشده در دسترس نیست و بازگشت تأییدنشده غیرفعال است.${NC}" ;;
                zh-tw) msg "${RED}[-] A-Box 校驗映象不可用，且未校驗的上游回退已被禁用（如需允許請設定 ABOX_ALLOW_UNVERIFIED_UPSTREAM=1）。${NC}" ;;
                ja)
                    msg "${RED}[-] A-Box の検証済みミラーを利用できず、未検証の upstream フォールバックは無効です（許可するには ABOX_ALLOW_UNVERIFIED_UPSTREAM=1 を設定してください）。${NC}" ;;
                *) msg "${RED}[-] A-Box 校验镜像不可用，且未校验的上游回退已被禁用（如需允许请设置 ABOX_ALLOW_UNVERIFIED_UPSTREAM=1）。${NC}" ;;
            esac
            rm -rf -- "$work"
            return 1
        fi
        case "${ABOX_LANG:-zh}" in
            en) msg "${YELLOW}[!] A-Box verified mirror unavailable or checksum mismatch; falling back to upstream (UNVERIFIED - no SHA pin).${NC}" ;;
            ru) msg "${YELLOW}[!] Проверенный зеркальный файл A-Box недоступен; переходим к upstream (БЕЗ ПРОВЕРКИ).${NC}" ;;
            fa) msg "${YELLOW}[!] نسخه تأییدشده A-Box در دسترس نیست؛ بازگشت به upstream (بدون تأیید).${NC}" ;;
            zh-tw) msg "${YELLOW}[!] A-Box 校驗映象不可用或校驗失敗，回退到上游（未校驗，無 SHA 釘扎）。${NC}" ;;
            ja)
                msg "${YELLOW}[!] A-Box の検証済みミラーが利用できないか、チェックサムが一致しません。upstream にフォールバックします（未検証・SHA ピン留めなし）。${NC}" ;;
            *) msg "${YELLOW}[!] A-Box 校验镜像不可用或校验失败，回退到上游（未校验，无 SHA 钉扎）。${NC}" ;;
        esac
        if curl -fLsS --retry 1 --connect-timeout 10 --max-time 180 "$upstream_url" -o "$upstream" && validate_test_script "$upstream"; then
            selected="$upstream"
            source="$upstream_url (UNVERIFIED)"
        else
            rm -rf -- "$work"
            case "${ABOX_LANG:-zh}" in
                en) msg "${RED}Upstream and A-Box recovery sources are unavailable; the script was not run.${NC}" ;;
                ru) msg "${RED}Основной и резервный источники недоступны; скрипт не запускался.${NC}" ;;
                fa) msg "${RED}منبع اصلی و پشتیبان در دسترس نیستند؛ اسکریپت اجرا نشد.${NC}" ;;
                zh-tw) msg "${RED}上游與 A-Box 災備源均不可用；未執行指令碼。${NC}" ;;
                ja)
                    msg "${RED}upstream と A-Box のリカバリーソースを利用できません。スクリプトは実行されませんでした。${NC}" ;;
                *) msg "${RED}上游与 A-Box 灾备源均不可用；未执行脚本。${NC}" ;;
            esac
            return 1
        fi
    fi
    sha=$(sha256sum "$selected" | awk '{print $1}')
    case "${ABOX_LANG:-zh}" in
        en) msg "${CYAN}Test tool: $label${NC}"; msg "${CYAN}Source: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='Execute this third-party test script? It may contact external endpoints and generate network traffic. [Y/N]: ' ;;
        ru) msg "${CYAN}Тест: $label${NC}"; msg "${CYAN}Источник: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='Запустить сторонний тестовый скрипт? Он может обращаться к внешним узлам и создавать сетевой трафик. [Y/N]: ' ;;
        fa) msg "${CYAN}ابزار آزمون: $label${NC}"; msg "${CYAN}منبع: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='اسکریپت آزمون شخص ثالث اجرا شود؟ ممکن است به مقصدهای بیرونی متصل شود و ترافیک ایجاد کند. [Y/N]: ' ;;
        zh-tw) msg "${CYAN}測試工具: $label${NC}"; msg "${CYAN}來源: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='即將執行第三方測試指令碼。它可能訪問外部檢測端點併產生網路流量；確認執行？[Y/N]: ' ;;
        ja)
            msg "${CYAN}テストツール: $label${NC}"; msg "${CYAN}ソース: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='このサードパーティー製テストスクリプトを実行しますか？外部エンドポイントに接続し、ネットワークトラフィックを発生させる可能性があります。[Y/N]: ' ;;
        *) msg "${CYAN}测试工具: $label${NC}"; msg "${CYAN}来源: $source${NC}"; msg "${CYAN}SHA256: $sha${NC}"; run_prompt='即将执行第三方测试脚本。它可能访问外部检测端点并产生网络流量；确认执行？[Y/N]: ' ;;
    esac
    if [[ "$selected" == "$mirror" ]]; then cat "$manifest" 2>/dev/null | head -12; fi
    if ! confirm_yes_no "$run_prompt"; then
        rm -rf -- "$work"
        return 130
    fi
    chmod 600 "$selected"
    env -i PATH="$PATH" HOME="${HOME:-/root}" LANG="${LANG:-C.UTF-8}" TERM="${TERM:-dumb}" bash "$selected" "$@"
    local rc=$?
    rm -rf -- "$work"
    return "$rc"
}

wallos_state_value() {
    local key="$1" val
    [[ -f "$WALLOS_DIR/.abox-state" && ! -L "$WALLOS_DIR/.abox-state" ]] || return 1
    val=$(awk -F= -v k="$key" '$1==k {sub(/^[^=]*=/, ""); print; exit}' "$WALLOS_DIR/.abox-state")
    # D-06: awk exits 0 even when the key is missing (empty output), which
    # defeated every `|| printf fallback` caller. Return 1 on empty instead.
    [[ -n "$val" ]] || return 1
    printf '%s\n' "$val"
}

wallos_detect_arch() {
    case "$(uname -m)" in
        x86_64|amd64) printf 'amd64\n' ;;
        aarch64|arm64) printf 'arm64\n' ;;
        armv7l|armv7) printf 'armv7\n' ;;
        *) return 1 ;;
    esac
}

wallos_port_free() {
    local port="$1"
    # P3-9: fail closed when ss is missing (was fail-open returning "free").
    command -v ss >/dev/null 2>&1 || return 1
    if ss -H -ltn "sport = :$port" 2>/dev/null | grep -q .; then return 1; fi
    return 0
}

wallos_print_host_info() {
    local os_name='unknown' os_version='unknown' arch mem_gb disk_gb cores ipv4 ipv6
    if [[ -r /etc/os-release ]]; then
        os_name=$(awk -F= '$1=="PRETTY_NAME" {gsub(/^"|"$/, "", $2); print $2; exit}' /etc/os-release)
        [[ -n "$os_name" ]] || os_name=$(awk -F= '$1=="ID" {print $2; exit}' /etc/os-release)
        os_version=$(awk -F= '$1=="VERSION_ID" {gsub(/^"|"$/, "", $2); print $2; exit}' /etc/os-release)
    fi
    arch=$(uname -m)
    mem_gb=$(awk '/MemTotal:/ {printf "%.1f", $2/1048576}' /proc/meminfo 2>/dev/null || printf 'unknown')
    disk_gb=$(df -Pk "$WALLOS_DIR" 2>/dev/null | awk 'NR==2 {printf "%.1f", $4/1048576}')
    [[ -n "$disk_gb" ]] || disk_gb=$(df -Pk /opt 2>/dev/null | awk 'NR==2 {printf "%.1f", $4/1048576}')
    [[ -n "$disk_gb" ]] || disk_gb='unknown'
    cores=$(getconf _NPROCESSORS_ONLN 2>/dev/null || printf 'unknown')
    ipv4=$(curl -4fsS --connect-timeout 3 --max-time 5 https://api.ipify.org 2>/dev/null || true)
    ipv6=$(curl -6fsS --connect-timeout 3 --max-time 5 https://api64.ipify.org 2>/dev/null || true)
    local _na; _na=$(tr_msg wl_hi_na)
    msg "${CYAN}$(tr_msg wl_hi_title)${NC}"
    msg "$(tprintf wl_hi_info "$os_name" "$os_version" "$arch" "$cores" "$mem_gb" "$disk_gb")"
    msg "$(tprintf wl_hi_ip "${ipv4:-$_na}" "${ipv6:-$_na}")"
}

wallos_install_runtime() {
    local os_id='' answer prompt runtime_error
    [[ -r /etc/os-release ]] || return 1
    os_id=$(awk -F= '$1=="ID" {gsub(/^"|"$/, "", $2); print $2; exit}' /etc/os-release)
    if command -v docker >/dev/null 2>&1; then
        # If the CLI is already installed, only try to start the existing daemon.
        # Do not install a second Docker package/engine over an unknown installation.
        if docker info >/dev/null 2>&1; then return 0; fi
        case "$os_id" in
            alpine)
                command -v rc-service >/dev/null 2>&1 && rc-service docker start >/dev/null 2>&1 9>&- 10>&- || true
                ;;
            *)
                if command -v systemctl >/dev/null 2>&1 && systemctl cat docker.service >/dev/null 2>&1; then
                    systemctl enable --now docker >/dev/null 2>&1 || true
                fi
                if command -v service >/dev/null 2>&1; then service docker start >/dev/null 2>&1 || true; fi
                ;;
        esac
        if docker info >/dev/null 2>&1; then return 0; fi
        runtime_error=$(tr_msg wl_rt_daemon_down)
        msg "${RED}${runtime_error}${NC}"
        return 1
    fi
    prompt=$(tr_msg wl_rt_install_prompt)
    read -r -p "$prompt" answer
    is_yes "$answer" || return 1
    case "$os_id" in
        debian|ubuntu|linuxmint|kali)
            apt-get update && apt-get install -y docker.io ca-certificates curl jq || return 1
            if command -v systemctl >/dev/null 2>&1; then systemctl enable --now docker || return 1
            elif command -v service >/dev/null 2>&1; then service docker start || return 1
            else return 1; fi
            ;;
        alpine)
            apk add --no-cache docker curl jq ca-certificates || return 1
            rc-update add docker default >/dev/null 2>&1 || true
            rc-service docker start || return 1
            ;;
        centos|rhel|rocky|almalinux|fedora)
            local -a docker_conflicts=()
            local pkg conflict_prompt
            command -v dnf >/dev/null 2>&1 || return 1
            command -v rpm >/dev/null 2>&1 || return 1
            dnf -y install dnf-plugins-core ca-certificates curl jq || return 1
            case "$os_id" in
                fedora) dnf config-manager --add-repo https://download.docker.com/linux/fedora/docker-ce.repo || return 1 ;;
                rhel) dnf config-manager --add-repo https://download.docker.com/linux/rhel/docker-ce.repo || return 1 ;;
                centos|rocky|almalinux) dnf config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo || return 1 ;;
            esac
            for pkg in docker docker-client docker-client-latest docker-common docker-latest docker-latest-logrotate docker-logrotate docker-engine docker.io containerd podman podman-docker runc; do
                rpm -q "$pkg" >/dev/null 2>&1 && docker_conflicts+=("$pkg")
            done
            if (("${#docker_conflicts[@]}" > 0)); then
                msg "${YELLOW}$(tprintf wl_rt_conflicts "${docker_conflicts[*]}")${NC}"
                conflict_prompt=$(tr_msg wl_rt_conflict_prompt)
                read -r -p "$conflict_prompt" answer || return 1
                is_yes "$answer" || { msg "${YELLOW}$(tr_msg wl_rt_declined)${NC}"; return 1; }
                dnf -y remove "${docker_conflicts[@]}" || return 1
            fi
            dnf -y install docker-ce docker-ce-cli containerd.io docker-buildx-plugin || {
                msg "${RED}$(tr_msg wl_rt_ce_fail)${NC}"
                return 1
            }
            systemctl enable --now docker || return 1
            ;;
        *)
            msg "${RED}$(tprintf wl_rt_unsupported "$os_id")${NC}"
            return 1
            ;;
    esac
    command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1
}

wallos_version_is_older() {
    local older="${1#v}" newer="${2#v}" i a b
    local -a old_parts=() new_parts=()
    [[ "$older" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ && "$newer" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 2
    IFS=. read -r -a old_parts <<< "$older"
    IFS=. read -r -a new_parts <<< "$newer"
    for i in 0 1 2; do
        a=$((10#${old_parts[$i]}))
        b=$((10#${new_parts[$i]}))
        (( a < b )) && return 0
        (( a > b )) && return 1
    done
    return 1
}

wallos_candidate_version_allowed() {
    local candidate="${1#v}" installed_image installed_version rc
    [[ "$candidate" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    [[ "${ABOX_WALLOS_ALLOW_DOWNGRADE:-0}" == 1 ]] && return 0
    docker container inspect wallos >/dev/null 2>&1 || return 0
    installed_image=$(docker inspect -f '{{.Config.Image}}' wallos 2>/dev/null || true)
    installed_version="${installed_image##*:}"
    [[ "$installed_version" == "$candidate" ]] && return 0
    if [[ "$installed_version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        wallos_version_is_older "$candidate" "$installed_version"
        rc=$?
        if (( rc == 0 )); then
            msg "${RED}$(tprintf wl_cv_downgrade "$candidate" "$installed_version")${NC}"
            return 1
        fi
        (( rc == 1 )) && return 0
    fi
    msg "${RED}$(tprintf wl_cv_compare "$candidate" "$installed_image")${NC}"
    return 1
}

# N-11: Fetch the retained version list from the A-Box wallos-mirror.
# Outputs one version per line, newest first. Empty on failure.
wallos_mirror_version_list() {
    local work versions_url
    work=$(umask 077; mktemp -d /tmp/A-Box-Wallos-ver.XXXXXX 2>/dev/null) || return 1
    versions_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/wallos-versions.txt"
    if curl -fLsS --connect-timeout 8 --max-time 20 "$versions_url" -o "$work/wallos-versions.txt" 2>/dev/null; then
        grep -E '^v[0-9]+\.[0-9]+\.[0-9]+$' "$work/wallos-versions.txt" 2>/dev/null || true
    fi
    rm -rf -- "$work"
}

# N-11: Prune local bellamy/wallos images to keep only the newest 2
# (current + previous verified-good). Enforces the 500MB local cache cap
# by count (2 images). (N-06: removed stale "reports total size" claim.)
# Args: $1 = image tag to always keep (current), $2 = image tag to keep (previous, may be empty).
wallos_prune_local_images() {
    local keep1="${1:-}" keep2="${2:-}" img tag
    # D-05: normalize docker.io/ prefix (docker inspect .Config.Image may include
    # it, while `docker images --format` never does) so keep-list comparison works.
    keep1="${keep1#docker.io/}"
    keep2="${keep2#docker.io/}"
    local -a all_images=()
    while IFS= read -r img; do
        [[ -n "$img" ]] || continue
        # Only manage bellamy/wallos images.
        [[ "$img" =~ ^bellamy/wallos:[A-Za-z0-9._-]+$ ]] || continue
        all_images+=("$img")
    done < <(docker images --format '{{.Repository}}:{{.Tag}}' 2>/dev/null | grep '^bellamy/wallos:' || true)
    local removed=0
    for img in "${all_images[@]}"; do
        if [[ "$img" != "$keep1" && "$img" != "$keep2" ]]; then
            # Keep at most 2: remove anything beyond keep1/keep2.
            # Count how many we would keep; if already 2 kept, remove the rest.
            if docker rmi "$img" >/dev/null 2>&1; then
                removed=$((removed + 1))
            else
                # D-09: was silently swallowed by `|| true`.
                msg "${YELLOW}$(tprintf wl_pr_rm_fail "$img")${NC}"
            fi
        fi
    done
    # D-08: removed dead 500MB-cap computation (total was calculated but never
    # used for enforcement or warning). Pruning is count-based (keep 2).
    if (( removed > 0 )); then
        msg "${CYAN}$(tprintf wl_pr_done "$removed" "${keep1:-none}" "${keep2:-}")${NC}"
    fi
    return 0
}

# N-11: Roll back Wallos to a specific version.
# Args: $1 = version tag (e.g. v2.5.1). Fetches the versioned image from the
# mirror if not present locally, restores the latest backup, recreates the container.
# D-02: best-effort recovery if rollback fails after the old container was removed.
# Tries to bring Wallos back up with the previous image so the service is not
# left completely down. Data on disk is already the restored backup.
_wallos_rollback_recover() {
    local prev_image="$1" port="$2" tz="$3" bind_address="$4"
    local -a _pub_args=()
    # X-03: use explicit bind:port form like the install path (L15630).
    # The old 0.0.0.0 -> "-p port:80" special case also published IPv6 [::]:port.
    [[ -n "$bind_address" ]] && _pub_args=(-p "${bind_address}:${port}:80/tcp")
    [[ -n "$prev_image" ]] || return 1
    # X-01: remove any existing 'wallos' container first. Callers may invoke
    # this after a failed docker run or unhealthy new container is still present;
    # without this, the second 'docker run --name wallos' always hits a name conflict.
    docker rm -f wallos >/dev/null 2>&1 || true
    docker run -d --name wallos --label com.alariclin.abox.managed=true \
        -v "$WALLOS_DIR/db:/var/www/html/db" \
        -v "$WALLOS_DIR/logos:/var/www/html/images/uploads/logos" \
        -e TZ="$tz" "${_pub_args[@]}" --restart unless-stopped "$prev_image" >/dev/null 2>&1
}

wallos_rollback_to_version() {
    local target_tag="$1" arch image_tag port tz bind_address backup
    [[ "$target_tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || { msg "${RED}$(tprintf wl_rb_invalid_ver "$target_tag")${NC}"; return 1; }
    # X-04: rollback's purpose IS downgrade; do not reuse the install-path
    # anti-downgrade gate (wallos_candidate_version_allowed) here. Instead
    # require the target to be strictly older than the installed version.
    local _installed_img _installed_ver
    _installed_img=$(docker inspect -f '{{.Config.Image}}' wallos 2>/dev/null || true)
    _installed_img="${_installed_img#docker.io/}"
    _installed_ver="${_installed_img##*:}"
    if [[ "$_installed_ver" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        wallos_version_is_older "${target_tag#v}" "$_installed_ver" || {
            msg "${RED}$(tprintf wl_rb_not_older "$target_tag" "$_installed_ver")${NC}"; return 1; }
    fi
    image_tag="${target_tag#v}"
    # Try local image first; else pull the versioned image from the mirror.
    if ! docker image inspect "bellamy/wallos:$image_tag" >/dev/null 2>&1; then
        msg "${YELLOW}$(tprintf wl_rb_fetching "$image_tag")${NC}"
        # Use the versioned mirror path: temporarily override tag selection.
        local _saved_result="${WALLOS_IMAGE_RESULT:-}"
        if ! _wallos_pull_versioned_image "$target_tag"; then
            WALLOS_IMAGE_RESULT="$_saved_result"
            msg "${RED}$(tprintf wl_rb_fetch_fail "$target_tag")${NC}"
            return 1
        fi
        WALLOS_IMAGE_RESULT="$_saved_result"
    fi
    # Stop and remove current container, restore latest backup, recreate.
    port=$(wallos_state_value PORT 2>/dev/null || true)
    tz=$(wallos_state_value TZ 2>/dev/null || printf 'UTC')
    bind_address=$(wallos_state_value BIND 2>/dev/null || printf '127.0.0.1')
    valid_canonical_port "$port" || { msg "${RED}$(tr_msg wl_rb_bad_port)${NC}"; return 1; }
    # Find the latest backup.
    backup=$(ls -t "$WALLOS_DIR"/backups/wallos-*.tar.gz 2>/dev/null | head -n 1 || true)
    [[ -n "$backup" && -f "$backup" && ! -L "$backup" ]] || { msg "${RED}$(tr_msg wl_rb_no_backup)${NC}"; return 1; }
    docker stop wallos >/dev/null 2>&1 || true
    # N-11: capture the pre-rollback image BEFORE removing the container,
    # so the prune step can retain 2 images (new current + previous). (NEW-1)
    local prev_image
    prev_image=$(docker inspect -f '{{.Config.Image}}' wallos 2>/dev/null || true)
    # Normalize docker.io/ prefix (matches _installed_img and old_image handling).
    prev_image="${prev_image#docker.io/}"
    docker rm -f wallos >/dev/null 2>&1 || {
        # A-04: rm failed after stop succeeded; try to restart the original
        # container instead of leaving it in Exited state.
        docker start wallos >/dev/null 2>&1 || true
        msg "${RED}$(tr_msg wl_rb_rm_fail)${NC}"
        return 1
    }
    wallos_restore_backup "$backup" || { msg "${RED}$(tr_msg wl_rb_restore_fail)${NC}"
        _wallos_rollback_recover "$prev_image" "$port" "$tz" "$bind_address" && \
            msg "${YELLOW}$(tr_msg wl_rb_recovered)${NC}"
        return 1; }
    local -a _pub_args=()
    # X-03: explicit bind:port form (matches install path); bare "-p port:80"
    # would also publish IPv6 [::]:port when bind is 0.0.0.0.
    [[ -n "$bind_address" ]] && _pub_args=(-p "${bind_address}:${port}:80/tcp")
    # Empty bind_address: omit -p entirely (no port publication, fail-closed).
    docker run -d --name wallos --label com.alariclin.abox.managed=true \
        -v "$WALLOS_DIR/db:/var/www/html/db" \
        -v "$WALLOS_DIR/logos:/var/www/html/images/uploads/logos" \
        -e TZ="$tz" "${_pub_args[@]}" --restart unless-stopped "bellamy/wallos:$image_tag" >/dev/null || {
        msg "${RED}$(tprintf wl_rb_start_fail "$target_tag")${NC}"
        _wallos_rollback_recover "$prev_image" "$port" "$tz" "$bind_address" && \
            msg "${YELLOW}$(tr_msg wl_rb_recovered)${NC}"
        return 1; }
    wallos_wait_healthy "$port" || { msg "${RED}$(tprintf wl_rb_unhealthy "$target_tag")${NC}"
        _wallos_rollback_recover "$prev_image" "$port" "$tz" "$bind_address" && \
            msg "${YELLOW}$(tr_msg wl_rb_recovered)${NC}"
        return 1; }
    wallos_write_state "bellamy/wallos:$image_tag" "$port" "$tz" "$bind_address" || {
        msg "${RED}$(tr_msg wl_rb_state_fail)${NC}"; return 1; }
    # N-11: prune to 2 images (new current + previous).
    wallos_prune_local_images "bellamy/wallos:$image_tag" "$prev_image"
    msg "${GREEN}$(tprintf wl_rb_done "$target_tag")${NC}"
    return 0
}

# N-11: Pull a specific versioned image from the A-Box mirror.
# Args: $1 = version tag. Sets WALLOS_IMAGE_RESULT on success.
_wallos_pull_versioned_image() {
    local tag="$1" arch asset expected actual work manifest_url sum_url
    [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    arch=$(wallos_detect_arch) || return 1
    work=$(umask 077; mktemp -d /tmp/A-Box-Wallos-ver.XXXXXX) || return 1
    local ver_manifest="wallos-manifest-${tag}.txt"
    manifest_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/$ver_manifest"
    sum_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/SHA256SUMS"
    if ! curl -fLsS --connect-timeout 8 --max-time 30 "$manifest_url" -o "$work/$ver_manifest" ||
       ! curl -fLsS --connect-timeout 8 --max-time 30 "$sum_url" -o "$work/SHA256SUMS"; then
        rm -rf -- "$work"; return 1
    fi
    # P1-2: verify SHA256SUMS signature before trusting it.
    curl -fLsS --connect-timeout 8 --max-time 30 "${sum_url}.sig" -o "$work/SHA256SUMS.sig" 2>/dev/null || true
    if ! abox_verify_sig_gate "$work/SHA256SUMS" "$work/SHA256SUMS.sig" "Wallos versioned SHA256SUMS"; then
        rm -rf -- "$work"; return 1
    fi
    # Verify manifest against SHA256SUMS (fail-closed).
    local manifest_expected manifest_actual
    manifest_expected=$(awk -v f="$ver_manifest" '$2==f || $2==("*" f) {print $1; exit}' "$work/SHA256SUMS" 2>/dev/null || true)
    manifest_actual=$(sha256sum "$work/$ver_manifest" 2>/dev/null | awk '{print $1}' || true)
    if [[ ! "$manifest_expected" =~ ^[A-Fa-f0-9]{64}$ || "${manifest_expected,,}" != "${manifest_actual,,}" ]]; then
        rm -rf -- "$work"
        msg "${RED}Wallos versioned manifest checksum mismatch; refusing.${NC}"
        return 1
    fi
    # Verify the manifest's tag matches the requested version.
    local mtag
    mtag=$(awk -F= '$1=="tag" {print $2; exit}' "$work/$ver_manifest" 2>/dev/null || true)
    [[ "$mtag" == "$tag" ]] || { rm -rf -- "$work"; return 1; }
    case "$arch" in amd64|arm64|armv7) asset="wallos-linux-$arch-${tag}.tar.gz" ;; *) rm -rf -- "$work"; return 1 ;; esac
    if ! curl -fLsS --connect-timeout 8 --max-time 600 \
        "https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/$asset" -o "$work/$asset"; then
        rm -rf -- "$work"; return 1
    fi
    expected=$(awk -v f="$asset" '$2==f || $2==("*" f) {print $1; exit}' "$work/SHA256SUMS" 2>/dev/null || true)
    actual=$(sha256sum "$work/$asset" 2>/dev/null | awk '{print $1}' || true)
    if [[ ! "$expected" =~ ^[A-Fa-f0-9]{64}$ || "${expected,,}" != "${actual,,}" ]]; then
        rm -rf -- "$work"
        msg "${RED}Wallos versioned archive checksum mismatch; refusing.${NC}"
        return 1
    fi
    local load_out image_tag="${tag#v}"
    load_out=$(gzip -dc "$work/$asset" | docker load 2>&1) || { rm -rf -- "$work"; return 1; }
    if [[ "$(grep -c '^Loaded image:' <<< "$load_out")" -ne 1 ]] ||
       ! grep -Fqx "Loaded image: bellamy/wallos:$image_tag" <<< "$load_out"; then
        rm -rf -- "$work"; return 1
    fi
    rm -rf -- "$work"
    docker image inspect "bellamy/wallos:$image_tag" >/dev/null 2>&1 || return 1
    WALLOS_IMAGE_RESULT="bellamy/wallos:$image_tag"
    return 0
}

wallos_latest_stable_tag() {
    local response tag
    response=$(curl -fLsS --retry 1 --connect-timeout 8 --max-time 20 https://api.github.com/repos/ellite/Wallos/releases/latest 2>/dev/null) || return 1
    tag=$(jq -er 'select(.draft == false and .prerelease == false) | .tag_name' <<< "$response" 2>/dev/null) || return 1
    [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    printf '%s\n' "$tag"
}

wallos_pull_or_restore_image() {
    local arch="$1" tag='' asset='' expected actual work manifest_url sum_url _w_ts=''
    WALLOS_IMAGE_RESULT=''
    tag=$(wallos_latest_stable_tag 2>/dev/null || true)
    if [[ -n "$tag" ]] && wallos_candidate_version_allowed "$tag"; then
        local image_tag="${tag#v}"
        # N-2: If the A-Box mirror manifest has the same tag, pull by immutable
        # digest (not mutable tag).
        # FINAL-AUDIT fix: download the manifest ONCE to a protected temp file,
        # verify it against SHA256SUMS (same check as the fallback path below),
        # then derive BOTH digest and tag from that single verified copy. The
        # old code used two separate curl fetches with no verification, so the
        # digest and tag could come from different manifest versions.
        # TRUST BOUNDARY NOTE: SHA256SUMS is fetched from the same mutable
        # Release as the manifest, so this check detects inconsistency and
        # corruption but is NOT an independent authenticity proof. A signature
        # trust root is still deferred (F-05).
        local _n2_work="" _mirror_digest="" _manifest_tag="" _n2_ts=""
        local _n2_manifest_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/wallos-manifest.txt"
        local _n2_sum_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/SHA256SUMS"
        _n2_work=$(umask 077; mktemp -d /tmp/A-Box-Wallos-n2.XXXXXX 2>/dev/null) || true
        if [[ -n "$_n2_work" && -d "$_n2_work" ]]; then
            # TRAP-3: EXIT trap ensures temp dir cleanup even on abnormal exit.
            # Expand $_n2_work now (double quotes); the local is gone when EXIT fires.
            # FIX: Save any pre-existing EXIT trap (e.g. runtime lock cleanup)
            # and restore it afterward, instead of discarding it with bare
            # "trap - EXIT" (follows the restore_saved_trap pattern).
            local _n2_prev_trap_exit
            _n2_prev_trap_exit=$(trap -p EXIT 2>/dev/null || true)
            trap "rm -rf -- '$_n2_work' 2>/dev/null" EXIT
            if curl -fLsS --connect-timeout 8 --max-time 30 "$_n2_manifest_url" -o "$_n2_work/wallos-manifest.txt" 2>/dev/null &&
               curl -fLsS --connect-timeout 8 --max-time 30 "$_n2_sum_url" -o "$_n2_work/SHA256SUMS" 2>/dev/null; then
                local _n2_expected _n2_actual
                # TRAP-3: filename anchored exactly via awk -v (not unanchored grep).
                _n2_expected=$(awk -v f="wallos-manifest.txt" '$2==f || $2==("*" f) {print $1; exit}' "$_n2_work/SHA256SUMS" 2>/dev/null || true)
                _n2_actual=$(sha256sum "$_n2_work/wallos-manifest.txt" 2>/dev/null | awk '{print $1}' || true)
                if [[ "$_n2_expected" =~ ^[A-Fa-f0-9]{64}$ && "${_n2_expected,,}" == "${_n2_actual,,}" ]]; then
                    # F-05: verify detached Ed25519 signature of the manifest.
                    curl -fLsS --connect-timeout 8 --max-time 30 "$_n2_sum_url.sig" -o "$_n2_work/SHA256SUMS.sig" 2>/dev/null || true
                    curl -fLsS --connect-timeout 8 --max-time 30 "${_n2_manifest_url}.sig" -o "$_n2_work/wallos-manifest.txt.sig" 2>/dev/null || true
                    # DS-Q4: SHA256SUMS 本身也要验签 (之前只下载不验证)
                    if ! abox_verify_sig_gate "$_n2_work/SHA256SUMS" "$_n2_work/SHA256SUMS.sig" "Wallos SHA256SUMS (N-2 fast path)"; then
                        msg "${RED}$(tr_msg wl_pi_sig_sums)${NC}"
                        trap - EXIT
                        restore_saved_trap EXIT "$_n2_prev_trap_exit"
                        rm -rf -- "$_n2_work"
                        return 1
                    fi
                    if ! abox_verify_sig_gate "$_n2_work/wallos-manifest.txt" "$_n2_work/wallos-manifest.txt.sig" "Wallos manifest (N-2 fast path)"; then
                        # D-10: abox_verify_sig_gate only returns 1 when ABOX_SIGNING_ENFORCE=1.
                        # In that mode, falling back to an unsigned tag pull would defeat
                        # enforcement, so fail hard instead of silently downgrading.
                        msg "${RED}$(tr_msg wl_pi_sig_manifest)${NC}"
                        trap - EXIT
                        restore_saved_trap EXIT "$_n2_prev_trap_exit"
                        rm -rf -- "$_n2_work"
                        return 1
                    else
                        # F-05 anti-replay on manifest timestamp.
                        _n2_ts=$(awk -F= '$1=="retrieved_at_utc" {print $2; exit}' "$_n2_work/wallos-manifest.txt" 2>/dev/null || true)
                        if [[ -n "$_n2_ts" ]] && ! abox_signing_timestamp_ok "$_n2_ts"; then
                            printf '[A-Box][F-05] FATAL: Wallos manifest timestamp %s predates trust floor\n' "$_n2_ts" >&2
                            # X-02: under ENFORCE=1, a stale timestamp must fail hard
                            # like a bad signature (D-10); falling back to an
                            # unsigned tag pull would defeat enforcement.
                            if [[ "${ABOX_SIGNING_ENFORCE:-1}" == '1' ]]; then
                                msg "${RED}$(tr_msg wl_pi_ts_reject_on)${NC}"
                                trap - EXIT
                                restore_saved_trap EXIT "$_n2_prev_trap_exit"
                                rm -rf -- "$_n2_work"
                                return 1
                            fi
                            msg "${YELLOW}$(tr_msg wl_pi_ts_reject_off)${NC}"
                        else
                            _mirror_digest=$(awk -F= -v a="$arch" '$1==("image_digest." a) {print $2; exit}' "$_n2_work/wallos-manifest.txt" 2>/dev/null || true)
                            _manifest_tag=$(awk -F= '$1=="tag" {print $2; exit}' "$_n2_work/wallos-manifest.txt" 2>/dev/null || true)
                        fi
                    fi
                else
                    msg "${YELLOW}$(tr_msg wl_pi_fp_mismatch)${NC}"
                fi
            fi
            trap - EXIT
            restore_saved_trap EXIT "$_n2_prev_trap_exit"
            rm -rf -- "$_n2_work"
        fi
        if [[ "$_mirror_digest" =~ ^(docker\.io/)?bellamy/wallos@sha256:[A-Fa-f0-9]{64}$ ]]; then
            if [[ "$_manifest_tag" == "$tag" ]]; then
                # N-2: docker pull by digest creates NO tag. Must docker tag
                # for downstream checks (require ^bellamy/wallos:[A-Za-z0-9._-]+$).
                if abox_run_wait '拉取 Wallos 镜像' docker pull "$_mirror_digest" && docker tag "$_mirror_digest" "bellamy/wallos:$image_tag"; then
                    WALLOS_IMAGE_RESULT="bellamy/wallos:$image_tag"
                    return 0
                fi
                msg "${YELLOW}$(tr_msg wl_pi_digest_fail)${NC}"
            fi
        fi
        if abox_run_wait '拉取 Wallos 镜像' docker pull "bellamy/wallos:$image_tag"; then
            # P2-1: record RepoDigest for auditability (mutable tag alone is not identity).
            # G11 FIX: Use digest reference instead of mutable tag to prevent TOCTOU.
            # After pull, immediately pin to digest so subsequent operations
            # cannot be affected by tag mutation.
            local _pulled_digest
            _pulled_digest=$(docker image inspect --format '{{index .RepoDigests 0}}' "bellamy/wallos:$image_tag" 2>/dev/null || true)
            if [[ "$_pulled_digest" =~ ^(docker\.io/)?bellamy/wallos@sha256:[A-Fa-f0-9]{64}$ ]]; then
                msg "${CYAN}$(tprintf wl_pi_digest "$_pulled_digest")${NC}"
                docker tag "$_pulled_digest" "bellamy/wallos:$image_tag" >/dev/null 2>&1 || true
            fi
            WALLOS_IMAGE_RESULT="bellamy/wallos:$image_tag"
            return 0
        fi
    fi
    msg "${YELLOW}$(tr_msg wl_pi_recovery)${NC}"
    work=$(umask 077; mktemp -d /tmp/A-Box-Wallos.XXXXXX) || return 1
    manifest_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/wallos-manifest.txt"
    sum_url="https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/SHA256SUMS"
    if ! curl -fLsS --connect-timeout 8 --max-time 30 "$manifest_url" -o "$work/wallos-manifest.txt" ||
       ! curl -fLsS --connect-timeout 8 --max-time 30 "$sum_url" -o "$work/SHA256SUMS"; then
        rm -rf -- "$work"
        return 1
    fi
    # D-2-FIX: Verify manifest itself against SHA256SUMS (manifest was unverified).
    manifest_expected=$(awk -v f="wallos-manifest.txt" '$2==f || $2==("*" f) {print $1; exit}' "$work/SHA256SUMS")
    manifest_actual=$(sha256sum "$work/wallos-manifest.txt" | awk '{print $1}')
    if [[ ! "$manifest_expected" =~ ^[A-Fa-f0-9]{64}$ || "${manifest_expected,,}" != "${manifest_actual,,}" ]]; then
        rm -rf -- "$work"
        msg "${RED}$(tr_msg wl_pi_manifest_sum)${NC}"
        return 1
    fi
    # P1-2: verify SHA256SUMS signature before trusting it.
    curl -fLsS --connect-timeout 8 --max-time 30 "${sum_url}.sig" -o "$work/SHA256SUMS.sig" 2>/dev/null || true
    if ! abox_verify_sig_gate "$work/SHA256SUMS" "$work/SHA256SUMS.sig" "Wallos SHA256SUMS (fallback path)"; then
        rm -rf -- "$work"
        return 1
    fi
    # F-05: verify detached Ed25519 signature of the manifest.
    curl -fLsS --connect-timeout 8 --max-time 30 "${manifest_url}.sig" -o "$work/wallos-manifest.txt.sig" 2>/dev/null || true
    if ! abox_verify_sig_gate "$work/wallos-manifest.txt" "$work/wallos-manifest.txt.sig" "Wallos manifest (fallback path)"; then
        rm -rf -- "$work"
        return 1
    fi
    # F-05 anti-replay on manifest timestamp.
    _w_ts=$(awk -F= '$1=="retrieved_at_utc" {print $2; exit}' "$work/wallos-manifest.txt" 2>/dev/null || true)
    if [[ -n "$_w_ts" ]] && ! abox_signing_timestamp_ok "$_w_ts"; then
        # X-10: gate on ENFORCE like the core path (L5297); unconditional
        # reject breaks the default ENFORCE=0 flow on a stale mirror.
        if [[ "${ABOX_SIGNING_ENFORCE:-1}" == '1' ]]; then
            printf '[A-Box][F-05] FATAL: Wallos manifest timestamp %s predates trust floor\n' "$_w_ts" >&2
            rm -rf -- "$work"
            return 1
        fi
        printf '[A-Box][F-05] WARNING: Wallos manifest timestamp %s predates trust floor (enforcement off)\n' "$_w_ts" >&2
    fi
    tag=$(awk -F= '$1=="tag" {print $2; exit}' "$work/wallos-manifest.txt")
    [[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || { rm -rf -- "$work"; return 1; }
    wallos_candidate_version_allowed "$tag" || { rm -rf -- "$work"; return 1; }
    case "$arch" in amd64|arm64|armv7) asset="wallos-linux-$arch.tar.gz" ;; *) rm -rf -- "$work"; return 1 ;; esac
    if ! curl -fLsS --connect-timeout 8 --max-time 600 \
        "https://github.com/alariclin/A-Box/releases/download/$WALLOS_MIRROR_RELEASE/$asset" -o "$work/$asset"; then
        rm -rf -- "$work"
        return 1
    fi
    expected=$(awk -v f="$asset" '$2==f || $2==("*" f) {print $1; exit}' "$work/SHA256SUMS")
    actual=$(sha256sum "$work/$asset" | awk '{print $1}')
    if [[ ! "$expected" =~ ^[A-Fa-f0-9]{64}$ || "${expected,,}" != "${actual,,}" ]]; then
        rm -rf -- "$work"
        msg "${RED}$(tr_msg wl_pi_mirror_sum)${NC}"
        return 1
    fi
    # N-3: Verify docker load loaded exactly the single expected image.
    # Do NOT docker rmi beforehand (would destroy rollback image on load failure).
    local load_out
    load_out=$(gzip -dc "$work/$asset" | docker load 2>&1) || { rm -rf -- "$work"; return 1; }
    if [[ "$(grep -c '^Loaded image:' <<< "$load_out")" -ne 1 ]] ||
       ! grep -Fqx "Loaded image: bellamy/wallos:${tag#v}" <<< "$load_out"; then
        rm -rf -- "$work"
        msg "${RED}$(tprintf wl_pi_archive "${tag#v}")${NC}"
        return 1
    fi
    # D-2-FIX: Fail-closed digest check. Manifest is now hash-verified above.
    # NOTE: docker load does NOT populate .RepoDigests (only docker pull does),
    # so RepoDigest comparison is skipped for loaded images. The tarball SHA
    # (verified above) + verified manifest together authenticate the image.
    local expected_digest
    expected_digest=$(awk -F= -v a="$arch" '$1==("image_digest." a) {print $2; exit}' "$work/wallos-manifest.txt")
    # Require digest present and format-valid (fail-closed if missing/malformed).
    # Allow optional docker.io/ prefix (containerd image store).
    if [[ ! "$expected_digest" =~ ^(docker\.io/)?bellamy/wallos@sha256:[A-Fa-f0-9]{64}$ ]]; then
        rm -rf -- "$work"
        msg "${RED}$(tprintf wl_pi_no_digest "$arch")${NC}"
        return 1
    fi
    # Defense-in-depth: If RepoDigests is populated (e.g. image was pulled), verify it matches.
    local loaded_digest
    loaded_digest=$(docker image inspect --format '{{index .RepoDigests 0}}' "bellamy/wallos:${tag#v}" 2>/dev/null || true)
    if [[ -n "$loaded_digest" && "$loaded_digest" != "$expected_digest" ]]; then
        rm -rf -- "$work"
        msg "${RED}$(tr_msg wl_pi_digest_mismatch)${NC}"
        return 1
    fi
    rm -rf -- "$work"
    local image_tag="${tag#v}"
    docker image inspect "bellamy/wallos:$image_tag" >/dev/null 2>&1 || return 1
    WALLOS_IMAGE_RESULT="bellamy/wallos:$image_tag"
    return 0
}
wallos_wait_healthy() {
    local port="$1" i code state
    for i in $(seq 1 60); do
        state=$(docker inspect -f '{{if .State.Health}}{{.State.Health.Status}}{{else}}no-healthcheck{{end}}' wallos 2>/dev/null || true)
        [[ "$state" == healthy ]] && return 0
        [[ "$state" == unhealthy ]] && return 1
        code=$(curl -sS -o /dev/null -w '%{http_code}' --connect-timeout 1 --max-time 2 "http://127.0.0.1:$port/" 2>/dev/null || true)
        case "$code" in 200|301|302|303|307|308) return 0 ;; esac
        sleep 1
    done
    return 1
}

wallos_create_backup() {
    local stamp="$1" backup="$WALLOS_DIR/backups/wallos-$1.tar.gz" temp list old
    mkdir -p "$WALLOS_DIR/backups" || return 1
    chmod 700 "$WALLOS_DIR/backups" || return 1
    [[ -d "$WALLOS_DIR/db" && ! -L "$WALLOS_DIR/db" &&
       -d "$WALLOS_DIR/logos" && ! -L "$WALLOS_DIR/logos" &&
       -f "$WALLOS_DIR/.abox-state" && ! -L "$WALLOS_DIR/.abox-state" ]] || return 1
    temp=$(umask 077; mktemp "$backup.tmp.XXXXXX") || return 1
    if ! tar -czf "$temp" -C "$WALLOS_DIR" db logos .abox-state ||
       ! gzip -t "$temp" ||
       ! tar -tzf "$temp" > "$temp.list"; then
        rm -f -- "$temp" "$temp.list"
        return 1
    fi
    list=$(cat "$temp.list") || { rm -f -- "$temp" "$temp.list"; return 1; }
    [[ "$list" == *"db/"* && "$list" == *"logos/"* && "$list" == *".abox-state"* ]] || {
        rm -f -- "$temp" "$temp.list"; return 1;
    }
    rm -f -- "$temp.list"
    chmod 600 "$temp" || { rm -f -- "$temp"; return 1; }
    sync -f "$temp" 2>/dev/null || true
    mv -f "$temp" "$backup" || { rm -f -- "$temp"; return 1; }
    sync -f "$WALLOS_DIR/backups" 2>/dev/null || true
    # D-07: BusyBox find (Alpine) lacks -printf; python3 is already a hard
    # dependency, so rotate by mtime in python. Keeps the newest 5 backups.
    # Rotation is best-effort: the backup itself already succeeded above.
    python3 - "$WALLOS_DIR/backups" "$backup" <<'PY_WALLOS_ROTATE' 2>/dev/null || true
import os, sys
_d, _keep = sys.argv[1], sys.argv[2]
_ents = []
try:
    _names = os.listdir(_d)
except OSError:
    _names = []
for _n in _names:
    _p = os.path.join(_d, _n)
    if _n.startswith('wallos-') and _n.endswith('.tar.gz') and os.path.isfile(_p) and not os.path.islink(_p):
        try:
            _ents.append((os.stat(_p).st_mtime, _p))
        except OSError:
            continue
_ents.sort(key=lambda e: e[0], reverse=True)
for _, _p in _ents[5:]:
    if _p != _keep:
        try:
            os.unlink(_p)
        except OSError:
            pass
PY_WALLOS_ROTATE
    printf '%s\n' "$backup"
}

wallos_restore_backup() {
    local backup="$1" stamp stage listing rescue name restore_name
    [[ -f "$backup" && ! -L "$backup" ]] || return 1
    gzip -t "$backup" || return 1
    listing=$(tar -tzf "$backup" 2>/dev/null) || return 1
    grep -Eq '^db/?$' <<< "$listing" && grep -Eq '^logos/?$' <<< "$listing" &&
        grep -Fxq '.abox-state' <<< "$listing" || return 1
    if grep -Eq '(^/|(^|/)\.\.(/|$))' <<< "$listing" ||
       grep -Ev '^(db(/.*)?|logos(/.*)?|\.abox-state)$' <<< "$listing" >/dev/null; then
        return 1
    fi
    # N-02 fix: reject symlinks, hardlinks, and special files inside the archive.
    # N-07 fix: enforce member count and size limits (zip-bomb protection).
    local vlisting member_count=0 total_usize=0
    vlisting=$(tar -tvzf "$backup" 2>/dev/null) || return 1
    while IFS= read -r line; do
        member_count=$((member_count + 1))
        # tar -tv output starts with file type char: - regular, d dir, l symlink, h hardlink, c/b/p/s/D special
        case "${line:0:1}" in
            -|d) ;;
            *) msg "${RED}$(tr_msg wl_rs_nonregular)${NC}" >&2; return 1 ;;
        esac
        # Size is the 3rd field in tar -tv output.
        local fsize
        fsize=$(awk '{print $3}' <<< "$line" 2>/dev/null || true)
        if [[ "$fsize" =~ ^[0-9]+$ ]] && (( 10#$fsize > 536870912 )); then
            msg "${RED}$(tr_msg wl_rs_oversized)${NC}" >&2
            return 1
        fi
        # Fix 2026-10-14: accumulate total decompressed size from tar listing.
        # gzip -l underreports multi-member gzip streams (only shows last member).
        if [[ "$fsize" =~ ^[0-9]+$ ]]; then
            total_usize=$((total_usize + 10#$fsize))
        fi
    done <<< "$vlisting"
    if (( member_count > 10000 )); then
        msg "${RED}$(tprintf wl_rs_toomany "$member_count")${NC}" >&2
        return 1
    fi
    # Fix 2026-10-14: total decompressed size guard uses summed tar member sizes.
    # (gzip -l is unreliable for multi-member streams; it reports only the last member.)
    if (( total_usize > 1073741824 )); then
        msg "${RED}$(tprintf wl_rs_toobig "$total_usize")${NC}" >&2
        return 1
    fi
    stage=$(umask 077; mktemp -d "$WALLOS_DIR/.restore-stage.XXXXXX") || return 1
    if ! tar -xzf "$backup" -C "$stage" ||
       [[ ! -d "$stage/db" || -L "$stage/db" ||
          ! -d "$stage/logos" || -L "$stage/logos" ||
          ! -f "$stage/.abox-state" || -L "$stage/.abox-state" ]]; then
        rm -rf -- "$stage"
        return 1
    fi
    stamp=$(date -u '+%Y%m%dT%H%M%SZ')
    rescue="$WALLOS_DIR/.restore-preserve-$stamp-$$"
    mkdir -m 700 "$rescue" || { rm -rf -- "$stage"; return 1; }
    for name in db logos .abox-state; do
        if [[ -e "$WALLOS_DIR/$name" || -L "$WALLOS_DIR/$name" ]]; then
            mv -- "$WALLOS_DIR/$name" "$rescue/$name" || {
                # B-07 fix: verify each rollback move; report incomplete state.
                local rb_failed=0
                for restore_name in db logos .abox-state; do
                    if [[ -e "$rescue/$restore_name" && ! -e "$WALLOS_DIR/$restore_name" ]]; then
                        mv -- "$rescue/$restore_name" "$WALLOS_DIR/$restore_name" 2>/dev/null || rb_failed=1
                    fi
                done
                rm -rf -- "$stage"
                (( rb_failed == 0 )) || msg "${RED}$(tprintf wl_rs_incomplete_check "$rescue")${NC}" >&2
                return 1
            }
        fi
    done
    for name in db logos .abox-state; do
        if ! mv -- "$stage/$name" "$WALLOS_DIR/$name"; then
            local rb_failed=0
            for restore_name in db logos .abox-state; do
                if [[ -e "$WALLOS_DIR/$restore_name" ]]; then
                    mv -- "$WALLOS_DIR/$restore_name" "$stage/$restore_name" 2>/dev/null || rb_failed=1
                fi
            done
            for restore_name in db logos .abox-state; do
                if [[ -e "$rescue/$restore_name" && ! -e "$WALLOS_DIR/$restore_name" ]]; then
                    mv -- "$rescue/$restore_name" "$WALLOS_DIR/$restore_name" 2>/dev/null || rb_failed=1
                fi
            done
            rm -rf -- "$stage"
            (( rb_failed == 0 )) || msg "${RED}$(tprintf wl_rs_incomplete_at "$rescue")${NC}" >&2
            return 1
        fi
    done
    rm -rf -- "$stage" "$rescue"
    return 0
}

wallos_upgrade_journal_write() {
    local phase="$1" old_image="$2" old_port="$3" old_tz="$4" old_bind="$5" backup="$6" was_running="$7"
    local journal="$WALLOS_DIR/.upgrade-transaction"
    [[ "$phase" == active || "$phase" == committed ]] || return 1
    [[ "$old_image" =~ ^bellamy/wallos:[A-Za-z0-9._-]+$ ]] || return 1
    valid_canonical_port "$old_port" || return 1
    valid_timezone_name "$old_tz" || return 1
    # F-08: accept any valid IP for rollback (was loopback/wildcard only, forcing coercion).
    { [[ -z "$old_bind" ]] || valid_ip_address "$old_bind"; } || return 1
    [[ "$was_running" == 0 || "$was_running" == 1 ]] || return 1
    [[ "$backup" == "$WALLOS_DIR/backups/wallos-"*.tar.gz && -f "$backup" && ! -L "$backup" ]] || return 1
    write_file_atomically_from_stdin "$journal" 600 <<EOF_WALLOS_TXN
phase=$phase
old_image=$old_image
old_port=$old_port
old_tz=$old_tz
old_bind=$old_bind
backup=$backup
was_running=$was_running
EOF_WALLOS_TXN
}

wallos_txn_value() {
    local file="$1" key="$2"
    awk -F= -v key="$key" '
        $1 == key {
            count++
            value = substr($0, index($0, "=") + 1)
        }
        END {
            if (count != 1) exit 1
            print value
        }
    ' "$file"
}

wallos_recover_interrupted_upgrade() {
    local journal="$WALLOS_DIR/.upgrade-transaction"
    local owner mode phase old_image old_port old_tz old_bind backup was_running
    [[ -e "$journal" || -L "$journal" ]] || return 0
    [[ -f "$journal" && ! -L "$journal" ]] || {
        msg "${RED}$(tr_msg wl_rc_journal_type)${NC}"
        return 1
    }
    owner=$(stat -c %u:%g "$journal" 2>/dev/null) || return 1
    mode=$(stat -c %a "$journal" 2>/dev/null) || return 1
    [[ "$owner" == 0:0 && "$mode" == 600 ]] || {
        msg "${RED}$(tr_msg wl_rc_journal_perm)${NC}"
        return 1
    }
    [[ "$(wc -l < "$journal" | tr -d '[:space:]')" == 7 ]] || {
        msg "${RED}$(tprintf wl_rc_journal_incomplete "$journal")${NC}"
        return 1
    }
    phase=$(wallos_txn_value "$journal" phase) || return 1
    [[ "$phase" == active || "$phase" == committed ]] || return 1
    old_image=$(wallos_txn_value "$journal" old_image) || return 1
    old_port=$(wallos_txn_value "$journal" old_port) || return 1
    old_tz=$(wallos_txn_value "$journal" old_tz) || return 1
    old_bind=$(wallos_txn_value "$journal" old_bind) || return 1
    backup=$(wallos_txn_value "$journal" backup) || return 1
    was_running=$(wallos_txn_value "$journal" was_running) || return 1
    if [[ "$phase" == committed ]]; then
        rm -f -- "$journal" || return 1
        msg "${YELLOW}$(tr_msg wl_rc_cleanup_done)${NC}"
        return 0
    fi
    [[ "$old_image" =~ ^bellamy/wallos:[A-Za-z0-9._-]+$ ]] || return 1
    valid_canonical_port "$old_port" || return 1
    valid_timezone_name "$old_tz" || return 1
    # F-08: accept any valid IP for rollback (was loopback/wildcard only).
    { [[ -z "$old_bind" ]] || valid_ip_address "$old_bind"; } || return 1
    [[ "$was_running" == 0 || "$was_running" == 1 ]] || return 1
    [[ "$backup" == "$WALLOS_DIR/backups/wallos-"*.tar.gz && -f "$backup" && ! -L "$backup" ]] || return 1
    if docker container inspect wallos >/dev/null 2>&1; then
        docker stop wallos >/dev/null 2>&1 || true
        docker rm -f wallos >/dev/null 2>&1 || {
            # A-04: rm failed after stop; restart original instead of leaving Exited.
            docker start wallos >/dev/null 2>&1 || true
            msg "${RED}$(tr_msg wl_rc_rm_fail)${NC}"
            return 1
        }
    fi
    if ! docker image inspect "$old_image" >/dev/null 2>&1; then
        # N-11: old image not present locally. Try fetching the exact previous
        # version from the versioned mirror instead of refusing.
        # N-03: look up the journal's old_image tag in the version list;
        # blind N-1 (2nd line) is wrong if the user had rolled back before.
        local _n1_tag _old_tag
        _old_tag="${old_image##*:}"
        _n1_tag=''
        if [[ "$_old_tag" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] && \
           wallos_mirror_version_list 2>/dev/null | grep -qx "v${_old_tag}"; then
            _n1_tag="v${_old_tag}"
        else
            _n1_tag=$(wallos_mirror_version_list 2>/dev/null | sed -n '2p' || true)
        fi
        if [[ "$_n1_tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] && _wallos_pull_versioned_image "$_n1_tag"; then
            # N-03: verify the fetched image matches the journal's old_image.
            if [[ "$WALLOS_IMAGE_RESULT" == "$old_image" || "$WALLOS_IMAGE_RESULT" == "bellamy/wallos:${_n1_tag#v}" ]]; then
                old_image="$WALLOS_IMAGE_RESULT"
                msg "${YELLOW}$(tprintf wl_rc_fetched "$_n1_tag")${NC}"
            else
                msg "${RED}$(tprintf wl_rc_mismatch "$WALLOS_IMAGE_RESULT" "$old_image")${NC}"
                return 1
            fi
        else
            msg "${RED}$(tprintf wl_rc_no_image "$old_image")${NC}"
            return 1
        fi
    fi
    wallos_restore_backup "$backup" || {
        msg "${RED}$(tprintf wl_rc_restore_fail "$journal" "$backup")${NC}"
        return 1
    }
    # FIX: When old_bind is empty (legacy containers had no IP binding),
    # "-p :<port>:80/tcp" makes Docker publish on 0.0.0.0 (fail-open,
    # exposing plaintext HTTP on all interfaces). Omit -p entirely instead.
    local -a wallos_pub_args=()
    if [[ -n "$old_bind" ]]; then
        wallos_pub_args=(-p "$old_bind:$old_port:80/tcp")
    fi
    if (( was_running == 1 )); then
        docker run -d --name wallos --label com.alariclin.abox.managed=true \
            -v "$WALLOS_DIR/db:/var/www/html/db" \
            -v "$WALLOS_DIR/logos:/var/www/html/images/uploads/logos" \
            -e TZ="$old_tz" "${wallos_pub_args[@]}" --restart unless-stopped "$old_image" >/dev/null || return 1
        wallos_wait_healthy "$old_port" || {
            msg "${RED}$(tr_msg wl_rc_unhealthy)${NC}"
            return 1
        }
    else
        docker create --name wallos --label com.alariclin.abox.managed=true \
            -v "$WALLOS_DIR/db:/var/www/html/db" \
            -v "$WALLOS_DIR/logos:/var/www/html/images/uploads/logos" \
            -e TZ="$old_tz" "${wallos_pub_args[@]}" --restart unless-stopped "$old_image" >/dev/null || return 1
    fi
    rm -f -- "$journal" || return 1
    msg "${YELLOW}$(tr_msg wl_rc_done)${NC}"
}

# ============ Wallos brute-force protection (fail2ban on nginx access log) ============
# Wallos keeps nginx access log inside the container's writable layer; fail2ban
# reads it from the host at <UpperDir>/var/log/nginx/access.log.
# Re-run after every (re)create of the container (install / upgrade / rollback).
wallos_bruteforce_protection() {
    local port="$1" bind_address="$2" wmode="${3:-}"
    local filter='/etc/fail2ban/filter.d/A-Box-wallos.conf'
    local jail='/etc/fail2ban/jail.d/A-Box-wallos.local'
    [[ -n "$wmode" ]] || wmode=$(wallos_state_value MODE 2>/dev/null || true)
    if [[ "$wmode" == https ]]; then
        # The jail watches Caddy's access log and bans on the public
        # port; the action port is the public (Caddy) port.
        local _pp=''; _pp=$(wallos_state_value PUBPORT 2>/dev/null || true)
        [[ "$_pp" =~ ^[0-9]+$ ]] && port="$_pp"
    fi
    # Localhost-only Wallos cannot be reached remotely; no jail needed.
    if [[ "$bind_address" == 127.0.0.1 && "$wmode" != https ]]; then
        rm -f -- "$jail" 2>/dev/null || true
        return 0
    fi
    command -v fail2ban-client >/dev/null 2>&1 || return 0
    command -v docker >/dev/null 2>&1 || return 0
    local upperdir logpath
    if [[ "$wmode" == https ]]; then
        logpath="$WALLOS_CADDY_LOG"
        # fail2ban needs the log file to exist; Caddy creates it on
        # start, but make sure an idle system still gets a jail.
        [[ -e "$logpath" ]] || : > "$logpath" 2>/dev/null || return 0
    else
        upperdir=$(docker inspect -f '{{.GraphDriver.Data.UpperDir}}' wallos 2>/dev/null || true)
        [[ -n "$upperdir" && -d "$upperdir" ]] || return 0
        logpath="$upperdir/var/log/nginx/access.log"
        # The log file appears on first HTTP request; create empty placeholder dir-wise only (file is created by nginx).
        [[ -e "$logpath" ]] || return 0
    fi
    local backend action
    backend=$(firewall_backend 2>/dev/null || true)
    case "$backend" in
        firewalld) action='firewallcmd-multiport' ;;
        ufw) action='ufw' ;;
        iptables) action='iptables-multiport' ;;
        *) return 0 ;;
    esac
    [[ -r "/etc/fail2ban/action.d/${action}.conf" ]] || return 0
    mkdir -p /etc/fail2ban/filter.d /etc/fail2ban/jail.d || return 0
    assert_abox_auxiliary_safe "$filter" 2>/dev/null || return 0
    assert_abox_auxiliary_safe "$jail" 2>/dev/null || return 0
    if [[ "$wmode" == https ]]; then
        # Caddy JSON access log: remote_ip comes first in the line.
        # Failed Wallos logins are POST /login.php answered 200; a
        # successful login redirects (302), so only 200s are counted
        # (verified against upstream login.php, 2026-10-20).
        write_file_atomically_from_stdin "$filter" 644 <<'EOF_WF2B_FILTER_HTTPS' || return 0
# Managed by A-Box
[Definition]
failregex = "remote_ip":\s*"<HOST>".*"method":\s*"POST".*"uri":\s*"/login\.php".*"status":\s*200
ignoreregex =
EOF_WF2B_FILTER_HTTPS
    else
        write_file_atomically_from_stdin "$filter" 644 <<'EOF_WF2B_FILTER' || return 0
# Managed by A-Box
[Definition]
failregex = ^<HOST> - \S+ \[[^\]]+\] "POST /login\.php HTTP/[0-9.]+" [0-9]{3} [0-9]+
ignoreregex =
EOF_WF2B_FILTER
    fi
    if [[ "$action" == 'ufw' ]]; then
        action="ufw[name=A-Box-wallos]"
    else
        action="${action}[name=A-Box-wallos, port=\"${port}\", protocol=tcp]"
    fi
    write_file_atomically_from_stdin "$jail" 644 <<EOF_WF2B_JAIL || return 0
# Managed by A-Box
[A-Box-wallos]
enabled = true
ignoreip = 127.0.0.1/8 ::1
port = ${port}
filter = A-Box-wallos
logpath = ${logpath}
maxretry = 10
findtime = 600
bantime = 86400
action = ${action}
EOF_WF2B_JAIL
    validate_fail2ban_config_or_die >/dev/null 2>&1 || { rm -f -- "$jail"; return 0; }
    if [[ "${INIT_SYS:-}" == systemd ]]; then
        systemctl restart fail2ban >/dev/null 2>&1 || true
    else
        rc-service fail2ban restart >/dev/null 2>&1 9>&- 10>&- || true
    fi
    return 0
}

wallos_public_urls() {
    local port="$1" ipv4 ipv6 host_ip
    local _cmode=''; _cmode=$(wallos_state_value MODE 2>/dev/null || true)
    if [[ "$_cmode" == cftunnel ]]; then
        local _ch=''; _ch=$(wallos_state_value CFHOST 2>/dev/null || true)
        if [[ -n "$_ch" ]]; then
            msg "${GREEN}$(tprintf wl_pu_url_cf "$_ch")${NC}"
            msg ''
            msg "${BOLD}$(tr_msg wl_pu_guide_cf_t)${NC}"
            msg "$(tr_msg wl_pu_guide_cf_1)"
            msg "$(tprintf wl_pu_guide_cf_2 "$port")"
            msg "$(tr_msg wl_pu_guide_cf_3)"
            return 0
        fi
    fi
    local _hmode=''; _hmode=$(wallos_state_value MODE 2>/dev/null || true)
    if [[ "$_hmode" == https ]] && is_service_running abox-wallos-caddy 2>/dev/null; then
        local _hp='' _hip=''
        _hp=$(wallos_state_value PUBPORT 2>/dev/null || true)
        _hip=$(get_public_ip 2>/dev/null || true); [[ -n "$_hip" ]] || _hip="${GLOBAL_PUBLIC_IP:-}"
        if [[ "$_hp" =~ ^[0-9]+$ && -n "$_hip" ]]; then
            msg "${GREEN}$(tprintf wl_pu_url_https "$_hip" "$_hp")${NC}"
            msg ''
            msg "${BOLD}$(tr_msg wl_pu_guide_https_t)${NC}"
            msg "$(tr_msg wl_pu_guide_https_1)"
            msg "$(tprintf wl_pu_guide_https_2 "$_hp")"
            msg "$(tr_msg wl_pu_guide_https_3)"
            return 0
        fi
    fi
    if [[ "$_hmode" == http ]]; then
        local _pip=''; _pip=$(get_public_ip 2>/dev/null || true); [[ -n "$_pip" ]] || _pip="${GLOBAL_PUBLIC_IP:-<VPS public IP>}"
        msg "${GREEN}$(tprintf wl_pu_url_http "$_pip" "$port")${NC}"
        msg ''
        msg "${BOLD}$(tr_msg wl_pu_guide_http_t)${NC}"
        msg "$(tr_msg wl_pu_guide_http_1)"
        msg "$(tprintf wl_pu_guide_http_2 "$port")"
        msg "$(tr_msg wl_pu_guide_http_3)"
        return 0
    fi
    host_ip=$(docker inspect -f '{{(index (index .HostConfig.PortBindings "80/tcp") 0).HostIp}}' wallos 2>/dev/null || true)
    # P3-8: handle empty binding and LAN-specific IPs explicitly (was: fell through to public-IP URL).
    if [[ -z "$host_ip" ]]; then
        msg "${YELLOW}$(tr_msg wl_pu_no_bind)${NC}"
        return 0
    fi
    if [[ "$host_ip" != 127.0.0.1 && "$host_ip" != 0.0.0.0 ]]; then
        msg "${GREEN}$(tprintf wl_pu_url_bound "$host_ip" "$port" "$host_ip")${NC}"
        return 0
    fi
    if [[ "$host_ip" == 127.0.0.1 ]]; then
        local _pub="${GLOBAL_PUBLIC_IP:-}"
        [[ -z "$_pub" ]] && _pub=$(curl -4fsS --connect-timeout 3 --max-time 5 https://api.ipify.org 2>/dev/null || true)
        [[ -z "$_pub" ]] && _pub='<VPS公网IP>'
        local _who="${SUDO_USER:-$(whoami)}"
        msg "${GREEN}$(tprintf wl_pu_local_url "$port")${NC}"; msg "${YELLOW}$(tr_msg wl_pu_local_warn)${NC}"
        msg "${CYAN}$(tr_msg wl_pu_ssh_t)${NC}"; msg "  ssh -L $port:127.0.0.1:$port $_who@$_pub"; msg "${CYAN}$(tprintf wl_pu_ssh_then "$port")${NC}"
        return 0
    fi
    ipv4=$(curl -4fsS --connect-timeout 3 --max-time 5 https://api.ipify.org 2>/dev/null || true)
    ipv6=$(curl -6fsS --connect-timeout 3 --max-time 5 https://api64.ipify.org 2>/dev/null || true)
    [[ -z "$ipv4" ]] || msg "${GREEN}$(tprintf wl_pu_url "$ipv4" "$port")${NC}"
    [[ -z "$ipv6" ]] || msg "${GREEN}$(tprintf wl_pu_url6 "$ipv6" "$port")${NC}"
    [[ -n "$ipv4" || -n "$ipv6" ]] || msg "${YELLOW}$(tprintf wl_pu_no_pub "$port")${NC}"
    if [[ "$host_ip" == 0.0.0.0 ]]; then
        msg ''
        msg "${BOLD}$(tr_msg wl_pu_guide_t)${NC}"
        msg "$(tr_msg wl_pu_guide_1)"
        msg "$(tprintf wl_pu_guide_2 "$port" "$port")"
        msg "$(tr_msg wl_pu_guide_3)"
    fi
}


install_wallos_caddy() {
    if [[ -x /usr/local/bin/caddy ]] && /usr/local/bin/caddy version 2>/dev/null | grep -q "v${WALLOS_CADDY_VERSION}"; then
        return 0
    fi
    get_architecture
    local want='' url='' tmp got
    case "$SB_ARCH" in
        amd64) want="$WALLOS_CADDY_SHA256_AMD64" ;;
        arm64) want="$WALLOS_CADDY_SHA256_ARM64" ;;
        *) msg "${RED}Caddy 不支持当前架构: $SB_ARCH${NC}"; return 1 ;;
    esac
    url="https://github.com/caddyserver/caddy/releases/download/v${WALLOS_CADDY_VERSION}/caddy_${WALLOS_CADDY_VERSION}_linux_${SB_ARCH}.tar.gz"
    tmp=$(mktemp -d /tmp/A-Box-caddy.XXXXXX) || return 1
    abox_run_wait 'Caddy download' curl -fL --retry 2 --connect-timeout 15 -o "$tmp/caddy.tgz" "$url" || { rm -rf "$tmp"; msg "${RED}Caddy 下载失败。${NC}"; return 1; }
    got=$(sha256sum "$tmp/caddy.tgz" 2>/dev/null | awk '{print $1}')
    if [[ "$got" != "$want" ]]; then
        rm -rf "$tmp"; msg "${RED}Caddy SHA256 校验失败 (供应链完整性保护)。${NC}"; return 1
    fi
    tar -xzf "$tmp/caddy.tgz" -C "$tmp" caddy 2>/dev/null || { rm -rf "$tmp"; msg "${RED}Caddy 解包失败。${NC}"; return 1; }
    chmod 755 "$tmp/caddy" || { rm -rf "$tmp"; return 1; }
    "$tmp/caddy" version >/dev/null 2>&1 || { rm -rf "$tmp"; msg "${RED}Caddy 执行校验失败。${NC}"; return 1; }
    install_binary_atomically "$tmp/caddy" /usr/local/bin/caddy || { rm -rf "$tmp"; msg "${RED}Caddy 原子安装失败。${NC}"; return 1; }
    rm -rf "$tmp"
}

wallos_https_write_unit() {
    if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
        write_file_atomically_from_stdin "/etc/systemd/system/abox-wallos-caddy.service" 600 <<'EOF_WCADDY' || return 1
