        chmod +x "/etc/init.d/abox-wallos-caddy" || return 1
        rc-update add abox-wallos-caddy default >/dev/null 2>&1 || true
        rc-service abox-wallos-caddy restart >/dev/null 2>&1 9>&- 10>&- || return 1
    fi
