}

xray_latest_remove() {
    local mode='' ver=''
    mode=$(_xl_state_get mode)
    ver=$(_xl_state_get version)
    if [[ -z "$mode" ]]; then
        msg "${YELLOW}$(tr_msg xl_not_installed)${NC}"
        return 0
    fi
    init_system_environment || return 1
    if [[ "$mode" == 'takeover' ]]; then
        msg "${RED}${BOLD}$(tr_msg xl_remove_warn_t)${NC}"
    else
        msg "${YELLOW}$(tr_msg xl_remove_warn_c)${NC}"
    fi
    confirm_soft "$(tr_msg xl_confirm)" || return 0
    if [[ "$mode" == 'coexist' ]]; then
        _xl_remove_coexist_files
    else
        if [[ "${INIT_SYS:-}" == 'systemd' ]]; then
            systemctl disable --now xray >/dev/null 2>&1 || true
            rm -f -- /etc/systemd/system/xray.service
            systemctl daemon-reload >/dev/null 2>&1 || true
        else
            rc-service xray stop >/dev/null 2>&1 || true
            rm -f -- /etc/init.d/xray /etc/conf.d/xray
        fi
        rm -f -- "$XRAY_SLOT_BIN"
        rm -rf -- "$XRAY_SLOT_DIR"
        rm -f -- "${ABOX_DIR:-/etc/ddr}/standalone-links.d/trojan-xray.link"
    fi
    rm -f -- "${ABOX_DIR:-/etc/ddr}/standalone-links.d"/latest-*.link
    rm -f -- "$XRAY_LATEST_STATE"
    msg "${GREEN}$(tr_msg xl_removed_note)${NC}"
    return 0
}

xray_latest_menu() {
    local latest_tag='' choice='' state_mode='' state_ver=''
    latest_tag=$(xl_upstream_latest_tag 2>/dev/null || echo '')
    while true; do
        clear
        msg "${CYAN}======================================================================${NC}"
        msg "${BOLD}${GREEN}$(tr_msg xl_title)${NC}"
        state_mode=$(_xl_state_get mode); state_ver=$(_xl_state_get version)
        msg "${CYAN}$(tr_msg xl_avail): ${latest_tag:-$(tr_msg xl_unknown)}${NC}"
        msg "${CYAN}$(tr_msg xl_slot): $(xl_binary_version "$XRAY_SLOT_BIN")${NC}"
        if [[ -n "$state_mode" ]]; then
            if [[ "$state_mode" == 'takeover' ]]; then
                msg "${CYAN}$(tr_msg xl_state_takeover): ${state_ver}${NC}"
            else
                msg "${CYAN}$(tr_msg xl_state_coexist): ${state_ver} ($(xl_binary_version "$XRAY_LATEST_BIN"))${NC}"
            fi
        else
            msg "${CYAN}$(tr_msg xl_latest_inst): $(tr_msg xl_not_installed)${NC}"
        fi
        if [[ -n "$latest_tag" ]] && ABOX_XRAY_VERSION="$latest_tag" xray_reality_requires_mlkem 2>/dev/null; then
            msg "${RED}${BOLD}$(tr_msg xl_mlkem_warn)${NC}"
        fi
        msg "${YELLOW} 1.  $(tr_msg xl_m_install)${NC}"
        msg "${YELLOW} 2.  VLESS + Vision + REALITY${NC}"
        msg "${YELLOW} 3.  VLESS + XHTTP + REALITY${NC}"
        msg "${YELLOW} 4.  Trojan-Reality${NC}"
        msg "${YELLOW} 5.  Shadowsocks 2022${NC}"
        msg "${YELLOW} 6.  SOCKS5${NC}"
        msg "${YELLOW} 7.  $(tr_msg xl_m_trio)${NC}"
        msg "${YELLOW} 8.  $(tr_msg xl_m_quad)${NC}"
        msg "${YELLOW} 9.  $(tr_msg xl_m_ports)${NC}"
        msg "${YELLOW}10.  $(tr_msg xl_m_remove)${NC}"
        msg "${CYAN} 0.  $(tr_msg xl_back_main)${NC}"
        read -r -p "$(tr_msg xl_select)" choice || return 0
        case "$choice" in
            1) xray_latest_install_core; pause_return ;;
            2) deploy_with_instance_choice xray-latest latest-vision xray_latest_deploy vision; pause_return ;;
            3) deploy_with_instance_choice xray-latest latest-xhttp xray_latest_deploy xhttp; pause_return ;;
            4) deploy_with_instance_choice xray-latest latest-trojan xray_latest_deploy trojan; pause_return ;;
            5) deploy_with_instance_choice xray-latest latest-ss xray_latest_deploy ss; pause_return ;;
            6) deploy_with_instance_choice xray-latest latest-socks xray_latest_deploy socks; pause_return ;;
            7) xray_latest_deploy_trio; pause_return ;;
            8) xray_latest_deploy_quad; pause_return ;;
            9) xl_show_ports; pause_return ;;
            10) xray_latest_remove; pause_return ;;
            0) return 0 ;;
            *) msg "${RED}$(tr_msg invalid_input): $choice${NC}"; sleep 1 ;;
        esac
    done
}

# A-Check (companion IP checker): the pinned release file is verified
# against its SHA-256 before it is cached under /etc/ddr/tools, and a
# cached copy is re-verified on every use. Mismatch = never executed.
ACHECK_VERSION='4.13.4'
ACHECK_SHA256='3d50a616e06fda8cd367622fa20ed4a2d5230e4d9dced3a657d4d3d57fdd1cea'
ACHECK_URL='https://raw.githubusercontent.com/alariclin/A-Check/v4.13.4/acheck.py'

run_acheck_tool() {
    command -v python3 >/dev/null 2>&1 || { msg "${RED}$(tr_msg acheck_no_python)${NC}"; return 1; }
    local _dir='/etc/ddr/tools' _f='/etc/ddr/tools/acheck.py' _tmp='' _sha=''
    if [[ -f "$_f" ]]; then
        _sha=$(sha256sum "$_f" 2>/dev/null | awk '{print $1}')
        [[ "${_sha,,}" == "$ACHECK_SHA256" ]] || rm -f -- "$_f"
    fi
    if [[ ! -f "$_f" ]]; then
        mkdir -p "$_dir" 2>/dev/null
        _tmp=$(mktemp /tmp/acheck.XXXXXX) || return 1
        if curl -fLsS --connect-timeout 10 --max-time 120 "$ACHECK_URL" -o "$_tmp"; then
            _sha=$(sha256sum "$_tmp" 2>/dev/null | awk '{print $1}')
            if [[ "${_sha,,}" == "$ACHECK_SHA256" ]]; then
                install -m 600 "$_tmp" "$_f" 2>/dev/null || cp "$_tmp" "$_f"
            fi
        fi
        rm -f -- "$_tmp"
    fi
    [[ -f "$_f" ]] || { msg "${RED}$(tr_msg acheck_failed)${NC}"; return 1; }
    python3 "$_f"
}


