uri_host() { if [[ "$1" == *:* ]]; then printf '[%s]' "$1"; else printf '%s' "$1"; fi; }

urlencode() {
    local raw="${1:-}"
    if command -v jq >/dev/null 2>&1; then
        jq -rn --arg v "$raw" '$v|@uri'
        return $?
    fi
    if command -v python3 >/dev/null 2>&1; then
        python3 -c 'import sys, urllib.parse; sys.stdout.write(urllib.parse.quote(sys.argv[1], safe=""))' "$raw"
        return $?
    fi
    # Last-resort RFC3986-ish encoder for environments missing jq/python3.
    local i c LC_ALL=C
    for ((i = 0; i < ${#raw}; i++)); do
        c=${raw:i:1}
        case "$c" in
            [a-zA-Z0-9.~_-]) printf '%s' "$c" ;;
            *) printf '%%%02X' "'$c" ;;
        esac
    done
}

build_ss2022_uri() {
    local host="$1" port="$2" pass="$3"
    # SIP002/SIP022: AEAD-2022 userinfo must not be Base64URL encoded;
    # method and password are percent-encoded as RFC3986 userinfo.
    printf 'ss://%s:%s@%s:%s#SS\n' \
        "$(urlencode '2022-blake3-aes-128-gcm')" \
        "$(urlencode "$pass")" \
        "$host" "$port"
}

singbox_hy2_tls_json() {
    if [[ -n "${HY2_DOMAIN:-}" && "${CORE:-}" != 'singbox' ]]; then
        cat <<EOF_TLS
      "tls": {
        "enabled": true,
        "server_name": "${HY2_DOMAIN}"
      }
EOF_TLS
    else
        # N-18 fix: validate the base64 SHA-256 fingerprint before embedding.
        # Must be 44-char base64 (32 bytes) to prevent JSON injection via .env.
        if [[ -z "${HY2_CERT_PUBKEY_SHA256_B64:-}" || ! "${HY2_CERT_PUBKEY_SHA256_B64}" =~ ^[A-Za-z0-9+/]{43}=$ ]]; then
            msg "${RED}[!] HY2_CERT_PUBKEY_SHA256_B64 格式无效，拒绝生成 sing-box TLS 配置。${NC}" >&2
            return 1
        fi
        cat <<EOF_TLS
      "tls": {
        "enabled": true,
        "insecure": true,
        "certificate_public_key_sha256": ["${HY2_CERT_PUBKEY_SHA256_B64:-}"]
      }
EOF_TLS
    fi
}

# Detect the VPS country (ISO-3166 alpha-2, uppercase) from the public egress IP.
# Used to pick bootstrap DNS for the Clash YAML: Chinese defaults must never be
# hard-coded for non-CN VPS. Returns empty on any failure; caller falls back to
# global defaults.
_detect_vps_country() {
    local trace loc
    trace=$(curl -sS --connect-timeout 2 -m 5 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null || true)
    loc=$(printf '%s\n' "$trace" | grep -m1 '^loc=' | cut -d= -f2 | tr -d '[:space:]')
    [[ "$loc" =~ ^[A-Za-z]{2}$ ]] || return 1
    printf '%s\n' "$loc" | tr 'a-z' 'A-Z'
}

# Bootstrap nameservers for the Clash YAML, chosen by VPS geolocation.
# Prints two plain IPv4 addresses, one per line.
_clash_default_nameservers() {
    local country="${1:-}"
    case "$country" in
        CN) printf '223.5.5.5\n119.29.29.29\n' ;;
        *)  printf '1.1.1.1\n8.8.8.8\n' ;;
    esac
}

write_clash_yaml() {
    local out="${CLASH_YAML_PATH:-$ABOX_DIR/A-Box-clash.yaml}" S_IP="${LINK_IP:-}" hy2_name="Hy2" tmp_out out_real base_real clash_hop_port client_uuid proxy_name
    local hy2_pass_yaml hy2_obfs_yaml ss_pass_yaml clash_mlkem=false clash_mlkem_rc
    local clash_ns1 clash_ns2 clash_country
    if clash_reality_mlkem_enabled; then
        clash_mlkem=true
    else
        clash_mlkem_rc=$?
        (( clash_mlkem_rc == 1 )) || return 1
    fi
    [[ -n "$out" && "$out" == /* ]] || return 1
    if [[ "${HY2_HOP:-}" == true && ( "${MODE:-}" == *'HY2'* || "${MODE:-}" == *'ALL'* ) ]]; then
        valid_hy2_clash_ports "${HY2_CLASH_PORTS:-}" || { msg "${YELLOW}[!] Hysteria 2 端口跳跃状态无效：HY2_CLASH_PORTS 缺失或非法，拒绝生成 Clash/Mihomo 配置。${NC}"; return 1; }
        valid_canonical_port "${HY2_BASE_PORT:-}" || { msg "${YELLOW}[!] Hysteria 2 基础端口无效，拒绝生成 Clash/Mihomo 配置。${NC}"; return 1; }
    fi
    [[ -n "${HY2_DOMAIN:-}" ]] && S_IP="$HY2_DOMAIN"
    clash_hop_port="${HY2_BASE_PORT:-443}"
    if [[ "${CORE:-}" != singbox && "${HY2_HOP:-}" == true ]]; then
        if [[ "${HY2_RANGE_START:-}" =~ ^[0-9]+$ ]]; then
            clash_hop_port="$HY2_RANGE_START"
        elif [[ "${HY2_CLASH_PORTS:-}" =~ ^([0-9]+)(-|$) ]]; then
            clash_hop_port="${BASH_REMATCH[1]}"
        fi
    fi
    [[ -n "${HY2_DOMAIN:-}" && "${CORE:-}" != 'singbox' ]] && hy2_name='Hy2'
    ensure_abox_dir_owned "$ABOX_DIR" || return 1
    command -v python3 >/dev/null 2>&1 || return 1
    base_real=$(python3 - "$ABOX_DIR" <<'PY_CLASH_REALPATH'
import os, sys
print(os.path.realpath(sys.argv[1]))
PY_CLASH_REALPATH
) || return 1
    out_real=$(python3 - "$out" <<'PY_CLASH_REALPATH'
import os, sys
print(os.path.realpath(sys.argv[1]))
PY_CLASH_REALPATH
) || return 1
    [[ "$out_real" == "$base_real"/* ]] || return 1
    [[ ! -L "$out" ]] || return 1
    tmp_out=$(mktemp "$base_real/.A-Box-clash-new.XXXXXX") || return 1
    # TRAP-7: UUID list temp file with explicit status check (no process substitution).
    local _clash_uuid_list_tmp
    _clash_uuid_list_tmp=$(umask 077; mktemp /tmp/A-Box-clash-uuid.XXXXXX) || { rm -f -- "$tmp_out"; return 1; }
    if ! write_full_uuid_list_to_file "$_clash_uuid_list_tmp"; then
        rm -f -- "$tmp_out" "$_clash_uuid_list_tmp"
        msg "${RED}UUID list unreadable or untrusted; refusing to generate incomplete Clash config.${NC}" >&2
        return 1
    fi
    # F-11 fix: clean up tmp_out and _clash_uuid_list_tmp on every early return below.
    hy2_pass_yaml=$(json_escape "${HY2_PASS:-}") || { rm -f -- "$tmp_out" "$_clash_uuid_list_tmp"; return 1; }
    hy2_obfs_yaml=$(json_escape "${HY2_OBFS:-}") || { rm -f -- "$tmp_out" "$_clash_uuid_list_tmp"; return 1; }
    ss_pass_yaml=$(json_escape "${SS_PASS:-}") || { rm -f -- "$tmp_out" "$_clash_uuid_list_tmp"; return 1; }
    # Bootstrap DNS by VPS geolocation; Chinese defaults only for CN VPS.
    clash_country=$(_detect_vps_country 2>/dev/null || true)
    clash_ns1=$(_clash_default_nameservers "$clash_country" 2>/dev/null | sed -n '1p')
    clash_ns2=$(_clash_default_nameservers "$clash_country" 2>/dev/null | sed -n '2p')
    [[ -n "$clash_ns1" && -n "$clash_ns2" ]] || { clash_ns1='1.1.1.1'; clash_ns2='8.8.8.8'; }
    {
        cat <<EOF_CLASH
mixed-port: 7890
allow-lan: false
mode: rule
log-level: info
ipv6: true

dns:
  enable: true
  listen: 127.0.0.1:1053
  enhanced-mode: fake-ip
  fake-ip-range: 198.18.0.1/16
  default-nameserver:
    - ${clash_ns1}
    - ${clash_ns2}
  fake-ip-filter:
    - "*.lan"
    - "*.local"
    - "*.internal"
    - "*.example"
    - "localhost"
    - "time.apple.com"
    - "captive.apple.com"
    - "detectportal.firefox.com"
    - "msftconnecttest.com"
    - "www.msftconnecttest.com"
    - "msftncsi.com"
    - "www.msftncsi.com"
    - "connectivitycheck.platform.hicloud.com"
    - "connectivitycheck.gstatic.com"
    - "ntp.tencent.com"
  nameserver:
    - https://dns.google/dns-query
    - https://cloudflare-dns.com/dns-query
  fallback:
    - tls://8.8.4.4
    - tls://1.1.1.1

proxies:
EOF_CLASH
        if [[ "$MODE" == *'VISION'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
            while IFS= read -r client_uuid; do
                [[ -n "$client_uuid" ]] || continue
                if [[ "$client_uuid" == "${UUID:-}" ]]; then proxy_name='Vision'; else proxy_name="Vision-${client_uuid:0:8}"; fi
                cat <<EOF_CLASH
  - name: "$proxy_name"
    type: vless
    server: "${LINK_IP:-}"
    port: ${VLESS_PORT:-443}
    uuid: "$client_uuid"
    udp: true
    tls: true
    servername: "${VISION_SNI:-}"
    client-fingerprint: chrome
    encryption: ""
    network: tcp
    flow: xtls-rprx-vision
    packet-encoding: xudp
    reality-opts:
      public-key: "${PUBLIC_KEY:-}"
      short-id: "${SHORT_ID:-}"
      support-x25519mlkem768: $clash_mlkem
    smux:
      enabled: false
EOF_CLASH
            done < "$_clash_uuid_list_tmp"
        fi
        if [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]]; then
            while IFS= read -r client_uuid; do
                [[ -n "$client_uuid" ]] || continue
                if [[ "$client_uuid" == "${UUID:-}" ]]; then proxy_name='XHTTP'; else proxy_name="XHTTP-${client_uuid:0:8}"; fi
                cat <<EOF_CLASH
  - name: "$proxy_name"
    type: vless
    server: "${LINK_IP:-}"
    port: ${XHTTP_PORT:-8443}
    uuid: "$client_uuid"
    udp: true
    tls: true
    servername: "${XHTTP_SNI:-}"
    client-fingerprint: chrome
    encryption: ""
    network: xhttp
    alpn:
      - h2
    reality-opts:
      public-key: "${PUBLIC_KEY:-}"
      short-id: "${SHORT_ID:-}"
      support-x25519mlkem768: $clash_mlkem
    xhttp-opts:
      path: /xhttp
      host: "${XHTTP_SNI:-}"
      mode: stream-one
    smux:
      enabled: false
EOF_CLASH
            done < "$_clash_uuid_list_tmp"
        fi
        if [[ "$MODE" == *'HY2'* || "$MODE" == *'ALL'* ]]; then
            if [[ -n "${HY2_DOMAIN:-}" && "$CORE" != 'singbox' ]]; then
                if [[ "${HY2_HOP:-}" == 'true' ]]; then
                    cat <<EOF_CLASH
  - name: "$hy2_name"
    type: hysteria2
    server: "$HY2_DOMAIN"
    port: $clash_hop_port
    ports: ${HY2_CLASH_PORTS}
    hop-interval: 30
    password: ${hy2_pass_yaml}
    alpn:
      - h3
    sni: "$HY2_DOMAIN"
    obfs: salamander
    obfs-password: ${hy2_obfs_yaml}
EOF_CLASH
                else
                    cat <<EOF_CLASH
  - name: "$hy2_name"
    type: hysteria2
    server: "$HY2_DOMAIN"
    port: ${HY2_BASE_PORT:-443}
    password: ${hy2_pass_yaml}
    alpn:
      - h3
    sni: "$HY2_DOMAIN"
    obfs: salamander
    obfs-password: ${hy2_obfs_yaml}
EOF_CLASH
                fi
            else
                if [[ "${HY2_HOP:-}" == 'true' ]]; then
                    cat <<EOF_CLASH
  - name: "$hy2_name"
    type: hysteria2
    server: "$S_IP"
    port: $clash_hop_port
    ports: ${HY2_CLASH_PORTS}
    hop-interval: 30
    password: ${hy2_pass_yaml}
    alpn:
      - h3
    skip-cert-verify: true
    fingerprint: "${HY2_CERT_SHA256_FP:-}"
    obfs: salamander
    obfs-password: ${hy2_obfs_yaml}
EOF_CLASH
                else
                    cat <<EOF_CLASH
  - name: "$hy2_name"
    type: hysteria2
    server: "$S_IP"
    port: ${HY2_BASE_PORT:-443}
    password: ${hy2_pass_yaml}
    alpn:
      - h3
    skip-cert-verify: true
    fingerprint: "${HY2_CERT_SHA256_FP:-}"
    obfs: salamander
    obfs-password: ${hy2_obfs_yaml}
EOF_CLASH
                fi
            fi
        fi
        if [[ "$MODE" == *'SS'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
            cat <<EOF_CLASH
  - name: "SS"
    type: ss
    server: "${LINK_IP:-}"
    port: ${SS_PORT:-2053}
    cipher: 2022-blake3-aes-128-gcm
    password: ${ss_pass_yaml}
    udp: true
    smux:
      enabled: false
EOF_CLASH
        fi
        cat <<EOF_CLASH

proxy-groups:
  - name: PROXY
    type: select
    proxies:
EOF_CLASH
        [[ "$MODE" == *'VISION'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]] && echo '      - Vision'
        [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]] && echo '      - XHTTP'
        while IFS= read -r client_uuid; do
            [[ -n "$client_uuid" && "$client_uuid" != "${UUID:-}" ]] || continue
            [[ "$MODE" == *'VISION'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]] && echo "      - Vision-${client_uuid:0:8}"
            [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]] && echo "      - XHTTP-${client_uuid:0:8}"
        done < "$_clash_uuid_list_tmp"
        [[ "$MODE" == *'HY2'* || "$MODE" == *'ALL'* ]] && echo "      - $hy2_name"
        [[ "$MODE" == *'SS'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]] && echo '      - SS'
        cat <<EOF_CLASH
      - DIRECT

rules:
  - MATCH,PROXY
EOF_CLASH
    } > "$tmp_out" || { rm -f -- "$tmp_out" "$_clash_uuid_list_tmp"; return 1; }
    rm -f -- "$_clash_uuid_list_tmp"
    chmod 600 "$tmp_out" || { rm -f -- "$tmp_out"; return 1; }
    [[ $EUID -eq 0 ]] && chown root:root "$tmp_out" || true
    mv -f -- "$tmp_out" "$out" || { rm -f -- "$tmp_out"; return 1; }
    chmod 600 "$out" || return 1
    printf '%s\n' "$out"
}

ensure_qrencode() {
    command -v qrencode >/dev/null 2>&1 && return 0
    [[ -n "${_QR_ENSURED:-}" ]] && return 1
    _QR_ENSURED=1
    if command -v apt-get >/dev/null 2>&1; then
        apt-get update -y -q >/dev/null 2>&1 || true
        apt-get -y install qrencode >/dev/null 2>&1 || true
    elif command -v dnf >/dev/null 2>&1; then
        dnf -y install qrencode >/dev/null 2>&1 || true
    elif command -v yum >/dev/null 2>&1; then
        yum -y install qrencode >/dev/null 2>&1 || true
    elif command -v apk >/dev/null 2>&1; then
        apk add --no-cache qrencode >/dev/null 2>&1 || true
    fi
    command -v qrencode >/dev/null 2>&1
}
generate_qr() {
    local url=$1
    ensure_qrencode || true
    if command -v qrencode >/dev/null 2>&1; then
        printf '\n%s\n' "${CYAN}================ 扫码导入 / Scan QR Code =================${NC}"
        printf '%s' "$url" | qrencode -s 1 -m 2 -t UTF8
        printf '%s\n\n' "${CYAN}==========================================================${NC}"
    elif [[ -z "${_QR_MISSING_WARNED:-}" ]]; then
        _QR_MISSING_WARNED=1
        msg "${YELLOW}[!] 未检测到 qrencode，跳过二维码显示。安装后进 12 号菜单重看即有：${NC}"
        msg "${YELLOW}    Debian/Ubuntu: sudo apt install -y qrencode${NC}"
        msg "${YELLOW}    Rocky/Alma/Fedora: sudo dnf install -y qrencode${NC}"
        msg "${YELLOW}    Alpine: sudo apk add qrencode${NC}"
    fi
}


build_hy2_uri_endpoint() {
    local raw="${HY2_URI_PORTS:-}" range
    if [[ -z "$raw" ]]; then
        if [[ "${HY2_HOP:-false}" == true && "${HY2_HOP_IMPL:-none}" == manual && "${HY2_BASE_PORT:-}" =~ ^[0-9]+$ && "${HY2_RANGE_START:-}" =~ ^[0-9]+$ && "${HY2_RANGE_END:-}" =~ ^[0-9]+$ ]]; then
            range="${HY2_RANGE_START}-${HY2_RANGE_END}"
            raw="${HY2_BASE_PORT},${range}"
        else
            raw="${HY2_BASE_PORT:-443}"
        fi
    fi
    valid_hy2_uri_ports "$raw" || return 1
    printf '%s\t%s\n' "$raw" ''
}


view_config() {
    local CALLER=${1:-manual}
    clear
    [[ ! -f "$ABOX_ENV" ]] && { msg "${RED}未检测到持久化配置变量。${NC}"; sleep 2; return 0; }
    load_abox_env "$ABOX_ENV" || die 'A-Box 状态文件无效或权限不安全。'
    local refreshed_ip
    refreshed_ip=$(refresh_public_ip || true)
    if [[ -n "$refreshed_ip" && "$refreshed_ip" != 'N/A' && "$refreshed_ip" != "${LINK_IP:-}" ]]; then
        LINK_IP="$refreshed_ip"
        write_env || die '公网 IP 已变化，但持久化更新失败。'
    fi
    VISION_SNI=${VISION_SNI:-${VLESS_SNI:-}}
    XHTTP_SNI=${XHTTP_SNI:-${VLESS_SNI:-}}
    local F_IP="${LINK_IP:-}" S_IP VLESS_URL XHTTP_URL HY2_URL SS_URL CLASH_FILE CLASH_SUB_URL CLASH_SCHEME
    local VISION_SNI_E XHTTP_SNI_E PUBLIC_KEY_E SHORT_ID_E HY2_PASS_E HY2_OBFS_E HY2_DOMAIN_E HY2_PIN_E HY2_URI_PORT HY2_QUERY_PREFIX
    IFS=$'\t' read -r HY2_URI_PORT HY2_QUERY_PREFIX < <(build_hy2_uri_endpoint) || die 'Hysteria2 分享链接端口参数无效。'
    [[ "$LINK_IP" =~ : ]] && F_IP="[$LINK_IP]"
    [[ -z "$LINK_IP" || "$LINK_IP" == 'N/A' ]] && msg "${YELLOW}[!] 未能自动获取公网 IP，分享链接可能不可用。${NC}"
    VISION_SNI_E=$(urlencode "${VISION_SNI:-}")
    XHTTP_SNI_E=$(urlencode "${XHTTP_SNI:-}")
    PUBLIC_KEY_E=$(urlencode "${PUBLIC_KEY:-}")
    SHORT_ID_E=$(urlencode "${SHORT_ID:-}")
    HY2_PASS_E=$(urlencode "${HY2_PASS:-}")
    HY2_OBFS_E=$(urlencode "${HY2_OBFS:-}")
    HY2_DOMAIN_E=$(urlencode "${HY2_DOMAIN:-}")
    HY2_PIN_E=$(urlencode "${HY2_CERT_SHA256_FP:-}")
    msg "${BLUE}======================================================================${NC}"
    msg "${BOLD}${CYAN}全局拓扑网络参数 (${MODE}) / Network Parameters${NC}"
    msg "${BLUE}======================================================================${NC}"
    msg "${BOLD}引擎栈:${NC} $CORE | ${BOLD}模式:${NC} $MODE"
    msg "${BLUE}--------------------------------------------------------------------------------${NC}"
    msg "${YELLOW}[ Shadowrocket / v2rayNG / NekoBox 单节点 URI ]${NC}"
    if [[ "$MODE" == *'VISION'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
        VLESS_URL="vless://$UUID@$F_IP:$VLESS_PORT?encryption=none&flow=xtls-rprx-vision&security=reality&sni=$VISION_SNI_E&fp=chrome&pbk=$PUBLIC_KEY_E&sid=$SHORT_ID_E&type=tcp#Vision"
        msg "${BOLD}${CYAN}── VLESS-Vision-Reality · 端口 ${VLESS_PORT}${NC}"
        msg "${GREEN}${VLESS_URL}${NC}"
        if [[ "$CORE" == 'xray' ]] && xray_reality_requires_mlkem; then
            msg "${YELLOW}当前 Xray $(effective_xray_version) 的 REALITY 服务端涉及较新的兼容门槛；Mihomo 请使用下方完整 YAML。部分 Shadowrocket / sing-box 版本可能无法建立连接。A-Box 默认使用经过当前 iOS + XHTTP/REALITY 兼容性权衡的版本 Xray ${ABOX_XRAY_DEFAULT_VERSION}（兼容性固定版，非 26.9.x ML-KEM prerelease）；更高 prerelease 版本请显式设置 ABOX_XRAY_VERSION。${NC}"
        fi
        generate_qr "$VLESS_URL"
    fi
    if [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]]; then
        XHTTP_URL="vless://$UUID@$F_IP:$XHTTP_PORT?encryption=none&security=reality&sni=$XHTTP_SNI_E&fp=chrome&pbk=$PUBLIC_KEY_E&sid=$SHORT_ID_E&type=xhttp&host=$XHTTP_SNI_E&path=%2Fxhttp&mode=stream-one#XHTTP"
        msg "${BOLD}${CYAN}── VLESS-XHTTP-Reality · 端口 ${XHTTP_PORT}${NC}"
        msg "${GREEN}${XHTTP_URL}${NC}"
        generate_qr "$XHTTP_URL"
    fi
    if [[ "$MODE" == *'HY2'* || "$MODE" == *'ALL'* ]]; then
        if [[ -n "${HY2_DOMAIN:-}" && "$CORE" != 'singbox' ]]; then
            HY2_URL="hysteria2://$HY2_PASS_E@$HY2_DOMAIN:$HY2_URI_PORT/?${HY2_QUERY_PREFIX}sni=$HY2_DOMAIN_E&obfs=salamander&obfs-password=$HY2_OBFS_E#Hy2"
        else
            S_IP="$F_IP"
            [[ -n "${HY2_DOMAIN:-}" ]] && S_IP="$HY2_DOMAIN"
            HY2_URL="hysteria2://$HY2_PASS_E@$S_IP:$HY2_URI_PORT/?${HY2_QUERY_PREFIX}insecure=1&pinSHA256=$HY2_PIN_E&obfs=salamander&obfs-password=$HY2_OBFS_E#Hy2"
        fi
        msg "${BOLD}${CYAN}── Hysteria 2 · 端口 ${HY2_URI_PORT}${NC}"
        msg "${GREEN}${HY2_URL}${NC}"
        [[ "${HY2_HOP:-}" == 'true' ]] && msg "${YELLOW}端口跳跃默认间隔 30s；不建议低于 5s。${NC}"
        generate_qr "$HY2_URL"
    fi
    if [[ "$MODE" == *'SS'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
        SS_URL=$(build_ss2022_uri "$F_IP" "$SS_PORT" "$SS_PASS")
        msg "${BOLD}${CYAN}── Shadowsocks-2022 · 端口 ${SS_PORT}${NC}"
        msg "${GREEN}${SS_URL}${NC}"
        generate_qr "$SS_URL"
    fi

    CLASH_FILE=$(write_clash_yaml) || die 'Clash/Mihomo YAML 配置生成失败。'
    CLASH_SUB_URL="${ABOX_CLASH_SUB_URL:-${CLASH_SUB_URL:-}}"
    msg "${BLUE}--------------------------------------------------------------------------------${NC}"
    msg "${YELLOW}[ Clash / Mihomo 完整配置 ]${NC}"
    msg "${GREEN}Local YAML: ${CLASH_FILE}${NC}"
    msg "${YELLOW}Clash/Mihomo 类客户端请导入完整 YAML 或远程订阅 URL；不要扫描上方单条 vless:// / hysteria2:// / ss://。${NC}"
    if [[ -n "$CLASH_SUB_URL" ]]; then
        CLASH_SCHEME="clash://install-config?url=$(urlencode "$CLASH_SUB_URL")"
        msg "${GREEN}Subscription URL: ${CLASH_SUB_URL}${NC}"
        generate_qr "$CLASH_SUB_URL"
        msg "${GREEN}Clash Verge Rev URL Scheme: ${CLASH_SCHEME}${NC}"
        generate_qr "$CLASH_SCHEME"
    else
        msg "${YELLOW}未设置 ABOX_CLASH_SUB_URL。若需要 Clash 扫码导入，请把 ${CLASH_FILE} 发布到 HTTPS 后执行：${NC}"
        msg "${CYAN}ABOX_CLASH_SUB_URL='https://example.com/A-Box-clash.yaml' sb${NC}"
    fi

    msg "${BLUE}--------------------------------------------------------------------------------${NC}"
    msg "${YELLOW}[ Clash / Mihomo YAML 预览 ]${NC}"
    sed -n '1,220p' "$CLASH_FILE" 2>/dev/null || true

    printf '\n%s\n' "${YELLOW}--- Sing-box 出站示例 ---${NC}"
    if [[ "$MODE" == *'HY2'* || "$MODE" == *'ALL'* ]]; then
        S_IP="$LINK_IP"
        [[ -n "${HY2_DOMAIN:-}" ]] && S_IP="$HY2_DOMAIN"
        if [[ "${HY2_HOP:-}" == 'true' ]]; then
            if valid_hy2_sb_ports "${HY2_SB_PORTS:-}"; then
                cat <<EOF_SB
    {
      "type": "hysteria2",
      "server": "$S_IP",
      "server_ports": ["$HY2_SB_PORTS"],
      "hop_interval": "30s",
      "password": $(json_escape "$HY2_PASS"),
$(singbox_hy2_tls_json),
      "obfs": {
        "type": "salamander",
        "password": $(json_escape "$HY2_OBFS")
      }
    }
EOF_SB
            else
                msg "${YELLOW}[!] Hysteria 2 端口跳跃状态缺失或非法；已省略无效的 Sing-box 出站示例。${NC}"
            fi
        else
            cat <<EOF_SB
    {
      "type": "hysteria2",
      "server": "$S_IP",
      "server_port": ${HY2_BASE_PORT:-443},
      "password": $(json_escape "$HY2_PASS"),
$(singbox_hy2_tls_json),
      "obfs": {
        "type": "salamander",
        "password": $(json_escape "$HY2_OBFS")
      }
    }
EOF_SB
        fi
    fi
    if [[ "$MODE" == *'SS'* || "$MODE" == *'ALL'* || "$MODE" == 'VLESS_SS' ]]; then
        cat <<EOF_SB
    {
      "type": "shadowsocks",
      "server": "$LINK_IP",
      "server_port": $SS_PORT,
      "method": "2022-blake3-aes-128-gcm",
      "password": $(json_escape "$SS_PASS")
    }
EOF_SB
    fi
    if [[ "$CORE" == 'xray' && ( "$MODE" == *'XHTTP'* || "$MODE" == *'ALL'* ) ]]; then
        printf '\n%s\n' "${YELLOW}--- v2rayN / v2rayNG XHTTP JSON ---${NC}"
        cat <<EOF_V2N
{
  "v": "2",
  "ps": "XHTTP",
  "add": "$LINK_IP",
  "port": "$XHTTP_PORT",
  "id": "$UUID",
  "net": "xhttp",
  "type": "none",
  "path": "/xhttp",
  "mode": "stream-one",
  "tls": "reality",
  "sni": "$XHTTP_SNI",
  "fp": "chrome",
  "pbk": "$PUBLIC_KEY",
  "sid": "$SHORT_ID"
}
EOF_V2N
    fi
    rebuild_standalone_links || true
    # --- standalone protocols (links registered at deploy time) ---
    if [[ -d "${ABOX_DIR:-/etc/ddr}/standalone-links.d" ]]; then
        local _lf _lt _lu _shown_sa=0
        for _lf in "${ABOX_DIR:-/etc/ddr}/standalone-links.d"/*.link; do
            [[ -f "$_lf" ]] || continue
            if (( ! _shown_sa )); then
                msg "${YELLOW}[ 独立协议节点 / Standalone Protocols ]${NC}"
                _shown_sa=1
            fi
            _lt=$(sed -n '1p' "$_lf")
            msg "${BOLD}${CYAN}── ${_lt}${NC}"
            while IFS= read -r _lu; do
                [[ -n "$_lu" ]] || continue
                msg "${GREEN}${_lu}${NC}"
                generate_qr "$_lu"
            done < <(sed -n '2,$p' "$_lf")
        done
    fi
    msg "${BLUE}--------------------------------------------------------------------------------${NC}"
    [[ "$CALLER" == 'deploy' ]] && msg "${GREEN}服务池部署完成。${NC}"
    pause_return
}

